// ============================================================================
// suPiposition — kernels/x86_64.s
//
// Instruction-set level:
//   x86-64-v4 (AVX512F, AVX512BW, AVX512CD, AVX512DQ, AVX512VL, AVX2, FMA,
//   BMI1, BMI2, F16C, LZCNT, MOVBE), plus ADX (ADCX, ADOX) for the six limb
//   kernels; mul_base and sqr_base also work in the 512-bit registers above
//   their calibrated scalar crossover. Assembled by the LLVM 23.1.5 integrated assembler in Intel syntax.
//   Contains zero instructions outside x86-64-v4 + ADX (no VBMI, no IFMA).
//
// Operating-system adaptation (SUPI_OS passed by kernels/build.rs):
//   SUPI_OS == 0 : Linux   (SysV AMD64 ABI, ELF)
//   SUPI_OS == 1 : Windows (Microsoft x64 ABI, COFF)
//   SUPI_OS == 2 : macOS   (SysV AMD64 ABI, Mach-O, leading underscore)
//
// Exported symbol:
//   supi_bind(table: *mut usize, abi: u64)
//   One body per kernel across all 24 entries of KernelTable (SUPI_ABI_VERSION = 6).
// ============================================================================

// ============================================================================
// 1. Cross-OS Assembler Macro Preamble
// ============================================================================

.macro TEXT_SECTION
    .text
.endm

.macro RODATA_SECTION
.if SUPI_OS == 0
    .section .rodata,"a",@progbits
.elseif SUPI_OS == 1
    .section .rdata,"dr"
.elseif SUPI_OS == 2
    .section __TEXT,__const
.else
    .text
.endif
.endm

.macro EXPORT_BIND
    .p2align 4
.if SUPI_OS == 2
    .globl _supi_bind
_supi_bind:
.else
    .globl supi_bind
supi_bind:
.endif
.endm

.macro LOCAL_FN name
    .p2align 4
\name:
.endm

// Unified GPR-only prologue:
// Normalizes arguments 1..4 into (rdi, rsi, rdx, rcx) on both SysV and Win64,
// saves all callee-saved GPRs, and allocates \scratch bytes aligned to 64 bytes
// at [rsp]. No limb kernel that enters through it touches XMM/YMM/ZMM.
.macro GPR_ENTER scratch=0
    push rbp
    mov  rbp, rsp
    push rbx
.if SUPI_OS == 1
    push rdi
    push rsi
.endif
    push r12
    push r13
    push r14
    push r15
.if SUPI_OS == 1
    mov  rdi, rcx
    mov  rsi, rdx
    mov  rdx, r8
    mov  rcx, r9
.endif
.if \scratch >= 4096
    // one store to every page on the way down (the saves above have written the first one)
    .rept (\scratch / 4096)
        sub  rsp, 4096
        mov  qword ptr [rsp], 0
    .endr
.endif
.if (\scratch % 4096) > 0
    sub  rsp, (\scratch % 4096)
.endif
.if \scratch > 0
    and  rsp, -64
    mov  qword ptr [rsp], 0
.endif
.endm

.macro GPR_LEAVE
.if SUPI_OS == 1
    lea  rsp, [rbp - 56]
.else
    lea  rsp, [rbp - 40]
.endif
    pop  r15
    pop  r14
    pop  r13
    pop  r12
.if SUPI_OS == 1
    pop  rsi
    pop  rdi
.endif
    pop  rbx
    pop  rbp
    ret
.endm

// Ultra-lightweight caller-saved prologue for leaf kernels using only volatile GPRs
// (rax, rcx, rdx, rsi, rdi, r8, r9, r10, r11; saves only rdi/rsi on Win64, zero pushes on SysV).
.macro LIMB_ENTER_FAST
.if SUPI_OS == 1
    push rdi
    push rsi
    mov  rdi, rcx
    mov  rsi, rdx
    mov  rdx, r8
    mov  rcx, r9
.endif
.endm

.macro LIMB_LEAVE_FAST
.if SUPI_OS == 1
    pop  rsi
    pop  rdi
.endif
    ret
.endm

// Unified AVX-512 vector prologue:
// Normalizes arguments 1..4 into (rdi, rsi, rdx, rcx), saves callee-saved GPRs
// and (on Windows) xmm6..xmm15, and allocates \scratch bytes aligned to 64 bytes
// at [rsp] (kept well within a single 4 KiB stack page).
.macro VEC_ENTER scratch=0
    push rbp
    mov  rbp, rsp
    push rbx
.if SUPI_OS == 1
    push rdi
    push rsi
.endif
    push r12
    push r13
    push r14
    push r15
.if SUPI_OS == 1
    sub  rsp, 168
    vmovups xmmword ptr [rbp - 72],  xmm6
    vmovups xmmword ptr [rbp - 88],  xmm7
    vmovups xmmword ptr [rbp - 104], xmm8
    vmovups xmmword ptr [rbp - 120], xmm9
    vmovups xmmword ptr [rbp - 136], xmm10
    vmovups xmmword ptr [rbp - 152], xmm11
    vmovups xmmword ptr [rbp - 168], xmm12
    vmovups xmmword ptr [rbp - 184], xmm13
    vmovups xmmword ptr [rbp - 200], xmm14
    vmovups xmmword ptr [rbp - 216], xmm15
    mov  rdi, rcx
    mov  rsi, rdx
    mov  rdx, r8
    mov  rcx, r9
.endif
.if \scratch >= 4096
    // one store to every page on the way down (the saves above have written the first one)
    .rept (\scratch / 4096)
        sub  rsp, 4096
        mov  qword ptr [rsp], 0
    .endr
.endif
.if (\scratch % 4096) > 0
    sub  rsp, (\scratch % 4096)
.endif
.if \scratch > 0
    and  rsp, -64
    mov  qword ptr [rsp], 0
.endif
.endm

.macro VEC_LEAVE
    vzeroupper
.if SUPI_OS == 1
    vmovups xmm6,  xmmword ptr [rbp - 72]
    vmovups xmm7,  xmmword ptr [rbp - 88]
    vmovups xmm8,  xmmword ptr [rbp - 104]
    vmovups xmm9,  xmmword ptr [rbp - 120]
    vmovups xmm10, xmmword ptr [rbp - 136]
    vmovups xmm11, xmmword ptr [rbp - 152]
    vmovups xmm12, xmmword ptr [rbp - 168]
    vmovups xmm13, xmmword ptr [rbp - 184]
    vmovups xmm14, xmmword ptr [rbp - 200]
    vmovups xmm15, xmmword ptr [rbp - 216]
    lea  rsp, [rbp - 56]
.else
    lea  rsp, [rbp - 40]
.endif
    pop  r15
    pop  r14
    pop  r13
    pop  r12
.if SUPI_OS == 1
    pop  rsi
    pop  rdi
.endif
    pop  rbx
    pop  rbp
    ret
.endm

// Lightweight AVX-512 prologue for kernels that only touch volatile zmm0..zmm5 and zmm16..zmm31
// (never xmm6..xmm15, avoiding 20 XMM save/restore instructions per call on Win64).
.macro VEC_ENTER_FAST
    push rbp
    mov  rbp, rsp
    push rbx
.if SUPI_OS == 1
    push rdi
    push rsi
.endif
    push r12
    push r13
    push r14
    push r15
.if SUPI_OS == 1
    mov  rdi, rcx
    mov  rsi, rdx
    mov  rdx, r8
    mov  rcx, r9
.endif
.endm

.macro VEC_LEAVE_FAST
    vzeroupper
.if SUPI_OS == 1
    lea  rsp, [rbp - 56]
.else
    lea  rsp, [rbp - 40]
.endif
    pop  r15
    pop  r14
    pop  r13
    pop  r12
.if SUPI_OS == 1
    pop  rsi
    pop  rdi
.endif
    pop  rbx
    pop  rbp
    ret
.endm

// Conditional Win64 XMM6..XMM15 save/restore for supi_k_fft_fwd and supi_k_fft_inv (scratch = 64):
// When n_complex <= 32 (3rd arg: rdx), both kernels touch only volatile zmm0..zmm5 and zmm16..zmm31,
// avoiding all 20 Win64 XMM stack memory operations across millions of small FFT calls.
.macro VEC_ENTER_FFT64
    push rbp
    mov  rbp, rsp
    push rbx
.if SUPI_OS == 1
    push rdi
    push rsi
.endif
    push r12
    push r13
    push r14
    push r15
.if SUPI_OS == 1
    mov  rdi, rcx
    mov  rsi, rdx
    mov  rdx, r8
    mov  rcx, r9
    cmp  rdx, 32
    jbe  1f
    sub  rsp, 232
    vmovups xmmword ptr [rbp - 72],  xmm6
    vmovups xmmword ptr [rbp - 88],  xmm7
    vmovups xmmword ptr [rbp - 104], xmm8
    vmovups xmmword ptr [rbp - 120], xmm9
    vmovups xmmword ptr [rbp - 136], xmm10
    vmovups xmmword ptr [rbp - 152], xmm11
    vmovups xmmword ptr [rbp - 168], xmm12
    vmovups xmmword ptr [rbp - 184], xmm13
    vmovups xmmword ptr [rbp - 200], xmm14
    vmovups xmmword ptr [rbp - 216], xmm15
    and  rsp, -64
    jmp  2f
1:
    sub  rsp, 64
    and  rsp, -64
2:
.else
    sub  rsp, 64
    and  rsp, -64
.endif
.endm

.macro VEC_LEAVE_FFT64
    vzeroupper
.if SUPI_OS == 1
    lea  rax, [rbp - 256]
    cmp  rsp, rax
    ja   1f
    vmovups xmm6,  xmmword ptr [rbp - 72]
    vmovups xmm7,  xmmword ptr [rbp - 88]
    vmovups xmm8,  xmmword ptr [rbp - 104]
    vmovups xmm9,  xmmword ptr [rbp - 120]
    vmovups xmm10, xmmword ptr [rbp - 136]
    vmovups xmm11, xmmword ptr [rbp - 152]
    vmovups xmm12, xmmword ptr [rbp - 168]
    vmovups xmm13, xmmword ptr [rbp - 184]
    vmovups xmm14, xmmword ptr [rbp - 200]
    vmovups xmm15, xmmword ptr [rbp - 216]
1:
    lea  rsp, [rbp - 56]
.else
    lea  rsp, [rbp - 40]
.endif
    pop  r15
    pop  r14
    pop  r13
    pop  r12
.if SUPI_OS == 1
    pop  rsi
    pop  rdi
.endif
    pop  rbx
    pop  rbp
    ret
.endm

// Zero-XMM-spill Win64 prologue/epilogue for supi_k_ntt_pmul:
// supi_k_ntt_pmul uses strictly volatile zmm0..zmm5 and zmm16..zmm31, touching only rdi/rsi on Win64.
.macro VEC_ENTER_PMUL
.if SUPI_OS == 1
    push rdi
    push rsi
    mov  rdi, rcx
    mov  rsi, rdx
    mov  rdx, r8
    mov  rcx, r9
.endif
.endm

.macro VEC_LEAVE_PMUL
    vzeroupper
.if SUPI_OS == 1
    pop  rsi
    pop  rdi
.endif
    ret
.endm

// Exact 8-lane f64 modular multiplication modulo P (zmm29 = p, zmm30 = inv_p, zmm31 = 0.0):
// Computes \A = (\A * \B) mod p in 7 vector operations matching refk::fma_mul_mod bit-for-bit.
.macro ZMM_MUL_MOD A, B, H, Q, MASK=k1
    vmulpd       \H, \A, \B
    vmulpd       \Q, \H, zmm30
    vfmsub213pd  \A, \B, \H
    vrndscalepd  \Q, \Q, 8
    vfnmadd231pd \H, \Q, zmm29
    vaddpd       \A, \H, \A
    vcmppd       \MASK, \A, zmm31, 1
    vaddpd       \A {\MASK}, \A, zmm29
.endm

// Four-vector scale multiply by zmm28 modulo P using ONLY zmm16..zmm23 and k1..k4
// (preserving zmm24..zmm27 twiddle registers across inner loops).
.macro ZMM_SCALE4 A0, A1, A2, A3
    vmulpd       zmm16, \A0, zmm28
    vmulpd       zmm17, \A1, zmm28
    vmulpd       zmm18, \A2, zmm28
    vmulpd       zmm19, \A3, zmm28
    vmulpd       zmm20, zmm16, zmm30
    vmulpd       zmm21, zmm17, zmm30
    vmulpd       zmm22, zmm18, zmm30
    vmulpd       zmm23, zmm19, zmm30
    vfmsub213pd  \A0, zmm28, zmm16
    vfmsub213pd  \A1, zmm28, zmm17
    vfmsub213pd  \A2, zmm28, zmm18
    vfmsub213pd  \A3, zmm28, zmm19
    vrndscalepd  zmm20, zmm20, 8
    vrndscalepd  zmm21, zmm21, 8
    vrndscalepd  zmm22, zmm22, 8
    vrndscalepd  zmm23, zmm23, 8
    vfnmadd231pd zmm16, zmm20, zmm29
    vfnmadd231pd zmm17, zmm21, zmm29
    vfnmadd231pd zmm18, zmm22, zmm29
    vfnmadd231pd zmm19, zmm23, zmm29
    vaddpd       \A0, zmm16, \A0
    vaddpd       \A1, zmm17, \A1
    vaddpd       \A2, zmm18, \A2
    vaddpd       \A3, zmm19, \A3
    vcmppd       k1, \A0, zmm31, 1
    vcmppd       k2, \A1, zmm31, 1
    vcmppd       k3, \A2, zmm31, 1
    vcmppd       k4, \A3, zmm31, 1
    vaddpd       \A0 {k1}, \A0, zmm29
    vaddpd       \A1 {k2}, \A1, zmm29
    vaddpd       \A2 {k3}, \A2, zmm29
    vaddpd       \A3 {k4}, \A3, zmm29
.endm


// Shoup four-vector scale multiply by zmm28 modulo P (with \SWP = fl(scale * inv_p) for |A| <= 1.3p).
.macro ZMM_SCALE4_SHOUP A0, A1, A2, A3, SWP:vararg
    vmulpd       zmm16, \A0, zmm28
    vmulpd       zmm17, \A1, zmm28
    vmulpd       zmm18, \A2, zmm28
    vmulpd       zmm19, \A3, zmm28
    vmulpd       zmm20, \A0, \SWP
    vmulpd       zmm21, \A1, \SWP
    vmulpd       zmm22, \A2, \SWP
    vmulpd       zmm23, \A3, \SWP
    vfmsub213pd  \A0, zmm28, zmm16
    vfmsub213pd  \A1, zmm28, zmm17
    vfmsub213pd  \A2, zmm28, zmm18
    vfmsub213pd  \A3, zmm28, zmm19
    vrndscalepd  zmm20, zmm20, 8
    vrndscalepd  zmm21, zmm21, 8
    vrndscalepd  zmm22, zmm22, 8
    vrndscalepd  zmm23, zmm23, 8
    vfnmadd231pd zmm16, zmm20, zmm29
    vfnmadd231pd zmm17, zmm21, zmm29
    vfnmadd231pd zmm18, zmm22, zmm29
    vfnmadd231pd zmm19, zmm23, zmm29
    vaddpd       \A0, zmm16, \A0
    vaddpd       \A1, zmm17, \A1
    vaddpd       \A2, zmm18, \A2
    vaddpd       \A3, zmm19, \A3
    vcmppd       k1, \A0, zmm31, 1
    vcmppd       k2, \A1, zmm31, 1
    vcmppd       k3, \A2, zmm31, 1
    vcmppd       k4, \A3, zmm31, 1
    vaddpd       \A0 {k1}, \A0, zmm29
    vaddpd       \A1 {k2}, \A1, zmm29
    vaddpd       \A2 {k3}, \A2, zmm29
    vaddpd       \A3 {k4}, \A3, zmm29
.endm

.macro ZMM_ADD_MOD DST, A, B, MASK=k1
    vaddpd \DST, \A, \B
    vcmppd \MASK, \DST, zmm29, 13
    vsubpd \DST {\MASK}, \DST, zmm29
.endm

.macro ZMM_SUB_MOD DST, A, B, MASK=k1
    vsubpd \DST, \A, \B
    vcmppd \MASK, \DST, zmm31, 1
    vaddpd \DST {\MASK}, \DST, zmm29
.endm

// Single DIF butterfly: V = (X * W) mod p; U' = (U + V) mod p; X' = (U - V) mod p.
.macro NTT_DIF1 U, X, W, H=zmm16, Q=zmm20
    vmulpd       \H, \X, \W
    vmulpd       \Q, \H, zmm30
    vfmsub213pd  \X, \W, \H
    vrndscalepd  \Q, \Q, 8
    vfnmadd231pd \H, \Q, zmm29
    vaddpd       \H, \H, \X
    vcmppd       k1, \H, zmm31, 1
    vaddpd       \H {k1}, \H, zmm29
    vsubpd       \X, \U, \H
    vaddpd       \U, \U, \H
    vcmppd       k1, \X, zmm31, 1
    vcmppd       k2, \U, zmm29, 13
    vaddpd       \X {k1}, \X, zmm29
    vsubpd       \U {k2}, \U, zmm29
.endm

// Four independent DIF butterflies interleaved across dual 512-bit FMA pipes.
// Scratch: zmm16..zmm23; constants: zmm29=p, zmm30=inv_p, zmm31=0.0; masks: k1..k4.
.macro NTT_DIF4 U0, X0, W0, U1, X1, W1, U2, X2, W2, U3, X3, W3
    vmulpd       zmm16, \X0, \W0
    vmulpd       zmm17, \X1, \W1
    vmulpd       zmm18, \X2, \W2
    vmulpd       zmm19, \X3, \W3

    vmulpd       zmm20, zmm16, zmm30
    vmulpd       zmm21, zmm17, zmm30
    vmulpd       zmm22, zmm18, zmm30
    vmulpd       zmm23, zmm19, zmm30

    vfmsub213pd  \X0, \W0, zmm16
    vfmsub213pd  \X1, \W1, zmm17
    vfmsub213pd  \X2, \W2, zmm18
    vfmsub213pd  \X3, \W3, zmm19

    vrndscalepd  zmm20, zmm20, 8
    vrndscalepd  zmm21, zmm21, 8
    vrndscalepd  zmm22, zmm22, 8
    vrndscalepd  zmm23, zmm23, 8

    vfnmadd231pd zmm16, zmm20, zmm29
    vfnmadd231pd zmm17, zmm21, zmm29
    vfnmadd231pd zmm18, zmm22, zmm29
    vfnmadd231pd zmm19, zmm23, zmm29

    vaddpd       zmm16, zmm16, \X0
    vaddpd       zmm17, zmm17, \X1
    vaddpd       zmm18, zmm18, \X2
    vaddpd       zmm19, zmm19, \X3

    vcmppd       k1, zmm16, zmm31, 1
    vcmppd       k2, zmm17, zmm31, 1
    vcmppd       k3, zmm18, zmm31, 1
    vcmppd       k4, zmm19, zmm31, 1
    vaddpd       zmm16 {k1}, zmm16, zmm29
    vaddpd       zmm17 {k2}, zmm17, zmm29
    vaddpd       zmm18 {k3}, zmm18, zmm29
    vaddpd       zmm19 {k4}, zmm19, zmm29

    vsubpd       \X0, \U0, zmm16
    vsubpd       \X1, \U1, zmm17
    vsubpd       \X2, \U2, zmm18
    vsubpd       \X3, \U3, zmm19

    vaddpd       \U0, \U0, zmm16
    vaddpd       \U1, \U1, zmm17
    vaddpd       \U2, \U2, zmm18
    vaddpd       \U3, \U3, zmm19

    vcmppd       k1, \X0, zmm31, 1
    vcmppd       k2, \X1, zmm31, 1
    vcmppd       k3, \X2, zmm31, 1
    vcmppd       k4, \X3, zmm31, 1
    vaddpd       \X0 {k1}, \X0, zmm29
    vaddpd       \X1 {k2}, \X1, zmm29
    vaddpd       \X2 {k3}, \X2, zmm29
    vaddpd       \X3 {k4}, \X3, zmm29

    vcmppd       k1, \U0, zmm29, 13
    vcmppd       k2, \U1, zmm29, 13
    vcmppd       k3, \U2, zmm29, 13
    vcmppd       k4, \U3, zmm29, 13
    vsubpd       \U0 {k1}, \U0, zmm29
    vsubpd       \U1 {k2}, \U1, zmm29
    vsubpd       \U2 {k3}, \U2, zmm29
    vsubpd       \U3 {k4}, \U3, zmm29
.endm

// Single DIT butterfly: sum = (U + V) mod p; diff = (U - V) mod p; U' = sum; V' = (diff * W) mod p.
.macro NTT_DIT1 U, V, W, H=zmm16, Q=zmm20
    vaddpd       \H, \U, \V
    vsubpd       \V, \U, \V
    vcmppd       k1, \H, zmm29, 13
    vcmppd       k2, \V, zmm31, 1
    vsubpd       \U, \H, zmm29
    vmovapd      \H {k1}, \U
    vmovapd      \U, \H
    vaddpd       \V {k2}, \V, zmm29
    ZMM_MUL_MOD  \V, \W, \H, \Q, k1
.endm

// Four independent DIT butterflies interleaved across dual 512-bit FMA pipes.
.macro NTT_DIT4 U0, V0, W0, U1, V1, W1, U2, V2, W2, U3, V3, W3
    vaddpd       zmm16, \U0, \V0
    vaddpd       zmm17, \U1, \V1
    vaddpd       zmm18, \U2, \V2
    vaddpd       zmm19, \U3, \V3

    vsubpd       \V0, \U0, \V0
    vsubpd       \V1, \U1, \V1
    vsubpd       \V2, \U2, \V2
    vsubpd       \V3, \U3, \V3

    vcmppd       k1, zmm16, zmm29, 13
    vcmppd       k2, zmm17, zmm29, 13
    vcmppd       k3, zmm18, zmm29, 13
    vcmppd       k4, zmm19, zmm29, 13
    vsubpd       zmm16 {k1}, zmm16, zmm29
    vsubpd       zmm17 {k2}, zmm17, zmm29
    vsubpd       zmm18 {k3}, zmm18, zmm29
    vsubpd       zmm19 {k4}, zmm19, zmm29

    vmovapd      \U0, zmm16
    vmovapd      \U1, zmm17
    vmovapd      \U2, zmm18
    vmovapd      \U3, zmm19

    vcmppd       k1, \V0, zmm31, 1
    vcmppd       k2, \V1, zmm31, 1
    vcmppd       k3, \V2, zmm31, 1
    vcmppd       k4, \V3, zmm31, 1
    vaddpd       \V0 {k1}, \V0, zmm29
    vaddpd       \V1 {k2}, \V1, zmm29
    vaddpd       \V2 {k3}, \V2, zmm29
    vaddpd       \V3 {k4}, \V3, zmm29

    vmulpd       zmm16, \V0, \W0
    vmulpd       zmm17, \V1, \W1
    vmulpd       zmm18, \V2, \W2
    vmulpd       zmm19, \V3, \W3

    vmulpd       zmm20, zmm16, zmm30
    vmulpd       zmm21, zmm17, zmm30
    vmulpd       zmm22, zmm18, zmm30
    vmulpd       zmm23, zmm19, zmm30

    vfmsub213pd  \V0, \W0, zmm16
    vfmsub213pd  \V1, \W1, zmm17
    vfmsub213pd  \V2, \W2, zmm18
    vfmsub213pd  \V3, \W3, zmm19

    vrndscalepd  zmm20, zmm20, 8
    vrndscalepd  zmm21, zmm21, 8
    vrndscalepd  zmm22, zmm22, 8
    vrndscalepd  zmm23, zmm23, 8

    vfnmadd231pd zmm16, zmm20, zmm29
    vfnmadd231pd zmm17, zmm21, zmm29
    vfnmadd231pd zmm18, zmm22, zmm29
    vfnmadd231pd zmm19, zmm23, zmm29

    vaddpd       \V0, zmm16, \V0
    vaddpd       \V1, zmm17, \V1
    vaddpd       \V2, zmm18, \V2
    vaddpd       \V3, zmm19, \V3

    vcmppd       k1, \V0, zmm31, 1
    vcmppd       k2, \V1, zmm31, 1
    vcmppd       k3, \V2, zmm31, 1
    vcmppd       k4, \V3, zmm31, 1
    vaddpd       \V0 {k1}, \V0, zmm29
    vaddpd       \V1 {k2}, \V1, zmm29
    vaddpd       \V2 {k3}, \V2, zmm29
    vaddpd       \V3 {k4}, \V3, zmm29
.endm

// Unmasked signed modular reduction: maps exact integers in (-7.5p, 7.5p) to [-0.501p, 0.501p].
.macro ZMM_RED4_SIGNED A0, A1, A2, A3
    vmulpd       zmm20, \A0, zmm30
    vmulpd       zmm21, \A1, zmm30
    vmulpd       zmm22, \A2, zmm30
    vmulpd       zmm23, \A3, zmm30
    vrndscalepd  zmm20, zmm20, 8
    vrndscalepd  zmm21, zmm21, 8
    vrndscalepd  zmm22, zmm22, 8
    vrndscalepd  zmm23, zmm23, 8
    vfnmadd231pd \A0, zmm20, zmm29
    vfnmadd231pd \A1, zmm21, zmm29
    vfnmadd231pd \A2, zmm22, zmm29
    vfnmadd231pd \A3, zmm23, zmm29
.endm

.macro ZMM_RED2_SIGNED A0, A1
    vmulpd       zmm20, \A0, zmm30
    vmulpd       zmm21, \A1, zmm30
    vrndscalepd  zmm20, zmm20, 8
    vrndscalepd  zmm21, zmm21, 8
    vfnmadd231pd \A0, zmm20, zmm29
    vfnmadd231pd \A1, zmm21, zmm29
.endm

.macro ZMM_RED1_SIGNED A0
    vmulpd       zmm20, \A0, zmm30
    vrndscalepd  zmm20, zmm20, 8
    vfnmadd231pd \A0, zmm20, zmm29
.endm

// Canonical reduction: maps exact integers in (-7.5p, 7.5p) to [0, p) bit-for-bit.
.macro ZMM_CANON4 A0, A1, A2, A3
    ZMM_RED4_SIGNED \A0, \A1, \A2, \A3
    vcmppd       k1, \A0, zmm31, 1
    vcmppd       k2, \A1, zmm31, 1
    vcmppd       k3, \A2, zmm31, 1
    vcmppd       k4, \A3, zmm31, 1
    vaddpd       \A0 {k1}, \A0, zmm29
    vaddpd       \A1 {k2}, \A1, zmm29
    vaddpd       \A2 {k3}, \A2, zmm29
    vaddpd       \A3 {k4}, \A3, zmm29
.endm


.macro ZMM_CANON2 A0, A1
    ZMM_RED2_SIGNED \A0, \A1
    vcmppd       k1, \A0, zmm31, 1
    vcmppd       k2, \A1, zmm31, 1
    vaddpd       \A0 {k1}, \A0, zmm29
    vaddpd       \A1 {k2}, \A1, zmm29
.endm

// Lazy signed FMA DIF butterflies (zero masks; exact integers in (-7.4p, 7.4p) over 4 stages).
.macro NTT_DIF1_LAZY U, X, W, H=zmm16, Q=zmm20
    vmulpd       \H, \X, \W
    vmulpd       \Q, \H, zmm30
    vfmsub213pd  \X, \W, \H
    vrndscalepd  \Q, \Q, 8
    vfnmadd231pd \H, \Q, zmm29
    vaddpd       \H, \H, \X
    vsubpd       \X, \U, \H
    vaddpd       \U, \U, \H
.endm

.macro NTT_DIF2_LAZY U0, X0, W0, U1, X1, W1
    vmulpd       zmm16, \X0, \W0
    vmulpd       zmm17, \X1, \W1
    vmulpd       zmm20, zmm16, zmm30
    vmulpd       zmm21, zmm17, zmm30
    vfmsub213pd  \X0, \W0, zmm16
    vfmsub213pd  \X1, \W1, zmm17
    vrndscalepd  zmm20, zmm20, 8
    vrndscalepd  zmm21, zmm21, 8
    vfnmadd231pd zmm16, zmm20, zmm29
    vfnmadd231pd zmm17, zmm21, zmm29
    vaddpd       zmm16, zmm16, \X0
    vaddpd       zmm17, zmm17, \X1
    vsubpd       \X0, \U0, zmm16
    vsubpd       \X1, \U1, zmm17
    vaddpd       \U0, \U0, zmm16
    vaddpd       \U1, \U1, zmm17
.endm

.macro NTT_DIF4_LAZY U0, X0, W0, U1, X1, W1, U2, X2, W2, U3, X3, W3
    vmulpd       zmm16, \X0, \W0
    vmulpd       zmm17, \X1, \W1
    vmulpd       zmm18, \X2, \W2
    vmulpd       zmm19, \X3, \W3

    vmulpd       zmm20, zmm16, zmm30
    vmulpd       zmm21, zmm17, zmm30
    vmulpd       zmm22, zmm18, zmm30
    vmulpd       zmm23, zmm19, zmm30

    vfmsub213pd  \X0, \W0, zmm16
    vfmsub213pd  \X1, \W1, zmm17
    vfmsub213pd  \X2, \W2, zmm18
    vfmsub213pd  \X3, \W3, zmm19

    vrndscalepd  zmm20, zmm20, 8
    vrndscalepd  zmm21, zmm21, 8
    vrndscalepd  zmm22, zmm22, 8
    vrndscalepd  zmm23, zmm23, 8

    vfnmadd231pd zmm16, zmm20, zmm29
    vfnmadd231pd zmm17, zmm21, zmm29
    vfnmadd231pd zmm18, zmm22, zmm29
    vfnmadd231pd zmm19, zmm23, zmm29

    vaddpd       zmm16, zmm16, \X0
    vaddpd       zmm17, zmm17, \X1
    vaddpd       zmm18, zmm18, \X2
    vaddpd       zmm19, zmm19, \X3

    vsubpd       \X0, \U0, zmm16
    vsubpd       \X1, \U1, zmm17
    vsubpd       \X2, \U2, zmm18
    vsubpd       \X3, \U3, zmm19

    vaddpd       \U0, \U0, zmm16
    vaddpd       \U1, \U1, zmm17
    vaddpd       \U2, \U2, zmm18
    vaddpd       \U3, \U3, zmm19
.endm

// Lazy signed FMA DIT butterflies (zero masks; exact integers in (-7.4p, 7.4p) over 4 stages).
.macro NTT_DIT1_LAZY U, V, W, H=zmm16, Q=zmm20
    vsubpd       \H, \U, \V
    vaddpd       \U, \U, \V
    vmulpd       \V, \H, \W
    vmulpd       \Q, \V, zmm30
    vfmsub213pd  \H, \W, \V
    vrndscalepd  \Q, \Q, 8
    vfnmadd231pd \V, \Q, zmm29
    vaddpd       \V, \V, \H
.endm

.macro NTT_DIT2_LAZY U0, V0, W0, U1, V1, W1
    vsubpd       zmm16, \U0, \V0
    vsubpd       zmm17, \U1, \V1
    vaddpd       \U0, \U0, \V0
    vaddpd       \U1, \U1, \V1
    vmulpd       \V0, zmm16, \W0
    vmulpd       \V1, zmm17, \W1
    vmulpd       zmm20, \V0, zmm30
    vmulpd       zmm21, \V1, zmm30
    vfmsub213pd  zmm16, \W0, \V0
    vfmsub213pd  zmm17, \W1, \V1
    vrndscalepd  zmm20, zmm20, 8
    vrndscalepd  zmm21, zmm21, 8
    vfnmadd231pd \V0, zmm20, zmm29
    vfnmadd231pd \V1, zmm21, zmm29
    vaddpd       \V0, \V0, zmm16
    vaddpd       \V1, \V1, zmm17
.endm

.macro NTT_DIT4_LAZY U0, V0, W0, U1, V1, W1, U2, V2, W2, U3, V3, W3
