    vsubpd       zmm17, \U1, \V1
    vsubpd       zmm18, \U2, \V2
    vsubpd       zmm19, \U3, \V3

    vaddpd       \U0, \U0, \V0
    vaddpd       \U1, \U1, \V1
    vaddpd       \U2, \U2, \V2
    vaddpd       \U3, \U3, \V3

    vmulpd       \V0, zmm16, \W0
    vmulpd       \V1, zmm17, \W1
    vmulpd       \V2, zmm18, \W2
    vmulpd       \V3, zmm19, \W3

    vmulpd       zmm20, \V0, zmm30
    vmulpd       zmm21, \V1, zmm30
    vmulpd       zmm22, \V2, zmm30
    vmulpd       zmm23, \V3, zmm30

    vfmsub213pd  zmm16, \W0, \V0
    vfmsub213pd  zmm17, \W1, \V1
    vfmsub213pd  zmm18, \W2, \V2
    vfmsub213pd  zmm19, \W3, \V3

    vrndscalepd  zmm20, zmm20, 8
    vrndscalepd  zmm21, zmm21, 8
