    vmulpd       zmm20, \X0, \WP0
    vmulpd       zmm21, \X1, \WP1
    vmulpd       zmm22, \X2, \WP2
    vmulpd       zmm23, \X3, \WP3

    vfmsub132pd  \X0, zmm16, \W0
    vfmsub132pd  \X1, zmm17, \W1
    vfmsub132pd  \X2, zmm18, \W2
    vfmsub132pd  \X3, zmm19, \W3

    vrndscalepd  zmm20, zmm20, 8
    vrndscalepd  zmm21, zmm21, 8
    vrndscalepd  zmm22, zmm22, 8
    vrndscalepd  zmm23, zmm23, 8

    vfnmadd231pd zmm16, zmm20, zmm29
    vfnmadd231pd zmm17, zmm21, zmm29
    vfnmadd231pd zmm18, zmm22, zmm29
    vfnmadd231pd zmm19, zmm23, zmm29

    vaddpd       zmm16, zmm16, \X0
    vaddpd       zmm17, zmm17, \X1
    vaddpd       zmm18, zmm18, \X2
    vaddpd       zmm19, zmm19, \X3

    vsubpd       \X0, \U0, zmm16
    vsubpd       \X1, \U1, zmm17
    vsubpd       \X2, \U2, zmm18
    vsubpd       \X3, \U3, zmm19

    vaddpd       \U0, \U0, zmm16
    vaddpd       \U1, \U1, zmm17
    vaddpd       \U2, \U2, zmm18
    vaddpd       \U3, \U3, zmm19
.endm

.macro NTT_DIF4_SHOUP_MEM U0, X0, W0, WP0, U1, X1, W1, WP1, U2, X2, W2, WP2, U3, X3, W3, WP3
    vmulpd       zmm16, \X0, qword ptr [\W0]{1to8}
    vmulpd       zmm17, \X1, qword ptr [\W1]{1to8}
    vmulpd       zmm18, \X2, qword ptr [\W2]{1to8}
    vmulpd       zmm19, \X3, qword ptr [\W3]{1to8}

    vmulpd       zmm20, \X0, qword ptr [\WP0]{1to8}
