    vmulpd       zmm22, \X2, qword ptr [\WP2]{1to8}
    vmulpd       zmm23, \X3, qword ptr [\WP3]{1to8}

    vfmsub132pd  \X0, zmm16, qword ptr [\W0]{1to8}
    vfmsub132pd  \X1, zmm17, qword ptr [\W1]{1to8}
    vfmsub132pd  \X2, zmm18, qword ptr [\W2]{1to8}
    vfmsub132pd  \X3, zmm19, qword ptr [\W3]{1to8}

    vrndscalepd  zmm20, zmm20, 8
    vrndscalepd  zmm21, zmm21, 8
    vrndscalepd  zmm22, zmm22, 8
    vrndscalepd  zmm23, zmm23, 8

    vfnmadd231pd zmm16, zmm20, zmm29
    vfnmadd231pd zmm17, zmm21, zmm29
