    vsubpd       \X1, \U1, zmm17
    vsubpd       \X2, \U2, zmm18
    vsubpd       \X3, \U3, zmm19

    vaddpd       \U0, \U0, zmm16
    vaddpd       \U1, \U1, zmm17
    vaddpd       \U2, \U2, zmm18
    vaddpd       \U3, \U3, zmm19
