    vmulpd       \V3, zmm19, \W3

    vmulpd       zmm20, zmm16, \WP0
    vmulpd       zmm21, zmm17, \WP1
    vmulpd       zmm22, zmm18, \WP2
    vmulpd       zmm23, zmm19, \WP3

    vfmsub132pd  zmm16, \V0, \W0
    vfmsub132pd  zmm17, \V1, \W1
