    vaddpd       \V0, \V0, zmm16
    vaddpd       \V1, \V1, zmm17
    vaddpd       \V2, \V2, zmm18
    vaddpd       \V3, \V3, zmm19
.endm

.macro NTT_DIT4_SHOUP_MEM U0, V0, W0, WP0, U1, V1, W1, WP1, U2, V2, W2, WP2, U3, V3, W3, WP3
    vsubpd       zmm16, \U0, \V0
