// Twiddle-free w == 1.0 DIF/DIT butterflies (pure add/sub, 0 multiplies).
.macro NTT_BFY4_W1 U0, V0, U1, V1, U2, V2, U3, V3
    vsubpd       zmm16, \U0, \V0
