.macro NTT_DIT2_SHOUP U0, V0, W0, WP0, U1, V1, W1, WP1
    vsubpd       zmm16, \U0, \V0
    vsubpd       zmm17, \U1, \V1
    vaddpd       \U0, \U0, \V0
    vaddpd       \U1, \U1, \V1
    vmulpd       \V0, zmm16, \W0
    vmulpd       \V1, zmm17, \W1
    vmulpd       zmm20, zmm16, \WP0
