    vmulpd       \V1, zmm17, qword ptr [\W1]{1to8}
    vmulpd       zmm20, zmm16, qword ptr [\WP0]{1to8}
    vmulpd       zmm21, zmm17, qword ptr [\WP1]{1to8}
    vfmsub132pd  zmm16, \V0, qword ptr [\W0]{1to8}
    vfmsub132pd  zmm17, \V1, qword ptr [\W1]{1to8}
    vrndscalepd  zmm20, zmm20, 8
    vrndscalepd  zmm21, zmm21, 8
    vfnmadd231pd \V0, zmm20, zmm29
    vfnmadd231pd \V1, zmm21, zmm29
    vaddpd       \V0, \V0, zmm16
    vaddpd       \V1, \V1, zmm17
.endm

// Two complex DIF butterflies interleaved across dual 512-bit FMA pipes (bit-exact with ref_fft_fwd).
// Scratch: zmm28..zmm29; preserves zmm0..zmm27 and zmm30..zmm31.
.macro FFT_DIF2 U0, X0, WR0, WI0, U1, X1, WR1, WI1
    vshufpd        zmm28, \X0, \X0, 0x55
    vshufpd        zmm29, \X1, \X1, 0x55
    vmulpd         zmm28, zmm28, \WI0
    vmulpd         zmm29, zmm29, \WI1
    vfmaddsub231pd zmm28, \X0, \WR0
    vfmaddsub231pd zmm29, \X1, \WR1
    vsubpd         \X0, \U0, zmm28
    vsubpd         \X1, \U1, zmm29
    vaddpd         \U0, \U0, zmm28
    vaddpd         \U1, \U1, zmm29
.endm

.macro FFT_DIF2_MEM U0, X0, WR0, WI0, U1, X1, WR1, WI1
    vshufpd        zmm28, \X0, \X0, 0x55
    vshufpd        zmm29, \X1, \X1, 0x55
    vmulpd         zmm28, zmm28, qword ptr [\WI0]{1to8}
    vmulpd         zmm29, zmm29, qword ptr [\WI1]{1to8}
    vfmaddsub231pd zmm28, \X0, qword ptr [\WR0]{1to8}
    vfmaddsub231pd zmm29, \X1, qword ptr [\WR1]{1to8}
    vsubpd         \X0, \U0, zmm28
    vsubpd         \X1, \U1, zmm29
    vaddpd         \U0, \U0, zmm28
    vaddpd         \U1, \U1, zmm29
.endm

// Two complex DIT butterflies interleaved across dual 512-bit FMA pipes (bit-exact with ref_fft_inv).
// Scratch: zmm28, zmm29; preserves zmm0..zmm27 (including zmm22 = 1.0 / orig_n).
.macro FFT_DIT2 U0, V0, WR0, WI0, U1, V1, WR1, WI1
    vsubpd         zmm28, \U0, \V0
    vsubpd         zmm29, \U1, \V1
    vaddpd         \U0,   \U0, \V0
    vaddpd         \U1,   \U1, \V1
    vshufpd        \V0,   zmm28, zmm28, 0x55
    vshufpd        \V1,   zmm29, zmm29, 0x55
    vmulpd         \V0,   \V0, \WI0
    vmulpd         \V1,   \V1, \WI1
    vfmaddsub231pd \V0,   zmm28, \WR0
    vfmaddsub231pd \V1,   zmm29, \WR1
.endm

.macro FFT_DIT2_MEM U0, V0, WR0, WI0, U1, V1, WR1, WI1
    vsubpd         zmm28, \U0, \V0
    vsubpd         zmm29, \U1, \V1
    vaddpd         \U0,   \U0, \V0
    vaddpd         \U1,   \U1, \V1
    vshufpd        \V0,   zmm28, zmm28, 0x55
    vshufpd        \V1,   zmm29, zmm29, 0x55
    vmulpd         \V0,   \V0, qword ptr [\WI0]{1to8}
    vmulpd         \V1,   \V1, qword ptr [\WI1]{1to8}
    vfmaddsub231pd \V0,   zmm28, qword ptr [\WR0]{1to8}
    vfmaddsub231pd \V1,   zmm29, qword ptr [\WR1]{1to8}
.endm

// Four complex DIF butterflies interleaved across dual 512-bit FMA pipes.
// Scratch: zmm28..zmm31; preserves zmm0..zmm27.
.macro FFT_DIF4 U0, X0, WR0, WI0, U1, X1, WR1, WI1, U2, X2, WR2, WI2, U3, X3, WR3, WI3
    vshufpd        zmm28, \X0, \X0, 0x55
    vshufpd        zmm29, \X1, \X1, 0x55
    vshufpd        zmm30, \X2, \X2, 0x55
    vshufpd        zmm31, \X3, \X3, 0x55
    vmulpd         zmm28, zmm28, \WI0
    vmulpd         zmm29, zmm29, \WI1
    vmulpd         zmm30, zmm30, \WI2
    vmulpd         zmm31, zmm31, \WI3
    vfmaddsub231pd zmm28, \X0, \WR0
    vfmaddsub231pd zmm29, \X1, \WR1
    vfmaddsub231pd zmm30, \X2, \WR2
    vfmaddsub231pd zmm31, \X3, \WR3
    vsubpd         \X0, \U0, zmm28
    vsubpd         \X1, \U1, zmm29
    vsubpd         \X2, \U2, zmm30
    vsubpd         \X3, \U3, zmm31
    vaddpd         \U0, \U0, zmm28
    vaddpd         \U1, \U1, zmm29
    vaddpd         \U2, \U2, zmm30
    vaddpd         \U3, \U3, zmm31
.endm

// Four complex DIT butterflies interleaved across dual 512-bit FMA pipes.
// Scratch: zmm28..zmm31; preserves zmm0..zmm27 (including zmm22 = 1.0 / orig_n).
.macro FFT_DIT4 U0, V0, WR0, WI0, U1, V1, WR1, WI1, U2, V2, WR2, WI2, U3, V3, WR3, WI3
    vsubpd         zmm28, \U0, \V0
    vsubpd         zmm29, \U1, \V1
    vsubpd         zmm30, \U2, \V2
    vsubpd         zmm31, \U3, \V3
    vaddpd         \U0,   \U0, \V0
    vaddpd         \U1,   \U1, \V1
    vaddpd         \U2,   \U2, \V2
    vaddpd         \U3,   \U3, \V3
    vshufpd        \V0,   zmm28, zmm28, 0x55
    vshufpd        \V1,   zmm29, zmm29, 0x55
    vshufpd        \V2,   zmm30, zmm30, 0x55
    vshufpd        \V3,   zmm31, zmm31, 0x55
    vmulpd         \V0,   \V0, \WI0
    vmulpd         \V1,   \V1, \WI1
    vmulpd         \V2,   \V2, \WI2
    vmulpd         \V3,   \V3, \WI3
    vfmaddsub231pd \V0,   zmm28, \WR0
    vfmaddsub231pd \V1,   zmm29, \WR1
    vfmaddsub231pd \V2,   zmm30, \WR2
    vfmaddsub231pd \V3,   zmm31, \WR3
.endm

TEXT_SECTION

// ============================================================================
// 2. CPU Probe and supi_bind(table, abi)
// ============================================================================

EXPORT_BIND
    GPR_ENTER 0
.if SUPI_OS > 2
    jmp  .Lbind_exit
.endif
    test rdi, rdi
    jz   .Lbind_exit
    cmp  rsi, 6
    jne  .Lbind_exit

    mov  r12, rdi                       // r12 = KernelTable *

    // Check max basic CPUID leaf >= 7
    xor  eax, eax
    cpuid
    cmp  eax, 7
    jb   .Lbind_exit

    // Check extended CPUID leaf >= 0x80000001 and LZCNT (ECX bit 5)
    mov  eax, 0x80000000
    cpuid
    cmp  eax, 0x80000001
    jb   .Lbind_exit
    mov  eax, 0x80000001
    cpuid
    bt   ecx, 5                         // LZCNT
    jnc  .Lbind_exit

    // Leaf 1: SSE3(0), SSSE3(9), FMA(12), CMPXCHG16B(13), SSE4.1(19),
    //         SSE4.2(20), MOVBE(22), POPCNT(23), AVX(28), F16C(29) = 0x30D83201
    mov  eax, 1
    cpuid
    mov  r13d, ecx                      // save leaf1 ECX (incl. OSXSAVE bit 27)
    mov  eax, ecx
    and  eax, 0x30D83201
    cmp  eax, 0x30D83201
    jne  .Lbind_exit

    // Leaf 7 subleaf 0: BMI1(3), AVX2(5), BMI2(8), AVX512F(16), AVX512DQ(17),
    //                   AVX512CD(28), AVX512BW(30), AVX512VL(31) = 0xD0030128
    mov  eax, 7
    xor  ecx, ecx
    cpuid
    mov  r14d, ebx                      // save leaf7 EBX (incl. ADX bit 19)
    mov  eax, ebx
    mov  edx, 0xD0030128
    and  eax, edx
    cmp  eax, edx
    jne  .Lbind_exit

    // Chip is x86-64-v4. Bind four GPR-only limb kernels where ADX (bit 19) is present;
    // mul_base and sqr_base also use 512-bit registers and are bound after OS ZMM state check.
    bt   r14d, 19
    jnc  .Lbind_check_zmm_os

    lea  rax, [rip + supi_k_add_n]
    mov  [r12 + 0*8], rax
    lea  rax, [rip + supi_k_sub_n]
    mov  [r12 + 1*8], rax
    lea  rax, [rip + supi_k_mul_1]
    mov  [r12 + 2*8], rax
    lea  rax, [rip + supi_k_addmul_1]
    mov  [r12 + 3*8], rax

.Lbind_check_zmm_os:
    // Check OS 512-bit register saving for mul_base, sqr_base, and the 18 vector kernels.
.if SUPI_OS == 2
    // macOS turns 512-bit state saving on lazily; read _COMM_PAGE_CPU_CAPABILITIES64
    // (0x00007fffffe00010) and test kHasAVX512F (bit 38).
    movabs rax, 0x00007fffffe00010
    mov    rax, [rax]
    bt     rax, 38
    jnc    .Lbind_exit
.else
    bt   r13d, 27                       // OSXSAVE
    jnc  .Lbind_exit
    xor  ecx, ecx
    xgetbv
    and  eax, 0xE6                      // XMM(1) | YMM(2) | opmask(5) | ZMM_Hi256(6) | Hi16_ZMM(7)
    cmp  eax, 0xE6
    jne  .Lbind_exit
.endif

    bt   r14d, 19                       // mul_base and sqr_base: ADX too
    jnc  .Lbind_vector_kernels
    lea  rax, [rip + supi_k_mul_base]
    mov  [r12 + 4*8], rax
    lea  rax, [rip + supi_k_sqr_base]
    mov  [r12 + 5*8], rax
.Lbind_vector_kernels:

    lea  rax, [rip + supi_k_fft_split]
    mov  [r12 + 6*8], rax
    lea  rax, [rip + supi_k_fft_fwd]
    mov  [r12 + 7*8], rax
    lea  rax, [rip + supi_k_fft_inv]
    mov  [r12 + 8*8], rax
    lea  rax, [rip + supi_k_fft_pmul]
    mov  [r12 + 9*8], rax
    lea  rax, [rip + supi_k_fft_pmuladd]
    mov  [r12 + 10*8], rax
    lea  rax, [rip + supi_k_fft_carry]
    mov  [r12 + 11*8], rax

    lea  rax, [rip + supi_k_ntt_split]
    mov  [r12 + 12*8], rax
    lea  rax, [rip + supi_k_ntt_fwd]
    mov  [r12 + 13*8], rax
    lea  rax, [rip + supi_k_ntt_inv]
    mov  [r12 + 14*8], rax
    lea  rax, [rip + supi_k_ntt_fwd_cols]
    mov  [r12 + 15*8], rax
    lea  rax, [rip + supi_k_ntt_inv_cols]
    mov  [r12 + 16*8], rax
    lea  rax, [rip + supi_k_ntt_pmul]
    mov  [r12 + 17*8], rax
    lea  rax, [rip + supi_k_ntt_pmuladd]
    mov  [r12 + 18*8], rax
    lea  rax, [rip + supi_k_ntt_crt]
    mov  [r12 + 19*8], rax

    lea  rax, [rip + supi_k_gather]
    mov  [r12 + 20*8], rax
    lea  rax, [rip + supi_k_scatter]
    mov  [r12 + 21*8], rax

    lea  rax, [rip + supi_k_to_digits]
    mov  [r12 + 22*8], rax
    lea  rax, [rip + supi_k_check_n]
    mov  [r12 + 23*8], rax

.Lbind_exit:
    GPR_LEAVE

// ============================================================================
// 3. Family 1 — Limb Kernels (6): MULX + ADCX/ADOX across GPRs; mul_base also has a vector form
// ============================================================================

// [0] add_n(dst: rdi, a: rsi, b: rdx, n: rcx) -> rax (carry)
LOCAL_FN supi_k_add_n
    LIMB_ENTER_FAST
    xor  eax, eax
    cmp  rcx, 8
    jb   .Ladd_tail

.p2align 4
.Ladd_loop8:
    bt   eax, 0
    mov  r8,  [rsi + 0]
    mov  r9,  [rsi + 8]
    mov  r10, [rsi + 16]
    mov  r11, [rsi + 24]
    adcx r8,  [rdx + 0]
    adcx r9,  [rdx + 8]
    adcx r10, [rdx + 16]
    adcx r11, [rdx + 24]
    mov  [rdi + 0],  r8
    mov  [rdi + 8],  r9
    mov  [rdi + 16], r10
    mov  [rdi + 24], r11

    mov  r8,  [rsi + 32]
    mov  r9,  [rsi + 40]
    mov  r10, [rsi + 48]
    mov  r11, [rsi + 56]
    adcx r8,  [rdx + 32]
    adcx r9,  [rdx + 40]
    adcx r10, [rdx + 48]
    adcx r11, [rdx + 56]
    mov  [rdi + 32], r8
    mov  [rdi + 40], r9
    mov  [rdi + 48], r10
    mov  [rdi + 56], r11
    setc al

    lea  rsi, [rsi + 64]
    lea  rdx, [rdx + 64]
    lea  rdi, [rdi + 64]
    sub  rcx, 8
    cmp  rcx, 8
    jae  .Ladd_loop8

.Ladd_tail:
    test rcx, rcx
    jz   .Ladd_done
    bt   eax, 0
.Ladd_loop1:
    mov  r8, [rsi]
    adcx r8, [rdx]
    mov  [rdi], r8
    lea  rsi, [rsi + 8]
    lea  rdx, [rdx + 8]
    lea  rdi, [rdi + 8]
    dec  rcx
    jnz  .Ladd_loop1
    setc al

.Ladd_done:
    movzx eax, al
    LIMB_LEAVE_FAST

// [1] sub_n(dst: rdi, a: rsi, b: rdx, n: rcx) -> rax (borrow)
LOCAL_FN supi_k_sub_n
    LIMB_ENTER_FAST
    xor  eax, eax
    cmp  rcx, 8
    jb   .Lsub_tail

.p2align 4
.Lsub_loop8:
    bt   eax, 0
    mov  r8,  [rsi + 0]
    mov  r9,  [rsi + 8]
    mov  r10, [rsi + 16]
    mov  r11, [rsi + 24]
    sbb  r8,  [rdx + 0]
    sbb  r9,  [rdx + 8]
    sbb  r10, [rdx + 16]
    sbb  r11, [rdx + 24]
    mov  [rdi + 0],  r8
    mov  [rdi + 8],  r9
    mov  [rdi + 16], r10
    mov  [rdi + 24], r11

    mov  r8,  [rsi + 32]
    mov  r9,  [rsi + 40]
    mov  r10, [rsi + 48]
    mov  r11, [rsi + 56]
    sbb  r8,  [rdx + 32]
    sbb  r9,  [rdx + 40]
    sbb  r10, [rdx + 48]
    sbb  r11, [rdx + 56]
    mov  [rdi + 32], r8
    mov  [rdi + 40], r9
    mov  [rdi + 48], r10
    mov  [rdi + 56], r11
    setc al

    lea  rsi, [rsi + 64]
    lea  rdx, [rdx + 64]
    lea  rdi, [rdi + 64]
    sub  rcx, 8
    cmp  rcx, 8
    jae  .Lsub_loop8

.Lsub_tail:
    test rcx, rcx
    jz   .Lsub_done
    bt   eax, 0
.Lsub_loop1:
    mov  r8, [rsi]
    sbb  r8, [rdx]
    mov  [rdi], r8
    lea  rsi, [rsi + 8]
    lea  rdx, [rdx + 8]
    lea  rdi, [rdi + 8]
    dec  rcx
    jnz  .Lsub_loop1
    setc al

.Lsub_done:
    movzx eax, al
    LIMB_LEAVE_FAST

// [2] mul_1(dst: rdi, a: rsi, n: rdx, m: rcx) -> rax (carry)
LOCAL_FN supi_k_mul_1
    LIMB_ENTER_FAST
    mov  r8, rdx                        // r8 = n
    mov  rdx, rcx                       // rdx = m (implicit source for MULX)
    xor  eax, eax                       // rax = 64-bit carry limb
    cmp  r8, 4
    jb   .Lmul1_tail

.p2align 4
.Lmul1_loop4:
    xor  r11d, r11d                     // CF = 0, r11 = 0
    mulx r10, r9,  [rsi + 0]
    adcx r9,  rax
    mov  [rdi + 0],  r9

    mulx rax, rcx, [rsi + 8]
    adcx rcx, r10
    mov  [rdi + 8],  rcx

    mulx r10, r9,  [rsi + 16]
    adcx r9,  rax
    mov  [rdi + 16], r9

    mulx rax, rcx, [rsi + 24]
    adcx rcx, r10
    mov  [rdi + 24], rcx

    adcx rax, r11                       // rax = hi3 + CF
    lea  rsi, [rsi + 32]
    lea  rdi, [rdi + 32]
    sub  r8, 4
    cmp  r8, 4
    jae  .Lmul1_loop4

.Lmul1_tail:
    test r8, r8
    jz   .Lmul1_done
.Lmul1_loop1:
    xor  r11d, r11d
    mulx r10, r9, [rsi]
    adcx r9,  rax
    adcx r10, r11
    mov  [rdi], r9
    mov  rax, r10
    lea  rsi, [rsi + 8]
    lea  rdi, [rdi + 8]
    dec  r8
    jnz  .Lmul1_loop1

.Lmul1_done:
    LIMB_LEAVE_FAST

// [3] addmul_1(dst: rdi, a: rsi, n: rdx, m: rcx) -> rax (carry)
// Uses dual independent carry chains (ADCX for product hi limbs, ADOX for dst accumulation).
LOCAL_FN supi_k_addmul_1
    LIMB_ENTER_FAST
    mov  r8, rdx                        // r8 = n
    mov  rdx, rcx                       // rdx = m
    xor  eax, eax                       // rax = incoming 64-bit carry limb
    mov  rcx, r8
    shr  rcx, 2                         // blocks of four limbs
    jz   .Laddmul1_tail
    xor  r11d, r11d                     // CF = 0, OF = 0, r11 = 0

    // Both carry chains run through the whole loop: nothing in it but ADCX and ADOX touches
    // CF or OF (LEA and JRCXZ leave the flags alone), so a limb costs one step of each chain.
.p2align 4
.Laddmul1_loop4:
    mulx r10, r9, [rsi + 0]
    adcx r9,  rax
    adox r9,  [rdi + 0]
    mov  [rdi + 0], r9

    mulx rax, r9, [rsi + 8]
    adcx r9,  r10
    adox r9,  [rdi + 8]
    mov  [rdi + 8], r9

    mulx r10, r9, [rsi + 16]
    adcx r9,  rax
    adox r9,  [rdi + 16]
    mov  [rdi + 16], r9

    mulx rax, r9, [rsi + 24]
    adcx r9,  r10
    adox r9,  [rdi + 24]
    mov  [rdi + 24], r9

    lea  rsi, [rsi + 32]
    lea  rdi, [rdi + 32]
    lea  rcx, [rcx - 1]
    jrcxz .Laddmul1_loop4_end
    jmp  .Laddmul1_loop4
.Laddmul1_loop4_end:
    adcx rax, r11                       // close both chains into the carry limb
    adox rax, r11
    and  r8, 3

.Laddmul1_tail:
    test r8, r8
    jz   .Laddmul1_done
.Laddmul1_loop1:
    xor  r11d, r11d
    mulx r10, r9, [rsi]
    adcx r9,  rax
    adox r9,  [rdi]
    mov  [rdi], r9
    adcx r10, r11
    adox r10, r11
    mov  rax, r10
    lea  rsi, [rsi + 8]
    lea  rdi, [rdi + 8]
    dec  r8
    jnz  .Laddmul1_loop1

.Laddmul1_done:
    LIMB_LEAVE_FAST

// [4] mul_base(dst: rdi, a: rsi, b: rdx, lens: rcx /* &[na, nb, rows_max] */)
//
// dst[0 .. na + nb] = a * b, a row for every limb of the shorter operand: the first row is the
// product of the longer operand and one limb, every other row adds such a product into dst.
// A row runs on two carry chains, CF for the high half of a limb's product into the low half
// of the next and OF for the sums with dst; both are clear when a row ends, since its top limb
// cannot overflow.
//
// Rows of up to eight limbs are straight code, one copy for each length, reached once a call
// through a table. Longer rows run an eight-limb loop that is entered where its first pass
// takes ((na - 1) mod 8) + 1 limbs, so that no row has a tail.
//
// Where the shorter operand has more than rows_max limbs and at most 64, and the longer at
// most 128, the product is made on 28-bit digits in the 512-bit registers instead (.Lvmb, after
// the rows). rows_max is the caller's: the length up to which rows are the faster of the two on
// the machine at hand, which the plan measures. The two bounds above it are this body's own.

// One limb of a row: rdx = the row's limb of b, rsi and rdi = a and dst at the pass, \T = the
// limb's place in it. Its high half goes to r9 where \T is even and to r10 where it is odd,
// and the high half before it comes from the other of the two. \ADD = 1 adds dst in.
.macro MB_LIMB T, ADD
.if ((\T) & 1) == 0
    mulx r9,  rax, [rsi + 8*(\T)]
    adcx rax, r10
.else
    mulx r10, rax, [rsi + 8*(\T)]
    adcx rax, r9
.endif
.if \ADD
    adox rax, [rdi + 8*(\T)]
.endif
    mov  [rdi + 8*(\T)], rax
.endm

// A whole row of \N limbs (1..8) and its top limb. r8 = 0; CF and OF are clear before and after.
.macro MB_SMALL_ROW N, ADD
    mulx r9,  rax, [rsi]
.if \ADD
    adox rax, [rdi]
.endif
    mov  [rdi], rax
.if \N > 1
    MB_LIMB 1, \ADD
.endif
.if \N > 2
    MB_LIMB 2, \ADD
.endif
.if \N > 3
    MB_LIMB 3, \ADD
.endif
.if \N > 4
    MB_LIMB 4, \ADD
.endif
.if \N > 5
    MB_LIMB 5, \ADD
.endif
.if \N > 6
    MB_LIMB 6, \ADD
.endif
.if \N > 7
    MB_LIMB 7, \ADD
.endif
.if ((\N) & 1) == 1
.if \N > 1
    adcx r9,  r8
.endif
.if \ADD
    adox r9,  r8
.endif
    mov  [rdi + 8*(\N)], r9
.else
    adcx r10, r8
.if \ADD
    adox r10, r8
.endif
    mov  [rdi + 8*(\N)], r10
.endif
.endm

// The product for a longer operand of \N limbs (1..8): r11 = the end of b, rcx = the row less
// the number of rows (it counts up to zero; INC leaves CF alone and clears OF here).
// Uses only volatile GPRs (+ rdi, rsi on Win64), avoiding 12 callee-saved push/pops on <= 8 limbs.
.macro MB_SMALL N
.p2align 4
.Lmb_small_\N:
    xor  r8d, r8d                       // r8 = 0, CF = OF = 0
    MB_SMALL_ROW \N, 0
    inc  rcx
    jz   .Lmb_small_done_\N
.p2align 4
.Lmb_small_row_\N:
    mov  rdx, [r11 + 8*rcx]
    lea  rdi, [rdi + 8]
    MB_SMALL_ROW \N, 1
    inc  rcx
    jnz  .Lmb_small_row_\N
.Lmb_small_done_\N:
.if SUPI_OS == 1
    pop  rsi
    pop  rdi
.endif
    ret
.endm

LOCAL_FN supi_k_mul_base
.if SUPI_OS == 1
    push rdi
    push rsi
    mov  rdi, rcx
    mov  rsi, rdx
    mov  rdx, r8
    mov  rcx, r9
.endif
    mov  r8,  [rcx + 0]                 // na
    mov  rax, [rcx + 16]                // rows_max
    mov  rcx, [rcx + 8]                 // nb
    test r8,  r8
    jz   .Lmb_small_ret
    test rcx, rcx
    jz   .Lmb_small_ret
    cmp  r8,  rcx
    jae  .Lmulbase_ordered
    xchg r8,  rcx
    xchg rsi, rdx
.Lmulbase_ordered:                      // a = rsi (r8 limbs, the longer), b = rdx (rcx limbs), rax = rows_max
    cmp  r8,  8
    ja   .Lmb_long
    lea  r11, [rdx + 8*rcx]             // the end of b
    neg  rcx
    mov  rdx, [r11 + 8*rcx]             // b[0]
    cmp  r8,  4
    ja   .Lmb_small_5to8
    cmp  r8,  2
    ja   .Lmb_small_3to4
    cmp  r8,  1
    je   .Lmb_small_1
    jmp  .Lmb_small_2
.Lmb_small_3to4:
    cmp  r8,  3
    je   .Lmb_small_3
    jmp  .Lmb_small_4
.Lmb_small_5to8:
    cmp  r8,  6
    ja   .Lmb_small_7to8
    je   .Lmb_small_6
    jmp  .Lmb_small_5
.Lmb_small_7to8:
    cmp  r8,  7
    je   .Lmb_small_7
    jmp  .Lmb_small_8

    MB_SMALL 1
    MB_SMALL 2
    MB_SMALL 3
    MB_SMALL 4
    MB_SMALL 5
    MB_SMALL 6
    MB_SMALL 7
    MB_SMALL 8

.p2align 4
.Lmb_long:
    // Shorter operand <= rows_max stays on scalar MULX/ADCX/ADOX rows; above rows_max uses
    // direct 28-bit vector multiplication (.Lvmb) up to 64 x 128 and 2D vector block tiling above.
    cmp  rcx, rax
    jbe  .Lmb_long_scalar
    cmp  rcx, 64
    ja   .Lmb_tiled_vmb
    cmp  r8,  128
    jbe  .Lvmb

.Lmb_tiled_vmb:
    push rbp
    mov  rbp, rsp
    push rbx
    push r12
    push r13
    push r14
    push r15
    sub  rsp, 1664
    and  rsp, -64
    mov  qword ptr [rsp], 0
    mov  [rsp + 1536], rdi              // dst
    mov  [rsp + 1544], rsi              // a
    mov  [rsp + 1552], r8               // na
    mov  [rsp + 1560], rdx              // b
    mov  [rsp + 1568], rcx              // nb
    mov  [rsp + 1576], rax              // rows_max

    lea  rcx, [r8 + rcx]
    mov  r9,  rdi
    xor  eax, eax
.Lmb_tiled_zero:
    mov  [r9], rax
    lea  r9, [r9 + 8]
    dec  rcx
    jnz  .Lmb_tiled_zero

    xor  eax, eax
    mov  [rsp + 1592], rax              // ib = 0
.Lmb_tiled_ib_loop:
    mov  rax, [rsp + 1592]              // ib
    mov  rcx, [rsp + 1568]              // nb
    sub  rcx, rax                       // rem_b = nb - ib
    mov  edx, 64
    cmp  rcx, 64
    cmova rcx, rdx                      // lb = min(64, nb - ib)
    mov  [rsp + 1600], rcx

    xor  eax, eax
    mov  [rsp + 1608], rax              // ia = 0
.Lmb_tiled_ia_loop:
    mov  rax, [rsp + 1608]              // ia
    mov  r8,  [rsp + 1552]              // na
    sub  r8,  rax                       // rem_a = na - ia
    mov  edx, 128
    cmp  r8,  128
    cmova r8, rdx                       // la = min(128, na - ia)
    mov  [rsp + 1616], r8

    mov  rsi, [rsp + 1544]
    lea  rsi, [rsi + 8*rax]             // &a[ia]
    mov  rbx, [rsp + 1592]              // ib
    mov  rdx, [rsp + 1560]
    lea  rdx, [rdx + 8*rbx]             // &b[ib]
    mov  rcx, [rsp + 1600]              // lb

    cmp  r8,  rcx
    jae  .Lmb_tiled_ord
    xchg r8,  rcx
    xchg rsi, rdx
.Lmb_tiled_ord:
    cmp  rcx, [rsp + 1576]
    jbe  .Lmb_tiled_do_sc
    cmp  r8,  9
    jb   .Lmb_tiled_do_sc

    mov  rdi, rsp                       // tile_prod[0..192]
    call .Lvmb_core
    mov  rax, [rsp + 1592]
    add  rax, [rsp + 1608]              // ia + ib
    mov  rdi, [rsp + 1536]
    lea  rdi, [rdi + 8*rax]             // &dst[ia + ib]
    mov  rsi, rsp
    mov  rcx, [rsp + 1600]
    add  rcx, [rsp + 1616]              // la + lb
    call .Lblk_add_into_dst
    jmp  .Lmb_tiled_ia_next

.Lmb_tiled_do_sc:
    mov  rax, [rsp + 1592]
    add  rax, [rsp + 1608]
    mov  rdi, [rsp + 1536]
    lea  rdi, [rdi + 8*rax]
    call .Lblk_acc_scalar

.Lmb_tiled_ia_next:
    mov  rax, [rsp + 1608]
    add  rax, 128
    cmp  rax, [rsp + 1552]
    jae  .Lmb_tiled_ib_next
    mov  [rsp + 1608], rax
    jmp  .Lmb_tiled_ia_loop

.Lmb_tiled_ib_next:
    mov  rax, [rsp + 1592]
    add  rax, 64
    cmp  rax, [rsp + 1568]
    jae  .Lmb_tiled_done
    mov  [rsp + 1592], rax
    jmp  .Lmb_tiled_ib_loop

.Lmb_tiled_done:
    lea  rsp, [rbp - 40]
    pop  r15
    pop  r14
    pop  r13
    pop  r12
    pop  rbx
    pop  rbp
    jmp  .Lmb_small_ret

.Lmb_long_scalar:
    push rbx
    push r12
    push r13
    push r14
    push r15
    mov  r15, rcx                       // nb
    mov  r12, rsi                       // a
    mov  r13, rdx                       // b, at the row's limb
    mov  r14, rdi                       // dst, at the row's first limb
    lea  rax, [r8 - 1]
    mov  rbx, rax
    shr  rbx, 3
    inc  rbx                            // passes a row
    and  eax, 7                         // limbs of a row's first pass, less one
    lea  r8,  [8*rax - 56]              // the first pass ends with the loop's eighth limb
    lea  r11, [rip + .Lmb_long_table]
    movsxd r10, dword ptr [r11 + 4*rax + 32]
    movsxd rax, dword ptr [r11 + 4*rax]
    add  rax, r11                       // where the first row enters its loop
    add  r11, r10                       // where every other row enters its loop
    mov  rdx, [r13]
    lea  rsi, [r12 + r8]
    lea  rdi, [r14 + r8]
    mov  rcx, rbx
    xor  r9d, r9d                       // no high half yet; CF = OF = 0
    xor  r10d, r10d
    jmp  rax

    // The first row: dst = a * b[0]. Nothing in the loop but ADCX touches CF (LEA and JRCXZ
    // leave the flags alone).
.p2align 4
.Lmb_long_first_top:
.Lmb_long_first_e8:
    MB_LIMB 0, 0
.Lmb_long_first_e7:
    MB_LIMB 1, 0
.Lmb_long_first_e6:
    MB_LIMB 2, 0
.Lmb_long_first_e5:
    MB_LIMB 3, 0
.Lmb_long_first_e4:
    MB_LIMB 4, 0
.Lmb_long_first_e3:
    MB_LIMB 5, 0
.Lmb_long_first_e2:
    MB_LIMB 6, 0
.Lmb_long_first_e1:
    MB_LIMB 7, 0
    lea  rcx, [rcx - 1]
    jrcxz .Lmb_long_first_end
    lea  rsi, [rsi + 64]
    lea  rdi, [rdi + 64]
    jmp  .Lmb_long_first_top
.Lmb_long_first_end:
    adcx r10, rcx                       // rcx = 0: the top limb
    mov  [rdi + 64], r10
    dec  r15
    jz   .Lmulbase_done

    // Every other row: dst[j .. j + na + 1] += a * b[j].
.p2align 4
.Lmb_long_row:
    lea  r13, [r13 + 8]
    lea  r14, [r14 + 8]
    mov  rdx, [r13]
    lea  rsi, [r12 + r8]
    lea  rdi, [r14 + r8]
    mov  rcx, rbx
    xor  r9d, r9d                       // no high half yet; CF = OF = 0
    xor  r10d, r10d
    jmp  r11

.p2align 4
.Lmb_long_row_top:
.Lmb_long_row_e8:
    MB_LIMB 0, 1
.Lmb_long_row_e7:
    MB_LIMB 1, 1
.Lmb_long_row_e6:
    MB_LIMB 2, 1
.Lmb_long_row_e5:
    MB_LIMB 3, 1
.Lmb_long_row_e4:
    MB_LIMB 4, 1
.Lmb_long_row_e3:
    MB_LIMB 5, 1
.Lmb_long_row_e2:
    MB_LIMB 6, 1
.Lmb_long_row_e1:
    MB_LIMB 7, 1
    lea  rcx, [rcx - 1]
    jrcxz .Lmb_long_row_end
    lea  rsi, [rsi + 64]
    lea  rdi, [rdi + 64]
    jmp  .Lmb_long_row_top
.Lmb_long_row_end:
    adcx r10, rcx                       // rcx = 0: the top limb
    adox r10, rcx
    mov  [rdi + 64], r10
    dec  r15
    jnz  .Lmb_long_row

.Lmulbase_done:
    pop  r15
    pop  r14
    pop  r13
    pop  r12
    pop  rbx
.Lmb_small_ret:
.if SUPI_OS == 1
    pop  rsi
    pop  rdi
.endif
    ret

// Where the code for each length starts, as distances from the table (kept in the text
// section, next to the code they point into, so that they are plain numbers).
.p2align 2
.Lmb_long_table:
    .long .Lmb_long_first_e1 - .Lmb_long_table
    .long .Lmb_long_first_e2 - .Lmb_long_table
    .long .Lmb_long_first_e3 - .Lmb_long_table
    .long .Lmb_long_first_e4 - .Lmb_long_table
    .long .Lmb_long_first_e5 - .Lmb_long_table
    .long .Lmb_long_first_e6 - .Lmb_long_table
    .long .Lmb_long_first_e7 - .Lmb_long_table
    .long .Lmb_long_first_e8 - .Lmb_long_table
    .long .Lmb_long_row_e1 - .Lmb_long_table
    .long .Lmb_long_row_e2 - .Lmb_long_table
    .long .Lmb_long_row_e3 - .Lmb_long_table
    .long .Lmb_long_row_e4 - .Lmb_long_table
    .long .Lmb_long_row_e5 - .Lmb_long_table
    .long .Lmb_long_row_e6 - .Lmb_long_table
    .long .Lmb_long_row_e7 - .Lmb_long_table
    .long .Lmb_long_row_e8 - .Lmb_long_table


// ---------------------------------------------------------------------------
// mul_base on the vector unit: a short operand of up to 64 limbs, a long one of up to 128.
//
// Both operands are cut into digits of 28 bits. A digit of the long operand, in all eight
// lanes, multiplies the short operand's digits eight at a time (VPMULUDQ), and the products are
// added to column sums held in up to twenty registers; a column takes at most 147 products
// below 2^56, so a sum stays below 2^64 and no carry is looked at until the end. The products
// of a digit start one column further up than those of the digit before it: the short operand
// is kept in eight copies, each a lane further up than the last, so that every load is a whole
// aligned register. After eight digits the lowest register is complete, is stored, and the
// registers move down by one.
//
// At the end column c is S_c = l_c + 2^28 h_c: the columns are put together two by two,
// P_m = (l_2m + h_(2m-1)) + 2^28 (l_(2m+1) + h_2m) < 2^64, and the product is the sum of
// P_m 2^(56 m): seven bytes a pair, with what a pair has above them carried into the next.
// What a pair has above its seven bytes is less than 2^8, so the seven bytes of the pair above
// plus that carry stay within seven bytes unless those bytes are within 2^8 of all ones: for
// every pair but the last eight or fewer, the bytes are therefore made eight pairs at a time
// from each pair and the one below it alone, and written fifty-six bytes a step. The sums are
// collected, and where one of them did outgrow its seven bytes, which no product of ordinary
// numbers does, the whole product is written again by the chain that carries pair by pair. That
// chain also writes the last pairs, whose stores have to end with the product.
//
// The bounds: twenty registers of sums take a short operand of up to 66 limbs (64 is used),
// and the frame is laid out for a long operand of 128 limbs. From which length of the short
// operand this is the faster of the two ways is not this file's to say: it is the caller's
// rows_max (14 limbs and more on a Zen 5 core, alone and two threads to the core).
//
// Stack: [0, 160) xmm6..xmm15 (Windows), [160, 192) scalars, [192, 2688) the long operand's
// digits, [2688, 13440) the eight copies of the short operand (1344 bytes apart),
// [13440, 17344) the column sums, then the pairs.
// ---------------------------------------------------------------------------

// zmm0 = eight limbs (seven are used) -> zmm2 = digits 0..7, zmm0 = digits 8..15.
// zmm4 = .Lvmb_perm_d, zmm5 = .Lvmb_shuf_in, zmm16 = 2^28 - 1, zmm17/zmm18 = .Lvmb_il_lo/_hi.
.macro VMB_SPLIT
    vpermd    zmm0, zmm4, zmm0          // the fourteen bytes of two pairs of digits to each lane
    vpshufb   zmm0, zmm0, zmm5          // a pair of digits (56 bits) in each quadword
    vpsrlq    zmm1, zmm0, 28            // the odd digits
    vpandq    zmm0, zmm0, zmm16         // the even digits
    vmovdqa64 zmm2, zmm17
    vpermi2q  zmm2, zmm0, zmm1
    vpermt2q  zmm0, zmm18, zmm1
.endm

// min(8, rcx) limbs at rsi, the rest zero -> zmm0
.macro VMB_LOAD
    mov  eax, 8
    cmp  rcx, 8
    cmovb eax, ecx
    mov  edx, -1
    bzhi edx, edx, eax
    kmovw k1, edx
    vmovdqu64 zmm0{k1}{z}, [rsi]
.endm

// The vector \CUR of the short operand's digits in its eight copies, \PREV = the vector before it.
.macro VMB_COPIES CUR, PREV, OFF
    vmovdqa64 [rbx + \OFF], \CUR
    valignq   zmm1, \CUR, \PREV, 7
    vmovdqa64 [rbx + \OFF + 1344], zmm1
    valignq   zmm1, \CUR, \PREV, 6
    vmovdqa64 [rbx + \OFF + 2688], zmm1
    valignq   zmm1, \CUR, \PREV, 5
    vmovdqa64 [rbx + \OFF + 4032], zmm1
    valignq   zmm1, \CUR, \PREV, 4
    vmovdqa64 [rbx + \OFF + 5376], zmm1
    valignq   zmm1, \CUR, \PREV, 3
    vmovdqa64 [rbx + \OFF + 6720], zmm1
    valignq   zmm1, \CUR, \PREV, 2
    vmovdqa64 [rbx + \OFF + 8064], zmm1
    valignq   zmm1, \CUR, \PREV, 1
    vmovdqa64 [rbx + \OFF + 9408], zmm1
.endm

// The products of two digits of the long operand (zmm0, zmm1) and one vector of the short
// operand, in the copies of the two digits' shifts, into the sum zmm\R.
.macro VMB_PAIR I, R, W
.Lvmb_row_e\W:
    vpmuludq zmm2, zmm0, [rsi + 64*\I]
    vpmuludq zmm3, zmm1, [rsi + 1344 + 64*\I]
    vpaddq   zmm2, zmm2, zmm3
    vpaddq   zmm\R, zmm\R, zmm2
.endm

.p2align 4
.Lvmb:                                  // tail-jump entry: rdi = dst, rsi = long (r8), rdx = short (rcx)
    call .Lvmb_core
    jmp  .Lmb_small_ret

.p2align 4
.Lvmb_core:                             // callable: rdi = dst, rsi = long (r8 <= 128), rdx = short (rcx <= 64)
    push rbp
    mov  rbp, rsp
    push rbx
    push r12
    push r13
    push r14
    push r15
    mov  r15, rcx
    .rept 4
    sub  rsp, 4096
    mov  qword ptr [rsp], 0
    .endr
    sub  rsp, 960
    and  rsp, -64
    mov  qword ptr [rsp], 0
    mov  [rsp + 160], rdi
    lea  rax, [r8 + r15]
    mov  [rsp + 168], rax               // limbs of the product
    mov  r13, r8                        // limbs of the long operand
    mov  r14, rdx                       // the short operand
    vmovdqa64 zmm4,  [rip + .Lvmb_perm_d]
    vmovdqa64 zmm5,  [rip + .Lvmb_shuf_in]
    vpbroadcastq zmm16, [rip + .Lvmb_m28]
    vmovdqa64 zmm17, [rip + .Lvmb_il_lo]
    vmovdqa64 zmm18, [rip + .Lvmb_il_hi]

    // the long operand's digits, sixteen to seven limbs
    lea  rbx, [rsp + 192]
    mov  rcx, r13
.p2align 4
.Lvmb_long_blk:
    VMB_LOAD
    VMB_SPLIT
    vmovdqa64 [rbx], zmm2
    vmovdqa64 [rbx + 64], zmm0
    add  rsi, 56
    add  rbx, 128
    sub  rcx, 7
    jg   .Lvmb_long_blk

    // the short operand's digits, in eight copies
    lea  rbx, [rsp + 2688]
    mov  rsi, r14
    mov  rcx, r15
    vpxorq zmm3, zmm3, zmm3             // the vector before the first
.p2align 4
.Lvmb_short_blk:
    VMB_LOAD
    VMB_SPLIT
    VMB_COPIES zmm2, zmm3, 0
    VMB_COPIES zmm0, zmm2, 64
    vmovdqa64 zmm3, zmm0
    add  rsi, 56
    add  rbx, 128
    sub  rcx, 7
    jg   .Lvmb_short_blk
    vpxorq zmm0, zmm0, zmm0
    VMB_COPIES zmm0, zmm3, 0            // what the last vector leaves for the one above it

    // W = sums a digit's products reach = (d + 6) / 8 + 1 for d = ceil(16 ns / 7) digits;
    // x / 7 = (x * 9363) >> 16 for x below 13000
    mov  eax, r15d
    shl  eax, 4
    add  eax, 6
    imul eax, eax, 9363
    shr  eax, 16
    add  eax, 6
    shr  eax, 3
    inc  eax
    mov  ecx, 20
    sub  ecx, eax                       // the sums are the registers zmm(12 + rcx) .. zmm31
.if SUPI_OS == 1
    cmp  ecx, 4
    jae  1f
    vmovups xmmword ptr [rsp + 96], xmm12
    vmovups xmmword ptr [rsp + 112], xmm13
    vmovups xmmword ptr [rsp + 128], xmm14
    vmovups xmmword ptr [rsp + 144], xmm15
1:
.endif
    lea  r11, [rip + .Lvmb_table]
    movsxd r9,  dword ptr [r11 + 4*rcx]
    movsxd r10, dword ptr [r11 + 4*rcx + 80]
    movsxd rax, dword ptr [r11 + 4*rcx + 160]
    movsxd rdi, dword ptr [r11 + 4*rcx + 240]
    add  r9,  r11                       // where a pair of rows starts
    add  r10, r11                       // where the lowest sum is stored and the others move down
    add  rax, r11                       // where the sums are stored at the end
    add  rdi, r11                       // where active sum registers are zeroed
    mov  [rsp + 176], rax
    shl  rcx, 6
    mov  [rsp + 184], rcx
    lea  rsi, [rsp + 2688]
    sub  rsi, rcx                       // the copies, so that zmm(12 + i) goes with [rsi + 64 i]
    lea  r11, [rsp + 13440]
    // epochs of eight digits: ceil(d / 8) for the long operand's d = ceil(16 nl / 7) digits
    mov  eax, r13d
    shl  eax, 4
    add  eax, 6
    imul eax, eax, 9363
    shr  eax, 16
    add  eax, 7
    shr  eax, 3
    mov  r8d, eax
    lea  rdx, [rsp + 192]
    mov  ecx, 4
    jmp  rdi
.Lvmb_zero_e20:
    vpxorq zmm12, zmm12, zmm12
.Lvmb_zero_e19:
    vpxorq zmm13, zmm13, zmm13
.Lvmb_zero_e18:
    vpxorq zmm14, zmm14, zmm14
.Lvmb_zero_e17:
    vpxorq zmm15, zmm15, zmm15
.Lvmb_zero_e16:
    vpxorq zmm16, zmm16, zmm16
.Lvmb_zero_e15:
    vpxorq zmm17, zmm17, zmm17
.Lvmb_zero_e14:
    vpxorq zmm18, zmm18, zmm18
.Lvmb_zero_e13:
    vpxorq zmm19, zmm19, zmm19
.Lvmb_zero_e12:
    vpxorq zmm20, zmm20, zmm20
.Lvmb_zero_e11:
    vpxorq zmm21, zmm21, zmm21
.Lvmb_zero_e10:
    vpxorq zmm22, zmm22, zmm22
.Lvmb_zero_e9:
    vpxorq zmm23, zmm23, zmm23
.Lvmb_zero_e8:
    vpxorq zmm24, zmm24, zmm24
.Lvmb_zero_e7:
    vpxorq zmm25, zmm25, zmm25
.Lvmb_zero_e6:
    vpxorq zmm26, zmm26, zmm26
.Lvmb_zero_e5:
    vpxorq zmm27, zmm27, zmm27
.Lvmb_zero_e4:
    vpxorq zmm28, zmm28, zmm28
.Lvmb_zero_e3:
    vpxorq zmm29, zmm29, zmm29
.Lvmb_zero_e2:
    vpxorq zmm30, zmm30, zmm30
.Lvmb_zero_e1:
    vpxorq zmm31, zmm31, zmm31

.p2align 4
.Lvmb_rows:
    vpbroadcastq zmm0, [rdx]
    vpbroadcastq zmm1, [rdx + 8]
    jmp  r9
.p2align 4
    VMB_PAIR 0, 12, 20
    VMB_PAIR 1, 13, 19
    VMB_PAIR 2, 14, 18
    VMB_PAIR 3, 15, 17
    VMB_PAIR 4, 16, 16
    VMB_PAIR 5, 17, 15
    VMB_PAIR 6, 18, 14
    VMB_PAIR 7, 19, 13
    VMB_PAIR 8, 20, 12
    VMB_PAIR 9, 21, 11
    VMB_PAIR 10, 22, 10
    VMB_PAIR 11, 23, 9
    VMB_PAIR 12, 24, 8
