    VMB_PAIR 16, 28, 4
    VMB_PAIR 17, 29, 3
    VMB_PAIR 18, 30, 2
    VMB_PAIR 19, 31, 1
    add  rsi, 2688
    add  rdx, 16
    dec  ecx
    jnz  .Lvmb_rows
    jmp  r10

.Lvmb_rot_e20:
    vmovdqa64 [r11], zmm12
    jmp  .Lvmb_rot_c0
.Lvmb_rot_e19:
    vmovdqa64 [r11], zmm13
    jmp  .Lvmb_rot_c1
.Lvmb_rot_e18:
    vmovdqa64 [r11], zmm14
    jmp  .Lvmb_rot_c2
.Lvmb_rot_e17:
    vmovdqa64 [r11], zmm15
    jmp  .Lvmb_rot_c3
.Lvmb_rot_e16:
    vmovdqa64 [r11], zmm16
    jmp  .Lvmb_rot_c4
.Lvmb_rot_e15:
    vmovdqa64 [r11], zmm17
    jmp  .Lvmb_rot_c5
.Lvmb_rot_e14:
    vmovdqa64 [r11], zmm18
    jmp  .Lvmb_rot_c6
.Lvmb_rot_e13:
    vmovdqa64 [r11], zmm19
    jmp  .Lvmb_rot_c7
.Lvmb_rot_e12:
    vmovdqa64 [r11], zmm20
    jmp  .Lvmb_rot_c8
.Lvmb_rot_e11:
    vmovdqa64 [r11], zmm21
    jmp  .Lvmb_rot_c9
.Lvmb_rot_e10:
    vmovdqa64 [r11], zmm22
    jmp  .Lvmb_rot_c10
.Lvmb_rot_e9:
    vmovdqa64 [r11], zmm23
    jmp  .Lvmb_rot_c11
.Lvmb_rot_e8:
    vmovdqa64 [r11], zmm24
    jmp  .Lvmb_rot_c12
.Lvmb_rot_e7:
    vmovdqa64 [r11], zmm25
    jmp  .Lvmb_rot_c13
.Lvmb_rot_e6:
    vmovdqa64 [r11], zmm26
    jmp  .Lvmb_rot_c14
.Lvmb_rot_e5:
    vmovdqa64 [r11], zmm27
    jmp  .Lvmb_rot_c15
.Lvmb_rot_e4:
    vmovdqa64 [r11], zmm28
    jmp  .Lvmb_rot_c16
.Lvmb_rot_e3:
    vmovdqa64 [r11], zmm29
    jmp  .Lvmb_rot_c17
.Lvmb_rot_e2:
    vmovdqa64 [r11], zmm30
    jmp  .Lvmb_rot_c18
.Lvmb_rot_e1:
    vmovdqa64 [r11], zmm31
    jmp  .Lvmb_rot_c19
.Lvmb_rot_c0:
    vmovdqa64 zmm12, zmm13
.Lvmb_rot_c1:
    vmovdqa64 zmm13, zmm14
.Lvmb_rot_c2:
    vmovdqa64 zmm14, zmm15
.Lvmb_rot_c3:
    vmovdqa64 zmm15, zmm16
.Lvmb_rot_c4:
    vmovdqa64 zmm16, zmm17
.Lvmb_rot_c5:
    vmovdqa64 zmm17, zmm18
.Lvmb_rot_c6:
    vmovdqa64 zmm18, zmm19
.Lvmb_rot_c7:
    vmovdqa64 zmm19, zmm20
.Lvmb_rot_c8:
    vmovdqa64 zmm20, zmm21
.Lvmb_rot_c9:
    vmovdqa64 zmm21, zmm22
.Lvmb_rot_c10:
    vmovdqa64 zmm22, zmm23
.Lvmb_rot_c11:
    vmovdqa64 zmm23, zmm24
.Lvmb_rot_c12:
    vmovdqa64 zmm24, zmm25
.Lvmb_rot_c13:
    vmovdqa64 zmm25, zmm26
.Lvmb_rot_c14:
    vmovdqa64 zmm26, zmm27
.Lvmb_rot_c15:
    vmovdqa64 zmm27, zmm28
.Lvmb_rot_c16:
    vmovdqa64 zmm28, zmm29
.Lvmb_rot_c17:
    vmovdqa64 zmm29, zmm30
.Lvmb_rot_c18:
    vmovdqa64 zmm30, zmm31
.Lvmb_rot_c19:
    vpxorq zmm31, zmm31, zmm31
    add  r11, 64
    sub  rsi, 10752
    mov  ecx, 4
    dec  r8d
    jnz  .Lvmb_rows

    mov  rax, [rsp + 176]
    sub  r11, [rsp + 184]
    jmp  rax
.Lvmb_flush_e20:
    vmovdqa64 [r11 + 0], zmm12
.Lvmb_flush_e19:
    vmovdqa64 [r11 + 64], zmm13
.Lvmb_flush_e18:
    vmovdqa64 [r11 + 128], zmm14
.Lvmb_flush_e17:
    vmovdqa64 [r11 + 192], zmm15
.Lvmb_flush_e16:
    vmovdqa64 [r11 + 256], zmm16
.Lvmb_flush_e15:
    vmovdqa64 [r11 + 320], zmm17
.Lvmb_flush_e14:
    vmovdqa64 [r11 + 384], zmm18
.Lvmb_flush_e13:
    vmovdqa64 [r11 + 448], zmm19
.Lvmb_flush_e12:
    vmovdqa64 [r11 + 512], zmm20
.Lvmb_flush_e11:
    vmovdqa64 [r11 + 576], zmm21
.Lvmb_flush_e10:
    vmovdqa64 [r11 + 640], zmm22
.Lvmb_flush_e9:
    vmovdqa64 [r11 + 704], zmm23
.Lvmb_flush_e8:
    vmovdqa64 [r11 + 768], zmm24
.Lvmb_flush_e7:
    vmovdqa64 [r11 + 832], zmm25
.Lvmb_flush_e6:
    vmovdqa64 [r11 + 896], zmm26
.Lvmb_flush_e5:
    vmovdqa64 [r11 + 960], zmm27
.Lvmb_flush_e4:
    vmovdqa64 [r11 + 1024], zmm28
.Lvmb_flush_e3:
    vmovdqa64 [r11 + 1088], zmm29
.Lvmb_flush_e2:
    vmovdqa64 [r11 + 1152], zmm30
.Lvmb_flush_e1:
    vmovdqa64 [r11 + 1216], zmm31
    vpxorq zmm0, zmm0, zmm0
    vmovdqa64 [r11 + 1280], zmm0
    vmovdqa64 [r11 + 1344], zmm0

    // columns to pairs, sixteen columns a step; the pairs go where the columns were. The steps
    // are ceil(limbs of the product / 7), and all but the last also write their pairs' bytes:
    // a step writes 58 bytes from 56 times its number on, which for those steps ends inside
    // the product.
    lea  rsi, [rsp + 13440]
    mov  rbx, rsi
    mov  rdi, [rsp + 160]
    mov  eax, [rsp + 168]
    add  eax, 6
    imul eax, eax, 9363
    shr  eax, 16
    lea  r12d, [rax - 1]                // the steps that write bytes (one at least: ten limbs and more)
    mov  ecx, r12d
    vpbroadcastq zmm16, [rip + .Lvmb_m28]
    vpxorq    zmm17, zmm17, zmm17       // what the column before the step has above 28 bits
    vmovdqa64 zmm18, [rip + .Lvmb_even]
    vmovdqa64 zmm19, [rip + .Lvmb_odd]
    vpbroadcastq zmm20, [rip + .Lvmb_m56]
    vbroadcasti32x4 zmm21, xmmword ptr [rip + .Lvmb_shuf_out]
    vpxorq    zmm22, zmm22, zmm22       // every sum of seven bytes and a carry, or-ed together
    vpxorq    zmm23, zmm23, zmm23       // what the pair before the step has above seven bytes
.p2align 4
.Lvmb_fin_vec:
    vmovdqa64 zmm0, [rsi]
    vmovdqa64 zmm1, [rsi + 64]
    vpsrlq  zmm2, zmm0, 28
    vpsrlq  zmm3, zmm1, 28
    vpandq  zmm0, zmm0, zmm16
    vpandq  zmm1, zmm1, zmm16
    valignq zmm17, zmm2, zmm17, 7       // each column's upper part to the column above
    valignq zmm2, zmm3, zmm2, 7
    vpaddq  zmm0, zmm0, zmm17
    vpaddq  zmm1, zmm1, zmm2
    vmovdqa64 zmm17, zmm3
    vmovdqa64 zmm2, zmm18
    vpermi2q zmm2, zmm0, zmm1           // the even columns
    vpermt2q zmm0, zmm19, zmm1          // the odd columns
    vpsllq  zmm0, zmm0, 28
    vpaddq  zmm2, zmm2, zmm0
    vmovdqa64 [rbx], zmm2               // the pairs, for the last step's carry and the chain
    vpsrlq  zmm0, zmm2, 56              // what each pair has above its seven bytes
    vpandq  zmm2, zmm2, zmm20
    valignq zmm1, zmm0, zmm23, 7        // ... goes to the pair above
    vmovdqa64 zmm23, zmm0
    vpaddq  zmm2, zmm2, zmm1
    vporq   zmm22, zmm22, zmm2
    vpshufb zmm2, zmm2, zmm21           // two pairs' fourteen bytes to the bottom of each lane
    vmovdqu xmmword ptr [rdi], xmm2     // sixteen bytes a lane: the two on top are the next lane's
    vextracti32x4 xmmword ptr [rdi + 14], zmm2, 1
    vextracti32x4 xmmword ptr [rdi + 28], zmm2, 2
    vextracti32x4 xmmword ptr [rdi + 42], zmm2, 3
    add  rdi, 56
    add  rsi, 128
    add  rbx, 64
    dec  ecx
    jnz  .Lvmb_fin_vec

    // the last step: its pairs only
    vmovdqa64 zmm0, [rsi]
    vmovdqa64 zmm1, [rsi + 64]
    vpsrlq  zmm2, zmm0, 28
    vpsrlq  zmm3, zmm1, 28
    vpandq  zmm0, zmm0, zmm16
    vpandq  zmm1, zmm1, zmm16
    valignq zmm17, zmm2, zmm17, 7
    valignq zmm2, zmm3, zmm2, 7
    vpaddq  zmm0, zmm0, zmm17
    vpaddq  zmm1, zmm1, zmm2
    vmovdqa64 zmm2, zmm18
    vpermi2q zmm2, zmm0, zmm1
    vpermt2q zmm0, zmm19, zmm1
    vpsllq  zmm0, zmm0, 28
    vpaddq  zmm2, zmm2, zmm0
    vmovdqa64 [rbx], zmm2

    // pairs to bytes by the chain: seven a pair, what a pair has above them goes to the next.
    // It takes the pairs of the last step, after the carry of the pair below them, or, where a
    // sum above outgrew its seven bytes, all of them.
    mov  rcx, [rsp + 168]
    mov  rdx, [rsp + 160]
    lea  r8,  [rdx + 8*rcx - 8]         // the last place a whole word may be stored
    vpsrlq  zmm0, zmm22, 56
    vptestmq k1, zmm0, zmm0
    kortestw k1, k1
    jnz  .Lvmb_fin_all
    shl  r12, 6                         // rdi is 56 bytes a step on; the pairs are 64
    lea  rsi, [rsp + r12 + 13440]
    mov  rax, [rsi - 8]
    shr  rax, 56
    jmp  .Lvmb_fin_pair
.Lvmb_fin_all:
    mov  rdi, rdx
    lea  rsi, [rsp + 13440]
    xor  eax, eax
.p2align 4
.Lvmb_fin_pair:
    add  rax, [rsi]
    mov  [rdi], rax                     // the eighth byte is written again by the next pair
    shr  rax, 56
    add  rsi, 8
    add  rdi, 7
    cmp  rdi, r8
    jbe  .Lvmb_fin_pair
    add  rax, [rsi]                     // the last one to seven bytes
    lea  rcx, [r8 + 8]
    sub  rcx, rdi
    mov  edx, -1
    bzhi edx, edx, ecx
    kmovw k1, edx
    vmovq xmm0, rax
    vmovdqu8 xmmword ptr [rdi]{k1}, xmm0

.if SUPI_OS == 1
    cmp  qword ptr [rsp + 184], 256
    jae  1f
    vmovups xmm12, xmmword ptr [rsp + 96]
    vmovups xmm13, xmmword ptr [rsp + 112]
    vmovups xmm14, xmmword ptr [rsp + 128]
    vmovups xmm15, xmmword ptr [rsp + 144]
1:
.endif
    vzeroupper
    lea  rsp, [rbp - 40]
    pop  r15
    pop  r14
    pop  r13
    pop  r12
    pop  rbx
    pop  rbp
    ret

// Add src[0..rcx] (rsi) into dst[0..] (rdi) and ripple any carry.
.p2align 4
.Lblk_add_into_dst:
    xor  eax, eax
.Lblk_add_lp:
    mov  r8, [rsi]
    adcx r8, [rdi]
    mov  [rdi], r8
    lea  rsi, [rsi + 8]
    lea  rdi, [rdi + 8]
    dec  rcx
    jnz  .Lblk_add_lp
    jnc  .Lblk_add_ret
.Lblk_add_ripple:
    add  qword ptr [rdi], 1
    lea  rdi, [rdi + 8]
    jc   .Lblk_add_ripple
.Lblk_add_ret:
    ret

// Accumulate long[0..r8] (rsi) * short[0..rcx] (rdx) into dst[0..] (rdi) with carry ripple.
.p2align 4
.Lblk_acc_scalar:
    push rbx
    push r12
    push r13
    push r14
    push r15
    mov  r12, rsi                       // long_ptr
    mov  r13, rdx                       // short_ptr
    mov  r14, rdi                       // dst_row_ptr
    mov  r15, rcx                       // n_short
.Lblk_sc_row:
    mov  rdx, [r13]                     // m = short[j]
    mov  rsi, r12
    mov  rdi, r14
    mov  rcx, r8                        // n_long
    xor  eax, eax                       // prev_carry = 0
.Lblk_sc_limb:
    xor  ebx, ebx
    mulx r10, r9, [rsi]
    adcx r9,  rax
    adox r9,  [rdi]
    mov  [rdi], r9
    adcx r10, rbx
    adox r10, rbx
    mov  rax, r10
    lea  rsi, [rsi + 8]
    lea  rdi, [rdi + 8]
    dec  rcx
    jnz  .Lblk_sc_limb
    add  [rdi], rax
    jnc  .Lblk_sc_next_row
.Lblk_sc_ripple:
    lea  rdi, [rdi + 8]
    add  qword ptr [rdi], 1
    jc   .Lblk_sc_ripple
.Lblk_sc_next_row:
    lea  r13, [r13 + 8]
    lea  r14, [r14 + 8]
    dec  r15
    jnz  .Lblk_sc_row
    pop  r15
    pop  r14
    pop  r13
    pop  r12
    pop  rbx
    ret

