// [5] sqr_base(dst: rdi, a: rsi, n: rdx, rows_max: rcx)
LOCAL_FN supi_k_sqr_base
    LIMB_ENTER_FAST
    test rdx, rdx
    jz   .Lmb_small_ret
    cmp  rdx, 8
    ja   .Lsqr_gt8
    mov  rax, rcx
    mov  r8,  rdx
    mov  rcx, rdx
    mov  rdx, rsi
    jmp  .Lmulbase_ordered
.Lsqr_gt8:
    cmp  rdx, rcx
    jbe  .Lsqr_scalar_tri
    cmp  rdx, 64
    ja   .Lsqr_tiled_vmb
    mov  rax, rcx
    mov  r8,  rdx
    mov  rcx, rdx
    mov  rdx, rsi
    jmp  .Lvmb

.Lsqr_tiled_vmb:
    push rbp
    mov  rbp, rsp
    push rbx
    push r12
    push r13
    push r14
    push r15
    sub  rsp, 1664
    and  rsp, -64
    mov  qword ptr [rsp], 0
    mov  [rsp + 1536], rdi              // dst
    mov  [rsp + 1544], rsi              // a
    mov  [rsp + 1552], rdx              // n
    mov  [rsp + 1560], rcx              // rows_max

    lea  rcx, [rdx + rdx]
    mov  r9,  rdi
    xor  eax, eax
.Lsqr_tiled_zero:
    mov  [r9], rax
    lea  r9, [r9 + 8]
    dec  rcx
    jnz  .Lsqr_tiled_zero

    // 1. Symmetric upper-triangle off-diagonal blocks (64 x <=128 via .Lvmb_core):
    xor  eax, eax
    mov  [rsp + 1568], rax              // ik = 0
.Lsqr_tiled_ik_chk:
    mov  rax, [rsp + 1568]              // ik
    lea  rbx, [rax + 64]                // ik + 64
    cmp  rbx, [rsp + 1552]
    jae  .Lsqr_tiled_double
    mov  [rsp + 1584], rbx              // ja = ik + 64

.Lsqr_tiled_ja_loop:
    mov  rbx, [rsp + 1584]              // ja
    mov  r8,  [rsp + 1552]              // n
    sub  r8,  rbx                       // n - ja
    mov  edx, 128
    cmp  r8,  128
    cmova r8, rdx                       // lj = min(128, n - ja)
    mov  [rsp + 1592], r8

    mov  rsi, [rsp + 1544]
    mov  rax, [rsp + 1568]              // ik
    lea  rdx, [rsi + 8*rax]             // &a[ik] (64 limbs)
    lea  rsi, [rsi + 8*rbx]             // &a[ja] (lj limbs)
    mov  ecx, 64

    cmp  r8,  rcx
    jae  .Lsqr_tiled_ord
    xchg r8,  rcx
    xchg rsi, rdx
.Lsqr_tiled_ord:
    cmp  rcx, [rsp + 1560]
    jbe  .Lsqr_tiled_off_sc

    mov  rdi, rsp
    call .Lvmb_core
    mov  rax, [rsp + 1568]
    add  rax, [rsp + 1584]              // ik + ja
    mov  rdi, [rsp + 1536]
    lea  rdi, [rdi + 8*rax]
    mov  rsi, rsp
    mov  rcx, [rsp + 1592]
    add  rcx, 64
    call .Lblk_add_into_dst
    jmp  .Lsqr_tiled_ja_next

.Lsqr_tiled_off_sc:
    mov  rax, [rsp + 1568]
    add  rax, [rsp + 1584]
    mov  rdi, [rsp + 1536]
    lea  rdi, [rdi + 8*rax]
    call .Lblk_acc_scalar

.Lsqr_tiled_ja_next:
    mov  rbx, [rsp + 1584]
    add  rbx, 128
    cmp  rbx, [rsp + 1552]
    jae  .Lsqr_tiled_ik_next
    mov  [rsp + 1584], rbx
    jmp  .Lsqr_tiled_ja_loop

.Lsqr_tiled_ik_next:
    mov  rax, [rsp + 1568]
    add  rax, 64
    mov  [rsp + 1568], rax
    jmp  .Lsqr_tiled_ik_chk

    // 2. Shift dst[0 .. 2*n] left by 1 bit:
.Lsqr_tiled_double:
    mov  rdi, [rsp + 1536]
    mov  rcx, [rsp + 1552]
    add  rcx, rcx
    xor  eax, eax
.Lsqr_tiled_shl1:
    mov  r8, [rdi]
    adcx r8, r8
    mov  [rdi], r8
    lea  rdi, [rdi + 8]
    dec  rcx
    jnz  .Lsqr_tiled_shl1

    // 3. Add diagonal block squares A_k^2 into dst[2*ik ..]:
    xor  eax, eax
    mov  [rsp + 1568], rax              // ik = 0
.Lsqr_tiled_diag_loop:
    mov  rax, [rsp + 1568]              // ik
    mov  r8,  [rsp + 1552]              // n
    sub  r8,  rax                       // n - ik
    mov  edx, 64
    cmp  r8,  64
    cmova r8, rdx                       // lk = min(64, n - ik)
    mov  [rsp + 1576], r8

    mov  rsi, [rsp + 1544]
    lea  rsi, [rsi + 8*rax]             // &a[ik]
    mov  rdx, rsi
    mov  rcx, r8

    cmp  rcx, [rsp + 1560]
    jbe  .Lsqr_tiled_diag_sc
    cmp  r8,  9
    jb   .Lsqr_tiled_diag_sc

    mov  rdi, rsp
    call .Lvmb_core
    mov  rax, [rsp + 1568]
    add  rax, rax                       // 2 * ik
    mov  rdi, [rsp + 1536]
    lea  rdi, [rdi + 8*rax]
    mov  rsi, rsp
    mov  rcx, [rsp + 1576]
    add  rcx, rcx                       // 2 * lk
    call .Lblk_add_into_dst
    jmp  .Lsqr_tiled_diag_next

.Lsqr_tiled_diag_sc:
    mov  rax, [rsp + 1568]
    add  rax, rax
    mov  rdi, [rsp + 1536]
    lea  rdi, [rdi + 8*rax]
    call .Lblk_acc_scalar

.Lsqr_tiled_diag_next:
    mov  rax, [rsp + 1568]
    add  rax, 64
    cmp  rax, [rsp + 1552]
    jae  .Lsqr_tiled_done
    mov  [rsp + 1568], rax
    jmp  .Lsqr_tiled_diag_loop

.Lsqr_tiled_done:
    lea  rsp, [rbp - 40]
    pop  r15
    pop  r14
    pop  r13
    pop  r12
    pop  rbx
    pop  rbp
    jmp  .Lmb_small_ret

.Lsqr_scalar_tri:
    push rbp
    mov  rbp, rsp
    push rbx
    push r12
    push r13
    push r14
    push r15
    sub  rsp, 64
    mov  [rsp + 0],  rdi                // base dst
    mov  [rsp + 8],  rsi                // base a
    mov  [rsp + 16], rdx                // n

    // Zero dst[0 .. 2*n] with GPR stores (no vector instructions in Family 1)
    lea  rcx, [rdx + rdx]
    mov  r8,  rdi
    xor  eax, eax
.Lsqr_zero:
    mov  [r8], rax
    lea  r8, [r8 + 8]
    dec  rcx
    jnz  .Lsqr_zero

    // Off-diagonal triangle: for i = 0 .. n - 2:
    //   addmul_1(&dst[2*i + 1], &a[i + 1], n - 1 - i, a[i]) -> dst[i + n]
    xor  rcx, rcx                       // i = 0
.Lsqr_tri_check:
    mov  r9,  [rsp + 16]                // n
    dec  r9                             // n - 1
    cmp  rcx, r9
    jae  .Lsqr_double
    mov  [rsp + 24], rcx                // save i

    mov  r8,  r9
    sub  r8,  rcx                       // len = (n - 1) - i
    mov  rbx, [rsp + 8]                 // base a
    mov  rdx, [rbx + 8*rcx]             // m = a[i]
    lea  rsi, [rbx + 8*rcx + 8]         // &a[i + 1]
    mov  rdi, [rsp + 0]                 // base dst
    lea  rax, [rcx + rcx + 1]
    lea  rdi, [rdi + 8*rax]             // &dst[2*i + 1]
    xor  eax, eax
    cmp  r8,  4
    jb   .Lsqr_tri_tail

.p2align 4
.Lsqr_tri_loop4:
    xor  ebx, ebx
    mulx r10, r9,  [rsi + 0]
    adcx r9,  rax
    adox r9,  [rdi + 0]
    mov  [rdi + 0], r9

    mulx r12, r11, [rsi + 8]
    adcx r11, r10
    adox r11, [rdi + 8]
    mov  [rdi + 8], r11

    mulx r14, r13, [rsi + 16]
    adcx r13, r12
    adox r13, [rdi + 16]
    mov  [rdi + 16], r13

    mulx rax, r15, [rsi + 24]
    adcx r15, r14
    adox r15, [rdi + 24]
    mov  [rdi + 24], r15

    adcx rax, rbx
    adox rax, rbx

    lea  rsi, [rsi + 32]
    lea  rdi, [rdi + 32]
    sub  r8,  4
    cmp  r8,  4
    jae  .Lsqr_tri_loop4

.Lsqr_tri_tail:
    test r8,  r8
    jz   .Lsqr_tri_store_c
.Lsqr_tri_loop1:
    xor  ebx, ebx
    mulx r10, r9, [rsi]
    adcx r9,  rax
    adox r9,  [rdi]
    mov  [rdi], r9
    adcx r10, rbx
    adox r10, rbx
    mov  rax, r10
    lea  rsi, [rsi + 8]
    lea  rdi, [rdi + 8]
    dec  r8
    jnz  .Lsqr_tri_loop1

.Lsqr_tri_store_c:
    mov  [rdi], rax                     // dst[i + n] = carry
    mov  rcx, [rsp + 24]
    inc  rcx
    jmp  .Lsqr_tri_check

.Lsqr_double:
    // Shift dst[0 .. 2*n] left by 1 bit using unbroken ADCX chain (DEC preserves CF)
    mov  rdi, [rsp + 0]
    mov  rcx, [rsp + 16]
    add  rcx, rcx                       // 2 * n
    xor  eax, eax                       // CF = 0
.Lsqr_shl1:
    mov  r8, [rdi]
    adcx r8, r8
    mov  [rdi], r8
    lea  rdi, [rdi + 8]
    dec  rcx
    jnz  .Lsqr_shl1

    // Add diagonal squares a[i]^2 into dst[2*i .. 2*i + 2] on unbroken ADCX chain
    mov  rdi, [rsp + 0]
    mov  rsi, [rsp + 8]
    mov  rcx, [rsp + 16]                // n
    xor  eax, eax                       // CF = 0
.Lsqr_diag:
    mov  rdx, [rsi]
    mulx r9,  r8, rdx
    adcx r8,  [rdi + 0]
    adcx r9,  [rdi + 8]
    mov  [rdi + 0], r8
    mov  [rdi + 8], r9
    lea  rsi, [rsi + 8]
    lea  rdi, [rdi + 16]
    dec  rcx
    jnz  .Lsqr_diag

.Lsqr_done:
    lea  rsp, [rbp - 40]
    pop  r15
    pop  r14
    pop  r13
    pop  r12
    pop  rbx
    pop  rbp
    jmp  .Lmb_small_ret


// ============================================================================
// 4. Family 2 — FFT Kernels (6): 4 complex f64 per ZMM, FMA throughout
// ============================================================================

// [6] fft_split(out_complex: rdi, limbs: rsi, weights: rdx, cfg: rcx)
// FftSplitCfg: in_limbs@0, n_complex@8, coeff_bits@16
LOCAL_FN supi_k_fft_split
    VEC_ENTER_FAST
    sub  rsp, 64
    and  rsp, -64
    mov  r8,  [rcx + 0]                 // in_limbs
    mov  r9,  [rcx + 8]                 // n_complex
    mov  r10, [rcx + 16]                // coeff_bits (b)

    test r9,  r9
    jz   .Lfftsplit_done

    // Save parameters for weight pass
    mov  r12, rdi                       // out_complex
    mov  r13, rdx                       // weights
    mov  r14, r9                        // n_complex

    // Single-pass fused balanced-split + weight fast path when all imaginary digits are 0:
    //   2 <= b <= 56, (n_complex & 7) == 0, n_complex >= 16, total_in_bits >= 512,
    //   and total_in_bits <= (n_complex - 1) * b (guarantees k_end <= n_complex)!
    mov  r15, r8
    shl  r15, 6                         // total_in_bits = in_limbs * 64
    lea  rax, [r10 - 2]
    cmp  rax, 54
    ja   .Lfftsplit_gen_entry
    test r14, 7
    jnz  .Lfftsplit_gen_entry
    cmp  r14, 16
    jb   .Lfftsplit_gen_entry
    lea  rax, [r14 - 1]
    imul rax, r10
    mov  rcx, r8
.Lfftsplit_trim_top:
    test rcx, rcx
    jz   .Lfftsplit_exact_zero
    mov  rdx, [rsi + 8*rcx - 8]
    test rdx, rdx
    jnz  .Lfftsplit_got_top
    dec  rcx
    jmp  .Lfftsplit_trim_top
.Lfftsplit_exact_zero:
    xor  edx, edx
    jmp  .Lfftsplit_cmp_exact
.Lfftsplit_got_top:
    lzcnt rdx, rdx
    shl  rcx, 6
    sub  rcx, rdx
    mov  rdx, rcx
.Lfftsplit_cmp_exact:
    cmp  rdx, rax
    ja   .Lfftsplit_f2p_entry

    mov  eax, 1
    shlx r11, rax, r10                  // base = 1 << b
    lea  rcx, [r10 - 1]
    shlx rbx, rax, rcx                  // half = 1 << (b - 1)
    lea  rax, [r14 - 8]
    mov  [rsp + 24], rax                // max_vec_k = n_complex - 8

    vpxorq       zmm31, zmm31, zmm31    // +0.0
    vmovdqa64    zmm20, [rip + .Lconst_idx_even]
    vpsrlq       zmm20, zmm20, 1
    vpbroadcastq zmm21, r10
    vpmullq      zmm20, zmm20, zmm21    // [0, b, 2b, 3b, 4b, 5b, 6b, 7b]
    mov          eax, 63
    vpbroadcastq zmm22, rax             // 63
    lea          rax, [r11 - 1]
    vpbroadcastq zmm23, rax             // bmask = (1 << b) - 1
    vpbroadcastq zmm24, rbx             // half  = 1 << (b - 1)
    lea          rax, [rbx - 1]
    vpbroadcastq zmm25, rax             // half - 1
    vpbroadcastq zmm26, r11             // base  = 1 << b
    mov          eax, 1
    vpbroadcastq zmm27, rax             // 1
    vmovdqa64    zmm28, [rip + .Lconst_idx_00112233]
    mov          eax, 4
    vpbroadcastq zmm29, rax
    vpaddq       zmm29, zmm28, zmm29    // [4, 4, 5, 5, 6, 6, 7, 7]
    vpsrlq       zmm21, zmm20, 6        // word_idx0 = [0, b, ..., 7b] >> 6
    vpaddq       zmm30, zmm21, zmm27    // word_idx1 = word_idx0 + 1
    vpandq       zmm19, zmm20, zmm22    // sh_r      = [0, b, ..., 7b] & 63
    vpxorq       zmm18, zmm19, zmm22    // sh_l      = 63 ^ sh_r

    xor  edx, edx                       // borrow_carry = 0
    xor  r9d, r9d                       // bit_pos = 0
    xor  ecx, ecx                       // k = 0
    test r8,  r8
    jz   .Lfftsplit_f1p_zero_rem
    cmp  qword ptr [rsi], 0
    jne  .Lfftsplit_f1p_after_zskip
    xor  eax, eax
.Lfftsplit_f1p_zscan:
    inc  rax
    cmp  rax, r8
    jae  .Lfftsplit_f1p_zero_rem
    cmp  qword ptr [rsi + 8*rax], 0
    je   .Lfftsplit_f1p_zscan
    shl  rax, 6                         // z_bits = z_words * 64
    xor  edx, edx
    div  r10                            // q = z_bits / b
    and  rax, -8                        // k_zero = q & !7
    jz   .Lfftsplit_f1p_zskip_done
    cmp  rax, r14
    cmova rax, r14
    mov  rcx, rax
    mov  rdi, r12
.Lfftsplit_f1p_zlead:
    vmovupd [rdi + 0],  zmm31
    vmovupd [rdi + 64], zmm31
    add  rdi, 128
    sub  rax, 8
    jnz  .Lfftsplit_f1p_zlead
    mov  r9, rcx
    imul r9, r10                        // bit_pos = k_zero * b ((r9 & 7) == 0)
.Lfftsplit_f1p_zskip_done:
    xor  edx, edx                       // borrow_carry = 0
.Lfftsplit_f1p_after_zskip:
    cmp  r15, 512
    jb   .Lfftsplit_f1p_tail_vec8
    lea  rdi, [r15 - 512]
    mov  [rsp + 16], rdi                // max_vec_bp = total_in_bits - 512

.p2align 4
.Lfftsplit_f1p_vec8:
    cmp          r9,  [rsp + 16]
    ja           .Lfftsplit_f1p_tail_vec8
    cmp          rcx, [rsp + 24]
    ja           .Lfftsplit_f1p_tail_vec8

    mov          rdi, r9
    shr          rdi, 3
    vmovdqu64    zmm3, [rsi + rdi]
    vpermq       zmm0, zmm21, zmm3
    vpermq       zmm1, zmm30, zmm3
    vpsrlvq      zmm0, zmm0,  zmm19
    vpsllq       zmm1, zmm1,  1
    vpsllvq      zmm1, zmm1,  zmm18
    vporq        zmm0, zmm0,  zmm1
    vpandq       zmm0, zmm0,  zmm23

    vpcmpuq      k1, zmm0, zmm24, 5
    vpcmpeqq     k2, zmm0, zmm25
    kmovw        eax, k1
    kmovw        edi, k2
    lea          eax, [rdx + 2*rax]
    add          eax, edi
    mov          edx, eax
    shr          edx, 8
    xor          eax, edi
    movzx        eax, al
    kmovw        k3, eax
    vpaddq       zmm0 {k3}, zmm0, zmm27
    vpcmpuq      k4, zmm0, zmm24, 5
    vpsubq       zmm0 {k4}, zmm0, zmm26
    vcvtqq2pd    zmm0, zmm0

    vpermq       zmm1, zmm28, zmm0
    vpermq       zmm2, zmm29, zmm0
    mov          rdi, rcx
    shl          rdi, 4
    vmulpd       zmm1, zmm1, [r13 + rdi + 0]
    vmulpd       zmm2, zmm2, [r13 + rdi + 64]
    vaddpd       zmm1, zmm1, zmm31
    vaddpd       zmm2, zmm2, zmm31
    vmovupd      [r12 + rdi + 0],  zmm1
    vmovupd      [r12 + rdi + 64], zmm2
    lea          r9,  [r9 + 8*r10]
    add          rcx, 8
    jmp          .Lfftsplit_f1p_vec8

.p2align 4
.Lfftsplit_f1p_tail_vec8:
    // Qword-masked 8-digit AVX-512 tail for the final <= 512 bits (zero branch mispredicts,
    // zero out-of-bounds loads; n_complex is a multiple of 8 so rcx steps cleanly to r14).
    cmp          rcx, r14
    jae          .Lfftsplit_done
    cmp          r9,  r15
    jb           .Lfftsplit_f1p_tv_inb
    test         edx, edx
    jz           .Lfftsplit_f1p_zero_rem
    vpxorq       zmm3, zmm3, zmm3
    xor          eax, eax
    jmp          .Lfftsplit_f1p_tv_bal
.Lfftsplit_f1p_tv_inb:
    mov          rdi, r9
    shr          rdi, 6
    mov          rax, r8
    sub          rax, rdi
    mov          edi, 0xFF
    bzhi         eax, edi, eax
    kmovw        k1, eax
    mov          rdi, r9
    shr          rdi, 6
    vmovdqu64    zmm3 {k1}{z}, [rsi + 8*rdi]
    mov          eax, r9d
    and          eax, 63
.Lfftsplit_f1p_tv_bal:
    vpbroadcastq zmm16, rax
    vpaddq       zmm16, zmm16, zmm20
    vpsrlq       zmm17, zmm16, 6
    vpaddq       zmm18, zmm17, zmm27
    vpermq       zmm0,  zmm17, zmm3
    vpermq       zmm1,  zmm18, zmm3
    vpandq       zmm16, zmm16, zmm22
    vpsrlvq      zmm0,  zmm0,  zmm16
    vpxorq       zmm19, zmm16, zmm22
    vpsllq       zmm1,  zmm1,  1
    vpsllvq      zmm1,  zmm1,  zmm19
    vporq        zmm0,  zmm0,  zmm1
    vpandq       zmm0,  zmm0,  zmm23

    vpcmpuq      k1, zmm0, zmm24, 5
    vpcmpeqq     k2, zmm0, zmm25
    kmovw        eax, k1
    kmovw        edi, k2
    lea          eax, [rdx + 2*rax]
    add          eax, edi
    mov          edx, eax
    shr          edx, 8
    xor          eax, edi
    movzx        eax, al
    kmovw        k3, eax
    vpaddq       zmm0 {k3}, zmm0, zmm27
    vpcmpuq      k4, zmm0, zmm24, 5
    vpsubq       zmm0 {k4}, zmm0, zmm26
    vcvtqq2pd    zmm0, zmm0

    vpermq       zmm1, zmm28, zmm0
    vpermq       zmm2, zmm29, zmm0
    mov          rdi, rcx
    shl          rdi, 4
    vmulpd       zmm1, zmm1, [r13 + rdi + 0]
    vmulpd       zmm2, zmm2, [r13 + rdi + 64]
    vaddpd       zmm1, zmm1, zmm31
    vaddpd       zmm2, zmm2, zmm31
    vmovupd      [r12 + rdi + 0],  zmm1
    vmovupd      [r12 + rdi + 64], zmm2
    lea          r9,  [r9 + 8*r10]
    add          rcx, 8
    jmp          .Lfftsplit_f1p_tail_vec8

.Lfftsplit_f1p_zero_rem:
    mov  rax, rcx
    shl  rax, 4
    add  rax, r12
    mov  rdx, r14
    sub  rdx, rcx
    jz   .Lfftsplit_done
    cmp  rdx, 4
    jb   .Lfftsplit_f1p_z1
.p2align 4
.Lfftsplit_f1p_z4:
    vmovupd [rax], zmm31
    lea  rax, [rax + 64]
    sub  rdx, 4
    cmp  rdx, 4
    jae  .Lfftsplit_f1p_z4
.Lfftsplit_f1p_z1:
    test rdx, rdx
    jz   .Lfftsplit_done
.Lfftsplit_f1p_z1_loop:
    vmovupd [rax], xmm31
    lea  rax, [rax + 16]
    dec  rdx
    jnz  .Lfftsplit_f1p_z1_loop
    jmp  .Lfftsplit_done

    // Two-half AVX-512 split + fused weight pass when 2 <= b <= 56, (n_complex & 7) == 0,
    // n_complex >= 16, and exact_in_bits > (n_complex - 1) * b:
    //   Computes j_im_zero = min(n_complex, (((max(0, exact_in_bits - n_complex*b)) / b) + 9) & !7).
    //   Pass 1 (pure 8-lane AVX-512): stores unweighted [xr_j, xr_j] only for j < j_im_zero,
    //           and fuses final [xr_j*wr, xr_j*wi] directly in Pass 1 for all j >= j_im_zero!
    //   Pass 2 (pure 8-lane AVX-512): extracts xi_j and fuses [xr_j*wr - xi_j*wi, xr_j*wi + xi_j*wr]
    //           strictly for j < j_im_zero (zero scalar tails, zero second pass over j >= j_im_zero!).
.p2align 4
.Lfftsplit_f2p_entry:
    mov  rax, r14
    imul rax, r10                       // n_complex * b
    cmp  rdx, rax
    ja   .Lfftsplit_f2p_calc_j
    mov  eax, 8                         // im_bits == 0 -> only j == 0 can take carry, so j_im_zero = 8
    jmp  .Lfftsplit_f2p_got_j
.Lfftsplit_f2p_calc_j:
    mov  rax, rdx
    mov  rcx, r14
    imul rcx, r10
    sub  rax, rcx                       // im_bits = exact_in_bits - n_complex * b
    xor  edx, edx
    div  r10                            // q = im_bits / b
    lea  rax, [rax + 9]                 // q + 2 rounded up to multiple of 8
    and  rax, -8
    cmp  rax, r14
    cmova rax, r14                      // j_im_zero = min(n_complex, (q + 9) & !7)
.Lfftsplit_f2p_got_j:
    mov  [rsp + 32], rax                // j_im_zero

    mov  eax, 1
    shlx r11, rax, r10                  // base = 1 << b
    lea  rcx, [r10 - 1]
    shlx rbx, rax, rcx                  // half = 1 << (b - 1)
    lea  rax, [r14 - 8]
    mov  [rsp + 24], rax                // last_vec_k = n_complex - 8

    vpxorq       zmm31, zmm31, zmm31    // +0.0
    vmovdqa64    zmm20, [rip + .Lconst_idx_even]
    vpsrlq       zmm20, zmm20, 1
    vpbroadcastq zmm21, r10
    vpmullq      zmm20, zmm20, zmm21    // [0, b, 2b, 3b, 4b, 5b, 6b, 7b]
    mov          eax, 63
    vpbroadcastq zmm22, rax             // 63
    lea          rax, [r11 - 1]
    vpbroadcastq zmm23, rax             // bmask = (1 << b) - 1
    vpbroadcastq zmm24, rbx             // half  = 1 << (b - 1)
    lea          rax, [rbx - 1]
    vpbroadcastq zmm25, rax             // half - 1
    vpbroadcastq zmm26, r11             // base  = 1 << b
    mov          eax, 1
    vpbroadcastq zmm27, rax             // 1
    vmovdqa64    zmm28, [rip + .Lconst_idx_00112233]
    mov          eax, 4
    vpbroadcastq zmm29, rax
    vpaddq       zmm29, zmm28, zmm29    // [4, 4, 5, 5, 6, 6, 7, 7]
    vpsrlq       zmm21, zmm20, 6        // word_idx0 = [0, b, ..., 7b] >> 6
    vpaddq       zmm30, zmm21, zmm27    // word_idx1 = word_idx0 + 1
    vpandq       zmm19, zmm20, zmm22    // sh_r      = [0, b, ..., 7b] & 63
    vpxorq       zmm18, zmm19, zmm22    // sh_l      = 63 ^ sh_r

    xor  edx, edx                       // borrow_carry = 0
    xor  r9d, r9d                       // bit_pos = 0
    xor  ecx, ecx                       // k = 0
    cmp  qword ptr [rsi], 0
    jne  .Lfftsplit_f2p_re_after_zskip
    xor  eax, eax
.Lfftsplit_f2p_re_zscan:
    inc  rax
    cmp  rax, r8
    jae  .Lfftsplit_f2p_re_after_zskip
    cmp  qword ptr [rsi + 8*rax], 0
    je   .Lfftsplit_f2p_re_zscan
    shl  rax, 6
    xor  edx, edx
    div  r10
    and  rax, -8
