    xor  edx, edx                       // next borrow_carry = 0
    lea  rdi, [rcx + 1]
    cmp  rdi, [rsp + 0]                 // k + 1 < m_digits ?
    jae  .Lfftsplit_store_dig
    mov  rdi, rax
    sub  rdi, r11
    cmp  rax, rbx                       // v >= half ?
    cmovge rax, rdi
    setge dl

.Lfftsplit_store_dig:
    vcvtsi2sd xmm0, xmm0, rax
    cmp  rcx, r14                       // k < n_complex ?
    jae  .Lfftsplit_store_im
    mov  rdi, rcx
    shl  rdi, 4
    vmovsd [r12 + rdi], xmm0
    jmp  .Lfftsplit_next_k
.Lfftsplit_store_im:
    mov  rdi, rcx
    sub  rdi, r14
    shl  rdi, 4
    vmovsd [r12 + rdi + 8], xmm0

.Lfftsplit_next_k:
    add  r9,  r10                       // bit_pos += b
    inc  rcx
    cmp  rcx, [rsp + 0]
    jb   .Lfftsplit_digit_loop

.Lfftsplit_digits_done:
    // Multiply only nonzero prefix [0 .. min(k_end, n_complex)) by weights 8 complex per iter!
    mov  rdi, r12                       // out_complex
    mov  rdx, r13                       // weights
    cmp  rcx, r14
    cmova rcx, r14                      // w_count = min(k_end, n_complex)
    cmp  rcx, 8
    jb   .Lfftsplit_w_check4

.p2align 4
.Lfftsplit_w_loop8:
    vmovupd  zmm0,  [rdi + 0]
    vmovupd  zmm1,  [rdx + 0]
    vmovupd  zmm5,  [rdi + 64]
    vmovupd  zmm16, [rdx + 64]
    vmovddup zmm2,  zmm1
    vshufpd  zmm3,  zmm1,  zmm1,  0xFF
    vshufpd  zmm4,  zmm0,  zmm0,  0x55
    vmovddup zmm17, zmm16
    vshufpd  zmm18, zmm16, zmm16, 0xFF
    vshufpd  zmm19, zmm5,  zmm5,  0x55
    vmulpd   zmm4,  zmm4,  zmm3
    vmulpd   zmm19, zmm19, zmm18
    vfmaddsub213pd zmm0, zmm2,  zmm4
    vfmaddsub213pd zmm5, zmm17, zmm19
    vmovupd  [rdi + 0],  zmm0
    vmovupd  [rdi + 64], zmm5
    lea  rdi, [rdi + 128]
    lea  rdx, [rdx + 128]
    sub  rcx, 8
    cmp  rcx, 8
    jae  .Lfftsplit_w_loop8

.Lfftsplit_w_check4:
    cmp  rcx, 4
    jb   .Lfftsplit_w_tail

.p2align 4
.Lfftsplit_w_loop4:
    vmovupd  zmm0, [rdi]
    vmovupd  zmm1, [rdx]
    vmovddup zmm2, zmm1                 // wr duplicated
    vshufpd  zmm3, zmm1, zmm1, 0xFF     // wi duplicated
    vshufpd  zmm4, zmm0, zmm0, 0x55     // [xi, xr]
    vmulpd   zmm4, zmm4, zmm3           // [xi*wi, xr*wi]
    vfmaddsub213pd zmm0, zmm2, zmm4     // [xr*wr - xi*wi, xi*wr + xr*wi]
    vmovupd  [rdi], zmm0
    lea  rdi, [rdi + 64]
    lea  rdx, [rdx + 64]
    sub  rcx, 4
    cmp  rcx, 4
    jae  .Lfftsplit_w_loop4

.Lfftsplit_w_tail:
    test rcx, rcx
    jz   .Lfftsplit_done
.Lfftsplit_w_loop1:
    vmovsd   xmm0, [rdi + 0]            // xr
    vmovsd   xmm1, [rdi + 8]            // xi
    vmovsd   xmm2, [rdx + 0]            // wr
    vmovsd   xmm3, [rdx + 8]            // wi
    vmulsd   xmm4, xmm1, xmm3           // xi * wi
    vfmsub231sd xmm4, xmm0, xmm2        // xr * wr - xi * wi
    vmulsd   xmm5, xmm1, xmm2           // xi * wr
    vfmadd231sd xmm5, xmm0, xmm3        // xr * wi + xi * wr
    vmovsd   [rdi + 0], xmm4
    vmovsd   [rdi + 8], xmm5
    lea  rdi, [rdi + 16]
    lea  rdx, [rdx + 16]
    dec  rcx
    jnz  .Lfftsplit_w_loop1

.Lfftsplit_done:
    VEC_LEAVE_FAST

// [7] fft_fwd(buf: rdi, twiddles: rsi, n_complex: rdx, l1_sub_n: rcx)
LOCAL_FN supi_k_fft_fwd
    VEC_ENTER_FFT64
    cmp  rdx, 1
    jbe  .Lfftfwd_done
    cmp  rdx, 2
    je   .Lfftfwd_n2

    mov  [rsp + 0], rdi                 // orig_buf
    mov  [rsp + 8], rdx                 // orig_n
    cmp  rcx, rdx
    jae  .Lfftfwd_sub_single
    mov  eax, 64
    cmp  rcx, 64
    cmovb rcx, rax
    lzcnt rax, rcx
    mov  ecx, 63
    sub  ecx, eax
    mov  eax, 1
    shl  rax, cl                        // sub_cap = largest power of two >= 64 and <= l1_sub_n
    cmp  rdx, rax
    jbe  .Lfftfwd_sub_single
    cmp  ecx, 10
    jne  .Lfftfwd_keep_sub_cap
    tzcnt r8, rdx
    test r8d, 1
    jz   .Lfftfwd_keep_sub_cap
    dec  ecx
    shr  rax, 1                         // sub_cap = 512 (2 L1 passes + pure R4 top passes for odd log2(n)!)
.Lfftfwd_keep_sub_cap:
    mov  [rsp + 40], rax                // sub_cap

    // Top stages above sub_cap before decomposing into L1-sized sub_cap complex sub-FFTs:
    mov  r8,  1                         // b_blocks = 1
    mov  r9,  rdx
    shr  r9,  1                         // m = orig_n >> 1

.Lfftfwd_top_r4_check:
    mov  rax, [rsp + 40]
    add  rax, rax                       // 2 * sub_cap
    cmp  r9,  rax
    jb   .Lfftfwd_top_r2_check

    mov  r15, r9
    shr  r15, 1                         // mh = m / 2 (>= 1024, multiple of 8)
    mov  r11, r15
    shl  r11, 4                         // mh_bytes = mh * 16
    xor  r10d, r10d                     // j = 0

.Lfftfwd_top_r4_block:
    mov  rcx, r10
    imul rcx, r11
    shl  rcx, 2
    lea  r12, [rdi + rcx]
    lea  r13, [r12 + r11]
    lea  rcx, [r13 + r11]
    lea  rax, [rcx + r11]
    mov  r14, r15

    lea  rdx, [r8 + r10]
    cmp  rdx, 1
    je   .Lfftfwd_top_r4_j0_entry

    shl  rdx, 4
    vbroadcastsd zmm16, [rsi + rdx + 0]
    vbroadcastsd zmm17, [rsi + rdx + 8]
    add  rdx, rdx
    vbroadcastsd zmm18, [rsi + rdx + 0]
    vbroadcastsd zmm19, [rsi + rdx + 8]
    vbroadcastsd zmm20, [rsi + rdx + 16]
    vbroadcastsd zmm21, [rsi + rdx + 24]

.p2align 4
.Lfftfwd_top_r4_loop8:
    vmovupd  zmm0, [r12 + 0]
    vmovupd  zmm1, [r13 + 0]
    vmovupd  zmm2, [rcx + 0]
    vmovupd  zmm3, [rax + 0]
    vmovupd  zmm6, [r12 + 64]
    vmovupd  zmm7, [r13 + 64]
    vmovupd  zmm8, [rcx + 64]
    vmovupd  zmm9, [rax + 64]

    vshufpd  zmm4,  zmm2, zmm2, 0x55
    vshufpd  zmm5,  zmm3, zmm3, 0x55
    vshufpd  zmm10, zmm8, zmm8, 0x55
    vshufpd  zmm11, zmm9, zmm9, 0x55
    vmulpd   zmm4,  zmm4,  zmm17
    vmulpd   zmm5,  zmm5,  zmm17
    vmulpd   zmm10, zmm10, zmm17
    vmulpd   zmm11, zmm11, zmm17
    vfmaddsub231pd zmm4,  zmm2, zmm16
    vfmaddsub231pd zmm5,  zmm3, zmm16
    vfmaddsub231pd zmm10, zmm8, zmm16
    vfmaddsub231pd zmm11, zmm9, zmm16

    vaddpd   zmm2, zmm0, zmm4
    vsubpd   zmm0, zmm0, zmm4
    vaddpd   zmm3, zmm1, zmm5
    vsubpd   zmm1, zmm1, zmm5
    vaddpd   zmm8, zmm6, zmm10
    vsubpd   zmm6, zmm6, zmm10
    vaddpd   zmm9, zmm7, zmm11
    vsubpd   zmm7, zmm7, zmm11

    vshufpd  zmm4,  zmm3, zmm3, 0x55
    vshufpd  zmm5,  zmm1, zmm1, 0x55
    vshufpd  zmm10, zmm9, zmm9, 0x55
    vshufpd  zmm11, zmm7, zmm7, 0x55
    vmulpd   zmm4,  zmm4,  zmm19
    vmulpd   zmm5,  zmm5,  zmm21
    vmulpd   zmm10, zmm10, zmm19
    vmulpd   zmm11, zmm11, zmm21
    vfmaddsub231pd zmm4,  zmm3, zmm18
    vfmaddsub231pd zmm5,  zmm1, zmm20
    vfmaddsub231pd zmm10, zmm9, zmm18
    vfmaddsub231pd zmm11, zmm7, zmm20

    vaddpd   zmm3, zmm2, zmm4
    vsubpd   zmm2, zmm2, zmm4
    vaddpd   zmm1, zmm0, zmm5
    vsubpd   zmm0, zmm0, zmm5
    vaddpd   zmm9, zmm8, zmm10
    vsubpd   zmm8, zmm8, zmm10
    vaddpd   zmm7, zmm6, zmm11
    vsubpd   zmm6, zmm6, zmm11

    vmovupd  [r12 + 0],  zmm3
    vmovupd  [r13 + 0],  zmm2
    vmovupd  [rcx + 0],  zmm1
    vmovupd  [rax + 0],  zmm0
    vmovupd  [r12 + 64], zmm9
    vmovupd  [r13 + 64], zmm8
    vmovupd  [rcx + 64], zmm7
    vmovupd  [rax + 64], zmm6

    lea  r12, [r12 + 128]
    lea  r13, [r13 + 128]
    lea  rcx, [rcx + 128]
    lea  rax, [rax + 128]
    sub  r14, 8
    jnz  .Lfftfwd_top_r4_loop8
    jmp  .Lfftfwd_top_r4_next_blk

.Lfftfwd_top_r4_j0_entry:
    vmovapd  zmm21, [rip + .Lconst_fft_neg_im]
.p2align 4
.Lfftfwd_top_r4_j0_loop8:
    vmovupd  zmm0, [r12 + 0]
    vmovupd  zmm1, [r13 + 0]
    vmovupd  zmm2, [rcx + 0]
    vmovupd  zmm3, [rax + 0]
    vmovupd  zmm6, [r12 + 64]
    vmovupd  zmm7, [r13 + 64]
    vmovupd  zmm8, [rcx + 64]
    vmovupd  zmm9, [rax + 64]

    vaddpd   zmm4,  zmm0, zmm2
    vsubpd   zmm0,  zmm0, zmm2
    vaddpd   zmm5,  zmm1, zmm3
    vsubpd   zmm1,  zmm1, zmm3
    vaddpd   zmm10, zmm6, zmm8
    vsubpd   zmm6,  zmm6, zmm8
    vaddpd   zmm11, zmm7, zmm9
    vsubpd   zmm7,  zmm7, zmm9

    vaddpd   zmm3,  zmm4, zmm5
    vsubpd   zmm2,  zmm4, zmm5
    vaddpd   zmm9,  zmm10, zmm11
    vsubpd   zmm8,  zmm10, zmm11

    vshufpd  zmm4,  zmm1, zmm1, 0x55
    vshufpd  zmm10, zmm7, zmm7, 0x55
    vxorpd   zmm4,  zmm4, zmm21
    vxorpd   zmm10, zmm10, zmm21
    vaddpd   zmm1,  zmm0, zmm4
    vsubpd   zmm0,  zmm0, zmm4
    vaddpd   zmm7,  zmm6, zmm10
    vsubpd   zmm6,  zmm6, zmm10

    vmovupd  [r12 + 0],  zmm3
    vmovupd  [r13 + 0],  zmm2
    vmovupd  [rcx + 0],  zmm1
    vmovupd  [rax + 0],  zmm0
    vmovupd  [r12 + 64], zmm9
    vmovupd  [r13 + 64], zmm8
    vmovupd  [rcx + 64], zmm7
    vmovupd  [rax + 64], zmm6

    lea  r12, [r12 + 128]
    lea  r13, [r13 + 128]
    lea  rcx, [rcx + 128]
    lea  rax, [rax + 128]
    sub  r14, 8
    jnz  .Lfftfwd_top_r4_j0_loop8

.Lfftfwd_top_r4_next_blk:
    inc  r10
    cmp  r10, r8
    jb   .Lfftfwd_top_r4_block

    shl  r8,  2
    shr  r9,  2
    jmp  .Lfftfwd_top_r4_check

.Lfftfwd_top_r2_check:
    mov  r11, [rsp + 40]                // sub_cap
    cmp  r9,  r11
    jb   .Lfftfwd_subs_start

    xor  r10d, r10d
    shl  r11, 4                         // m_bytes = sub_cap * 16
.Lfftfwd_top_r2_block:
    mov  rcx, r10
    imul rcx, r11
    add  rcx, rcx                       // j * 2 * m_bytes
    lea  r12, [rdi + rcx]
    lea  r13, [r12 + r11]
    mov  r14, [rsp + 40]                // sub_cap (>= 64, multiple of 8)
    lea  rax, [r8 + r10]
    cmp  rax, 1
    je   .Lfftfwd_top_r2_j0_loop8
    shl  rax, 4
    vbroadcastsd zmm6, [rsi + rax + 0]
    vbroadcastsd zmm7, [rsi + rax + 8]
.p2align 4
.Lfftfwd_top_r2_loop8:
    vmovupd  zmm0, [r12 + 0]
    vmovupd  zmm1, [r13 + 0]
    vmovupd  zmm2, [r12 + 64]
    vmovupd  zmm3, [r13 + 64]
    vshufpd  zmm4, zmm1, zmm1, 0x55
    vshufpd  zmm5, zmm3, zmm3, 0x55
    vmulpd   zmm4, zmm4, zmm7
    vmulpd   zmm5, zmm5, zmm7
    vfmaddsub231pd zmm4, zmm1, zmm6
    vfmaddsub231pd zmm5, zmm3, zmm6
    vaddpd   zmm1, zmm0, zmm4
    vsubpd   zmm0, zmm0, zmm4
    vaddpd   zmm3, zmm2, zmm5
    vsubpd   zmm2, zmm2, zmm5
    vmovupd  [r12 + 0],  zmm1
    vmovupd  [r13 + 0],  zmm0
    vmovupd  [r12 + 64], zmm3
    vmovupd  [r13 + 64], zmm2
    lea  r12, [r12 + 128]
    lea  r13, [r13 + 128]
    sub  r14, 8
    jnz  .Lfftfwd_top_r2_loop8
    jmp  .Lfftfwd_top_r2_next_blk

.p2align 4
.Lfftfwd_top_r2_j0_loop8:
    vmovupd  zmm0, [r12 + 0]
    vmovupd  zmm1, [r13 + 0]
    vmovupd  zmm2, [r12 + 64]
    vmovupd  zmm3, [r13 + 64]
    vaddpd   zmm4, zmm0, zmm1
    vsubpd   zmm0, zmm0, zmm1
    vaddpd   zmm5, zmm2, zmm3
    vsubpd   zmm2, zmm2, zmm3
    vmovupd  [r12 + 0],  zmm4
    vmovupd  [r13 + 0],  zmm0
    vmovupd  [r12 + 64], zmm5
    vmovupd  [r13 + 64], zmm2
    lea  r12, [r12 + 128]
    lea  r13, [r13 + 128]
    sub  r14, 8
    jnz  .Lfftfwd_top_r2_j0_loop8

.Lfftfwd_top_r2_next_blk:

    inc  r10
    cmp  r10, r8
    jb   .Lfftfwd_top_r2_block
    shl  r8,  1

.Lfftfwd_subs_start:
    mov  [rsp + 16], r8                 // num_subs = orig_n / sub_cap
    mov  qword ptr [rsp + 24], 0        // sb = 0
    mov  rax, [rsp + 40]
    mov  [rsp + 32], rax                // sub_n = sub_cap
    jmp  .Lfftfwd_sub_loop

.Lfftfwd_sub_single:
    mov  qword ptr [rsp + 16], 1        // num_subs = 1
    mov  qword ptr [rsp + 24], 0        // sb = 0
    mov  [rsp + 32], rdx                // sub_n = orig_n

.Lfftfwd_sub_loop:
    mov  rax, [rsp + 24]                // sb
    mov  rcx, [rsp + 16]                // num_subs
    mov  rdx, [rsp + 32]                // sub_n
    mov  rdi, [rsp + 0]
    mov  r11, rax
    imul r11, rdx
    shl  r11, 4                         // sb * sub_n * 16
    add  rdi, r11                       // sub_buf
    lea  rbx, [rcx + rax]               // k_base = num_subs + sb

    // 1a. Execute 4-stage Radix-16 passes from m = 512 down to m = 64, leaving m <= 32 for a
    // single in-register Radix-64 (bot6), Radix-32 (bot5), Radix-16 (bot4), or Radix-8 (bot3) pass!
    mov  r8,  1                         // b_local = 1
    mov  r9,  rdx
    shr  r9,  1                         // m = sub_n >> 1

.Lfftfwd_r16_check:
    cmp  r9,  64
    jb   .Lfftfwd_r4_check

    mov  r15, r9
    shr  r15, 3                         // ms = m / 8 >= 4 (multiple of 4)
    mov  r11, r15
    shl  r11, 4                         // ms_bytes = ms * 16
    xor  r10d, r10d                     // j = 0

.Lfftfwd_r16_block:
    lea  rax, [rbx + r10]
    cmp  rax, 1
    je   .Lfftfwd_r16_block_j0
    shl  rax, 4
    vbroadcastsd zmm16, [rsi + rax + 0] // stg1: wr0
    vbroadcastsd zmm17, [rsi + rax + 8] // stg1: wi0
    add  rax, rax
    vbroadcastsd zmm18, [rsi + rax + 0] // stg2: wr10
    vbroadcastsd zmm19, [rsi + rax + 8] // stg2: wi10
    vbroadcastsd zmm20, [rsi + rax + 16]// stg2: wr11
    vbroadcastsd zmm21, [rsi + rax + 24]// stg2: wi11
    add  rax, rax
    lea  r13, [rsi + rax]               // &tw[4 * k0] (stg3)
    vbroadcastsd zmm22, [r13 + 0]
    vbroadcastsd zmm23, [r13 + 8]
    vbroadcastsd zmm30, [r13 + 16]
    vbroadcastsd zmm31, [r13 + 24]
    vbroadcastsd zmm24, [r13 + 32]
    vbroadcastsd zmm25, [r13 + 40]
    vbroadcastsd zmm26, [r13 + 48]
    vbroadcastsd zmm27, [r13 + 56]
    add  rax, rax
    lea  rdx, [rsi + rax]               // &tw[8 * k0] (stg4)

    mov  rcx, r10
    imul rcx, r11
    shl  rcx, 4                         // j * 16 * ms_bytes
    lea  r12, [rdi + rcx]               // s0
    mov  r14, r15                       // count = ms
    lea  rax, [r11 + 2*r11]             // 3 * ms_bytes
    jmp  .Lfftfwd_r16_vec

.Lfftfwd_r16_block_j0:
    vmovapd zmm21, [rip + .Lconst_fft_neg_im]
    lea  r13, [rsi + 64]                // &tw[4] (stg3: tw[4]=(1,0), tw[5]=(0,-1)!)
    vbroadcastsd zmm30, [r13 + 32]      // tw[6].re
    vbroadcastsd zmm31, [r13 + 40]      // tw[6].im
    vbroadcastsd zmm16, [r13 + 48]      // tw[7].re
    vbroadcastsd zmm17, [r13 + 56]      // tw[7].im
    lea  rdx, [rsi + 128]               // &tw[8] (stg4: tw[8]=(1,0), tw[9]=(0,-1)!)
    vbroadcastsd zmm18, [rdx + 64]      // tw[12].re
    vbroadcastsd zmm19, [rdx + 72]      // tw[12].im
    vbroadcastsd zmm22, [rdx + 80]      // tw[13].re
    vbroadcastsd zmm23, [rdx + 88]      // tw[13].im
    mov  r12, rdi                       // s0 (j == 0)
    mov  r14, r15                       // count = ms
    lea  rax, [r11 + 2*r11]             // 3 * ms_bytes

.p2align 4
.Lfftfwd_r16_vec_j0:
    vmovupd zmm0,  [r12]
    vmovupd zmm1,  [r12 + r11]
    vmovupd zmm2,  [r12 + 2*r11]
    vmovupd zmm3,  [r12 + rax]
    lea  rcx, [r12 + 4*r11]
    vmovupd zmm4,  [rcx]
    vmovupd zmm5,  [rcx + r11]
    vmovupd zmm6,  [rcx + 2*r11]
    vmovupd zmm7,  [rcx + rax]
    lea  rcx, [r12 + 8*r11]
    vmovupd zmm8,  [rcx]
    vmovupd zmm9,  [rcx + r11]
    vmovupd zmm10, [rcx + 2*r11]
    vmovupd zmm11, [rcx + rax]
    lea  rcx, [rcx + 4*r11]
    vmovupd zmm12, [rcx]
    vmovupd zmm13, [rcx + r11]
    vmovupd zmm14, [rcx + 2*r11]
    vmovupd zmm15, [rcx + rax]

    // Stage 1 (k0 == 1: tw[1] = (1, 0))
    vsubpd  zmm28, zmm0, zmm8
    vsubpd  zmm29, zmm1, zmm9
    vaddpd  zmm0,  zmm0, zmm8
    vaddpd  zmm1,  zmm1, zmm9
    vmovapd zmm8,  zmm28
    vmovapd zmm9,  zmm29
    vsubpd  zmm28, zmm2, zmm10
    vsubpd  zmm29, zmm3, zmm11
    vaddpd  zmm2,  zmm2, zmm10
    vaddpd  zmm3,  zmm3, zmm11
    vmovapd zmm10, zmm28
    vmovapd zmm11, zmm29
    vsubpd  zmm28, zmm4, zmm12
    vsubpd  zmm29, zmm5, zmm13
    vaddpd  zmm4,  zmm4, zmm12
    vaddpd  zmm5,  zmm5, zmm13
    vmovapd zmm12, zmm28
    vmovapd zmm13, zmm29
    vsubpd  zmm28, zmm6, zmm14
    vsubpd  zmm29, zmm7, zmm15
    vaddpd  zmm6,  zmm6, zmm14
    vaddpd  zmm7,  zmm7, zmm15
    vmovapd zmm14, zmm28
    vmovapd zmm15, zmm29

    // Stage 2 (k0 == 1: tw[2] = (1, 0), tw[3] = (0, -1))
    vsubpd  zmm28, zmm0, zmm4
    vsubpd  zmm29, zmm1, zmm5
    vaddpd  zmm0,  zmm0, zmm4
    vaddpd  zmm1,  zmm1, zmm5
    vmovapd zmm4,  zmm28
    vmovapd zmm5,  zmm29
    vsubpd  zmm28, zmm2, zmm6
    vsubpd  zmm29, zmm3, zmm7
    vaddpd  zmm2,  zmm2, zmm6
    vaddpd  zmm3,  zmm3, zmm7
    vmovapd zmm6,  zmm28
    vmovapd zmm7,  zmm29

    vshufpd zmm28, zmm12, zmm12, 0x55
    vshufpd zmm29, zmm13, zmm13, 0x55
    vxorpd  zmm28, zmm28, zmm21
    vxorpd  zmm29, zmm29, zmm21
    vsubpd  zmm12, zmm8,  zmm28
    vsubpd  zmm13, zmm9,  zmm29
    vaddpd  zmm8,  zmm8,  zmm28
    vaddpd  zmm9,  zmm9,  zmm29
    vshufpd zmm28, zmm14, zmm14, 0x55
    vshufpd zmm29, zmm15, zmm15, 0x55
    vxorpd  zmm28, zmm28, zmm21
    vxorpd  zmm29, zmm29, zmm21
    vsubpd  zmm14, zmm10, zmm28
    vsubpd  zmm15, zmm11, zmm29
    vaddpd  zmm10, zmm10, zmm28
    vaddpd  zmm11, zmm11, zmm29

    // Stage 3 (k0 == 1: tw[4] = (1, 0), tw[5] = (0, -1), tw[6] & tw[7] in regs)
    vsubpd  zmm28, zmm0, zmm2
    vsubpd  zmm29, zmm1, zmm3
    vaddpd  zmm0,  zmm0, zmm2
    vaddpd  zmm1,  zmm1, zmm3
    vmovapd zmm2,  zmm28
    vmovapd zmm3,  zmm29
    vshufpd zmm28, zmm6, zmm6, 0x55
    vshufpd zmm29, zmm7, zmm7, 0x55
    vxorpd  zmm28, zmm28, zmm21
    vxorpd  zmm29, zmm29, zmm21
    vsubpd  zmm6,  zmm4, zmm28
    vsubpd  zmm7,  zmm5, zmm29
    vaddpd  zmm4,  zmm4, zmm28
    vaddpd  zmm5,  zmm5, zmm29
    FFT_DIF2 zmm8,  zmm10, zmm30, zmm31, zmm9,  zmm11, zmm30, zmm31
    FFT_DIF2 zmm12, zmm14, zmm16, zmm17, zmm13, zmm15, zmm16, zmm17

    // Stage 4 (k0 == 1: tw[8] = (1, 0), tw[9] = (0, -1))
    vsubpd  zmm28, zmm0, zmm1
    vaddpd  zmm0,  zmm0, zmm1
    vmovapd zmm1,  zmm28
    vshufpd zmm29, zmm3, zmm3, 0x55
    vxorpd  zmm29, zmm29, zmm21
    vsubpd  zmm3,  zmm2, zmm29
    vaddpd  zmm2,  zmm2, zmm29

    FFT_DIF2_MEM zmm4,  zmm5,  rdx+32, rdx+40,  zmm6,  zmm7,  rdx+48,  rdx+56
    FFT_DIF2     zmm8,  zmm9,  zmm18,  zmm19,   zmm10, zmm11, zmm22,   zmm23
    FFT_DIF2_MEM zmm12, zmm13, rdx+96, rdx+104, zmm14, zmm15, rdx+112, rdx+120
    jmp     .Lfftfwd_r16_store

.p2align 4
.Lfftfwd_r16_vec:
    vmovupd zmm0,  [r12]
    vmovupd zmm1,  [r12 + r11]
    vmovupd zmm2,  [r12 + 2*r11]
    vmovupd zmm3,  [r12 + rax]
    lea  rcx, [r12 + 4*r11]
    vmovupd zmm4,  [rcx]
    vmovupd zmm5,  [rcx + r11]
    vmovupd zmm6,  [rcx + 2*r11]
    vmovupd zmm7,  [rcx + rax]
    lea  rcx, [r12 + 8*r11]
    vmovupd zmm8,  [rcx]
    vmovupd zmm9,  [rcx + r11]
    vmovupd zmm10, [rcx + 2*r11]
    vmovupd zmm11, [rcx + rax]
    lea  rcx, [rcx + 4*r11]
    vmovupd zmm12, [rcx]
    vmovupd zmm13, [rcx + r11]
    vmovupd zmm14, [rcx + 2*r11]
    vmovupd zmm15, [rcx + rax]

    // Stage 1 (stride 8)
    FFT_DIF2 zmm0, zmm8,  zmm16, zmm17, zmm1, zmm9,  zmm16, zmm17
    FFT_DIF2 zmm2, zmm10, zmm16, zmm17, zmm3, zmm11, zmm16, zmm17
    FFT_DIF2 zmm4, zmm12, zmm16, zmm17, zmm5, zmm13, zmm16, zmm17
    FFT_DIF2 zmm6, zmm14, zmm16, zmm17, zmm7, zmm15, zmm16, zmm17

    // Stage 2 (stride 4)
    FFT_DIF2 zmm0, zmm4,  zmm18, zmm19, zmm1, zmm5,  zmm18, zmm19
    FFT_DIF2 zmm2, zmm6,  zmm18, zmm19, zmm3, zmm7,  zmm18, zmm19
    FFT_DIF2 zmm8, zmm12, zmm20, zmm21, zmm9, zmm13, zmm20, zmm21
    FFT_DIF2 zmm10, zmm14, zmm20, zmm21, zmm11, zmm15, zmm20, zmm21

.Lfftfwd_r16_stg3:
    // Stage 3 (stride 2)
    FFT_DIF2 zmm0,  zmm2,  zmm22, zmm23, zmm1,  zmm3,  zmm22, zmm23
    FFT_DIF2 zmm4,  zmm6,  zmm30, zmm31, zmm5,  zmm7,  zmm30, zmm31
    FFT_DIF2 zmm8,  zmm10, zmm24, zmm25, zmm9,  zmm11, zmm24, zmm25
    FFT_DIF2 zmm12, zmm14, zmm26, zmm27, zmm13, zmm15, zmm26, zmm27

    // Stage 4 (stride 1)
    FFT_DIF2_MEM zmm0,  zmm1,  rdx+0,  rdx+8,   zmm2,  zmm3,  rdx+16,  rdx+24
    FFT_DIF2_MEM zmm4,  zmm5,  rdx+32, rdx+40,  zmm6,  zmm7,  rdx+48,  rdx+56
    FFT_DIF2_MEM zmm8,  zmm9,  rdx+64, rdx+72,  zmm10, zmm11, rdx+80,  rdx+88
    FFT_DIF2_MEM zmm12, zmm13, rdx+96, rdx+104, zmm14, zmm15, rdx+112, rdx+120

.Lfftfwd_r16_store:
    vmovupd [r12],         zmm0
    vmovupd [r12 + r11],   zmm1
    vmovupd [r12 + 2*r11], zmm2
    vmovupd [r12 + rax],   zmm3
    lea  rcx, [r12 + 4*r11]
    vmovupd [rcx],         zmm4
    vmovupd [rcx + r11],   zmm5
    vmovupd [rcx + 2*r11], zmm6
    vmovupd [rcx + rax],   zmm7
    lea  rcx, [r12 + 8*r11]
    vmovupd [rcx],         zmm8
    vmovupd [rcx + r11],   zmm9
    vmovupd [rcx + 2*r11], zmm10
    vmovupd [rcx + rax],   zmm11
    lea  rcx, [rcx + 4*r11]
    vmovupd [rcx],         zmm12
    vmovupd [rcx + r11],   zmm13
    vmovupd [rcx + 2*r11], zmm14
    vmovupd [rcx + rax],   zmm15

    lea  r12, [r12 + 64]
    sub  r14, 4
    jz   .Lfftfwd_r16_blk_done
    lea  rcx, [rbx + r10]
    cmp  rcx, 1
    je   .Lfftfwd_r16_vec_j0
    jmp  .Lfftfwd_r16_vec
.Lfftfwd_r16_blk_done:

    inc  r10
    cmp  r10, r8
    jb   .Lfftfwd_r16_block

    shl  r8,  4
    shl  rbx, 4
    shr  r9,  4
    mov  rdx, [rsp + 32]
    jmp  .Lfftfwd_r16_check

.Lfftfwd_r4_check:
    cmp  r9,  32
    je   .Lfftfwd_m32_to_m1
    cmp  r9,  16
    je   .Lfftfwd_m16_m8_m4_m2_m1
    jb   .Lfftfwd_stage_check

    mov  r15, r9
    shr  r15, 1                         // mh = m / 2
    mov  r11, r15
    shl  r11, 4                         // mh_bytes = mh * 16
    xor  r10d, r10d                     // j = 0

.Lfftfwd_r4_block:
    lea  rax, [rbx + r10]
    shl  rax, 4
    vbroadcastsd zmm16, [rsi + rax + 0] // wr0
    vbroadcastsd zmm17, [rsi + rax + 8] // wi0
    add  rax, rax
    vbroadcastsd zmm18, [rsi + rax + 0] // wr1
    vbroadcastsd zmm19, [rsi + rax + 8] // wi1
    vbroadcastsd zmm20, [rsi + rax + 16]// wr2
    vbroadcastsd zmm21, [rsi + rax + 24]// wi2

    mov  rcx, r10
    imul rcx, r11
    shl  rcx, 2                         // j * 4 * mh_bytes
    lea  r12, [rdi + rcx]               // q0
    lea  r13, [r12 + r11]               // q1
    lea  rcx, [r13 + r11]               // q2
    lea  rax, [rcx + r11]               // q3
    mov  r14, r15                       // count = mh (multiple of 4)
    cmp  r14, 8
    jb   .Lfftfwd_r4_tail4

.p2align 6
.Lfftfwd_r4_loop8:
    vmovupd  zmm0,  [r12 + 0]
    vmovupd  zmm1,  [r13 + 0]
    vmovupd  zmm2,  [rcx + 0]
    vmovupd  zmm3,  [rax + 0]
    vmovupd  zmm22, [r12 + 64]
    vmovupd  zmm23, [r13 + 64]
    vmovupd  zmm24, [rcx + 64]
    vmovupd  zmm25, [rax + 64]

    vshufpd  zmm4,  zmm2,  zmm2,  0x55
    vshufpd  zmm5,  zmm3,  zmm3,  0x55
    vshufpd  zmm26, zmm24, zmm24, 0x55
    vshufpd  zmm27, zmm25, zmm25, 0x55
    vmulpd   zmm4,  zmm4,  zmm17
    vmulpd   zmm5,  zmm5,  zmm17
    vmulpd   zmm26, zmm26, zmm17
    vmulpd   zmm27, zmm27, zmm17
    vfmaddsub231pd zmm4,  zmm2,  zmm16
    vfmaddsub231pd zmm5,  zmm3,  zmm16
    vfmaddsub231pd zmm26, zmm24, zmm16
    vfmaddsub231pd zmm27, zmm25, zmm16

    vaddpd   zmm2,  zmm0,  zmm4
    vsubpd   zmm0,  zmm0,  zmm4
    vaddpd   zmm3,  zmm1,  zmm5
    vsubpd   zmm1,  zmm1,  zmm5
    vaddpd   zmm24, zmm22, zmm26
    vsubpd   zmm22, zmm22, zmm26
    vaddpd   zmm25, zmm23, zmm27
    vsubpd   zmm23, zmm23, zmm27

    vshufpd  zmm4,  zmm3,  zmm3,  0x55
    vshufpd  zmm5,  zmm1,  zmm1,  0x55
    vshufpd  zmm26, zmm25, zmm25, 0x55
    vshufpd  zmm27, zmm23, zmm23, 0x55
    vmulpd   zmm4,  zmm4,  zmm19
    vmulpd   zmm5,  zmm5,  zmm21
    vmulpd   zmm26, zmm26, zmm19
    vmulpd   zmm27, zmm27, zmm21
    vfmaddsub231pd zmm4,  zmm3,  zmm18
    vfmaddsub231pd zmm5,  zmm1,  zmm20
    vfmaddsub231pd zmm26, zmm25, zmm18
    vfmaddsub231pd zmm27, zmm23, zmm20

    vaddpd   zmm3,  zmm2,  zmm4
    vsubpd   zmm2,  zmm2,  zmm4
    vaddpd   zmm1,  zmm0,  zmm5
    vsubpd   zmm0,  zmm0,  zmm5
    vaddpd   zmm25, zmm24, zmm26
    vsubpd   zmm24, zmm24, zmm26
    vaddpd   zmm23, zmm22, zmm27
    vsubpd   zmm22, zmm22, zmm27

    vmovupd  [r12 + 0],  zmm3
    vmovupd  [r13 + 0],  zmm2
    vmovupd  [rcx + 0],  zmm1
    vmovupd  [rax + 0],  zmm0
    vmovupd  [r12 + 64], zmm25
    vmovupd  [r13 + 64], zmm24
    vmovupd  [rcx + 64], zmm23
    vmovupd  [rax + 64], zmm22

    lea  r12, [r12 + 128]
    lea  r13, [r13 + 128]
    lea  rcx, [rcx + 128]
    lea  rax, [rax + 128]
    sub  r14, 8
    cmp  r14, 8
    jae  .Lfftfwd_r4_loop8

.Lfftfwd_r4_tail4:
    test r14, r14
    jz   .Lfftfwd_r4_next_blk
    vmovupd  zmm0, [r12]
    vmovupd  zmm1, [r13]
    vmovupd  zmm2, [rcx]
    vmovupd  zmm3, [rax]

    vshufpd  zmm4, zmm2, zmm2, 0x55
    vshufpd  zmm5, zmm3, zmm3, 0x55
    vmulpd   zmm4, zmm4, zmm17
    vmulpd   zmm5, zmm5, zmm17
    vfmaddsub231pd zmm4, zmm2, zmm16
    vfmaddsub231pd zmm5, zmm3, zmm16

    vaddpd   zmm2, zmm0, zmm4
    vsubpd   zmm0, zmm0, zmm4
    vaddpd   zmm3, zmm1, zmm5
    vsubpd   zmm1, zmm1, zmm5

    vshufpd  zmm4, zmm3, zmm3, 0x55
    vshufpd  zmm5, zmm1, zmm1, 0x55
    vmulpd   zmm4, zmm4, zmm19
    vmulpd   zmm5, zmm5, zmm21
    vfmaddsub231pd zmm4, zmm3, zmm18
    vfmaddsub231pd zmm5, zmm1, zmm20

    vaddpd   zmm3, zmm2, zmm4
    vsubpd   zmm2, zmm2, zmm4
    vaddpd   zmm1, zmm0, zmm5
    vsubpd   zmm0, zmm0, zmm5

    vmovupd  [r12], zmm3
    vmovupd  [r13], zmm2
    vmovupd  [rcx], zmm1
    vmovupd  [rax], zmm0

.Lfftfwd_r4_next_blk:
    inc  r10
    cmp  r10, r8
    jb   .Lfftfwd_r4_block

    shl  r8,  2
    shl  rbx, 2
    shr  r9,  2
    jmp  .Lfftfwd_r4_check

    // 1b-even. Fused 6-stage Radix-64 (m = 32, 16, 8, 4, 2, 1) in zmm0..zmm15 with zero spills!
.Lfftfwd_m32_to_m1:
    xor  r10d, r10d                     // j = 0 .. r8 - 1 (64 complex = 1024B per block)
.p2align 6
.Lfftfwd_m32_to_m1_loop:
    mov  rax, r10
    shl  rax, 10                        // j * 1024
    vmovupd  zmm0,  [rdi + rax + 0]
    vmovupd  zmm1,  [rdi + rax + 64]
    vmovupd  zmm2,  [rdi + rax + 128]
    vmovupd  zmm3,  [rdi + rax + 192]
    vmovupd  zmm4,  [rdi + rax + 256]
    vmovupd  zmm5,  [rdi + rax + 320]
    vmovupd  zmm6,  [rdi + rax + 384]
    vmovupd  zmm7,  [rdi + rax + 448]
    vmovupd  zmm8,  [rdi + rax + 512]
    vmovupd  zmm9,  [rdi + rax + 576]
    vmovupd  zmm10, [rdi + rax + 640]
    vmovupd  zmm11, [rdi + rax + 704]
    vmovupd  zmm12, [rdi + rax + 768]
    vmovupd  zmm13, [rdi + rax + 832]
    vmovupd  zmm14, [rdi + rax + 896]
    vmovupd  zmm15, [rdi + rax + 960]

    lea  rcx, [rbx + r10]
    shl  rcx, 4                         // (k_m32 + j) * 16

    // Stage m = 32 across halves [0..31] and [32..63]:
    vbroadcastsd zmm16, [rsi + rcx + 0]
    vbroadcastsd zmm17, [rsi + rcx + 8]
    FFT_DIF4 zmm0, zmm8,  zmm16, zmm17, zmm1, zmm9,  zmm16, zmm17, zmm2, zmm10, zmm16, zmm17, zmm3, zmm11, zmm16, zmm17
    FFT_DIF4 zmm4, zmm12, zmm16, zmm17, zmm5, zmm13, zmm16, zmm17, zmm6, zmm14, zmm16, zmm17, zmm7, zmm15, zmm16, zmm17
    add  rcx, rcx                       // 2 * (k_m32 + j) * 16

    // Stage m = 16 across quarters [0..15]/[16..31] and [32..47]/[48..63]:
    vbroadcastsd zmm16, [rsi + rcx + 0]
    vbroadcastsd zmm17, [rsi + rcx + 8]
    vbroadcastsd zmm18, [rsi + rcx + 16]
    vbroadcastsd zmm19, [rsi + rcx + 24]
    FFT_DIF4 zmm0, zmm4,  zmm16, zmm17, zmm1, zmm5,  zmm16, zmm17, zmm2,  zmm6,  zmm16, zmm17, zmm3,  zmm7,  zmm16, zmm17
    FFT_DIF4 zmm8, zmm12, zmm18, zmm19, zmm9, zmm13, zmm18, zmm19, zmm10, zmm14, zmm18, zmm19, zmm11, zmm15, zmm18, zmm19
    add  rcx, rcx                       // 4 * (k_m32 + j) * 16 = k_m8 * 16

    // Stage m = 8 across all 4 16-complex sub-blocks:
    vbroadcastsd zmm16, [rsi + rcx + 0]
    vbroadcastsd zmm17, [rsi + rcx + 8]
    vbroadcastsd zmm18, [rsi + rcx + 16]
    vbroadcastsd zmm19, [rsi + rcx + 24]
    vbroadcastsd zmm20, [rsi + rcx + 32]
    vbroadcastsd zmm21, [rsi + rcx + 40]
    vbroadcastsd zmm22, [rsi + rcx + 48]
    vbroadcastsd zmm23, [rsi + rcx + 56]
    FFT_DIF4 zmm0, zmm2,  zmm16, zmm17, zmm1, zmm3,  zmm16, zmm17, zmm4,  zmm6,  zmm18, zmm19, zmm5,  zmm7,  zmm18, zmm19
    FFT_DIF4 zmm8, zmm10, zmm20, zmm21, zmm9, zmm11, zmm20, zmm21, zmm12, zmm14, zmm22, zmm23, zmm13, zmm15, zmm22, zmm23

    // Stage m = 4 across all 8 eighths:
    vbroadcastsd zmm16, [rsi + 2*rcx + 0]
    vbroadcastsd zmm17, [rsi + 2*rcx + 8]
    vbroadcastsd zmm18, [rsi + 2*rcx + 16]
    vbroadcastsd zmm19, [rsi + 2*rcx + 24]
    vbroadcastsd zmm20, [rsi + 2*rcx + 32]
    vbroadcastsd zmm21, [rsi + 2*rcx + 40]
    vbroadcastsd zmm22, [rsi + 2*rcx + 48]
    vbroadcastsd zmm23, [rsi + 2*rcx + 56]
    FFT_DIF4 zmm0, zmm1, zmm16, zmm17, zmm2, zmm3, zmm18, zmm19, zmm4, zmm5, zmm20, zmm21, zmm6, zmm7, zmm22, zmm23

    vbroadcastsd zmm16, [rsi + 2*rcx + 64]
    vbroadcastsd zmm17, [rsi + 2*rcx + 72]
    vbroadcastsd zmm18, [rsi + 2*rcx + 80]
    vbroadcastsd zmm19, [rsi + 2*rcx + 88]
    vbroadcastsd zmm20, [rsi + 2*rcx + 96]
    vbroadcastsd zmm21, [rsi + 2*rcx + 104]
    vbroadcastsd zmm22, [rsi + 2*rcx + 112]
    vbroadcastsd zmm23, [rsi + 2*rcx + 120]
    FFT_DIF4 zmm8, zmm9, zmm16, zmm17, zmm10, zmm11, zmm18, zmm19, zmm12, zmm13, zmm20, zmm21, zmm14, zmm15, zmm22, zmm23

    // Stage m = 2 across first half (zmm0..zmm7):
    vshuff64x2 zmm24, zmm0,  zmm1,  0x44
    vshuff64x2 zmm1,  zmm0,  zmm1,  0xEE
    vmovapd    zmm0,  zmm24
    vshuff64x2 zmm25, zmm2,  zmm3,  0x44
    vshuff64x2 zmm3,  zmm2,  zmm3,  0xEE
    vmovapd    zmm2,  zmm25
    vshuff64x2 zmm26, zmm4,  zmm5,  0x44
    vshuff64x2 zmm5,  zmm4,  zmm5,  0xEE
    vmovapd    zmm4,  zmm26
    vshuff64x2 zmm27, zmm6,  zmm7,  0x44
    vshuff64x2 zmm7,  zmm6,  zmm7,  0xEE
    vmovapd    zmm6,  zmm27
    vmovupd    zmm24, [rsi + 4*rcx + 0]
    vmovupd    zmm25, [rsi + 4*rcx + 64]
    vshuff64x2 zmm28, zmm24, zmm24, 0x50
    vshuff64x2 zmm29, zmm24, zmm24, 0xFA
    vshuff64x2 zmm30, zmm25, zmm25, 0x50
    vshuff64x2 zmm31, zmm25, zmm25, 0xFA
    vmovddup   zmm16, zmm28
    vshufpd    zmm17, zmm28, zmm28, 0xFF
    vmovddup   zmm18, zmm29
    vshufpd    zmm19, zmm29, zmm29, 0xFF
    vmovddup   zmm20, zmm30
    vshufpd    zmm21, zmm30, zmm30, 0xFF
    vmovddup   zmm22, zmm31
    vshufpd    zmm23, zmm31, zmm31, 0xFF
    FFT_DIF4 zmm0, zmm1, zmm16, zmm17, zmm2, zmm3, zmm18, zmm19, zmm4, zmm5, zmm20, zmm21, zmm6, zmm7, zmm22, zmm23

    // Stage m = 2 across second half (zmm8..zmm15):
    vshuff64x2 zmm24, zmm8,  zmm9,  0x44
    vshuff64x2 zmm9,  zmm8,  zmm9,  0xEE
    vmovapd    zmm8,  zmm24
    vshuff64x2 zmm25, zmm10, zmm11, 0x44
    vshuff64x2 zmm11, zmm10, zmm11, 0xEE
    vmovapd    zmm10, zmm25
    vshuff64x2 zmm26, zmm12, zmm13, 0x44
    vshuff64x2 zmm13, zmm12, zmm13, 0xEE
    vmovapd    zmm12, zmm26
    vshuff64x2 zmm27, zmm14, zmm15, 0x44
    vshuff64x2 zmm15, zmm14, zmm15, 0xEE
    vmovapd    zmm14, zmm27
    vmovupd    zmm24, [rsi + 4*rcx + 128]
    vmovupd    zmm25, [rsi + 4*rcx + 192]
    vshuff64x2 zmm28, zmm24, zmm24, 0x50
    vshuff64x2 zmm29, zmm24, zmm24, 0xFA
    vshuff64x2 zmm30, zmm25, zmm25, 0x50
    vshuff64x2 zmm31, zmm25, zmm25, 0xFA
    vmovddup   zmm16, zmm28
    vshufpd    zmm17, zmm28, zmm28, 0xFF
    vmovddup   zmm18, zmm29
    vshufpd    zmm19, zmm29, zmm29, 0xFF
    vmovddup   zmm20, zmm30
    vshufpd    zmm21, zmm30, zmm30, 0xFF
    vmovddup   zmm22, zmm31
    vshufpd    zmm23, zmm31, zmm31, 0xFF
    FFT_DIF4 zmm8, zmm9, zmm16, zmm17, zmm10, zmm11, zmm18, zmm19, zmm12, zmm13, zmm20, zmm21, zmm14, zmm15, zmm22, zmm23

    // Stage m = 1 + interleave & store across first half (zmm0..zmm7):
    vshuff64x2 zmm24, zmm0,  zmm1,  0x88
    vshuff64x2 zmm1,  zmm0,  zmm1,  0xDD
    vshuff64x2 zmm25, zmm2,  zmm3,  0x88
    vshuff64x2 zmm3,  zmm2,  zmm3,  0xDD
    vshuff64x2 zmm26, zmm4,  zmm5,  0x88
    vshuff64x2 zmm5,  zmm4,  zmm5,  0xDD
    vshuff64x2 zmm27, zmm6,  zmm7,  0x88
    vshuff64x2 zmm7,  zmm6,  zmm7,  0xDD
    vmovupd    zmm28, [rsi + 8*rcx + 0]
    vmovupd    zmm29, [rsi + 8*rcx + 64]
    vmovupd    zmm30, [rsi + 8*rcx + 128]
    vmovupd    zmm31, [rsi + 8*rcx + 192]
    vshuff64x2 zmm28, zmm28, zmm28, 0xD8
    vshuff64x2 zmm29, zmm29, zmm29, 0xD8
    vshuff64x2 zmm30, zmm30, zmm30, 0xD8
    vshuff64x2 zmm31, zmm31, zmm31, 0xD8
    vmovddup   zmm16, zmm28
    vshufpd    zmm17, zmm28, zmm28, 0xFF
    vmovddup   zmm18, zmm29
    vshufpd    zmm19, zmm29, zmm29, 0xFF
    vmovddup   zmm20, zmm30
    vshufpd    zmm21, zmm30, zmm30, 0xFF
    vmovddup   zmm22, zmm31
    vshufpd    zmm23, zmm31, zmm31, 0xFF
    FFT_DIF4 zmm24, zmm1, zmm16, zmm17, zmm25, zmm3, zmm18, zmm19, zmm26, zmm5, zmm20, zmm21, zmm27, zmm7, zmm22, zmm23

    vmovdqa64  zmm28, [rip + .Lconst_idx_pair_lo]
    vmovdqa64  zmm29, [rip + .Lconst_idx_pair_hi]
    vmovapd    zmm0,  zmm24
    vpermt2pd  zmm0,  zmm28, zmm1
    vpermt2pd  zmm24, zmm29, zmm1
    vmovapd    zmm2,  zmm25
    vpermt2pd  zmm2,  zmm28, zmm3
    vpermt2pd  zmm25, zmm29, zmm3
    vmovapd    zmm4,  zmm26
    vpermt2pd  zmm4,  zmm28, zmm5
    vpermt2pd  zmm26, zmm29, zmm5
    vmovapd    zmm6,  zmm27
    vpermt2pd  zmm6,  zmm28, zmm7
    vpermt2pd  zmm27, zmm29, zmm7
    vmovupd    [rdi + rax + 0],   zmm0
    vmovupd    [rdi + rax + 64],  zmm24
    vmovupd    [rdi + rax + 128], zmm2
    vmovupd    [rdi + rax + 192], zmm25
    vmovupd    [rdi + rax + 256], zmm4
    vmovupd    [rdi + rax + 320], zmm26
    vmovupd    [rdi + rax + 384], zmm6
    vmovupd    [rdi + rax + 448], zmm27

    // Stage m = 1 + interleave & store across second half (zmm8..zmm15):
    vshuff64x2 zmm24, zmm8,  zmm9,  0x88
    vshuff64x2 zmm9,  zmm8,  zmm9,  0xDD
    vshuff64x2 zmm25, zmm10, zmm11, 0x88
    vshuff64x2 zmm11, zmm10, zmm11, 0xDD
    vshuff64x2 zmm26, zmm12, zmm13, 0x88
    vshuff64x2 zmm13, zmm12, zmm13, 0xDD
    vshuff64x2 zmm27, zmm14, zmm15, 0x88
    vshuff64x2 zmm15, zmm14, zmm15, 0xDD
    vmovupd    zmm28, [rsi + 8*rcx + 256]
    vmovupd    zmm29, [rsi + 8*rcx + 320]
    vmovupd    zmm30, [rsi + 8*rcx + 384]
    vmovupd    zmm31, [rsi + 8*rcx + 448]
    vshuff64x2 zmm28, zmm28, zmm28, 0xD8
    vshuff64x2 zmm29, zmm29, zmm29, 0xD8
    vshuff64x2 zmm30, zmm30, zmm30, 0xD8
    vshuff64x2 zmm31, zmm31, zmm31, 0xD8
    vmovddup   zmm16, zmm28
    vshufpd    zmm17, zmm28, zmm28, 0xFF
    vmovddup   zmm18, zmm29
    vshufpd    zmm19, zmm29, zmm29, 0xFF
    vmovddup   zmm20, zmm30
    vshufpd    zmm21, zmm30, zmm30, 0xFF
    vmovddup   zmm22, zmm31
    vshufpd    zmm23, zmm31, zmm31, 0xFF
    FFT_DIF4 zmm24, zmm9, zmm16, zmm17, zmm25, zmm11, zmm18, zmm19, zmm26, zmm13, zmm20, zmm21, zmm27, zmm15, zmm22, zmm23

    vmovdqa64  zmm28, [rip + .Lconst_idx_pair_lo]
    vmovdqa64  zmm29, [rip + .Lconst_idx_pair_hi]
    vmovapd    zmm8,  zmm24
    vpermt2pd  zmm8,  zmm28, zmm9
    vpermt2pd  zmm24, zmm29, zmm9
    vmovapd    zmm10, zmm25
    vpermt2pd  zmm10, zmm28, zmm11
    vpermt2pd  zmm25, zmm29, zmm11
    vmovapd    zmm12, zmm26
    vpermt2pd  zmm12, zmm28, zmm13
    vpermt2pd  zmm26, zmm29, zmm13
    vmovapd    zmm14, zmm27
    vpermt2pd  zmm14, zmm28, zmm15
    vpermt2pd  zmm27, zmm29, zmm15
    vmovupd    [rdi + rax + 512], zmm8
    vmovupd    [rdi + rax + 576], zmm24
    vmovupd    [rdi + rax + 640], zmm10
    vmovupd    [rdi + rax + 704], zmm25
    vmovupd    [rdi + rax + 768], zmm12
    vmovupd    [rdi + rax + 832], zmm26
    vmovupd    [rdi + rax + 896], zmm14
    vmovupd    [rdi + rax + 960], zmm27

    inc  r10
    cmp  r10, r8
    jb   .Lfftfwd_m32_to_m1_loop
    jmp  .Lfftfwd_next_sub

    // 1b. Fused 5-stage Radix-32 (m = 16, 8, 4, 2, 1), 4-stage Radix-16, or 3-stage Radix-8 bottom pass!
.Lfftfwd_m16_m8_m4_m2_m1:
    xor  r10d, r10d                     // j = 0 .. r8 - 1 (32 complex = 512B per block)
.p2align 6
.Lfftfwd_m16_m8_m4_m2_m1_loop:
    mov  rax, r10
    shl  rax, 9                         // j * 512
    vmovupd  zmm0,  [rdi + rax + 0]     // [c0..c3]
    vmovupd  zmm1,  [rdi + rax + 64]    // [c4..c7]
    vmovupd  zmm2,  [rdi + rax + 128]   // [c8..c11]
    vmovupd  zmm3,  [rdi + rax + 192]   // [c12..c15]
    vmovupd  zmm4,  [rdi + rax + 256]   // [c16..c19]
    vmovupd  zmm5,  [rdi + rax + 320]   // [c20..c23]
    vmovupd  zmm24, [rdi + rax + 384]   // [c24..c27]
    vmovupd  zmm25, [rdi + rax + 448]   // [c28..c31]

    lea  rcx, [rbx + r10]
    shl  rcx, 4                         // (k_m16 + j) * 16

    // Stage m = 16 across halves [0..15] and [16..31]:
    vbroadcastsd zmm16, [rsi + rcx + 0]
    vbroadcastsd zmm17, [rsi + rcx + 8]
    FFT_DIF4 zmm0, zmm4, zmm16, zmm17, zmm1, zmm5, zmm16, zmm17, zmm2, zmm24, zmm16, zmm17, zmm3, zmm25, zmm16, zmm17
    add  rcx, rcx                       // 2 * (k_m16 + j) * 16

    // Stage m = 8 across both 16-complex halves:
    vbroadcastsd zmm16, [rsi + rcx + 0]
    vbroadcastsd zmm17, [rsi + rcx + 8]
    vbroadcastsd zmm18, [rsi + rcx + 16]
    vbroadcastsd zmm19, [rsi + rcx + 24]
    FFT_DIF4 zmm0, zmm2, zmm16, zmm17, zmm1, zmm3, zmm16, zmm17, zmm4, zmm24, zmm18, zmm19, zmm5, zmm25, zmm18, zmm19

    // Stage m = 4 across all 4 quarters:
    vbroadcastsd zmm16, [rsi + 2*rcx + 0]
    vbroadcastsd zmm17, [rsi + 2*rcx + 8]
    vbroadcastsd zmm18, [rsi + 2*rcx + 16]
    vbroadcastsd zmm19, [rsi + 2*rcx + 24]
    vbroadcastsd zmm20, [rsi + 2*rcx + 32]
    vbroadcastsd zmm21, [rsi + 2*rcx + 40]
    vbroadcastsd zmm22, [rsi + 2*rcx + 48]
    vbroadcastsd zmm23, [rsi + 2*rcx + 56]
    FFT_DIF4 zmm0, zmm1, zmm16, zmm17, zmm2, zmm3, zmm18, zmm19, zmm4, zmm5, zmm20, zmm21, zmm24, zmm25, zmm22, zmm23

    // Stage m = 2 across all 8 eighths:
    vshuff64x2 zmm26, zmm0,  zmm1,  0x44
    vshuff64x2 zmm1,  zmm0,  zmm1,  0xEE
    vshuff64x2 zmm27, zmm2,  zmm3,  0x44
    vshuff64x2 zmm3,  zmm2,  zmm3,  0xEE
    vshuff64x2 zmm0,  zmm4,  zmm5,  0x44
    vshuff64x2 zmm5,  zmm4,  zmm5,  0xEE
    vshuff64x2 zmm2,  zmm24, zmm25, 0x44
    vshuff64x2 zmm25, zmm24, zmm25, 0xEE
    vmovupd    zmm4,  [rsi + 4*rcx + 0]
    vmovupd    zmm24, [rsi + 4*rcx + 64]
    vshuff64x2 zmm28, zmm4,  zmm4,  0x50
    vshuff64x2 zmm29, zmm4,  zmm4,  0xFA
    vshuff64x2 zmm30, zmm24, zmm24, 0x50
    vshuff64x2 zmm31, zmm24, zmm24, 0xFA
    vmovddup   zmm16, zmm28
    vshufpd    zmm17, zmm28, zmm28, 0xFF
    vmovddup   zmm18, zmm29
    vshufpd    zmm19, zmm29, zmm29, 0xFF
    vmovddup   zmm20, zmm30
    vshufpd    zmm21, zmm30, zmm30, 0xFF
    vmovddup   zmm22, zmm31
    vshufpd    zmm23, zmm31, zmm31, 0xFF
    FFT_DIF4 zmm26, zmm1, zmm16, zmm17, zmm27, zmm3, zmm18, zmm19, zmm0, zmm5, zmm20, zmm21, zmm2, zmm25, zmm22, zmm23

    // Stage m = 1 across all 16 pairs:
    vshuff64x2 zmm4,  zmm26, zmm1,  0x88
    vshuff64x2 zmm1,  zmm26, zmm1,  0xDD
    vshuff64x2 zmm24, zmm27, zmm3,  0x88
    vshuff64x2 zmm3,  zmm27, zmm3,  0xDD
    vshuff64x2 zmm26, zmm0,  zmm5,  0x88
    vshuff64x2 zmm5,  zmm0,  zmm5,  0xDD
    vshuff64x2 zmm27, zmm2,  zmm25, 0x88
    vshuff64x2 zmm25, zmm2,  zmm25, 0xDD
    vmovupd    zmm28, [rsi + 8*rcx + 0]
    vmovupd    zmm29, [rsi + 8*rcx + 64]
    vmovupd    zmm30, [rsi + 8*rcx + 128]
    vmovupd    zmm31, [rsi + 8*rcx + 192]
    vshuff64x2 zmm28, zmm28, zmm28, 0xD8
    vshuff64x2 zmm29, zmm29, zmm29, 0xD8
    vshuff64x2 zmm30, zmm30, zmm30, 0xD8
    vshuff64x2 zmm31, zmm31, zmm31, 0xD8
    vmovddup   zmm16, zmm28
    vshufpd    zmm17, zmm28, zmm28, 0xFF
    vmovddup   zmm18, zmm29
    vshufpd    zmm19, zmm29, zmm29, 0xFF
    vmovddup   zmm20, zmm30
    vshufpd    zmm21, zmm30, zmm30, 0xFF
    vmovddup   zmm22, zmm31
    vshufpd    zmm23, zmm31, zmm31, 0xFF
    FFT_DIF4 zmm4, zmm1, zmm16, zmm17, zmm24, zmm3, zmm18, zmm19, zmm26, zmm5, zmm20, zmm21, zmm27, zmm25, zmm22, zmm23

    vmovdqa64  zmm16, [rip + .Lconst_idx_pair_lo]
    vmovdqa64  zmm17, [rip + .Lconst_idx_pair_hi]
    vmovapd    zmm0,  zmm4
    vpermt2pd  zmm0,  zmm16, zmm1
    vpermt2pd  zmm4,  zmm17, zmm1
    vmovapd    zmm2,  zmm24
    vpermt2pd  zmm2,  zmm16, zmm3
    vpermt2pd  zmm24, zmm17, zmm3
    vmovapd    zmm18, zmm26
    vpermt2pd  zmm18, zmm16, zmm5
    vpermt2pd  zmm26, zmm17, zmm5
    vmovapd    zmm19, zmm27
    vpermt2pd  zmm19, zmm16, zmm25
    vpermt2pd  zmm27, zmm17, zmm25
    vmovupd  [rdi + rax + 0],   zmm0
    vmovupd  [rdi + rax + 64],  zmm4
    vmovupd  [rdi + rax + 128], zmm2
    vmovupd  [rdi + rax + 192], zmm24
    vmovupd  [rdi + rax + 256], zmm18
    vmovupd  [rdi + rax + 320], zmm26
    vmovupd  [rdi + rax + 384], zmm19
    vmovupd  [rdi + rax + 448], zmm27

    inc  r10
    cmp  r10, r8
    jb   .Lfftfwd_m16_m8_m4_m2_m1_loop
    jmp  .Lfftfwd_next_sub

.Lfftfwd_stage_check:
    cmp  r9,  8
    jb   .Lfftfwd_chk_m4

    xor  r10d, r10d                     // j = 0 .. r8 - 1 (16 complex = 256B per block)
    cmp  r8,   2
    jb   .Lfftfwd_m8_m4_m2_m1_vec

.p2align 6
.Lfftfwd_m8_m4_m2_m1_vec2:
    mov  rax, r10
    shl  rax, 8                         // j * 256
    vmovupd  zmm0,  [rdi + rax + 0]     // block j:   [c0..c3]
    vmovupd  zmm1,  [rdi + rax + 64]    // block j:   [c4..c7]
    vmovupd  zmm2,  [rdi + rax + 128]   // block j:   [c8..c11]
    vmovupd  zmm3,  [rdi + rax + 192]   // block j:   [c12..c15]
    vmovupd  zmm4,  [rdi + rax + 256]   // block j+1: [d0..d3]
    vmovupd  zmm5,  [rdi + rax + 320]   // block j+1: [d4..d7]
    vmovupd  zmm24, [rdi + rax + 384]   // block j+1: [d8..d11]
    vmovupd  zmm25, [rdi + rax + 448]   // block j+1: [d12..d15]

    lea  rcx, [rbx + r10]
    shl  rcx, 4                         // (k_m8 + j) * 16

    // Stage m = 8 across blocks j and j+1:
    vbroadcastsd zmm16, [rsi + rcx + 0]
    vbroadcastsd zmm17, [rsi + rcx + 8]
    vbroadcastsd zmm18, [rsi + rcx + 16]
    vbroadcastsd zmm19, [rsi + rcx + 24]
    FFT_DIF4 zmm0, zmm2, zmm16, zmm17, zmm1, zmm3, zmm16, zmm17, zmm4, zmm24, zmm18, zmm19, zmm5, zmm25, zmm18, zmm19

    // Stage m = 4 across all 4 halves:
    vbroadcastsd zmm16, [rsi + 2*rcx + 0]
    vbroadcastsd zmm17, [rsi + 2*rcx + 8]
    vbroadcastsd zmm18, [rsi + 2*rcx + 16]
    vbroadcastsd zmm19, [rsi + 2*rcx + 24]
    vbroadcastsd zmm20, [rsi + 2*rcx + 32]
    vbroadcastsd zmm21, [rsi + 2*rcx + 40]
    vbroadcastsd zmm22, [rsi + 2*rcx + 48]
    vbroadcastsd zmm23, [rsi + 2*rcx + 56]
    FFT_DIF4 zmm0, zmm1, zmm16, zmm17, zmm2, zmm3, zmm18, zmm19, zmm4, zmm5, zmm20, zmm21, zmm24, zmm25, zmm22, zmm23

    // Stage m = 2 across all 8 quarters:
    vshuff64x2 zmm26, zmm0,  zmm1,  0x44
    vshuff64x2 zmm1,  zmm0,  zmm1,  0xEE
    vshuff64x2 zmm27, zmm2,  zmm3,  0x44
    vshuff64x2 zmm3,  zmm2,  zmm3,  0xEE
    vshuff64x2 zmm0,  zmm4,  zmm5,  0x44
    vshuff64x2 zmm5,  zmm4,  zmm5,  0xEE
    vshuff64x2 zmm2,  zmm24, zmm25, 0x44
    vshuff64x2 zmm25, zmm24, zmm25, 0xEE
    vmovupd    zmm4,  [rsi + 4*rcx + 0]
    vmovupd    zmm24, [rsi + 4*rcx + 64]
    vshuff64x2 zmm28, zmm4,  zmm4,  0x50
    vshuff64x2 zmm29, zmm4,  zmm4,  0xFA
    vshuff64x2 zmm30, zmm24, zmm24, 0x50
    vshuff64x2 zmm31, zmm24, zmm24, 0xFA
    vmovddup   zmm16, zmm28
    vshufpd    zmm17, zmm28, zmm28, 0xFF
    vmovddup   zmm18, zmm29
    vshufpd    zmm19, zmm29, zmm29, 0xFF
    vmovddup   zmm20, zmm30
    vshufpd    zmm21, zmm30, zmm30, 0xFF
    vmovddup   zmm22, zmm31
    vshufpd    zmm23, zmm31, zmm31, 0xFF
    FFT_DIF4 zmm26, zmm1, zmm16, zmm17, zmm27, zmm3, zmm18, zmm19, zmm0, zmm5, zmm20, zmm21, zmm2, zmm25, zmm22, zmm23

    // Stage m = 1 across all 16 pairs:
    vshuff64x2 zmm4,  zmm26, zmm1,  0x88
    vshuff64x2 zmm1,  zmm26, zmm1,  0xDD
    vshuff64x2 zmm24, zmm27, zmm3,  0x88
    vshuff64x2 zmm3,  zmm27, zmm3,  0xDD
    vshuff64x2 zmm26, zmm0,  zmm5,  0x88
    vshuff64x2 zmm5,  zmm0,  zmm5,  0xDD
    vshuff64x2 zmm27, zmm2,  zmm25, 0x88
    vshuff64x2 zmm25, zmm2,  zmm25, 0xDD
    vmovupd    zmm28, [rsi + 8*rcx + 0]
    vmovupd    zmm29, [rsi + 8*rcx + 64]
    vmovupd    zmm30, [rsi + 8*rcx + 128]
    vmovupd    zmm31, [rsi + 8*rcx + 192]
    vshuff64x2 zmm28, zmm28, zmm28, 0xD8
    vshuff64x2 zmm29, zmm29, zmm29, 0xD8
    vshuff64x2 zmm30, zmm30, zmm30, 0xD8
    vshuff64x2 zmm31, zmm31, zmm31, 0xD8
    vmovddup   zmm16, zmm28
    vshufpd    zmm17, zmm28, zmm28, 0xFF
    vmovddup   zmm18, zmm29
    vshufpd    zmm19, zmm29, zmm29, 0xFF
    vmovddup   zmm20, zmm30
    vshufpd    zmm21, zmm30, zmm30, 0xFF
    vmovddup   zmm22, zmm31
    vshufpd    zmm23, zmm31, zmm31, 0xFF
    FFT_DIF4 zmm4, zmm1, zmm16, zmm17, zmm24, zmm3, zmm18, zmm19, zmm26, zmm5, zmm20, zmm21, zmm27, zmm25, zmm22, zmm23

    vmovdqa64  zmm16, [rip + .Lconst_idx_pair_lo]
    vmovdqa64  zmm17, [rip + .Lconst_idx_pair_hi]
    vmovapd    zmm0,  zmm4
    vpermt2pd  zmm0,  zmm16, zmm1
    vpermt2pd  zmm4,  zmm17, zmm1
    vmovapd    zmm2,  zmm24
    vpermt2pd  zmm2,  zmm16, zmm3
    vpermt2pd  zmm24, zmm17, zmm3
    vmovapd    zmm18, zmm26
    vpermt2pd  zmm18, zmm16, zmm5
    vpermt2pd  zmm26, zmm17, zmm5
    vmovapd    zmm19, zmm27
    vpermt2pd  zmm19, zmm16, zmm25
    vpermt2pd  zmm27, zmm17, zmm25
    vmovupd  [rdi + rax + 0],   zmm0
    vmovupd  [rdi + rax + 64],  zmm4
    vmovupd  [rdi + rax + 128], zmm2
    vmovupd  [rdi + rax + 192], zmm24
    vmovupd  [rdi + rax + 256], zmm18
    vmovupd  [rdi + rax + 320], zmm26
    vmovupd  [rdi + rax + 384], zmm19
    vmovupd  [rdi + rax + 448], zmm27

    add  r10, 2
    cmp  r10, r8
    jb   .Lfftfwd_m8_m4_m2_m1_vec2
    jmp  .Lfftfwd_next_sub

.p2align 4
.Lfftfwd_m8_m4_m2_m1_vec:
    mov  rax, r10
    shl  rax, 8                         // j * 256
    vmovupd  zmm0, [rdi + rax + 0]      // [c0..c3]
    vmovupd  zmm1, [rdi + rax + 64]     // [c4..c7]
    vmovupd  zmm2, [rdi + rax + 128]    // [c8..c11]
    vmovupd  zmm3, [rdi + rax + 192]    // [c12..c15]

    lea  rcx, [rbx + r10]
    shl  rcx, 4                         // (k_m8 + j) * 16

    // Stage m = 8:
    vbroadcastsd zmm16, [rsi + rcx + 0]
    vbroadcastsd zmm17, [rsi + rcx + 8]
    FFT_DIF2 zmm0, zmm2, zmm16, zmm17, zmm1, zmm3, zmm16, zmm17

    // Stage m = 4:
    vbroadcastsd zmm16, [rsi + 2*rcx + 0]
    vbroadcastsd zmm17, [rsi + 2*rcx + 8]
    vbroadcastsd zmm18, [rsi + 2*rcx + 16]
    vbroadcastsd zmm19, [rsi + 2*rcx + 24]
    FFT_DIF2 zmm0, zmm1, zmm16, zmm17, zmm2, zmm3, zmm18, zmm19

    // Stage m = 2 across both 8-complex halves:
    vshuff64x2 zmm4,  zmm0,  zmm1,  0x44
    vshuff64x2 zmm5,  zmm0,  zmm1,  0xEE
    vshuff64x2 zmm24, zmm2,  zmm3,  0x44
    vshuff64x2 zmm25, zmm2,  zmm3,  0xEE
    vmovupd    zmm20, [rsi + 4*rcx]
    vshuff64x2 zmm21, zmm20, zmm20, 0x50
    vshuff64x2 zmm22, zmm20, zmm20, 0xFA
    vmovddup   zmm16, zmm21
    vshufpd    zmm17, zmm21, zmm21, 0xFF
    vmovddup   zmm18, zmm22
    vshufpd    zmm19, zmm22, zmm22, 0xFF
    FFT_DIF2 zmm4, zmm5, zmm16, zmm17, zmm24, zmm25, zmm18, zmm19

    // Stage m = 1 across all 8 pairs:
    vshuff64x2 zmm0,  zmm4,  zmm5,  0x88
    vshuff64x2 zmm1,  zmm4,  zmm5,  0xDD
    vshuff64x2 zmm2,  zmm24, zmm25, 0x88
    vshuff64x2 zmm3,  zmm24, zmm25, 0xDD
    vmovupd    zmm20, [rsi + 8*rcx + 0]
    vmovupd    zmm21, [rsi + 8*rcx + 64]
    vshuff64x2 zmm20, zmm20, zmm20, 0xD8
    vshuff64x2 zmm21, zmm21, zmm21, 0xD8
    vmovddup   zmm16, zmm20
    vshufpd    zmm17, zmm20, zmm20, 0xFF
    vmovddup   zmm18, zmm21
    vshufpd    zmm19, zmm21, zmm21, 0xFF
    FFT_DIF2 zmm0, zmm1, zmm16, zmm17, zmm2, zmm3, zmm18, zmm19

    vshuff64x2 zmm4,  zmm0,  zmm1,  0x88
    vshuff64x2 zmm5,  zmm0,  zmm1,  0xDD
    vshuff64x2 zmm24, zmm2,  zmm3,  0x88
    vshuff64x2 zmm25, zmm2,  zmm3,  0xDD
    vshuff64x2 zmm4,  zmm4,  zmm4,  0xD8
    vshuff64x2 zmm5,  zmm5,  zmm5,  0xD8
    vshuff64x2 zmm24, zmm24, zmm24, 0xD8
    vshuff64x2 zmm25, zmm25, zmm25, 0xD8
    vmovupd  [rdi + rax + 0],   zmm4
    vmovupd  [rdi + rax + 64],  zmm5
    vmovupd  [rdi + rax + 128], zmm24
    vmovupd  [rdi + rax + 192], zmm25

    inc  r10
    cmp  r10, r8
    jb   .Lfftfwd_m8_m4_m2_m1_vec
    jmp  .Lfftfwd_next_sub

.Lfftfwd_chk_m4:
    cmp  r9,  4
    jb   .Lfftfwd_m2_m1

    xor  r10d, r10d                     // j = 0 .. r8
    cmp  r8,  2
    jb   .Lfftfwd_m4_m2_m1_vec
    vmovdqa64 zmm26, [rip + .Lconst_idx_pair_lo]
    vmovdqa64 zmm27, [rip + .Lconst_idx_pair_hi]

.p2align 4
.Lfftfwd_m4_m2_m1_vec2:
    mov  rax, r10
    shl  rax, 7                         // j * 128
    vmovupd  zmm0, [rdi + rax + 0]      // block j:   [c0..c3]
    vmovupd  zmm1, [rdi + rax + 64]     // block j:   [c4..c7]
    vmovupd  zmm2, [rdi + rax + 128]    // block j+1: [d0..d3]
    vmovupd  zmm3, [rdi + rax + 192]    // block j+1: [d4..d7]

    lea  rcx, [rbx + r10]
    shl  rcx, 4                         // (k_m4 + j) * 16

    // Stage m = 4 across blocks j and j+1:
    vbroadcastsd zmm16, [rsi + rcx + 0]
    vbroadcastsd zmm17, [rsi + rcx + 8]
    vbroadcastsd zmm18, [rsi + rcx + 16]
    vbroadcastsd zmm19, [rsi + rcx + 24]
    FFT_DIF2 zmm0, zmm1, zmm16, zmm17, zmm2, zmm3, zmm18, zmm19

    // Stage m = 2 across all 4 quarters:
    vshuff64x2 zmm4,  zmm0,  zmm1,  0x44
    vshuff64x2 zmm5,  zmm0,  zmm1,  0xEE
    vshuff64x2 zmm24, zmm2,  zmm3,  0x44
    vshuff64x2 zmm25, zmm2,  zmm3,  0xEE
    vmovupd    zmm20, [rsi + 2*rcx]
    vshuff64x2 zmm21, zmm20, zmm20, 0x50
    vshuff64x2 zmm22, zmm20, zmm20, 0xFA
    vmovddup   zmm16, zmm21
    vshufpd    zmm17, zmm21, zmm21, 0xFF
    vmovddup   zmm18, zmm22
    vshufpd    zmm19, zmm22, zmm22, 0xFF
    FFT_DIF2 zmm4, zmm5, zmm16, zmm17, zmm24, zmm25, zmm18, zmm19

    // Stage m = 1 across all 8 pairs:
    vshuff64x2 zmm0,  zmm4,  zmm5,  0x88
    vshuff64x2 zmm1,  zmm4,  zmm5,  0xDD
    vshuff64x2 zmm2,  zmm24, zmm25, 0x88
    vshuff64x2 zmm3,  zmm24, zmm25, 0xDD
    vmovupd    zmm20, [rsi + 4*rcx + 0]
    vmovupd    zmm21, [rsi + 4*rcx + 64]
    vshuff64x2 zmm20, zmm20, zmm20, 0xD8
    vshuff64x2 zmm21, zmm21, zmm21, 0xD8
    vmovddup   zmm16, zmm20
    vshufpd    zmm17, zmm20, zmm20, 0xFF
    vmovddup   zmm18, zmm21
    vshufpd    zmm19, zmm21, zmm21, 0xFF
    FFT_DIF2 zmm0, zmm1, zmm16, zmm17, zmm2, zmm3, zmm18, zmm19

    vmovapd   zmm4,  zmm0
    vpermt2pd zmm4,  zmm26, zmm1
    vpermt2pd zmm0,  zmm27, zmm1
    vmovapd   zmm24, zmm2
    vpermt2pd zmm24, zmm26, zmm3
    vpermt2pd zmm2,  zmm27, zmm3
    vmovupd  [rdi + rax + 0],   zmm4
    vmovupd  [rdi + rax + 64],  zmm0
    vmovupd  [rdi + rax + 128], zmm24
    vmovupd  [rdi + rax + 192], zmm2

    add  r10, 2
    cmp  r10, r8
    jb   .Lfftfwd_m4_m2_m1_vec2
    jmp  .Lfftfwd_next_sub

.p2align 4
.Lfftfwd_m4_m2_m1_vec:
    mov  rax, r10
    shl  rax, 7                         // j * 128
    vmovupd  zmm0, [rdi + rax + 0]      // [c0, c1, c2, c3]
    vmovupd  zmm1, [rdi + rax + 64]     // [c4, c5, c6, c7]

    // Stage m = 4:
    lea  rcx, [rbx + r10]
    shl  rcx, 4                         // (k_m4 + j) * 16
    vbroadcastsd zmm16, [rsi + rcx + 0]
    vbroadcastsd zmm17, [rsi + rcx + 8]
    vshufpd  zmm4, zmm1, zmm1, 0x55
    vmulpd   zmm4, zmm4, zmm17
    vfmaddsub231pd zmm4, zmm1, zmm16
    vsubpd   zmm1, zmm0, zmm4
    vaddpd   zmm0, zmm0, zmm4

    // Stage m = 2 across both 4-complex halves:
    vshuff64x2 zmm2,  zmm0, zmm1, 0x44
    vshuff64x2 zmm3,  zmm0, zmm1, 0xEE
    vmovupd    ymm5,  [rsi + 2*rcx]
    vshuff64x2 zmm5,  zmm5, zmm5, 0x50
    vmovddup   zmm16, zmm5
    vshufpd    zmm17, zmm5, zmm5, 0xFF
    vshufpd    zmm4,  zmm3, zmm3, 0x55
    vmulpd     zmm4,  zmm4, zmm17
    vfmaddsub231pd zmm4, zmm3, zmm16
    vaddpd     zmm0,  zmm2, zmm4
    vsubpd     zmm1,  zmm2, zmm4

    // Stage m = 1 across all 4 pairs:
    vshuff64x2 zmm2,  zmm0, zmm1, 0x88
    vshuff64x2 zmm3,  zmm0, zmm1, 0xDD
    vmovupd    zmm5,  [rsi + 4*rcx]
    vshuff64x2 zmm5,  zmm5, zmm5, 0xD8
    vmovddup   zmm16, zmm5
    vshufpd    zmm17, zmm5, zmm5, 0xFF
    vshufpd    zmm4,  zmm3, zmm3, 0x55
    vmulpd     zmm4,  zmm4, zmm17
    vfmaddsub231pd zmm4, zmm3, zmm16
    vaddpd     zmm0,  zmm2, zmm4
    vsubpd     zmm1,  zmm2, zmm4

    vshuff64x2 zmm2, zmm0, zmm1, 0x88
    vshuff64x2 zmm2, zmm2, zmm2, 0xD8
    vshuff64x2 zmm3, zmm0, zmm1, 0xDD
    vshuff64x2 zmm3, zmm3, zmm3, 0xD8
    vmovupd  [rdi + rax + 0],  zmm2
    vmovupd  [rdi + rax + 64], zmm3

    inc  r10
    cmp  r10, r8
    jb   .Lfftfwd_m4_m2_m1_vec
    jmp  .Lfftfwd_next_sub

    // 2. Full 512-bit ZMM fused pass for final stages m = 2 and m = 1 (8 complex / 2 groups per iter).
    // Here r8 == sub_n / 4 (groups), rbx == k_m2, 2 * rbx == k_m1.
.Lfftfwd_m2_m1:
    lea  r9,  [rbx + rbx]               // k_m1 = 2 * k_m2
    xor  r10d, r10d                     // g = 0
    cmp  r8,  2
    jb   .Lfftfwd_m2_m1_tail1

.p2align 4
.Lfftfwd_m2_m1_vec2:
    mov  rax, r10
    shl  rax, 6
    vmovupd  zmm0, [rdi + rax + 0]      // [c0, c1, c2, c3]
    vmovupd  zmm1, [rdi + rax + 64]     // [c4, c5, c6, c7]

    // Stage m = 2 across 2 groups: u = [c0, c1, c4, c5], x = [c2, c3, c6, c7]
    vshuff64x2 zmm2, zmm0, zmm1, 0x44
    vshuff64x2 zmm3, zmm0, zmm1, 0xEE
    lea  rcx, [rbx + r10]
    shl  rcx, 4
    vmovupd    ymm5,  [rsi + rcx]       // [wg0, wg1]
    vshuff64x2 zmm5,  zmm5, zmm5, 0x50  // [wg0, wg0, wg1, wg1]
    vmovddup   zmm16, zmm5
    vshufpd    zmm17, zmm5, zmm5, 0xFF
    vshufpd    zmm4,  zmm3, zmm3, 0x55
    vmulpd     zmm4,  zmm4, zmm17
    vfmaddsub231pd zmm4, zmm3, zmm16
    vaddpd     zmm0,  zmm2, zmm4        // [c0', c1', c4', c5']
    vsubpd     zmm1,  zmm2, zmm4        // [c2', c3', c6', c7']

    // Stage m = 1 across 2 groups: u = [c0', c4', c2', c6'], x = [c1', c5', c3', c7']
    vshuff64x2 zmm2, zmm0, zmm1, 0x88
    vshuff64x2 zmm3, zmm0, zmm1, 0xDD
    lea  rcx, [r10 + r10]
    add  rcx, r9
    shl  rcx, 4
    vmovupd    zmm5,  [rsi + rcx]       // [w0, w1, w2, w3]
    vshuff64x2 zmm5,  zmm5, zmm5, 0xD8  // [w0, w2, w1, w3]
    vmovddup   zmm16, zmm5
    vshufpd    zmm17, zmm5, zmm5, 0xFF
    vshufpd    zmm4,  zmm3, zmm3, 0x55
    vmulpd     zmm4,  zmm4, zmm17
    vfmaddsub231pd zmm4, zmm3, zmm16
    vaddpd     zmm0,  zmm2, zmm4        // [c0'', c4'', c2'', c6'']
    vsubpd     zmm1,  zmm2, zmm4        // [c1'', c5'', c3'', c7'']

    vshuff64x2 zmm2, zmm0, zmm1, 0x88   // [c0'', c2'', c1'', c3'']
    vshuff64x2 zmm2, zmm2, zmm2, 0xD8   // [c0'', c1'', c2'', c3'']
    vshuff64x2 zmm3, zmm0, zmm1, 0xDD   // [c4'', c6'', c5'', c7'']
    vshuff64x2 zmm3, zmm3, zmm3, 0xD8   // [c4'', c5'', c6'', c7'']
    vmovupd  [rdi + rax + 0],  zmm2
    vmovupd  [rdi + rax + 64], zmm3

    add  r10, 2
    cmp  r10, r8
    jb   .Lfftfwd_m2_m1_vec2
    jmp  .Lfftfwd_next_sub

.Lfftfwd_m2_m1_tail1:
    // Single group fallback only when orig_n == 4 (r8 == 1, r10 == 0):
    vmovupd  zmm0, [rdi]
    vextractf64x4 ymm1, zmm0, 1
    mov  rcx, rbx
    shl  rcx, 4
    vbroadcastsd ymm16, [rsi + rcx + 0]
    vbroadcastsd ymm17, [rsi + rcx + 8]
    vshufpd  ymm2, ymm1, ymm1, 0x05
    vmulpd   ymm2, ymm2, ymm17
    vfmaddsub231pd ymm2, ymm1, ymm16
    vaddpd   ymm3, ymm0, ymm2
    vsubpd   ymm4, ymm0, ymm2

    mov  rcx, r9
    shl  rcx, 4
    vmovupd  ymm5,  [rsi + rcx]
    vmovddup ymm16, ymm5
    vshufpd  ymm17, ymm5, ymm5, 0x0F
    vshuff64x2 ymm0, ymm3, ymm4, 0x00
    vshuff64x2 ymm1, ymm3, ymm4, 0x03
    vshufpd  ymm2, ymm1, ymm1, 0x05
    vmulpd   ymm2, ymm2, ymm17
    vfmaddsub231pd ymm2, ymm1, ymm16
    vaddpd   ymm3, ymm0, ymm2
    vsubpd   ymm4, ymm0, ymm2
    vshuff64x2 ymm0, ymm3, ymm4, 0x00
    vshuff64x2 ymm1, ymm3, ymm4, 0x03
    vinsertf64x4 zmm0, zmm0, ymm1, 1
    vmovupd  [rdi], zmm0

.Lfftfwd_next_sub:
    mov  rax, [rsp + 24]
    inc  rax
    cmp  rax, [rsp + 16]
    jae  .Lfftfwd_done
    mov  [rsp + 24], rax
    jmp  .Lfftfwd_sub_loop

.Lfftfwd_n2:
    vmovupd  xmm0,  [rdi + 0]
    vmovupd  xmm1,  [rdi + 16]
    vmovddup xmm16, [rsi + 16]
    vmovddup xmm17, [rsi + 24]
    vshufpd  xmm2,  xmm1, xmm1, 0x01
    vmulpd   xmm2,  xmm2, xmm17
    vfmaddsub231pd xmm2, xmm1, xmm16
    vaddpd   xmm3,  xmm0, xmm2
    vsubpd   xmm4,  xmm0, xmm2
    vmovupd  [rdi + 0],  xmm3
    vmovupd  [rdi + 16], xmm4

.Lfftfwd_done:
    VEC_LEAVE_FFT64

// Fused 6-stage Radix-64 DIT bottom body (m = 1, 2, 4, 8, 16, 32) on 64 complex points in zmm0..zmm15.
// Inputs: rdi = base buf, rsi = inv_twiddles, rbx = k_m32, r10 = block index j; preserves zmm22 = 1.0 / orig_n!
.macro FFT_INV_BOT6_BODY
    mov  rax, r10
    shl  rax, 10                        // j * 1024
    lea  rcx, [rbx + r10]
    shl  rcx, 6                         // 4 * (k_m32 + j) * 16 = k_m8 * 16

    // First half (32 complex = zmm0..zmm7): stages m = 1, 2, 4
    vmovupd  zmm0,  [rdi + rax + 0]
    vmovupd  zmm1,  [rdi + rax + 64]
    vmovupd  zmm2,  [rdi + rax + 128]
    vmovupd  zmm3,  [rdi + rax + 192]
    vmovupd  zmm4,  [rdi + rax + 256]
    vmovupd  zmm5,  [rdi + rax + 320]
    vmovupd  zmm6,  [rdi + rax + 384]
    vmovupd  zmm7,  [rdi + rax + 448]

    vshuff64x2 zmm25, zmm0,  zmm1,  0x88
    vshuff64x2 zmm1,  zmm0,  zmm1,  0xDD
    vmovapd    zmm0,  zmm25
    vshuff64x2 zmm26, zmm2,  zmm3,  0x88
    vshuff64x2 zmm3,  zmm2,  zmm3,  0xDD
    vmovapd    zmm2,  zmm26
    vshuff64x2 zmm27, zmm4,  zmm5,  0x88
    vshuff64x2 zmm5,  zmm4,  zmm5,  0xDD
    vmovapd    zmm4,  zmm27
    vshuff64x2 zmm28, zmm6,  zmm7,  0x88
    vshuff64x2 zmm7,  zmm6,  zmm7,  0xDD
    vmovapd    zmm6,  zmm28
    vmovupd    zmm16, [rsi + 8*rcx + 0]
    vmovupd    zmm18, [rsi + 8*rcx + 64]
    vmovupd    zmm20, [rsi + 8*rcx + 128]
    vmovupd    zmm23, [rsi + 8*rcx + 192]
    vmovddup   zmm17, zmm16
    vshufpd    zmm16, zmm16, zmm16, 0xFF
    vmovddup   zmm19, zmm18
    vshufpd    zmm18, zmm18, zmm18, 0xFF
    vmovddup   zmm21, zmm20
    vshufpd    zmm20, zmm20, zmm20, 0xFF
    vmovddup   zmm24, zmm23
    vshufpd    zmm23, zmm23, zmm23, 0xFF
    FFT_DIT4 zmm0, zmm1, zmm17, zmm16, zmm2, zmm3, zmm19, zmm18, zmm4, zmm5, zmm21, zmm20, zmm6, zmm7, zmm24, zmm23

    vshuff64x2 zmm25, zmm0,  zmm1,  0x88
    vshuff64x2 zmm1,  zmm0,  zmm1,  0xDD
    vmovapd    zmm0,  zmm25
    vshuff64x2 zmm26, zmm2,  zmm3,  0x88
    vshuff64x2 zmm3,  zmm2,  zmm3,  0xDD
    vmovapd    zmm2,  zmm26
    vshuff64x2 zmm27, zmm4,  zmm5,  0x88
    vshuff64x2 zmm5,  zmm4,  zmm5,  0xDD
    vmovapd    zmm4,  zmm27
    vshuff64x2 zmm28, zmm6,  zmm7,  0x88
    vshuff64x2 zmm7,  zmm6,  zmm7,  0xDD
    vmovapd    zmm6,  zmm28
    vmovupd    zmm25, [rsi + 4*rcx + 0]
    vmovupd    zmm26, [rsi + 4*rcx + 64]
    vshuff64x2 zmm16, zmm25, zmm25, 0x44
    vshuff64x2 zmm18, zmm25, zmm25, 0xEE
    vshuff64x2 zmm20, zmm26, zmm26, 0x44
    vshuff64x2 zmm23, zmm26, zmm26, 0xEE
    vmovddup   zmm17, zmm16
    vshufpd    zmm16, zmm16, zmm16, 0xFF
    vmovddup   zmm19, zmm18
    vshufpd    zmm18, zmm18, zmm18, 0xFF
    vmovddup   zmm21, zmm20
    vshufpd    zmm20, zmm20, zmm20, 0xFF
    vmovddup   zmm24, zmm23
    vshufpd    zmm23, zmm23, zmm23, 0xFF
    FFT_DIT4 zmm0, zmm1, zmm17, zmm16, zmm2, zmm3, zmm19, zmm18, zmm4, zmm5, zmm21, zmm20, zmm6, zmm7, zmm24, zmm23
    vshuff64x2 zmm25, zmm0,  zmm1,  0x88
    vshuff64x2 zmm1,  zmm0,  zmm1,  0xDD
    vmovapd    zmm0,  zmm25
    vshuff64x2 zmm26, zmm2,  zmm3,  0x88
    vshuff64x2 zmm3,  zmm2,  zmm3,  0xDD
    vmovapd    zmm2,  zmm26
    vshuff64x2 zmm27, zmm4,  zmm5,  0x88
    vshuff64x2 zmm5,  zmm4,  zmm5,  0xDD
    vmovapd    zmm4,  zmm27
    vshuff64x2 zmm28, zmm6,  zmm7,  0x88
    vshuff64x2 zmm7,  zmm6,  zmm7,  0xDD
    vmovapd    zmm6,  zmm28

    vbroadcastsd zmm16, [rsi + 2*rcx + 0]
    vbroadcastsd zmm17, [rsi + 2*rcx + 8]
    vbroadcastsd zmm18, [rsi + 2*rcx + 16]
    vbroadcastsd zmm19, [rsi + 2*rcx + 24]
    vbroadcastsd zmm20, [rsi + 2*rcx + 32]
    vbroadcastsd zmm21, [rsi + 2*rcx + 40]
    vbroadcastsd zmm23, [rsi + 2*rcx + 48]
    vbroadcastsd zmm24, [rsi + 2*rcx + 56]
    FFT_DIT4 zmm0, zmm1, zmm16, zmm17, zmm2, zmm3, zmm18, zmm19, zmm4, zmm5, zmm20, zmm21, zmm6, zmm7, zmm23, zmm24

    // Second half (32 complex = zmm8..zmm15): stages m = 1, 2, 4
    vmovupd  zmm8,  [rdi + rax + 512]
    vmovupd  zmm9,  [rdi + rax + 576]
    vmovupd  zmm10, [rdi + rax + 640]
    vmovupd  zmm11, [rdi + rax + 704]
    vmovupd  zmm12, [rdi + rax + 768]
    vmovupd  zmm13, [rdi + rax + 832]
    vmovupd  zmm14, [rdi + rax + 896]
    vmovupd  zmm15, [rdi + rax + 960]

    vshuff64x2 zmm25, zmm8,  zmm9,  0x88
    vshuff64x2 zmm9,  zmm8,  zmm9,  0xDD
    vmovapd    zmm8,  zmm25
    vshuff64x2 zmm26, zmm10, zmm11, 0x88
    vshuff64x2 zmm11, zmm10, zmm11, 0xDD
    vmovapd    zmm10, zmm26
    vshuff64x2 zmm27, zmm12, zmm13, 0x88
    vshuff64x2 zmm13, zmm12, zmm13, 0xDD
    vmovapd    zmm12, zmm27
    vshuff64x2 zmm28, zmm14, zmm15, 0x88
    vshuff64x2 zmm15, zmm14, zmm15, 0xDD
    vmovapd    zmm14, zmm28
    vmovupd    zmm16, [rsi + 8*rcx + 256]
    vmovupd    zmm18, [rsi + 8*rcx + 320]
    vmovupd    zmm20, [rsi + 8*rcx + 384]
    vmovupd    zmm23, [rsi + 8*rcx + 448]
    vmovddup   zmm17, zmm16
    vshufpd    zmm16, zmm16, zmm16, 0xFF
    vmovddup   zmm19, zmm18
    vshufpd    zmm18, zmm18, zmm18, 0xFF
    vmovddup   zmm21, zmm20
    vshufpd    zmm20, zmm20, zmm20, 0xFF
    vmovddup   zmm24, zmm23
    vshufpd    zmm23, zmm23, zmm23, 0xFF
    FFT_DIT4 zmm8, zmm9, zmm17, zmm16, zmm10, zmm11, zmm19, zmm18, zmm12, zmm13, zmm21, zmm20, zmm14, zmm15, zmm24, zmm23

    vshuff64x2 zmm25, zmm8,  zmm9,  0x88
    vshuff64x2 zmm9,  zmm8,  zmm9,  0xDD
    vmovapd    zmm8,  zmm25
    vshuff64x2 zmm26, zmm10, zmm11, 0x88
    vshuff64x2 zmm11, zmm10, zmm11, 0xDD
    vmovapd    zmm10, zmm26
    vshuff64x2 zmm27, zmm12, zmm13, 0x88
    vshuff64x2 zmm13, zmm12, zmm13, 0xDD
    vmovapd    zmm12, zmm27
    vshuff64x2 zmm28, zmm14, zmm15, 0x88
    vshuff64x2 zmm15, zmm14, zmm15, 0xDD
    vmovapd    zmm14, zmm28
    vmovupd    zmm25, [rsi + 4*rcx + 128]
    vmovupd    zmm26, [rsi + 4*rcx + 192]
    vshuff64x2 zmm16, zmm25, zmm25, 0x44
    vshuff64x2 zmm18, zmm25, zmm25, 0xEE
    vshuff64x2 zmm20, zmm26, zmm26, 0x44
    vshuff64x2 zmm23, zmm26, zmm26, 0xEE
    vmovddup   zmm17, zmm16
    vshufpd    zmm16, zmm16, zmm16, 0xFF
    vmovddup   zmm19, zmm18
    vshufpd    zmm18, zmm18, zmm18, 0xFF
    vmovddup   zmm21, zmm20
    vshufpd    zmm20, zmm20, zmm20, 0xFF
    vmovddup   zmm24, zmm23
    vshufpd    zmm23, zmm23, zmm23, 0xFF
    FFT_DIT4 zmm8, zmm9, zmm17, zmm16, zmm10, zmm11, zmm19, zmm18, zmm12, zmm13, zmm21, zmm20, zmm14, zmm15, zmm24, zmm23
    vshuff64x2 zmm25, zmm8,  zmm9,  0x88
    vshuff64x2 zmm9,  zmm8,  zmm9,  0xDD
    vmovapd    zmm8,  zmm25
    vshuff64x2 zmm26, zmm10, zmm11, 0x88
    vshuff64x2 zmm11, zmm10, zmm11, 0xDD
    vmovapd    zmm10, zmm26
    vshuff64x2 zmm27, zmm12, zmm13, 0x88
    vshuff64x2 zmm13, zmm12, zmm13, 0xDD
    vmovapd    zmm12, zmm27
    vshuff64x2 zmm28, zmm14, zmm15, 0x88
    vshuff64x2 zmm15, zmm14, zmm15, 0xDD
    vmovapd    zmm14, zmm28

    vbroadcastsd zmm16, [rsi + 2*rcx + 64]
    vbroadcastsd zmm17, [rsi + 2*rcx + 72]
    vbroadcastsd zmm18, [rsi + 2*rcx + 80]
    vbroadcastsd zmm19, [rsi + 2*rcx + 88]
    vbroadcastsd zmm20, [rsi + 2*rcx + 96]
    vbroadcastsd zmm21, [rsi + 2*rcx + 104]
    vbroadcastsd zmm23, [rsi + 2*rcx + 112]
    vbroadcastsd zmm24, [rsi + 2*rcx + 120]
    FFT_DIT4 zmm8, zmm9, zmm16, zmm17, zmm10, zmm11, zmm18, zmm19, zmm12, zmm13, zmm20, zmm21, zmm14, zmm15, zmm23, zmm24

    // Stage m = 8 across all 4 16-complex quarters:
    vbroadcastsd zmm16, [rsi + rcx + 0]
    vbroadcastsd zmm17, [rsi + rcx + 8]
    vbroadcastsd zmm18, [rsi + rcx + 16]
    vbroadcastsd zmm19, [rsi + rcx + 24]
    vbroadcastsd zmm20, [rsi + rcx + 32]
    vbroadcastsd zmm21, [rsi + rcx + 40]
    vbroadcastsd zmm23, [rsi + rcx + 48]
    vbroadcastsd zmm24, [rsi + rcx + 56]
    FFT_DIT4 zmm0, zmm2,  zmm16, zmm17, zmm1, zmm3,  zmm16, zmm17, zmm4,  zmm6,  zmm18, zmm19, zmm5,  zmm7,  zmm18, zmm19
    FFT_DIT4 zmm8, zmm10, zmm20, zmm21, zmm9, zmm11, zmm20, zmm21, zmm12, zmm14, zmm23, zmm24, zmm13, zmm15, zmm23, zmm24

    // Stage m = 16 across halves [0..15]/[16..31] and [32..47]/[48..63]:
    shr  rcx, 1
    vbroadcastsd zmm16, [rsi + rcx + 0]
    vbroadcastsd zmm17, [rsi + rcx + 8]
    vbroadcastsd zmm18, [rsi + rcx + 16]
    vbroadcastsd zmm19, [rsi + rcx + 24]
    FFT_DIT4 zmm0, zmm4,  zmm16, zmm17, zmm1, zmm5,  zmm16, zmm17, zmm2,  zmm6,  zmm16, zmm17, zmm3,  zmm7,  zmm16, zmm17
    FFT_DIT4 zmm8, zmm12, zmm18, zmm19, zmm9, zmm13, zmm18, zmm19, zmm10, zmm14, zmm18, zmm19, zmm11, zmm15, zmm18, zmm19

    // Stage m = 32 across the 64-complex block:
    shr  rcx, 1
    vbroadcastsd zmm16, [rsi + rcx + 0]
    vbroadcastsd zmm17, [rsi + rcx + 8]
    FFT_DIT4 zmm0, zmm8,  zmm16, zmm17, zmm1, zmm9,  zmm16, zmm17, zmm2, zmm10, zmm16, zmm17, zmm3, zmm11, zmm16, zmm17
    FFT_DIT4 zmm4, zmm12, zmm16, zmm17, zmm5, zmm13, zmm16, zmm17, zmm6, zmm14, zmm16, zmm17, zmm7, zmm15, zmm16, zmm17
.endm

// [8] fft_inv(buf: rdi, inv_twiddles: rsi, n_complex: rdx, l1_sub_n: rcx)
LOCAL_FN supi_k_fft_inv
    VEC_ENTER_FFT64
    cmp  rdx, 1
    jbe  .Lfftinv_done
    cmp  rdx, 2
    je   .Lfftinv_n2

    mov  r11, rcx                       // preserve l1_sub_n across zmm22 exponent setup

    // Precompute exact reciprocal 1.0 / n_complex in zmm22 via power-of-two IEEE-754 exponent!
    tzcnt rcx, rdx
    mov   eax, 1023
    sub   eax, ecx
    shl   rax, 52
    vmovq xmm22, rax
    vbroadcastsd zmm22, xmm22

    mov  [rsp + 0], rdi                 // orig_buf
    mov  [rsp + 8], rdx                 // orig_n
    cmp  r11, rdx
    jae  .Lfftinv_single_blk
    mov  eax, 64
    cmp  r11, 64
    cmovb r11, rax
    lzcnt rax, r11
    mov  ecx, 63
    sub  ecx, eax
    mov  eax, 1
    shl  rax, cl                        // sub_cap = largest power of two >= 64 and <= l1_sub_n
    cmp  rdx, rax
    jbe  .Lfftinv_single_blk
    cmp  ecx, 10
    jne  .Lfftinv_large
    tzcnt r8, rdx
    test r8d, 1
    jz   .Lfftinv_large
    dec  ecx
    shr  rax, 1                         // sub_cap = 512 (2 L1 passes + pure R4 top passes for odd log2(n)!)
    jmp  .Lfftinv_large

.Lfftinv_single_blk:
    cmp  rdx, 4
    je   .Lfftinv_m1_m2_n4

    tzcnt rax, rdx
    test  eax, 1
    jnz   .Lfftinv_m1_m2_m4_small

    mov   ecx, eax
    and   ecx, 3
    cmp   ecx, 2
    je    .Lfftinv_m1248_16_32_small

    // Fused 4-stage Radix-16 DIT bottom pass (m = 1, 2, 4, 8 in registers) for orig_n = 16, 256:
    mov  r8,  rdx
    shr  r8,  4                         // blocks = orig_n / 16
    mov  rbx, r8                        // k_m8 = orig_n / 16
    xor  r10d, r10d                     // j = 0
    cmp  r8,  1
    je   .Lfftinv_m1_m2_m4_m8_vec

.p2align 4
.Lfftinv_m1_m2_m4_m8_vec2:
    mov  rax, r10
    shl  rax, 8                         // j * 256
    lea  rcx, [rbx + r10]
    shl  rcx, 4                         // (k_m8 + j) * 16
    vmovupd  zmm0,  [rdi + rax + 0]
    vmovupd  zmm1,  [rdi + rax + 64]
    vmovupd  zmm24, [rdi + rax + 128]
    vmovupd  zmm25, [rdi + rax + 192]
    vmovupd  zmm4,  [rdi + rax + 256]
    vmovupd  zmm5,  [rdi + rax + 320]
    vmovupd  zmm26, [rdi + rax + 384]
    vmovupd  zmm27, [rdi + rax + 448]

    // Stage m = 1 across all 16 pairs (preserving zmm22 = 1.0 / orig_n):
    vshuff64x2 zmm2,  zmm0,  zmm1,  0x88
    vshuff64x2 zmm3,  zmm0,  zmm1,  0xDD
    vshuff64x2 zmm0,  zmm24, zmm25, 0x88
    vshuff64x2 zmm1,  zmm24, zmm25, 0xDD
    vshuff64x2 zmm24, zmm4,  zmm5,  0x88
    vshuff64x2 zmm25, zmm4,  zmm5,  0xDD
    vshuff64x2 zmm4,  zmm26, zmm27, 0x88
    vshuff64x2 zmm5,  zmm26, zmm27, 0xDD
    vmovupd    zmm16, [rsi + 8*rcx + 0]
    vmovupd    zmm18, [rsi + 8*rcx + 64]
    vmovupd    zmm20, [rsi + 8*rcx + 128]
    vmovupd    zmm26, [rsi + 8*rcx + 192]
    vmovddup   zmm17, zmm16
    vshufpd    zmm16, zmm16, zmm16, 0xFF
    vmovddup   zmm19, zmm18
    vshufpd    zmm18, zmm18, zmm18, 0xFF
    vmovddup   zmm21, zmm20
    vshufpd    zmm20, zmm20, zmm20, 0xFF
    vmovddup   zmm27, zmm26
    vshufpd    zmm26, zmm26, zmm26, 0xFF
    FFT_DIT4 zmm2, zmm3, zmm17, zmm16, zmm0, zmm1, zmm19, zmm18, zmm24, zmm25, zmm21, zmm20, zmm4, zmm5, zmm27, zmm26

    // Stage m = 2 across all 8 quarters:
    vshuff64x2 zmm26, zmm2,  zmm3,  0x88
    vshuff64x2 zmm3,  zmm2,  zmm3,  0xDD
    vshuff64x2 zmm27, zmm0,  zmm1,  0x88
    vshuff64x2 zmm1,  zmm0,  zmm1,  0xDD
    vshuff64x2 zmm0,  zmm24, zmm25, 0x88
    vshuff64x2 zmm25, zmm24, zmm25, 0xDD
    vshuff64x2 zmm2,  zmm4,  zmm5,  0x88
    vshuff64x2 zmm5,  zmm4,  zmm5,  0xDD
    vmovupd    zmm4,  [rsi + 4*rcx + 0]
    vmovupd    zmm24, [rsi + 4*rcx + 64]
    vshuff64x2 zmm16, zmm4,  zmm4,  0x44
    vshuff64x2 zmm18, zmm4,  zmm4,  0xEE
    vshuff64x2 zmm20, zmm24, zmm24, 0x44
    vshuff64x2 zmm23, zmm24, zmm24, 0xEE
    vmovddup   zmm17, zmm16
    vshufpd    zmm16, zmm16, zmm16, 0xFF
    vmovddup   zmm19, zmm18
    vshufpd    zmm18, zmm18, zmm18, 0xFF
    vmovddup   zmm21, zmm20
    vshufpd    zmm20, zmm20, zmm20, 0xFF
    vmovddup   zmm4,  zmm23
    vshufpd    zmm23, zmm23, zmm23, 0xFF
    FFT_DIT4 zmm26, zmm3, zmm17, zmm16, zmm27, zmm1, zmm19, zmm18, zmm0, zmm25, zmm21, zmm20, zmm2, zmm5, zmm4, zmm23
    vshuff64x2 zmm4,  zmm26, zmm3,  0x88
    vshuff64x2 zmm3,  zmm26, zmm3,  0xDD
    vshuff64x2 zmm24, zmm27, zmm1,  0x88
    vshuff64x2 zmm1,  zmm27, zmm1,  0xDD
    vshuff64x2 zmm26, zmm0,  zmm25, 0x88
    vshuff64x2 zmm25, zmm0,  zmm25, 0xDD
    vshuff64x2 zmm27, zmm2,  zmm5,  0x88
    vshuff64x2 zmm5,  zmm2,  zmm5,  0xDD

    // Stage m = 4 across all 4 halves:
    vbroadcastsd zmm16, [rsi + 2*rcx + 0]
    vbroadcastsd zmm17, [rsi + 2*rcx + 8]
    vbroadcastsd zmm18, [rsi + 2*rcx + 16]
    vbroadcastsd zmm19, [rsi + 2*rcx + 24]
    vbroadcastsd zmm20, [rsi + 2*rcx + 32]
    vbroadcastsd zmm21, [rsi + 2*rcx + 40]
    vbroadcastsd zmm0,  [rsi + 2*rcx + 48]
    vbroadcastsd zmm2,  [rsi + 2*rcx + 56]
    FFT_DIT4 zmm4, zmm3, zmm16, zmm17, zmm24, zmm1, zmm18, zmm19, zmm26, zmm25, zmm20, zmm21, zmm27, zmm5, zmm0, zmm2

    // Stage m = 8 across blocks j and j+1:
    vbroadcastsd zmm16, [rsi + rcx + 0]
    vbroadcastsd zmm17, [rsi + rcx + 8]
    vbroadcastsd zmm18, [rsi + rcx + 16]
    vbroadcastsd zmm19, [rsi + rcx + 24]
    FFT_DIT4 zmm4, zmm24, zmm16, zmm17, zmm3, zmm1, zmm16, zmm17, zmm26, zmm27, zmm18, zmm19, zmm25, zmm5, zmm18, zmm19

    vmovupd  [rdi + rax + 0],   zmm4
    vmovupd  [rdi + rax + 64],  zmm3
    vmovupd  [rdi + rax + 128], zmm24
    vmovupd  [rdi + rax + 192], zmm1
    vmovupd  [rdi + rax + 256], zmm26
    vmovupd  [rdi + rax + 320], zmm25
    vmovupd  [rdi + rax + 384], zmm27
    vmovupd  [rdi + rax + 448], zmm5

    add  r10, 2
    cmp  r10, r8
    jb   .Lfftinv_m1_m2_m4_m8_vec2
    jmp  .Lfftinv_m1248_after

.p2align 4
.Lfftinv_m1_m2_m4_m8_vec:
    mov  rax, r10
    shl  rax, 8                         // j * 256
    lea  rcx, [rbx + r10]
    shl  rcx, 4                         // (k_m8 + j) * 16
    vmovupd  zmm0,  [rdi + rax + 0]
    vmovupd  zmm1,  [rdi + rax + 64]
    vmovupd  zmm24, [rdi + rax + 128]
    vmovupd  zmm25, [rdi + rax + 192]

    // Stage m = 1 across all 8 pairs:
    vshuff64x2 zmm2,  zmm0,  zmm1,  0x88
    vshuff64x2 zmm3,  zmm0,  zmm1,  0xDD
    vshuff64x2 zmm26, zmm24, zmm25, 0x88
    vshuff64x2 zmm27, zmm24, zmm25, 0xDD
    vmovupd    zmm16, [rsi + 8*rcx + 0]
    vmovupd    zmm18, [rsi + 8*rcx + 64]
    vmovddup   zmm17, zmm16
    vshufpd    zmm16, zmm16, zmm16, 0xFF
    vmovddup   zmm19, zmm18
    vshufpd    zmm18, zmm18, zmm18, 0xFF
    FFT_DIT2 zmm2, zmm3, zmm17, zmm16, zmm26, zmm27, zmm19, zmm18

    // Stage m = 2 across all 4 quarters:
    vshuff64x2 zmm0,  zmm2,  zmm3,  0x88
    vshuff64x2 zmm1,  zmm2,  zmm3,  0xDD
    vshuff64x2 zmm24, zmm26, zmm27, 0x88
    vshuff64x2 zmm25, zmm26, zmm27, 0xDD
    vmovupd    zmm20, [rsi + 4*rcx]
    vshuff64x2 zmm16, zmm20, zmm20, 0x44
    vshuff64x2 zmm18, zmm20, zmm20, 0xEE
    vmovddup   zmm17, zmm16
    vshufpd    zmm16, zmm16, zmm16, 0xFF
    vmovddup   zmm19, zmm18
    vshufpd    zmm18, zmm18, zmm18, 0xFF
    FFT_DIT2 zmm0, zmm1, zmm17, zmm16, zmm24, zmm25, zmm19, zmm18
    vshuff64x2 zmm2,  zmm0,  zmm1,  0x88
    vshuff64x2 zmm3,  zmm0,  zmm1,  0xDD
    vshuff64x2 zmm26, zmm24, zmm25, 0x88
    vshuff64x2 zmm27, zmm24, zmm25, 0xDD

    // Stage m = 4 across both 8-complex halves:
    vbroadcastsd zmm16, [rsi + 2*rcx + 0]
    vbroadcastsd zmm17, [rsi + 2*rcx + 8]
    vbroadcastsd zmm18, [rsi + 2*rcx + 16]
    vbroadcastsd zmm19, [rsi + 2*rcx + 24]
    FFT_DIT2 zmm2, zmm3, zmm16, zmm17, zmm26, zmm27, zmm18, zmm19

    // Stage m = 8 across the 16-complex block:
    vbroadcastsd zmm16, [rsi + rcx + 0]
    vbroadcastsd zmm17, [rsi + rcx + 8]
    FFT_DIT2 zmm2, zmm26, zmm16, zmm17, zmm3, zmm27, zmm16, zmm17

    cmp  r8, 1
    je   .Lfftinv_m1248_n16
    vmovupd  [rdi + rax + 0],   zmm2
    vmovupd  [rdi + rax + 64],  zmm3
    vmovupd  [rdi + rax + 128], zmm26
    vmovupd  [rdi + rax + 192], zmm27

    inc  r10
    cmp  r10, r8
    jb   .Lfftinv_m1_m2_m4_m8_vec

.Lfftinv_m1248_after:
    mov  r9,  16                        // m = 16
    mov  r8,  rdx
    shr  r8,  8                         // b_local = orig_n / 256
    mov  rbx, r8                        // k_base = b_local
    mov  [rsp + 32], rdx                // limit_n = orig_n
    mov  qword ptr [rsp + 40], 1        // is_small = 1
    jmp  .Lfftinv_r16_check

.Lfftinv_m1248_n16:
    vmulpd   zmm2,  zmm2,  zmm22
    vmulpd   zmm3,  zmm3,  zmm22
    vmulpd   zmm26, zmm26, zmm22
    vmulpd   zmm27, zmm27, zmm22
    vmovupd  [rdi + 0],   zmm2
    vmovupd  [rdi + 64],  zmm3
    vmovupd  [rdi + 128], zmm26
    vmovupd  [rdi + 192], zmm27
    jmp  .Lfftinv_done

.Lfftinv_m1248_16_32_small:
    // Fused 6-stage Radix-64 DIT bottom pass (m = 1..32 in registers) for orig_n = 64, 1024:
    // cuts n = 64 to 1 pass and n = 1024 to 2 passes!
    mov  r8,  rdx
    shr  r8,  6                         // blocks = orig_n / 64
    mov  rbx, r8                        // k_m32 = orig_n / 64
    xor  r10d, r10d                     // j = 0
.p2align 6
.Lfftinv_m1248_16_32_small_lp:
    FFT_INV_BOT6_BODY
    cmp  r8,  1
    je   .Lfftinv_m1248_16_32_n64
    vmovupd  [rdi + rax + 0],   zmm0
    vmovupd  [rdi + rax + 64],  zmm1
    vmovupd  [rdi + rax + 128], zmm2
    vmovupd  [rdi + rax + 192], zmm3
    vmovupd  [rdi + rax + 256], zmm4
    vmovupd  [rdi + rax + 320], zmm5
    vmovupd  [rdi + rax + 384], zmm6
    vmovupd  [rdi + rax + 448], zmm7
    vmovupd  [rdi + rax + 512], zmm8
    vmovupd  [rdi + rax + 576], zmm9
    vmovupd  [rdi + rax + 640], zmm10
    vmovupd  [rdi + rax + 704], zmm11
    vmovupd  [rdi + rax + 768], zmm12
    vmovupd  [rdi + rax + 832], zmm13
    vmovupd  [rdi + rax + 896], zmm14
    vmovupd  [rdi + rax + 960], zmm15
    inc  r10
    cmp  r10, r8
    jb   .Lfftinv_m1248_16_32_small_lp

    mov  r9,  64                        // m = 64
    mov  r8,  rdx
    shr  r8,  10                        // b_local = orig_n / 1024
    mov  rbx, r8                        // k_base = b_local
    mov  [rsp + 32], rdx                // limit_n = orig_n
    mov  qword ptr [rsp + 40], 1        // is_small = 1
    jmp  .Lfftinv_r16_check

.Lfftinv_m1248_16_32_n64:
    vmulpd   zmm0,  zmm0,  zmm22
    vmulpd   zmm1,  zmm1,  zmm22
    vmulpd   zmm2,  zmm2,  zmm22
    vmulpd   zmm3,  zmm3,  zmm22
    vmulpd   zmm4,  zmm4,  zmm22
    vmulpd   zmm5,  zmm5,  zmm22
    vmulpd   zmm6,  zmm6,  zmm22
    vmulpd   zmm7,  zmm7,  zmm22
    vmulpd   zmm8,  zmm8,  zmm22
    vmulpd   zmm9,  zmm9,  zmm22
    vmulpd   zmm10, zmm10, zmm22
    vmulpd   zmm11, zmm11, zmm22
    vmulpd   zmm12, zmm12, zmm22
    vmulpd   zmm13, zmm13, zmm22
    vmulpd   zmm14, zmm14, zmm22
    vmulpd   zmm15, zmm15, zmm22
    vmovupd  [rdi + 0],   zmm0
    vmovupd  [rdi + 64],  zmm1
    vmovupd  [rdi + 128], zmm2
    vmovupd  [rdi + 192], zmm3
    vmovupd  [rdi + 256], zmm4
    vmovupd  [rdi + 320], zmm5
    vmovupd  [rdi + 384], zmm6
    vmovupd  [rdi + 448], zmm7
    vmovupd  [rdi + 512], zmm8
    vmovupd  [rdi + 576], zmm9
    vmovupd  [rdi + 640], zmm10
    vmovupd  [rdi + 704], zmm11
    vmovupd  [rdi + 768], zmm12
    vmovupd  [rdi + 832], zmm13
    vmovupd  [rdi + 896], zmm14
    vmovupd  [rdi + 960], zmm15
    jmp  .Lfftinv_done

.Lfftinv_m1_m2_m4_small:
    mov  ecx, eax
    and  ecx, 3
    cmp  ecx, 1
    jne  .Lfftinv_m124_only_small

    // Fused 5-stage Radix-32 DIT bottom pass (m = 1, 2, 4, 8, 16 in registers) for orig_n = 32, 512:
    // cuts n = 32 to 1 pass and n = 512 to 2 passes!
    mov  r8,  rdx
    shr  r8,  5                         // blocks = orig_n / 32
    mov  rbx, r8                        // k_m16 = orig_n / 32
    xor  r10d, r10d                     // j = 0
.p2align 6
.Lfftinv_m1248_16_small_lp:
    mov  rax, r10
    shl  rax, 9                         // j * 512
    lea  rcx, [rbx + r10]
    shl  rcx, 5                         // 2 * (k_m16 + j) * 16
    vmovupd  zmm0,  [rdi + rax + 0]
    vmovupd  zmm1,  [rdi + rax + 64]
    vmovupd  zmm24, [rdi + rax + 128]
    vmovupd  zmm25, [rdi + rax + 192]
    vmovupd  zmm4,  [rdi + rax + 256]
    vmovupd  zmm5,  [rdi + rax + 320]
    vmovupd  zmm26, [rdi + rax + 384]
    vmovupd  zmm27, [rdi + rax + 448]

    vshuff64x2 zmm2,  zmm0,  zmm1,  0x88
    vshuff64x2 zmm3,  zmm0,  zmm1,  0xDD
    vshuff64x2 zmm0,  zmm24, zmm25, 0x88
    vshuff64x2 zmm1,  zmm24, zmm25, 0xDD
    vshuff64x2 zmm24, zmm4,  zmm5,  0x88
    vshuff64x2 zmm25, zmm4,  zmm5,  0xDD
    vshuff64x2 zmm4,  zmm26, zmm27, 0x88
    vshuff64x2 zmm5,  zmm26, zmm27, 0xDD
    vmovupd    zmm16, [rsi + 8*rcx + 0]
    vmovupd    zmm18, [rsi + 8*rcx + 64]
    vmovupd    zmm20, [rsi + 8*rcx + 128]
    vmovupd    zmm26, [rsi + 8*rcx + 192]
    vmovddup   zmm17, zmm16
    vshufpd    zmm16, zmm16, zmm16, 0xFF
    vmovddup   zmm19, zmm18
    vshufpd    zmm18, zmm18, zmm18, 0xFF
    vmovddup   zmm21, zmm20
    vshufpd    zmm20, zmm20, zmm20, 0xFF
    vmovddup   zmm27, zmm26
    vshufpd    zmm26, zmm26, zmm26, 0xFF
    FFT_DIT4 zmm2, zmm3, zmm17, zmm16, zmm0, zmm1, zmm19, zmm18, zmm24, zmm25, zmm21, zmm20, zmm4, zmm5, zmm27, zmm26

    vshuff64x2 zmm26, zmm2,  zmm3,  0x88
    vshuff64x2 zmm3,  zmm2,  zmm3,  0xDD
    vshuff64x2 zmm27, zmm0,  zmm1,  0x88
    vshuff64x2 zmm1,  zmm0,  zmm1,  0xDD
    vshuff64x2 zmm0,  zmm24, zmm25, 0x88
    vshuff64x2 zmm25, zmm24, zmm25, 0xDD
    vshuff64x2 zmm2,  zmm4,  zmm5,  0x88
    vshuff64x2 zmm5,  zmm4,  zmm5,  0xDD
    vmovupd    zmm4,  [rsi + 4*rcx + 0]
    vmovupd    zmm24, [rsi + 4*rcx + 64]
    vshuff64x2 zmm16, zmm4,  zmm4,  0x44
    vshuff64x2 zmm18, zmm4,  zmm4,  0xEE
    vshuff64x2 zmm20, zmm24, zmm24, 0x44
    vshuff64x2 zmm23, zmm24, zmm24, 0xEE
    vmovddup   zmm17, zmm16
    vshufpd    zmm16, zmm16, zmm16, 0xFF
    vmovddup   zmm19, zmm18
    vshufpd    zmm18, zmm18, zmm18, 0xFF
    vmovddup   zmm21, zmm20
    vshufpd    zmm20, zmm20, zmm20, 0xFF
    vmovddup   zmm4,  zmm23
    vshufpd    zmm23, zmm23, zmm23, 0xFF
    FFT_DIT4 zmm26, zmm3, zmm17, zmm16, zmm27, zmm1, zmm19, zmm18, zmm0, zmm25, zmm21, zmm20, zmm2, zmm5, zmm4, zmm23
    vshuff64x2 zmm4,  zmm26, zmm3,  0x88
    vshuff64x2 zmm3,  zmm26, zmm3,  0xDD
    vshuff64x2 zmm24, zmm27, zmm1,  0x88
    vshuff64x2 zmm1,  zmm27, zmm1,  0xDD
    vshuff64x2 zmm26, zmm0,  zmm25, 0x88
    vshuff64x2 zmm25, zmm0,  zmm25, 0xDD
    vshuff64x2 zmm27, zmm2,  zmm5,  0x88
    vshuff64x2 zmm5,  zmm2,  zmm5,  0xDD

    vbroadcastsd zmm16, [rsi + 2*rcx + 0]
    vbroadcastsd zmm17, [rsi + 2*rcx + 8]
    vbroadcastsd zmm18, [rsi + 2*rcx + 16]
    vbroadcastsd zmm19, [rsi + 2*rcx + 24]
    vbroadcastsd zmm20, [rsi + 2*rcx + 32]
    vbroadcastsd zmm21, [rsi + 2*rcx + 40]
    vbroadcastsd zmm0,  [rsi + 2*rcx + 48]
    vbroadcastsd zmm2,  [rsi + 2*rcx + 56]
    FFT_DIT4 zmm4, zmm3, zmm16, zmm17, zmm24, zmm1, zmm18, zmm19, zmm26, zmm25, zmm20, zmm21, zmm27, zmm5, zmm0, zmm2

    vbroadcastsd zmm16, [rsi + rcx + 0]
    vbroadcastsd zmm17, [rsi + rcx + 8]
    vbroadcastsd zmm18, [rsi + rcx + 16]
    vbroadcastsd zmm19, [rsi + rcx + 24]
    FFT_DIT4 zmm4, zmm24, zmm16, zmm17, zmm3, zmm1, zmm16, zmm17, zmm26, zmm27, zmm18, zmm19, zmm25, zmm5, zmm18, zmm19

    shr  rcx, 1                         // (k_m16 + j) * 16
    vbroadcastsd zmm16, [rsi + rcx + 0]
    vbroadcastsd zmm17, [rsi + rcx + 8]
    FFT_DIT4 zmm4, zmm26, zmm16, zmm17, zmm3, zmm25, zmm16, zmm17, zmm24, zmm27, zmm16, zmm17, zmm1, zmm5, zmm16, zmm17

    cmp  r8,  1
    je   .Lfftinv_m1248_16_n32
    vmovupd  [rdi + rax + 0],   zmm4
    vmovupd  [rdi + rax + 64],  zmm3
    vmovupd  [rdi + rax + 128], zmm24
    vmovupd  [rdi + rax + 192], zmm1
    vmovupd  [rdi + rax + 256], zmm26
    vmovupd  [rdi + rax + 320], zmm25
    vmovupd  [rdi + rax + 384], zmm27
    vmovupd  [rdi + rax + 448], zmm5

    inc  r10
    cmp  r10, r8
    jb   .Lfftinv_m1248_16_small_lp

    mov  r9,  32                        // m = 32
    mov  r8,  rdx
    shr  r8,  9                         // b_local = orig_n / 512
    mov  rbx, r8                        // k_base = b_local
    mov  [rsp + 32], rdx                // limit_n = orig_n
    mov  qword ptr [rsp + 40], 1        // is_small = 1
    jmp  .Lfftinv_r16_check

.Lfftinv_m1248_16_n32:
    vmulpd   zmm4,  zmm4,  zmm22
    vmulpd   zmm3,  zmm3,  zmm22
    vmulpd   zmm24, zmm24, zmm22
    vmulpd   zmm1,  zmm1,  zmm22
    vmulpd   zmm26, zmm26, zmm22
    vmulpd   zmm25, zmm25, zmm22
    vmulpd   zmm27, zmm27, zmm22
    vmulpd   zmm5,  zmm5,  zmm22
    vmovupd  [rdi + 0],   zmm4
    vmovupd  [rdi + 64],  zmm3
    vmovupd  [rdi + 128], zmm24
    vmovupd  [rdi + 192], zmm1
    vmovupd  [rdi + 256], zmm26
    vmovupd  [rdi + 320], zmm25
    vmovupd  [rdi + 384], zmm27
    vmovupd  [rdi + 448], zmm5
    jmp  .Lfftinv_done

.Lfftinv_m124_only_small:
    // Fused 3-stage Radix-8 DIT bottom pass (m = 1, 2, 4 in registers) for orig_n = 8, 128:
    mov  r8,  rdx
    shr  r8,  3                         // blocks = orig_n / 8
    mov  rbx, r8                        // k_m4 = orig_n / 8
    xor  r10d, r10d                     // j = 0
    cmp  r8,  1
    je   .Lfftinv_m1_m2_m4_vec

.p2align 4
.Lfftinv_m1_m2_m4_vec2:
    mov  rax, r10
    shl  rax, 7                         // j * 128
    lea  rcx, [rbx + r10]
    shl  rcx, 4                         // (k_m4 + j) * 16
    vmovupd  zmm0,  [rdi + rax + 0]
    vmovupd  zmm1,  [rdi + rax + 64]
    vmovupd  zmm24, [rdi + rax + 128]
    vmovupd  zmm25, [rdi + rax + 192]

    // Stage m = 1 across all 8 pairs:
    vshuff64x2 zmm2,  zmm0,  zmm1,  0x88
    vshuff64x2 zmm3,  zmm0,  zmm1,  0xDD
    vshuff64x2 zmm26, zmm24, zmm25, 0x88
    vshuff64x2 zmm27, zmm24, zmm25, 0xDD
    vmovupd    zmm16, [rsi + 4*rcx + 0]
    vmovupd    zmm18, [rsi + 4*rcx + 64]
    vmovddup   zmm17, zmm16
    vshufpd    zmm16, zmm16, zmm16, 0xFF
    vmovddup   zmm19, zmm18
    vshufpd    zmm18, zmm18, zmm18, 0xFF
    FFT_DIT2 zmm2, zmm3, zmm17, zmm16, zmm26, zmm27, zmm19, zmm18

    // Stage m = 2 across all 4 quarters:
    vshuff64x2 zmm0,  zmm2,  zmm3,  0x88
    vshuff64x2 zmm1,  zmm2,  zmm3,  0xDD
    vshuff64x2 zmm24, zmm26, zmm27, 0x88
    vshuff64x2 zmm25, zmm26, zmm27, 0xDD
    vmovupd    zmm20, [rsi + 2*rcx]
    vshuff64x2 zmm16, zmm20, zmm20, 0x44
    vshuff64x2 zmm18, zmm20, zmm20, 0xEE
    vmovddup   zmm17, zmm16
    vshufpd    zmm16, zmm16, zmm16, 0xFF
    vmovddup   zmm19, zmm18
    vshufpd    zmm18, zmm18, zmm18, 0xFF
    FFT_DIT2 zmm0, zmm1, zmm17, zmm16, zmm24, zmm25, zmm19, zmm18
    vshuff64x2 zmm2,  zmm0,  zmm1,  0x88
    vshuff64x2 zmm3,  zmm0,  zmm1,  0xDD
    vshuff64x2 zmm26, zmm24, zmm25, 0x88
    vshuff64x2 zmm27, zmm24, zmm25, 0xDD

    // Stage m = 4 across blocks j and j+1:
    vbroadcastsd zmm16, [rsi + rcx + 0]
    vbroadcastsd zmm17, [rsi + rcx + 8]
    vbroadcastsd zmm18, [rsi + rcx + 16]
    vbroadcastsd zmm19, [rsi + rcx + 24]
    FFT_DIT2 zmm2, zmm3, zmm16, zmm17, zmm26, zmm27, zmm18, zmm19

    vmovupd  [rdi + rax + 0],   zmm2
    vmovupd  [rdi + rax + 64],  zmm3
    vmovupd  [rdi + rax + 128], zmm26
    vmovupd  [rdi + rax + 192], zmm27

    add  r10, 2
    cmp  r10, r8
    jb   .Lfftinv_m1_m2_m4_vec2
    jmp  .Lfftinv_m1_m2_m4_after

.p2align 4
.Lfftinv_m1_m2_m4_vec:
    mov  rax, r10
    shl  rax, 7                         // j * 128
    lea  rcx, [rbx + r10]
    shl  rcx, 4                         // (k_m4 + j) * 16
    vmovupd  zmm0, [rdi + rax + 0]
    vmovupd  zmm1, [rdi + rax + 64]

    // Stage m = 1:
    vshuff64x2 zmm2,  zmm0, zmm1, 0x88
    vshuff64x2 zmm3,  zmm0, zmm1, 0xDD
    vaddpd     zmm4,  zmm2, zmm3
    vsubpd     zmm5,  zmm2, zmm3
    vmovupd    zmm1,  [rsi + 4*rcx]
    vmovddup   zmm16, zmm1
    vshufpd    zmm17, zmm1, zmm1, 0xFF
    vshufpd    zmm2,  zmm5, zmm5, 0x55
    vmulpd     zmm2,  zmm2, zmm17
    vfmaddsub231pd zmm2, zmm5, zmm16

    // Stage m = 2:
    vshuff64x2 zmm0,  zmm4, zmm2, 0x88
    vshuff64x2 zmm1,  zmm4, zmm2, 0xDD
    vaddpd     zmm3,  zmm0, zmm1
    vsubpd     zmm4,  zmm0, zmm1
    vmovupd    ymm5,  [rsi + 2*rcx]
    vshuff64x2 zmm5,  zmm5, zmm5, 0x44
    vmovddup   zmm16, zmm5
    vshufpd    zmm17, zmm5, zmm5, 0xFF
    vshufpd    zmm2,  zmm4, zmm4, 0x55
    vmulpd     zmm2,  zmm2, zmm17
    vfmaddsub231pd zmm2, zmm4, zmm16
    vshuff64x2 zmm0,  zmm3, zmm2, 0x88
    vshuff64x2 zmm1,  zmm3, zmm2, 0xDD

    // Stage m = 4:
    vaddpd     zmm3,  zmm0, zmm1
    vsubpd     zmm4,  zmm0, zmm1
    vbroadcastsd zmm16, [rsi + rcx + 0]
    vbroadcastsd zmm17, [rsi + rcx + 8]
    vshufpd    zmm2,  zmm4, zmm4, 0x55
    vmulpd     zmm2,  zmm2, zmm17
    vfmaddsub231pd zmm2, zmm4, zmm16

    cmp  r8,  1
    je   .Lfftinv_m124_n8
    vmovupd  [rdi + rax + 0],  zmm3
    vmovupd  [rdi + rax + 64], zmm2
    inc  r10
    cmp  r10, r8
    jb   .Lfftinv_m1_m2_m4_vec

.Lfftinv_m1_m2_m4_after:
    mov  r9,  8                         // m = 8
    mov  r8,  rdx
    shr  r8,  7                         // b_local = orig_n / 128
    mov  rbx, r8                        // k_base = b_local
    mov  [rsp + 32], rdx                // limit_n = orig_n
    mov  qword ptr [rsp + 40], 1        // is_small = 1
    jmp  .Lfftinv_r16_check

.Lfftinv_m124_n8:
    vmulpd   zmm3, zmm3, zmm22
    vmulpd   zmm2, zmm2, zmm22
    vmovupd  [rdi + 0],  zmm3
    vmovupd  [rdi + 64], zmm2
    jmp  .Lfftinv_done

.Lfftinv_m1_m2_n4:
    // n_complex == 4 (1 group, fused 1/4 scaling):
    vmovupd  zmm0, [rdi]
    vextractf64x4 ymm1, zmm0, 1
    vshuff64x2 ymm2, ymm0, ymm1, 0x00
    vshuff64x2 ymm3, ymm0, ymm1, 0x03
    vaddpd   ymm4, ymm2, ymm3
    vsubpd   ymm5, ymm2, ymm3
    vmovupd  ymm1,  [rsi + 32]
    vmovddup ymm16, ymm1
    vshufpd  ymm17, ymm1, ymm1, 0x0F
    vshufpd  ymm2,  ymm5, ymm5, 0x05
    vmulpd   ymm2,  ymm2, ymm17
    vfmaddsub231pd ymm2, ymm5, ymm16
    vshuff64x2 ymm0, ymm4, ymm2, 0x00
    vshuff64x2 ymm1, ymm4, ymm2, 0x03
    vaddpd   ymm3, ymm0, ymm1
    vsubpd   ymm4, ymm0, ymm1
    vbroadcastsd ymm16, [rsi + 16]
    vbroadcastsd ymm17, [rsi + 24]
    vshufpd  ymm2, ymm4, ymm4, 0x05
    vmulpd   ymm2, ymm2, ymm17
    vfmaddsub231pd ymm2, ymm4, ymm16
    vinsertf64x4 zmm0, zmm3, ymm2, 1
    vmulpd   zmm0, zmm0, zmm22
    vmovupd  [rdi], zmm0
    jmp  .Lfftinv_done

    // Large n_complex > sub_cap: execute bottom stages inside L1-sized sub_cap sub-blocks!
.Lfftinv_large:
    mov  [rsp + 56], rax                // sub_cap
    mov  rax, rdx
    shr  rax, cl                        // num_subs = orig_n / sub_cap
    mov  [rsp + 16], rax
    mov  qword ptr [rsp + 24], 0        // sb = 0

.Lfftinv_sub_loop:
    mov  rax, [rsp + 24]                // sb
    mov  rcx, [rsp + 16]                // num_subs
    mov  rdi, [rsp + 0]
    mov  rdx, [rsp + 56]                // sub_cap
    mov  r11, rax
    imul r11, rdx
    shl  r11, 4                         // sb * sub_cap * 16
    add  rdi, r11                       // sub_buf
    lea  r15, [rcx + rax]               // s_idx = num_subs + sb
    mov  [rsp + 48], r15                // save s_idx

    tzcnt rcx, rdx                      // ks = log2(sub_cap) >= 6
    test  ecx, 1
    jnz   .Lfftinv_sub_odd_ks

    mov   eax, ecx
    and   eax, 3
    cmp   eax, 2
    je    .Lfftinv_sub_m1248_16_32

    // 1a. log2(sub_cap) == 8 (sub_cap == 256): 2x-unrolled 4-stage Radix-16 DIT bottom pass (m = 1..8) inside sub_buf!
    mov  r8,  rdx
    shr  r8,  4                         // blocks = sub_cap / 16 (>= 4, even)
    sub  ecx, 4
    mov  rbx, r15
    shl  rbx, cl                        // k_m8 = s_idx << (ks - 4)
    xor  r10d, r10d
.p2align 6
.Lfftinv_sub_m1248_vec2:
    mov  rax, r10
    shl  rax, 8
    lea  rcx, [rbx + r10]
    shl  rcx, 4
    vmovupd  zmm0,  [rdi + rax + 0]
    vmovupd  zmm1,  [rdi + rax + 64]
    vmovupd  zmm24, [rdi + rax + 128]
    vmovupd  zmm25, [rdi + rax + 192]
    vmovupd  zmm4,  [rdi + rax + 256]
    vmovupd  zmm5,  [rdi + rax + 320]
    vmovupd  zmm26, [rdi + rax + 384]
    vmovupd  zmm27, [rdi + rax + 448]

    vshuff64x2 zmm2,  zmm0,  zmm1,  0x88
    vshuff64x2 zmm3,  zmm0,  zmm1,  0xDD
    vshuff64x2 zmm0,  zmm24, zmm25, 0x88
    vshuff64x2 zmm1,  zmm24, zmm25, 0xDD
    vshuff64x2 zmm24, zmm4,  zmm5,  0x88
    vshuff64x2 zmm25, zmm4,  zmm5,  0xDD
    vshuff64x2 zmm4,  zmm26, zmm27, 0x88
    vshuff64x2 zmm5,  zmm26, zmm27, 0xDD
    vmovupd    zmm16, [rsi + 8*rcx + 0]
    vmovupd    zmm18, [rsi + 8*rcx + 64]
    vmovupd    zmm20, [rsi + 8*rcx + 128]
    vmovupd    zmm26, [rsi + 8*rcx + 192]
    vmovddup   zmm17, zmm16
    vshufpd    zmm16, zmm16, zmm16, 0xFF
    vmovddup   zmm19, zmm18
    vshufpd    zmm18, zmm18, zmm18, 0xFF
    vmovddup   zmm21, zmm20
    vshufpd    zmm20, zmm20, zmm20, 0xFF
    vmovddup   zmm27, zmm26
    vshufpd    zmm26, zmm26, zmm26, 0xFF
    FFT_DIT4 zmm2, zmm3, zmm17, zmm16, zmm0, zmm1, zmm19, zmm18, zmm24, zmm25, zmm21, zmm20, zmm4, zmm5, zmm27, zmm26

    vshuff64x2 zmm26, zmm2,  zmm3,  0x88
    vshuff64x2 zmm3,  zmm2,  zmm3,  0xDD
    vshuff64x2 zmm27, zmm0,  zmm1,  0x88
    vshuff64x2 zmm1,  zmm0,  zmm1,  0xDD
    vshuff64x2 zmm0,  zmm24, zmm25, 0x88
    vshuff64x2 zmm25, zmm24, zmm25, 0xDD
    vshuff64x2 zmm2,  zmm4,  zmm5,  0x88
    vshuff64x2 zmm5,  zmm4,  zmm5,  0xDD
    vmovupd    zmm4,  [rsi + 4*rcx + 0]
    vmovupd    zmm24, [rsi + 4*rcx + 64]
    vshuff64x2 zmm16, zmm4,  zmm4,  0x44
    vshuff64x2 zmm18, zmm4,  zmm4,  0xEE
    vshuff64x2 zmm20, zmm24, zmm24, 0x44
    vshuff64x2 zmm23, zmm24, zmm24, 0xEE
    vmovddup   zmm17, zmm16
    vshufpd    zmm16, zmm16, zmm16, 0xFF
    vmovddup   zmm19, zmm18
    vshufpd    zmm18, zmm18, zmm18, 0xFF
    vmovddup   zmm21, zmm20
    vshufpd    zmm20, zmm20, zmm20, 0xFF
    vmovddup   zmm4,  zmm23
    vshufpd    zmm23, zmm23, zmm23, 0xFF
    FFT_DIT4 zmm26, zmm3, zmm17, zmm16, zmm27, zmm1, zmm19, zmm18, zmm0, zmm25, zmm21, zmm20, zmm2, zmm5, zmm4, zmm23
    vshuff64x2 zmm4,  zmm26, zmm3,  0x88
    vshuff64x2 zmm3,  zmm26, zmm3,  0xDD
    vshuff64x2 zmm24, zmm27, zmm1,  0x88
    vshuff64x2 zmm1,  zmm27, zmm1,  0xDD
    vshuff64x2 zmm26, zmm0,  zmm25, 0x88
    vshuff64x2 zmm25, zmm0,  zmm25, 0xDD
    vshuff64x2 zmm27, zmm2,  zmm5,  0x88
    vshuff64x2 zmm5,  zmm2,  zmm5,  0xDD

    vbroadcastsd zmm16, [rsi + 2*rcx + 0]
    vbroadcastsd zmm17, [rsi + 2*rcx + 8]
    vbroadcastsd zmm18, [rsi + 2*rcx + 16]
