    vmovupd zmm11, [rcx + rax]
    lea  rcx, [rcx + 4*r11]
    vmovupd zmm12, [rcx]
    vmovupd zmm13, [rcx + r11]
    vmovupd zmm14, [rcx + 2*r11]
    vmovupd zmm15, [rcx + rax]

    // Stage 1 (stride 1: 1*m)
    FFT_DIT2_MEM zmm0,  zmm1,  rdx+0,  rdx+8,   zmm2,  zmm3,  rdx+16,  rdx+24
    FFT_DIT2_MEM zmm4,  zmm5,  rdx+32, rdx+40,  zmm6,  zmm7,  rdx+48,  rdx+56
    FFT_DIT2_MEM zmm8,  zmm9,  rdx+64, rdx+72,  zmm10, zmm11, rdx+80,  rdx+88
    FFT_DIT2_MEM zmm12, zmm13, rdx+96, rdx+104, zmm14, zmm15, rdx+112, rdx+120

    // Stage 2 (stride 2: 2*m)
    FFT_DIT2     zmm0,  zmm2,  zmm30, zmm31, zmm1,  zmm3,  zmm30, zmm31
    FFT_DIT2     zmm4,  zmm6,  zmm23, zmm24, zmm5,  zmm7,  zmm23, zmm24
    FFT_DIT2     zmm8,  zmm10, zmm25, zmm26, zmm9,  zmm11, zmm25, zmm26
    FFT_DIT2_MEM zmm12, zmm14, r13+48, r13+56, zmm13, zmm15, r13+48, r13+56

    // Stage 3 (stride 4: 4*m)
    lea  rcx, [rbx + r10]
    cmp  rcx, 1
    je   .Lfftinv_r16_stg34_j0
    FFT_DIT2 zmm0, zmm4,  zmm18, zmm19, zmm1, zmm5,  zmm18, zmm19
    FFT_DIT2 zmm2, zmm6,  zmm18, zmm19, zmm3, zmm7,  zmm18, zmm19
    FFT_DIT2 zmm8, zmm12, zmm20, zmm21, zmm9, zmm13, zmm20, zmm21
    FFT_DIT2 zmm10, zmm14, zmm20, zmm21, zmm11, zmm15, zmm20, zmm21

    // Stage 4 (stride 8: 8*m)
    FFT_DIT2 zmm0, zmm8,  zmm16, zmm17, zmm1, zmm9,  zmm16, zmm17
    FFT_DIT2 zmm2, zmm10, zmm16, zmm17, zmm3, zmm11, zmm16, zmm17
    FFT_DIT2 zmm4, zmm12, zmm16, zmm17, zmm5, zmm13, zmm16, zmm17
    FFT_DIT2 zmm6, zmm14, zmm16, zmm17, zmm7, zmm15, zmm16, zmm17
    jmp  .Lfftinv_r16_chk_scale

.Lfftinv_r16_stg34_j0:
    // Stage 3 (k0 == 1: inv_tw[2] = (1, 0), inv_tw[3] = (0, +1))
    vmovapd zmm28, [rip + .Lconst_fft_neg_re]
    vsubpd  zmm24, zmm0, zmm4
    vsubpd  zmm25, zmm1, zmm5
    vaddpd  zmm0,  zmm0, zmm4
    vaddpd  zmm1,  zmm1, zmm5
    vmovapd zmm4,  zmm24
    vmovapd zmm5,  zmm25
    vsubpd  zmm24, zmm2, zmm6
    vsubpd  zmm25, zmm3, zmm7
    vaddpd  zmm2,  zmm2, zmm6
    vaddpd  zmm3,  zmm3, zmm7
    vmovapd zmm6,  zmm24
    vmovapd zmm7,  zmm25

    vsubpd  zmm24, zmm8,  zmm12
    vsubpd  zmm25, zmm9,  zmm13
    vaddpd  zmm8,  zmm8,  zmm12
    vaddpd  zmm9,  zmm9,  zmm13
    vshufpd zmm12, zmm24, zmm24, 0x55
    vshufpd zmm13, zmm25, zmm25, 0x55
    vxorpd  zmm12, zmm12, zmm28
    vxorpd  zmm13, zmm13, zmm28
    vsubpd  zmm24, zmm10, zmm14
    vsubpd  zmm25, zmm11, zmm15
    vaddpd  zmm10, zmm10, zmm14
    vaddpd  zmm11, zmm11, zmm15
    vshufpd zmm14, zmm24, zmm24, 0x55
    vshufpd zmm15, zmm25, zmm25, 0x55
    vxorpd  zmm14, zmm14, zmm28
    vxorpd  zmm15, zmm15, zmm28

    // Stage 4 (k0 == 1: inv_tw[1] = (1, 0))
    vsubpd  zmm24, zmm0, zmm8
    vsubpd  zmm25, zmm1, zmm9
    vaddpd  zmm0,  zmm0, zmm8
    vaddpd  zmm1,  zmm1, zmm9
    vmovapd zmm8,  zmm24
    vmovapd zmm9,  zmm25
    vsubpd  zmm24, zmm2, zmm10
    vsubpd  zmm25, zmm3, zmm11
    vaddpd  zmm2,  zmm2, zmm10
    vaddpd  zmm3,  zmm3, zmm11
    vmovapd zmm10, zmm24
    vmovapd zmm11, zmm25
    vsubpd  zmm24, zmm4, zmm12
    vsubpd  zmm25, zmm5, zmm13
    vaddpd  zmm4,  zmm4, zmm12
    vaddpd  zmm5,  zmm5, zmm13
    vmovapd zmm12, zmm24
    vmovapd zmm13, zmm25
    vsubpd  zmm24, zmm6, zmm14
    vsubpd  zmm25, zmm7, zmm15
    vaddpd  zmm6,  zmm6, zmm14
    vaddpd  zmm7,  zmm7, zmm15
    vmovapd zmm14, zmm24
    vmovapd zmm15, zmm25

.Lfftinv_r16_chk_scale:
    cmp  qword ptr [rsp + 40], 0
    je   .Lfftinv_r16_store
    cmp  r8, 1
    jne  .Lfftinv_r16_store
    vmulpd zmm0,  zmm0,  zmm22
    vmulpd zmm1,  zmm1,  zmm22
    vmulpd zmm2,  zmm2,  zmm22
    vmulpd zmm3,  zmm3,  zmm22
    vmulpd zmm4,  zmm4,  zmm22
    vmulpd zmm5,  zmm5,  zmm22
    vmulpd zmm6,  zmm6,  zmm22
    vmulpd zmm7,  zmm7,  zmm22
    vmulpd zmm8,  zmm8,  zmm22
    vmulpd zmm9,  zmm9,  zmm22
    vmulpd zmm10, zmm10, zmm22
    vmulpd zmm11, zmm11, zmm22
    vmulpd zmm12, zmm12, zmm22
    vmulpd zmm13, zmm13, zmm22
    vmulpd zmm14, zmm14, zmm22
    vmulpd zmm15, zmm15, zmm22

.Lfftinv_r16_store:
    vmovupd [r12],         zmm0
    vmovupd [r12 + r11],   zmm1
    vmovupd [r12 + 2*r11], zmm2
    vmovupd [r12 + rax],   zmm3
    lea  rcx, [r12 + 4*r11]
    vmovupd [rcx],         zmm4
    vmovupd [rcx + r11],   zmm5
    vmovupd [rcx + 2*r11], zmm6
    vmovupd [rcx + rax],   zmm7
    lea  rcx, [r12 + 8*r11]
    vmovupd [rcx],         zmm8
    vmovupd [rcx + r11],   zmm9
    vmovupd [rcx + 2*r11], zmm10
    vmovupd [rcx + rax],   zmm11
    lea  rcx, [rcx + 4*r11]
    vmovupd [rcx],         zmm12
    vmovupd [rcx + r11],   zmm13
    vmovupd [rcx + 2*r11], zmm14
    vmovupd [rcx + rax],   zmm15

    lea  r12, [r12 + 64]
    sub  r14, 4
    jz   .Lfftinv_r16_blk_done
    lea  rcx, [rbx + r10]
    cmp  rcx, 1
    je   .Lfftinv_r16_vec_j0
    jmp  .Lfftinv_r16_vec
.Lfftinv_r16_blk_done:

    inc  r10
    cmp  r10, r8
    jb   .Lfftinv_r16_block

    shl  r9,  4
    shr  r8,  4
    shr  rbx, 4
    jmp  .Lfftinv_r16_check

.Lfftinv_r16_done:
    cmp  qword ptr [rsp + 40], 0
    je   .Lfftinv_sub_after_r16
    mov  rdx, [rsp + 8]
    cmp  r9,  rdx
    jae  .Lfftinv_done
    jmp  .Lfftinv_r4_check

.Lfftinv_sub_after_r16:
    cmp  r9,  [rsp + 56]
    jae  .Lfftinv_sub_next

.Lfftinv_sub_r4_last:
    // 3. Dual-pipe 8-ZMM Radix-4 DIT pass for the final 2 stages (m = sub_cap/4, sub_cap/2) of sub_buf!
    mov  rax, [rsp + 48]                // s_idx = num_subs + sb
    shl  rax, 4
    vbroadcastsd zmm16, [rsi + rax + 0]
    vbroadcastsd zmm17, [rsi + rax + 8]
    add  rax, rax
    vbroadcastsd zmm18, [rsi + rax + 0]
    vbroadcastsd zmm19, [rsi + rax + 8]
    vbroadcastsd zmm20, [rsi + rax + 16]
    vbroadcastsd zmm21, [rsi + rax + 24]
    mov  r14, [rsp + 56]
    shr  r14, 2                         // m_last = sub_cap / 4 (>= 16, multiple of 8)
    mov  r11, r14
    shl  r11, 4                         // quarter_bytes = m_last * 16
    mov  r12, rdi
    lea  r13, [r12 + r11]
    lea  rcx, [r13 + r11]
    lea  rax, [rcx + r11]
.p2align 4
.Lfftinv_sub_r4_loop8:
    vmovupd  zmm0, [r12 + 0]
    vmovupd  zmm1, [r13 + 0]
    vmovupd  zmm2, [rcx + 0]
    vmovupd  zmm3, [rax + 0]
    vmovupd  zmm6, [r12 + 64]
    vmovupd  zmm7, [r13 + 64]
    vmovupd  zmm8, [rcx + 64]
    vmovupd  zmm9, [rax + 64]
    vaddpd   zmm4,  zmm0, zmm1
    vsubpd   zmm1,  zmm0, zmm1
    vaddpd   zmm5,  zmm2, zmm3
    vsubpd   zmm3,  zmm2, zmm3
    vaddpd   zmm10, zmm6, zmm7
    vsubpd   zmm7,  zmm6, zmm7
    vaddpd   zmm11, zmm8, zmm9
    vsubpd   zmm9,  zmm8, zmm9
    vshufpd  zmm0, zmm1, zmm1, 0x55
    vshufpd  zmm2, zmm3, zmm3, 0x55
    vshufpd  zmm6, zmm7, zmm7, 0x55
    vshufpd  zmm8, zmm9, zmm9, 0x55
    vmulpd   zmm0, zmm0, zmm19
    vmulpd   zmm2, zmm2, zmm21
    vmulpd   zmm6, zmm6, zmm19
    vmulpd   zmm8, zmm8, zmm21
    vfmaddsub231pd zmm0, zmm1, zmm18
    vfmaddsub231pd zmm2, zmm3, zmm20
    vfmaddsub231pd zmm6, zmm7, zmm18
    vfmaddsub231pd zmm8, zmm9, zmm20
    vaddpd   zmm1, zmm4,  zmm5
    vsubpd   zmm4, zmm4,  zmm5
    vaddpd   zmm3, zmm0,  zmm2
    vsubpd   zmm0, zmm0,  zmm2
    vaddpd   zmm7, zmm10, zmm11
    vsubpd   zmm10, zmm10, zmm11
    vaddpd   zmm9, zmm6,  zmm8
    vsubpd   zmm6, zmm6,  zmm8
    vshufpd  zmm5,  zmm4,  zmm4,  0x55
    vshufpd  zmm2,  zmm0,  zmm0,  0x55
    vshufpd  zmm11, zmm10, zmm10, 0x55
    vshufpd  zmm8,  zmm6,  zmm6,  0x55
    vmulpd   zmm5,  zmm5,  zmm17
    vmulpd   zmm2,  zmm2,  zmm17
    vmulpd   zmm11, zmm11, zmm17
    vmulpd   zmm8,  zmm8,  zmm17
    vfmaddsub231pd zmm5,  zmm4,  zmm16
    vfmaddsub231pd zmm2,  zmm0,  zmm16
    vfmaddsub231pd zmm11, zmm10, zmm16
    vfmaddsub231pd zmm8,  zmm6,  zmm16
    vmovupd  [r12 + 0],  zmm1
    vmovupd  [r13 + 0],  zmm3
    vmovupd  [rcx + 0],  zmm5
    vmovupd  [rax + 0],  zmm2
    vmovupd  [r12 + 64], zmm7
    vmovupd  [r13 + 64], zmm9
    vmovupd  [rcx + 64], zmm11
    vmovupd  [rax + 64], zmm8
    lea  r12, [r12 + 128]
    lea  r13, [r13 + 128]
    lea  rcx, [rcx + 128]
    lea  rax, [rax + 128]
    sub  r14, 8
    jnz  .Lfftinv_sub_r4_loop8

.Lfftinv_sub_next:
    mov  rax, [rsp + 24]
    inc  rax
    cmp  rax, [rsp + 16]
    jae  .Lfftinv_top_after_subs
    mov  [rsp + 24], rax
    jmp  .Lfftinv_sub_loop

.Lfftinv_top_after_subs:
    mov  rdi, [rsp + 0]                 // orig_buf
    mov  rdx, [rsp + 8]                 // orig_n
    mov  r9,  [rsp + 56]                // resume global DIT at m = sub_cap!

    // 2a. Fused 2-stage Radix-4 DIT passes while 2 * m < n_complex (2x-unrolled).
.Lfftinv_r4_check:
    lea  rax, [r9 + r9]
    cmp  rax, rdx
    jae  .Lfftinv_stage_check

    mov  r8,  rdx
    xor  ecx, ecx
    tzcnt rcx, r9
    add  ecx, 2
    shr  r8,  cl                        // b_hi = n_complex / (4 * m)
    mov  r11, r9
    shl  r11, 4                         // mh_bytes = m * 16
    xor  r10d, r10d                     // j = 0

.Lfftinv_r4_block:
    lea  rax, [r8 + r10]
    shl  rax, 4
    vbroadcastsd zmm16, [rsi + rax + 0] // wr0 (stage 2*m)
    vbroadcastsd zmm17, [rsi + rax + 8] // wi0
    add  rax, rax
    vbroadcastsd zmm18, [rsi + rax + 0] // wr1 (stage m, sub 0)
    vbroadcastsd zmm19, [rsi + rax + 8] // wi1
    vbroadcastsd zmm20, [rsi + rax + 16]// wr2 (stage m, sub 1)
    vbroadcastsd zmm21, [rsi + rax + 24]// wi2

    mov  rcx, r10
    imul rcx, r11
    shl  rcx, 2
    lea  r12, [rdi + rcx]               // q0
    lea  r13, [r12 + r11]               // q1
    lea  rcx, [r13 + r11]               // q2
    lea  rax, [rcx + r11]               // q3
    mov  r14, r9                        // count = m (multiple of 4)

    cmp  r8,  1
    je   .Lfftinv_r4_scaled_entry

    cmp  r14, 8
    jb   .Lfftinv_r4_tail4

.p2align 4
.Lfftinv_r4_loop8:
    vmovupd  zmm0,  [r12 + 0]
    vmovupd  zmm1,  [r13 + 0]
    vmovupd  zmm2,  [rcx + 0]
    vmovupd  zmm3,  [rax + 0]
    vmovupd  zmm23, [r12 + 64]
    vmovupd  zmm24, [r13 + 64]
    vmovupd  zmm25, [rcx + 64]
    vmovupd  zmm26, [rax + 64]

    vaddpd   zmm4,  zmm0,  zmm1
    vsubpd   zmm1,  zmm0,  zmm1
    vaddpd   zmm5,  zmm2,  zmm3
    vsubpd   zmm3,  zmm2,  zmm3
    vaddpd   zmm27, zmm23, zmm24
    vsubpd   zmm24, zmm23, zmm24
    vaddpd   zmm28, zmm25, zmm26
    vsubpd   zmm26, zmm25, zmm26

    vshufpd  zmm0,  zmm1,  zmm1,  0x55
    vshufpd  zmm2,  zmm3,  zmm3,  0x55
    vshufpd  zmm23, zmm24, zmm24, 0x55
    vshufpd  zmm25, zmm26, zmm26, 0x55
    vmulpd   zmm0,  zmm0,  zmm19
    vmulpd   zmm2,  zmm2,  zmm21
    vmulpd   zmm23, zmm23, zmm19
    vmulpd   zmm25, zmm25, zmm21
    vfmaddsub231pd zmm0,  zmm1,  zmm18
    vfmaddsub231pd zmm2,  zmm3,  zmm20
    vfmaddsub231pd zmm23, zmm24, zmm18
    vfmaddsub231pd zmm25, zmm26, zmm20

    vaddpd   zmm1,  zmm4,  zmm5
    vsubpd   zmm4,  zmm4,  zmm5
    vaddpd   zmm3,  zmm0,  zmm2
    vsubpd   zmm0,  zmm0,  zmm2
    vaddpd   zmm24, zmm27, zmm28
    vsubpd   zmm27, zmm27, zmm28
    vaddpd   zmm26, zmm23, zmm25
    vsubpd   zmm23, zmm23, zmm25

    vshufpd  zmm5,  zmm4,  zmm4,  0x55
    vshufpd  zmm2,  zmm0,  zmm0,  0x55
    vshufpd  zmm28, zmm27, zmm27, 0x55
    vshufpd  zmm25, zmm23, zmm23, 0x55
    vmulpd   zmm5,  zmm5,  zmm17
    vmulpd   zmm2,  zmm2,  zmm17
    vmulpd   zmm28, zmm28, zmm17
    vmulpd   zmm25, zmm25, zmm17
    vfmaddsub231pd zmm5,  zmm4,  zmm16
    vfmaddsub231pd zmm2,  zmm0,  zmm16
    vfmaddsub231pd zmm28, zmm27, zmm16
    vfmaddsub231pd zmm25, zmm23, zmm16

    vmovupd  [r12 + 0],  zmm1
    vmovupd  [r13 + 0],  zmm3
    vmovupd  [rcx + 0],  zmm5
    vmovupd  [rax + 0],  zmm2
    vmovupd  [r12 + 64], zmm24
    vmovupd  [r13 + 64], zmm26
    vmovupd  [rcx + 64], zmm28
    vmovupd  [rax + 64], zmm25

    lea  r12, [r12 + 128]
    lea  r13, [r13 + 128]
    lea  rcx, [rcx + 128]
    lea  rax, [rax + 128]
    sub  r14, 8
    cmp  r14, 8
    jae  .Lfftinv_r4_loop8

.Lfftinv_r4_tail4:
    test r14, r14
    jz   .Lfftinv_r4_next_block
    vmovupd  zmm0, [r12]
    vmovupd  zmm1, [r13]
    vmovupd  zmm2, [rcx]
    vmovupd  zmm3, [rax]
    vaddpd   zmm4, zmm0, zmm1
    vsubpd   zmm1, zmm0, zmm1
    vaddpd   zmm5, zmm2, zmm3
    vsubpd   zmm3, zmm2, zmm3
    vshufpd  zmm0, zmm1, zmm1, 0x55
    vshufpd  zmm2, zmm3, zmm3, 0x55
    vmulpd   zmm0, zmm0, zmm19
    vmulpd   zmm2, zmm2, zmm21
    vfmaddsub231pd zmm0, zmm1, zmm18
    vfmaddsub231pd zmm2, zmm3, zmm20
    vaddpd   zmm1, zmm4, zmm5
    vsubpd   zmm4, zmm4, zmm5
    vaddpd   zmm3, zmm0, zmm2
    vsubpd   zmm0, zmm0, zmm2
    vshufpd  zmm5, zmm4, zmm4, 0x55
    vshufpd  zmm2, zmm0, zmm0, 0x55
    vmulpd   zmm5, zmm5, zmm17
    vmulpd   zmm2, zmm2, zmm17
    vfmaddsub231pd zmm5, zmm4, zmm16
    vfmaddsub231pd zmm2, zmm0, zmm16
    vmovupd  [r12], zmm1
    vmovupd  [r13], zmm3
    vmovupd  [rcx], zmm5
    vmovupd  [rax], zmm2
    jmp  .Lfftinv_r4_next_block

.Lfftinv_r4_scaled_entry:
    // r8 == 1 implies j == 0 and k0 == 1: inv_tw[2] = (1, 0), inv_tw[3] = (0, +1), inv_tw[1] = (1, 0)!
    vmovapd  zmm21, [rip + .Lconst_fft_neg_re]
    cmp  r14, 8
    jb   .Lfftinv_r4_scaled_tail4

.p2align 4
.Lfftinv_r4_loop8_scaled:
    vmovupd  zmm0,  [r12 + 0]
    vmovupd  zmm1,  [r13 + 0]
    vmovupd  zmm2,  [rcx + 0]
    vmovupd  zmm3,  [rax + 0]
    vmovupd  zmm23, [r12 + 64]
    vmovupd  zmm24, [r13 + 64]
    vmovupd  zmm25, [rcx + 64]
    vmovupd  zmm26, [rax + 64]

    vaddpd   zmm4,  zmm0,  zmm1
    vsubpd   zmm0,  zmm0,  zmm1
    vaddpd   zmm5,  zmm2,  zmm3
    vsubpd   zmm3,  zmm2,  zmm3
    vaddpd   zmm27, zmm23, zmm24
    vsubpd   zmm23, zmm23, zmm24
    vaddpd   zmm28, zmm25, zmm26
    vsubpd   zmm26, zmm25, zmm26

    vshufpd  zmm2,  zmm3,  zmm3,  0x55
    vshufpd  zmm25, zmm26, zmm26, 0x55
    vxorpd   zmm2,  zmm2,  zmm21
    vxorpd   zmm25, zmm25, zmm21

    vaddpd   zmm1,  zmm4,  zmm5
    vsubpd   zmm5,  zmm4,  zmm5
    vaddpd   zmm3,  zmm0,  zmm2
    vsubpd   zmm2,  zmm0,  zmm2
    vaddpd   zmm24, zmm27, zmm28
    vsubpd   zmm28, zmm27, zmm28
    vaddpd   zmm26, zmm23, zmm25
    vsubpd   zmm25, zmm23, zmm25

    vmulpd   zmm1,  zmm1,  zmm22
    vmulpd   zmm3,  zmm3,  zmm22
    vmulpd   zmm5,  zmm5,  zmm22
    vmulpd   zmm2,  zmm2,  zmm22
    vmulpd   zmm24, zmm24, zmm22
    vmulpd   zmm26, zmm26, zmm22
    vmulpd   zmm28, zmm28, zmm22
    vmulpd   zmm25, zmm25, zmm22

    vmovupd  [r12 + 0],  zmm1
    vmovupd  [r13 + 0],  zmm3
    vmovupd  [rcx + 0],  zmm5
    vmovupd  [rax + 0],  zmm2
    vmovupd  [r12 + 64], zmm24
    vmovupd  [r13 + 64], zmm26
    vmovupd  [rcx + 64], zmm28
    vmovupd  [rax + 64], zmm25

    lea  r12, [r12 + 128]
    lea  r13, [r13 + 128]
    lea  rcx, [rcx + 128]
    lea  rax, [rax + 128]
    sub  r14, 8
    cmp  r14, 8
    jae  .Lfftinv_r4_loop8_scaled

.Lfftinv_r4_scaled_tail4:
    test r14, r14
    jz   .Lfftinv_done
    vmovupd  zmm0, [r12]
    vmovupd  zmm1, [r13]
    vmovupd  zmm2, [rcx]
    vmovupd  zmm3, [rax]
    vaddpd   zmm4, zmm0, zmm1
    vsubpd   zmm0, zmm0, zmm1
    vaddpd   zmm5, zmm2, zmm3
    vsubpd   zmm3, zmm2, zmm3
    vshufpd  zmm2, zmm3, zmm3, 0x55
    vxorpd   zmm2, zmm2, zmm21
    vaddpd   zmm1, zmm4, zmm5
    vsubpd   zmm5, zmm4, zmm5
    vaddpd   zmm3, zmm0, zmm2
    vsubpd   zmm2, zmm0, zmm2
    vmulpd   zmm1, zmm1, zmm22
    vmulpd   zmm3, zmm3, zmm22
    vmulpd   zmm5, zmm5, zmm22
    vmulpd   zmm2, zmm2, zmm22
    vmovupd  [r12], zmm1
    vmovupd  [r13], zmm3
    vmovupd  [rcx], zmm5
    vmovupd  [rax], zmm2
    jmp  .Lfftinv_done

.Lfftinv_r4_next_block:
    inc  r10
    cmp  r10, r8
    jb   .Lfftinv_r4_block

    shl  r9,  2
    jmp  .Lfftinv_r4_check

    // 2b. Leftover final single stage m == n_complex / 2 (b_blocks == 1, inv_tw[1] == (1, 0), fused 1/n scale!).
.Lfftinv_stage_check:
    cmp  r9,  rdx
    jae  .Lfftinv_done

    mov  r11, r9
    shl  r11, 4                         // m_bytes = m * 16
    mov  r12, rdi
    lea  r13, [r12 + r11]
    mov  r14, r9
    cmp  r14, 8
    jb   .Lfftinv_bfy4

.p2align 4
.Lfftinv_bfy8:
    vmovupd  zmm0, [r12 + 0]
    vmovupd  zmm1, [r13 + 0]
    vmovupd  zmm2, [r12 + 64]
    vmovupd  zmm3, [r13 + 64]
    vaddpd   zmm4, zmm0, zmm1
    vsubpd   zmm1, zmm0, zmm1
    vaddpd   zmm5, zmm2, zmm3
    vsubpd   zmm3, zmm2, zmm3
    vmulpd   zmm4, zmm4, zmm22
    vmulpd   zmm1, zmm1, zmm22
    vmulpd   zmm5, zmm5, zmm22
    vmulpd   zmm3, zmm3, zmm22
    vmovupd  [r12 + 0],  zmm4
    vmovupd  [r13 + 0],  zmm1
    vmovupd  [r12 + 64], zmm5
    vmovupd  [r13 + 64], zmm3
    lea  r12, [r12 + 128]
    lea  r13, [r13 + 128]
    sub  r14, 8
    cmp  r14, 8
    jae  .Lfftinv_bfy8

.Lfftinv_bfy4:
    test r14, r14
    jz   .Lfftinv_done
    vmovupd  zmm0, [r12]
    vmovupd  zmm1, [r13]
    vaddpd   zmm4, zmm0, zmm1
    vsubpd   zmm1, zmm0, zmm1
    vmulpd   zmm4, zmm4, zmm22
    vmulpd   zmm1, zmm1, zmm22
    vmovupd  [r12], zmm4
    vmovupd  [r13], zmm1
    jmp  .Lfftinv_done

.Lfftinv_n2:
    vmovupd  xmm0,  [rdi + 0]
    vmovupd  xmm1,  [rdi + 16]
    vaddpd   xmm3,  xmm0, xmm1
    vsubpd   xmm4,  xmm0, xmm1
    vmovddup xmm16, [rsi + 16]
    vmovddup xmm17, [rsi + 24]
    vshufpd  xmm2,  xmm4, xmm4, 0x01
    vmulpd   xmm2,  xmm2, xmm17
    vfmaddsub231pd xmm2, xmm4, xmm16
    mov  rax, 0x3FE0000000000000        // 0.5
    vmovq xmm5, rax
    vmovddup xmm5, xmm5
    vmulpd   xmm3, xmm3, xmm5
    vmulpd   xmm2, xmm2, xmm5
    vmovupd  [rdi + 0],  xmm3
    vmovupd  [rdi + 16], xmm2

.Lfftinv_done:
    VEC_LEAVE_FFT64

// [9] fft_pmul(dst: rdi, a: rsi, b: rdx, n_complex: rcx)
LOCAL_FN supi_k_fft_pmul
    LIMB_ENTER_FAST
    cmp  rcx, 8
    jb   .Lfftpmul_check4

.p2align 4
.Lfftpmul_loop8:
    vmovupd  zmm0,  [rsi + 0]
    vmovupd  zmm1,  [rdx + 0]
    vmovupd  zmm5,  [rsi + 64]
    vmovupd  zmm16, [rdx + 64]
    vmovddup zmm2,  zmm1
    vshufpd  zmm3,  zmm1,  zmm1,  0xFF
    vshufpd  zmm4,  zmm0,  zmm0,  0x55
    vmulpd   zmm4,  zmm4,  zmm3
    vfmaddsub213pd zmm0, zmm2, zmm4

    vmovddup zmm17, zmm16
    vshufpd  zmm18, zmm16, zmm16, 0xFF
    vshufpd  zmm19, zmm5,  zmm5,  0x55
    vmulpd   zmm19, zmm19, zmm18
    vfmaddsub213pd zmm5, zmm17, zmm19

    vmovupd  [rdi + 0],  zmm0
    vmovupd  [rdi + 64], zmm5
    lea  rsi, [rsi + 128]
    lea  rdx, [rdx + 128]
    lea  rdi, [rdi + 128]
    sub  rcx, 8
    cmp  rcx, 8
    jae  .Lfftpmul_loop8

.Lfftpmul_check4:
    cmp  rcx, 4
    jb   .Lfftpmul_tail
    vmovupd  zmm0, [rsi]
    vmovupd  zmm1, [rdx]
    vmovddup zmm2, zmm1
    vshufpd  zmm3, zmm1, zmm1, 0xFF
    vshufpd  zmm4, zmm0, zmm0, 0x55
    vmulpd   zmm4, zmm4, zmm3
    vfmaddsub213pd zmm0, zmm2, zmm4
    vmovupd  [rdi], zmm0
    lea  rsi, [rsi + 64]
    lea  rdx, [rdx + 64]
    lea  rdi, [rdi + 64]
    sub  rcx, 4

.Lfftpmul_tail:
    test rcx, rcx
    jz   .Lfftpmul_done
.Lfftpmul_loop1:
    vmovsd   xmm0, [rsi + 0]
    vmovsd   xmm1, [rsi + 8]
    vmovsd   xmm2, [rdx + 0]
    vmovsd   xmm3, [rdx + 8]
    vmulsd   xmm4, xmm1, xmm3
    vfmsub231sd xmm4, xmm0, xmm2
    vmulsd   xmm5, xmm1, xmm2
    vfmadd231sd xmm5, xmm0, xmm3
    vmovsd   [rdi + 0], xmm4
    vmovsd   [rdi + 8], xmm5
    lea  rsi, [rsi + 16]
    lea  rdx, [rdx + 16]
    lea  rdi, [rdi + 16]
    dec  rcx
    jnz  .Lfftpmul_loop1

.Lfftpmul_done:
    vzeroupper
    LIMB_LEAVE_FAST

// [10] fft_pmuladd(dst: rdi, ptrs: rsi, n_complex: rdx, sub_second: rcx)
LOCAL_FN supi_k_fft_pmuladd
    LIMB_ENTER_FAST
    mov  r8,  [rsi + 0]                 // a1
    mov  r9,  [rsi + 8]                 // b1
    mov  r10, [rsi + 16]                // a2
    mov  r11, [rsi + 24]                // b2
    cmp  rdx, 4
    jb   .Lfftpmuladd_tail
    test rcx, rcx
    jnz  .Lfftpmuladd_sub_entry

    cmp  rdx, 8
    jb   .Lfftpmuladd_add4
.p2align 4
.Lfftpmuladd_loop8_add:
    vmovupd  zmm0,  [r8  + 0]
    vmovupd  zmm1,  [r9  + 0]
    vmovupd  zmm16, [r8  + 64]
    vmovupd  zmm17, [r9  + 64]
    vmovddup zmm2,  zmm1
    vshufpd  zmm3,  zmm1,  zmm1,  0xFF
    vshufpd  zmm4,  zmm0,  zmm0,  0x55
    vmovddup zmm18, zmm17
    vshufpd  zmm19, zmm17, zmm17, 0xFF
    vshufpd  zmm20, zmm16, zmm16, 0x55
    vmulpd   zmm4,  zmm4,  zmm3
    vmulpd   zmm20, zmm20, zmm19
    vfmaddsub213pd zmm0,  zmm2,  zmm4
    vfmaddsub213pd zmm16, zmm18, zmm20

    vmovupd  zmm5,  [r10 + 0]
    vmovupd  zmm26, [r11 + 0]
    vmovupd  zmm21, [r10 + 64]
    vmovupd  zmm22, [r11 + 64]
    vmovddup zmm27, zmm26
    vshufpd  zmm28, zmm26, zmm26, 0xFF
    vshufpd  zmm29, zmm5,  zmm5,  0x55
    vmovddup zmm23, zmm22
    vshufpd  zmm24, zmm22, zmm22, 0xFF
    vshufpd  zmm25, zmm21, zmm21, 0x55
    vmulpd   zmm29, zmm29, zmm28
    vmulpd   zmm25, zmm25, zmm24
    vfmaddsub213pd zmm5,  zmm27, zmm29
    vfmaddsub213pd zmm21, zmm23, zmm25

    vaddpd   zmm0,  zmm0,  zmm5
    vaddpd   zmm16, zmm16, zmm21
    vmovupd  [rdi + 0],  zmm0
    vmovupd  [rdi + 64], zmm16
    lea  r8,  [r8  + 128]
    lea  r9,  [r9  + 128]
    lea  r10, [r10 + 128]
    lea  r11, [r11 + 128]
    lea  rdi, [rdi + 128]
    sub  rdx, 8
    cmp  rdx, 8
    jae  .Lfftpmuladd_loop8_add

.Lfftpmuladd_add4:
    cmp  rdx, 4
    jb   .Lfftpmuladd_tail
    vmovupd  zmm0,  [r8]
    vmovupd  zmm1,  [r9]
    vmovddup zmm2,  zmm1
    vshufpd  zmm3,  zmm1,  zmm1,  0xFF
    vshufpd  zmm4,  zmm0,  zmm0,  0x55
    vmulpd   zmm4,  zmm4,  zmm3
    vfmaddsub213pd zmm0, zmm2, zmm4
    vmovupd  zmm5,  [r10]
    vmovupd  zmm26, [r11]
    vmovddup zmm27, zmm26
    vshufpd  zmm28, zmm26, zmm26, 0xFF
    vshufpd  zmm29, zmm5,  zmm5,  0x55
    vmulpd   zmm29, zmm29, zmm28
    vfmaddsub213pd zmm5, zmm27, zmm29
    vaddpd   zmm0, zmm0, zmm5
    vmovupd  [rdi], zmm0
    lea  r8,  [r8  + 64]
    lea  r9,  [r9  + 64]
    lea  r10, [r10 + 64]
    lea  r11, [r11 + 64]
    lea  rdi, [rdi + 64]
    sub  rdx, 4
    jmp  .Lfftpmuladd_tail

.Lfftpmuladd_sub_entry:
    cmp  rdx, 8
    jb   .Lfftpmuladd_sub4
.p2align 4
.Lfftpmuladd_loop8_sub:
    vmovupd  zmm0,  [r8  + 0]
    vmovupd  zmm1,  [r9  + 0]
    vmovupd  zmm16, [r8  + 64]
    vmovupd  zmm17, [r9  + 64]
    vmovddup zmm2,  zmm1
    vshufpd  zmm3,  zmm1,  zmm1,  0xFF
    vshufpd  zmm4,  zmm0,  zmm0,  0x55
    vmovddup zmm18, zmm17
    vshufpd  zmm19, zmm17, zmm17, 0xFF
    vshufpd  zmm20, zmm16, zmm16, 0x55
    vmulpd   zmm4,  zmm4,  zmm3
    vmulpd   zmm20, zmm20, zmm19
    vfmaddsub213pd zmm0,  zmm2,  zmm4
    vfmaddsub213pd zmm16, zmm18, zmm20

    vmovupd  zmm5,  [r10 + 0]
    vmovupd  zmm26, [r11 + 0]
    vmovupd  zmm21, [r10 + 64]
    vmovupd  zmm22, [r11 + 64]
    vmovddup zmm27, zmm26
    vshufpd  zmm28, zmm26, zmm26, 0xFF
    vshufpd  zmm29, zmm5,  zmm5,  0x55
    vmovddup zmm23, zmm22
    vshufpd  zmm24, zmm22, zmm22, 0xFF
    vshufpd  zmm25, zmm21, zmm21, 0x55
    vmulpd   zmm29, zmm29, zmm28
    vmulpd   zmm25, zmm25, zmm24
    vfmaddsub213pd zmm5,  zmm27, zmm29
    vfmaddsub213pd zmm21, zmm23, zmm25

    vsubpd   zmm0,  zmm0,  zmm5
    vsubpd   zmm16, zmm16, zmm21
    vmovupd  [rdi + 0],  zmm0
    vmovupd  [rdi + 64], zmm16
    lea  r8,  [r8  + 128]
    lea  r9,  [r9  + 128]
    lea  r10, [r10 + 128]
    lea  r11, [r11 + 128]
    lea  rdi, [rdi + 128]
    sub  rdx, 8
    cmp  rdx, 8
    jae  .Lfftpmuladd_loop8_sub

.Lfftpmuladd_sub4:
    cmp  rdx, 4
    jb   .Lfftpmuladd_tail
    vmovupd  zmm0,  [r8]
    vmovupd  zmm1,  [r9]
    vmovddup zmm2,  zmm1
    vshufpd  zmm3,  zmm1,  zmm1,  0xFF
    vshufpd  zmm4,  zmm0,  zmm0,  0x55
    vmulpd   zmm4,  zmm4,  zmm3
    vfmaddsub213pd zmm0, zmm2, zmm4
    vmovupd  zmm5,  [r10]
    vmovupd  zmm26, [r11]
    vmovddup zmm27, zmm26
    vshufpd  zmm28, zmm26, zmm26, 0xFF
    vshufpd  zmm29, zmm5,  zmm5,  0x55
    vmulpd   zmm29, zmm29, zmm28
    vfmaddsub213pd zmm5, zmm27, zmm29
    vsubpd   zmm0, zmm0, zmm5
    vmovupd  [rdi], zmm0
    lea  r8,  [r8  + 64]
    lea  r9,  [r9  + 64]
    lea  r10, [r10 + 64]
    lea  r11, [r11 + 64]
    lea  rdi, [rdi + 64]
    sub  rdx, 4

.Lfftpmuladd_tail:
    test rdx, rdx
    jz   .Lfftpmuladd_done
.Lfftpmuladd_loop1:
    vmovsd   xmm0, [r8 + 0]
    vmovsd   xmm1, [r8 + 8]
    vmovsd   xmm2, [r9 + 0]
    vmovsd   xmm3, [r9 + 8]
    vmulsd   xmm4, xmm1, xmm3
    vfmsub231sd xmm4, xmm0, xmm2
    vmulsd   xmm5, xmm1, xmm2
    vfmadd231sd xmm5, xmm0, xmm3

    vmovsd   xmm16, [r10 + 0]
    vmovsd   xmm17, [r10 + 8]
    vmovsd   xmm18, [r11 + 0]
    vmovsd   xmm19, [r11 + 8]
    vmulsd   xmm20, xmm17, xmm19
    vfmsub231sd xmm20, xmm16, xmm18
    vmulsd   xmm21, xmm17, xmm18
    vfmadd231sd xmm21, xmm16, xmm19

    test rcx, rcx
    jnz  .Lfftpmuladd_sub1
    vaddsd   xmm4, xmm4, xmm20
    vaddsd   xmm5, xmm5, xmm21
    jmp  .Lfftpmuladd_store1
.Lfftpmuladd_sub1:
    vsubsd   xmm4, xmm4, xmm20
    vsubsd   xmm5, xmm5, xmm21
.Lfftpmuladd_store1:
    vmovsd   [rdi + 0], xmm4
    vmovsd   [rdi + 8], xmm5
    lea  r8,  [r8 + 16]
    lea  r9,  [r9 + 16]
    lea  r10, [r10 + 16]
    lea  r11, [r11 + 16]
    lea  rdi, [rdi + 16]
    dec  rdx
    jnz  .Lfftpmuladd_loop1

.Lfftpmuladd_done:
    vzeroupper
    LIMB_LEAVE_FAST

.macro FFT_COALESCE8 Z, C1, T4, C2
    vpsravq   \C1, \Z,  zmm20
    vpandq    \Z,  \Z,  zmm21
    valignq   \T4, \C1, zmm22, 7
    vpaddq    \Z,  \Z,  \T4
    vpsravq   \C2, \Z,  zmm20
    vpandq    \Z,  \Z,  zmm21
    vpaddq    \C1, \C1, \C2
    valignq   \T4, \C2, zmm22, 7
    vpaddq    \Z,  \Z,  \T4
    vpshufd   \T4, \Z,  0xEE
    vpsllvq   \T4, \T4, zmm20
    vpaddq    \Z,  \Z,  \T4
    vmovdqa64 \Z {k1}, \C1
.endm

// ---- fft_carry in one pass (16 <= b <= 24, n_complex a multiple of 8, n_complex * b a
// multiple of 64) ----------------------------------------------------------------------------
// A digit is a rounded coefficient, an i64, below 2^(3b - 1) in size for the coefficients of a
// product of balanced b-bit digits at any transform length in use. The real parts are digits
// 0..n-1, the imaginary parts digits n..2n-1; each half fills q0 = n*b/64 limbs. A register
// of four complex points holds digits r0, i0, r1, i1, r2, i2, r3, i3.
// Constants of a call:
//   zmm20 = b, zmm21 = 2^b - 1, zmm28 = ~(2^b - 1), zmm12 = the pairs of digits of eight points
//   gathered half by half, zmm29 / zmm30 = the left / right shifts that put each pair into the
//   limb it starts in and the one after, zmm31 / zmm11 / k5 = where those pieces go in the three
//   limbs of each half (k4), k6 = the lanes that take the bits shifted out of the limb below,
//   k3 = the first lane of each half, r8 = 8b, r14 = .Lconst_fy_acc.
// State: zmm23..zmm25 = what the top digits of the register before gave up in each round;
//   r11 / xmm8 = bits already used of the limbs in the making (xmm9 = 64 less that),
//   zmm27 = those limbs (lanes 0 and 4), r15 = their index; r10 / r9 = where the limbs of the
//   real / imaginary half go; zmm15, zmm7 = rounding error so far.

// One round: every digit keeps its low b bits and gives the rest to the next digit of its
// half, two lanes up (out of the top two lanes into \P, whose old top lanes come in at the
// bottom).
.macro FFT_CARRY_ROUND2 Z, P
    vpsravq   zmm16, \Z, zmm20
    vpandq    \Z, \Z, zmm21
    valignq   zmm17, zmm16, \P, 6
    vmovdqa64 \P, zmm16
    vpaddq    \Z, \Z, zmm17
.endm

// Digits to digits in [-1, 2^b] in three rounds: what a digit gives up is below 2^(2b - 1),
// then below 2^(b - 1) or so, then -1, 0 or 1. \K = the lanes left outside [0, 2^b): digits
// that were too large, or a last carry that met a digit at the end of its range.
.macro FFT_CARRY_SETTLE2 Z, K
    FFT_CARRY_ROUND2 \Z, zmm23
    FFT_CARRY_ROUND2 \Z, zmm24
    FFT_CARRY_ROUND2 \Z, zmm25
    vptestmq  \K, \Z, zmm28
.endm

.macro FFT_CARRY_ONE_PASS
.p2align 6
.Lfy_loop:
    // weights for eight complex points
    vmovupd  zmm0, [rsi + 0]
    vmovupd  zmm1, [rdx + 0]
    vmovddup zmm2, zmm1
    vshufpd  zmm3, zmm1, zmm1, 0xFF
    vshufpd  zmm4, zmm0, zmm0, 0x55
    vmulpd   zmm4, zmm4, zmm3
    vfmaddsub213pd zmm0, zmm2, zmm4

    vmovupd  zmm5, [rsi + 64]
    vmovupd  zmm1, [rdx + 64]
    vmovddup zmm2, zmm1
    vshufpd  zmm3, zmm1, zmm1, 0xFF
    vshufpd  zmm4, zmm5, zmm5, 0x55
    vmulpd   zmm4, zmm4, zmm3
    vfmaddsub213pd zmm5, zmm2, zmm4

    // rounding, its error, integers
    vrndscalepd zmm1, zmm0, 8
    vrndscalepd zmm2, zmm5, 8
    vsubpd      zmm0, zmm0, zmm1
    vsubpd      zmm5, zmm5, zmm2
    vrangepd    zmm15, zmm15, zmm0, 0x0B    // the larger in size, without its sign
    vrangepd    zmm7,  zmm7,  zmm5, 0x0B
    vcvttpd2qq  zmm1, zmm1
    vcvttpd2qq  zmm2, zmm2

    // carries
    FFT_CARRY_SETTLE2 zmm1, k2
    FFT_CARRY_SETTLE2 zmm2, k7
    kortestw k2, k7
    jnz  .Lfy_more
.Lfy_settled:

    // pairs of digits (lanes 0, 1, 4, 5), gathered: real half in lanes 0..3, imaginary in 4..7
    valignq  zmm16, zmm1, zmm1, 2
    vpsllq   zmm16, zmm16, xmm20
    vpaddq   zmm1, zmm1, zmm16
    valignq  zmm17, zmm2, zmm2, 2
    vpsllq   zmm17, zmm17, xmm20
    vpaddq   zmm2, zmm2, zmm17
    vpermt2q zmm1, zmm12, zmm2

    // the three limbs the eight points fill in each half
    vpsllvq  zmm16, zmm1, zmm29
    vpsrlvq  zmm17, zmm1, zmm30
    valignq  zmm18 {k5}{z}, zmm16, zmm16, 2
    vmovdqa64 zmm19, zmm16
    vpermt2q zmm19 {k4}{z}, zmm11, zmm17
    vpermt2q zmm16 {k4}{z}, zmm31, zmm17
    vpternlogq zmm16, zmm19, zmm18, 0xFE

    // to the bit the output stands at, joined to the limbs in the making; four limbs of each
    // half are stored and the two or three that are complete are kept
    vpsllq   zmm18, zmm16, xmm8
    vpsrlq   zmm16, zmm16, xmm9
    valignq  zmm16 {k6}{z}, zmm16, zmm16, 7
    vpternlogq zmm18, zmm16, zmm27, 0xFE
    vmovdqu64 [r10 + 8*r15], ymm18
    vextracti64x4 ymmword ptr [r9 + 8*r15], zmm18, 1

    lea  eax, [r11 + r8]
    mov  edi, eax
    shr  edi, 6                         // limbs completed: 2 or 3
    and  eax, 63
    mov  r11d, eax
    vpaddq xmm8, xmm8, xmm6
    vpandq xmm8, xmm8, xmmword ptr [rbx + 0]
    vpsubq xmm9, xmm26, xmm8
    add  r15, rdi
    shl  edi, 6
    vmovdqa64 zmm17, [r14 + rdi - 128]
    vpermq   zmm27 {k3}{z}, zmm17, zmm18

    lea  rsi, [rsi + 128]
    lea  rdx, [rdx + 128]
    sub  rcx, 8
    jnz  .Lfy_loop
    jmp  .Lfy_done

    // A digit is left at -1 or at 2^b: its carry has further to go than three rounds take it,
    // through digits at the end of their range. A product cut short of its length has them
    // where it is cut when what lies below is all zeros or all ones, as the top of an exact
    // quotient is. More rounds on these sixteen points alone, a digit's width further each,
    // until all are in range (eight at most, then every carry has left the points); what the
    // top digits give up joins the last round's carry for the next points. A call that needs
    // many such rounds has long runs of such digits and starts again digit by digit.
.Lfy_more:
    dec  dword ptr [rbx + 120]
    js   .Lfy_restart
    vpxorq    zmm18, zmm18, zmm18
    vpsravq   zmm16, zmm1, zmm20
    vpandq    zmm1, zmm1, zmm21
    valignq   zmm17, zmm16, zmm18, 6
    vpaddq    zmm1, zmm1, zmm17
    vpsravq   zmm19, zmm2, zmm20
    vpandq    zmm2, zmm2, zmm21
    valignq   zmm17, zmm19, zmm16, 6
    vpaddq    zmm2, zmm2, zmm17
    vpaddq    zmm25, zmm25, zmm19
    vptestmq  k2, zmm1, zmm28
    vptestmq  k7, zmm2, zmm28
    kortestw  k2, k7
    jnz  .Lfy_more
    jmp  .Lfy_settled
.endm


// [11] fft_carry(out_limbs: rdi, buf: rsi, inv_weights: rdx, cfg: rcx)
// FftCarryCfg: out_limbs@0, n_complex@8, coeff_bits@16, top_carry@24, max_err@32, check_word@40
// top_carry is written, not read: the signed carry out of the last coefficient.
// Converts balanced digits to 64-bit integers 8 at a time (vcvttpd2qq) and tracks
// max rounding error across 8 lanes with vrndscalepd + vandpd (AVX512DQ) + vmaxpd.
// From 16 to 24 bits a digit, where each half of the digits fills whole limbs, the call runs
// in one pass with the carries settled in the vector unit (FFT_CARRY_ONE_PASS): three rounds
// for every digit and more where a carry has further to go; a call with many such places
// starts again on the code below.
LOCAL_FN supi_k_fft_carry
    VEC_ENTER 128
    mov  rbx, rsp                       // rbx = fixed 64B-aligned frame base for locals
    mov  [rbx + 64], rdi                // out_limbs ptr
    mov  [rbx + 72], rsi                // buf ptr
    mov  [rbx + 80], rdx                // inv_weights ptr
    mov  [rbx + 88], rcx                // cfg ptr
    vxorpd xmm10, xmm10, xmm10          // rounding error seen by the one-by-one tail

    mov  r12, [rcx + 0]                 // out_len
    mov  r13, [rcx + 8]                 // n_complex
    mov  r14, [rcx + 16]                // b = coeff_bits

    // Fast stack sizing when FFT_CARRY_ONE_PASS can write the real half directly into out_limbs:
    //   16 <= b <= 24, n_complex >= 8, (n_complex & 7) == 0, (n_complex * b) % 64 == 0,
    //   and out_len >= q0 + 4 -> only allocate `8 * q0 + 64` bytes for the imaginary half!
    cmp  r13, 8
    jb   .Lfftcarry_alloc_full
    test r13b, 7
    jnz  .Lfftcarry_alloc_full
    cmp  r14, 16
    jb   .Lfftcarry_alloc_full
    cmp  r14, 24
    ja   .Lfftcarry_alloc_full
    mov  rax, r13
    imul rax, r14
    test al, 63
    jnz  .Lfftcarry_alloc_full
    shr  rax, 6                         // q0 = (n_complex * b) / 64
    lea  rcx, [rax + 4]
    cmp  r12, rcx
    jb   .Lfftcarry_alloc_full
    lea  rax, [8*rax + 95]
    and  rax, -64
    jmp  .Lfftcarry_probe

.Lfftcarry_alloc_full:
    // Dynamically allocate 64B-aligned `yi_buf` (`n_complex * 8` bytes, and 64 more for the
    // one-pass form's two halves) at [rsp] with 4 KiB stack probing
    lea  rax, [8*r13 + 127]
    and  rax, -64
    jz   .Lfftcarry_stk_ok
.Lfftcarry_probe:
    cmp  rax, 4096
    jbe  .Lfftcarry_probe_tail
    sub  rsp, 4096
    mov  qword ptr [rsp], 0
    sub  rax, 4096
    jmp  .Lfftcarry_probe
.Lfftcarry_probe_tail:
    sub  rsp, rax
    mov  qword ptr [rsp], 0
.Lfftcarry_stk_ok:
    mov  [rbx + 104], rsp               // yi_write_ptr = yi_buf base

    vpxorq zmm15, zmm15, zmm15          // zmm15 = max_err vector (8 lanes)
    mov  rax, 0x7FFFFFFFFFFFFFFF
    vpbroadcastq zmm14, rax             // zmm14 = abs mask for f64
    vmovdqa64 zmm12, [rip + .Lconst_idx_even]
    vmovdqa64 zmm13, [rip + .Lconst_idx_odd]

    cmp  r14, 8
    jb   .Lfftcarry_no_coal
    cmp  r14, 30
    ja   .Lfftcarry_no_coal
    vpbroadcastq zmm20, r14
    mov  eax, 1
    shlx rax, rax, r14
    dec  rax
    vpbroadcastq zmm21, rax
    vpxorq zmm22, zmm22, zmm22
    mov  eax, 0x80
    kmovw k1, eax
.Lfftcarry_no_coal:

    // Carry state across Pass 0 (real digits 0..n-1) and Pass 1 (imag digits n..2n-1):
    //   r8  = carry (signed i64)
    //   r9  = bit_buf (u64, holds r11 bits in [0..r11), high bits zero)
    //   r10 = out_limbs (*mut u64)
    //   r11 = bit_cnt (usize, 0..63)
    //   r15 = limb_idx (usize)
    xor  r8d,  r8d
    xor  r9d,  r9d
    mov  r10,  [rbx + 64]
    xor  r11d, r11d
    xor  r15d, r15d

    // Pass 0: Load `buf` and `inv_weights` ONCE, compute & round BOTH `yr` and `yi`,
    // save `yi` i64s to `yi_buf`, and carry-propagate `yr` with single-branch 64-bit packing!
    mov  rsi, [rbx + 72]                // buf
    mov  rdx, [rbx + 80]                // inv_weights
    mov  rcx, r13                       // remaining = n_complex
    cmp  rcx, 8
    jb   .Lfftcarry_p0_tail

    // 16..24 bits a digit, whole blocks of eight points, whole limbs a half: in one pass
    cmp  r14, 16
    jb   .Lfftcarry_vec8
    cmp  r14, 24
    ja   .Lfftcarry_vec8
    test r13b, 7
    jnz  .Lfftcarry_vec8
    mov  rax, r13
    imul rax, r14
    test al, 63
    jnz  .Lfftcarry_vec8
    shr  rax, 6
    mov  [rbx + 112], rax               // q0: the limbs each half fills
    lea  rdi, [rax + 4]
    cmp  r12, rdi
    jb   .Lfftcarry_fy_stack
    mov  r10, [rbx + 64]                // real half written directly into out_limbs!
    mov  r9,  rsp                       // imaginary half at [rsp]
    jmp  .Lfftcarry_fy_setup
.Lfftcarry_fy_stack:
    mov  r10, rsp                       // the real half's limbs, q0 and four of room
    lea  r9,  [rsp + 8*rax + 32]        // the imaginary half's
.Lfftcarry_fy_setup:
    vpternlogq zmm28, zmm28, zmm28, 0xFF
    vpxorq  zmm28, zmm28, zmm21         // ~(2^b - 1)
    // where a pair of digits starts among the bits of eight points: 0, 2b, 4b, 6b
    xor  edi, edi
    mov  [rbx + 0], rdi
    mov  [rbx + 32], rdi
    lea  edi, [r14 + r14]
    mov  [rbx + 8], rdi                 // 2b, in the first limb
    mov  [rbx + 40], rdi
    lea  edi, [4*r14 - 64]
    mov  [rbx + 16], rdi                // 4b, in the second
    mov  [rbx + 48], rdi
    lea  edi, [r14 + 2*r14]
    lea  edi, [2*rdi - 64]              // 6b, in the second limb up to 21 bits a digit
    vmovdqa64 zmm11, [rip + .Lconst_fy_idx2_two]
    mov  eax, 0x22
    cmp  r14, 22
    jb   1f
    sub  edi, 64                        // and in the third from 22
    vmovdqa64 zmm11, [rip + .Lconst_fy_idx2_three]
    xor  eax, eax
1:
    mov  [rbx + 24], rdi
    mov  [rbx + 56], rdi
    kmovw k5, eax
    vmovdqa64 zmm29, [rbx + 0]
    mov  qword ptr [rbx + 0], 63
    mov  qword ptr [rbx + 8], 0
    mov  eax, 64
    vpbroadcastq zmm30, rax
    vpsubq  zmm30, zmm30, zmm29
    vmovq   xmm26, rax
    vmovq   xmm9, rax                   // 64 less the bits used: none yet
    vpxor   xmm8, xmm8, xmm8
    vmovdqa64 zmm31, [rip + .Lconst_fy_idx1]
    vmovdqa64 zmm12, [rip + .Lconst_fy_gather]
    mov  eax, 0x77
    kmovw k4, eax
    mov  eax, 0x11
    kmovw k3, eax
    mov  eax, 0xEE
    kmovw k6, eax
    vpxorq  zmm23, zmm23, zmm23
    vpxorq  zmm24, zmm24, zmm24
    vpxorq  zmm25, zmm25, zmm25
    vpxorq  zmm27, zmm27, zmm27
    vpxorq  zmm7, zmm7, zmm7
    mov  dword ptr [rbx + 120], 4096     // the rounds beyond three that the call may take
    lea  r8d, [8*r14]                   // 8b
    mov  eax, r8d
    and  eax, 63
    vmovq xmm6, rax
    lea  r14, [rip + .Lconst_fy_acc]
    jmp  .Lfy_loop

.p2align 4
.Lfftcarry_vec8:
    // Load 8 complex numbers from buf and inv_weights (2 ZMMs each)
    vmovupd  zmm0, [rsi + 0]
    vmovupd  zmm1, [rdx + 0]
    vmovddup zmm2, zmm1
    vshufpd  zmm3, zmm1, zmm1, 0xFF
    vshufpd  zmm4, zmm0, zmm0, 0x55
    vmulpd   zmm4, zmm4, zmm3
    vfmaddsub213pd zmm0, zmm2, zmm4     // [yr0, yi0, yr1, yi1, yr2, yi2, yr3, yi3]

    vmovupd  zmm5, [rsi + 64]
    vmovupd  zmm6, [rdx + 64]
    vmovddup zmm7, zmm6
    vshufpd  zmm8, zmm6, zmm6, 0xFF
    vshufpd  zmm9, zmm5, zmm5, 0x55
    vmulpd   zmm9, zmm9, zmm8
    vfmaddsub213pd zmm5, zmm7, zmm9     // [yr4, yi4, yr5, yi5, yr6, yi6, yr7, yi7]

    vmovapd     zmm6, zmm0
    vpermt2pd   zmm0, zmm12, zmm5       // 8 real digits [yr0..yr7]
    vpermt2pd   zmm6, zmm13, zmm5       // 8 imag digits [yi0..yi7]

    vrndscalepd zmm1, zmm0, 8           // rr = round_ties_even(yr)
    vrndscalepd zmm7, zmm6, 8           // ri = round_ties_even(yi)
    vsubpd      zmm2, zmm0, zmm1
    vsubpd      zmm8, zmm6, zmm7
    vandpd      zmm2, zmm2, zmm14
    vandpd      zmm8, zmm8, zmm14
    vmaxpd      zmm2, zmm2, zmm8
    vmaxpd      zmm15, zmm15, zmm2      // track max_err across both yr and yi

    vcvttpd2qq  zmm1, zmm1              // 8 yr i64s
    vcvttpd2qq  zmm7, zmm7              // 8 yi i64s
    mov         [rbx + 96], rcx

    cmp  r14, 8
    jb   .Lfftcarry_p0_nocoal
    cmp  r14, 30
    ja   .Lfftcarry_p0_nocoal

    FFT_COALESCE8 zmm1, zmm3, zmm4, zmm5
    FFT_COALESCE8 zmm7, zmm3, zmm4, zmm5
    vmovdqa64   [rbx + 0], zmm1
    mov         rax, [rbx + 104]
    vmovdqa64   [rax], zmm7
    add         rax, 64
    mov         [rbx + 104], rax

    lea  ecx, [r14 + r14]               // ecx = 2*b in 16..60
    lea  rax, [r15 + 5]
    cmp  rax, r12
    ja   .Lfftcarry_prop4_safe

.Lfftcarry_prop4_fast:
    .irp OFF, 0, 16, 32, 48
    mov  rax, [rbx + \OFF]
    add  rax, r8
    sarx r8,  rax, rcx
    bzhi rax, rax, rcx
    shlx rdi, rax, r11
    or   r9,  rdi
    mov  [r10 + 8*r15], r9
    mov  edi, 63
    sub  edi, r11d
    shr  rax, 1
    shrx rax, rax, rdi
    add  r11d, ecx
    mov  edi, r11d
    and  r11d, 63
    shr  edi, 6
    cmovnz r9, rax
    add  r15, rdi
    .endr
    add  r8, [rbx + 56]
    jmp  .Lfftcarry_after_prop8

.Lfftcarry_prop4_safe:
    .irp OFF, 0, 16, 32, 48
    mov  rax, [rbx + \OFF]
    add  rax, r8
    sarx r8,  rax, rcx
    bzhi rax, rax, rcx
    shlx rdi, rax, r11
    or   r9,  rdi
    add  r11, rcx
    cmp  r11, 64
    jb   1f
    cmp  r15, r12
    jae  2f
    mov  [r10 + 8*r15], r9
2:
    inc  r15
    sub  r11, 64
    mov  edi, ecx
    sub  edi, r11d
    shrx r9,  rax, rdi
1:
    .endr
    add  r8, [rbx + 56]
    jmp  .Lfftcarry_after_prop8

.Lfftcarry_p0_nocoal:
    vmovdqa64   [rbx + 0], zmm1
    mov         rax, [rbx + 104]
    vmovdqa64   [rax], zmm7
    add         rax, 64
    mov         [rbx + 104], rax

    xor  ecx, ecx                       // lane = 0..7
    cmp  r14, 64
    jae  .Lfftcarry_prop8
    lea  rax, [r15 + 8]
    cmp  rax, r12
    ja   .Lfftcarry_prop8

.Lfftcarry_prop8_fast:
    .irp lane, 0, 1, 2, 3, 4, 5, 6, 7
    mov  rax, [rbx + 8*\lane]           // d (i64)
    add  rax, r8                        // val = d + carry
    sarx r8,  rax, r14                  // carry = val >> b (arithmetic, BMI2)
    bzhi rax, rax, r14                  // coeff = val & ((1 << b) - 1)
    shlx rdi, rax, r11                  // coeff << bit_cnt
    or   r9,  rdi
    mov  [r10 + 8*r15], r9
    mov  edi, 63
    sub  edi, r11d
    shr  rax, 1
    shrx rax, rax, rdi                  // hi_part = coeff >> (64 - bit_cnt)
    add  r11d, r14d                     // new_cnt = bit_cnt + b
    mov  edi, r11d
    and  r11d, 63
    shr  edi, 6                         // emit = new_cnt >> 6 in {0, 1}; ZF=0 iff emit==1
    cmovnz r9, rax
    add  r15, rdi
    .endr
    jmp  .Lfftcarry_after_prop8

.Lfftcarry_prop8:
    mov  rax, [rbx + 8*rcx]             // d (i64)
    add  rax, r8                        // val = d + carry
    sarx r8,  rax, r14                  // carry = val >> b (arithmetic, BMI2)
    bzhi rax, rax, r14                  // coeff = val & ((1 << b) - 1)
    shlx rdi, rax, r11                  // coeff << bit_cnt
    or   r9,  rdi
    add  r11, r14                       // bit_cnt += b
    cmp  r11, 64
    jb   .Lfftcarry_next_lane8
    cmp  r15, r12
    jae  .Lfftcarry_skip_store8
    mov  [r10 + 8*r15], r9
.Lfftcarry_skip_store8:
    inc  r15
    sub  r11, 64
    mov  edi, r14d
    sub  edi, r11d
    shrx r9,  rax, rdi
.Lfftcarry_next_lane8:
    inc  ecx
    cmp  ecx, 8
    jb   .Lfftcarry_prop8

.Lfftcarry_after_prop8:

    mov  rcx, [rbx + 96]
    lea  rsi, [rsi + 128]
    lea  rdx, [rdx + 128]
    sub  rcx, 8
    cmp  rcx, 8
    jae  .Lfftcarry_vec8

.Lfftcarry_p0_tail:
    test rcx, rcx
    jz   .Lfftcarry_pass1
    mov  [rbx + 96], rcx
.Lfftcarry_p0_scalar:
    vmovsd      xmm0, [rsi + 0]         // zr
    vmovsd      xmm1, [rsi + 8]         // zi
    vmovsd      xmm2, [rdx + 0]         // wr
    vmovsd      xmm3, [rdx + 8]         // wi
    vmulsd      xmm4, xmm1, xmm3
    vfmsub231sd xmm4, xmm0, xmm2        // yr
    vmulsd      xmm7, xmm0, xmm3
    vfmadd231sd xmm7, xmm1, xmm2        // yi

    vrndscalesd xmm5, xmm4, xmm4, 8
    vrndscalesd xmm8, xmm7, xmm7, 8
    vsubsd      xmm6, xmm4, xmm5
    vsubsd      xmm9, xmm7, xmm8
    vandpd      xmm6, xmm6, xmm14
    vandpd      xmm9, xmm9, xmm14
    vmaxsd      xmm10, xmm10, xmm6      // not into xmm15: that would clear its other lanes
    vmaxsd      xmm10, xmm10, xmm9

    vcvttsd2si  rax, xmm8               // yi (i64)
    mov         rdi, [rbx + 104]
    mov         [rdi], rax
    add         rdi, 8
    mov         [rbx + 104], rdi

    vcvttsd2si  rax, xmm5               // yr (i64)
    add  rax, r8
    sarx r8,  rax, r14
    bzhi rax, rax, r14
    shlx rdi, rax, r11
    or   r9,  rdi
    add  r11, r14
    cmp  r11, 64
    jb   .Lfftcarry_p0_next1
    cmp  r15, r12
    jae  .Lfftcarry_p0_skip1
    mov  [r10 + 8*r15], r9
.Lfftcarry_p0_skip1:
    inc  r15
    sub  r11, 64
    mov  edi, r14d
    sub  edi, r11d
    shrx r9,  rax, rdi
.Lfftcarry_p0_next1:
    lea  rsi, [rsi + 16]
    lea  rdx, [rdx + 16]
    dec  qword ptr [rbx + 96]
    jnz  .Lfftcarry_p0_scalar

    // Pass 1: Pure GPR carry-propagation over pre-rounded `yi_buf` at [rsp]!
.Lfftcarry_pass1:
    mov  rsi, rsp                       // yi_buf
    mov  rcx, r13                       // n_complex
    test rcx, rcx
    jz   .Lfftcarry_after_pass1
    cmp  rcx, 8
    jb   .Lfftcarry_p1_loop

    cmp  r14, 8
    jb   .Lfftcarry_p1_check64
    cmp  r14, 30
    ja   .Lfftcarry_p1_check64
    lea  edx, [r14 + r14]               // edx = 2*b in 16..60

.p2align 4
.Lfftcarry_p1_fast4:
    lea  rax, [r15 + 5]
    cmp  rax, r12
    ja   .Lfftcarry_p1_safe4

    .irp OFF, 0, 16, 32, 48
    mov  rax, [rsi + \OFF]
    add  rax, r8
    sarx r8,  rax, rdx
    bzhi rax, rax, rdx
    shlx rdi, rax, r11
    or   r9,  rdi
    mov  [r10 + 8*r15], r9
    mov  edi, 63
    sub  edi, r11d
    shr  rax, 1
    shrx rax, rax, rdi
    add  r11d, edx
    mov  edi, r11d
    and  r11d, 63
    shr  edi, 6
    cmovnz r9, rax
    add  r15, rdi
    .endr
    add  r8, [rsi + 56]
    add  rsi, 64
    sub  rcx, 8
    cmp  rcx, 8
    jae  .Lfftcarry_p1_fast4
    test rcx, rcx
    jz   .Lfftcarry_after_pass1
    jmp  .Lfftcarry_p1_loop

.Lfftcarry_p1_safe4:
    .irp OFF, 0, 16, 32, 48
    mov  rax, [rsi + \OFF]
    add  rax, r8
    sarx r8,  rax, rdx
    bzhi rax, rax, rdx
    shlx rdi, rax, r11
    or   r9,  rdi
    add  r11, rdx
    cmp  r11, 64
    jb   1f
    cmp  r15, r12
    jae  2f
    mov  [r10 + 8*r15], r9
2:
    inc  r15
    sub  r11, 64
    mov  edi, edx
    sub  edi, r11d
    shrx r9,  rax, rdi
1:
    .endr
    add  r8, [rsi + 56]
    add  rsi, 64
    sub  rcx, 8
    cmp  rcx, 8
    jae  .Lfftcarry_p1_safe4
    test rcx, rcx
    jz   .Lfftcarry_after_pass1
    jmp  .Lfftcarry_p1_loop

.Lfftcarry_p1_check64:
    cmp  r14, 64
    jae  .Lfftcarry_p1_loop

.p2align 4
.Lfftcarry_p1_fast8:
    lea  rax, [r15 + 8]
    cmp  rax, r12
    ja   .Lfftcarry_p1_loop

    .irp OFF, 0, 8, 16, 24, 32, 40, 48, 56
    mov  rax, [rsi + \OFF]
    add  rax, r8
    sarx r8,  rax, r14
    bzhi rax, rax, r14
    shlx rdi, rax, r11
    or   r9,  rdi
    mov  [r10 + 8*r15], r9
    mov  edi, 63
    sub  edi, r11d
    shr  rax, 1
    shrx rax, rax, rdi
    add  r11d, r14d
    mov  edi, r11d
    and  r11d, 63
    shr  edi, 6
    cmovnz r9, rax
    add  r15, rdi
    .endr

    add  rsi, 64
    sub  rcx, 8
    cmp  rcx, 8
    jae  .Lfftcarry_p1_fast8
    test rcx, rcx
    jz   .Lfftcarry_after_pass1

.p2align 4
.Lfftcarry_p1_loop:
    mov  rax, [rsi]
    add  rsi, 8
    add  rax, r8
    sarx r8,  rax, r14
    bzhi rax, rax, r14
    shlx rdi, rax, r11
    or   r9,  rdi
    add  r11, r14
    cmp  r11, 64
    jb   .Lfftcarry_p1_next
    cmp  r15, r12
    jae  .Lfftcarry_p1_skip
    mov  [r10 + 8*r15], r9
.Lfftcarry_p1_skip:
    inc  r15
    sub  r11, 64
    mov  edi, r14d
    sub  edi, r11d
    shrx r9,  rax, rdi
.Lfftcarry_p1_next:
    dec  rcx
    jnz  .Lfftcarry_p1_loop

.Lfftcarry_after_pass1:
    // Flush positive carry and remaining bit_buf into out_limbs
    xor  r10d, r10d
    cmp  r8,  0
    jle  .Lfftcarry_flush_buf
    shlx rdi, r8, r11
    or   r9,  rdi
    test r11, r11
    jz   .Lfftcarry_flush_buf
    mov  edi, 64
    sub  edi, r11d
    shrx r10, r8, rdi

.Lfftcarry_flush_buf:
    mov  rdi, [rbx + 64]
    cmp  r11, 0
    jne  .Lfftcarry_emit_last
    mov  rax, r9
    or   rax, r10
    jz   .Lfftcarry_zero_rem
.Lfftcarry_emit_last:
    cmp  r15, r12
    jae  .Lfftcarry_clamp_emit
    mov  [rdi + 8*r15], r9
    inc  r15
    test r10, r10
    jz   .Lfftcarry_zero_rem
    cmp  r15, r12
    jae  .Lfftcarry_clamp_emit
    mov  [rdi + 8*r15], r10
    inc  r15

.Lfftcarry_zero_rem:
    mov  r13, r15
    cmp  r15, r12
    jae  .Lfftcarry_clamp_emit
    vpxorq zmm0, zmm0, zmm0
    mov  rcx, r12
    sub  rcx, r15
    lea  rsi, [rdi + 8*r15]
    cmp  rcx, 8
    jb   .Lfftcarry_zrem_tail
.Lfftcarry_zrem_vec8:
    vmovdqu64 [rsi], zmm0
    add  rsi, 64
    sub  rcx, 8
    cmp  rcx, 8
    jae  .Lfftcarry_zrem_vec8
.Lfftcarry_zrem_tail:
    test rcx, rcx
    jz   .Lfftcarry_reduce_err
    xor  eax, eax
.Lfftcarry_zrem_loop:
    mov  [rsi], rax
    add  rsi, 8
    dec  rcx
    jnz  .Lfftcarry_zrem_loop
    jmp  .Lfftcarry_reduce_err

.Lfftcarry_clamp_emit:
    mov  r13, r12

.Lfftcarry_reduce_err:
    // Horizontal max of zmm15 -> xmm15[0]
    vextractf64x4 ymm0, zmm15, 1
    vmaxpd   ymm0, ymm0, ymm15
    vextractf128 xmm1, ymm0, 1
    vmaxpd   xmm0, xmm0, xmm1
    vshufpd  xmm1, xmm0, xmm0, 1
    vmaxsd   xmm0, xmm0, xmm1
    vmaxsd   xmm0, xmm0, xmm10
    mov  rcx, [rbx + 88]                // cfg
    vmovsd   [rcx + 32], xmm0           // cfg.max_err
    mov  [rcx + 24], r8                 // cfg.top_carry = the carry left after the last coefficient

    // Inline ZMM w0 reduction over emitted non-zero-padded limbs [0..r13) (zero call overhead,
    // zero trailing-zero scan, single vzeroupper in VEC_LEAVE):
    mov  r12, [rbx + 64]                // limbs = out_limbs
    mov  r9,  0x1FFFFFFFFFFFFFFF        // MOD_W0 = 2^61 - 1
    mov  r10, 0x03FFFFFFFFFFFFFF        // (1 << 58) - 1
    xor  eax, eax                       // w0 = 0
    test r13, r13
    jz   .Lfftcarry_w0_done

    mov  rcx, r13
    and  rcx, 7
    mov  r15, r13
    and  r15, -8                        // vec_n = emit_len & !7
    jz   .Lfftcarry_w0_peel_only
    test rcx, rcx
    jz   .Lfftcarry_w0_vec_init

.Lfftcarry_w0_peel_only:
    mov  r8,  r13
.Lfftcarry_w0_peel_loop:
    cmp  r8,  r15
    jbe  .Lfftcarry_w0_vec_check
    dec  r8
    mov  rdx, [r12 + 8*r8]
    mov  rsi, rdx
    and  rsi, r9
    shr  rdx, 61
    add  rsi, rdx
    mov  rdx, rsi
    sub  rdx, r9
    cmovae rsi, rdx

    mov  rdx, rax
    and  rdx, r10
    shl  rdx, 3
    shr  rax, 58
    add  rax, rdx
    mov  rdx, rax
    sub  rdx, r9
    cmovae rax, rdx
    add  rax, rsi
    mov  rdx, rax
    sub  rdx, r9
    cmovae rax, rdx
    jmp  .Lfftcarry_w0_peel_loop

.Lfftcarry_w0_vec_check:
    test r15, r15
    jz   .Lfftcarry_w0_done

.Lfftcarry_w0_vec_init:
    vmovq        xmm0, rax
    vpbroadcastq zmm16, r9              // MOD_W0
    mov  rdx, 0x0000001FFFFFFFFF        // (1 << 37) - 1
    vpbroadcastq zmm17, rdx

    lea  rsi, [r12 + 8*r15 - 64]
    mov  rcx, r15
    shr  rcx, 3
    test cl, 1
    jz   .Lfftcarry_w0_pairs
    vmovdqu64 zmm1, [rsi]
    vpandq    zmm2, zmm0, zmm17
    vpsllq    zmm2, zmm2, 24
    vpsrlq    zmm0, zmm0, 37
    vpaddq    zmm0, zmm0, zmm2
    vpandq    zmm3, zmm1, zmm16
    vpsrlq    zmm1, zmm1, 61
    vpaddq    zmm3, zmm3, zmm1
    vpaddq    zmm0, zmm0, zmm3
    sub  rsi, 64
    dec  rcx
    jz   .Lfftcarry_w0_vec_done
.Lfftcarry_w0_pairs:
    vpxorq    zmm18, zmm18, zmm18
    mov  edx, 0x1FFF
    vpbroadcastq zmm19, rdx
.p2align 4
.Lfftcarry_w0_vec_loop:
    vmovdqu64 zmm4, [rsi]
    vmovdqu64 zmm1, [rsi - 64]
    vpandq    zmm2, zmm0,  zmm19
    vpandq    zmm5, zmm18, zmm19
    vpsllq    zmm2, zmm2,  48
    vpsllq    zmm5, zmm5,  48
    vpsrlq    zmm0,  zmm0,  13
    vpsrlq    zmm18, zmm18, 13
    vpaddq    zmm0,  zmm0,  zmm2
    vpaddq    zmm18, zmm18, zmm5

    vpandq    zmm3,  zmm1, zmm16
    vpandq    zmm20, zmm4, zmm16
    vpsrlq    zmm1,  zmm1, 61
    vpsrlq    zmm4,  zmm4, 61
    vpaddq    zmm3,  zmm3,  zmm1
    vpaddq    zmm20, zmm20, zmm4
    vpaddq    zmm0,  zmm0,  zmm3
    vpaddq    zmm18, zmm18, zmm20

    sub  rsi, 128
    sub  rcx, 2
    jnz  .Lfftcarry_w0_vec_loop

    vpandq    zmm2,  zmm18, zmm17
    vpsllq    zmm2,  zmm2,  24
    vpsrlq    zmm18, zmm18, 37
    vpaddq    zmm18, zmm18, zmm2
    vpaddq    zmm0,  zmm0,  zmm18
.Lfftcarry_w0_vec_done:
    vmovdqa64 [rbx + 0], zmm0
    xor  eax, eax
    mov  ecx, 7
.Lfftcarry_w0_hfold:
    mov  rsi, [rbx + 8*rcx]
    mov  rdx, rsi
    and  rsi, r9
    shr  rdx, 61
    add  rsi, rdx
    mov  rdx, rsi
    sub  rdx, r9
    cmovae rsi, rdx

    mov  rdx, rax
    and  rdx, r10
    shl  rdx, 3
    shr  rax, 58
    add  rax, rdx
    mov  rdx, rax
    sub  rdx, r9
    cmovae rax, rdx
    add  rax, rsi
    mov  rdx, rax
    sub  rdx, r9
    cmovae rax, rdx
    sub  ecx, 1
    jnc  .Lfftcarry_w0_hfold

.Lfftcarry_w0_done:
    mov  rcx, [rbx + 88]
    mov  [rcx + 40], rax                // cfg.check_word = w0
    VEC_LEAVE

    FFT_CARRY_ONE_PASS

// All points done. What the top digit of the real half gave up belongs at the bottom of the
// imaginary half, whose own top digit's share is the carry out of the whole.
.Lfy_done:
    vpaddq    zmm16, zmm23, zmm24
    vpaddq    zmm16, zmm16, zmm25
    vextracti64x2 xmm16, zmm16, 3
    vmovq     rax, xmm16                // out of the real half
    vpextrq   r8, xmm16, 1              // out of the imaginary half
    vrangepd  zmm15, zmm15, zmm7, 0x0B
    cqo                                 // rdx = the limbs above rax: 0 or -1
    add  [r9], rax
    setc al
    xor  edi, edi
.Lfy_ripple:
    movzx ecx, al
    add  rcx, rdx                       // carry and limb above: nothing left when they cancel
    jz   .Lfy_copy
    inc  rdi
    cmp  rdi, r15
    jae  .Lfy_ripple_top
    add  al, 0xFF                       // the carry back into CF
    adc  [r9 + 8*rdi], rdx
    setc al
    jmp  .Lfy_ripple
.Lfy_ripple_top:
    add  r8, rcx                        // ran through the whole half: into the carry out
.Lfy_copy:
    // Copy imaginary half (and real half only if staged on stack) using 512-bit ZMM vectors
    mov  rdi, [rbx + 64]
    cmp  r10, rdi
    je   .Lfy_copy_imag_only
    cmp  r12, r15
    jbe  .Lfy_copy_real_only
    mov  rcx, r15
    mov  rsi, r10
    cmp  rcx, 8
    jb   .Lfy_copy_real_tail
.Lfy_copy_real_vec8:
    vmovdqu64 zmm0, [rsi]
    vmovdqu64 [rdi], zmm0
    add  rsi, 64
    add  rdi, 64
    sub  rcx, 8
    cmp  rcx, 8
    jae  .Lfy_copy_real_vec8
.Lfy_copy_real_tail:
    test rcx, rcx
    jz   .Lfy_copy_after_real
.Lfy_copy_real_s1:
    mov  rax, [rsi]
    mov  [rdi], rax
    add  rsi, 8
    add  rdi, 8
    dec  rcx
    jnz  .Lfy_copy_real_s1
.Lfy_copy_after_real:
    mov  rcx, r12
    sub  rcx, r15
    cmp  rcx, r15
    cmova rcx, r15
    mov  rsi, r9
    jmp  .Lfy_copy_vec
.Lfy_copy_real_only:
    mov  rcx, r12
    mov  rsi, r10
    jmp  .Lfy_copy_vec
.Lfy_copy_imag_only:
    lea  rdi, [rdi + 8*r15]
    mov  rcx, r12
    sub  rcx, r15
    cmp  rcx, r15
    cmova rcx, r15
    mov  rsi, r9
.Lfy_copy_vec:
    cmp  rcx, 32
    jb   .Lfy_copy_vec8
.p2align 4
.Lfy_copy_vec32:
    vmovdqu64 zmm0, [rsi + 0]
    vmovdqu64 zmm1, [rsi + 64]
    vmovdqu64 zmm2, [rsi + 128]
    vmovdqu64 zmm3, [rsi + 192]
    vmovdqu64 [rdi + 0],   zmm0
    vmovdqu64 [rdi + 64],  zmm1
    vmovdqu64 [rdi + 128], zmm2
    vmovdqu64 [rdi + 192], zmm3
    add  rsi, 256
    add  rdi, 256
    sub  rcx, 32
    cmp  rcx, 32
    jae  .Lfy_copy_vec32
.Lfy_copy_vec8:
    cmp  rcx, 8
    jb   .Lfy_copy_tail
.Lfy_copy_vec8_loop:
    vmovdqu64 zmm0, [rsi]
    vmovdqu64 [rdi], zmm0
    add  rsi, 64
    add  rdi, 64
    sub  rcx, 8
    cmp  rcx, 8
    jae  .Lfy_copy_vec8_loop
.Lfy_copy_tail:
    test rcx, rcx
    jz   .Lfy_copy_done
.Lfy_copy_tail_loop:
    mov  rax, [rsi]
    mov  [rdi], rax
    add  rsi, 8
    add  rdi, 8
    dec  rcx
    jnz  .Lfy_copy_tail_loop
.Lfy_copy_done:
    // the old code's ending: a carry out above zero is one more limb, the rest of the output
    // zero, then the error and the check word
    add  r15, r15
    xor  r9d, r9d
    xor  r11d, r11d
    jmp  .Lfftcarry_after_pass1

// Too many digits did not settle in three rounds: the whole call again, digit by digit.
.Lfy_restart:
    mov  rsp, rbx
    lea  rax, [8*r13 + 127]
    and  rax, -64
    jz   .Lfy_restart_stk_ok
.Lfy_restart_probe:
    cmp  rax, 4096
    jbe  .Lfy_restart_probe_tail
    sub  rsp, 4096
    mov  qword ptr [rsp], 0
    sub  rax, 4096
    jmp  .Lfy_restart_probe
.Lfy_restart_probe_tail:
    sub  rsp, rax
    mov  qword ptr [rsp], 0
.Lfy_restart_stk_ok:
    mov  rcx, [rbx + 88]
    mov  r14, [rcx + 16]
    vmovdqa64 zmm12, [rip + .Lconst_idx_even]
    vpxorq zmm15, zmm15, zmm15
    xor  r8d,  r8d
    xor  r9d,  r9d
    mov  r10,  [rbx + 64]
    xor  r11d, r11d
    xor  r15d, r15d
    mov  [rbx + 104], rsp
    mov  rsi, [rbx + 72]
    mov  rdx, [rbx + 80]
    mov  rcx, r13
    jmp  .Lfftcarry_vec8

// ============================================================================
// 5. Family 3 — NTT Kernels (8): 8 residues/ZMM, Radix-16 in ZMM0..ZMM31
// ============================================================================

// Four-vector (32-lane) f64 modular multiply helper saturating dual 512-bit FMA pipes.
// Scratch: zmm16..zmm19, zmm23..zmm26, masks k1..k4; constants zmm29=p, zmm30=inv_p, zmm31=0.0.
// Caller must NOT pass zmm16..19 or zmm23..26 as B (e.g. use zmm28).
.macro ZMM_MUL_MOD4 A0, A1, A2, A3, B
    vmulpd       zmm16, \A0, \B
    vmulpd       zmm17, \A1, \B
    vmulpd       zmm18, \A2, \B
    vmulpd       zmm19, \A3, \B
    vmulpd       zmm23, zmm16, zmm30
    vmulpd       zmm24, zmm17, zmm30
    vmulpd       zmm25, zmm18, zmm30
    vmulpd       zmm26, zmm19, zmm30
    vfmsub213pd  \A0, \B, zmm16
    vfmsub213pd  \A1, \B, zmm17
    vfmsub213pd  \A2, \B, zmm18
    vfmsub213pd  \A3, \B, zmm19
    vrndscalepd  zmm23, zmm23, 8
    vrndscalepd  zmm24, zmm24, 8
    vrndscalepd  zmm25, zmm25, 8
    vrndscalepd  zmm26, zmm26, 8
    vfnmadd231pd zmm16, zmm23, zmm29
    vfnmadd231pd zmm17, zmm24, zmm29
    vfnmadd231pd zmm18, zmm25, zmm29
    vfnmadd231pd zmm19, zmm26, zmm29
    vaddpd       \A0, zmm16, \A0
    vaddpd       \A1, zmm17, \A1
    vaddpd       \A2, zmm18, \A2
    vaddpd       \A3, zmm19, \A3
    vcmppd       k1, \A0, zmm31, 1
    vcmppd       k2, \A1, zmm31, 1
    vcmppd       k3, \A2, zmm31, 1
    vcmppd       k4, \A3, zmm31, 1
    vaddpd       \A0 {k1}, \A0, zmm29
    vaddpd       \A1 {k2}, \A1, zmm29
    vaddpd       \A2 {k3}, \A2, zmm29
    vaddpd       \A3 {k4}, \A3, zmm29
.endm


// Lazy step of the Horner chain over 48-bit chunks, for p > 2^48 (zmm29 = p, \KP = 2^48 * inv_p):
// zmm16..19 = zmm0..3 * 2^48 - q * p with q the rounded quotient. \K holds 2^48 (exact power of 2),
// so fl((zmm0 * 2^48) * inv_p) == fl(zmm0 * (2^48 * inv_p)) bit-for-bit, breaking the serial H -> Q
// dependency (-3 cycles per step!). Scratch: zmm23..26.
.macro ZMM_MUL48_LAZY4 K, KP
    vmulpd       zmm16, zmm0, \K
    vmulpd       zmm17, zmm1, \K
    vmulpd       zmm18, zmm2, \K
    vmulpd       zmm19, zmm3, \K
    vmulpd       zmm23, zmm0, \KP
    vmulpd       zmm24, zmm1, \KP
    vmulpd       zmm25, zmm2, \KP
    vmulpd       zmm26, zmm3, \KP
    vrndscalepd  zmm23, zmm23, 8
    vrndscalepd  zmm24, zmm24, 8
    vrndscalepd  zmm25, zmm25, 8
    vrndscalepd  zmm26, zmm26, 8
    vfnmadd231pd zmm16, zmm23, zmm29
    vfnmadd231pd zmm17, zmm24, zmm29
    vfnmadd231pd zmm18, zmm25, zmm29
    vfnmadd231pd zmm19, zmm26, zmm29
.endm

// One step of the chain: zmm0..3 = zmm0..3 * 2^48 + the chunks at \SRC, lazy.
.macro ZMM_HORNER48_LAZY4 K, KP, SRC
    ZMM_MUL48_LAZY4 \K, \KP
    vaddpd       zmm0, zmm16, [\SRC + 0]
    vaddpd       zmm1, zmm17, [\SRC + 64]
    vaddpd       zmm2, zmm18, [\SRC + 128]
    vaddpd       zmm3, zmm19, [\SRC + 192]
.endm

// \A0..\A3 += p where negative; -= p where p or more (zmm31 = 0.0).
.macro ZMM_FIX_NEG4 A0, A1, A2, A3
    vcmppd       k1, \A0, zmm31, 1
    vcmppd       k2, \A1, zmm31, 1
    vcmppd       k3, \A2, zmm31, 1
    vcmppd       k4, \A3, zmm31, 1
    vaddpd       \A0 {k1}, \A0, zmm29
    vaddpd       \A1 {k2}, \A1, zmm29
    vaddpd       \A2 {k3}, \A2, zmm29
    vaddpd       \A3 {k4}, \A3, zmm29
.endm

.macro ZMM_FIX_GE4 A0, A1, A2, A3
    vcmppd       k1, \A0, zmm29, 13
    vcmppd       k2, \A1, zmm29, 13
    vcmppd       k3, \A2, zmm29, 13
    vcmppd       k4, \A3, zmm29, 13
    vsubpd       \A0 {k1}, \A0, zmm29
    vsubpd       \A1 {k2}, \A1, zmm29
    vsubpd       \A2 {k3}, \A2, zmm29
    vsubpd       \A3 {k4}, \A3, zmm29
.endm

// The last step of the chain: zmm0..3 = (zmm0..3 * 2^48 + the chunks at \SRC) mod p, in [0, p).
.macro ZMM_HORNER48_LAST4 K, KP, SRC
    ZMM_MUL48_LAZY4 \K, \KP
    ZMM_FIX_NEG4 zmm16, zmm17, zmm18, zmm19
    vaddpd       zmm0, zmm16, [\SRC + 0]
    vaddpd       zmm1, zmm17, [\SRC + 64]
    vaddpd       zmm2, zmm18, [\SRC + 128]
    vaddpd       zmm3, zmm19, [\SRC + 192]
    ZMM_FIX_GE4 zmm0, zmm1, zmm2, zmm3
.endm

// [12] ntt_split(dst: rdi, limbs: rsi, cfg: rdx)
// NttSplitCfg: in_limbs@0, start_coeff@8, count@16, coeff_bits@24,
//              col_stride@32, cols_per_row@40, p@48, inv_p@56
LOCAL_FN supi_k_ntt_split
    VEC_ENTER_FAST
    mov  r8,  [rdx + 16]                // count
    test r8,  r8
    jz   .Lnttsplit_fast_done
    cmp  qword ptr [rdx + 0], -1
    je   .Lnttsplit_reduce_entry
.if SUPI_OS == 1
    sub  rsp, 168
    vmovups xmmword ptr [rbp - 72],  xmm6
    vmovups xmmword ptr [rbp - 88],  xmm7
    vmovups xmmword ptr [rbp - 104], xmm8
    vmovups xmmword ptr [rbp - 120], xmm9
    vmovups xmmword ptr [rbp - 136], xmm10
    vmovups xmmword ptr [rbp - 152], xmm11
    vmovups xmmword ptr [rbp - 168], xmm12
    vmovups xmmword ptr [rbp - 184], xmm13
    vmovups xmmword ptr [rbp - 200], xmm14
    vmovups xmmword ptr [rbp - 216], xmm15
.endif
    sub  rsp, 2560
    and  rsp, -64
    mov  qword ptr [rsp], 0
    mov  rax, [rdx + 48]
    test rax, rax
    jz   .Lnttsplit_extract_entry

    mov  [rsp + 192], rdi               // dst
    mov  [rsp + 200], rsi               // limbs
    mov  [rsp + 208], rdx               // cfg
    mov  r9,  [rdx + 0]                 // in_limbs
    mov  [rsp + 216], r9
    shl  r9,  6
    mov  [rsp + 224], r9                // total_in_bits = in_limbs * 64

    mov  r10, [rdx + 24]                // b = coeff_bits
    lea  rax, [r10 + 31]
    shr  rax, 5                         // num_chunks = (b + 31) / 32
    mov  [rsp + 232], rax
    lea  rax, [r10 + 47]
    xor  edx, edx
    mov  ecx, 48
    div  rcx
    mov  [rsp + 280], rax               // num_chunks_48 = (b + 47) / 48
    mov  rdx, [rsp + 208]

    vbroadcastsd zmm29, [rdx + 48]      // p
    vbroadcastsd zmm30, [rdx + 56]      // inv_p
    vpxorq       zmm31, zmm31, zmm31    // 0.0

    // Compute two32_mod -> zmm28, two48_mod -> zmm19, mask48 -> zmm18, use_48bit -> [rsp + 264]
    vcvttsd2usi rcx, [rdx + 48]         // p_u64
    mov  eax, 1
    shl  rax, 32
    xor  edx, edx
    div  rcx                            // rdx = 2^32 % p_u64
    vcvtusi2sd xmm0, xmm0, rdx
    vbroadcastsd zmm28, xmm0            // zmm28 = two32_mod

    mov  eax, 1
    shl  rax, 48
    xor  r8d, r8d
    cmp  rcx, rax
    seta r8b
    mov  [rsp + 264], r8                // use_48bit = (p_u64 > 2^48)
    lea  rdi, [rax - 1]
    vpbroadcastq zmm18, rdi             // zmm18 = (1 << 48) - 1
    xor  edx, edx
    div  rcx                            // rdx = 2^48 % p_u64
    vcvtusi2sd xmm0, xmm0, rdx
    vbroadcastsd zmm19, xmm0            // zmm19 = two48_mod
    vmulsd       xmm0, xmm0, xmm30      // two48_wp = two48_mod * inv_p
    vmovsd       [rsp + 288], xmm0

    // Precompute ZMM constants & reduction mode for vectorized b <= 128 fast paths:
    //   zmm18 = broadcast((1u64 << 48) - 1)
    //   zmm19 = broadcast(two48_mod)
    //   zmm21 = broadcast(hi_mask for 65 <= b <= 128)
    //   zmm22 = broadcast(1)
    //   zmm23 = broadcast(64)
    //   zmm24 = broadcast(63)
    //   zmm25 = [0, b, 2*b, 3*b, 4*b, 5*b, 6*b, 7*b]
    //   zmm26 = broadcast(0xFFFF_FFFF)
    //   zmm27 = broadcast((b >= 64) ? u64::MAX : ((1u64 << b) - 1))
    //   [rsp + 256] = mode (0: b<=52 && 2^b<=p; 1: b<=52 && 2^b<=2*p; 2: split)
    vmovdqa64    zmm25, [rip + .Lconst_idx_even]
    vpsrlq       zmm25, zmm25, 1
    vpbroadcastq zmm23, r10
    vpmullq      zmm25, zmm25, zmm23
    mov  eax, 1
    vpbroadcastq zmm22, rax
    mov  eax, 64
    vpbroadcastq zmm23, rax
    mov  eax, 63
    vpbroadcastq zmm24, rax
    mov  eax, 0xFFFFFFFF
    vpbroadcastq zmm26, rax
    mov  rax, -1
    cmp  r10, 64
    jae  .Lnttsplit_init_mask_ok
    bzhi rax, rax, r10
.Lnttsplit_init_mask_ok:
    vpbroadcastq zmm27, rax
    cmp  r10, 64
    jbe  .Lnttsplit_init_hi96_done
    cmp  r10, 128
    ja   .Lnttsplit_init_hi160
    mov  rax, -1
    cmp  r10, 128
    je   .Lnttsplit_init_hi_set
    lea  r8d, [r10d - 64]
    bzhi rax, rax, r8
    jmp  .Lnttsplit_init_hi_set
.Lnttsplit_init_hi160:
    cmp  r10, 192
    ja   .Lnttsplit_init_hi208
    mov  rax, -1
    cmp  r10, 192
    je   .Lnttsplit_init_hi_set
    lea  r8d, [r10d - 128]
    bzhi rax, rax, r8
    jmp  .Lnttsplit_init_hi_set
.Lnttsplit_init_hi208:
    cmp  r10, 240
    ja   .Lnttsplit_init_hi384
    mov  rax, -1
    lea  r8d, [r10d - 192]
    bzhi rax, rax, r8
.Lnttsplit_init_hi_set:
    vpbroadcastq zmm21, rax
    jmp  .Lnttsplit_init_hi96_done
.Lnttsplit_init_hi384:
    cmp  r10, 384
    ja   .Lnttsplit_init_hi96_done
    mov  rax, -1
    cmp  r10, 256
    jae  .Lnttsplit_init_u3_ok
    lea  r8d, [r10d - 192]
    bzhi rax, rax, r8
.Lnttsplit_init_u3_ok:
    vpbroadcastq zmm0, rax
    vmovdqa64 [rsp + 2368], zmm0
    xor  eax, eax
    cmp  r10, 256
    jbe  .Lnttsplit_init_u4_ok
    mov  rax, -1
    cmp  r10, 320
    jae  .Lnttsplit_init_u4_ok
    lea  r8d, [r10d - 256]
    bzhi rax, rax, r8
.Lnttsplit_init_u4_ok:
    vpbroadcastq zmm0, rax
    vmovdqa64 [rsp + 2432], zmm0
    xor  eax, eax
    cmp  r10, 320
    jbe  .Lnttsplit_init_u5_ok
    mov  rax, -1
    cmp  r10, 384
    jae  .Lnttsplit_init_u5_ok
    lea  r8d, [r10d - 320]
    bzhi rax, rax, r8
.Lnttsplit_init_u5_ok:
    vpbroadcastq zmm0, rax
    vmovdqa64 [rsp + 2496], zmm0
.Lnttsplit_init_hi96_done:
    mov  eax, 16
    mov  [rsp + 272], rax
    vpbroadcastq zmm20, rax

    mov  eax, 2                         // default mode = 2
    cmp  r10, 52
    ja   .Lnttsplit_init_mode_ok
    mov  edx, 1
    shlx rdx, rdx, r10                  // 2^b (exact, <= 2^52)
    cmp  rdx, rcx                       // 2^b <= p_u64 ?
    ja   .Lnttsplit_check_mode1
    xor  eax, eax                       // mode = 0 (direct vcvtuqq2pd!)
    jmp  .Lnttsplit_init_mode_ok
.Lnttsplit_check_mode1:
    mov  rdi, rcx
    shl  rdi, 1                         // 2 * p_u64 (< 2^54)
    cmp  rdx, rdi
    ja   .Lnttsplit_init_mode_ok
    mov  eax, 1                         // mode = 1 (single conditional subtract!)
.Lnttsplit_init_mode_ok:
    mov  [rsp + 256], rax

    mov  rdx, [rsp + 208]
    mov  r11, [rdx + 8]                 // start_coeff
    mov  r12, [rdx + 32]                // col_stride
    mov  r13, [rdx + 40]                // cols_per_row

    xor  r14d, r14d                     // out_pos = 0
    xor  r15d, r15d                     // cur_col = 0 (used when col_stride != 0)
    mov  rbx, r11                       // cur_row_base = start_coeff

.macro SPLIT64_VEC8 OUT_Z, TMP_Z
    mov  rax, rdx
    shr  rax, 6
    mov  ecx, edx
    and  ecx, 63
    vpbroadcastq zmm8,  rcx
    vpaddq       zmm8,  zmm8,  zmm25
    vpsrlq       zmm9,  zmm8,  6
    vpandq       zmm8,  zmm8,  zmm24
    vmovdqu64    zmm10, [rsi + 8*rax]
    vmovdqu64    zmm11, [rsi + 8*rax + 8]
    vpermq       \OUT_Z, zmm9, zmm10
    vpermq       \TMP_Z, zmm9, zmm11
    vpsrlvq      \OUT_Z, \OUT_Z, zmm8
    vpsubq       zmm12, zmm23, zmm8
    vpsllvq      \TMP_Z, \TMP_Z, zmm12
    vporq        \OUT_Z, \OUT_Z, \TMP_Z
    vpandq       \OUT_Z, \OUT_Z, zmm27
    add  rdx, r8
.endm

.macro SPLIT96_VEC8 HI_Z, LO_Z
    mov  rax, rdx
    shr  rax, 6
    mov  ecx, edx
    and  ecx, 63
    vpbroadcastq zmm8,  rcx
    vpaddq       zmm8,  zmm8,  zmm25
    vpsrlq       zmm9,  zmm8,  6
    vpandq       zmm8,  zmm8,  zmm24
    vpsubq       zmm10, zmm23, zmm8
    vmovdqu64    zmm11, [rsi + 8*rax + 0]
    vmovdqu64    zmm12, [rsi + 8*rax + 64]
    vmovdqa64    zmm13, zmm11
    vpermt2q     zmm13, zmm9,  zmm12
    vpaddq       zmm16, zmm9,  zmm22
    vmovdqa64    zmm14, zmm11
    vpermt2q     zmm14, zmm16, zmm12
    vpaddq       zmm16, zmm16, zmm22
    vmovdqa64    zmm15, zmm11
    vpermt2q     zmm15, zmm16, zmm12
    vpsrlvq      zmm13, zmm13, zmm8
    vpsllvq      zmm17, zmm14, zmm10
    vporq        zmm17, zmm13, zmm17
    vpsrlvq      zmm14, zmm14, zmm8
    vpsllvq      zmm15, zmm15, zmm10
    vporq        \HI_Z, zmm14, zmm15
    vpandq       \HI_Z, \HI_Z, zmm21
    vpandq       \LO_Z, zmm17, zmm18
    vpsrlq       zmm8,  zmm17, 48
    vpsllq       \HI_Z, \HI_Z, 16
    vporq        \HI_Z, \HI_Z, zmm8
    add  rdx, r8
.endm

.macro TRANSPOSE4_VEC8
    // Load 4 contiguous u64 words per lane across 8 strided lanes using only rax, rcx and
    // transpose in-register into zmm4=W0, zmm5=W1, zmm6=W2, zmm7=W3 (advances rdx += 8*r10).
    mov          rax, rdx
    shr          rax, 6
    vmovdqu64    ymm4, [rsi + 8*rax]
    lea          rcx, [rdx + 2*r10]
    shr          rcx, 6
    vinserti64x4 zmm4, zmm4, [rsi + 8*rcx], 1

    lea          rax, [rdx + r10]
    shr          rax, 6
    vmovdqu64    ymm5, [rsi + 8*rax]
    lea          rcx, [rdx + 2*r10]
    add          rcx, r10
    shr          rcx, 6
    vinserti64x4 zmm5, zmm5, [rsi + 8*rcx], 1

    lea          rdx, [rdx + 4*r10]
    mov          rax, rdx
    shr          rax, 6
    vmovdqu64    ymm6, [rsi + 8*rax]
    lea          rcx, [rdx + 2*r10]
    shr          rcx, 6
    vinserti64x4 zmm6, zmm6, [rsi + 8*rcx], 1

    lea          rax, [rdx + r10]
    shr          rax, 6
    vmovdqu64    ymm7, [rsi + 8*rax]
    lea          rcx, [rdx + 2*r10]
    add          rcx, r10
    shr          rcx, 6
    vinserti64x4 zmm7, zmm7, [rsi + 8*rcx], 1
    lea          rdx, [rdx + 4*r10]

    vpunpcklqdq  zmm11, zmm4, zmm5
    vpunpckhqdq  zmm12, zmm4, zmm5
    vpunpcklqdq  zmm13, zmm6, zmm7
    vpunpckhqdq  zmm14, zmm6, zmm7
    vshufi64x2   zmm4,  zmm11, zmm13, 0x88
    vshufi64x2   zmm5,  zmm12, zmm14, 0x88
    vshufi64x2   zmm6,  zmm11, zmm13, 0xDD
    vshufi64x2   zmm7,  zmm12, zmm14, 0xDD
.endm

