    vporq        zmm1, zmm1, zmm17
    vpsrlvq      zmm2, zmm12, zmm8
    vpsllvq      zmm17, zmm13, zmm9
    vporq        zmm2, zmm2, zmm17
    vpsrlvq      zmm3, zmm13, zmm8
    vpsllvq      zmm17, zmm14, zmm9
    vporq        zmm3, zmm3, zmm17
    vpsrlvq      zmm4, zmm14, zmm8
    vpsllvq      zmm17, zmm15, zmm9
    vporq        zmm4, zmm4, zmm17
    vpsrlvq      zmm5, zmm15, zmm8
    vpsllvq      zmm17, zmm16, zmm9
    vporq        zmm5, zmm5, zmm17
    vpandq       zmm3, zmm3, [rsp + 2368]
    vpandq       zmm4, zmm4, [rsp + 2432]
    vpandq       zmm5, zmm5, [rsp + 2496]
