.Lnttsplit_fast32_red_lo:
    vcmppd       k1, zmm0, zmm29, 13
    vcmppd       k2, zmm1, zmm29, 13
    vcmppd       k3, zmm2, zmm29, 13
    vcmppd       k4, zmm3, zmm29, 13
    vsubpd       zmm0 {k1}, zmm0, zmm29
    vsubpd       zmm1 {k2}, zmm1, zmm29
    vsubpd       zmm2 {k3}, zmm2, zmm29
    vsubpd       zmm3 {k4}, zmm3, zmm29

.Lnttsplit_fast32_emit:
    mov  rdi, [rsp + 192]
    lea  rdi, [rdi + 8*r14]
    vmovupd [rdi + 0],   zmm0
    vmovupd [rdi + 64],  zmm1
    vmovupd [rdi + 128], zmm2
    vmovupd [rdi + 192], zmm3
    add  r14, 32
    jmp  .Lnttsplit_batch_loop

.Lnttsplit_try8:
    mov  rcx, [rsp + 208]
    mov  rax, [rcx + 16]
    sub  rax, r14
    mov  ecx, 8
    cmp  rax, 8
    cmovb rcx, rax                      // batch_len = min(8, rem)
    mov  [rsp + 240], rcx

    // Fast contiguous 8-lane path when batch_len == 8 and (b <= 96 || (b <= 384 && use_48bit))
    cmp  rcx, 8
    jb   .Lnttsplit_slow_idx
    cmp  r10, 96
    jbe  .Lnttsplit_check_stride
    cmp  r10, 384
    ja   .Lnttsplit_slow_idx
    cmp  qword ptr [rsp + 264], 0
    je   .Lnttsplit_slow_idx
.Lnttsplit_check_stride:
    test r12, r12
    jnz  .Lnttsplit_check_fast_strided
    lea  rax, [r11 + r14]
    mov  rdx, rax
    imul rdx, r10                       // cur_bit = start_idx * b
    cmp  r10, 96
    jbe  .Lnttsplit_fast_go
    cmp  rdx, [rsp + 224]
    jae  .Lnttsplit_fast_go
    mov  r8d, 18
    cmp  r10, 128
    jbe  .Lnttsplit_check_margin8_ns
    mov  r8d, 24
    cmp  r10, 160
    jbe  .Lnttsplit_check_margin8_ns
    mov  r8d, 36
    cmp  r10, 240
    jbe  .Lnttsplit_check_margin8_ns
    mov  r8d, 51
.Lnttsplit_check_margin8_ns:
    mov  rdi, rdx
    shr  rdi, 6
    add  rdi, r8
    cmp  rdi, [rsp + 216]
    ja   .Lnttsplit_slow_idx
    jmp  .Lnttsplit_fast_go

.Lnttsplit_check_fast_strided:
    lea  rax, [r15 + 8]
    cmp  rax, r13
    ja   .Lnttsplit_slow_idx
    lea  rax, [rbx + r15]
    mov  rdx, rax
    imul rdx, r10                       // cur_bit = start_idx * b
    cmp  r10, 96
    jbe  .Lnttsplit_strided_advance
    cmp  rdx, [rsp + 224]
    jae  .Lnttsplit_strided_advance
    mov  r8d, 18
    cmp  r10, 128
    jbe  .Lnttsplit_check_margin8_st
    mov  r8d, 24
    cmp  r10, 160
    jbe  .Lnttsplit_check_margin8_st
    mov  r8d, 36
    cmp  r10, 240
    jbe  .Lnttsplit_check_margin8_st
    mov  r8d, 51
.Lnttsplit_check_margin8_st:
    mov  rdi, rdx
    shr  rdi, 6
    add  rdi, r8
    cmp  rdi, [rsp + 216]
    ja   .Lnttsplit_slow_idx
.Lnttsplit_strided_advance:
    add  r15, 8
    cmp  r15, r13
    jb   .Lnttsplit_fast_go
    xor  r15d, r15d
    add  rbx, r12

.Lnttsplit_fast_go:
    // Fast zero path when cur_bit >= total_in_bits!
    cmp  rdx, [rsp + 224]
    jb   .Lnttsplit_fast_nonzero
    test r12, r12
    jz   .Lnttsplit_bulk_zero
    cmp  r12, r13
    jb   .Lnttsplit_fast_emit_zero8
.Lnttsplit_bulk_zero:
    // Monotonic indices (col_stride == 0 or col_stride >= cols_per_row): bulk-zero all remaining [r14 .. count) and exit!
    mov  rdi, [rsp + 192]
    mov  rcx, [rsp + 208]
    mov  rax, [rcx + 16]
    lea  rdi, [rdi + 8*r14]
    sub  rax, r14
.p2align 4
.Lnttsplit_zero_rem8:
    vmovupd [rdi], zmm31
    lea  rdi, [rdi + 64]
    sub  rax, 8
    cmp  rax, 8
    jae  .Lnttsplit_zero_rem8
    test rax, rax
    jz   .Lnttsplit_done
.Lnttsplit_zero_rem1:
    vmovsd [rdi], xmm31
    lea  rdi, [rdi + 8]
    dec  rax
    jnz  .Lnttsplit_zero_rem1
    jmp  .Lnttsplit_done

.Lnttsplit_fast_emit_zero8:
    mov  rdi, [rsp + 192]
    vmovupd [rdi + 8*r14], zmm31
    add  r14, 8
    jmp  .Lnttsplit_batch_loop

.Lnttsplit_fast_nonzero:
    mov  rsi, [rsp + 200]               // limbs
    mov  r9,  [rsp + 216]               // in_limbs
    cmp  r10d, 64
    ja   .Lnttsplit_fast96_start

    // Contiguous 2-vector load + vpermq for 1 <= b <= 64 (zero vpgatherqq!)
    mov  rax, rdx
    shr  rax, 6                         // base_limb = cur_bit >> 6
    lea  rcx, [rax + 9]
    cmp  rcx, r9                        // base_limb + 9 <= in_limbs ?
    ja   .Lnttsplit_fast64_scalar

    mov  ecx, edx
    and  ecx, 63
    vpbroadcastq zmm2, rcx
    vpaddq     zmm2, zmm2, zmm25        // rel_bit[0..7] = (cur_bit & 63) + i * b
    vpsrlq     zmm3, zmm2, 6            // rel_limb[0..7] in 0..7
    vpandq     zmm2, zmm2, zmm24        // bit_off[0..7] (& 63)
    vmovdqu64  zmm10, [rsi + 8*rax]
    vmovdqu64  zmm11, [rsi + 8*rax + 8]
    vpermq     zmm0, zmm3, zmm10
    vpermq     zmm1, zmm3, zmm11
    vpsrlvq    zmm0, zmm0, zmm2
    vpsubq     zmm4, zmm23, zmm2        // 64 - bit_off (64 -> vpsllvq yields 0)
    vpsllvq    zmm1, zmm1, zmm4
    vporq      zmm0, zmm0, zmm1
    vpandq     zmm0, zmm0, zmm27

.Lnttsplit_vec_reduce:
    mov  rax, [rsp + 256]
    test rax, rax
    jnz  .Lnttsplit_vec_mode12
    vcvtuqq2pd zmm0, zmm0
    jmp  .Lnttsplit_fast_emit
.Lnttsplit_vec_mode12:
    cmp  eax, 1
    jne  .Lnttsplit_vec_mode2
    vcvtuqq2pd zmm0, zmm0
    vcmppd     k1, zmm0, zmm29, 13
    vsubpd     zmm0 {k1}, zmm0, zmm29
    jmp  .Lnttsplit_fast_emit
.Lnttsplit_vec_mode2:
    cmp        qword ptr [rsp + 264], 0
    je         .Lnttsplit_vec_mode2_32
    vpandq     zmm1, zmm0, zmm18
    vpsrlq     zmm0, zmm0, 48
    vcvtuqq2pd zmm1, zmm1
    vcvtuqq2pd zmm0, zmm0
    ZMM_MUL_MOD zmm0, zmm19, zmm16, zmm20, k1
    ZMM_ADD_MOD zmm0, zmm0, zmm1, k1
    jmp        .Lnttsplit_fast_emit
.Lnttsplit_vec_mode2_32:
    vpandq     zmm1, zmm0, zmm26
    vpsrlq     zmm0, zmm0, 32
    vcvtuqq2pd zmm1, zmm1
    vcmppd     k1, zmm1, zmm29, 13
    vsubpd     zmm1 {k1}, zmm1, zmm29
    vcvtuqq2pd zmm0, zmm0
    vcmppd     k1, zmm0, zmm29, 13
    vsubpd     zmm0 {k1}, zmm0, zmm29
    ZMM_MUL_MOD zmm0, zmm28, zmm16, zmm20, k1
    ZMM_ADD_MOD zmm0, zmm0, zmm1, k1
    jmp  .Lnttsplit_fast_emit

.Lnttsplit_fast64_scalar:
    xor  edi, edi                       // lane = 0
.p2align 4
.Lnttsplit_fast64_loop:
    xor  eax, eax
    xor  ecx, ecx
    cmp  rdx, [rsp + 224]
    jae  .Lnttsplit_f64_store
    mov  r8,  rdx
    shr  r8,  6
    mov  ecx, edx
    and  ecx, 63
    shrx rax, [rsi + 8*r8], rcx
    add  ecx, r10d
    cmp  ecx, 64
    jbe  .Lnttsplit_f64_mask
    inc  r8
    cmp  r8,  r9
    jae  .Lnttsplit_f64_mask
    mov  ecx, edx
    and  ecx, 63
    neg  ecx
    add  ecx, 64
    shlx r8,  [rsi + 8*r8], rcx
    or   rax, r8
.Lnttsplit_f64_mask:
    cmp  r10d, 64
    jae  .Lnttsplit_f64_split
    bzhi rax, rax, r10
.Lnttsplit_f64_split:
    mov  ecx, eax
    shr  rax, 32
.Lnttsplit_f64_store:
    mov  [rsp + 0 + 8*rdi],  rcx
    mov  [rsp + 64 + 8*rdi], rax
    add  rdx, r10
    inc  edi
    cmp  edi, 8
    jb   .Lnttsplit_fast64_loop

    vcvtuqq2pd zmm1, [rsp + 0]
    vcmppd     k1, zmm1, zmm29, 13
    vsubpd     zmm1 {k1}, zmm1, zmm29
    cmp  r10d, 32
    jbe  .Lnttsplit_f64_1chunk
    vcvtuqq2pd zmm0, [rsp + 64]
    vcmppd     k1, zmm0, zmm29, 13
    vsubpd     zmm0 {k1}, zmm0, zmm29
    ZMM_MUL_MOD zmm0, zmm28, zmm16, zmm20, k1
    ZMM_ADD_MOD zmm0, zmm0, zmm1, k1
    jmp  .Lnttsplit_fast_emit
.Lnttsplit_f64_1chunk:
    vmovapd zmm0, zmm1
    jmp  .Lnttsplit_fast_emit

.Lnttsplit_fast96_start:
    // Contiguous vector loads + vpermt2q for 65 <= b <= 128 (zero vpgatherqq!)
    mov  rax, rdx
    shr  rax, 6                         // base_limb = cur_bit >> 6
    cmp  r10d, 96
    ja   .Lnttsplit_fast128_vec
    lea  rcx, [rax + 16]
    cmp  rcx, r9                        // base_limb + 16 <= in_limbs ?
    ja   .Lnttsplit_fast96_scalar

    mov  ecx, edx
    and  ecx, 63
    vpbroadcastq zmm2, rcx
    vpaddq       zmm2, zmm2, zmm25      // rel_bit[0..7] in 0..735
    vpsrlq       zmm3, zmm2, 6          // rel_limb[0..7] in 0..11
    vpandq       zmm2, zmm2, zmm24      // bit_off[0..7] (& 63)
    vpsubq       zmm4, zmm23, zmm2      // 64 - bit_off (64 -> vpsllvq yields 0)

    vmovdqu64    zmm10, [rsi + 8*rax + 0]
    vmovdqu64    zmm11, [rsi + 8*rax + 64]

    vmovdqa64    zmm0, zmm10
    vpermt2q     zmm0, zmm3, zmm11      // limbs[base + rel_limb]
    vpaddq       zmm6, zmm3, zmm22
    vmovdqa64    zmm1, zmm10
    vpermt2q     zmm1, zmm6, zmm11      // limbs[base + rel_limb + 1]
    vpaddq       zmm6, zmm6, zmm22
    vmovdqa64    zmm5, zmm10
    vpermt2q     zmm5, zmm6, zmm11      // limbs[base + rel_limb + 2]

    vpsrlvq      zmm0, zmm0, zmm2
    vpsllvq      zmm17, zmm1, zmm4
    vporq        zmm17, zmm0, zmm17     // lo64

    vpsrlvq      zmm1, zmm1, zmm2
    vpsllvq      zmm5, zmm5, zmm4
    vporq        zmm0, zmm1, zmm5       // raw hi64
    vpandq       zmm0, zmm0, zmm21      // hi (bits 64 .. b-1)

    cmp          qword ptr [rsp + 264], 0
    je           .Lnttsplit_fast96_32bit

    vpandq       zmm1, zmm17, zmm18     // lo48 (< 2^48 < p)
    vpsrlq       zmm2, zmm17, 48
    vpsllq       zmm0, zmm0, 16
    vporq        zmm0, zmm0, zmm2       // hi48 (< 2^48 < p)
    vcvtuqq2pd   zmm0, zmm0
    vcvtuqq2pd   zmm1, zmm1
    ZMM_MUL_MOD  zmm0, zmm19, zmm16, zmm20, k1
    ZMM_ADD_MOD  zmm0, zmm0, zmm1, k1
    jmp          .Lnttsplit_fast_emit

.Lnttsplit_fast96_32bit:
    vpsrlq       zmm1, zmm17, 32        // chunk1 (bits 32 .. 63)
    vpandq       zmm2, zmm17, zmm26     // chunk0 (bits 0 .. 31)

    vcvtuqq2pd   zmm0, zmm0
    vcmppd       k1, zmm0, zmm29, 13
    vsubpd       zmm0 {k1}, zmm0, zmm29
    vcvtuqq2pd   zmm1, zmm1
    vcmppd       k1, zmm1, zmm29, 13
    vsubpd       zmm1 {k1}, zmm1, zmm29
    ZMM_MUL_MOD  zmm0, zmm28, zmm16, zmm20, k1
    ZMM_ADD_MOD  zmm0, zmm0, zmm1, k1
    vcvtuqq2pd   zmm1, zmm2
    vcmppd       k1, zmm1, zmm29, 13
    vsubpd       zmm1 {k1}, zmm1, zmm29
    ZMM_MUL_MOD  zmm0, zmm28, zmm16, zmm20, k1
    ZMM_ADD_MOD  zmm0, zmm0, zmm1, k1
    jmp          .Lnttsplit_fast_emit

.Lnttsplit_fast128_vec:
    cmp  r10d, 128
    ja   .Lnttsplit_fast160_vec
    // 97 <= b <= 128 with p > 2^48 and base_limb + 18 <= in_limbs:
    mov  ecx, edx
    and  ecx, 63
    vpbroadcastq zmm2, rcx
    vpaddq       zmm2, zmm2, zmm25      // rel_bit[0..7] in 0..959
    vpsrlq       zmm3, zmm2, 6          // rel_limb[0..7] in 0..14
    vpandq       zmm2, zmm2, zmm24      // bit_off[0..7] (& 63)
    vpsubq       zmm4, zmm23, zmm2      // 64 - bit_off (64 -> vpsllvq yields 0)

    vmovdqu64    zmm10, [rsi + 8*rax + 0]
    vmovdqu64    zmm11, [rsi + 8*rax + 64]
    vmovdqu64    zmm12, [rsi + 8*rax + 16]
    vmovdqu64    zmm13, [rsi + 8*rax + 80]

    vmovdqa64    zmm0, zmm10
    vpermt2q     zmm0, zmm3, zmm11      // limbs[base + rel_limb]
    vpaddq       zmm6, zmm3, zmm22
    vmovdqa64    zmm1, zmm10
    vpermt2q     zmm1, zmm6, zmm11      // limbs[base + rel_limb + 1]
    vmovdqa64    zmm5, zmm12
    vpermt2q     zmm5, zmm3, zmm13      // limbs[base + 2 + rel_limb]

    vpsrlvq      zmm0, zmm0, zmm2
    vpsllvq      zmm17, zmm1, zmm4
    vporq        zmm17, zmm0, zmm17     // lo64

    vpsrlvq      zmm1, zmm1, zmm2
    vpsllvq      zmm5, zmm5, zmm4
    vporq        zmm0, zmm1, zmm5       // raw hi64
    vpandq       zmm0, zmm0, zmm21      // hi (bits 64 .. b-1)

    vpandq       zmm2, zmm17, zmm18     // chunk0: bits 0..47 (< 2^48 < p)
    vpsrlq       zmm1, zmm17, 48
    vpsllq       zmm5, zmm0, 16
    vporq        zmm1, zmm1, zmm5
    vpandq       zmm1, zmm1, zmm18      // chunk1: bits 48..95 (< 2^48 < p)
    vpsrlq       zmm0, zmm0, 32         // chunk2: bits 96..b-1 (< 2^32 < p)

    vcvtuqq2pd   zmm0, zmm0
    vcvtuqq2pd   zmm1, zmm1
    ZMM_MUL_MOD  zmm0, zmm19, zmm16, zmm20, k1
    ZMM_ADD_MOD  zmm0, zmm0, zmm1, k1
    vcvtuqq2pd   zmm1, zmm2
    ZMM_MUL_MOD  zmm0, zmm19, zmm16, zmm20, k1
    ZMM_ADD_MOD  zmm0, zmm0, zmm1, k1
    jmp          .Lnttsplit_fast_emit

.Lnttsplit_fast160_vec:
    vpbroadcastq zmm20, [rsp + 272]
    xor  r8d, r8d
    cmp  r10d, 160
    ja   .Lnttsplit_fast192_vec
    SPLIT160_VEC8 zmm0, 64, 0
    cmp  r10d, 144
    ja   .Lnttsplit_fast160_4ch
    vcvtuqq2pd   zmm0, zmm0
    jmp  .Lnttsplit_fast160_c1c0
.Lnttsplit_fast160_4ch:
    vpandq       zmm1, zmm0, zmm18
    vpsrlq       zmm0, zmm0, 48
    vcvtuqq2pd   zmm0, zmm0
    vcvtuqq2pd   zmm1, zmm1
    ZMM_MUL_MOD  zmm0, zmm19, zmm16, zmm20, k1
    ZMM_ADD_MOD  zmm0, zmm0, zmm1, k1
.Lnttsplit_fast160_c1c0:
    vmovapd      zmm1, [rsp + 64]
    ZMM_MUL_MOD  zmm0, zmm19, zmm16, zmm20, k1
    ZMM_ADD_MOD  zmm0, zmm0, zmm1, k1
    vmovapd      zmm1, [rsp + 0]
    ZMM_MUL_MOD  zmm0, zmm19, zmm16, zmm20, k1
    ZMM_ADD_MOD  zmm0, zmm0, zmm1, k1
    jmp          .Lnttsplit_fast_emit

.Lnttsplit_fast192_vec:
    cmp  r10d, 192
    ja   .Lnttsplit_fast208_vec
    SPLIT192_VEC8 zmm0, 832, 64, 0
    jmp  .Lnttsplit_fast192_c2c1c0
.Lnttsplit_fast208_vec:
    cmp  r10d, 240
    ja   .Lnttsplit_fast384_vec
    SPLIT208_VEC8 zmm0, 1088, 832, 64, 0
    vmovapd      zmm1, [rsp + 1088]
    ZMM_MUL_MOD  zmm0, zmm19, zmm16, zmm20, k1
    ZMM_ADD_MOD  zmm0, zmm0, zmm1, k1
.Lnttsplit_fast192_c2c1c0:
    vmovapd      zmm1, [rsp + 832]
    ZMM_MUL_MOD  zmm0, zmm19, zmm16, zmm20, k1
    ZMM_ADD_MOD  zmm0, zmm0, zmm1, k1
    jmp  .Lnttsplit_fast160_c1c0

.Lnttsplit_fast384_vec:
    SPLIT384_VEC8 320, 64
    mov  rcx, [rsp + 280]
    dec  rcx
    mov  rax, rcx
    shl  rax, 6
    vcvtuqq2pd   zmm0, [rsp + rax + 320]
.Lnttsplit_fast384_vec_loop:
    sub  rax, 64
    vcvtuqq2pd   zmm1, [rsp + rax + 320]
    ZMM_MUL_MOD  zmm0, zmm19, zmm16, zmm20, k1
    ZMM_ADD_MOD  zmm0, zmm0, zmm1, k1
    dec  rcx
    jnz  .Lnttsplit_fast384_vec_loop
    jmp  .Lnttsplit_fast_emit

.Lnttsplit_fast96_scalar:
    xor  edi, edi
.p2align 4
.Lnttsplit_fast96_loop:
    xor  eax, eax
    xor  ecx, ecx
    xor  r13d, r13d
    cmp  rdx, [rsp + 224]
    jae  .Lnttsplit_f96_store
    mov  r8,  rdx
    shr  r8,  6
    mov  rax, [rsi + 8*r8]
    xor  r11d, r11d
    inc  r8
    cmp  r8,  r9
    jae  .Lnttsplit_f96_shift
    mov  r11, [rsi + 8*r8]
    inc  r8
    cmp  r8,  r9
    jae  .Lnttsplit_f96_shift
    mov  r13, [rsi + 8*r8]
.Lnttsplit_f96_shift:
    mov  ecx, edx
    and  ecx, 63
    shrd rax, r11, cl
    shrd r11, r13, cl
    lea  r8d, [r10d - 64]
    bzhi r13, r11, r8
    mov  ecx, eax
    shr  rax, 32
.Lnttsplit_f96_store:
    mov  [rsp + 0 + 8*rdi],   rcx
    mov  [rsp + 64 + 8*rdi],  rax
    mov  [rsp + 128 + 8*rdi], r13
    add  rdx, r10
    inc  edi
    cmp  edi, 8
    jb   .Lnttsplit_fast96_loop

    mov  rdx, [rsp + 208]
    mov  r11, [rdx + 8]
    mov  r13, [rdx + 40]

    vcvtuqq2pd zmm0, [rsp + 128]
    vcmppd     k1, zmm0, zmm29, 13
    vsubpd     zmm0 {k1}, zmm0, zmm29
    vcvtuqq2pd zmm1, [rsp + 64]
    vcmppd     k1, zmm1, zmm29, 13
    vsubpd     zmm1 {k1}, zmm1, zmm29
    ZMM_MUL_MOD zmm0, zmm28, zmm16, zmm20, k1
    ZMM_ADD_MOD zmm0, zmm0, zmm1, k1
    vcvtuqq2pd zmm1, [rsp + 0]
    vcmppd     k1, zmm1, zmm29, 13
    vsubpd     zmm1 {k1}, zmm1, zmm29
    ZMM_MUL_MOD zmm0, zmm28, zmm16, zmm20, k1
    ZMM_ADD_MOD zmm0, zmm0, zmm1, k1

.Lnttsplit_fast_emit:
    mov  rdi, [rsp + 192]
    vmovupd [rdi + 8*r14], zmm0
    add  r14, 8
    jmp  .Lnttsplit_batch_loop

.Lnttsplit_slow_idx:
    // Record the 8 (or batch_len) coefficient indices in [rsp + 128 .. 192]
    xor  edi, edi
.Lnttsplit_idx_loop:
    test r12, r12                       // col_stride == 0 ?
    jnz  .Lnttsplit_strided_idx
    lea  rax, [r11 + r14]
    add  rax, rdi
    mov  [rsp + 128 + 8*rdi], rax
    jmp  .Lnttsplit_idx_next
.Lnttsplit_strided_idx:
    lea  rax, [rbx + r15]
    mov  [rsp + 128 + 8*rdi], rax
    inc  r15
    cmp  r15, r13
    jb   .Lnttsplit_idx_next
    xor  r15d, r15d
    add  rbx, r12
.Lnttsplit_idx_next:
    inc  rdi
    cmp  rdi, rcx
    jb   .Lnttsplit_idx_loop

    // Zero unused lanes so ZMM arithmetic stays clean
    cmp  rcx, 8
    jae  .Lnttsplit_chunks_start
    mov  rdi, rcx
    xor  eax, eax
.Lnttsplit_zero_lanes:
    mov  [rsp + 0 + 8*rdi], rax
    inc  rdi
    cmp  rdi, 8
    jb   .Lnttsplit_zero_lanes

.Lnttsplit_chunks_start:
    vpxorq zmm0, zmm0, zmm0             // acc = 0.0 across 8 lanes
    mov  r8,  [rsp + 232]               // chunk = num_chunks
.Lnttsplit_chunk_loop:
    dec  r8                             // chunk = num_chunks - 1 .. 0
    mov  rax, r8
    shl  rax, 5                         // chunk_bit_off = chunk * 32
    mov  rcx, r10                       // b
    sub  rcx, rax                       // width_rem = b - chunk * 32
    mov  edx, 32
    cmp  rcx, 32
    cmova rcx, rdx                      // c_w = min(32, b - chunk * 32)

    // Extract c_w bits for each lane in batch_len into [rsp + 0 .. 64]
    mov  rsi, [rsp + 200]               // limbs
    mov  r9,  [rsp + 216]               // in_limbs
    xor  edi, edi
.Lnttsplit_extract_lane:
    mov  rdx, [rsp + 128 + 8*rdi]       // coeff idx
    imul rdx, r10                       // idx * b
    add  rdx, rax                       // c_bit = idx * b + chunk * 32
    xor  r11d, r11d                     // part = 0
    cmp  rdx, [rsp + 224]               // c_bit < total_in_bits ?
    jae  .Lnttsplit_store_lane
    mov  r11, rdx
    shr  r11, 6                         // limb_idx
    cmp  r11, r9
    jae  .Lnttsplit_zero_part
    mov  [rsp + 248], rax
    mov  eax, edx
    and  eax, 63                        // bit_off
    shrx r13, [rsi + 8*r11], rax
    add  eax, ecx                       // bit_off + c_w
    cmp  eax, 64
    jbe  .Lnttsplit_mask_part
    lea  rax, [r11 + 1]
    cmp  rax, r9
    jae  .Lnttsplit_mask_part
    mov  eax, edx
    and  eax, 63
    neg  eax
    add  eax, 64                        // 64 - bit_off
    shlx r11, [rsi + 8*r11 + 8], rax
    or   r13, r11
.Lnttsplit_mask_part:
    bzhi r11, r13, rcx
    mov  rax, [rsp + 248]
    jmp  .Lnttsplit_store_lane
.Lnttsplit_zero_part:
    xor  r11d, r11d
.Lnttsplit_store_lane:
    mov  [rsp + 0 + 8*rdi], r11
    inc  rdi
    cmp  rdi, [rsp + 240]
    jb   .Lnttsplit_extract_lane

    // Restore r11 = start_coeff, r13 = cols_per_row
    mov  rdx, [rsp + 208]
    mov  r11, [rdx + 8]
    mov  r13, [rdx + 40]

    // Convert 8 u64 chunks -> f64 and reduce mod p
    vcvtuqq2pd zmm1, [rsp + 0]
    vcmppd     k1, zmm1, zmm29, 13
    vsubpd     zmm1 {k1}, zmm1, zmm29   // part_red

    // If chunk + 1 < num_chunks: acc = fma_mul_mod(acc, two32_mod, p, inv_p)
    lea  rdx, [r8 + 1]
    cmp  rdx, [rsp + 232]
    jae  .Lnttsplit_add_part
    ZMM_MUL_MOD zmm0, zmm28, zmm16, zmm20, k1
.Lnttsplit_add_part:
    ZMM_ADD_MOD zmm0, zmm0, zmm1, k1

    test r8,  r8
    jnz  .Lnttsplit_chunk_loop

    // Store batch_len f64 residues to dst + 8 * out_pos
    mov  rcx, [rsp + 240]
    mov  rdi, [rsp + 192]
    lea  rdi, [rdi + 8*r14]
    mov  eax, 0xFF
    bzhi eax, eax, ecx
    kmovw k1, eax
    vmovupd [rdi] {k1}, zmm0

    add  r14, rcx
    jmp  .Lnttsplit_batch_loop

    // ========================================================================
    // Planar 48-bit chunk extraction mode (cfg.p == 0.0)
    // ========================================================================
.Lnttsplit_extract_entry:
    mov  [rsp + 192], rdi               // dst
    mov  [rsp + 200], rsi               // limbs
    mov  [rsp + 208], rdx               // cfg
    mov  r9,  [rdx + 0]                 // in_limbs
    mov  [rsp + 216], r9
    shl  r9,  6
    mov  [rsp + 224], r9                // total_in_bits = in_limbs * 64
    mov  r10, [rdx + 24]                // b = coeff_bits
    mov  rax, r8
    cmp  r8,  32
    jb   .Lnttsplit_ext_stride_ok
    add  rax, 7
    and  rax, -8
    add  rax, 8
.Lnttsplit_ext_stride_ok:
    shl  rax, 3
    mov  [rsp + 248], rax               // plane_stride_bytes

    lea  rax, [r10 + 47]
    xor  edx, edx
    mov  ecx, 48
    div  rcx
    mov  [rsp + 232], rax               // num_chunks_48 = (b + 47) / 48

    vpxorq zmm31, zmm31, zmm31
    mov  eax, 1
    shl  rax, 48
    dec  rax
    vpbroadcastq zmm18, rax             // (1 << 48) - 1
    vmovdqa64    zmm25, [rip + .Lconst_idx_even]
    vpsrlq       zmm25, zmm25, 1
    vpbroadcastq zmm23, r10
    vpmullq      zmm25, zmm25, zmm23
    mov  eax, 1
    vpbroadcastq zmm22, rax
    mov  eax, 64
    vpbroadcastq zmm23, rax
    mov  eax, 63
    vpbroadcastq zmm24, rax
    mov  rax, -1
    cmp  r10, 64
    jae  .Lnttsplit_ext_mask_ok
    bzhi rax, rax, r10
.Lnttsplit_ext_mask_ok:
    vpbroadcastq zmm27, rax
    cmp  r10, 64
    jbe  .Lnttsplit_ext_hi_done
    cmp  r10, 128
    ja   .Lnttsplit_ext_hi160
    mov  rax, -1
    cmp  r10, 128
    je   .Lnttsplit_ext_hi_set
    lea  r8d, [r10d - 64]
    bzhi rax, rax, r8
    jmp  .Lnttsplit_ext_hi_set
.Lnttsplit_ext_hi160:
    cmp  r10, 192
    ja   .Lnttsplit_ext_hi208
    mov  rax, -1
    cmp  r10, 192
    je   .Lnttsplit_ext_hi_set
    lea  r8d, [r10d - 128]
    bzhi rax, rax, r8
    jmp  .Lnttsplit_ext_hi_set
.Lnttsplit_ext_hi208:
    cmp  r10, 240
    ja   .Lnttsplit_ext_hi384
    mov  rax, -1
    lea  r8d, [r10d - 192]
    bzhi rax, rax, r8
.Lnttsplit_ext_hi_set:
    vpbroadcastq zmm21, rax
    jmp  .Lnttsplit_ext_hi_done
.Lnttsplit_ext_hi384:
    cmp  r10, 384
    ja   .Lnttsplit_ext_hi_done
    mov  rax, -1
    cmp  r10, 256
    jae  .Lnttsplit_ext_u3_ok
    lea  r8d, [r10d - 192]
    bzhi rax, rax, r8
.Lnttsplit_ext_u3_ok:
    vpbroadcastq zmm0, rax
    vmovdqa64 [rsp + 2368], zmm0
    xor  eax, eax
    cmp  r10, 256
    jbe  .Lnttsplit_ext_u4_ok
    mov  rax, -1
    cmp  r10, 320
    jae  .Lnttsplit_ext_u4_ok
    lea  r8d, [r10d - 256]
    bzhi rax, rax, r8
.Lnttsplit_ext_u4_ok:
    vpbroadcastq zmm0, rax
    vmovdqa64 [rsp + 2432], zmm0
    xor  eax, eax
    cmp  r10, 320
    jbe  .Lnttsplit_ext_u5_ok
    mov  rax, -1
    cmp  r10, 384
    jae  .Lnttsplit_ext_u5_ok
    lea  r8d, [r10d - 320]
    bzhi rax, rax, r8
.Lnttsplit_ext_u5_ok:
    vpbroadcastq zmm0, rax
    vmovdqa64 [rsp + 2496], zmm0
.Lnttsplit_ext_hi_done:
    mov  eax, 16
    mov  [rsp + 272], rax
    vpbroadcastq zmm20, [rsp + 272]

    mov  ecx, 33
    cmp  r10, 64
    jbe  .Lnttsplit_ext_init_margin_ok
    mov  ecx, 52
    cmp  r10, 96
    jbe  .Lnttsplit_ext_init_margin_ok
    mov  ecx, 68
    cmp  r10, 128
    jbe  .Lnttsplit_ext_init_margin_ok
    mov  ecx, 86
    cmp  r10, 160
    jbe  .Lnttsplit_ext_init_margin_ok
    mov  ecx, 116
    cmp  r10, 208
    jbe  .Lnttsplit_ext_init_margin_ok
    mov  ecx, 128
    cmp  r10, 240
    jbe  .Lnttsplit_ext_init_margin_ok
    mov  ecx, 195
.Lnttsplit_ext_init_margin_ok:
    mov  [rsp + 256], rcx               // precomputed 32-lane limb margin

    mov  rdx, [rsp + 208]
    mov  rax, [rdx + 16]
    mov  [rsp + 264], rax               // count
    mov  r11, [rdx + 8]                 // start_coeff
    mov  r12, [rdx + 32]                // col_stride
    mov  r13, [rdx + 40]                // cols_per_row
    xor  r14d, r14d                     // out_pos = 0
    xor  r15d, r15d                     // cur_col = 0
    mov  rbx, r11                       // cur_row_base = start_coeff

.p2align 6
.Lnttsplit_ext_loop:
    mov  rax, [rsp + 264]               // count
    sub  rax, r14                       // rem
    jz   .Lnttsplit_done

    // Fast bulk-zero / 32-lane zero path when cur_bit >= total_in_bits!
    test r12, r12
    jnz  .Lnttsplit_ext_cur_st
    lea  rdx, [r11 + r14]
    jmp  .Lnttsplit_ext_cur_chk
.Lnttsplit_ext_cur_st:
    lea  rdx, [rbx + r15]
.Lnttsplit_ext_cur_chk:
    imul rdx, r10
    cmp  rdx, [rsp + 224]
    jb   .Lnttsplit_ext_nonzero
    test r12, r12
    jz   .Lnttsplit_ext_bulk_zero
    cmp  r12, r13
    jae  .Lnttsplit_ext_bulk_zero
    cmp  rax, 32
    jb   .Lnttsplit_ext_scalar
    lea  rdi, [r15 + 32]
    cmp  rdi, r13
    ja   .Lnttsplit_ext_scalar
    add  r15, 32
    cmp  r15, r13
    jb   .Lnttsplit_ext_zero32
    xor  r15d, r15d
    add  rbx, r12
.Lnttsplit_ext_zero32:
    mov  rdi, [rsp + 192]
    lea  rdi, [rdi + 8*r14]
    mov  r9,  [rsp + 248]
    mov  rcx, [rsp + 232]
.Lnttsplit_ext_z32_plane:
    vmovupd [rdi + 0],   zmm31
    vmovupd [rdi + 64],  zmm31
    vmovupd [rdi + 128], zmm31
    vmovupd [rdi + 192], zmm31
    add  rdi, r9
    dec  rcx
    jnz  .Lnttsplit_ext_z32_plane
    add  r14, 32
    jmp  .Lnttsplit_ext_loop

.Lnttsplit_ext_bulk_zero:
    mov  rsi, [rsp + 192]
    lea  rsi, [rsi + 8*r14]
    mov  r9,  [rsp + 248]
    mov  r8,  [rsp + 232]
.Lnttsplit_ext_bz_plane:
    mov  rdi, rsi
    mov  rcx, rax
    cmp  rcx, 8
    jb   .Lnttsplit_ext_bz_tail
.p2align 4
.Lnttsplit_ext_bz8:
    vmovupd [rdi], zmm31
    lea  rdi, [rdi + 64]
    sub  rcx, 8
    cmp  rcx, 8
    jae  .Lnttsplit_ext_bz8
.Lnttsplit_ext_bz_tail:
    test rcx, rcx
    jz   .Lnttsplit_ext_bz_next
.Lnttsplit_ext_bz1:
    vmovsd [rdi], xmm31
    lea  rdi, [rdi + 8]
    dec  rcx
    jnz  .Lnttsplit_ext_bz1
.Lnttsplit_ext_bz_next:
    add  rsi, r9
    dec  r8
    jnz  .Lnttsplit_ext_bz_plane
    jmp  .Lnttsplit_done

.Lnttsplit_ext_nonzero:
    cmp  rax, 32
    jb   .Lnttsplit_ext_scalar
    cmp  r10, 384
    ja   .Lnttsplit_ext_scalar
    mov  rcx, [rsp + 256]               // limb_margin
    test r12, r12
    jnz  .Lnttsplit_ext_try_strided
    mov  rdi, rdx
    shr  rdi, 6
    add  rdi, rcx
    cmp  rdi, [rsp + 216]
    ja   .Lnttsplit_ext_scalar
    jmp  .Lnttsplit_ext32_go

.Lnttsplit_ext_try_strided:
    lea  rdi, [r15 + 32]
    cmp  rdi, r13
    ja   .Lnttsplit_ext_scalar
    mov  rdi, rdx
    shr  rdi, 6
    add  rdi, rcx
    cmp  rdi, [rsp + 216]
    ja   .Lnttsplit_ext_scalar
    add  r15, 32
    cmp  r15, r13
    jb   .Lnttsplit_ext32_go
    xor  r15d, r15d
    add  rbx, r12
    mov  rsi, [rsp + 200]
    lea  rdi, [rbx + 4*r12]
    imul rdi, r10
    cmp  rdi, [rsp + 224]
    jae  .Lnttsplit_ext32_pf_done
    shr  rdi, 6
    lea  rdi, [rsi + 8*rdi]
    prefetcht0 [rdi + 0]
    prefetcht0 [rdi + 64]
    prefetcht0 [rdi + 128]
    prefetcht0 [rdi + 192]
    prefetcht0 [rdi + 256]
    prefetcht0 [rdi + 320]
    prefetcht0 [rdi + 384]
    cmp  r10d, 96
    jbe  .Lnttsplit_ext32_pf_done
    prefetcht0 [rdi + 448]
    prefetcht0 [rdi + 512]
    prefetcht0 [rdi + 576]
    cmp  r10d, 160
    jbe  .Lnttsplit_ext32_pf_done
    prefetcht0 [rdi + 640]
    prefetcht0 [rdi + 704]
    prefetcht0 [rdi + 768]
    jmp  .Lnttsplit_ext32_pf_done

.Lnttsplit_ext32_go:
    mov  rsi, [rsp + 200]
.Lnttsplit_ext32_pf_done:
    lea  r8,  [8*r10]
    cmp  r10d, 64
    ja   .Lnttsplit_ext32_b96

    SPLIT64_VEC8 zmm0, zmm13
    SPLIT64_VEC8 zmm1, zmm13
    SPLIT64_VEC8 zmm2, zmm13
    SPLIT64_VEC8 zmm3, zmm13
    mov  rdi, [rsp + 192]
    lea  rdi, [rdi + 8*r14]
    cmp  r10d, 48
    ja   .Lnttsplit_ext32_b64_2ch
    vcvtuqq2pd zmm0, zmm0
    vcvtuqq2pd zmm1, zmm1
    vcvtuqq2pd zmm2, zmm2
    vcvtuqq2pd zmm3, zmm3
    vmovupd [rdi + 0],   zmm0
    vmovupd [rdi + 64],  zmm1
    vmovupd [rdi + 128], zmm2
    vmovupd [rdi + 192], zmm3
    add  r14, 32
    jmp  .Lnttsplit_ext_loop

.Lnttsplit_ext32_b64_2ch:
    vpandq     zmm4, zmm0, zmm18
    vpandq     zmm5, zmm1, zmm18
    vpandq     zmm6, zmm2, zmm18
    vpandq     zmm7, zmm3, zmm18
    vpsrlq     zmm0, zmm0, 48
    vpsrlq     zmm1, zmm1, 48
    vpsrlq     zmm2, zmm2, 48
    vpsrlq     zmm3, zmm3, 48
    jmp  .Lnttsplit_ext32_store_2ch

.Lnttsplit_ext32_b96:
    cmp  r10d, 96
    ja   .Lnttsplit_ext32_b128
    SPLIT96_VEC8 zmm0, zmm4
    SPLIT96_VEC8 zmm1, zmm5
    SPLIT96_VEC8 zmm2, zmm6
    SPLIT96_VEC8 zmm3, zmm7
    mov  rdi, [rsp + 192]
    lea  rdi, [rdi + 8*r14]
.Lnttsplit_ext32_store_2ch:
    mov  r9,  [rsp + 248]
    vcvtuqq2pd zmm4, zmm4
    vcvtuqq2pd zmm5, zmm5
    vcvtuqq2pd zmm6, zmm6
    vcvtuqq2pd zmm7, zmm7
    vcvtuqq2pd zmm0, zmm0
    vcvtuqq2pd zmm1, zmm1
    vcvtuqq2pd zmm2, zmm2
    vcvtuqq2pd zmm3, zmm3
    vmovupd [rdi + 0],   zmm4
    vmovupd [rdi + 64],  zmm5
    vmovupd [rdi + 128], zmm6
    vmovupd [rdi + 192], zmm7
    add  rdi, r9
    vmovupd [rdi + 0],   zmm0
    vmovupd [rdi + 64],  zmm1
    vmovupd [rdi + 128], zmm2
    vmovupd [rdi + 192], zmm3
    add  r14, 32
    jmp  .Lnttsplit_ext_loop

.Lnttsplit_ext32_b128:
    cmp  r10d, 128
    ja   .Lnttsplit_ext32_b160
    SPLIT128_VEC8 zmm0, 576, 320
    SPLIT128_VEC8 zmm1, 640, 384
    SPLIT128_VEC8 zmm2, 704, 448
    SPLIT128_VEC8 zmm3, 768, 512
    jmp  .Lnttsplit_ext32_store_3ch

.Lnttsplit_ext32_b160:
    cmp  r10d, 160
    ja   .Lnttsplit_ext32_b192
    SPLIT160_VEC8 zmm0, 576, 320
    SPLIT160_VEC8 zmm1, 640, 384
    SPLIT160_VEC8 zmm2, 704, 448
    SPLIT160_VEC8 zmm3, 768, 512
    cmp  r10d, 144
    ja   .Lnttsplit_ext32_store_4ch
    vcvtuqq2pd zmm0, zmm0
    vcvtuqq2pd zmm1, zmm1
    vcvtuqq2pd zmm2, zmm2
    vcvtuqq2pd zmm3, zmm3

.Lnttsplit_ext32_store_3ch:
    mov  rdi, [rsp + 192]
    lea  rdi, [rdi + 8*r14]
    mov  r9,  [rsp + 248]
    vmovapd zmm4, [rsp + 320]
    vmovapd zmm5, [rsp + 384]
    vmovapd zmm6, [rsp + 448]
    vmovapd zmm7, [rsp + 512]
    vmovupd [rdi + 0],   zmm4
    vmovupd [rdi + 64],  zmm5
    vmovupd [rdi + 128], zmm6
    vmovupd [rdi + 192], zmm7
    add  rdi, r9
    vmovapd zmm4, [rsp + 576]
    vmovapd zmm5, [rsp + 640]
    vmovapd zmm6, [rsp + 704]
    vmovapd zmm7, [rsp + 768]
    vmovupd [rdi + 0],   zmm4
    vmovupd [rdi + 64],  zmm5
    vmovupd [rdi + 128], zmm6
    vmovupd [rdi + 192], zmm7
    add  rdi, r9
    vmovupd [rdi + 0],   zmm0
    vmovupd [rdi + 64],  zmm1
    vmovupd [rdi + 128], zmm2
    vmovupd [rdi + 192], zmm3
    add  r14, 32
    jmp  .Lnttsplit_ext_loop

.Lnttsplit_ext32_b192:
    cmp  r10d, 192
    ja   .Lnttsplit_ext32_b208
    SPLIT192_VEC8 zmm0, 832, 576, 320
    SPLIT192_VEC8 zmm1, 896, 640, 384
    SPLIT192_VEC8 zmm2, 960, 704, 448
    SPLIT192_VEC8 zmm3, 1024, 768, 512
    mov  rdi, [rsp + 192]
    lea  rdi, [rdi + 8*r14]
    mov  r9,  [rsp + 248]
    vmovapd zmm4, [rsp + 320]
    vmovapd zmm5, [rsp + 384]
    vmovapd zmm6, [rsp + 448]
    vmovapd zmm7, [rsp + 512]
    vmovupd [rdi + 0],   zmm4
    vmovupd [rdi + 64],  zmm5
    vmovupd [rdi + 128], zmm6
    vmovupd [rdi + 192], zmm7
    add  rdi, r9
    vmovapd zmm4, [rsp + 576]
    vmovapd zmm5, [rsp + 640]
    vmovapd zmm6, [rsp + 704]
    vmovapd zmm7, [rsp + 768]
    vmovupd [rdi + 0],   zmm4
    vmovupd [rdi + 64],  zmm5
    vmovupd [rdi + 128], zmm6
    vmovupd [rdi + 192], zmm7
    add  rdi, r9
    vmovapd zmm4, [rsp + 832]
    vmovapd zmm5, [rsp + 896]
    vmovapd zmm6, [rsp + 960]
    vmovapd zmm7, [rsp + 1024]
    vmovupd [rdi + 0],   zmm4
    vmovupd [rdi + 64],  zmm5
    vmovupd [rdi + 128], zmm6
    vmovupd [rdi + 192], zmm7
    add  rdi, r9
    vmovupd [rdi + 0],   zmm0
    vmovupd [rdi + 64],  zmm1
    vmovupd [rdi + 128], zmm2
    vmovupd [rdi + 192], zmm3
    add  r14, 32
    jmp  .Lnttsplit_ext_loop

.Lnttsplit_ext32_b208:
    cmp  r10d, 240
    ja   .Lnttsplit_ext32_b384
    SPLIT208_VEC8 zmm0, 1088, 832, 576, 320
    SPLIT208_VEC8 zmm1, 1152, 896, 640, 384
    SPLIT208_VEC8 zmm2, 1216, 960, 704, 448
    SPLIT208_VEC8 zmm3, 1280, 1024, 768, 512
    mov  rdi, [rsp + 192]
    lea  rdi, [rdi + 8*r14]
    mov  r9,  [rsp + 248]
    vmovapd zmm4, [rsp + 320]
    vmovapd zmm5, [rsp + 384]
    vmovapd zmm6, [rsp + 448]
    vmovapd zmm7, [rsp + 512]
    vmovupd [rdi + 0],   zmm4
    vmovupd [rdi + 64],  zmm5
    vmovupd [rdi + 128], zmm6
    vmovupd [rdi + 192], zmm7
    add  rdi, r9
    vmovapd zmm4, [rsp + 576]
    vmovapd zmm5, [rsp + 640]
    vmovapd zmm6, [rsp + 704]
    vmovapd zmm7, [rsp + 768]
    vmovupd [rdi + 0],   zmm4
    vmovupd [rdi + 64],  zmm5
    vmovupd [rdi + 128], zmm6
    vmovupd [rdi + 192], zmm7
    add  rdi, r9
    vmovapd zmm4, [rsp + 832]
    vmovapd zmm5, [rsp + 896]
    vmovapd zmm6, [rsp + 960]
    vmovapd zmm7, [rsp + 1024]
    vmovupd [rdi + 0],   zmm4
    vmovupd [rdi + 64],  zmm5
    vmovupd [rdi + 128], zmm6
    vmovupd [rdi + 192], zmm7
    add  rdi, r9
    vmovapd zmm4, [rsp + 1088]
    vmovapd zmm5, [rsp + 1152]
    vmovapd zmm6, [rsp + 1216]
    vmovapd zmm7, [rsp + 1280]
    vmovupd [rdi + 0],   zmm4
    vmovupd [rdi + 64],  zmm5
    vmovupd [rdi + 128], zmm6
    vmovupd [rdi + 192], zmm7
    add  rdi, r9
    vmovupd [rdi + 0],   zmm0
    vmovupd [rdi + 64],  zmm1
    vmovupd [rdi + 128], zmm2
    vmovupd [rdi + 192], zmm3
    add  r14, 32
    jmp  .Lnttsplit_ext_loop

.Lnttsplit_ext32_b384:
    SPLIT384_VEC8 320, 256
    SPLIT384_VEC8 384, 256
    SPLIT384_VEC8 448, 256
    SPLIT384_VEC8 512, 256
    mov  rdi, [rsp + 192]
    lea  rdi, [rdi + 8*r14]
    mov  r9,  [rsp + 248]
    mov  rcx, [rsp + 232]
    xor  eax, eax
.Lnttsplit_ext32_b384_plane:
    vcvtuqq2pd zmm4, [rsp + rax + 320]
    vcvtuqq2pd zmm5, [rsp + rax + 384]
    vcvtuqq2pd zmm6, [rsp + rax + 448]
    vcvtuqq2pd zmm7, [rsp + rax + 512]
    vmovupd [rdi + 0],   zmm4
    vmovupd [rdi + 64],  zmm5
    vmovupd [rdi + 128], zmm6
    vmovupd [rdi + 192], zmm7
    add  rdi, r9
    add  rax, 256
    dec  rcx
    jnz  .Lnttsplit_ext32_b384_plane
    add  r14, 32
    jmp  .Lnttsplit_ext_loop

.Lnttsplit_ext32_store_4ch:
    mov  rdi, [rsp + 192]
    lea  rdi, [rdi + 8*r14]
    mov  r9,  [rsp + 248]
    vmovapd zmm4, [rsp + 320]
    vmovapd zmm5, [rsp + 384]
    vmovapd zmm6, [rsp + 448]
    vmovapd zmm7, [rsp + 512]
    vmovupd [rdi + 0],   zmm4
    vmovupd [rdi + 64],  zmm5
    vmovupd [rdi + 128], zmm6
    vmovupd [rdi + 192], zmm7
    add  rdi, r9
    vmovapd zmm4, [rsp + 576]
    vmovapd zmm5, [rsp + 640]
    vmovapd zmm6, [rsp + 704]
    vmovapd zmm7, [rsp + 768]
    vmovupd [rdi + 0],   zmm4
    vmovupd [rdi + 64],  zmm5
    vmovupd [rdi + 128], zmm6
    vmovupd [rdi + 192], zmm7
    add  rdi, r9
    vpandq     zmm4, zmm0, zmm18
    vpandq     zmm5, zmm1, zmm18
    vpandq     zmm6, zmm2, zmm18
    vpandq     zmm7, zmm3, zmm18
    vpsrlq     zmm0, zmm0, 48
    vpsrlq     zmm1, zmm1, 48
    vpsrlq     zmm2, zmm2, 48
    vpsrlq     zmm3, zmm3, 48
    vcvtuqq2pd zmm4, zmm4
    vcvtuqq2pd zmm5, zmm5
    vcvtuqq2pd zmm6, zmm6
    vcvtuqq2pd zmm7, zmm7
    vmovupd [rdi + 0],   zmm4
    vmovupd [rdi + 64],  zmm5
    vmovupd [rdi + 128], zmm6
    vmovupd [rdi + 192], zmm7
    add  rdi, r9
    vcvtuqq2pd zmm0, zmm0
    vcvtuqq2pd zmm1, zmm1
    vcvtuqq2pd zmm2, zmm2
    vcvtuqq2pd zmm3, zmm3
    vmovupd [rdi + 0],   zmm0
    vmovupd [rdi + 64],  zmm1
    vmovupd [rdi + 128], zmm2
    vmovupd [rdi + 192], zmm3
    add  r14, 32
    jmp  .Lnttsplit_ext_loop

.Lnttsplit_ext_scalar:
    test r12, r12
    jnz  .Lnttsplit_ext_sc_strided
    lea  rdx, [r11 + r14]
    jmp  .Lnttsplit_ext_sc_idx_ok
.Lnttsplit_ext_sc_strided:
    lea  rdx, [rbx + r15]
    inc  r15
    cmp  r15, r13
    jb   .Lnttsplit_ext_sc_idx_ok
    xor  r15d, r15d
    add  rbx, r12
.Lnttsplit_ext_sc_idx_ok:
    imul rdx, r10                       // bit_pos = idx * b
    mov  rsi, [rsp + 200]
    mov  r9,  [rsp + 216]
    mov  rdi, [rsp + 192]
    lea  rdi, [rdi + 8*r14]
    mov  rax, [rsp + 232]
    mov  [rsp + 0], rax                 // rem_chunks
    xor  r8d, r8d                       // ch_bit_off = 0
.Lnttsplit_ext_sc_ch:
    mov  rcx, r10
    sub  rcx, r8
    mov  eax, 48
    cmp  rcx, rax
    cmova rcx, rax                      // c_w = min(48, b - ch_bit_off)
    lea  rax, [rdx + r8]                // c_bit
    xor  r13d, r13d
    cmp  rax, [rsp + 224]
    jae  .Lnttsplit_ext_sc_emit
    mov  r11, rax
    shr  r11, 6
    cmp  r11, r9
    jae  .Lnttsplit_ext_sc_emit
    and  eax, 63
    shrx r13, [rsi + 8*r11], rax
    inc  r11
    add  eax, ecx
    cmp  eax, 64
    jbe  .Lnttsplit_ext_sc_mask
    cmp  r11, r9
    jae  .Lnttsplit_ext_sc_mask
    sub  eax, ecx
    neg  eax
    add  eax, 64
    shlx r11, [rsi + 8*r11], rax
    or   r13, r11
.Lnttsplit_ext_sc_mask:
    bzhi r13, r13, rcx
.Lnttsplit_ext_sc_emit:
    vcvtusi2sd xmm0, xmm0, r13
    vmovsd [rdi], xmm0
    add  rdi, [rsp + 248]
    add  r8, 48
    dec  qword ptr [rsp + 0]
    jnz  .Lnttsplit_ext_sc_ch

    mov  rdx, [rsp + 208]
    mov  r11, [rdx + 8]
    mov  r13, [rdx + 40]
    inc  r14
    jmp  .Lnttsplit_ext_loop

    // ========================================================================
    // Planar 48-bit chunk modular Horner reduction mode (cfg.in_limbs == u64::MAX)
    // ========================================================================
.Lnttsplit_reduce_entry:
    mov  r10, [rdx + 24]                // b = coeff_bits
    mov  r11, [rdx + 48]                // p (IEEE-754 f64 bits)
    vbroadcastsd zmm29, [rdx + 48]      // p
    vbroadcastsd zmm30, [rdx + 56]      // inv_p
    vpxorq       zmm31, zmm31, zmm31    // 0.0

    mov  r9,  r8
    cmp  r8,  32
    jb   .Lnttsplit_red_stride_ok
    add  r9,  7
    and  r9,  -8
    add  r9,  8
.Lnttsplit_red_stride_ok:
    shl  r9,  3                         // plane_stride_bytes

    lea  rax, [r10 + 47]
    cmp  r10, 32768
    ja   .Lnttsplit_red_div_b
    imul rax, rax, 0xAAAB
    shr  rax, 21                        // exact (b + 47) / 48 for all b <= 65000!
    mov  r12, rax
    jmp  .Lnttsplit_red_chk_p
.Lnttsplit_red_div_b:
    xor  edx, edx
    mov  r12d, 48
    div  r12
    mov  r12, rax

.Lnttsplit_red_chk_p:
    movabs rax, 0x42F0000000000000      // 2^48 = 281474976710656.0 (exact IEEE-754 f64)
    cmp  r11, rax
    jbe  .Lnttsplit_red_small_p         // p_u64 <= 2^48 -> general loop
    vmovq        xmm0, rax
    vbroadcastsd zmm28, xmm0            // zmm28 = 2^48 (since p > 2^48!)
    vmulpd       zmm27, zmm28, zmm30    // zmm27 = 2^48 * inv_p (exact exponent +48!)
    cmp  r8,  32
    jb   .Lnttsplit_red_gen
    cmp  r12, 2
    je   .Lnttsplit_red2
    cmp  r12, 3
    je   .Lnttsplit_red3
    cmp  r12, 4
    je   .Lnttsplit_red4
    cmp  r12, 5
    je   .Lnttsplit_red5
    ja   .Lnttsplit_red_ge6
    jmp  .Lnttsplit_red_gen

.Lnttsplit_red_small_p:
    vmovq       xmm0, r11
    vcvttsd2usi rcx, xmm0
    mov  eax, 1
    shl  rax, 48
    xor  edx, edx
    div  rcx
    vcvtusi2sd   xmm0, xmm0, rdx
    vbroadcastsd zmm28, xmm0
    jmp  .Lnttsplit_red_gen

.Lnttsplit_red_ge6:
    mov  r13, r12
    dec  r13
    imul r13, r9
.p2align 6
.Lnttsplit_red_ge6_loop32:
    lea  rbx, [rsi + r13]
    vmovupd zmm0, [rbx + 0]
    vmovupd zmm1, [rbx + 64]
    vmovupd zmm2, [rbx + 128]
    vmovupd zmm3, [rbx + 192]
    mov  rax, r12
    dec  rax
.Lnttsplit_red_ge6_ch:
    sub  rbx, r9
    ZMM_HORNER48_LAZY4 zmm28, zmm27, rbx
    dec  rax
    jnz  .Lnttsplit_red_ge6_ch
    ZMM_FIX_NEG4 zmm0, zmm1, zmm2, zmm3     // the lazy chain ends within (-0.625 p, 1.625 p)
    ZMM_FIX_GE4 zmm0, zmm1, zmm2, zmm3
    vmovupd [rdi + 0],   zmm0
    vmovupd [rdi + 64],  zmm1
    vmovupd [rdi + 128], zmm2
    vmovupd [rdi + 192], zmm3
    add  rsi, 256
    add  rdi, 256
    sub  r8,  32
    cmp  r8,  32
    jae  .Lnttsplit_red_ge6_loop32
    jmp  .Lnttsplit_red_gen

.Lnttsplit_red2:
    lea  r13, [rsi + r9]
.p2align 6
.Lnttsplit_red2_loop32:
    vmovupd zmm0, [r13 + 0]
    vmovupd zmm1, [r13 + 64]
    vmovupd zmm2, [r13 + 128]
    vmovupd zmm3, [r13 + 192]
    ZMM_HORNER48_LAST4 zmm28, zmm27, rsi
    vmovupd [rdi + 0],   zmm0
    vmovupd [rdi + 64],  zmm1
    vmovupd [rdi + 128], zmm2
    vmovupd [rdi + 192], zmm3
    add  rsi, 256
    add  r13, 256
    add  rdi, 256
    sub  r8,  32
    cmp  r8,  32
    jae  .Lnttsplit_red2_loop32
    jmp  .Lnttsplit_red_gen

.Lnttsplit_red3:
    lea  r13, [rsi + r9]
    lea  r14, [r13 + r9]
.p2align 6
.Lnttsplit_red3_loop32:
    vmovupd zmm0, [r14 + 0]
    vmovupd zmm1, [r14 + 64]
    vmovupd zmm2, [r14 + 128]
    vmovupd zmm3, [r14 + 192]
    ZMM_HORNER48_LAZY4 zmm28, zmm27, r13
    ZMM_HORNER48_LAST4 zmm28, zmm27, rsi
    vmovupd [rdi + 0],   zmm0
    vmovupd [rdi + 64],  zmm1
    vmovupd [rdi + 128], zmm2
    vmovupd [rdi + 192], zmm3
    add  rsi, 256
    add  r13, 256
    add  r14, 256
    add  rdi, 256
    sub  r8,  32
    cmp  r8,  32
    jae  .Lnttsplit_red3_loop32
    jmp  .Lnttsplit_red_gen

.Lnttsplit_red4:
    lea  r13, [rsi + r9]
    lea  r14, [r13 + r9]
    lea  r15, [r14 + r9]
.p2align 6
.Lnttsplit_red4_loop32:
    vmovupd zmm0, [r15 + 0]
    vmovupd zmm1, [r15 + 64]
    vmovupd zmm2, [r15 + 128]
    vmovupd zmm3, [r15 + 192]
    ZMM_HORNER48_LAZY4 zmm28, zmm27, r14
    ZMM_HORNER48_LAZY4 zmm28, zmm27, r13
    ZMM_HORNER48_LAST4 zmm28, zmm27, rsi
    vmovupd [rdi + 0],   zmm0
    vmovupd [rdi + 64],  zmm1
    vmovupd [rdi + 128], zmm2
    vmovupd [rdi + 192], zmm3
    add  rsi, 256
    add  r13, 256
    add  r14, 256
    add  r15, 256
    add  rdi, 256
    sub  r8,  32
    cmp  r8,  32
    jae  .Lnttsplit_red4_loop32
    jmp  .Lnttsplit_red_gen

.Lnttsplit_red5:
    lea  r13, [rsi + r9]
    lea  r14, [r13 + r9]
    lea  r15, [r14 + r9]
    lea  rbx, [r15 + r9]
.p2align 6
.Lnttsplit_red5_loop32:
    vmovupd zmm0, [rbx + 0]
    vmovupd zmm1, [rbx + 64]
    vmovupd zmm2, [rbx + 128]
    vmovupd zmm3, [rbx + 192]
    ZMM_HORNER48_LAZY4 zmm28, zmm27, r15
    ZMM_HORNER48_LAZY4 zmm28, zmm27, r14
    ZMM_HORNER48_LAZY4 zmm28, zmm27, r13
    ZMM_HORNER48_LAST4 zmm28, zmm27, rsi
    vmovupd [rdi + 0],   zmm0
    vmovupd [rdi + 64],  zmm1
    vmovupd [rdi + 128], zmm2
    vmovupd [rdi + 192], zmm3
    add  rsi, 256
    add  r13, 256
    add  r14, 256
    add  r15, 256
    add  rbx, 256
    add  rdi, 256
    sub  r8,  32
    cmp  r8,  32
    jae  .Lnttsplit_red5_loop32

.Lnttsplit_red_gen:
    cmp  r8,  8
    jb   .Lnttsplit_red_tail
.Lnttsplit_red_loop8:
    vpxorq zmm0, zmm0, zmm0
    mov  rax, r12
    mov  rbx, r12
    dec  rbx
    imul rbx, r9
    add  rbx, rsi
.Lnttsplit_red_ch8:
    vmovupd zmm1, [rbx]
    vcmppd  k1, zmm1, zmm29, 13
    vsubpd  zmm1 {k1}, zmm1, zmm29
    cmp  rax, r12
    je   .Lnttsplit_red_add8
    ZMM_MUL_MOD zmm0, zmm28, zmm16, zmm20, k1
.Lnttsplit_red_add8:
    ZMM_ADD_MOD zmm0, zmm0, zmm1, k1
    sub  rbx, r9
    dec  rax
    jnz  .Lnttsplit_red_ch8
    vmovupd [rdi], zmm0
    add  rsi, 64
    add  rdi, 64
    sub  r8,  8
    cmp  r8,  8
    jae  .Lnttsplit_red_loop8

.Lnttsplit_red_tail:
    test r8,  r8
    jz   .Lnttsplit_fast_done
    mov  eax, 0xFF
    bzhi eax, eax, r8d
    kmovw k5, eax
    vpxorq zmm0, zmm0, zmm0
    mov  rax, r12
    mov  rbx, r12
    dec  rbx
    imul rbx, r9
    add  rbx, rsi
.Lnttsplit_red_cht:
    vmovupd zmm1 {k5}{z}, [rbx]
    vcmppd  k1, zmm1, zmm29, 13
    vsubpd  zmm1 {k1}, zmm1, zmm29
    cmp  rax, r12
    je   .Lnttsplit_red_addt
    ZMM_MUL_MOD zmm0, zmm28, zmm16, zmm20, k1
.Lnttsplit_red_addt:
    ZMM_ADD_MOD zmm0, zmm0, zmm1, k1
    sub  rbx, r9
    dec  rax
    jnz  .Lnttsplit_red_cht
    vmovupd [rdi] {k5}, zmm0

.Lnttsplit_fast_done:
    VEC_LEAVE_FAST

.Lnttsplit_done:
    VEC_LEAVE

// [13] ntt_fwd(buf: rdi, twiddles: rsi, n: rdx, prime: rcx)
// In-register Radix-16 DIF passes across ZMM0..ZMM31, plus Radix-8/4/2 top
// alignment and in-register Radix-16 bottom pass (m = 8, 4, 2, 1).
LOCAL_FN supi_k_ntt_fwd
    VEC_ENTER 1152
    cmp  rdx, 1
    jbe  .Lnttfwd_done

    mov  qword ptr [rsp + 1128], 0
    mov  qword ptr [rsp + 1144], 0

    vbroadcastsd zmm29, [rcx + 0]       // p
    vbroadcastsd zmm30, [rcx + 8]       // inv_p
    vpxorq       zmm31, zmm31, zmm31    // 0.0

    cmp  rdx, 16
    jb   .Lnttfwd_small

.Lnttfwd_ge16_entry:
    mov  [rsp + 0], rdi                 // orig_buf
    mov  [rsp + 8], rdx                 // orig_n
    mov  rax, [rcx + 24]                // raw l1_sub
    mov  rbx, [rcx + 32]                // raw l2_sub
    cmp  rax, rdx
    jae  .Lnttfwd_single_sub
    mov  r8d, 64
    cmp  rax, 64
    cmovb rax, r8
    lzcnt r9, rax
    mov  ecx, 63
    sub  ecx, r9d                       // k1 = log2(l1_sub) >= 6
    mov  eax, 1
    shl  rax, cl                        // l1_sub = 2^k1
    cmp  rdx, rax
    jbe  .Lnttfwd_single_sub
    cmp  ecx, 11
    jne  .Lnttfwd_keep_k1
    tzcnt r8, rdx
    test r8d, 1
    jnz  .Lnttfwd_keep_k1
    dec  ecx
    shr  rax, 1                         // l1_sub = 1024 for all even log2(orig_n) (2 L1 passes + pure R4 above!)
.Lnttfwd_keep_k1:
    mov  [rsp + 1072], rax              // l1_sub
    mov  [rsp + 1080], rcx              // k1
    jmp  .Lnttfwd_above_start

.Lnttfwd_single_sub:
    mov  [rsp + 16], rdx                // sub_n = orig_n
    mov  qword ptr [rsp + 24], 1        // num_subs = 1
    mov  qword ptr [rsp + 1048], 0      // num_l2 = 0
    mov  qword ptr [rsp + 1056], 1      // sub_end = 1
    jmp  .Lnttfwd_sub_init

    // Top DIF passes above sub_n = l1_sub using 4-stream Radix-4 / 2-stream Radix-2
    // with 2-level l2_sub + l1_sub sub-blocking when n > l2_sub.
.Lnttfwd_above_start:
    cmp  rbx, rdx
    jae  .Lnttfwd_no_l2_mode
    lea  r8,  [rax + rax]               // min l2_sub = 2 * l1_sub
    cmp  rbx, r8
    cmovb rbx, r8
    lzcnt r9, rbx
    mov  ecx, 63
    sub  ecx, r9d                       // k2 = log2(l2_sub) > k1
    mov  eax, 1
    shl  rax, cl                        // l2_sub = 2^k2
    cmp  ecx, 15
    jne  .Lnttfwd_keep_k2
    cmp  qword ptr [rsp + 1080], 10
    jne  .Lnttfwd_keep_k2
    dec  ecx
    shr  rax, 1                         // l2_sub = 16384 (128 KiB) for even log2(orig_n) >= 16 (pure R4 in L3 and L2!)
.Lnttfwd_keep_k2:
    cmp  rdx, rax
    ja   .Lnttfwd_l2_mode

.Lnttfwd_no_l2_mode:
    mov  qword ptr [rsp + 1024], 1      // tw_root_blk = 1
    mov  qword ptr [rsp + 1032], 0      // is_l2_local = 0
    mov  qword ptr [rsp + 1048], 0      // num_l2 = 0
    tzcnt r15, rdx
    sub  r15, [rsp + 1080]              // stages above l1_sub
    mov  r12, 1                         // b_blocks = 1
    mov  r13, rdx
    shr  r13, 1                         // m = n / 2
    xor  edx, edx                       // stages since the values were last within p of zero
    jmp  .Lnttfwd_above_r4

.Lnttfwd_l2_mode:
    mov  [rsp + 1088], rax              // l2_sub
    mov  [rsp + 1096], rcx              // k2
    mov  r8,  rcx
    sub  r8,  [rsp + 1080]              // k_diff = k2 - k1 >= 1
    mov  [rsp + 1104], r8
    mov  eax, 1
    mov  ecx, r8d
    shl  rax, cl                        // subs_per_l2 = 1 << (k2 - k1)
    mov  [rsp + 1112], rax
    mov  rcx, [rsp + 1096]
    mov  rax, rdx
    shr  rax, cl
    mov  [rsp + 1048], rax              // num_l2 = orig_n / l2_sub
    mov  qword ptr [rsp + 1040], 0      // l2_idx = 0
    mov  qword ptr [rsp + 1024], 1      // tw_root_blk = 1
    mov  qword ptr [rsp + 1032], 0      // is_l2_local = 0
    tzcnt r15, rdx
    sub  r15, [rsp + 1096]              // stages above l2_sub
    mov  r12, 1                         // b_blocks = 1
    mov  r13, rdx
    shr  r13, 1                         // m = n / 2
    xor  edx, edx                       // stages since the values were last within p of zero

.Lnttfwd_above_r4:
    cmp  r15, 2
    jb   .Lnttfwd_above_r2
    // Lazy values may go through four stages between two reductions (from within p of zero
    // they stay within 7.0 p, as in the Radix-16 passes below). A pass therefore leaves its
    // reduction to the next one where the two together are four stages or fewer; the last
    // pass above sub_n always reduces. ecx: this pass reduces.
    add  edx, 2
    mov  ecx, 1
    lea  rax, [r15 - 2]                 // stages left above sub_n after this pass
    test rax, rax
    jz   .Lnttfwd_above_r4_red
    cmp  rax, 2
    mov  r9d, 2
    cmova rax, r9                       // the stages of the next pass
    add  eax, edx
    cmp  eax, 4
    ja   .Lnttfwd_above_r4_red
    xor  ecx, ecx
    jmp  .Lnttfwd_above_r4_go
.Lnttfwd_above_r4_red:
    xor  edx, edx
.Lnttfwd_above_r4_go:
    mov  r14, r13
    shr  r14, 1                         // s = m / 2 >= 2048 (multiple of 32)
    mov  rbx, r14
    shl  rbx, 3                         // s_bytes (4 streams = 8 ways across 2 SMT threads <= 12-way L1d)
    xor  r8d, r8d
.Lnttfwd_above_r4_blk:
    mov  rax, r8
    shl  rax, 2
    imul rax, rbx
    lea  r9,  [rdi + rax]
    mov  r10, r14
    mov  rax, [rsp + 1024]
    imul rax, r12
    add  rax, r8
    mov  r11, 0x3FF0000000000000
    cmp  qword ptr [rsi + 8*rax], r11
    jne  .Lnttfwd_above_r4_gen
    add  rax, rax
    cmp  qword ptr [rsi + 8*rax], r11
    jne  .Lnttfwd_above_r4_gen_from2
    vbroadcastsd zmm26, [rsi + 8*rax + 8]
    vmulpd       zmm27, zmm26, zmm30
    test ecx, ecx
    jnz  .Lnttfwd_above_r4_vec_w1_red
.p2align 6
.Lnttfwd_above_r4_vec_w1:
    lea  r11, [r9 + 2*rbx]
    vmovupd zmm0,  [r9 + 0]
    vmovupd zmm1,  [r9 + 64]
    vmovupd zmm2,  [r9 + rbx + 0]
    vmovupd zmm3,  [r9 + rbx + 64]
    vmovupd zmm4,  [r11 + 0]
    vmovupd zmm5,  [r11 + 64]
