    vmovupd [r9 + 64],         zmm1
    vmovupd [r9 + rbx + 0],    zmm2
    vmovupd [r9 + rbx + 64],   zmm3
    vmovupd [r9 + 2*rbx + 0],  zmm4
    vmovupd [r9 + 2*rbx + 64], zmm5
    vmovupd [r9 + rax + 0],    zmm6
    vmovupd [r9 + rax + 64],   zmm7
    vmovupd [r11 + 0],         zmm8
    vmovupd [r11 + 64],        zmm9
    vmovupd [r11 + rbx + 0],   zmm10
    vmovupd [r11 + rbx + 64],  zmm11
    vmovupd [r11 + 2*rbx + 0], zmm12
    vmovupd [r11 + 2*rbx + 64],zmm13
    vmovupd [r11 + rax + 0],   zmm14
    vmovupd [r11 + rax + 64],  zmm15

    lea  r9, [r9 + 128]
    sub  r10, 16
    jnz  .Lnttfwd_r8_top_w1
    jmp  .Lnttfwd_r8_top_done

.Lnttfwd_r8_top_gen:
    mov  qword ptr [rsp + 56], 0
    vbroadcastsd zmm28, [rsi + rcx]
    vmulpd       zmm31, zmm28, zmm30
    vbroadcastsd zmm24, [rsi + 2*rcx + 0]
    vbroadcastsd zmm25, [rsi + 2*rcx + 8]
    vmulpd       zmm26, zmm24, zmm30
    vmulpd       zmm27, zmm25, zmm30
    vmovupd      ymm20, [rsi + 4*rcx]
    vmulpd       ymm20, ymm20, ymm30
    vmovapd      [rsp + 64], ymm20
.p2align 4
.Lnttfwd_r8_top_vec:
    lea  r11, [r9 + 4*rbx]
    vmovupd zmm0,  [r9 + 0]
    vmovupd zmm1,  [r9 + 64]
    vmovupd zmm2,  [r9 + rbx + 0]
    vmovupd zmm3,  [r9 + rbx + 64]
    vmovupd zmm4,  [r9 + 2*rbx + 0]
    vmovupd zmm5,  [r9 + 2*rbx + 64]
    vmovupd zmm6,  [r9 + rax + 0]
    vmovupd zmm7,  [r9 + rax + 64]
    vmovupd zmm8,  [r11 + 0]
    vmovupd zmm9,  [r11 + 64]
    vmovupd zmm10, [r11 + rbx + 0]
    vmovupd zmm11, [r11 + rbx + 64]
    vmovupd zmm12, [r11 + 2*rbx + 0]
    vmovupd zmm13, [r11 + 2*rbx + 64]
    vmovupd zmm14, [r11 + rax + 0]
    vmovupd zmm15, [r11 + rax + 64]

    NTT_DIF4_SHOUP zmm0, zmm8,  zmm28, zmm31, zmm1, zmm9,  zmm28, zmm31, zmm2, zmm10, zmm28, zmm31, zmm3, zmm11, zmm28, zmm31
    NTT_DIF4_SHOUP zmm4, zmm12, zmm28, zmm31, zmm5, zmm13, zmm28, zmm31, zmm6, zmm14, zmm28, zmm31, zmm7, zmm15, zmm28, zmm31

    NTT_DIF4_SHOUP zmm0, zmm4,  zmm24, zmm26, zmm1, zmm5,  zmm24, zmm26, zmm2, zmm6,  zmm24, zmm26, zmm3, zmm7,  zmm24, zmm26
    NTT_DIF4_SHOUP zmm8, zmm12, zmm25, zmm27, zmm9, zmm13, zmm25, zmm27, zmm10, zmm14, zmm25, zmm27, zmm11, zmm15, zmm25, zmm27

    NTT_DIF4_SHOUP_MEM zmm0, zmm2,  rsi+4*rcx+0,  rsp+64+0,  zmm1, zmm3,  rsi+4*rcx+0,  rsp+64+0,  zmm4,  zmm6,  rsi+4*rcx+8,  rsp+64+8,  zmm5,  zmm7,  rsi+4*rcx+8,  rsp+64+8
    NTT_DIF4_SHOUP_MEM zmm8, zmm10, rsi+4*rcx+16, rsp+64+16, zmm9, zmm11, rsi+4*rcx+16, rsp+64+16, zmm12, zmm14, rsi+4*rcx+24, rsp+64+24, zmm13, zmm15, rsi+4*rcx+24, rsp+64+24

    vmovupd [r9 + 0],          zmm0
    vmovupd [r9 + 64],         zmm1
    vmovupd [r9 + rbx + 0],    zmm2
    vmovupd [r9 + rbx + 64],   zmm3
    vmovupd [r9 + 2*rbx + 0],  zmm4
    vmovupd [r9 + 2*rbx + 64], zmm5
    vmovupd [r9 + rax + 0],    zmm6
    vmovupd [r9 + rax + 64],   zmm7
    vmovupd [r11 + 0],         zmm8
    vmovupd [r11 + 64],        zmm9
    vmovupd [r11 + rbx + 0],   zmm10
    vmovupd [r11 + rbx + 64],  zmm11
    vmovupd [r11 + 2*rbx + 0], zmm12
    vmovupd [r11 + 2*rbx + 64],zmm13
    vmovupd [r11 + rax + 0],   zmm14
    vmovupd [r11 + rax + 64],  zmm15

    lea  r9, [r9 + 128]
    sub  r10, 16
    jnz  .Lnttfwd_r8_top_vec

.Lnttfwd_r8_top_done:
    mov  rdx, [rsp + 16]
    mov  r12, 8
    mov  r13, rdx
    shr  r13, 4
    sub  r15, 3

    // 1. In-register Radix-16 pass inside L1d while r15 >= 4 (s_bytes = 128 B on sub_n = 2048!)
.Lnttfwd_r16_check:
    cmp  r15, 4
    jb   .Lnttfwd_top_rem

    mov  r14, r13
    shr  r14, 3                         // s = m / 8
    mov  rbx, r14
    shl  rbx, 3                         // s_bytes = s * 8
    xor  r8d, r8d                       // j_local = 0 .. b_local - 1

.Lnttfwd_r16_block:
    mov  [rsp + 48], r8
    mov  rcx, [rsp + 40]
    imul rcx, r12
    add  rcx, r8                        // tw_idx0 = tw_root * b_local + j_local
    shl  rcx, 3                         // 8 * tw_idx0
    vbroadcastsd zmm28, [rsi + rcx]
    vmulpd       zmm31, zmm28, zmm30

    mov  rax, r8
    shl  rax, 4
    imul rax, rbx
    lea  r9,  [rdi + rax]
    mov  r10, r14                       // i_rem = s
    lea  rax, [rbx + 2*rbx]             // 3 * s_bytes
    cmp  qword ptr [rsp + 56], 0
    je   .Lnttfwd_r16_prep_gen
    mov  r11, 0x3FF0000000000000
    cmp  qword ptr [rsi + rcx], r11
    jne  .Lnttfwd_r16_prep_gen
    cmp  qword ptr [rsi + 2*rcx], r11
    jne  .Lnttfwd_r16_prep_gen
    cmp  qword ptr [rsi + 4*rcx], r11
    jne  .Lnttfwd_r16_prep_gen
    vbroadcastsd zmm28, [rsi + 2*rcx + 8]
    vmulpd       zmm31, zmm28, zmm30
    vmovupd      ymm20, [rsi + 4*rcx]
    vmovupd      zmm21, [rsi + 8*rcx]
    vmulpd       ymm20, ymm20, ymm30
    vmulpd       zmm21, zmm21, zmm30
    vmovapd      [rsp + 96],  ymm20
    vmovapd      [rsp + 128], zmm21
    vbroadcastsd zmm24, [rsi + 4*rcx + 16]
    vbroadcastsd zmm25, [rsi + 4*rcx + 24]
    vmulpd       zmm26, zmm24, zmm30
    vmulpd       zmm27, zmm25, zmm30

.p2align 6
.Lnttfwd_r16_vec_w1:
    vmovupd zmm0,  [r9]
    vmovupd zmm1,  [r9 + rbx]
    vmovupd zmm2,  [r9 + 2*rbx]
    vmovupd zmm3,  [r9 + rax]
    lea  r11, [r9 + 4*rbx]
    lea  r8,  [r9 + 8*rbx]
    vmovupd zmm4,  [r11]
    vmovupd zmm5,  [r11 + rbx]
    vmovupd zmm6,  [r11 + 2*rbx]
    vmovupd zmm7,  [r11 + rax]
    vmovupd zmm8,  [r8]
    vmovupd zmm9,  [r8 + rbx]
    vmovupd zmm10, [r8 + 2*rbx]
    vmovupd zmm11, [r8 + rax]
    lea  r11, [r8 + 4*rbx]
    vmovupd zmm12, [r11]
    vmovupd zmm13, [r11 + rbx]
    vmovupd zmm14, [r11 + 2*rbx]
    vmovupd zmm15, [r11 + rax]

    NTT_BFY4_W1    zmm0, zmm8,  zmm1, zmm9,  zmm2, zmm10, zmm3, zmm11
    NTT_BFY4_W1    zmm4, zmm12, zmm5, zmm13, zmm6, zmm14, zmm7, zmm15
    NTT_BFY4_W1    zmm0, zmm4,  zmm1, zmm5,  zmm2, zmm6,  zmm3, zmm7
    ZMM_RED4_SIGNED zmm0, zmm1, zmm2, zmm3

    NTT_DIF4_SHOUP zmm8, zmm12, zmm28, zmm31, zmm9, zmm13, zmm28, zmm31, zmm10, zmm14, zmm28, zmm31, zmm11, zmm15, zmm28, zmm31

    NTT_BFY2_W1        zmm0, zmm2, zmm1, zmm3
    NTT_DIF2_SHOUP_MEM zmm4, zmm6, rsi+4*rcx+8, rsp+96+8, zmm5, zmm7, rsi+4*rcx+8, rsp+96+8
    NTT_DIF4_SHOUP     zmm8, zmm10, zmm24, zmm26, zmm9, zmm11, zmm24, zmm26, zmm12, zmm14, zmm25, zmm27, zmm13, zmm15, zmm25, zmm27

    NTT_DIF4_SHOUP_MEM zmm0, zmm1, rsi+8*rcx+0,  rsp+128+0,  zmm2,  zmm3,  rsi+8*rcx+8,  rsp+128+8,  zmm4,  zmm5,  rsi+8*rcx+16, rsp+128+16, zmm6,  zmm7,  rsi+8*rcx+24, rsp+128+24
    NTT_DIF4_SHOUP_MEM zmm8, zmm9, rsi+8*rcx+32, rsp+128+32, zmm10, zmm11, rsi+8*rcx+40, rsp+128+40, zmm12, zmm13, rsi+8*rcx+48, rsp+128+48, zmm14, zmm15, rsi+8*rcx+56, rsp+128+56

    vmovupd [r9],         zmm0
    vmovupd [r9 + rbx],   zmm1
    vmovupd [r9 + 2*rbx], zmm2
    vmovupd [r9 + rax],   zmm3
    lea  r11, [r9 + 4*rbx]
    lea  r8,  [r9 + 8*rbx]
    vmovupd [r11],         zmm4
    vmovupd [r11 + rbx],   zmm5
    vmovupd [r11 + 2*rbx], zmm6
    vmovupd [r11 + rax],   zmm7
    vmovupd [r8],          zmm8
    vmovupd [r8 + rbx],    zmm9
    vmovupd [r8 + 2*rbx],  zmm10
    vmovupd [r8 + rax],    zmm11
    lea  r11, [r8 + 4*rbx]
    vmovupd [r11],         zmm12
    vmovupd [r11 + rbx],   zmm13
    vmovupd [r11 + 2*rbx], zmm14
    vmovupd [r11 + rax],   zmm15

    lea  r9, [r9 + 64]
    sub  r10, 8
    jnz  .Lnttfwd_r16_vec_w1
    jmp  .Lnttfwd_r16_blk_next

.Lnttfwd_r16_prep_gen:
    vbroadcastsd zmm24, [rsi + 2*rcx + 0]
    vbroadcastsd zmm25, [rsi + 2*rcx + 8]
    vmulpd       zmm26, zmm24, zmm30
    vmulpd       zmm27, zmm25, zmm30
    vmovupd      ymm20, [rsi + 4*rcx]
    vmovupd      zmm21, [rsi + 8*rcx]
    vmulpd       ymm20, ymm20, ymm30
    vmulpd       zmm21, zmm21, zmm30
    vmovapd      [rsp + 96],  ymm20
    vmovapd      [rsp + 128], zmm21

.p2align 6
.Lnttfwd_r16_vec:
    vmovupd zmm0,  [r9]
    vmovupd zmm1,  [r9 + rbx]
    vmovupd zmm2,  [r9 + 2*rbx]
    vmovupd zmm3,  [r9 + rax]
    lea  r11, [r9 + 4*rbx]
    lea  r8,  [r9 + 8*rbx]
    vmovupd zmm4,  [r11]
    vmovupd zmm5,  [r11 + rbx]
    vmovupd zmm6,  [r11 + 2*rbx]
    vmovupd zmm7,  [r11 + rax]
    vmovupd zmm8,  [r8]
    vmovupd zmm9,  [r8 + rbx]
    vmovupd zmm10, [r8 + 2*rbx]
    vmovupd zmm11, [r8 + rax]
    lea  r11, [r8 + 4*rbx]
    vmovupd zmm12, [r11]
    vmovupd zmm13, [r11 + rbx]
    vmovupd zmm14, [r11 + 2*rbx]
    vmovupd zmm15, [r11 + rax]

    NTT_DIF4_SHOUP zmm0, zmm8,  zmm28, zmm31, zmm1, zmm9,  zmm28, zmm31, zmm2, zmm10, zmm28, zmm31, zmm3, zmm11, zmm28, zmm31
    NTT_DIF4_SHOUP zmm4, zmm12, zmm28, zmm31, zmm5, zmm13, zmm28, zmm31, zmm6, zmm14, zmm28, zmm31, zmm7, zmm15, zmm28, zmm31

    NTT_DIF4_SHOUP zmm0, zmm4,  zmm24, zmm26, zmm1, zmm5,  zmm24, zmm26, zmm2, zmm6,  zmm24, zmm26, zmm3, zmm7,  zmm24, zmm26
    NTT_DIF4_SHOUP zmm8, zmm12, zmm25, zmm27, zmm9, zmm13, zmm25, zmm27, zmm10, zmm14, zmm25, zmm27, zmm11, zmm15, zmm25, zmm27

    NTT_DIF4_SHOUP_MEM zmm0, zmm2,  rsi+4*rcx+0,  rsp+96+0,   zmm1,  zmm3,  rsi+4*rcx+0,  rsp+96+0,   zmm4,  zmm6,  rsi+4*rcx+8,  rsp+96+8,   zmm5,  zmm7,  rsi+4*rcx+8,  rsp+96+8
    NTT_DIF4_SHOUP_MEM zmm8, zmm10, rsi+4*rcx+16, rsp+96+16,  zmm9,  zmm11, rsi+4*rcx+16, rsp+96+16,  zmm12, zmm14, rsi+4*rcx+24, rsp+96+24,  zmm13, zmm15, rsi+4*rcx+24, rsp+96+24

    NTT_DIF4_SHOUP_MEM zmm0, zmm1,  rsi+8*rcx+0,  rsp+128+0,  zmm2,  zmm3,  rsi+8*rcx+8,  rsp+128+8,  zmm4,  zmm5,  rsi+8*rcx+16, rsp+128+16, zmm6,  zmm7,  rsi+8*rcx+24, rsp+128+24
    NTT_DIF4_SHOUP_MEM zmm8, zmm9,  rsi+8*rcx+32, rsp+128+32, zmm10, zmm11, rsi+8*rcx+40, rsp+128+40, zmm12, zmm13, rsi+8*rcx+48, rsp+128+48, zmm14, zmm15, rsi+8*rcx+56, rsp+128+56

    vmovupd [r9],         zmm0
    vmovupd [r9 + rbx],   zmm1
    vmovupd [r9 + 2*rbx], zmm2
    vmovupd [r9 + rax],   zmm3
    lea  r11, [r9 + 4*rbx]
    lea  r8,  [r9 + 8*rbx]
    vmovupd [r11],         zmm4
    vmovupd [r11 + rbx],   zmm5
    vmovupd [r11 + 2*rbx], zmm6
    vmovupd [r11 + rax],   zmm7
    vmovupd [r8],          zmm8
    vmovupd [r8 + rbx],    zmm9
    vmovupd [r8 + 2*rbx],  zmm10
    vmovupd [r8 + rax],    zmm11
    lea  r11, [r8 + 4*rbx]
    vmovupd [r11],         zmm12
    vmovupd [r11 + rbx],   zmm13
    vmovupd [r11 + 2*rbx], zmm14
    vmovupd [r11 + rax],   zmm15

    lea  r9, [r9 + 64]
    sub  r10, 8
    jnz  .Lnttfwd_r16_vec

.Lnttfwd_r16_blk_next:
    mov  r8, [rsp + 48]
    inc  r8
    cmp  r8, r12
    jb   .Lnttfwd_r16_block

    shl  r12, 4
    shr  r13, 4
    sub  r15, 4
    jmp  .Lnttfwd_r16_check

.macro NTT_FWD_BOT4_STAGES
    vbroadcastsd zmm24, [rsi + 8*rax + 0]
    vbroadcastsd zmm25, [rsi + 8*rax + 8]
    vbroadcastsd zmm26, [rsi + 8*rax + 16]
    vbroadcastsd zmm27, [rsi + 8*rax + 24]
    NTT_PREP_WP4 zmm24, zmm25, zmm26, zmm27

    add  rax, rax
    vbroadcastf64x2 zmm8,  [rsi + 8*rax + 0]
    vbroadcastf64x2 zmm9,  [rsi + 8*rax + 16]
    vbroadcastf64x2 zmm10, [rsi + 8*rax + 32]
    vbroadcastf64x2 zmm11, [rsi + 8*rax + 48]
    vshufpd zmm8,  zmm8,  zmm8,  0xF0
    vshufpd zmm9,  zmm9,  zmm9,  0xF0
    vshufpd zmm10, zmm10, zmm10, 0xF0
    vshufpd zmm11, zmm11, zmm11, 0xF0

    NTT_DIF4_SHOUP zmm0, zmm1, zmm24, zmm20, zmm2, zmm3, zmm25, zmm21, zmm4, zmm5, zmm26, zmm22, zmm6, zmm7, zmm27, zmm23

    NTT_PREP_WP4 zmm8, zmm9, zmm10, zmm11
    vshuff64x2 zmm24, zmm0, zmm1, 0x44
    vshuff64x2 zmm1,  zmm0, zmm1, 0xEE
    vshuff64x2 zmm25, zmm2, zmm3, 0x44
    vshuff64x2 zmm3,  zmm2, zmm3, 0xEE
    vshuff64x2 zmm26, zmm4, zmm5, 0x44
    vshuff64x2 zmm5,  zmm4, zmm5, 0xEE
    vshuff64x2 zmm27, zmm6, zmm7, 0x44
    vshuff64x2 zmm7,  zmm6, zmm7, 0xEE

    add  rax, rax
    vbroadcastf64x4 zmm0, [rsi + 8*rax + 0]
    vbroadcastf64x4 zmm2, [rsi + 8*rax + 32]
    vbroadcastf64x4 zmm4, [rsi + 8*rax + 64]
    vbroadcastf64x4 zmm6, [rsi + 8*rax + 96]
    vshufpd zmm0, zmm0, zmm0, 0xF0
    vshufpd zmm2, zmm2, zmm2, 0xF0
    vshufpd zmm4, zmm4, zmm4, 0xF0
    vshufpd zmm6, zmm6, zmm6, 0xF0

    NTT_DIF4_SHOUP zmm24, zmm1, zmm8, zmm20, zmm25, zmm3, zmm9, zmm21, zmm26, zmm5, zmm10, zmm22, zmm27, zmm7, zmm11, zmm23

    NTT_PREP_WP4 zmm0, zmm2, zmm4, zmm6
    vshuff64x2 zmm8,  zmm24, zmm1, 0x88
    vshuff64x2 zmm1,  zmm24, zmm1, 0xDD
    vshuff64x2 zmm9,  zmm25, zmm3, 0x88
    vshuff64x2 zmm3,  zmm25, zmm3, 0xDD
    vshuff64x2 zmm10, zmm26, zmm5, 0x88
    vshuff64x2 zmm5,  zmm26, zmm5, 0xDD
    vshuff64x2 zmm11, zmm27, zmm7, 0x88
    vshuff64x2 zmm7,  zmm27, zmm7, 0xDD

    add  rax, rax
    vmovupd    zmm24, [rsi + 8*rax + 0]
    vmovupd    zmm25, [rsi + 8*rax + 64]
    vmovupd    zmm26, [rsi + 8*rax + 128]
    vmovupd    zmm27, [rsi + 8*rax + 192]
    vshuff64x2 zmm24, zmm24, zmm24, 0xD8
    vshuff64x2 zmm25, zmm25, zmm25, 0xD8
    vshuff64x2 zmm26, zmm26, zmm26, 0xD8
    vshuff64x2 zmm27, zmm27, zmm27, 0xD8

    NTT_DIF4_SHOUP zmm8, zmm1, zmm0, zmm20, zmm9, zmm3, zmm2, zmm21, zmm10, zmm5, zmm4, zmm22, zmm11, zmm7, zmm6, zmm23

    NTT_PREP_WP4 zmm24, zmm25, zmm26, zmm27
    vunpcklpd zmm0, zmm8,  zmm1
    vunpckhpd zmm1, zmm8,  zmm1
    vunpcklpd zmm2, zmm9,  zmm3
    vunpckhpd zmm3, zmm9,  zmm3
    vunpcklpd zmm4, zmm10, zmm5
    vunpckhpd zmm5, zmm10, zmm5
    vunpcklpd zmm6, zmm11, zmm7
    vunpckhpd zmm7, zmm11, zmm7
    NTT_DIF4_SHOUP zmm0, zmm1, zmm24, zmm20, zmm2, zmm3, zmm25, zmm21, zmm4, zmm5, zmm26, zmm22, zmm6, zmm7, zmm27, zmm23
.endm

// Permutes 64 elements of `pmul_b` from natural memory order into `(even, odd)` register order
// using `zmm12/zmm13 = .Lconst_idx_bot_inv_lo/hi`, and multiplies `zmm0..zmm7` (in [-0.501p, 0.501p])
// directly into `(zmm0, zmm8, zmm2, zmm9, zmm4, zmm10, zmm6, zmm11)` in [-0.501p, 0.501p] with 0 masks!
.macro ZMM_PMUL8_FUSED_INV_ORDER PB_BASE, PB_OFF
    cmp          r11, rdi
    jne          1f
    vmovapd      zmm16, zmm0
    vmovapd      zmm8,  zmm1
    vmovapd      zmm18, zmm2
    vmovapd      zmm9,  zmm3
    vmovapd      zmm20, zmm4
    vmovapd      zmm10, zmm5
    vmovapd      zmm22, zmm6
    vmovapd      zmm11, zmm7
    jmp          2f
1:
    vmovupd      zmm16, [\PB_BASE + \PB_OFF + 0]
    vmovupd      zmm17, [\PB_BASE + \PB_OFF + 64]
    vmovupd      zmm18, [\PB_BASE + \PB_OFF + 128]
    vmovupd      zmm19, [\PB_BASE + \PB_OFF + 192]
    vmovupd      zmm20, [\PB_BASE + \PB_OFF + 256]
    vmovupd      zmm21, [\PB_BASE + \PB_OFF + 320]
    vmovupd      zmm22, [\PB_BASE + \PB_OFF + 384]
    vmovupd      zmm23, [\PB_BASE + \PB_OFF + 448]

    vmovapd      zmm8,  zmm16
    vpermt2pd    zmm16, zmm12, zmm17
    vpermt2pd    zmm8,  zmm13, zmm17
    vmovapd      zmm9,  zmm18
    vpermt2pd    zmm18, zmm12, zmm19
    vpermt2pd    zmm9,  zmm13, zmm19
    vmovapd      zmm10, zmm20
    vpermt2pd    zmm20, zmm12, zmm21
    vpermt2pd    zmm10, zmm13, zmm21
    vmovapd      zmm11, zmm22
    vpermt2pd    zmm22, zmm12, zmm23
    vpermt2pd    zmm11, zmm13, zmm23
2:
    vmulpd       zmm14, zmm0, zmm16
    vmulpd       zmm17, zmm1, zmm8
    vmulpd       zmm15, zmm2, zmm18
    vmulpd       zmm19, zmm3, zmm9
    vmulpd       zmm24, zmm4, zmm20
    vmulpd       zmm21, zmm5, zmm10
    vmulpd       zmm25, zmm6, zmm22
    vmulpd       zmm23, zmm7, zmm11

    vfmsub213pd  zmm0,  zmm16, zmm14
    vfmsub213pd  zmm8,  zmm1,  zmm17
    vfmsub213pd  zmm2,  zmm18, zmm15
    vfmsub213pd  zmm9,  zmm3,  zmm19
    vfmsub213pd  zmm4,  zmm20, zmm24
    vfmsub213pd  zmm10, zmm5,  zmm21
    vfmsub213pd  zmm6,  zmm22, zmm25
    vfmsub213pd  zmm11, zmm7,  zmm23

    vmulpd       zmm16, zmm14, zmm30
    vmulpd       zmm1,  zmm17, zmm30
    vmulpd       zmm18, zmm15, zmm30
    vmulpd       zmm3,  zmm19, zmm30
    vmulpd       zmm20, zmm24, zmm30
    vmulpd       zmm5,  zmm21, zmm30
    vmulpd       zmm22, zmm25, zmm30
    vmulpd       zmm7,  zmm23, zmm30

    vrndscalepd  zmm16, zmm16, 8
    vrndscalepd  zmm1,  zmm1,  8
    vrndscalepd  zmm18, zmm18, 8
    vrndscalepd  zmm3,  zmm3,  8
    vrndscalepd  zmm20, zmm20, 8
    vrndscalepd  zmm5,  zmm5,  8
    vrndscalepd  zmm22, zmm22, 8
    vrndscalepd  zmm7,  zmm7,  8

    vfnmadd231pd zmm14, zmm16, zmm29
    vfnmadd231pd zmm17, zmm1,  zmm29
    vfnmadd231pd zmm15, zmm18, zmm29
    vfnmadd231pd zmm19, zmm3,  zmm29
    vfnmadd231pd zmm24, zmm20, zmm29
    vfnmadd231pd zmm21, zmm5,  zmm29
    vfnmadd231pd zmm25, zmm22, zmm29
    vfnmadd231pd zmm23, zmm7,  zmm29

    vaddpd       zmm0,  zmm14, zmm0
    vaddpd       zmm8,  zmm17, zmm8
    vaddpd       zmm2,  zmm15, zmm2
    vaddpd       zmm9,  zmm19, zmm9
    vaddpd       zmm4,  zmm24, zmm4
    vaddpd       zmm10, zmm21, zmm10
    vaddpd       zmm6,  zmm25, zmm6
    vaddpd       zmm11, zmm23, zmm11
.endm

// In-register DIT stages m = 1, 2, 4, 8 consuming `(zmm0, zmm8, zmm2, zmm9, zmm4, zmm10, zmm6, zmm11)`
// with `inv_tw` in `\TW_REG` and `rax` = `m = 1` twiddle index, producing `zmm0..zmm7`.
.macro NTT_INV_BOT4_FROM_REGS TW_REG
    vmovupd    zmm24, [\TW_REG + 8*rax + 0]
    vmovupd    zmm25, [\TW_REG + 8*rax + 64]
    vmovupd    zmm26, [\TW_REG + 8*rax + 128]
    vmovupd    zmm27, [\TW_REG + 8*rax + 192]
    vshuff64x2 zmm24, zmm24, zmm24, 0xD8
    vshuff64x2 zmm25, zmm25, zmm25, 0xD8
    vshuff64x2 zmm26, zmm26, zmm26, 0xD8
    vshuff64x2 zmm27, zmm27, zmm27, 0xD8
    NTT_PREP_WP4 zmm24, zmm25, zmm26, zmm27

    shr  rax, 1
    vbroadcastf64x4 zmm1, [\TW_REG + 8*rax + 0]
    vbroadcastf64x4 zmm3, [\TW_REG + 8*rax + 32]
    vbroadcastf64x4 zmm5, [\TW_REG + 8*rax + 64]
    vbroadcastf64x4 zmm7, [\TW_REG + 8*rax + 96]
    vshufpd zmm1, zmm1, zmm1, 0xF0
    vshufpd zmm3, zmm3, zmm3, 0xF0
    vshufpd zmm5, zmm5, zmm5, 0xF0
    vshufpd zmm7, zmm7, zmm7, 0xF0

    NTT_DIT4_SHOUP zmm0, zmm8, zmm24, zmm20, zmm2, zmm9, zmm25, zmm21, zmm4, zmm10, zmm26, zmm22, zmm6, zmm11, zmm27, zmm23

    NTT_PREP_WP4 zmm1, zmm3, zmm5, zmm7
    vunpcklpd zmm24, zmm0, zmm8
    vunpckhpd zmm8,  zmm0, zmm8
    vunpcklpd zmm25, zmm2, zmm9
    vunpckhpd zmm9,  zmm2, zmm9
    vunpcklpd zmm26, zmm4, zmm10
    vunpckhpd zmm10, zmm4, zmm10
    vunpcklpd zmm27, zmm6, zmm11
    vunpckhpd zmm11, zmm6, zmm11

    shr  rax, 1
    vbroadcastf64x2 zmm0, [\TW_REG + 8*rax + 0]
    vbroadcastf64x2 zmm2, [\TW_REG + 8*rax + 16]
    vbroadcastf64x2 zmm4, [\TW_REG + 8*rax + 32]
    vbroadcastf64x2 zmm6, [\TW_REG + 8*rax + 48]
    vshufpd zmm0, zmm0, zmm0, 0xCC
    vshufpd zmm2, zmm2, zmm2, 0xCC
    vshufpd zmm4, zmm4, zmm4, 0xCC
    vshufpd zmm6, zmm6, zmm6, 0xCC

    NTT_DIT4_SHOUP zmm24, zmm8, zmm1, zmm20, zmm25, zmm9, zmm3, zmm21, zmm26, zmm10, zmm5, zmm22, zmm27, zmm11, zmm7, zmm23
    ZMM_RED4_SIGNED zmm24, zmm25, zmm26, zmm27

    NTT_PREP_WP4 zmm0, zmm2, zmm4, zmm6
    vshuff64x2 zmm1,  zmm24, zmm8,  0x44
    vshuff64x2 zmm8,  zmm24, zmm8,  0xEE
    vshuff64x2 zmm3,  zmm25, zmm9,  0x44
    vshuff64x2 zmm9,  zmm25, zmm9,  0xEE
    vshuff64x2 zmm5,  zmm26, zmm10, 0x44
    vshuff64x2 zmm10, zmm26, zmm10, 0xEE
    vshuff64x2 zmm7,  zmm27, zmm11, 0x44
    vshuff64x2 zmm11, zmm27, zmm11, 0xEE

    shr  rax, 1
    vbroadcastsd zmm24, [\TW_REG + 8*rax + 0]
    vbroadcastsd zmm25, [\TW_REG + 8*rax + 8]
    vbroadcastsd zmm26, [\TW_REG + 8*rax + 16]
    vbroadcastsd zmm27, [\TW_REG + 8*rax + 24]

    NTT_DIT4_SHOUP zmm1, zmm8, zmm0, zmm20, zmm3, zmm9, zmm2, zmm21, zmm5, zmm10, zmm4, zmm22, zmm7, zmm11, zmm6, zmm23

    NTT_PREP_WP4 zmm24, zmm25, zmm26, zmm27
    vshuff64x2 zmm0, zmm1, zmm8,  0x88
    vshuff64x2 zmm1, zmm1, zmm8,  0xDD
    vshuff64x2 zmm2, zmm3, zmm9,  0x88
    vshuff64x2 zmm3, zmm3, zmm9,  0xDD
    vshuff64x2 zmm4, zmm5, zmm10, 0x88
    vshuff64x2 zmm5, zmm5, zmm10, 0xDD
    vshuff64x2 zmm6, zmm7, zmm11, 0x88
    vshuff64x2 zmm7, zmm7, zmm11, 0xDD
    NTT_DIT4_SHOUP zmm0, zmm1, zmm24, zmm20, zmm2, zmm3, zmm25, zmm21, zmm4, zmm5, zmm26, zmm22, zmm6, zmm7, zmm27, zmm23
    ZMM_RED4_SIGNED zmm0, zmm2, zmm4, zmm6
.endm

.macro NTT_FWD_BOT4_HALF OUT_OFF
    NTT_FWD_BOT4_STAGES

    vmovapd   zmm8,  zmm0
    vpermt2pd zmm0,  zmm12, zmm1
    vpermt2pd zmm8,  zmm13, zmm1
    vmovapd   zmm9,  zmm2
    vpermt2pd zmm2,  zmm12, zmm3
    vpermt2pd zmm9,  zmm13, zmm3
    vmovapd   zmm10, zmm4
    vpermt2pd zmm4,  zmm12, zmm5
    vpermt2pd zmm10, zmm13, zmm5
    vmovapd   zmm11, zmm6
    vpermt2pd zmm6,  zmm12, zmm7
    vpermt2pd zmm11, zmm13, zmm7

    ZMM_CANON4 zmm0, zmm8, zmm2, zmm9
    ZMM_CANON4 zmm4, zmm10, zmm6, zmm11

    vmovupd [r10 + \OUT_OFF + 0],   zmm0
    vmovupd [r10 + \OUT_OFF + 64],  zmm8
    vmovupd [r10 + \OUT_OFF + 128], zmm2
    vmovupd [r10 + \OUT_OFF + 192], zmm9
    vmovupd [r10 + \OUT_OFF + 256], zmm4
    vmovupd [r10 + \OUT_OFF + 320], zmm10
    vmovupd [r10 + \OUT_OFF + 384], zmm6
    vmovupd [r10 + \OUT_OFF + 448], zmm11
.endm

    // 2. Remaining 0..3 stages with m >= 16 inside L1d: in-register Radix-128 (r15==3 -> 7 stages!)
    //    or Radix-64 (r15==2 -> 6 stages!) or Radix-2 + Radix-16 (r15==1).
.Lnttfwd_top_rem:
    cmp  r15, 3
    jne  .Lnttfwd_top_r4
    cmp  qword ptr [rsp + 1144], 0
    jne  .Lnttfwd_bot7_fused
    vpxorq zmm31, zmm31, zmm31
    mov  rdx, [rsp + 16]
    mov  r12, rdx
    shr  r12, 7                         // b64_local = sub_n / 128 >= 1
    mov  r13, [rsp + 40]
    imul r13, r12                       // tw_b64_base = tw_root * b64_local
    xor  r8d, r8d                       // b64 = 0 .. r12 - 1
.p2align 6
.Lnttfwd_bot7_loop:
    mov  rax, r8
    shl  rax, 10                        // b64 * 1024 bytes
    lea  r10, [rdi + rax]
    lea  rcx, [r13 + r8]
    shl  rcx, 3                         // 8 * k64

    vmovupd zmm0,  [r10 + 0]
    vmovupd zmm1,  [r10 + 64]
    vmovupd zmm2,  [r10 + 128]
    vmovupd zmm3,  [r10 + 192]
    vmovupd zmm4,  [r10 + 256]
    vmovupd zmm5,  [r10 + 320]
    vmovupd zmm6,  [r10 + 384]
    vmovupd zmm7,  [r10 + 448]
    vmovupd zmm8,  [r10 + 512]
    vmovupd zmm9,  [r10 + 576]
    vmovupd zmm10, [r10 + 640]
    vmovupd zmm11, [r10 + 704]
    vmovupd zmm12, [r10 + 768]
    vmovupd zmm13, [r10 + 832]
    vmovupd zmm14, [r10 + 896]
    vmovupd zmm15, [r10 + 960]

    vbroadcastsd zmm24, [rsi + rcx]
    vmulpd       zmm27, zmm24, zmm30
    NTT_DIF4_SHOUP zmm0, zmm8,  zmm24, zmm27, zmm1, zmm9,  zmm24, zmm27, zmm2, zmm10, zmm24, zmm27, zmm3, zmm11, zmm24, zmm27
    NTT_DIF4_SHOUP zmm4, zmm12, zmm24, zmm27, zmm5, zmm13, zmm24, zmm27, zmm6, zmm14, zmm24, zmm27, zmm7, zmm15, zmm24, zmm27

    vbroadcastsd zmm24, [rsi + 2*rcx + 0]
    vbroadcastsd zmm25, [rsi + 2*rcx + 8]
    vmulpd       zmm26, zmm24, zmm30
    vmulpd       zmm27, zmm25, zmm30
    NTT_DIF4_SHOUP zmm0, zmm4,  zmm24, zmm26, zmm1, zmm5,  zmm24, zmm26, zmm2, zmm6,  zmm24, zmm26, zmm3, zmm7,  zmm24, zmm26
    NTT_DIF4_SHOUP zmm8, zmm12, zmm25, zmm27, zmm9, zmm13, zmm25, zmm27, zmm10, zmm14, zmm25, zmm27, zmm11, zmm15, zmm25, zmm27

    vbroadcastsd zmm24, [rsi + 4*rcx + 0]
    vbroadcastsd zmm25, [rsi + 4*rcx + 8]
    vmulpd       zmm26, zmm24, zmm30
    vmulpd       zmm27, zmm25, zmm30
    NTT_DIF4_SHOUP zmm0, zmm2,  zmm24, zmm26, zmm1, zmm3,  zmm24, zmm26, zmm4, zmm6,  zmm25, zmm27, zmm5, zmm7,  zmm25, zmm27
    vbroadcastsd zmm24, [rsi + 4*rcx + 16]
    vbroadcastsd zmm25, [rsi + 4*rcx + 24]
    vmulpd       zmm26, zmm24, zmm30
    vmulpd       zmm27, zmm25, zmm30
    NTT_DIF4_SHOUP zmm8, zmm10, zmm24, zmm26, zmm9, zmm11, zmm24, zmm26, zmm12, zmm14, zmm25, zmm27, zmm13, zmm15, zmm25, zmm27

    ZMM_RED4_SIGNED zmm0,  zmm1,  zmm2,  zmm3
    ZMM_RED4_SIGNED zmm4,  zmm5,  zmm6,  zmm7
    ZMM_RED4_SIGNED zmm8,  zmm9,  zmm10, zmm11
    ZMM_RED4_SIGNED zmm12, zmm13, zmm14, zmm15

    vmovapd   [rsp + 128], zmm8
    vmovapd   [rsp + 192], zmm9
    vmovapd   [rsp + 256], zmm10
    vmovapd   [rsp + 320], zmm11
    vmovapd   [rsp + 384], zmm12
    vmovapd   [rsp + 448], zmm13
    vmovdqa64 zmm12, [rip + .Lconst_idx_bot_fwd_lo]
    vmovdqa64 zmm13, [rip + .Lconst_idx_bot_fwd_hi]

    mov  rax, rcx                       // 8 * k64 (m = 8 element index for Half 0)
    NTT_FWD_BOT4_HALF 0

    vmovapd zmm0, [rsp + 128]
    vmovapd zmm1, [rsp + 192]
    vmovapd zmm2, [rsp + 256]
    vmovapd zmm3, [rsp + 320]
    vmovapd zmm4, [rsp + 384]
    vmovapd zmm5, [rsp + 448]
    vmovapd zmm6, zmm14
    vmovapd zmm7, zmm15
    lea  rax, [rcx + 4]                 // 8 * k64 + 4 (m = 8 element index for Half 1)
    NTT_FWD_BOT4_HALF 512

    inc  r8
    cmp  r8, r12
    jb   .Lnttfwd_bot7_loop
    jmp  .Lnttfwd_next_sub

.p2align 6
.Lntt_bot4_fused_core:
    NTT_FWD_BOT4_STAGES
    ZMM_RED4_SIGNED zmm0, zmm1, zmm2, zmm3
    ZMM_RED4_SIGNED zmm4, zmm5, zmm6, zmm7
    ZMM_PMUL8_FUSED_INV_ORDER r11, r15
    NTT_INV_BOT4_FROM_REGS r9
    ret

.Lnttfwd_bot7_fused:
    mov  rax, [rsp + 1008]
    mov  [rsp + 48], rax                // restore need_scale
    vbroadcastsd zmm28, [rsp + 1064]
    vpxorq zmm31, zmm31, zmm31
    mov  rdx, [rsp + 16]                // sub_n (128 or 2048)
    mov  r12, rdx
    shr  r12, 7                         // b64_local = sub_n / 128 >= 1
    mov  r13, [rsp + 40]
    imul r13, r12                       // tw_b64_base = tw_root * b64_local
    mov  r9,  [rsp + 1136]              // inv_tw
    mov  r11, [rsp + 1144]              // pmul_b
    mov  rax, rdi
    sub  rax, [rsp + 0]
    add  r11, rax                       // pb_sub
    xor  r8d, r8d                       // b64 = 0 .. r12 - 1

.p2align 6
.Lnttfwd_bot7_fused_loop:
    mov  r14, r8
    shl  r14, 10                        // b64 * 1024 bytes
    lea  r10, [rdi + r14]
    lea  rcx, [r13 + r8]
    shl  rcx, 3                         // 8 * k64

    vmovupd zmm0,  [r10 + 0]
    vmovupd zmm1,  [r10 + 64]
    vmovupd zmm2,  [r10 + 128]
    vmovupd zmm3,  [r10 + 192]
    vmovupd zmm4,  [r10 + 256]
    vmovupd zmm5,  [r10 + 320]
    vmovupd zmm6,  [r10 + 384]
    vmovupd zmm7,  [r10 + 448]
    vmovupd zmm8,  [r10 + 512]
    vmovupd zmm9,  [r10 + 576]
    vmovupd zmm10, [r10 + 640]
    vmovupd zmm11, [r10 + 704]
    vmovupd zmm12, [r10 + 768]
    vmovupd zmm13, [r10 + 832]
    vmovupd zmm14, [r10 + 896]
    vmovupd zmm15, [r10 + 960]

    vbroadcastsd zmm24, [rsi + rcx]
    vmulpd       zmm27, zmm24, zmm30
    NTT_DIF4_SHOUP zmm0, zmm8,  zmm24, zmm27, zmm1, zmm9,  zmm24, zmm27, zmm2, zmm10, zmm24, zmm27, zmm3, zmm11, zmm24, zmm27
    NTT_DIF4_SHOUP zmm4, zmm12, zmm24, zmm27, zmm5, zmm13, zmm24, zmm27, zmm6, zmm14, zmm24, zmm27, zmm7, zmm15, zmm24, zmm27

    vbroadcastsd zmm24, [rsi + 2*rcx + 0]
    vbroadcastsd zmm25, [rsi + 2*rcx + 8]
    vmulpd       zmm26, zmm24, zmm30
    vmulpd       zmm27, zmm25, zmm30
    NTT_DIF4_SHOUP zmm0, zmm4,  zmm24, zmm26, zmm1, zmm5,  zmm24, zmm26, zmm2, zmm6,  zmm24, zmm26, zmm3, zmm7,  zmm24, zmm26
    NTT_DIF4_SHOUP zmm8, zmm12, zmm25, zmm27, zmm9, zmm13, zmm25, zmm27, zmm10, zmm14, zmm25, zmm27, zmm11, zmm15, zmm25, zmm27

    vbroadcastsd zmm24, [rsi + 4*rcx + 0]
    vbroadcastsd zmm25, [rsi + 4*rcx + 8]
    vmulpd       zmm26, zmm24, zmm30
    vmulpd       zmm27, zmm25, zmm30
    NTT_DIF4_SHOUP zmm0, zmm2,  zmm24, zmm26, zmm1, zmm3,  zmm24, zmm26, zmm4, zmm6,  zmm25, zmm27, zmm5, zmm7,  zmm25, zmm27
    vbroadcastsd zmm24, [rsi + 4*rcx + 16]
    vbroadcastsd zmm25, [rsi + 4*rcx + 24]
    vmulpd       zmm26, zmm24, zmm30
    vmulpd       zmm27, zmm25, zmm30
    NTT_DIF4_SHOUP zmm8, zmm10, zmm24, zmm26, zmm9, zmm11, zmm24, zmm26, zmm12, zmm14, zmm25, zmm27, zmm13, zmm15, zmm25, zmm27

    ZMM_RED4_SIGNED zmm0,  zmm1,  zmm2,  zmm3
    ZMM_RED4_SIGNED zmm4,  zmm5,  zmm6,  zmm7
    ZMM_RED4_SIGNED zmm8,  zmm9,  zmm10, zmm11
    ZMM_RED4_SIGNED zmm12, zmm13, zmm14, zmm15

    vmovapd   [rsp + 128], zmm8
    vmovapd   [rsp + 192], zmm9
    vmovapd   [rsp + 256], zmm10
    vmovapd   [rsp + 320], zmm11
    vmovapd   [rsp + 384], zmm12
    vmovapd   [rsp + 448], zmm13
    vmovapd   [rsp + 512], zmm14
    vmovapd   [rsp + 576], zmm15
    vmovdqa64 zmm12, [rip + .Lconst_idx_bot_inv_lo]
    vmovdqa64 zmm13, [rip + .Lconst_idx_bot_inv_hi]

    // Half 0: fwd m=8..1 -> signed pmul_b -> inv m=1..8 in registers!
    mov  rax, rcx                       // 8 * k64 -> ends at 64 * k64 -> back to 8 * k64
    mov  r15, r14
    call .Lntt_bot4_fused_core

    // Swap Half 0 inv output (zmm0..7) with Half 1 fwd input ([rsp + 128..576])!
    vmovapd zmm8,  [rsp + 128]
    vmovapd zmm9,  [rsp + 192]
    vmovapd zmm10, [rsp + 256]
    vmovapd zmm11, [rsp + 320]
    vmovapd [rsp + 128], zmm0
    vmovapd [rsp + 192], zmm1
    vmovapd [rsp + 256], zmm2
    vmovapd [rsp + 320], zmm3
    vmovapd zmm0,  zmm8
    vmovapd zmm1,  zmm9
    vmovapd zmm2,  zmm10
    vmovapd zmm3,  zmm11
    vmovapd zmm8,  [rsp + 384]
    vmovapd zmm9,  [rsp + 448]
    vmovapd zmm10, [rsp + 512]
    vmovapd zmm11, [rsp + 576]
    vmovapd [rsp + 384], zmm4
    vmovapd [rsp + 448], zmm5
    vmovapd [rsp + 512], zmm6
    vmovapd [rsp + 576], zmm7
    vmovapd zmm4,  zmm8
    vmovapd zmm5,  zmm9
    vmovapd zmm6,  zmm10
    vmovapd zmm7,  zmm11

    // Half 1: fwd m=8..1 -> signed pmul_b -> inv m=1..8 in registers!
    lea  rax, [rcx + 4]                 // 8 * k64 + 4
    lea  r15, [r14 + 512]
    call .Lntt_bot4_fused_core

    vmovapd zmm8,  zmm0
    vmovapd zmm9,  zmm1
    vmovapd zmm10, zmm2
    vmovapd zmm11, zmm3
    vmovapd zmm12, zmm4
    vmovapd zmm13, zmm5
    vmovapd zmm14, zmm6
    vmovapd zmm15, zmm7
    vmovapd zmm0,  [rsp + 128]
    vmovapd zmm1,  [rsp + 192]
    vmovapd zmm2,  [rsp + 256]
    vmovapd zmm3,  [rsp + 320]
    vmovapd zmm4,  [rsp + 384]
    vmovapd zmm5,  [rsp + 448]
    vmovapd zmm6,  [rsp + 512]
    vmovapd zmm7,  [rsp + 576]

    vbroadcastsd zmm24, [r9 + 4*rcx + 0]
    vbroadcastsd zmm25, [r9 + 4*rcx + 8]
    vmulpd       zmm26, zmm24, zmm30
    vmulpd       zmm27, zmm25, zmm30
    NTT_DIT4_SHOUP zmm0, zmm2,  zmm24, zmm26, zmm1, zmm3,  zmm24, zmm26, zmm4, zmm6,  zmm25, zmm27, zmm5, zmm7,  zmm25, zmm27
    vbroadcastsd zmm24, [r9 + 4*rcx + 16]
    vbroadcastsd zmm25, [r9 + 4*rcx + 24]
    vmulpd       zmm26, zmm24, zmm30
    vmulpd       zmm27, zmm25, zmm30
    NTT_DIT4_SHOUP zmm8, zmm10, zmm24, zmm26, zmm9, zmm11, zmm24, zmm26, zmm12, zmm14, zmm25, zmm27, zmm13, zmm15, zmm25, zmm27

    vbroadcastsd zmm24, [r9 + 2*rcx + 0]
    vbroadcastsd zmm25, [r9 + 2*rcx + 8]
    vmulpd       zmm26, zmm24, zmm30
    vmulpd       zmm27, zmm25, zmm30
    NTT_DIT4_SHOUP zmm0, zmm4,  zmm24, zmm26, zmm1, zmm5,  zmm24, zmm26, zmm2, zmm6,  zmm24, zmm26, zmm3, zmm7,  zmm24, zmm26
    NTT_DIT4_SHOUP zmm8, zmm12, zmm25, zmm27, zmm9, zmm13, zmm25, zmm27, zmm10, zmm14, zmm25, zmm27, zmm11, zmm15, zmm25, zmm27

    vbroadcastsd zmm24, [r9 + rcx]
    vmulpd       zmm26, zmm24, zmm30
    NTT_DIT4_SHOUP zmm0, zmm8,  zmm24, zmm26, zmm1, zmm9,  zmm24, zmm26, zmm2, zmm10, zmm24, zmm26, zmm3, zmm11, zmm24, zmm26
    NTT_DIT4_SHOUP zmm4, zmm12, zmm24, zmm26, zmm5, zmm13, zmm24, zmm26, zmm6, zmm14, zmm24, zmm26, zmm7, zmm15, zmm24, zmm26

    cmp  rdx, 128
    jne  .Lnttfwd_bot7_fused_noscl
    cmp  qword ptr [rsp + 24], 1
    ja   .Lnttfwd_bot7_fused_noscl
    cmp  qword ptr [rsp + 48], 0
    je   .Lnttinv_bot7_n128_canon
    ZMM_RED4_SIGNED  zmm0,  zmm1,  zmm2,  zmm3
    ZMM_RED4_SIGNED  zmm4,  zmm5,  zmm6,  zmm7
    ZMM_SCALE4_SHOUP zmm0,  zmm1,  zmm2,  zmm3,  qword ptr [rsp + 1120]{1to8}
    ZMM_SCALE4_SHOUP zmm4,  zmm5,  zmm6,  zmm7,  qword ptr [rsp + 1120]{1to8}
    ZMM_SCALE4_SHOUP zmm8,  zmm9,  zmm10, zmm11, qword ptr [rsp + 1120]{1to8}
    ZMM_SCALE4_SHOUP zmm12, zmm13, zmm14, zmm15, qword ptr [rsp + 1120]{1to8}
    vmovupd [r10 + 0],   zmm0
    vmovupd [r10 + 64],  zmm1
    vmovupd [r10 + 128], zmm2
    vmovupd [r10 + 192], zmm3
    vmovupd [r10 + 256], zmm4
    vmovupd [r10 + 320], zmm5
    vmovupd [r10 + 384], zmm6
    vmovupd [r10 + 448], zmm7
    vmovupd [r10 + 512], zmm8
    vmovupd [r10 + 576], zmm9
    vmovupd [r10 + 640], zmm10
    vmovupd [r10 + 704], zmm11
    vmovupd [r10 + 768], zmm12
    vmovupd [r10 + 832], zmm13
    vmovupd [r10 + 896], zmm14
    vmovupd [r10 + 960], zmm15
    jmp  .Lnttinv_done

.Lnttfwd_bot7_fused_noscl:
    ZMM_RED4_SIGNED zmm0, zmm1, zmm2, zmm3
    ZMM_RED4_SIGNED zmm4, zmm5, zmm6, zmm7
    vmovupd [r10 + 0],   zmm0
    vmovupd [r10 + 64],  zmm1
    vmovupd [r10 + 128], zmm2
    vmovupd [r10 + 192], zmm3
    vmovupd [r10 + 256], zmm4
    vmovupd [r10 + 320], zmm5
    vmovupd [r10 + 384], zmm6
    vmovupd [r10 + 448], zmm7
    vmovupd [r10 + 512], zmm8
    vmovupd [r10 + 576], zmm9
    vmovupd [r10 + 640], zmm10
    vmovupd [r10 + 704], zmm11
    vmovupd [r10 + 768], zmm12
    vmovupd [r10 + 832], zmm13
    vmovupd [r10 + 896], zmm14
    vmovupd [r10 + 960], zmm15

    inc  r8
    cmp  r8, r12
    jb   .Lnttfwd_bot7_fused_loop

    mov  rsi, r9
    tzcnt r15, rdx
    sub  r15, 7
    jz   .Lnttinv_next_sub
    mov  r13, 128
    mov  r12, rdx
    shr  r12, 8
    jmp  .Lnttinv_r16_check

.Lnttfwd_top_r4:
    cmp  r15, 2
    je   .Lnttfwd_bottom_r64
    jmp  .Lnttfwd_top_r2
    mov  r14, r13
    shr  r14, 1                         // s = m / 2 >= 16 (multiple of 16)
    mov  rbx, r14
    shl  rbx, 3                         // s_bytes
    xor  r8d, r8d
.Lnttfwd_r4_block:
    mov  rax, r8
    shl  rax, 2
    imul rax, rbx
    lea  r9,  [rdi + rax]
    mov  r10, r14
    mov  rax, [rsp + 40]
    imul rax, r12
    add  rax, r8
    vbroadcastsd zmm24, [rsi + 8*rax]
    add  rax, rax
    vbroadcastsd zmm25, [rsi + 8*rax + 0]
    vbroadcastsd zmm26, [rsi + 8*rax + 8]
    vmulpd       zmm27, zmm24, zmm30
    vmulpd       zmm28, zmm25, zmm30
    vmulpd       zmm31, zmm26, zmm30
    cmp  r10, 32
    jb   .Lnttfwd_r4_vec
.p2align 4
.Lnttfwd_r4_vec32:
    lea  r11, [r9 + 2*rbx]
    vmovupd zmm0,  [r9 + 0]
    vmovupd zmm1,  [r9 + 64]
    vmovupd zmm2,  [r9 + rbx + 0]
    vmovupd zmm3,  [r9 + rbx + 64]
    vmovupd zmm4,  [r11 + 0]
    vmovupd zmm5,  [r11 + 64]
    vmovupd zmm6,  [r11 + rbx + 0]
    vmovupd zmm7,  [r11 + rbx + 64]
    vmovupd zmm8,  [r9 + 128]
    vmovupd zmm9,  [r9 + 192]
    vmovupd zmm10, [r9 + rbx + 128]
    vmovupd zmm11, [r9 + rbx + 192]
    vmovupd zmm12, [r11 + 128]
    vmovupd zmm13, [r11 + 192]
    vmovupd zmm14, [r11 + rbx + 128]
    vmovupd zmm15, [r11 + rbx + 192]
    NTT_DIF4_SHOUP zmm0, zmm4,  zmm24, zmm27, zmm1, zmm5,  zmm24, zmm27, zmm2,  zmm6,  zmm24, zmm27, zmm3,  zmm7,  zmm24, zmm27
    NTT_DIF4_SHOUP zmm8, zmm12, zmm24, zmm27, zmm9, zmm13, zmm24, zmm27, zmm10, zmm14, zmm24, zmm27, zmm11, zmm15, zmm24, zmm27
    NTT_DIF4_SHOUP zmm0, zmm2,  zmm25, zmm28, zmm1, zmm3,  zmm25, zmm28, zmm4,  zmm6,  zmm26, zmm31, zmm5,  zmm7,  zmm26, zmm31
    NTT_DIF4_SHOUP zmm8, zmm10, zmm25, zmm28, zmm9, zmm11, zmm25, zmm28, zmm12, zmm14, zmm26, zmm31, zmm13, zmm15, zmm26, zmm31
    vmovupd [r9 + 0],          zmm0
    vmovupd [r9 + 64],         zmm1
    vmovupd [r9 + rbx + 0],    zmm2
    vmovupd [r9 + rbx + 64],   zmm3
    vmovupd [r11 + 0],         zmm4
    vmovupd [r11 + 64],        zmm5
    vmovupd [r11 + rbx + 0],   zmm6
    vmovupd [r11 + rbx + 64],  zmm7
    vmovupd [r9 + 128],        zmm8
    vmovupd [r9 + 192],        zmm9
    vmovupd [r9 + rbx + 128],  zmm10
    vmovupd [r9 + rbx + 192],  zmm11
    vmovupd [r11 + 128],       zmm12
    vmovupd [r11 + 192],       zmm13
    vmovupd [r11 + rbx + 128], zmm14
    vmovupd [r11 + rbx + 192], zmm15
    lea  r9, [r9 + 256]
    sub  r10, 32
    jnz  .Lnttfwd_r4_vec32
    jmp  .Lnttfwd_r4_next

.p2align 4
.Lnttfwd_r4_vec:
    lea  r11, [r9 + 2*rbx]
    vmovupd zmm0, [r9 + 0]
    vmovupd zmm1, [r9 + 64]
    vmovupd zmm2, [r9 + rbx + 0]
    vmovupd zmm3, [r9 + rbx + 64]
    vmovupd zmm4, [r11 + 0]
    vmovupd zmm5, [r11 + 64]
    vmovupd zmm6, [r11 + rbx + 0]
    vmovupd zmm7, [r11 + rbx + 64]
    NTT_DIF4_SHOUP zmm0, zmm4, zmm24, zmm27, zmm1, zmm5, zmm24, zmm27, zmm2, zmm6, zmm24, zmm27, zmm3, zmm7, zmm24, zmm27
    NTT_DIF4_SHOUP zmm0, zmm2, zmm25, zmm28, zmm1, zmm3, zmm25, zmm28, zmm4, zmm6, zmm26, zmm31, zmm5, zmm7, zmm26, zmm31
    vmovupd [r9 + 0],        zmm0
    vmovupd [r9 + 64],       zmm1
    vmovupd [r9 + rbx + 0],  zmm2
    vmovupd [r9 + rbx + 64], zmm3
    vmovupd [r11 + 0],       zmm4
    vmovupd [r11 + 64],      zmm5
    vmovupd [r11 + rbx + 0], zmm6
    vmovupd [r11 + rbx + 64], zmm7
    lea  r9, [r9 + 128]
    sub  r10, 16
    jnz  .Lnttfwd_r4_vec
.Lnttfwd_r4_next:
    inc  r8
    cmp  r8, r12
    jb   .Lnttfwd_r4_block
    shl  r12, 2
    shr  r13, 2
    sub  r15, 2

.Lnttfwd_top_r2:
    test r15, r15
    jz   .Lnttfwd_bottom_r16
    mov  rbx, r13
    shl  rbx, 3                         // m_bytes (m == 16 -> 128 B)
    xor  r8d, r8d
    cmp  r12, 2
    jb   .Lnttfwd_r2_block1
.p2align 4
.Lnttfwd_r2_block2:
    mov  rax, [rsp + 40]
    imul rax, r12
    add  rax, r8
    vbroadcastsd zmm24, [rsi + 8*rax + 0]
    vbroadcastsd zmm25, [rsi + 8*rax + 8]
    vmulpd       zmm26, zmm24, zmm30
    vmulpd       zmm27, zmm25, zmm30
    mov  rax, r8
    add  rax, rax
    imul rax, rbx
    lea  r9, [rdi + rax]
    vmovupd zmm0, [r9 + 0]
    vmovupd zmm1, [r9 + 64]
    vmovupd zmm2, [r9 + 128]
    vmovupd zmm3, [r9 + 192]
    vmovupd zmm4, [r9 + 256]
    vmovupd zmm5, [r9 + 320]
    vmovupd zmm6, [r9 + 384]
    vmovupd zmm7, [r9 + 448]
    NTT_DIF4_SHOUP zmm0, zmm2, zmm24, zmm26, zmm1, zmm3, zmm24, zmm26, zmm4, zmm6, zmm25, zmm27, zmm5, zmm7, zmm25, zmm27
    vmovupd [r9 + 0],   zmm0
    vmovupd [r9 + 64],  zmm1
    vmovupd [r9 + 128], zmm2
    vmovupd [r9 + 192], zmm3
    vmovupd [r9 + 256], zmm4
    vmovupd [r9 + 320], zmm5
    vmovupd [r9 + 384], zmm6
    vmovupd [r9 + 448], zmm7
    add  r8, 2
    cmp  r8, r12
    jb   .Lnttfwd_r2_block2
    jmp  .Lnttfwd_bottom_r16

.Lnttfwd_r2_block1:
    mov  rax, [rsp + 40]
    imul rax, r12
    add  rax, r8
    vbroadcastsd zmm24, [rsi + 8*rax]
    vmulpd       zmm26, zmm24, zmm30
    mov  rax, r8
    add  rax, rax
    imul rax, rbx
    lea  r9, [rdi + rax]
    vmovupd zmm0, [r9 + 0]
    vmovupd zmm1, [r9 + 64]
    vmovupd zmm2, [r9 + rbx + 0]
    vmovupd zmm3, [r9 + rbx + 64]
    NTT_DIF2_SHOUP zmm0, zmm2, zmm24, zmm26, zmm1, zmm3, zmm24, zmm26
    vmovupd [r9 + 0],  zmm0
    vmovupd [r9 + 64], zmm1
    vmovupd [r9 + rbx + 0],  zmm2
    vmovupd [r9 + rbx + 64], zmm3
    inc  r8
    cmp  r8, r12
    jb   .Lnttfwd_r2_block1
    jmp  .Lnttfwd_bottom_r16

    // 3a. In-register Radix-64 bottom pass covering stages m = 32, 16, 8, 4, 2, 1 inside L1d!
.Lnttfwd_bottom_r64:
    cmp  qword ptr [rsp + 1144], 0
    jne  .Lnttfwd_bot6_fused
    vpxorq zmm31, zmm31, zmm31
    mov  rdx, [rsp + 16]
    mov  r12, rdx
    shr  r12, 6                         // b32_local = sub_n / 64 >= 1
    mov  r13, [rsp + 40]
    imul r13, r12                       // tw_b32_base = tw_root * b32_local
    xor  r8d, r8d                       // b32 = 0 .. r12 - 1
    vmovdqa64 zmm12, [rip + .Lconst_idx_bot_fwd_lo]
    vmovdqa64 zmm13, [rip + .Lconst_idx_bot_fwd_hi]

.p2align 6
.Lnttfwd_bot6_loop:
    mov  rax, r8
    shl  rax, 9                         // b32 * 512 bytes
    lea  r10, [rdi + rax]

    // Stage m = 32 & m = 16 twiddles + WP in zmm8..10:
    lea  rax, [r13 + r8]
    vbroadcastsd zmm24, [rsi + 8*rax]
    vmulpd       zmm8,  zmm24, zmm30
    add  rax, rax
    vbroadcastsd zmm25, [rsi + 8*rax + 0]
    vbroadcastsd zmm26, [rsi + 8*rax + 8]
    vmulpd       zmm9,  zmm25, zmm30
    vmulpd       zmm10, zmm26, zmm30

    vmovupd zmm0, [r10 + 0]
    vmovupd zmm1, [r10 + 64]
    vmovupd zmm2, [r10 + 128]
    vmovupd zmm3, [r10 + 192]
    vmovupd zmm4, [r10 + 256]
    vmovupd zmm5, [r10 + 320]
    vmovupd zmm6, [r10 + 384]
    vmovupd zmm7, [r10 + 448]

    NTT_DIF4_SHOUP zmm0, zmm4, zmm24, zmm8, zmm1, zmm5, zmm24, zmm8, zmm2, zmm6, zmm24, zmm8, zmm3, zmm7, zmm24, zmm8
    NTT_DIF4_SHOUP zmm0, zmm2, zmm25, zmm9, zmm1, zmm3, zmm25, zmm9, zmm4, zmm6, zmm26, zmm10, zmm5, zmm7, zmm26, zmm10
    ZMM_RED4_SIGNED zmm0, zmm1, zmm2, zmm3
    ZMM_RED4_SIGNED zmm4, zmm5, zmm6, zmm7

    // Stage m = 8:
    add  rax, rax
    vbroadcastsd zmm24, [rsi + 8*rax + 0]
    vbroadcastsd zmm25, [rsi + 8*rax + 8]
    vbroadcastsd zmm26, [rsi + 8*rax + 16]
    vbroadcastsd zmm27, [rsi + 8*rax + 24]
    NTT_PREP_WP4 zmm24, zmm25, zmm26, zmm27

    add  rax, rax
    vbroadcastf64x2 zmm8,  [rsi + 8*rax + 0]
    vbroadcastf64x2 zmm9,  [rsi + 8*rax + 16]
    vbroadcastf64x2 zmm10, [rsi + 8*rax + 32]
    vbroadcastf64x2 zmm11, [rsi + 8*rax + 48]
    vshufpd zmm8,  zmm8,  zmm8,  0xF0
    vshufpd zmm9,  zmm9,  zmm9,  0xF0
    vshufpd zmm10, zmm10, zmm10, 0xF0
    vshufpd zmm11, zmm11, zmm11, 0xF0

    NTT_DIF4_SHOUP zmm0, zmm1, zmm24, zmm20, zmm2, zmm3, zmm25, zmm21, zmm4, zmm5, zmm26, zmm22, zmm6, zmm7, zmm27, zmm23

    // Stage m = 4:
    NTT_PREP_WP4 zmm8, zmm9, zmm10, zmm11
    vshuff64x2 zmm24, zmm0, zmm1, 0x44
    vshuff64x2 zmm1,  zmm0, zmm1, 0xEE
    vshuff64x2 zmm25, zmm2, zmm3, 0x44
    vshuff64x2 zmm3,  zmm2, zmm3, 0xEE
    vshuff64x2 zmm26, zmm4, zmm5, 0x44
    vshuff64x2 zmm5,  zmm4, zmm5, 0xEE
    vshuff64x2 zmm27, zmm6, zmm7, 0x44
    vshuff64x2 zmm7,  zmm6, zmm7, 0xEE

    add  rax, rax
    vbroadcastf64x4 zmm0, [rsi + 8*rax + 0]
    vbroadcastf64x4 zmm2, [rsi + 8*rax + 32]
    vbroadcastf64x4 zmm4, [rsi + 8*rax + 64]
    vbroadcastf64x4 zmm6, [rsi + 8*rax + 96]
    vshufpd zmm0, zmm0, zmm0, 0xF0
    vshufpd zmm2, zmm2, zmm2, 0xF0
    vshufpd zmm4, zmm4, zmm4, 0xF0
    vshufpd zmm6, zmm6, zmm6, 0xF0

    NTT_DIF4_SHOUP zmm24, zmm1, zmm8, zmm20, zmm25, zmm3, zmm9, zmm21, zmm26, zmm5, zmm10, zmm22, zmm27, zmm7, zmm11, zmm23

    // Stage m = 2:
    NTT_PREP_WP4 zmm0, zmm2, zmm4, zmm6
    vshuff64x2 zmm8,  zmm24, zmm1, 0x88
    vshuff64x2 zmm1,  zmm24, zmm1, 0xDD
    vshuff64x2 zmm9,  zmm25, zmm3, 0x88
    vshuff64x2 zmm3,  zmm25, zmm3, 0xDD
    vshuff64x2 zmm10, zmm26, zmm5, 0x88
    vshuff64x2 zmm5,  zmm26, zmm5, 0xDD
    vshuff64x2 zmm11, zmm27, zmm7, 0x88
    vshuff64x2 zmm7,  zmm27, zmm7, 0xDD

    add  rax, rax
    vmovupd    zmm24, [rsi + 8*rax + 0]
    vmovupd    zmm25, [rsi + 8*rax + 64]
    vmovupd    zmm26, [rsi + 8*rax + 128]
    vmovupd    zmm27, [rsi + 8*rax + 192]
    vshuff64x2 zmm24, zmm24, zmm24, 0xD8
    vshuff64x2 zmm25, zmm25, zmm25, 0xD8
    vshuff64x2 zmm26, zmm26, zmm26, 0xD8
    vshuff64x2 zmm27, zmm27, zmm27, 0xD8

    NTT_DIF4_SHOUP zmm8, zmm1, zmm0, zmm20, zmm9, zmm3, zmm2, zmm21, zmm10, zmm5, zmm4, zmm22, zmm11, zmm7, zmm6, zmm23

    // Stage m = 1:
    NTT_PREP_WP4 zmm24, zmm25, zmm26, zmm27
    vunpcklpd zmm0, zmm8,  zmm1
    vunpckhpd zmm1, zmm8,  zmm1
    vunpcklpd zmm2, zmm9,  zmm3
    vunpckhpd zmm3, zmm9,  zmm3
    vunpcklpd zmm4, zmm10, zmm5
    vunpckhpd zmm5, zmm10, zmm5
    vunpcklpd zmm6, zmm11, zmm7
    vunpckhpd zmm7, zmm11, zmm7
    NTT_DIF4_SHOUP zmm0, zmm1, zmm24, zmm20, zmm2, zmm3, zmm25, zmm21, zmm4, zmm5, zmm26, zmm22, zmm6, zmm7, zmm27, zmm23

    vmovapd   zmm8,  zmm0
    vpermt2pd zmm0,  zmm12, zmm1
    vpermt2pd zmm8,  zmm13, zmm1
    vmovapd   zmm9,  zmm2
    vpermt2pd zmm2,  zmm12, zmm3
    vpermt2pd zmm9,  zmm13, zmm3
    vmovapd   zmm10, zmm4
    vpermt2pd zmm4,  zmm12, zmm5
    vpermt2pd zmm10, zmm13, zmm5
    vmovapd   zmm11, zmm6
    vpermt2pd zmm6,  zmm12, zmm7
    vpermt2pd zmm11, zmm13, zmm7

    ZMM_CANON4 zmm0, zmm8, zmm2, zmm9
    ZMM_CANON4 zmm4, zmm10, zmm6, zmm11

    vmovupd [r10 + 0],   zmm0
    vmovupd [r10 + 64],  zmm8
    vmovupd [r10 + 128], zmm2
    vmovupd [r10 + 192], zmm9
    vmovupd [r10 + 256], zmm4
    vmovupd [r10 + 320], zmm10
    vmovupd [r10 + 384], zmm6
    vmovupd [r10 + 448], zmm11

    inc  r8
    cmp  r8, r12
    jb   .Lnttfwd_bot6_loop
    jmp  .Lnttfwd_next_sub

.Lnttfwd_bot6_fused:
    mov  rax, [rsp + 1008]
    mov  [rsp + 48], rax                // restore need_scale
    vbroadcastsd zmm28, [rsp + 1064]
    vpxorq zmm31, zmm31, zmm31
    mov  rdx, [rsp + 16]                // sub_n (64, 512, or 1024)
    mov  r12, rdx
    shr  r12, 6                         // b32_local = sub_n / 64 >= 1
    mov  r13, [rsp + 40]
    imul r13, r12                       // tw_b32_base = tw_root * b32_local
    mov  r9,  [rsp + 1136]              // inv_tw
    mov  r11, [rsp + 1144]              // pmul_b
    mov  rax, rdi
    sub  rax, [rsp + 0]
    add  r11, rax                       // pb_sub
    xor  r8d, r8d                       // b32 = 0 .. r12 - 1
    vmovdqa64 zmm12, [rip + .Lconst_idx_bot_inv_lo]
    vmovdqa64 zmm13, [rip + .Lconst_idx_bot_inv_hi]

.p2align 6
.Lnttfwd_bot6_fused_loop:
    mov  rcx, r8
    shl  rcx, 9                         // b32 * 512 bytes
    lea  r10, [rdi + rcx]

    lea  rax, [r13 + r8]
    vbroadcastsd zmm24, [rsi + 8*rax]
    vmulpd       zmm8,  zmm24, zmm30
    add  rax, rax
    vbroadcastsd zmm25, [rsi + 8*rax + 0]
    vbroadcastsd zmm26, [rsi + 8*rax + 8]
    vmulpd       zmm9,  zmm25, zmm30
    vmulpd       zmm10, zmm26, zmm30

    vmovupd zmm0, [r10 + 0]
    vmovupd zmm1, [r10 + 64]
    vmovupd zmm2, [r10 + 128]
    vmovupd zmm3, [r10 + 192]
    vmovupd zmm4, [r10 + 256]
    vmovupd zmm5, [r10 + 320]
    vmovupd zmm6, [r10 + 384]
    vmovupd zmm7, [r10 + 448]

    NTT_DIF4_SHOUP zmm0, zmm4, zmm24, zmm8, zmm1, zmm5, zmm24, zmm8, zmm2, zmm6, zmm24, zmm8, zmm3, zmm7, zmm24, zmm8
    NTT_DIF4_SHOUP zmm0, zmm2, zmm25, zmm9, zmm1, zmm3, zmm25, zmm9, zmm4, zmm6, zmm26, zmm10, zmm5, zmm7, zmm26, zmm10
    ZMM_RED4_SIGNED zmm0, zmm1, zmm2, zmm3
    ZMM_RED4_SIGNED zmm4, zmm5, zmm6, zmm7

    add  rax, rax                       // 4 * (r13 + r8)
    mov  r15, rcx
    call .Lntt_bot4_fused_core

    shr  rax, 1
    vbroadcastsd zmm24, [r9 + 8*rax + 0]
    vbroadcastsd zmm25, [r9 + 8*rax + 8]
    vmulpd       zmm8,  zmm24, zmm30
    vmulpd       zmm9,  zmm25, zmm30
    shr  rax, 1
    vbroadcastsd zmm26, [r9 + 8*rax]
    vmulpd       zmm10, zmm26, zmm30
    NTT_DIT4_SHOUP zmm0, zmm2, zmm24, zmm8,  zmm1, zmm3, zmm24, zmm8,  zmm4, zmm6, zmm25, zmm9,  zmm5, zmm7, zmm25, zmm9
    NTT_DIT4_SHOUP zmm0, zmm4, zmm26, zmm10, zmm1, zmm5, zmm26, zmm10, zmm2, zmm6, zmm26, zmm10, zmm3, zmm7, zmm26, zmm10

    cmp  rdx, 64
    jne  .Lnttfwd_bot6_fused_noscl
    cmp  qword ptr [rsp + 24], 1
    ja   .Lnttfwd_bot6_fused_noscl
    cmp  qword ptr [rsp + 48], 0
    je   .Lnttinv_bot6_n64_canon
    ZMM_RED4_SIGNED  zmm0, zmm1, zmm2, zmm3
    ZMM_SCALE4_SHOUP zmm0, zmm1, zmm2, zmm3, qword ptr [rsp + 1120]{1to8}
    ZMM_SCALE4_SHOUP zmm4, zmm5, zmm6, zmm7, qword ptr [rsp + 1120]{1to8}
    vmovupd [r10 + 0],   zmm0
    vmovupd [r10 + 64],  zmm1
    vmovupd [r10 + 128], zmm2
    vmovupd [r10 + 192], zmm3
    vmovupd [r10 + 256], zmm4
    vmovupd [r10 + 320], zmm5
    vmovupd [r10 + 384], zmm6
    vmovupd [r10 + 448], zmm7
    jmp  .Lnttinv_done

.Lnttfwd_bot6_fused_noscl:
    ZMM_RED4_SIGNED zmm0, zmm1, zmm2, zmm3
    vmovupd [r10 + 0],   zmm0
    vmovupd [r10 + 64],  zmm1
    vmovupd [r10 + 128], zmm2
    vmovupd [r10 + 192], zmm3
    vmovupd [r10 + 256], zmm4
    vmovupd [r10 + 320], zmm5
    vmovupd [r10 + 384], zmm6
    vmovupd [r10 + 448], zmm7

    inc  r8
    cmp  r8, r12
    jb   .Lnttfwd_bot6_fused_loop

    mov  rsi, r9
    tzcnt r15, rdx
    sub  r15, 6
    jz   .Lnttinv_next_sub
    mov  r13, 64
    mov  r12, rdx
    shr  r12, 7
    jmp  .Lnttinv_r16_check

    // 3b. In-register Radix-16 bottom pass covering stages m = 8, 4, 2, 1 inside L1d!
.Lnttfwd_bottom_r16:
    vpxorq zmm31, zmm31, zmm31
    mov  rdx, [rsp + 16]
    mov  r12, rdx
    shr  r12, 4                         // b8_local = sub_n / 16
    mov  r13, [rsp + 40]
    imul r13, r12                       // tw_b8_base = tw_root * b8_local
    xor  r8d, r8d                       // b8 = 0
    mov  r9,  r12
    and  r9,  -4                        // 4-block limit
    cmp  r9,  4
    jb   .Lnttfwd_bot1_check

    vmovdqa64 zmm12, [rip + .Lconst_idx_bot_fwd_lo]
    vmovdqa64 zmm13, [rip + .Lconst_idx_bot_fwd_hi]

.p2align 4
.Lnttfwd_bot4_loop:
    mov  rax, r8
    shl  rax, 7                         // b8 * 128 bytes
    lea  r10, [rdi + rax]

    // Stage m = 8 twiddles + WP prepared ahead of data loads; preload Stage m = 4 twiddles into zmm8..11!
    lea  rax, [r13 + r8]
    vbroadcastsd zmm24, [rsi + 8*rax + 0]
    vbroadcastsd zmm25, [rsi + 8*rax + 8]
    vbroadcastsd zmm26, [rsi + 8*rax + 16]
    vbroadcastsd zmm27, [rsi + 8*rax + 24]
    NTT_PREP_WP4 zmm24, zmm25, zmm26, zmm27

    vmovupd zmm0, [r10 + 0]
    vmovupd zmm1, [r10 + 64]
    vmovupd zmm2, [r10 + 128]
    vmovupd zmm3, [r10 + 192]
    vmovupd zmm4, [r10 + 256]
    vmovupd zmm5, [r10 + 320]
    vmovupd zmm6, [r10 + 384]
    vmovupd zmm7, [r10 + 448]

    add  rax, rax
    vbroadcastf64x2 zmm8,  [rsi + 8*rax + 0]
    vbroadcastf64x2 zmm9,  [rsi + 8*rax + 16]
    vbroadcastf64x2 zmm10, [rsi + 8*rax + 32]
    vbroadcastf64x2 zmm11, [rsi + 8*rax + 48]
    vshufpd zmm8,  zmm8,  zmm8,  0xF0
    vshufpd zmm9,  zmm9,  zmm9,  0xF0
    vshufpd zmm10, zmm10, zmm10, 0xF0
    vshufpd zmm11, zmm11, zmm11, 0xF0

    NTT_DIF4_SHOUP zmm0, zmm1, zmm24, zmm20, zmm2, zmm3, zmm25, zmm21, zmm4, zmm5, zmm26, zmm22, zmm6, zmm7, zmm27, zmm23

    // Stage m = 4: prepare WP from preloaded zmm8..11 while shuffling data & preloading m = 2 into zmm0,2,4,6!
    NTT_PREP_WP4 zmm8, zmm9, zmm10, zmm11
    vshuff64x2 zmm24, zmm0, zmm1, 0x44
    vshuff64x2 zmm1,  zmm0, zmm1, 0xEE
    vshuff64x2 zmm25, zmm2, zmm3, 0x44
    vshuff64x2 zmm3,  zmm2, zmm3, 0xEE
    vshuff64x2 zmm26, zmm4, zmm5, 0x44
    vshuff64x2 zmm5,  zmm4, zmm5, 0xEE
    vshuff64x2 zmm27, zmm6, zmm7, 0x44
    vshuff64x2 zmm7,  zmm6, zmm7, 0xEE

    add  rax, rax
    vbroadcastf64x4 zmm0, [rsi + 8*rax + 0]
    vbroadcastf64x4 zmm2, [rsi + 8*rax + 32]
    vbroadcastf64x4 zmm4, [rsi + 8*rax + 64]
    vbroadcastf64x4 zmm6, [rsi + 8*rax + 96]
    vshufpd zmm0, zmm0, zmm0, 0xF0
    vshufpd zmm2, zmm2, zmm2, 0xF0
    vshufpd zmm4, zmm4, zmm4, 0xF0
    vshufpd zmm6, zmm6, zmm6, 0xF0

    NTT_DIF4_SHOUP zmm24, zmm1, zmm8, zmm20, zmm25, zmm3, zmm9, zmm21, zmm26, zmm5, zmm10, zmm22, zmm27, zmm7, zmm11, zmm23

    // Stage m = 2: prepare WP from preloaded zmm0,2,4,6 while shuffling data & preloading m = 1 into zmm24..27!
    NTT_PREP_WP4 zmm0, zmm2, zmm4, zmm6
    vshuff64x2 zmm8,  zmm24, zmm1, 0x88
    vshuff64x2 zmm1,  zmm24, zmm1, 0xDD
    vshuff64x2 zmm9,  zmm25, zmm3, 0x88
    vshuff64x2 zmm3,  zmm25, zmm3, 0xDD
    vshuff64x2 zmm10, zmm26, zmm5, 0x88
    vshuff64x2 zmm5,  zmm26, zmm5, 0xDD
    vshuff64x2 zmm11, zmm27, zmm7, 0x88
    vshuff64x2 zmm7,  zmm27, zmm7, 0xDD

    add  rax, rax
    vmovupd    zmm24, [rsi + 8*rax + 0]
    vmovupd    zmm25, [rsi + 8*rax + 64]
    vmovupd    zmm26, [rsi + 8*rax + 128]
    vmovupd    zmm27, [rsi + 8*rax + 192]
    vshuff64x2 zmm24, zmm24, zmm24, 0xD8
    vshuff64x2 zmm25, zmm25, zmm25, 0xD8
    vshuff64x2 zmm26, zmm26, zmm26, 0xD8
    vshuff64x2 zmm27, zmm27, zmm27, 0xD8

    NTT_DIF4_SHOUP zmm8, zmm1, zmm0, zmm20, zmm9, zmm3, zmm2, zmm21, zmm10, zmm5, zmm4, zmm22, zmm11, zmm7, zmm6, zmm23

    // Stage m = 1: prepare WP from preloaded zmm24..27 while unpacking data!
    NTT_PREP_WP4 zmm24, zmm25, zmm26, zmm27
    vunpcklpd zmm0, zmm8,  zmm1
    vunpckhpd zmm1, zmm8,  zmm1
    vunpcklpd zmm2, zmm9,  zmm3
    vunpckhpd zmm3, zmm9,  zmm3
    vunpcklpd zmm4, zmm10, zmm5
    vunpckhpd zmm5, zmm10, zmm5
    vunpcklpd zmm6, zmm11, zmm7
    vunpckhpd zmm7, zmm11, zmm7
    NTT_DIF4_SHOUP zmm0, zmm1, zmm24, zmm20, zmm2, zmm3, zmm25, zmm21, zmm4, zmm5, zmm26, zmm22, zmm6, zmm7, zmm27, zmm23

    vmovapd   zmm8,  zmm0
    vpermt2pd zmm0,  zmm12, zmm1
    vpermt2pd zmm8,  zmm13, zmm1
    vmovapd   zmm9,  zmm2
    vpermt2pd zmm2,  zmm12, zmm3
    vpermt2pd zmm9,  zmm13, zmm3
    vmovapd   zmm10, zmm4
    vpermt2pd zmm4,  zmm12, zmm5
    vpermt2pd zmm10, zmm13, zmm5
    vmovapd   zmm11, zmm6
    vpermt2pd zmm6,  zmm12, zmm7
    vpermt2pd zmm11, zmm13, zmm7

    ZMM_RED4_SIGNED zmm0, zmm8, zmm2, zmm9
    ZMM_RED4_SIGNED zmm4, zmm10, zmm6, zmm11
    cmp  qword ptr [rsp + 1144], 0
    jne  .Lnttfwd_bot4_store
    vcmppd k1, zmm0,  zmm31, 1
    vcmppd k2, zmm8,  zmm31, 1
    vcmppd k3, zmm2,  zmm31, 1
    vcmppd k4, zmm9,  zmm31, 1
    vaddpd zmm0  {k1}, zmm0,  zmm29
    vaddpd zmm8  {k2}, zmm8,  zmm29
    vaddpd zmm2  {k3}, zmm2,  zmm29
    vaddpd zmm9  {k4}, zmm9,  zmm29
    vcmppd k1, zmm4,  zmm31, 1
    vcmppd k2, zmm10, zmm31, 1
    vcmppd k3, zmm6,  zmm31, 1
    vcmppd k4, zmm11, zmm31, 1
    vaddpd zmm4  {k1}, zmm4,  zmm29
    vaddpd zmm10 {k2}, zmm10, zmm29
    vaddpd zmm6  {k3}, zmm6,  zmm29
    vaddpd zmm11 {k4}, zmm11, zmm29
.Lnttfwd_bot4_store:

    vmovupd [r10 + 0],   zmm0
    vmovupd [r10 + 64],  zmm8
    vmovupd [r10 + 128], zmm2
    vmovupd [r10 + 192], zmm9
    vmovupd [r10 + 256], zmm4
    vmovupd [r10 + 320], zmm10
    vmovupd [r10 + 384], zmm6
    vmovupd [r10 + 448], zmm11

    add  r8, 4
    cmp  r8, r9
    jb   .Lnttfwd_bot4_loop

.Lnttfwd_bot1_check:
    cmp  r8, r12
    jae  .Lnttfwd_next_sub
    vmovdqa64 zmm12, [rip + .Lconst_idx_00001111]
    vmovdqa64 zmm13, [rip + .Lconst_idx_00112233]
    vmovdqa64 zmm14, [rip + .Lconst_idx_even]
    vmovdqa64 zmm15, [rip + .Lconst_idx_odd]
    vmovdqa64 zmm26, [rip + .Lconst_idx_interleave_lo]
    vmovdqa64 zmm27, [rip + .Lconst_idx_interleave_hi]
.Lnttfwd_bot1_loop:
    mov  rax, r8
    shl  rax, 7
    lea  r10, [rdi + rax]
    vmovupd zmm0, [r10 + 0]
    vmovupd zmm1, [r10 + 64]

    lea  rax, [r13 + r8]
    vbroadcastsd zmm24, [rsi + 8*rax]
    NTT_DIF1_LAZY zmm0, zmm1, zmm24

    add  rax, rax
    vmovupd xmm24, [rsi + 8*rax]
    vpermq  zmm24, zmm12, zmm24
    vshuff64x2 zmm8, zmm0, zmm1, 0x44
    vshuff64x2 zmm1, zmm0, zmm1, 0xEE
    NTT_DIF1_LAZY zmm8, zmm1, zmm24
    vshuff64x2 zmm0, zmm8, zmm1, 0x44
    vshuff64x2 zmm1, zmm8, zmm1, 0xEE

    add  rax, rax
    vmovupd ymm24, [rsi + 8*rax]
    vpermq  zmm24, zmm13, zmm24
    vshuff64x2 zmm8, zmm0, zmm1, 0x88
    vshuff64x2 zmm1, zmm0, zmm1, 0xDD
    NTT_DIF1_LAZY zmm8, zmm1, zmm24
    vshuff64x2 zmm0, zmm8, zmm1, 0x44
    vshuff64x2 zmm1, zmm8, zmm1, 0xEE
    vshuff64x2 zmm0, zmm0, zmm0, 0xD8
    vshuff64x2 zmm1, zmm1, zmm1, 0xD8

    add  rax, rax
    vmovupd   zmm24, [rsi + 8*rax]
    vmovapd   zmm8,  zmm0
    vpermt2pd zmm0,  zmm14, zmm1
    vpermt2pd zmm8,  zmm15, zmm1
    NTT_DIF1_LAZY zmm0, zmm8, zmm24
    vmovapd   zmm1,  zmm0
    vpermt2pd zmm0,  zmm26, zmm8
    vpermt2pd zmm1,  zmm27, zmm8
    ZMM_CANON2 zmm0, zmm1

    vmovupd [r10 + 0],  zmm0
    vmovupd [r10 + 64], zmm1
    inc  r8
    cmp  r8, r12
    jb   .Lnttfwd_bot1_loop

.Lnttfwd_next_sub:
    cmp  qword ptr [rsp + 1128], 0
    jne  .Lntt_fused_l1_to_inv
    mov  rax, [rsp + 32]
    inc  rax
    cmp  rax, [rsp + 1056]
    jb   .Lnttfwd_cont_sub
    cmp  qword ptr [rsp + 1048], 0
    je   .Lnttfwd_done
    mov  rax, [rsp + 1040]
    inc  rax
    cmp  rax, [rsp + 1048]
    jae  .Lnttfwd_done
    mov  [rsp + 1040], rax
    jmp  .Lnttfwd_l2_blk_start
.Lnttfwd_cont_sub:
    mov  [rsp + 32], rax
    jmp  .Lnttfwd_sub_loop

    // Small power-of-two fallback for n in {2, 4, 8}
.Lnttfwd_small:
    mov  r8,  1                         // b_blocks
    mov  r9,  rdx
    shr  r9,  1                         // m
.Lnttfwd_sm_stage:
    xor  r10d, r10d                     // j = 0
.Lnttfwd_sm_block:
    lea  rax, [r8 + r10]
    vmovsd xmm6, [rsi + 8*rax]          // w
    mov  r11, r10
    imul r11, r9
    add  r11, r11                       // base = j * 2 * m
    xor  r12d, r12d                     // i = 0
.Lnttfwd_sm_bfy:
    lea  rax, [r11 + r12]
    lea  rbx, [rax + r9]
    vmovsd xmm0, [rdi + 8*rax]          // u
    vmovsd xmm1, [rdi + 8*rbx]          // x
    vmulsd xmm2, xmm1, xmm6
    vmulsd xmm3, xmm2, xmm30
    vfmsub213sd xmm1, xmm6, xmm2
    vrndscalesd xmm3, xmm3, xmm3, 8
    vfnmadd231sd xmm2, xmm3, xmm29
    vaddsd xmm1, xmm2, xmm1
    vcmpsd k1, xmm1, xmm31, 1
    vaddsd xmm1 {k1}, xmm1, xmm29       // v
    vsubsd xmm2, xmm0, xmm1
    vaddsd xmm0, xmm0, xmm1
    vcmpsd k1, xmm2, xmm31, 1
    vcmpsd k2, xmm0, xmm29, 13
    vaddsd xmm2 {k1}, xmm2, xmm29
    vsubsd xmm0 {k2}, xmm0, xmm29
    vmovsd [rdi + 8*rax], xmm0
    vmovsd [rdi + 8*rbx], xmm2
    inc  r12
    cmp  r12, r9
    jb   .Lnttfwd_sm_bfy
    inc  r10
    cmp  r10, r8
    jb   .Lnttfwd_sm_block
    shl  r8, 1
    shr  r9, 1
    jnz  .Lnttfwd_sm_stage

.Lnttfwd_done:
    VEC_LEAVE

.macro L1D_PMUL_SUB
    mov  r9,  rdi
    mov  r10, rdx
    cmp  r10, 64
    jb   2f
.p2align 4
1:
    vmovupd zmm0,  [r9 + 0]
    vmovupd zmm1,  [r9 + 64]
    vmovupd zmm2,  [r9 + 128]
    vmovupd zmm3,  [r9 + 192]
    vmovupd zmm4,  [r9 + 256]
    vmovupd zmm5,  [r9 + 320]
    vmovupd zmm6,  [r9 + 384]
    vmovupd zmm7,  [r9 + 448]
    vmovupd zmm8,  [r11 + 0]
    vmovupd zmm9,  [r11 + 64]
    vmovupd zmm10, [r11 + 128]
    vmovupd zmm11, [r11 + 192]
    vmovupd zmm12, [r11 + 256]
    vmovupd zmm13, [r11 + 320]
    vmovupd zmm14, [r11 + 384]
    vmovupd zmm15, [r11 + 448]

    vmulpd       zmm16, zmm0, zmm8
    vmulpd       zmm17, zmm1, zmm9
    vmulpd       zmm18, zmm2, zmm10
    vmulpd       zmm19, zmm3, zmm11
    vmulpd       zmm20, zmm4, zmm12
    vmulpd       zmm21, zmm5, zmm13
    vmulpd       zmm22, zmm6, zmm14
    vmulpd       zmm23, zmm7, zmm15

    vfmsub213pd  zmm0,  zmm8,  zmm16
    vfmsub213pd  zmm1,  zmm9,  zmm17
    vfmsub213pd  zmm2,  zmm10, zmm18
    vfmsub213pd  zmm3,  zmm11, zmm19
    vfmsub213pd  zmm4,  zmm12, zmm20
    vfmsub213pd  zmm5,  zmm13, zmm21
    vfmsub213pd  zmm6,  zmm14, zmm22
    vfmsub213pd  zmm7,  zmm15, zmm23

    vmulpd       zmm8,  zmm16, zmm30
    vmulpd       zmm9,  zmm17, zmm30
    vmulpd       zmm10, zmm18, zmm30
    vmulpd       zmm11, zmm19, zmm30
    vmulpd       zmm12, zmm20, zmm30
    vmulpd       zmm13, zmm21, zmm30
    vmulpd       zmm14, zmm22, zmm30
    vmulpd       zmm15, zmm23, zmm30

    vrndscalepd  zmm8,  zmm8,  8
    vrndscalepd  zmm9,  zmm9,  8
    vrndscalepd  zmm10, zmm10, 8
    vrndscalepd  zmm11, zmm11, 8
    vrndscalepd  zmm12, zmm12, 8
    vrndscalepd  zmm13, zmm13, 8
    vrndscalepd  zmm14, zmm14, 8
    vrndscalepd  zmm15, zmm15, 8

    vfnmadd231pd zmm16, zmm8,  zmm29
    vfnmadd231pd zmm17, zmm9,  zmm29
    vfnmadd231pd zmm18, zmm10, zmm29
    vfnmadd231pd zmm19, zmm11, zmm29
    vfnmadd231pd zmm20, zmm12, zmm29
    vfnmadd231pd zmm21, zmm13, zmm29
    vfnmadd231pd zmm22, zmm14, zmm29
    vfnmadd231pd zmm23, zmm15, zmm29

    vaddpd       zmm0,  zmm16, zmm0
    vaddpd       zmm1,  zmm17, zmm1
    vaddpd       zmm2,  zmm18, zmm2
    vaddpd       zmm3,  zmm19, zmm3
    vaddpd       zmm4,  zmm20, zmm4
    vaddpd       zmm5,  zmm21, zmm5
    vaddpd       zmm6,  zmm22, zmm6
    vaddpd       zmm7,  zmm23, zmm7

    vcmppd       k1, zmm0, zmm31, 1
    vcmppd       k2, zmm1, zmm31, 1
    vcmppd       k3, zmm2, zmm31, 1
    vcmppd       k4, zmm3, zmm31, 1
    vaddpd       zmm0 {k1}, zmm0, zmm29
    vaddpd       zmm1 {k2}, zmm1, zmm29
    vaddpd       zmm2 {k3}, zmm2, zmm29
    vaddpd       zmm3 {k4}, zmm3, zmm29
    vcmppd       k1, zmm4, zmm31, 1
    vcmppd       k2, zmm5, zmm31, 1
    vcmppd       k3, zmm6, zmm31, 1
    vcmppd       k4, zmm7, zmm31, 1
    vaddpd       zmm4 {k1}, zmm4, zmm29
    vaddpd       zmm5 {k2}, zmm5, zmm29
    vaddpd       zmm6 {k3}, zmm6, zmm29
    vaddpd       zmm7 {k4}, zmm7, zmm29

    vmovupd [r9 + 0],   zmm0
    vmovupd [r9 + 64],  zmm1
    vmovupd [r9 + 128], zmm2
    vmovupd [r9 + 192], zmm3
    vmovupd [r9 + 256], zmm4
    vmovupd [r9 + 320], zmm5
    vmovupd [r9 + 384], zmm6
    vmovupd [r9 + 448], zmm7

    add  r9,  512
    add  r11, 512
    sub  r10, 64
    jnz  1b
    jmp  4f
2:
3:
    vmovupd zmm0, [r9 + 0]
    vmovupd zmm1, [r9 + 64]
    vmovupd zmm2, [r11 + 0]
    vmovupd zmm3, [r11 + 64]
    ZMM_MUL_MOD zmm0, zmm2, zmm16, zmm20, k1
    ZMM_MUL_MOD zmm1, zmm3, zmm17, zmm21, k2
    vmovupd [r9 + 0],  zmm0
    vmovupd [r9 + 64], zmm1
    add  r9,  128
    add  r11, 128
    sub  r10, 16
    jnz  3b
4:
.endm

// [14] ntt_inv(buf: rdi, inv_twiddles: rsi, n: rdx, prime: rcx)
// In-register Radix-16 bottom DIT pass (m = 1, 2, 4, 8), followed by
// in-register Radix-16 / Radix-4 / Radix-2 top DIT passes and scale multiply.
// Also supports depth-first L2 + L1d fused (fwd + pmul + inv) and (pmul + inv)
// via prime.fwd_tw ([rcx + 40]) and prime.pmul_b ([rcx + 48]).
LOCAL_FN supi_k_ntt_inv
    VEC_ENTER 1152
    test rdx, rdx
    jz   .Lnttinv_done

    vbroadcastsd zmm29, [rcx + 0]       // p
    vbroadcastsd zmm30, [rcx + 8]       // inv_p
    vbroadcastsd zmm28, [rcx + 16]      // scale
    vpxorq       zmm31, zmm31, zmm31    // 0.0
    vmulsd       xmm16, xmm28, xmm30
    vmovsd       [rsp + 1120], xmm16    // scale_wp = fl(scale * inv_p)
    mov  rax, [rcx + 16]
    mov  [rsp + 1064], rax              // save scalar scale for fast reload after Shoup r4 loops
    mov  rbx, 0x3FF0000000000000        // 1.0
    xor  r8d, r8d
    cmp  rax, rbx
    setne r8b
    mov  [rsp + 48],   r8               // need_scale (0 or 1)
    mov  [rsp + 1008], r8               // preserved across ntt_fwd R16 pass

    mov  r9,  [rcx + 40]                // fwd_tw (or null)
    mov  r10, [rcx + 48]                // pmul_b (or null)
    mov  [rsp + 1128], r9
    mov  [rsp + 1136], rsi              // inv_tw
    mov  [rsp + 1144], r10
    mov  rax, r9
    or   rax, r10
    jz   .Lnttinv_plain_entry

    cmp  rdx, 16
    jb   .Lnttinv_fused_lt16
    test r9,  r9
    jz   .Lnttinv_ge16_entry
    mov  rsi, r9
    jmp  .Lnttfwd_ge16_entry

.Lnttinv_fused_lt16:
    test r9,  r9
    jz   .Lnttinv_lt16_pmul
    cmp  rdx, 1
    jbe  .Lnttinv_lt16_pmul
    mov  r8,  1
    mov  r13, rdx
    shr  r13, 1
.Lnttinv_lt16_fwd_stg:
    xor  r10d, r10d
.Lnttinv_lt16_fwd_blk:
    lea  rax, [r8 + r10]
    vmovsd xmm6, [r9 + 8*rax]
    mov  r11, r10
    imul r11, r13
    add  r11, r11
    xor  r12d, r12d
.Lnttinv_lt16_fwd_bfy:
    lea  rax, [r11 + r12]
    lea  rbx, [rax + r13]
    vmovsd xmm0, [rdi + 8*rax]
    vmovsd xmm1, [rdi + 8*rbx]
    vmulsd xmm2, xmm1, xmm6
    vmulsd xmm3, xmm2, xmm30
    vfmsub213sd xmm1, xmm6, xmm2
    vrndscalesd xmm3, xmm3, xmm3, 8
    vfnmadd231sd xmm2, xmm3, xmm29
    vaddsd xmm1, xmm2, xmm1
    vcmpsd k1, xmm1, xmm31, 1
    vaddsd xmm1 {k1}, xmm1, xmm29
    vsubsd xmm2, xmm0, xmm1
    vaddsd xmm0, xmm0, xmm1
    vcmpsd k1, xmm2, xmm31, 1
    vcmpsd k2, xmm0, xmm29, 13
    vaddsd xmm2 {k1}, xmm2, xmm29
    vsubsd xmm0 {k2}, xmm0, xmm29
    vmovsd [rdi + 8*rax], xmm0
    vmovsd [rdi + 8*rbx], xmm2
    inc  r12
    cmp  r12, r13
    jb   .Lnttinv_lt16_fwd_bfy
    inc  r10
    cmp  r10, r8
    jb   .Lnttinv_lt16_fwd_blk
    shl  r8,  1
    shr  r13, 1
    jnz  .Lnttinv_lt16_fwd_stg
.Lnttinv_lt16_pmul:
    mov  r10, [rsp + 1144]
    test r10, r10
    jz   .Lnttinv_plain_entry
    mov  eax, 0xFF
    bzhi eax, eax, edx
    kmovw k5, eax
    vmovupd zmm0 {k5}{z}, [rdi]
    vmovupd zmm1 {k5}{z}, [r10]
    ZMM_MUL_MOD zmm0, zmm1, zmm16, zmm20, k1
    vmovupd [rdi] {k5}, zmm0

.Lnttinv_plain_entry:
    cmp  rdx, 1
    je   .Lnttinv_scale_check
    cmp  rdx, 16
    jb   .Lnttinv_small

.Lnttinv_ge16_entry:
    mov  [rsp + 0], rdi                 // orig_buf
    mov  [rsp + 8], rdx                 // orig_n
    mov  rax, [rcx + 24]                // raw l1_sub
    mov  rbx, [rcx + 32]                // raw l2_sub
    cmp  rax, rdx
    jae  .Lnttinv_single_sub
    mov  r8d, 64
    cmp  rax, 64
    cmovb rax, r8
    lzcnt r9, rax
    mov  ecx, 63
    sub  ecx, r9d                       // k1 = log2(l1_sub) >= 6
    mov  eax, 1
    shl  rax, cl                        // l1_sub = 2^k1
    cmp  rdx, rax
    jbe  .Lnttinv_single_sub
    cmp  ecx, 11
    jne  .Lnttinv_set_sub_l1
    tzcnt r8, rdx
    test r8d, 1
    jnz  .Lnttinv_set_sub_l1
    dec  ecx
    shr  rax, 1                         // l1_sub = 1024 for all even log2(orig_n) (2 L1 passes + pure R4 above!)
    jmp  .Lnttinv_set_sub_l1

.Lnttinv_single_sub:
    mov  [rsp + 16], rdx                // sub_n = orig_n
    mov  qword ptr [rsp + 24], 1        // num_subs = 1
    mov  qword ptr [rsp + 1048], 0      // num_l2 = 0
    mov  qword ptr [rsp + 1056], 1      // sub_end = 1
    jmp  .Lnttinv_sub_init

.Lnttinv_set_sub_l1:
    mov  [rsp + 1072], rax              // l1_sub
    mov  [rsp + 1080], rcx              // k1
    mov  [rsp + 16], rax                // sub_n = l1_sub
    mov  r10, rdx
    shr  r10, cl
    mov  [rsp + 24], r10                // num_subs = orig_n / l1_sub
    cmp  rbx, rdx
    jae  .Lnttinv_no_l2_mode
    lea  r8,  [rax + rax]               // min l2_sub = 2 * l1_sub
    cmp  rbx, r8
    cmovb rbx, r8
    lzcnt r9, rbx
    mov  ecx, 63
    sub  ecx, r9d                       // k2 = log2(l2_sub) > k1
    mov  eax, 1
    shl  rax, cl                        // l2_sub = 2^k2
    cmp  ecx, 15
    jne  .Lnttinv_keep_k2
    cmp  qword ptr [rsp + 1080], 10
    jne  .Lnttinv_keep_k2
    dec  ecx
    shr  rax, 1                         // l2_sub = 16384 (128 KiB) for even log2(orig_n) >= 16 (pure R4 in L3 and L2!)
.Lnttinv_keep_k2:
    cmp  rdx, rax
    ja   .Lnttinv_l2_mode

.Lnttinv_no_l2_mode:
    mov  qword ptr [rsp + 1048], 0      // num_l2 = 0
    mov  [rsp + 1056], r10              // sub_end = num_subs
    jmp  .Lnttinv_sub_init

.Lnttinv_l2_mode:
    mov  [rsp + 1088], rax              // l2_sub
    mov  [rsp + 1096], rcx              // k2
    mov  r8,  rcx
    sub  r8,  [rsp + 1080]              // k_diff = k2 - k1 >= 1
    mov  [rsp + 1104], r8
    mov  eax, 1
    mov  ecx, r8d
    shl  rax, cl                        // subs_per_l2 = 1 << (k2 - k1)
    mov  [rsp + 1112], rax
    mov  [rsp + 1056], rax              // sub_end = subs_per_l2
    mov  rcx, [rsp + 1096]
    mov  rax, rdx
    shr  rax, cl
    mov  [rsp + 1048], rax              // num_l2 = orig_n / l2_sub
    mov  qword ptr [rsp + 1040], 0      // l2_idx = 0

.Lnttinv_sub_init:
    xor  eax, eax
    mov  [rsp + 32], rax                // sub_idx = 0
    jmp  .Lnttinv_sub_loop

.Lntt_fused_l1_to_inv:
    mov  rsi, [rsp + 1136]              // inv_tw
    mov  rax, [rsp + 1008]
    mov  [rsp + 48], rax                // restore need_scale
    vbroadcastsd zmm28, [rsp + 1064]
    vpxorq       zmm31, zmm31, zmm31

    // 1. Depth-first L1d sub-block loop (m = 1 .. sub_n / 2, <= 16 KiB in L1d!)
.Lnttinv_sub_loop:
    mov  rax, [rsp + 32]                // sub_idx
    mov  rcx, [rsp + 24]                // num_subs
    add  rcx, rax
    mov  [rsp + 40], rcx                // tw_root = num_subs + sub_idx
    mov  rdx, [rsp + 16]                // sub_n
    imul rax, rdx
    shl  rax, 3
    mov  rdi, [rsp + 0]
    add  rdi, rax                       // sub_buf
    mov  r11, [rsp + 1144]              // pmul_b
    test r11, r11
    jz   .Lnttinv_sub_after_pmul
    add  r11, rax                       // pb_sub
    cmp  rdx, 64
    jae  .Lnttinv_sub_after_pmul        // fused directly into bot7/bot6/bot4 loads!
    L1D_PMUL_SUB
    xor  r11d, r11d
.Lnttinv_sub_after_pmul:

.macro ZMM_PMUL8_MEM_SIGNED A_BASE, B_BASE
    vmovupd      zmm0,  [\A_BASE + 0]
    vmovupd      zmm1,  [\A_BASE + 64]
    vmovupd      zmm2,  [\A_BASE + 128]
    vmovupd      zmm3,  [\A_BASE + 192]
    vmovupd      zmm4,  [\A_BASE + 256]
    vmovupd      zmm5,  [\A_BASE + 320]
    vmovupd      zmm6,  [\A_BASE + 384]
    vmovupd      zmm7,  [\A_BASE + 448]
    vmovupd      zmm8,  [\B_BASE + 0]
    vmovupd      zmm9,  [\B_BASE + 64]
    vmovupd      zmm10, [\B_BASE + 128]
    vmovupd      zmm11, [\B_BASE + 192]
    vmovupd      zmm14, [\B_BASE + 256]
    vmovupd      zmm15, [\B_BASE + 320]
    vmovupd      zmm24, [\B_BASE + 384]
    vmovupd      zmm25, [\B_BASE + 448]

    vmulpd       zmm16, zmm0, zmm8
    vmulpd       zmm17, zmm1, zmm9
    vmulpd       zmm18, zmm2, zmm10
    vmulpd       zmm19, zmm3, zmm11
    vmulpd       zmm20, zmm4, zmm14
    vmulpd       zmm21, zmm5, zmm15
    vmulpd       zmm22, zmm6, zmm24
    vmulpd       zmm23, zmm7, zmm25

    vfmsub213pd  zmm0,  zmm8,  zmm16
    vfmsub213pd  zmm1,  zmm9,  zmm17
    vfmsub213pd  zmm2,  zmm10, zmm18
    vfmsub213pd  zmm3,  zmm11, zmm19
    vfmsub213pd  zmm4,  zmm14, zmm20
    vfmsub213pd  zmm5,  zmm15, zmm21
    vfmsub213pd  zmm6,  zmm24, zmm22
    vfmsub213pd  zmm7,  zmm25, zmm23

    vmulpd       zmm8,  zmm16, zmm30
    vmulpd       zmm9,  zmm17, zmm30
    vmulpd       zmm10, zmm18, zmm30
    vmulpd       zmm11, zmm19, zmm30
    vmulpd       zmm14, zmm20, zmm30
    vmulpd       zmm15, zmm21, zmm30
    vmulpd       zmm24, zmm22, zmm30
    vmulpd       zmm25, zmm23, zmm30

    vrndscalepd  zmm8,  zmm8,  8
    vrndscalepd  zmm9,  zmm9,  8
    vrndscalepd  zmm10, zmm10, 8
    vrndscalepd  zmm11, zmm11, 8
    vrndscalepd  zmm14, zmm14, 8
    vrndscalepd  zmm15, zmm15, 8
    vrndscalepd  zmm24, zmm24, 8
    vrndscalepd  zmm25, zmm25, 8

    vfnmadd231pd zmm16, zmm8,  zmm29
    vfnmadd231pd zmm17, zmm9,  zmm29
    vfnmadd231pd zmm18, zmm10, zmm29
    vfnmadd231pd zmm19, zmm11, zmm29
    vfnmadd231pd zmm20, zmm14, zmm29
    vfnmadd231pd zmm21, zmm15, zmm29
    vfnmadd231pd zmm22, zmm24, zmm29
    vfnmadd231pd zmm23, zmm25, zmm29

    vaddpd       zmm0,  zmm16, zmm0
    vaddpd       zmm1,  zmm17, zmm1
    vaddpd       zmm2,  zmm18, zmm2
    vaddpd       zmm3,  zmm19, zmm3
    vaddpd       zmm4,  zmm20, zmm4
    vaddpd       zmm5,  zmm21, zmm5
    vaddpd       zmm6,  zmm22, zmm6
    vaddpd       zmm7,  zmm23, zmm7
.endm

.macro NTT_INV_BOT4_HALF IN_OFF, PB_OFF_REG
    test r11, r11
    jnz  1f
    vmovupd zmm0, [r10 + \IN_OFF + 0]
    vmovupd zmm1, [r10 + \IN_OFF + 64]
    vmovupd zmm2, [r10 + \IN_OFF + 128]
    vmovupd zmm3, [r10 + \IN_OFF + 192]
    vmovupd zmm4, [r10 + \IN_OFF + 256]
    vmovupd zmm5, [r10 + \IN_OFF + 320]
    vmovupd zmm6, [r10 + \IN_OFF + 384]
    vmovupd zmm7, [r10 + \IN_OFF + 448]
    jmp  2f
1:
    ZMM_PMUL8_MEM_SIGNED r10 + \IN_OFF, r11 + \PB_OFF_REG + \IN_OFF
2:
    vmovupd    zmm24, [rsi + 8*rax + 0]
    vmovupd    zmm25, [rsi + 8*rax + 64]
    vmovupd    zmm26, [rsi + 8*rax + 128]
    vmovupd    zmm27, [rsi + 8*rax + 192]
    vshuff64x2 zmm24, zmm24, zmm24, 0xD8
    vshuff64x2 zmm25, zmm25, zmm25, 0xD8
    vshuff64x2 zmm26, zmm26, zmm26, 0xD8
    vshuff64x2 zmm27, zmm27, zmm27, 0xD8
    NTT_PREP_WP4 zmm24, zmm25, zmm26, zmm27

    vmovapd   zmm8,  zmm0
    vpermt2pd zmm0,  zmm12, zmm1
    vpermt2pd zmm8,  zmm13, zmm1
    vmovapd   zmm9,  zmm2
    vpermt2pd zmm2,  zmm12, zmm3
    vpermt2pd zmm9,  zmm13, zmm3
    vmovapd   zmm10, zmm4
    vpermt2pd zmm4,  zmm12, zmm5
    vpermt2pd zmm10, zmm13, zmm5
    vmovapd   zmm11, zmm6
    vpermt2pd zmm6,  zmm12, zmm7
    vpermt2pd zmm11, zmm13, zmm7

    shr  rax, 1
    vbroadcastf64x4 zmm1, [rsi + 8*rax + 0]
    vbroadcastf64x4 zmm3, [rsi + 8*rax + 32]
    vbroadcastf64x4 zmm5, [rsi + 8*rax + 64]
    vbroadcastf64x4 zmm7, [rsi + 8*rax + 96]
    vshufpd zmm1, zmm1, zmm1, 0xF0
    vshufpd zmm3, zmm3, zmm3, 0xF0
    vshufpd zmm5, zmm5, zmm5, 0xF0
    vshufpd zmm7, zmm7, zmm7, 0xF0

    NTT_DIT4_SHOUP zmm0, zmm8, zmm24, zmm20, zmm2, zmm9, zmm25, zmm21, zmm4, zmm10, zmm26, zmm22, zmm6, zmm11, zmm27, zmm23

    NTT_PREP_WP4 zmm1, zmm3, zmm5, zmm7
    vunpcklpd zmm24, zmm0, zmm8
    vunpckhpd zmm8,  zmm0, zmm8
    vunpcklpd zmm25, zmm2, zmm9
    vunpckhpd zmm9,  zmm2, zmm9
    vunpcklpd zmm26, zmm4, zmm10
    vunpckhpd zmm10, zmm4, zmm10
    vunpcklpd zmm27, zmm6, zmm11
    vunpckhpd zmm11, zmm6, zmm11

    shr  rax, 1
    vbroadcastf64x2 zmm0, [rsi + 8*rax + 0]
    vbroadcastf64x2 zmm2, [rsi + 8*rax + 16]
    vbroadcastf64x2 zmm4, [rsi + 8*rax + 32]
    vbroadcastf64x2 zmm6, [rsi + 8*rax + 48]
    vshufpd zmm0, zmm0, zmm0, 0xCC
    vshufpd zmm2, zmm2, zmm2, 0xCC
    vshufpd zmm4, zmm4, zmm4, 0xCC
    vshufpd zmm6, zmm6, zmm6, 0xCC

    NTT_DIT4_SHOUP zmm24, zmm8, zmm1, zmm20, zmm25, zmm9, zmm3, zmm21, zmm26, zmm10, zmm5, zmm22, zmm27, zmm11, zmm7, zmm23
    ZMM_RED4_SIGNED zmm24, zmm25, zmm26, zmm27

    NTT_PREP_WP4 zmm0, zmm2, zmm4, zmm6
    vshuff64x2 zmm1,  zmm24, zmm8,  0x44
    vshuff64x2 zmm8,  zmm24, zmm8,  0xEE
    vshuff64x2 zmm3,  zmm25, zmm9,  0x44
    vshuff64x2 zmm9,  zmm25, zmm9,  0xEE
    vshuff64x2 zmm5,  zmm26, zmm10, 0x44
    vshuff64x2 zmm10, zmm26, zmm10, 0xEE
    vshuff64x2 zmm7,  zmm27, zmm11, 0x44
    vshuff64x2 zmm11, zmm27, zmm11, 0xEE

    shr  rax, 1
    vbroadcastsd zmm24, [rsi + 8*rax + 0]
    vbroadcastsd zmm25, [rsi + 8*rax + 8]
    vbroadcastsd zmm26, [rsi + 8*rax + 16]
    vbroadcastsd zmm27, [rsi + 8*rax + 24]

    NTT_DIT4_SHOUP zmm1, zmm8, zmm0, zmm20, zmm3, zmm9, zmm2, zmm21, zmm5, zmm10, zmm4, zmm22, zmm7, zmm11, zmm6, zmm23

    NTT_PREP_WP4 zmm24, zmm25, zmm26, zmm27
    vshuff64x2 zmm0, zmm1, zmm8,  0x88
    vshuff64x2 zmm1, zmm1, zmm8,  0xDD
    vshuff64x2 zmm2, zmm3, zmm9,  0x88
    vshuff64x2 zmm3, zmm3, zmm9,  0xDD
    vshuff64x2 zmm4, zmm5, zmm10, 0x88
    vshuff64x2 zmm5, zmm5, zmm10, 0xDD
    vshuff64x2 zmm6, zmm7, zmm11, 0x88
    vshuff64x2 zmm7, zmm7, zmm11, 0xDD
    NTT_DIT4_SHOUP zmm0, zmm1, zmm24, zmm20, zmm2, zmm3, zmm25, zmm21, zmm4, zmm5, zmm26, zmm22, zmm6, zmm7, zmm27, zmm23
    ZMM_RED4_SIGNED zmm0, zmm2, zmm4, zmm6
.endm

    // 1a. In-register Radix-128 (m = 1..64 for sub_n = 128, 2048), Radix-64 (m = 1..32 for sub_n = 64, 512, 1024),
    //     or Radix-16 (m = 1..8) bottom DIT pass
    tzcnt r15, rdx
    cmp  r15, 6
    jb   .Lnttinv_bot4_start
    cmp  r15, 9
    je   .Lnttinv_bot6_entry
    mov  eax, r15d
    and  eax, 3
    cmp  eax, 2
    je   .Lnttinv_bot6_entry
    cmp  eax, 3
    je   .Lnttinv_bot7_entry
    jmp  .Lnttinv_bot4_start

.Lnttinv_bot7_entry:
    mov  r12, rdx
    shr  r12, 7                         // b64_local = sub_n / 128 >= 1
    mov  r13, [rsp + 40]
    imul r13, r12                       // tw_b64_base = tw_root * b64_local
    xor  r8d, r8d                       // b64 = 0 .. r12 - 1
    vmovdqa64 zmm12, [rip + .Lconst_idx_bot_inv_lo]
    vmovdqa64 zmm13, [rip + .Lconst_idx_bot_inv_hi]

.p2align 6
.Lnttinv_bot7_loop:
    mov  r9,  r8
    shl  r9,  10                        // b64 * 1024 bytes
    lea  r10, [rdi + r9]
    lea  rcx, [r13 + r8]                // k64

    mov  rax, rcx
    shl  rax, 6                         // 64 * k64 (m = 1 element index for Half 0)
    NTT_INV_BOT4_HALF 0, r9
    vmovapd [rsp + 128], zmm0
    vmovapd [rsp + 192], zmm1
    vmovapd [rsp + 256], zmm2
    vmovapd [rsp + 320], zmm3
    vmovapd [rsp + 384], zmm4
    vmovapd [rsp + 448], zmm5
    vmovapd [rsp + 512], zmm6
    vmovapd [rsp + 576], zmm7

    mov  rax, rcx
    shl  rax, 6
    add  rax, 32                        // 64 * k64 + 32 (m = 1 element index for Half 1)
    NTT_INV_BOT4_HALF 512, r9

    vmovapd zmm8,  zmm0
    vmovapd zmm9,  zmm1
    vmovapd zmm10, zmm2
    vmovapd zmm11, zmm3
    vmovapd zmm12, zmm4
    vmovapd zmm13, zmm5
    vmovapd zmm14, zmm6
    vmovapd zmm15, zmm7
    vmovapd zmm0,  [rsp + 128]
    vmovapd zmm1,  [rsp + 192]
    vmovapd zmm2,  [rsp + 256]
    vmovapd zmm3,  [rsp + 320]
    vmovapd zmm4,  [rsp + 384]
    vmovapd zmm5,  [rsp + 448]
    vmovapd zmm6,  [rsp + 512]
    vmovapd zmm7,  [rsp + 576]

    shl  rcx, 3                         // 8 * k64 (byte offset into rsi)
    vbroadcastsd zmm24, [rsi + 4*rcx + 0]
    vbroadcastsd zmm25, [rsi + 4*rcx + 8]
    vmulpd       zmm26, zmm24, zmm30
    vmulpd       zmm27, zmm25, zmm30
    NTT_DIT4_SHOUP zmm0, zmm2,  zmm24, zmm26, zmm1, zmm3,  zmm24, zmm26, zmm4, zmm6,  zmm25, zmm27, zmm5, zmm7,  zmm25, zmm27
    vbroadcastsd zmm24, [rsi + 4*rcx + 16]
    vbroadcastsd zmm25, [rsi + 4*rcx + 24]
    vmulpd       zmm26, zmm24, zmm30
    vmulpd       zmm27, zmm25, zmm30
    NTT_DIT4_SHOUP zmm8, zmm10, zmm24, zmm26, zmm9, zmm11, zmm24, zmm26, zmm12, zmm14, zmm25, zmm27, zmm13, zmm15, zmm25, zmm27

    vbroadcastsd zmm24, [rsi + 2*rcx + 0]
    vbroadcastsd zmm25, [rsi + 2*rcx + 8]
    vmulpd       zmm26, zmm24, zmm30
    vmulpd       zmm27, zmm25, zmm30
    NTT_DIT4_SHOUP zmm0, zmm4,  zmm24, zmm26, zmm1, zmm5,  zmm24, zmm26, zmm2, zmm6,  zmm24, zmm26, zmm3, zmm7,  zmm24, zmm26
    NTT_DIT4_SHOUP zmm8, zmm12, zmm25, zmm27, zmm9, zmm13, zmm25, zmm27, zmm10, zmm14, zmm25, zmm27, zmm11, zmm15, zmm25, zmm27

    vbroadcastsd zmm24, [rsi + rcx]
    vmulpd       zmm26, zmm24, zmm30
    NTT_DIT4_SHOUP zmm0, zmm8,  zmm24, zmm26, zmm1, zmm9,  zmm24, zmm26, zmm2, zmm10, zmm24, zmm26, zmm3, zmm11, zmm24, zmm26
    NTT_DIT4_SHOUP zmm4, zmm12, zmm24, zmm26, zmm5, zmm13, zmm24, zmm26, zmm6, zmm14, zmm24, zmm26, zmm7, zmm15, zmm24, zmm26

    cmp  rdx, 128
    jne  .Lnttinv_bot7_noscl
    cmp  qword ptr [rsp + 24], 1
    ja   .Lnttinv_bot7_noscl
    cmp  qword ptr [rsp + 48], 0
    je   .Lnttinv_bot7_n128_canon
    ZMM_RED4_SIGNED  zmm0,  zmm1,  zmm2,  zmm3
    ZMM_RED4_SIGNED  zmm4,  zmm5,  zmm6,  zmm7
    ZMM_SCALE4_SHOUP zmm0,  zmm1,  zmm2,  zmm3,  qword ptr [rsp + 1120]{1to8}
    ZMM_SCALE4_SHOUP zmm4,  zmm5,  zmm6,  zmm7,  qword ptr [rsp + 1120]{1to8}
    ZMM_SCALE4_SHOUP zmm8,  zmm9,  zmm10, zmm11, qword ptr [rsp + 1120]{1to8}
    ZMM_SCALE4_SHOUP zmm12, zmm13, zmm14, zmm15, qword ptr [rsp + 1120]{1to8}
    vmovupd [r10 + 0],   zmm0
    vmovupd [r10 + 64],  zmm1
    vmovupd [r10 + 128], zmm2
    vmovupd [r10 + 192], zmm3
    vmovupd [r10 + 256], zmm4
    vmovupd [r10 + 320], zmm5
    vmovupd [r10 + 384], zmm6
    vmovupd [r10 + 448], zmm7
    vmovupd [r10 + 512], zmm8
    vmovupd [r10 + 576], zmm9
    vmovupd [r10 + 640], zmm10
    vmovupd [r10 + 704], zmm11
    vmovupd [r10 + 768], zmm12
    vmovupd [r10 + 832], zmm13
    vmovupd [r10 + 896], zmm14
    vmovupd [r10 + 960], zmm15
    jmp  .Lnttinv_done

.Lnttinv_bot7_n128_canon:
    ZMM_CANON4   zmm0,  zmm1,  zmm2,  zmm3
    ZMM_CANON4   zmm4,  zmm5,  zmm6,  zmm7
    ZMM_FIX_NEG4 zmm8,  zmm9,  zmm10, zmm11
    ZMM_FIX_NEG4 zmm12, zmm13, zmm14, zmm15
    vmovupd [r10 + 0],   zmm0
    vmovupd [r10 + 64],  zmm1
    vmovupd [r10 + 128], zmm2
    vmovupd [r10 + 192], zmm3
    vmovupd [r10 + 256], zmm4
    vmovupd [r10 + 320], zmm5
    vmovupd [r10 + 384], zmm6
    vmovupd [r10 + 448], zmm7
    vmovupd [r10 + 512], zmm8
    vmovupd [r10 + 576], zmm9
    vmovupd [r10 + 640], zmm10
    vmovupd [r10 + 704], zmm11
    vmovupd [r10 + 768], zmm12
    vmovupd [r10 + 832], zmm13
    vmovupd [r10 + 896], zmm14
    vmovupd [r10 + 960], zmm15
    jmp  .Lnttinv_done

.Lnttinv_bot7_noscl:
    ZMM_RED4_SIGNED zmm0, zmm1, zmm2, zmm3
    ZMM_RED4_SIGNED zmm4, zmm5, zmm6, zmm7
    vmovupd [r10 + 0],   zmm0
    vmovupd [r10 + 64],  zmm1
    vmovupd [r10 + 128], zmm2
    vmovupd [r10 + 192], zmm3
    vmovupd [r10 + 256], zmm4
    vmovupd [r10 + 320], zmm5
    vmovupd [r10 + 384], zmm6
    vmovupd [r10 + 448], zmm7
    vmovupd [r10 + 512], zmm8
    vmovupd [r10 + 576], zmm9
    vmovupd [r10 + 640], zmm10
    vmovupd [r10 + 704], zmm11
    vmovupd [r10 + 768], zmm12
    vmovupd [r10 + 832], zmm13
    vmovupd [r10 + 896], zmm14
    vmovupd [r10 + 960], zmm15

    vmovdqa64 zmm12, [rip + .Lconst_idx_bot_inv_lo]
    vmovdqa64 zmm13, [rip + .Lconst_idx_bot_inv_hi]
    inc  r8
    cmp  r8, r12
    jb   .Lnttinv_bot7_loop

    sub  r15, 7
    jz   .Lnttinv_next_sub
    mov  r13, 128
    mov  r12, rdx
    shr  r12, 8
    jmp  .Lnttinv_r16_check

.Lnttinv_bot6_entry:
    mov  r12, rdx
    shr  r12, 4                         // b8_local = sub_n / 16 (multiple of 4)
    mov  r13, [rsp + 40]
    imul r13, r12                       // tw_b8_base = tw_root * b8_local
    xor  r8d, r8d                       // b8 = 0
    vmovdqa64 zmm12, [rip + .Lconst_idx_bot_inv_lo]
    vmovdqa64 zmm13, [rip + .Lconst_idx_bot_inv_hi]

.p2align 6
.Lnttinv_bot6_loop:
    mov  rax, r8
    shl  rax, 7
    lea  r10, [rdi + rax]
    test r11, r11
    jnz  .Lnttinv_bot6_pmul
    vmovupd zmm0, [r10 + 0]
    vmovupd zmm1, [r10 + 64]
    vmovupd zmm2, [r10 + 128]
    vmovupd zmm3, [r10 + 192]
    vmovupd zmm4, [r10 + 256]
    vmovupd zmm5, [r10 + 320]
    vmovupd zmm6, [r10 + 384]
    vmovupd zmm7, [r10 + 448]
    jmp  .Lnttinv_bot6_tw
.Lnttinv_bot6_pmul:
    ZMM_PMUL8_MEM_SIGNED r10, r11 + rax
.Lnttinv_bot6_tw:
    lea  rax, [r13 + r8]
    shl  rax, 3
    vmovupd    zmm24, [rsi + 8*rax + 0]
    vmovupd    zmm25, [rsi + 8*rax + 64]
    vmovupd    zmm26, [rsi + 8*rax + 128]
    vmovupd    zmm27, [rsi + 8*rax + 192]
    vshuff64x2 zmm24, zmm24, zmm24, 0xD8
    vshuff64x2 zmm25, zmm25, zmm25, 0xD8
    vshuff64x2 zmm26, zmm26, zmm26, 0xD8
    vshuff64x2 zmm27, zmm27, zmm27, 0xD8
    NTT_PREP_WP4 zmm24, zmm25, zmm26, zmm27

    vmovapd   zmm8,  zmm0
    vpermt2pd zmm0,  zmm12, zmm1
    vpermt2pd zmm8,  zmm13, zmm1
    vmovapd   zmm9,  zmm2
    vpermt2pd zmm2,  zmm12, zmm3
    vpermt2pd zmm9,  zmm13, zmm3
    vmovapd   zmm10, zmm4
    vpermt2pd zmm4,  zmm12, zmm5
    vpermt2pd zmm10, zmm13, zmm5
    vmovapd   zmm11, zmm6
    vpermt2pd zmm6,  zmm12, zmm7
    vpermt2pd zmm11, zmm13, zmm7

    shr  rax, 1
    vbroadcastf64x4 zmm1, [rsi + 8*rax + 0]
    vbroadcastf64x4 zmm3, [rsi + 8*rax + 32]
    vbroadcastf64x4 zmm5, [rsi + 8*rax + 64]
    vbroadcastf64x4 zmm7, [rsi + 8*rax + 96]
    vshufpd zmm1, zmm1, zmm1, 0xF0
    vshufpd zmm3, zmm3, zmm3, 0xF0
    vshufpd zmm5, zmm5, zmm5, 0xF0
    vshufpd zmm7, zmm7, zmm7, 0xF0

    NTT_DIT4_SHOUP zmm0, zmm8, zmm24, zmm20, zmm2, zmm9, zmm25, zmm21, zmm4, zmm10, zmm26, zmm22, zmm6, zmm11, zmm27, zmm23

    NTT_PREP_WP4 zmm1, zmm3, zmm5, zmm7
    vunpcklpd zmm24, zmm0, zmm8
    vunpckhpd zmm8,  zmm0, zmm8
    vunpcklpd zmm25, zmm2, zmm9
    vunpckhpd zmm9,  zmm2, zmm9
    vunpcklpd zmm26, zmm4, zmm10
    vunpckhpd zmm10, zmm4, zmm10
    vunpcklpd zmm27, zmm6, zmm11
    vunpckhpd zmm11, zmm6, zmm11

    shr  rax, 1
    vbroadcastf64x2 zmm0, [rsi + 8*rax + 0]
    vbroadcastf64x2 zmm2, [rsi + 8*rax + 16]
    vbroadcastf64x2 zmm4, [rsi + 8*rax + 32]
    vbroadcastf64x2 zmm6, [rsi + 8*rax + 48]
    vshufpd zmm0, zmm0, zmm0, 0xCC
    vshufpd zmm2, zmm2, zmm2, 0xCC
    vshufpd zmm4, zmm4, zmm4, 0xCC
    vshufpd zmm6, zmm6, zmm6, 0xCC

    NTT_DIT4_SHOUP zmm24, zmm8, zmm1, zmm20, zmm25, zmm9, zmm3, zmm21, zmm26, zmm10, zmm5, zmm22, zmm27, zmm11, zmm7, zmm23
    ZMM_RED4_SIGNED zmm24, zmm25, zmm26, zmm27

    NTT_PREP_WP4 zmm0, zmm2, zmm4, zmm6
    vshuff64x2 zmm1,  zmm24, zmm8,  0x44
    vshuff64x2 zmm8,  zmm24, zmm8,  0xEE
    vshuff64x2 zmm3,  zmm25, zmm9,  0x44
    vshuff64x2 zmm9,  zmm25, zmm9,  0xEE
    vshuff64x2 zmm5,  zmm26, zmm10, 0x44
    vshuff64x2 zmm10, zmm26, zmm10, 0xEE
    vshuff64x2 zmm7,  zmm27, zmm11, 0x44
    vshuff64x2 zmm11, zmm27, zmm11, 0xEE

    shr  rax, 1
    vbroadcastsd zmm24, [rsi + 8*rax + 0]
    vbroadcastsd zmm25, [rsi + 8*rax + 8]
    vbroadcastsd zmm26, [rsi + 8*rax + 16]
    vbroadcastsd zmm27, [rsi + 8*rax + 24]

    NTT_DIT4_SHOUP zmm1, zmm8, zmm0, zmm20, zmm3, zmm9, zmm2, zmm21, zmm5, zmm10, zmm4, zmm22, zmm7, zmm11, zmm6, zmm23

    NTT_PREP_WP4 zmm24, zmm25, zmm26, zmm27
    vshuff64x2 zmm0, zmm1, zmm8,  0x88
    vshuff64x2 zmm1, zmm1, zmm8,  0xDD
    vshuff64x2 zmm2, zmm3, zmm9,  0x88
    vshuff64x2 zmm3, zmm3, zmm9,  0xDD
    vshuff64x2 zmm4, zmm5, zmm10, 0x88
    vshuff64x2 zmm5, zmm5, zmm10, 0xDD
    vshuff64x2 zmm6, zmm7, zmm11, 0x88
    vshuff64x2 zmm7, zmm7, zmm11, 0xDD
    NTT_DIT4_SHOUP zmm0, zmm1, zmm24, zmm20, zmm2, zmm3, zmm25, zmm21, zmm4, zmm5, zmm26, zmm22, zmm6, zmm7, zmm27, zmm23
    ZMM_RED4_SIGNED zmm0, zmm2, zmm4, zmm6

    // Stage m = 16 & Stage m = 32:
    shr  rax, 1
    vbroadcastsd zmm24, [rsi + 8*rax + 0]
    vbroadcastsd zmm25, [rsi + 8*rax + 8]
    vmulpd       zmm8,  zmm24, zmm30
    vmulpd       zmm9,  zmm25, zmm30
    shr  rax, 1
    vbroadcastsd zmm26, [rsi + 8*rax]
    vmulpd       zmm10, zmm26, zmm30
    NTT_DIT4_SHOUP zmm0, zmm2, zmm24, zmm8,  zmm1, zmm3, zmm24, zmm8,  zmm4, zmm6, zmm25, zmm9,  zmm5, zmm7, zmm25, zmm9
    NTT_DIT4_SHOUP zmm0, zmm4, zmm26, zmm10, zmm1, zmm5, zmm26, zmm10, zmm2, zmm6, zmm26, zmm10, zmm3, zmm7, zmm26, zmm10

    cmp  rdx, 64
    jne  .Lnttinv_bot6_noscl
    cmp  qword ptr [rsp + 24], 1
    ja   .Lnttinv_bot6_noscl
    cmp  qword ptr [rsp + 48], 0
    je   .Lnttinv_bot6_n64_canon
    ZMM_RED4_SIGNED  zmm0, zmm1, zmm2, zmm3
    ZMM_SCALE4_SHOUP zmm0, zmm1, zmm2, zmm3, qword ptr [rsp + 1120]{1to8}
    ZMM_SCALE4_SHOUP zmm4, zmm5, zmm6, zmm7, qword ptr [rsp + 1120]{1to8}
    vmovupd [r10 + 0],   zmm0
    vmovupd [r10 + 64],  zmm1
    vmovupd [r10 + 128], zmm2
    vmovupd [r10 + 192], zmm3
    vmovupd [r10 + 256], zmm4
    vmovupd [r10 + 320], zmm5
    vmovupd [r10 + 384], zmm6
    vmovupd [r10 + 448], zmm7
    jmp  .Lnttinv_done

.Lnttinv_bot6_n64_canon:
    ZMM_CANON4 zmm0, zmm1, zmm2, zmm3
    ZMM_CANON4 zmm4, zmm5, zmm6, zmm7
    vmovupd [r10 + 0],   zmm0
    vmovupd [r10 + 64],  zmm1
    vmovupd [r10 + 128], zmm2
    vmovupd [r10 + 192], zmm3
    vmovupd [r10 + 256], zmm4
    vmovupd [r10 + 320], zmm5
    vmovupd [r10 + 384], zmm6
    vmovupd [r10 + 448], zmm7
    jmp  .Lnttinv_done

.Lnttinv_bot6_noscl:
    ZMM_RED4_SIGNED zmm0, zmm1, zmm2, zmm3
    vmovupd [r10 + 0],   zmm0
    vmovupd [r10 + 64],  zmm1
    vmovupd [r10 + 128], zmm2
    vmovupd [r10 + 192], zmm3
    vmovupd [r10 + 256], zmm4
    vmovupd [r10 + 320], zmm5
    vmovupd [r10 + 384], zmm6
    vmovupd [r10 + 448], zmm7

    add  r8, 4
    cmp  r8, r12
    jb   .Lnttinv_bot6_loop

    sub  r15, 6
    jz   .Lnttinv_next_sub
    mov  r13, 64
    mov  r12, rdx
    shr  r12, 7
    jmp  .Lnttinv_r16_check

.Lnttinv_bot4_start:
    mov  r12, rdx
    shr  r12, 4                         // b8_local = sub_n / 16
    mov  r13, [rsp + 40]
    imul r13, r12                       // tw_b8_base = tw_root * b8_local
    xor  r8d, r8d                       // b8 = 0
    mov  r9,  r12
    and  r9,  -4
    cmp  r9,  4
    jb   .Lnttinv_bot1_check

    vmovdqa64 zmm12, [rip + .Lconst_idx_bot_inv_lo]
    vmovdqa64 zmm13, [rip + .Lconst_idx_bot_inv_hi]

.p2align 4
.Lnttinv_bot4_loop:
    mov  rax, r8
    shl  rax, 7
    lea  r10, [rdi + rax]
    test r11, r11
    jnz  .Lnttinv_bot4_pmul
    vmovupd zmm0, [r10 + 0]
    vmovupd zmm1, [r10 + 64]
    vmovupd zmm2, [r10 + 128]
    vmovupd zmm3, [r10 + 192]
    vmovupd zmm4, [r10 + 256]
    vmovupd zmm5, [r10 + 320]
    vmovupd zmm6, [r10 + 384]
    vmovupd zmm7, [r10 + 448]
    jmp  .Lnttinv_bot4_tw
.Lnttinv_bot4_pmul:
    ZMM_PMUL8_MEM_SIGNED r10, r11 + rax
.Lnttinv_bot4_tw:
    // Stage m = 1 twiddles + WP prepared ahead of permutes!
    lea  rax, [r13 + r8]
    shl  rax, 3
    vmovupd    zmm24, [rsi + 8*rax + 0]
    vmovupd    zmm25, [rsi + 8*rax + 64]
    vmovupd    zmm26, [rsi + 8*rax + 128]
    vmovupd    zmm27, [rsi + 8*rax + 192]
    vshuff64x2 zmm24, zmm24, zmm24, 0xD8
    vshuff64x2 zmm25, zmm25, zmm25, 0xD8
    vshuff64x2 zmm26, zmm26, zmm26, 0xD8
    vshuff64x2 zmm27, zmm27, zmm27, 0xD8
    NTT_PREP_WP4 zmm24, zmm25, zmm26, zmm27

    vmovapd   zmm8,  zmm0
    vpermt2pd zmm0,  zmm12, zmm1
    vpermt2pd zmm8,  zmm13, zmm1
    vmovapd   zmm9,  zmm2
    vpermt2pd zmm2,  zmm12, zmm3
    vpermt2pd zmm9,  zmm13, zmm3
    vmovapd   zmm10, zmm4
    vpermt2pd zmm4,  zmm12, zmm5
    vpermt2pd zmm10, zmm13, zmm5
    vmovapd   zmm11, zmm6
    vpermt2pd zmm6,  zmm12, zmm7
    vpermt2pd zmm11, zmm13, zmm7

    // Preload Stage m = 2 twiddles into now-free zmm1,3,5,7 while m = 1 executes!
    shr  rax, 1
    vbroadcastf64x4 zmm1, [rsi + 8*rax + 0]
    vbroadcastf64x4 zmm3, [rsi + 8*rax + 32]
    vbroadcastf64x4 zmm5, [rsi + 8*rax + 64]
    vbroadcastf64x4 zmm7, [rsi + 8*rax + 96]
    vshufpd zmm1, zmm1, zmm1, 0xF0
    vshufpd zmm3, zmm3, zmm3, 0xF0
    vshufpd zmm5, zmm5, zmm5, 0xF0
    vshufpd zmm7, zmm7, zmm7, 0xF0

    NTT_DIT4_SHOUP zmm0, zmm8, zmm24, zmm20, zmm2, zmm9, zmm25, zmm21, zmm4, zmm10, zmm26, zmm22, zmm6, zmm11, zmm27, zmm23

    // Stage m = 2: prepare WP from zmm1,3,5,7 while unpacking data & preloading m = 4 into zmm0,2,4,6!
    NTT_PREP_WP4 zmm1, zmm3, zmm5, zmm7
    vunpcklpd zmm24, zmm0, zmm8
    vunpckhpd zmm8,  zmm0, zmm8
    vunpcklpd zmm25, zmm2, zmm9
    vunpckhpd zmm9,  zmm2, zmm9
    vunpcklpd zmm26, zmm4, zmm10
    vunpckhpd zmm10, zmm4, zmm10
    vunpcklpd zmm27, zmm6, zmm11
    vunpckhpd zmm11, zmm6, zmm11

    shr  rax, 1
    vbroadcastf64x2 zmm0, [rsi + 8*rax + 0]
    vbroadcastf64x2 zmm2, [rsi + 8*rax + 16]
    vbroadcastf64x2 zmm4, [rsi + 8*rax + 32]
    vbroadcastf64x2 zmm6, [rsi + 8*rax + 48]
    vshufpd zmm0, zmm0, zmm0, 0xCC
    vshufpd zmm2, zmm2, zmm2, 0xCC
    vshufpd zmm4, zmm4, zmm4, 0xCC
    vshufpd zmm6, zmm6, zmm6, 0xCC

    NTT_DIT4_SHOUP zmm24, zmm8, zmm1, zmm20, zmm25, zmm9, zmm3, zmm21, zmm26, zmm10, zmm5, zmm22, zmm27, zmm11, zmm7, zmm23
    ZMM_RED4_SIGNED zmm24, zmm25, zmm26, zmm27

    // Stage m = 4: prepare WP from zmm0,2,4,6 while shuffling data & preloading m = 8 into zmm24..27!
    NTT_PREP_WP4 zmm0, zmm2, zmm4, zmm6
    vshuff64x2 zmm1,  zmm24, zmm8,  0x44
    vshuff64x2 zmm8,  zmm24, zmm8,  0xEE
    vshuff64x2 zmm3,  zmm25, zmm9,  0x44
    vshuff64x2 zmm9,  zmm25, zmm9,  0xEE
    vshuff64x2 zmm5,  zmm26, zmm10, 0x44
    vshuff64x2 zmm10, zmm26, zmm10, 0xEE
    vshuff64x2 zmm7,  zmm27, zmm11, 0x44
    vshuff64x2 zmm11, zmm27, zmm11, 0xEE

    shr  rax, 1
    vbroadcastsd zmm24, [rsi + 8*rax + 0]
    vbroadcastsd zmm25, [rsi + 8*rax + 8]
    vbroadcastsd zmm26, [rsi + 8*rax + 16]
    vbroadcastsd zmm27, [rsi + 8*rax + 24]

    NTT_DIT4_SHOUP zmm1, zmm8, zmm0, zmm20, zmm3, zmm9, zmm2, zmm21, zmm5, zmm10, zmm4, zmm22, zmm7, zmm11, zmm6, zmm23

    // Stage m = 8: prepare WP from zmm24..27 while shuffling data!
    NTT_PREP_WP4 zmm24, zmm25, zmm26, zmm27
    vshuff64x2 zmm0, zmm1, zmm8,  0x88
    vshuff64x2 zmm1, zmm1, zmm8,  0xDD
    vshuff64x2 zmm2, zmm3, zmm9,  0x88
    vshuff64x2 zmm3, zmm3, zmm9,  0xDD
    vshuff64x2 zmm4, zmm5, zmm10, 0x88
    vshuff64x2 zmm5, zmm5, zmm10, 0xDD
    vshuff64x2 zmm6, zmm7, zmm11, 0x88
    vshuff64x2 zmm7, zmm7, zmm11, 0xDD
    NTT_DIT4_SHOUP zmm0, zmm1, zmm24, zmm20, zmm2, zmm3, zmm25, zmm21, zmm4, zmm5, zmm26, zmm22, zmm6, zmm7, zmm27, zmm23
    ZMM_RED4_SIGNED zmm0, zmm2, zmm4, zmm6

    vmovupd [r10 + 0],   zmm0
    vmovupd [r10 + 64],  zmm1
    vmovupd [r10 + 128], zmm2
    vmovupd [r10 + 192], zmm3
    vmovupd [r10 + 256], zmm4
    vmovupd [r10 + 320], zmm5
    vmovupd [r10 + 384], zmm6
    vmovupd [r10 + 448], zmm7

    add  r8, 4
    cmp  r8, r9
    jb   .Lnttinv_bot4_loop

.Lnttinv_bot1_check:
    cmp  r8, r12
    jae  .Lnttinv_top_start
    vmovdqa64 zmm12, [rip + .Lconst_idx_00001111]
    vmovdqa64 zmm13, [rip + .Lconst_idx_00112233]
    vmovdqa64 zmm14, [rip + .Lconst_idx_even]
    vmovdqa64 zmm15, [rip + .Lconst_idx_odd]
    vmovdqa64 zmm26, [rip + .Lconst_idx_interleave_lo]
    vmovdqa64 zmm27, [rip + .Lconst_idx_interleave_hi]
.Lnttinv_bot1_loop:
    mov  rax, r8
    shl  rax, 7
    lea  r10, [rdi + rax]
    vmovupd zmm0, [r10 + 0]
    vmovupd zmm1, [r10 + 64]

    lea  rax, [r13 + r8]
    shl  rax, 3
    vmovupd   zmm24, [rsi + 8*rax]
    vmovapd   zmm8,  zmm0
    vpermt2pd zmm0,  zmm14, zmm1
    vpermt2pd zmm8,  zmm15, zmm1
    NTT_DIT1_LAZY zmm0, zmm8, zmm24
    vmovapd   zmm1,  zmm0
    vpermt2pd zmm0,  zmm26, zmm8
    vpermt2pd zmm1,  zmm27, zmm8

    lea  rax, [r13 + r8]
    shl  rax, 2
    vmovupd ymm24, [rsi + 8*rax]
    vpermq  zmm24, zmm13, zmm24
    vshuff64x2 zmm8, zmm0, zmm1, 0x88
    vshuff64x2 zmm1, zmm0, zmm1, 0xDD
    NTT_DIT1_LAZY zmm8, zmm1, zmm24
    ZMM_RED1_SIGNED zmm8
    vshuff64x2 zmm0, zmm8, zmm1, 0x44
    vshuff64x2 zmm1, zmm8, zmm1, 0xEE
    vshuff64x2 zmm0, zmm0, zmm0, 0xD8
    vshuff64x2 zmm1, zmm1, zmm1, 0xD8

    lea  rax, [r13 + r8]
    add  rax, rax
    vmovupd xmm24, [rsi + 8*rax]
    vpermq  zmm24, zmm12, zmm24
    vshuff64x2 zmm8, zmm0, zmm1, 0x44
    vshuff64x2 zmm1, zmm0, zmm1, 0xEE
    NTT_DIT1_LAZY zmm8, zmm1, zmm24
    vshuff64x2 zmm0, zmm8, zmm1, 0x44
    vshuff64x2 zmm1, zmm8, zmm1, 0xEE

    lea  rax, [r13 + r8]
    vbroadcastsd zmm24, [rsi + 8*rax]
    NTT_DIT1_LAZY zmm0, zmm1, zmm24
    ZMM_RED2_SIGNED zmm0, zmm1

    vmovupd [r10 + 0],  zmm0
    vmovupd [r10 + 64], zmm1
    inc  r8
    cmp  r8, r12
    jb   .Lnttinv_bot1_loop

    // 1b. Sub-block DIT passes starting at m = 16 inside L1d (s = 16 -> s_bytes = 128 B!)
.Lnttinv_top_start:
    tzcnt r15, rdx
    sub  r15, 4                         // rem_stages inside sub-block
    mov  r13, 16                        // s = m = 16
    mov  r12, rdx
    shr  r12, 5                         // b_local = sub_n / 32

.Lnttinv_r16_check:
    cmp  r15, 4
    jb   .Lnttinv_top_rem

    mov  r14, r12
    shr  r14, 3                         // b0_local
    mov  rbx, r13
    shl  rbx, 3                         // s_bytes = 128
    xor  r8d, r8d

.Lnttinv_r16_block:
    mov  [rsp + 56], r8
    mov  rcx, [rsp + 40]
    imul rcx, r14
    add  rcx, r8                        // tw_idx0 = tw_root * b0_local + j_local
    shl  rcx, 3                         // 8 * tw_idx0

    mov  rax, r8
    shl  rax, 4
    imul rax, rbx
    lea  r9,  [rdi + rax]
    mov  r10, r13                       // i_rem = s
    lea  rax, [rbx + 2*rbx]             // 3 * s_bytes

    mov  r11, 0x3FF0000000000000
    cmp  qword ptr [rsi + rcx], r11
    jne  .Lnttinv_r16_prep_gen
    cmp  qword ptr [rsi + 2*rcx], r11
    jne  .Lnttinv_r16_prep_gen
    cmp  qword ptr [rsi + 4*rcx], r11
    jne  .Lnttinv_r16_prep_gen
    vmovsd       xmm20, [rsi + 2*rcx + 8]
    vmovupd      ymm21, [rsi + 4*rcx]
    vmovupd      zmm22, [rsi + 8*rcx]
    vmulsd       xmm20, xmm20, xmm30
    vmulpd       ymm21, ymm21, ymm30
    vmulpd       zmm22, zmm22, zmm30
    vmovsd       [rsp + 88],  xmm20
    vmovapd      [rsp + 96],  ymm21
    vmovapd      [rsp + 128], zmm22
    vbroadcastsd zmm24, [rsi + 4*rcx + 16]
    vbroadcastsd zmm25, [rsi + 4*rcx + 24]
    vmulpd       zmm26, zmm24, zmm30
    vmulpd       zmm27, zmm25, zmm30

.p2align 6
.Lnttinv_r16_vec_w1:
    vmovupd zmm0,  [r9]
    vmovupd zmm1,  [r9 + rbx]
    vmovupd zmm2,  [r9 + 2*rbx]
    vmovupd zmm3,  [r9 + rax]
    lea  r11, [r9 + 4*rbx]
    lea  r8,  [r9 + 8*rbx]
    vmovupd zmm4,  [r11]
    vmovupd zmm5,  [r11 + rbx]
    vmovupd zmm6,  [r11 + 2*rbx]
    vmovupd zmm7,  [r11 + rax]
    vmovupd zmm8,  [r8]
    vmovupd zmm9,  [r8 + rbx]
    vmovupd zmm10, [r8 + 2*rbx]
    vmovupd zmm11, [r8 + rax]
    lea  r11, [r8 + 4*rbx]
    vmovupd zmm12, [r11]
    vmovupd zmm13, [r11 + rbx]
    vmovupd zmm14, [r11 + 2*rbx]
    vmovupd zmm15, [r11 + rax]

    NTT_DIT4_SHOUP_MEM zmm0, zmm1, rsi+8*rcx+0,  rsp+128+0,  zmm2,  zmm3,  rsi+8*rcx+8,  rsp+128+8,  zmm4,  zmm5,  rsi+8*rcx+16, rsp+128+16, zmm6,  zmm7,  rsi+8*rcx+24, rsp+128+24
    NTT_DIT4_SHOUP_MEM zmm8, zmm9, rsi+8*rcx+32, rsp+128+32, zmm10, zmm11, rsi+8*rcx+40, rsp+128+40, zmm12, zmm13, rsi+8*rcx+48, rsp+128+48, zmm14, zmm15, rsi+8*rcx+56, rsp+128+56

    NTT_BFY2_W1        zmm0, zmm2, zmm1, zmm3
    NTT_DIT2_SHOUP_MEM zmm4, zmm6, rsi+4*rcx+8, rsp+96+8, zmm5, zmm7, rsi+4*rcx+8, rsp+96+8
    NTT_DIT4_SHOUP     zmm8, zmm10, zmm24, zmm26, zmm9, zmm11, zmm24, zmm26, zmm12, zmm14, zmm25, zmm27, zmm13, zmm15, zmm25, zmm27
    ZMM_RED4_SIGNED    zmm0, zmm4, zmm8, zmm12

    NTT_BFY4_W1        zmm0, zmm4, zmm1, zmm5, zmm2, zmm6, zmm3, zmm7
    NTT_DIT4_SHOUP_MEM zmm8, zmm12, rsi+2*rcx+8, rsp+88, zmm9, zmm13, rsi+2*rcx+8, rsp+88, zmm10, zmm14, rsi+2*rcx+8, rsp+88, zmm11, zmm15, rsi+2*rcx+8, rsp+88
    NTT_BFY4_W1        zmm0, zmm8,  zmm1, zmm9,  zmm2, zmm10, zmm3, zmm11
    NTT_BFY4_W1        zmm4, zmm12, zmm5, zmm13, zmm6, zmm14, zmm7, zmm15

    ZMM_RED4_SIGNED zmm0,  zmm1,  zmm2,  zmm3
    ZMM_RED4_SIGNED zmm4,  zmm5,  zmm6,  zmm7
    ZMM_RED4_SIGNED zmm8,  zmm9,  zmm10, zmm11
    ZMM_RED4_SIGNED zmm12, zmm13, zmm14, zmm15

    cmp  r15, 4
    jne  .Lnttinv_r16_w1_store
    cmp  qword ptr [rsp + 24], 1
    ja   .Lnttinv_r16_w1_store
    cmp  qword ptr [rsp + 48], 0
    je   .Lnttinv_r16_w1_canon
    ZMM_SCALE4_SHOUP zmm0,  zmm1,  zmm2,  zmm3,  qword ptr [rsp + 1120]{1to8}
    ZMM_SCALE4_SHOUP zmm4,  zmm5,  zmm6,  zmm7,  qword ptr [rsp + 1120]{1to8}
    ZMM_SCALE4_SHOUP zmm8,  zmm9,  zmm10, zmm11, qword ptr [rsp + 1120]{1to8}
    ZMM_SCALE4_SHOUP zmm12, zmm13, zmm14, zmm15, qword ptr [rsp + 1120]{1to8}
    jmp  .Lnttinv_r16_w1_store
.Lnttinv_r16_w1_canon:
    vcmppd k1, zmm0,  zmm31, 1
    vcmppd k2, zmm1,  zmm31, 1
    vcmppd k3, zmm2,  zmm31, 1
    vcmppd k4, zmm3,  zmm31, 1
    vaddpd zmm0  {k1}, zmm0,  zmm29
    vaddpd zmm1  {k2}, zmm1,  zmm29
    vaddpd zmm2  {k3}, zmm2,  zmm29
    vaddpd zmm3  {k4}, zmm3,  zmm29
    vcmppd k1, zmm4,  zmm31, 1
    vcmppd k2, zmm5,  zmm31, 1
    vcmppd k3, zmm6,  zmm31, 1
    vcmppd k4, zmm7,  zmm31, 1
    vaddpd zmm4  {k1}, zmm4,  zmm29
    vaddpd zmm5  {k2}, zmm5,  zmm29
    vaddpd zmm6  {k3}, zmm6,  zmm29
    vaddpd zmm7  {k4}, zmm7,  zmm29
    vcmppd k1, zmm8,  zmm31, 1
    vcmppd k2, zmm9,  zmm31, 1
    vcmppd k3, zmm10, zmm31, 1
    vcmppd k4, zmm11, zmm31, 1
    vaddpd zmm8  {k1}, zmm8,  zmm29
    vaddpd zmm9  {k2}, zmm9,  zmm29
    vaddpd zmm10 {k3}, zmm10, zmm29
    vaddpd zmm11 {k4}, zmm11, zmm29
    vcmppd k1, zmm12, zmm31, 1
    vcmppd k2, zmm13, zmm31, 1
    vcmppd k3, zmm14, zmm31, 1
    vcmppd k4, zmm15, zmm31, 1
    vaddpd zmm12 {k1}, zmm12, zmm29
    vaddpd zmm13 {k2}, zmm13, zmm29
    vaddpd zmm14 {k3}, zmm14, zmm29
    vaddpd zmm15 {k4}, zmm15, zmm29

.Lnttinv_r16_w1_store:
    vmovupd [r9],         zmm0
    vmovupd [r9 + rbx],   zmm1
    vmovupd [r9 + 2*rbx], zmm2
    vmovupd [r9 + rax],   zmm3
    lea  r11, [r9 + 4*rbx]
    lea  r8,  [r9 + 8*rbx]
    vmovupd [r11],         zmm4
    vmovupd [r11 + rbx],   zmm5
    vmovupd [r11 + 2*rbx], zmm6
    vmovupd [r11 + rax],   zmm7
    vmovupd [r8],          zmm8
    vmovupd [r8 + rbx],    zmm9
    vmovupd [r8 + 2*rbx],  zmm10
    vmovupd [r8 + rax],    zmm11
    lea  r11, [r8 + 4*rbx]
    vmovupd [r11],         zmm12
    vmovupd [r11 + rbx],   zmm13
    vmovupd [r11 + 2*rbx], zmm14
    vmovupd [r11 + rax],   zmm15

    lea  r9, [r9 + 64]
    sub  r10, 8
    jnz  .Lnttinv_r16_vec_w1
    jmp  .Lnttinv_r16_blk_next

.Lnttinv_r16_prep_gen:
    vmovsd       xmm20, [rsi + rcx]
    vmovupd      ymm21, [rsi + 4*rcx]
    vmovupd      zmm22, [rsi + 8*rcx]
    vmulsd       xmm20, xmm20, xmm30
    vmulpd       ymm21, ymm21, ymm30
    vmulpd       zmm22, zmm22, zmm30
    vmovsd       [rsp + 64],  xmm20
    vmovapd      [rsp + 96],  ymm21
    vmovapd      [rsp + 128], zmm22
    vbroadcastsd zmm24, [rsi + 2*rcx + 0]
    vbroadcastsd zmm25, [rsi + 2*rcx + 8]
    vmulpd       zmm26, zmm24, zmm30
    vmulpd       zmm27, zmm25, zmm30

.p2align 6
.Lnttinv_r16_vec:
    vmovupd zmm0,  [r9]
    vmovupd zmm1,  [r9 + rbx]
    vmovupd zmm2,  [r9 + 2*rbx]
    vmovupd zmm3,  [r9 + rax]
    lea  r11, [r9 + 4*rbx]
    lea  r8,  [r9 + 8*rbx]
    vmovupd zmm4,  [r11]
    vmovupd zmm5,  [r11 + rbx]
    vmovupd zmm6,  [r11 + 2*rbx]
    vmovupd zmm7,  [r11 + rax]
    vmovupd zmm8,  [r8]
    vmovupd zmm9,  [r8 + rbx]
    vmovupd zmm10, [r8 + 2*rbx]
    vmovupd zmm11, [r8 + rax]
    lea  r11, [r8 + 4*rbx]
    vmovupd zmm12, [r11]
    vmovupd zmm13, [r11 + rbx]
    vmovupd zmm14, [r11 + 2*rbx]
    vmovupd zmm15, [r11 + rax]

    NTT_DIT4_SHOUP_MEM zmm0, zmm1,  rsi+8*rcx+0,  rsp+128+0,  zmm2,  zmm3,  rsi+8*rcx+8,  rsp+128+8,  zmm4,  zmm5,  rsi+8*rcx+16, rsp+128+16, zmm6,  zmm7,  rsi+8*rcx+24, rsp+128+24
    NTT_DIT4_SHOUP_MEM zmm8, zmm9,  rsi+8*rcx+32, rsp+128+32, zmm10, zmm11, rsi+8*rcx+40, rsp+128+40, zmm12, zmm13, rsi+8*rcx+48, rsp+128+48, zmm14, zmm15, rsi+8*rcx+56, rsp+128+56

    NTT_DIT4_SHOUP_MEM zmm0, zmm2,  rsi+4*rcx+0,  rsp+96+0,   zmm1,  zmm3,  rsi+4*rcx+0,  rsp+96+0,   zmm4,  zmm6,  rsi+4*rcx+8,  rsp+96+8,   zmm5,  zmm7,  rsi+4*rcx+8,  rsp+96+8
    NTT_DIT4_SHOUP_MEM zmm8, zmm10, rsi+4*rcx+16, rsp+96+16,  zmm9,  zmm11, rsi+4*rcx+16, rsp+96+16,  zmm12, zmm14, rsi+4*rcx+24, rsp+96+24,  zmm13, zmm15, rsi+4*rcx+24, rsp+96+24
    ZMM_RED4_SIGNED    zmm0, zmm4, zmm8, zmm12

    NTT_DIT4_SHOUP     zmm0, zmm4,  zmm24, zmm26, zmm1, zmm5,  zmm24, zmm26, zmm2, zmm6,  zmm24, zmm26, zmm3, zmm7,  zmm24, zmm26
    NTT_DIT4_SHOUP     zmm8, zmm12, zmm25, zmm27, zmm9, zmm13, zmm25, zmm27, zmm10, zmm14, zmm25, zmm27, zmm11, zmm15, zmm25, zmm27

    NTT_DIT4_SHOUP_MEM zmm0, zmm8,  rsi+rcx, rsp+64, zmm1, zmm9,  rsi+rcx, rsp+64, zmm2, zmm10, rsi+rcx, rsp+64, zmm3, zmm11, rsi+rcx, rsp+64
    NTT_DIT4_SHOUP_MEM zmm4, zmm12, rsi+rcx, rsp+64, zmm5, zmm13, rsi+rcx, rsp+64, zmm6, zmm14, rsi+rcx, rsp+64, zmm7, zmm15, rsi+rcx, rsp+64

    ZMM_RED4_SIGNED zmm0,  zmm1,  zmm2,  zmm3
    ZMM_RED4_SIGNED zmm4,  zmm5,  zmm6,  zmm7

    cmp  r15, 4
    jne  .Lnttinv_r16_store
    cmp  qword ptr [rsp + 24], 1
    ja   .Lnttinv_r16_store
    cmp  qword ptr [rsp + 48], 0
    je   .Lnttinv_r16_canon
    ZMM_SCALE4_SHOUP zmm0,  zmm1,  zmm2,  zmm3,  qword ptr [rsp + 1120]{1to8}
    ZMM_SCALE4_SHOUP zmm4,  zmm5,  zmm6,  zmm7,  qword ptr [rsp + 1120]{1to8}
    ZMM_SCALE4_SHOUP zmm8,  zmm9,  zmm10, zmm11, qword ptr [rsp + 1120]{1to8}
    ZMM_SCALE4_SHOUP zmm12, zmm13, zmm14, zmm15, qword ptr [rsp + 1120]{1to8}
    jmp  .Lnttinv_r16_store
.Lnttinv_r16_canon:
    vcmppd k1, zmm0,  zmm31, 1
    vcmppd k2, zmm1,  zmm31, 1
    vcmppd k3, zmm2,  zmm31, 1
    vcmppd k4, zmm3,  zmm31, 1
    vaddpd zmm0  {k1}, zmm0,  zmm29
    vaddpd zmm1  {k2}, zmm1,  zmm29
    vaddpd zmm2  {k3}, zmm2,  zmm29
    vaddpd zmm3  {k4}, zmm3,  zmm29
    vcmppd k1, zmm4,  zmm31, 1
    vcmppd k2, zmm5,  zmm31, 1
    vcmppd k3, zmm6,  zmm31, 1
    vcmppd k4, zmm7,  zmm31, 1
    vaddpd zmm4  {k1}, zmm4,  zmm29
    vaddpd zmm5  {k2}, zmm5,  zmm29
    vaddpd zmm6  {k3}, zmm6,  zmm29
    vaddpd zmm7  {k4}, zmm7,  zmm29
    vcmppd k1, zmm8,  zmm31, 1
    vcmppd k2, zmm9,  zmm31, 1
    vcmppd k3, zmm10, zmm31, 1
    vcmppd k4, zmm11, zmm31, 1
    vaddpd zmm8  {k1}, zmm8,  zmm29
    vaddpd zmm9  {k2}, zmm9,  zmm29
    vaddpd zmm10 {k3}, zmm10, zmm29
    vaddpd zmm11 {k4}, zmm11, zmm29
    vcmppd k1, zmm12, zmm31, 1
    vcmppd k2, zmm13, zmm31, 1
    vcmppd k3, zmm14, zmm31, 1
    vcmppd k4, zmm15, zmm31, 1
    vaddpd zmm12 {k1}, zmm12, zmm29
    vaddpd zmm13 {k2}, zmm13, zmm29
    vaddpd zmm14 {k3}, zmm14, zmm29
    vaddpd zmm15 {k4}, zmm15, zmm29

.Lnttinv_r16_store:
    vmovupd [r9],         zmm0
    vmovupd [r9 + rbx],   zmm1
    vmovupd [r9 + 2*rbx], zmm2
    vmovupd [r9 + rax],   zmm3
    lea  r11, [r9 + 4*rbx]
    lea  r8,  [r9 + 8*rbx]
    vmovupd [r11],         zmm4
    vmovupd [r11 + rbx],   zmm5
    vmovupd [r11 + 2*rbx], zmm6
    vmovupd [r11 + rax],   zmm7
    vmovupd [r8],          zmm8
    vmovupd [r8 + rbx],    zmm9
    vmovupd [r8 + 2*rbx],  zmm10
    vmovupd [r8 + rax],    zmm11
    lea  r11, [r8 + 4*rbx]
    vmovupd [r11],         zmm12
    vmovupd [r11 + rbx],   zmm13
    vmovupd [r11 + 2*rbx], zmm14
    vmovupd [r11 + rax],   zmm15

    lea  r9, [r9 + 64]
    sub  r10, 8
    jnz  .Lnttinv_r16_vec

.Lnttinv_r16_blk_next:
    mov  r8, [rsp + 56]
    inc  r8
    cmp  r8, r14
    jb   .Lnttinv_r16_block

    shl  r13, 4
    shr  r12, 4
    sub  r15, 4
    jnz  .Lnttinv_r16_check
    cmp  qword ptr [rsp + 24], 1
    jbe  .Lnttinv_done
    jmp  .Lnttinv_next_sub

.Lnttinv_top_rem:
    cmp  r15, 3
    jne  .Lnttinv_top_r4
    mov  rbx, r13
    shl  rbx, 3                         // s_bytes (s >= 16, multiple of 16)
    lea  rax, [rbx + 2*rbx]             // 3 * s_bytes
    mov  rcx, [rsp + 40]
    shl  rcx, 3                         // 8 * tw_root (b0_local == 1)
    mov  r9,  rdi
    mov  r10, r13                       // i_rem = s

    mov  r11, 0x3FF0000000000000
    cmp  qword ptr [rsi + rcx], r11
    jne  .Lnttinv_r8_gen
    cmp  qword ptr [rsi + 2*rcx], r11
    jne  .Lnttinv_r8_gen
    cmp  qword ptr [rsi + 4*rcx], r11
    jne  .Lnttinv_r8_gen

    cmp  qword ptr [rsp + 24], 1
    jbe  .Lnttinv_r8_w1_fin_prep

    vmovsd       xmm20, [rsi + 4*rcx + 8]
    vmulsd       xmm20, xmm20, xmm30
    vmovsd       [rsp + 64], xmm20
    vbroadcastsd zmm24, [rsi + 4*rcx + 16]
    vbroadcastsd zmm25, [rsi + 4*rcx + 24]
    vmulpd       zmm26, zmm24, zmm30
    vmulpd       zmm27, zmm25, zmm30
    vbroadcastsd zmm28, [rsi + 2*rcx + 8]
    vmulpd       zmm31, zmm28, zmm30
.p2align 4
