    mov  r15, [rsp + 1104]              // stages_per_l2 = k2 - k1
    mov  r13, [rsp + 1072]              // s = l1_sub
    mov  r12, [rsp + 1112]
    shr  r12, 1                         // b_blocks = subs_per_l2 / 2
