    mov  qword ptr [rsp + 1032], 0      // is_l2_local = 0
    mov  rcx, [rsp + 48]
    mov  [rsp + 40], rcx                // need_scale

    tzcnt r15, rdx
    mov  rcx, [rsp + 1080]              // k1
    sub  r15, rcx                       // rem_stages above l1_sub
    mov  r13, [rsp + 1072]              // s = l1_sub (multiple of 32)
    inc  ecx
    mov  r12, rdx
    shr  r12, cl                        // b_blocks = orig_n / (2 * l1_sub)
    xor  ecx, ecx                       // ecx = 0 when inputs are <= 0.501p, 1 when <= 1.002p

