    vmovupd zmm3, [r9 + 192]
    vmovupd zmm4, [r9 + rbx + 0]
    vmovupd zmm5, [r9 + rbx + 64]
    vmovupd zmm6, [r9 + rbx + 128]
    vmovupd zmm7, [r9 + rbx + 192]
    NTT_DIT4_SHOUP zmm0, zmm4, zmm24, zmm27, zmm1, zmm5, zmm24, zmm27, zmm2, zmm6, zmm24, zmm27, zmm3, zmm7, zmm24, zmm27
    ZMM_RED4_SIGNED zmm0, zmm1, zmm2, zmm3
    ZMM_SCALE4_SHOUP zmm0, zmm1, zmm2, zmm3, qword ptr [rsp + 1120]{1to8}
    ZMM_SCALE4_SHOUP zmm4, zmm5, zmm6, zmm7, qword ptr [rsp + 1120]{1to8}
    vmovupd [r9 + 0],         zmm0
    vmovupd [r9 + 64],        zmm1
    vmovupd [r9 + 128],       zmm2
    vmovupd [r9 + 192],       zmm3
    vmovupd [r9 + rbx + 0],   zmm4
    vmovupd [r9 + rbx + 64],  zmm5
    vmovupd [r9 + rbx + 128], zmm6
    vmovupd [r9 + rbx + 192], zmm7
    lea  r9, [r9 + 256]
    sub  r10, 32
    jnz  .Lnttinv_above_r2_vec_sc

.Lnttinv_above_r2_next:
    inc  r8
    cmp  r8, r12
    jb   .Lnttinv_above_r2_blk
    jmp  .Lnttinv_above_l2_chk

    // Small power-of-two fallback for n in {2, 4, 8}
.Lnttinv_small:
    mov  r9,  1                         // m = 1
.Lnttinv_sm_stage:
    mov  r8,  rdx
    tzcnt rcx, r9
    inc  ecx
    shr  r8,  cl                        // b_blocks = n / (2 * m)
    xor  r10d, r10d                     // j = 0
.Lnttinv_sm_block:
    lea  rax, [r8 + r10]
    vmovsd xmm6, [rsi + 8*rax]          // w_inv
    mov  r11, r10
    imul r11, r9
    add  r11, r11
    xor  r12d, r12d                     // i = 0
.Lnttinv_sm_bfy:
    lea  rax, [r11 + r12]
    lea  rbx, [rax + r9]
    vmovsd xmm0, [rdi + 8*rax]          // u
    vmovsd xmm1, [rdi + 8*rbx]          // v
    vaddsd xmm2, xmm0, xmm1
    vsubsd xmm1, xmm0, xmm1
    vcmpsd k1, xmm2, xmm29, 13
    vcmpsd k2, xmm1, xmm31, 1
    vsubsd xmm2 {k1}, xmm2, xmm29
    vaddsd xmm1 {k2}, xmm1, xmm29
    vmovsd [rdi + 8*rax], xmm2
    vmulsd xmm2, xmm1, xmm6
    vmulsd xmm3, xmm2, xmm30
    vfmsub213sd xmm1, xmm6, xmm2
    vrndscalesd xmm3, xmm3, xmm3, 8
    vfnmadd231sd xmm2, xmm3, xmm29
    vaddsd xmm1, xmm2, xmm1
    vcmpsd k1, xmm1, xmm31, 1
    vaddsd xmm1 {k1}, xmm1, xmm29
    vmovsd [rdi + 8*rbx], xmm1
    inc  r12
    cmp  r12, r9
    jb   .Lnttinv_sm_bfy
    inc  r10
    cmp  r10, r8
    jb   .Lnttinv_sm_block
    shl  r9, 1
    cmp  r9, rdx
    jb   .Lnttinv_sm_stage

.Lnttinv_scale_check:
    cmp  qword ptr [rsp + 48], 0
    jne  .Lnttinv_do_scale
    cmp  rdx, 16
    jb   .Lnttinv_done
    mov  rcx, rdx
.Lnttinv_canon16:
    vmovupd zmm0, [rdi + 0]
    vmovupd zmm1, [rdi + 64]
    vcmppd  k1, zmm0, zmm31, 1
    vcmppd  k2, zmm1, zmm31, 1
    vaddpd  zmm0 {k1}, zmm0, zmm29
    vaddpd  zmm1 {k2}, zmm1, zmm29
    vmovupd [rdi + 0],  zmm0
    vmovupd [rdi + 64], zmm1
    lea  rdi, [rdi + 128]
    sub  rcx, 16
    jnz  .Lnttinv_canon16
    jmp  .Lnttinv_done

.Lnttinv_do_scale:
    mov  rcx, rdx                       // n
    cmp  rcx, 32
    jb   .Lnttinv_scale8_check
    vbroadcastsd zmm15, [rsp + 1120]
.p2align 4
.Lnttinv_scale32:
    vmovupd zmm0, [rdi + 0]
    vmovupd zmm1, [rdi + 64]
    vmovupd zmm2, [rdi + 128]
    vmovupd zmm3, [rdi + 192]
    ZMM_SCALE4_SHOUP zmm0, zmm1, zmm2, zmm3, zmm15
    vmovupd [rdi + 0],   zmm0
    vmovupd [rdi + 64],  zmm1
    vmovupd [rdi + 128], zmm2
    vmovupd [rdi + 192], zmm3
    lea  rdi, [rdi + 256]
    sub  rcx, 32
    cmp  rcx, 32
    jae  .Lnttinv_scale32

.Lnttinv_scale8_check:
    cmp  rcx, 8
    jb   .Lnttinv_scale_tail
.Lnttinv_scale8:
    vmovupd zmm0, [rdi]
    ZMM_MUL_MOD zmm0, zmm28, zmm16, zmm20, k1
    vmovupd [rdi], zmm0
    lea  rdi, [rdi + 64]
    sub  rcx, 8
    cmp  rcx, 8
    jae  .Lnttinv_scale8

.Lnttinv_scale_tail:
    test rcx, rcx
    jz   .Lnttinv_done
    mov  eax, 0xFF
    bzhi eax, eax, ecx
    kmovw k5, eax
    vmovupd zmm0 {k5}{z}, [rdi]
    ZMM_MUL_MOD zmm0, zmm28, zmm16, zmm20, k1
    vmovupd [rdi] {k5}, zmm0

.Lnttinv_done:
    VEC_LEAVE

// [15] ntt_fwd_cols(buf: rdi, twiddles: rsi, cfg: rdx /* *const NttColsCfg */, prime: rcx)
// Full 8-column strips gather <= l2_sub_rows rows ONCE into contiguous 64B-aligned scratch buffer,
// running all top and l1_sub_rows sub-strip passes in-place and scattering ONCE!
LOCAL_FN supi_k_ntt_fwd_cols
    VEC_ENTER 320
    mov  r8,  [rdx + 0]                 // rows
    mov  r9,  [rdx + 8]                 // cols
    cmp  r8,  1
    jbe  .Lnttfwdcols_done
    test r9,  r9
    jz   .Lnttfwdcols_done
    cmp  r8,  16
    je   .Lnttfwdcols_r16_entry
    cmp  r9,  8
    jb   .Lnttfwdcols_stk_ok

    mov  r10, [rdx + 16]                // raw l1_sub_rows
    mov  r11, [rdx + 24]                // raw l2_sub_rows
    mov  rbx, [rdx + 32]                // scratch ptr (64B-aligned, or null for stack fallback)
    mov  r14, rcx                       // preserve prime ptr
    test rbx, rbx
    jnz  .Lnttfwdcols_norm_l1
    mov  eax, 4096
    cmp  r10, rax
    cmova r10, rax
    cmp  r11, rax
    cmova r11, rax
.Lnttfwdcols_norm_l1:
    cmp  r10, r8
    jb   .Lnttfwdcols_l1_lt_rows
    mov  r10, r8
    tzcnt r12, r8
    mov  r11, r8
    jmp  .Lnttfwdcols_choose_buf
.Lnttfwdcols_l1_lt_rows:
    mov  eax, 16
    cmp  r10, 16
    cmovb r10, rax
    lzcnt rax, r10
    mov  r12d, 63
    sub  r12d, eax                      // k1 = log2(l1_sub_rows) >= 4
    mov  eax, 1
    mov  ecx, r12d
    shl  rax, cl
    mov  r10, rax                       // l1_sub_rows = 2^k1
    cmp  r11, r8
    jb   .Lnttfwdcols_norm_l2
    mov  r11, r8
    jmp  .Lnttfwdcols_choose_buf
.Lnttfwdcols_norm_l2:
    cmp  r11, r10
    cmovb r11, r10
    lzcnt rax, r11
    mov  ecx, 63
    sub  ecx, eax
    mov  eax, 1
    shl  rax, cl
    mov  r11, rax                       // l2_sub_rows = 2^k2 >= l1_sub_rows
.Lnttfwdcols_choose_buf:
    mov  rcx, r14                       // restore prime ptr
    test rbx, rbx
    jnz  .Lnttfwdcols_save_cfg
    mov  rax, r8
    cmp  r8,  r11
    cmova rax, r10                      // strip_rows = (rows <= l2_sub_rows ? rows : l1_sub_rows)
    shl  rax, 6                         // strip_bytes = strip_rows * 64
.Lnttfwdcols_probe:
    cmp  rax, 4096
    jbe  .Lnttfwdcols_probe_tail
    sub  rsp, 4096
    mov  qword ptr [rsp], 0
    sub  rax, 4096
    jmp  .Lnttfwdcols_probe
.Lnttfwdcols_probe_tail:
    sub  rsp, rax
    and  rsp, -64
    mov  qword ptr [rsp], 0
    lea  rbx, [rsp + 320]
.Lnttfwdcols_save_cfg:
    mov  [rsp + 256], r10               // l1_sub_rows
    mov  [rsp + 264], r12               // k1
    mov  [rsp + 272], r11               // l2_sub_rows
    mov  [rsp + 280], rbx               // strip_buf_base
.Lnttfwdcols_stk_ok:

    vbroadcastsd zmm29, [rcx + 0]       // p
    vbroadcastsd zmm30, [rcx + 8]       // inv_p
    vpxorq       zmm31, zmm31, zmm31    // 0.0

    mov  [rsp + 0],  r8                 // rows
    mov  [rsp + 8],  r9                 // cols
    mov  rax, r9
    shl  rax, 3
    mov  [rsp + 16], rax                // row_stride_bytes = cols * 8
    xor  eax, eax
    mov  [rsp + 24], rax                // col_offset = 0

.Lnttfwdcols_strip_loop:
    mov  rcx, [rsp + 24]                // col_offset
    mov  r9,  [rsp + 8]                 // cols
    sub  r9,  rcx                       // rem_cols
    jz   .Lnttfwdcols_done
    lea  r15, [rdi + 8*rcx]             // strip_base_ptr = &buf[col_offset]
    mov  [rsp + 32], r15
    cmp  r9,  8
    jb   .Lnttfwdcols_masked_strip

    // Full 8-column unmasked strip
    mov  r8,  [rsp + 0]                 // rows
    cmp  r8,  [rsp + 256]
    ja   .Lnttfwdcols_above_l1
    mov  qword ptr [rsp + 112], 0       // full_buf_mode = 0
    mov  [rsp + 64], r8                 // sub_rows = rows
    mov  qword ptr [rsp + 72], 1        // num_subs = 1
    jmp  .Lnttfwdcols_sub_init

.Lnttfwdcols_above_l1:
    cmp  r8,  [rsp + 272]
    ja   .Lnttfwdcols_above_strided
    mov  qword ptr [rsp + 112], 1       // full_buf_mode = 1 (first ab pass gathers tile -> scratch!)
    mov  rax, [rsp + 32]
    mov  [rsp + 128], rax               // ab_src_base = strip_base_ptr
    mov  rax, [rsp + 16]
    mov  [rsp + 136], rax               // ab_src_stride = row_stride_bytes
    mov  r9,  [rsp + 280]
    mov  [rsp + 120], r9                // ab_dst_base = strip_buf_base
    mov  qword ptr [rsp + 56], 64       // ab_dst_stride = 64
    jmp  .Lnttfwdcols_ab_start

.Lnttfwdcols_above_strided:
    mov  qword ptr [rsp + 112], 0       // full_buf_mode = 0
    mov  rax, [rsp + 32]
    mov  [rsp + 128], rax               // ab_src_base = strip_base_ptr
    mov  [rsp + 120], rax               // ab_dst_base = strip_base_ptr
    mov  rax, [rsp + 16]
    mov  [rsp + 136], rax               // ab_src_stride = row_stride_bytes
    mov  [rsp + 56],  rax               // ab_dst_stride = row_stride_bytes

.Lnttfwdcols_ab_start:
    tzcnt r14, r8
    sub  r14, [rsp + 264]               // stages above l1_sub_rows
    mov  qword ptr [rsp + 288], 0       // lazy_stages = 0
    mov  r12, 1                         // b_blocks = 1
    mov  r13, r8
    shr  r13, 1                         // m_rows = rows / 2

.Lnttfwdcols_ab_r4:
    cmp  r14, 2
    jb   .Lnttfwdcols_ab_r2
    mov  rax, [rsp + 288]               // lazy_stages since last reduction
    add  rax, 2
    mov  ecx, 1
    lea  rdx, [r14 - 2]
    test rdx, rdx
    jz   .Lnttfwdcols_ab_r4_chk4
    mov  r9d, 2
    cmp  rdx, 2
    cmova rdx, r9
    add  rdx, rax
    cmp  rdx, 4
    ja   .Lnttfwdcols_ab_r4_set_red
    xor  ecx, ecx
    mov  [rsp + 288], rax
    jmp  .Lnttfwdcols_ab_r4_save_red
.Lnttfwdcols_ab_r4_chk4:
    cmp  rax, 4
    ja   .Lnttfwdcols_ab_r4_set_red
    xor  ecx, ecx
    mov  [rsp + 288], rax
    jmp  .Lnttfwdcols_ab_r4_save_red
.Lnttfwdcols_ab_r4_set_red:
    mov  qword ptr [rsp + 288], 0
.Lnttfwdcols_ab_r4_save_red:
    mov  [rsp + 296], rcx               // do_reduce (0 or 1)
    mov  rdx, [rsp + 136]               // ab_src_stride
    mov  rbx, r13
    shr  rbx, 1                         // s_rows = m_rows / 2 (>= 256, even)
    mov  [rsp + 40], rbx
    mov  rax, rbx
    imul rax, [rsp + 56]                // dst_sub_stride = s_rows * ab_dst_stride
    mov  [rsp + 48], rax
    imul rbx, rdx                       // src_sub_stride = s_rows * ab_src_stride
    xor  r8d, r8d
.Lnttfwdcols_ab_r4_blk:
    mov  rax, r8
    shl  rax, 2
    mov  rcx, rax
    imul rax, rbx
    mov  r9,  [rsp + 128]
    add  r9,  rax                       // src_ptr
    imul rcx, [rsp + 48]
    mov  r15, [rsp + 120]
    add  r15, rcx                       // dst_ptr
    mov  r10, [rsp + 40]
    lea  rax, [r12 + r8]
    mov  r11, 0x3FF0000000000000
    cmp  qword ptr [rsi + 8*rax], r11
    jne  .Lnttfwdcols_ab_r4_gen
    add  rax, rax
    cmp  qword ptr [rsi + 8*rax], r11
    jne  .Lnttfwdcols_ab_r4_gen_from2
    vbroadcastsd zmm26, [rsi + 8*rax + 8]
    vmulpd       zmm27, zmm26, zmm30
.p2align 4
.Lnttfwdcols_ab_r4_row_w1:
    vmovupd zmm0, [r9]
    vmovupd zmm1, [r9 + rbx]
    lea  r11, [r9 + 2*rbx]
    vmovupd zmm2, [r11]
    vmovupd zmm3, [r11 + rbx]
    lea  rcx, [r9 + rdx]
    vmovupd zmm4, [rcx]
    vmovupd zmm5, [rcx + rbx]
    lea  rax, [rcx + 2*rbx]
    vmovupd zmm6, [rax]
    vmovupd zmm7, [rax + rbx]
    lea  r9,  [r9 + 2*rdx]
    NTT_BFY4_W1    zmm0, zmm2, zmm1, zmm3, zmm4, zmm6, zmm5, zmm7
    NTT_BFY2_W1    zmm0, zmm1, zmm4, zmm5
    NTT_DIF2_SHOUP zmm2, zmm3, zmm26, zmm27, zmm6, zmm7, zmm26, zmm27
    ZMM_RED4_SIGNED zmm0, zmm1, zmm2, zmm3
    ZMM_RED4_SIGNED zmm4, zmm5, zmm6, zmm7
    mov  rcx, [rsp + 56]
    mov  rax, [rsp + 48]
    lea  r11, [r15 + 2*rax]
    vmovupd [r15],       zmm0
    vmovupd [r15 + rax], zmm1
    vmovupd [r11],       zmm2
    vmovupd [r11 + rax], zmm3
    add  r15, rcx
    lea  r11, [r15 + 2*rax]
    vmovupd [r15],       zmm4
    vmovupd [r15 + rax], zmm5
    vmovupd [r11],       zmm6
    vmovupd [r11 + rax], zmm7
    add  r15, rcx
    sub  r10, 2
    jnz  .Lnttfwdcols_ab_r4_row_w1
    jmp  .Lnttfwdcols_ab_r4_next

.Lnttfwdcols_ab_r4_gen_from2:
    shr  rax, 1
.Lnttfwdcols_ab_r4_gen:
    vbroadcastsd zmm24, [rsi + 8*rax]
    add  rax, rax
    vbroadcastsd zmm25, [rsi + 8*rax + 0]
    vbroadcastsd zmm26, [rsi + 8*rax + 8]
    vmulpd       zmm27, zmm24, zmm30
    vmulpd       zmm28, zmm25, zmm30
    vmulpd       zmm31, zmm26, zmm30
.p2align 4
.Lnttfwdcols_ab_r4_row:
    vmovupd zmm0, [r9]
    vmovupd zmm1, [r9 + rbx]
    lea  r11, [r9 + 2*rbx]
    vmovupd zmm2, [r11]
    vmovupd zmm3, [r11 + rbx]
    lea  rcx, [r9 + rdx]
    vmovupd zmm4, [rcx]
    vmovupd zmm5, [rcx + rbx]
    lea  rax, [rcx + 2*rbx]
    vmovupd zmm6, [rax]
    vmovupd zmm7, [rax + rbx]
    lea  r9,  [r9 + 2*rdx]
    NTT_DIF4_SHOUP zmm0, zmm2, zmm24, zmm27, zmm1, zmm3, zmm24, zmm27, zmm4, zmm6, zmm24, zmm27, zmm5, zmm7, zmm24, zmm27
    NTT_DIF4_SHOUP zmm0, zmm1, zmm25, zmm28, zmm2, zmm3, zmm26, zmm31, zmm4, zmm5, zmm25, zmm28, zmm6, zmm7, zmm26, zmm31
    cmp  qword ptr [rsp + 296], 0
    je   .Lnttfwdcols_ab_r4_store
    ZMM_RED4_SIGNED zmm0, zmm1, zmm2, zmm3
    ZMM_RED4_SIGNED zmm4, zmm5, zmm6, zmm7
.Lnttfwdcols_ab_r4_store:
    mov  rcx, [rsp + 56]
    mov  rax, [rsp + 48]
    lea  r11, [r15 + 2*rax]
    vmovupd [r15],       zmm0
    vmovupd [r15 + rax], zmm1
    vmovupd [r11],       zmm2
    vmovupd [r11 + rax], zmm3
    add  r15, rcx
    lea  r11, [r15 + 2*rax]
    vmovupd [r15],       zmm4
    vmovupd [r15 + rax], zmm5
    vmovupd [r11],       zmm6
    vmovupd [r11 + rax], zmm7
    add  r15, rcx
    sub  r10, 2
    jnz  .Lnttfwdcols_ab_r4_row
.Lnttfwdcols_ab_r4_next:
    inc  r8
    cmp  r8, r12
    jb   .Lnttfwdcols_ab_r4_blk
    mov  rax, [rsp + 120]
    mov  [rsp + 128], rax               // subsequent ab passes run in-place on dst
    mov  rax, [rsp + 56]
    mov  [rsp + 136], rax
    shl  r12, 2
    shr  r13, 2
    sub  r14, 2
    jmp  .Lnttfwdcols_ab_r4

.Lnttfwdcols_ab_r2:
    test r14, r14
    jz   .Lnttfwdcols_ab_done
    mov  rdx, [rsp + 136]               // ab_src_stride
    mov  rbx, r13                       // r13 == 256 (multiple of 4)
    mov  rax, rbx
    imul rax, [rsp + 56]
    mov  [rsp + 48], rax                // dst_sub_stride
    imul rbx, rdx                       // src_sub_stride
    xor  r8d, r8d
.Lnttfwdcols_ab_r2_blk:
    mov  rax, r8
    add  rax, rax
    mov  rcx, rax
    imul rax, rbx
    mov  r9,  [rsp + 128]
    add  r9,  rax                       // src_ptr
    imul rcx, [rsp + 48]
    mov  r15, [rsp + 120]
    add  r15, rcx                       // dst_ptr
    mov  r10, r13
    lea  rax, [r12 + r8]
    mov  r11, 0x3FF0000000000000
    cmp  qword ptr [rsi + 8*rax], r11
    jne  .Lnttfwdcols_ab_r2_gen
.p2align 4
.Lnttfwdcols_ab_r2_row_w1:
    vmovupd zmm0, [r9]
    vmovupd zmm1, [r9 + rbx]
    lea  rcx, [r9 + rdx]
    vmovupd zmm2, [rcx]
    vmovupd zmm3, [rcx + rbx]
    lea  r11, [r9 + 2*rdx]
    vmovupd zmm4, [r11]
    vmovupd zmm5, [r11 + rbx]
    lea  rax, [r11 + rdx]
    vmovupd zmm6, [rax]
    vmovupd zmm7, [rax + rbx]
    lea  r9,  [r9 + 4*rdx]
    NTT_BFY4_W1 zmm0, zmm1, zmm2, zmm3, zmm4, zmm5, zmm6, zmm7
    ZMM_RED4_SIGNED zmm0, zmm1, zmm2, zmm3
    ZMM_RED4_SIGNED zmm4, zmm5, zmm6, zmm7
    mov  rcx, [rsp + 56]
    mov  rax, [rsp + 48]
    vmovupd [r15],       zmm0
    vmovupd [r15 + rax], zmm1
    add  r15, rcx
    vmovupd [r15],       zmm2
    vmovupd [r15 + rax], zmm3
    add  r15, rcx
    vmovupd [r15],       zmm4
    vmovupd [r15 + rax], zmm5
    add  r15, rcx
    vmovupd [r15],       zmm6
    vmovupd [r15 + rax], zmm7
    add  r15, rcx
    sub  r10, 4
    jnz  .Lnttfwdcols_ab_r2_row_w1
    jmp  .Lnttfwdcols_ab_r2_next

.Lnttfwdcols_ab_r2_gen:
    vbroadcastsd zmm24, [rsi + 8*rax]
    vmulpd       zmm27, zmm24, zmm30
.p2align 4
.Lnttfwdcols_ab_r2_row:
    vmovupd zmm0, [r9]
    vmovupd zmm1, [r9 + rbx]
    lea  rcx, [r9 + rdx]
    vmovupd zmm2, [rcx]
    vmovupd zmm3, [rcx + rbx]
    lea  r11, [r9 + 2*rdx]
    vmovupd zmm4, [r11]
    vmovupd zmm5, [r11 + rbx]
    lea  rax, [r11 + rdx]
    vmovupd zmm6, [rax]
    vmovupd zmm7, [rax + rbx]
    lea  r9,  [r9 + 4*rdx]
