    vmovupd zmm7,  [r10 + rax]
    vmovupd zmm8,  [r11]
    vmovupd zmm9,  [r11 + rdx]
    vmovupd zmm10, [r11 + 2*rdx]
    vmovupd zmm11, [r11 + rax]
    lea  r12, [r11 + rbx]
    vmovupd zmm12, [r12]
    vmovupd zmm13, [r12 + rdx]
    vmovupd zmm14, [r12 + 2*rdx]
    vmovupd zmm15, [r12 + rax]

    NTT_BFY4_W1    zmm0, zmm8,  zmm1, zmm9,  zmm2, zmm10, zmm3, zmm11
    NTT_BFY4_W1    zmm4, zmm12, zmm5, zmm13, zmm6, zmm14, zmm7, zmm15
    NTT_BFY4_W1    zmm0, zmm4,  zmm1, zmm5,  zmm2, zmm6,  zmm3, zmm7
    ZMM_RED4_SIGNED zmm0, zmm1, zmm2, zmm3

    vbroadcastsd   zmm27, [rsp + 24]
    NTT_DIF4_SHOUP zmm8, zmm12, zmm28, zmm27, zmm9, zmm13, zmm28, zmm27, zmm10, zmm14, zmm28, zmm27, zmm11, zmm15, zmm28, zmm27

    NTT_BFY2_W1    zmm0, zmm2, zmm1, zmm3
    vbroadcastsd zmm25, [rsi + 40]
    vbroadcastsd zmm27, [rsp + 40]
    NTT_DIF2_SHOUP zmm4, zmm6, zmm25, zmm27, zmm5, zmm7, zmm25, zmm27
    vbroadcastsd zmm24, [rsi + 48]
    vbroadcastsd zmm25, [rsi + 56]
    vbroadcastsd zmm26, [rsp + 48]
    vbroadcastsd zmm27, [rsp + 56]
    NTT_DIF4_SHOUP zmm8, zmm10, zmm24, zmm26, zmm9, zmm11, zmm24, zmm26, zmm12, zmm14, zmm25, zmm27, zmm13, zmm15, zmm25, zmm27

    vbroadcastsd zmm24, [rsi + 64]
    vbroadcastsd zmm25, [rsi + 72]
    vbroadcastsd zmm26, [rsi + 80]
    vbroadcastsd zmm27, [rsi + 88]
    vbroadcastsd zmm20, [rsp + 64]
    vbroadcastsd zmm21, [rsp + 72]
    vbroadcastsd zmm22, [rsp + 80]
    vbroadcastsd zmm23, [rsp + 88]
    NTT_DIF4_SHOUP zmm0, zmm1, zmm24, zmm20, zmm2, zmm3, zmm25, zmm21, zmm4, zmm5, zmm26, zmm22, zmm6, zmm7, zmm27, zmm23
    vbroadcastsd zmm24, [rsi + 96]
    vbroadcastsd zmm25, [rsi + 104]
    vbroadcastsd zmm26, [rsi + 112]
    vbroadcastsd zmm27, [rsi + 120]
    vbroadcastsd zmm20, [rsp + 96]
    vbroadcastsd zmm21, [rsp + 104]
    vbroadcastsd zmm22, [rsp + 112]
    vbroadcastsd zmm23, [rsp + 120]
    NTT_DIF4_SHOUP zmm8, zmm9, zmm24, zmm20, zmm10, zmm11, zmm25, zmm21, zmm12, zmm13, zmm26, zmm22, zmm14, zmm15, zmm27, zmm23

    ZMM_CANON4 zmm0,  zmm1,  zmm2,  zmm3
    ZMM_CANON4 zmm4,  zmm5,  zmm6,  zmm7
    ZMM_CANON4 zmm8,  zmm9,  zmm10, zmm11
    ZMM_CANON4 zmm12, zmm13, zmm14, zmm15

    vmovupd [rdi],         zmm0
    vmovupd [rdi + rdx],   zmm1
    vmovupd [rdi + 2*rdx], zmm2
    vmovupd [rdi + rax],   zmm3
    vmovupd [r10],         zmm4
    vmovupd [r10 + rdx],   zmm5
    vmovupd [r10 + 2*rdx], zmm6
    vmovupd [r10 + rax],   zmm7
    vmovupd [r11],         zmm8
    vmovupd [r11 + rdx],   zmm9
    vmovupd [r11 + 2*rdx], zmm10
    vmovupd [r11 + rax],   zmm11
    vmovupd [r12],         zmm12
    vmovupd [r12 + rdx],   zmm13
    vmovupd [r12 + 2*rdx], zmm14
    vmovupd [r12 + rax],   zmm15

    add  rdi, 64
    sub  r9,  8
    cmp  r9,  8
    jae  .Lnttfwdcols_r16_loop_w1
    jmp  .Lnttfwdcols_r16_tail

.p2align 4
.Lnttfwdcols_r16_loop:
    vmovupd zmm0,  [rdi]
    vmovupd zmm1,  [rdi + rdx]
    vmovupd zmm2,  [rdi + 2*rdx]
    vmovupd zmm3,  [rdi + rax]
    lea  r10, [rdi + rbx]
    lea  r11, [rdi + 2*rbx]
    vmovupd zmm4,  [r10]
    vmovupd zmm5,  [r10 + rdx]
    vmovupd zmm6,  [r10 + 2*rdx]
    vmovupd zmm7,  [r10 + rax]
    vmovupd zmm8,  [r11]
    vmovupd zmm9,  [r11 + rdx]
    vmovupd zmm10, [r11 + 2*rdx]
    vmovupd zmm11, [r11 + rax]
    lea  r12, [r11 + rbx]
    vmovupd zmm12, [r12]
    vmovupd zmm13, [r12 + rdx]
    vmovupd zmm14, [r12 + 2*rdx]
    vmovupd zmm15, [r12 + rax]

    vbroadcastsd   zmm27, [rsp + 8]
    NTT_DIF4_SHOUP zmm0, zmm8,  zmm28, zmm27, zmm1, zmm9,  zmm28, zmm27, zmm2, zmm10, zmm28, zmm27, zmm3, zmm11, zmm28, zmm27
    NTT_DIF4_SHOUP zmm4, zmm12, zmm28, zmm27, zmm5, zmm13, zmm28, zmm27, zmm6, zmm14, zmm28, zmm27, zmm7, zmm15, zmm28, zmm27

    vbroadcastsd zmm24, [rsi + 16]
    vbroadcastsd zmm25, [rsi + 24]
    vbroadcastsd zmm26, [rsp + 16]
    vbroadcastsd zmm27, [rsp + 24]
    NTT_DIF4_SHOUP zmm0, zmm4,  zmm24, zmm26, zmm1, zmm5,  zmm24, zmm26, zmm2, zmm6,  zmm24, zmm26, zmm3, zmm7,  zmm24, zmm26
    NTT_DIF4_SHOUP zmm8, zmm12, zmm25, zmm27, zmm9, zmm13, zmm25, zmm27, zmm10, zmm14, zmm25, zmm27, zmm11, zmm15, zmm25, zmm27

    vbroadcastsd zmm24, [rsi + 32]
    vbroadcastsd zmm25, [rsi + 40]
    vbroadcastsd zmm26, [rsp + 32]
    vbroadcastsd zmm27, [rsp + 40]
    NTT_DIF4_SHOUP zmm0, zmm2,  zmm24, zmm26, zmm1, zmm3,  zmm24, zmm26, zmm4, zmm6,  zmm25, zmm27, zmm5, zmm7,  zmm25, zmm27
    vbroadcastsd zmm24, [rsi + 48]
    vbroadcastsd zmm25, [rsi + 56]
    vbroadcastsd zmm26, [rsp + 48]
    vbroadcastsd zmm27, [rsp + 56]
    NTT_DIF4_SHOUP zmm8, zmm10, zmm24, zmm26, zmm9, zmm11, zmm24, zmm26, zmm12, zmm14, zmm25, zmm27, zmm13, zmm15, zmm25, zmm27

    vbroadcastsd zmm24, [rsi + 64]
    vbroadcastsd zmm25, [rsi + 72]
    vbroadcastsd zmm26, [rsi + 80]
    vbroadcastsd zmm27, [rsi + 88]
    vbroadcastsd zmm20, [rsp + 64]
    vbroadcastsd zmm21, [rsp + 72]
    vbroadcastsd zmm22, [rsp + 80]
    vbroadcastsd zmm23, [rsp + 88]
    NTT_DIF4_SHOUP zmm0, zmm1, zmm24, zmm20, zmm2, zmm3, zmm25, zmm21, zmm4, zmm5, zmm26, zmm22, zmm6, zmm7, zmm27, zmm23
    vbroadcastsd zmm24, [rsi + 96]
    vbroadcastsd zmm25, [rsi + 104]
    vbroadcastsd zmm26, [rsi + 112]
    vbroadcastsd zmm27, [rsi + 120]
    vbroadcastsd zmm20, [rsp + 96]
    vbroadcastsd zmm21, [rsp + 104]
    vbroadcastsd zmm22, [rsp + 112]
    vbroadcastsd zmm23, [rsp + 120]
    NTT_DIF4_SHOUP zmm8, zmm9, zmm24, zmm20, zmm10, zmm11, zmm25, zmm21, zmm12, zmm13, zmm26, zmm22, zmm14, zmm15, zmm27, zmm23

    ZMM_CANON4 zmm0,  zmm1,  zmm2,  zmm3
    ZMM_CANON4 zmm4,  zmm5,  zmm6,  zmm7
    ZMM_CANON4 zmm8,  zmm9,  zmm10, zmm11
    ZMM_CANON4 zmm12, zmm13, zmm14, zmm15

    vmovupd [rdi],         zmm0
    vmovupd [rdi + rdx],   zmm1
    vmovupd [rdi + 2*rdx], zmm2
    vmovupd [rdi + rax],   zmm3
    vmovupd [r10],         zmm4
    vmovupd [r10 + rdx],   zmm5
    vmovupd [r10 + 2*rdx], zmm6
    vmovupd [r10 + rax],   zmm7
    vmovupd [r11],         zmm8
    vmovupd [r11 + rdx],   zmm9
    vmovupd [r11 + 2*rdx], zmm10
    vmovupd [r11 + rax],   zmm11
    vmovupd [r12],         zmm12
    vmovupd [r12 + rdx],   zmm13
    vmovupd [r12 + 2*rdx], zmm14
    vmovupd [r12 + rax],   zmm15

    add  rdi, 64
    sub  r9,  8
    cmp  r9,  8
    jae  .Lnttfwdcols_r16_loop

.Lnttfwdcols_r16_tail:
    test r9,  r9
    jz   .Lnttfwdcols_done
    mov  qword ptr [rsp + 0], 16
    mov  [rsp + 8],  r9
    mov  [rsp + 16], rdx
    mov  qword ptr [rsp + 24], 0
    mov  [rsp + 32], rdi
    jmp  .Lnttfwdcols_masked_strip

.Lnttfwdcols_done:
    VEC_LEAVE

// [16] ntt_inv_cols(buf: rdi, inv_twiddles: rsi, cfg: rdx /* *const NttColsCfg */, prime: rcx)
// Full 8-column strips gather <= l2_sub_rows rows ONCE into 64B-aligned scratch buffer,
// executing unmasked aligned vmovapd DIT stages in-place and fusing final scale on single scatter!
LOCAL_FN supi_k_ntt_inv_cols
    VEC_ENTER 320
    mov  r8,  [rdx + 0]                 // rows
    mov  r9,  [rdx + 8]                 // cols
    test r8,  r8
    jz   .Lnttinvcols_done
    test r9,  r9
    jz   .Lnttinvcols_done
    cmp  r8,  1
    jbe  .Lnttinvcols_stk_ok
    cmp  r8,  16
    je   .Lnttinvcols_r16_entry
    cmp  r9,  8
    jb   .Lnttinvcols_stk_ok

    mov  r10, [rdx + 16]                // raw l1_sub_rows
    mov  r11, [rdx + 24]                // raw l2_sub_rows
    mov  rbx, [rdx + 32]                // scratch ptr (64B-aligned, or null for stack fallback)
    mov  r14, rcx                       // preserve prime ptr
    test rbx, rbx
    jnz  .Lnttinvcols_norm_l1
    mov  eax, 4096
    cmp  r10, rax
    cmova r10, rax
    cmp  r11, rax
    cmova r11, rax
.Lnttinvcols_norm_l1:
    cmp  r10, r8
    jb   .Lnttinvcols_l1_lt_rows
    mov  r10, r8
    tzcnt r12, r8
    mov  r11, r8
    jmp  .Lnttinvcols_choose_buf
.Lnttinvcols_l1_lt_rows:
    mov  eax, 16
    cmp  r10, 16
    cmovb r10, rax
    lzcnt rax, r10
    mov  r12d, 63
    sub  r12d, eax                      // k1 = log2(l1_sub_rows) >= 4
    mov  eax, 1
    mov  ecx, r12d
    shl  rax, cl
    mov  r10, rax                       // l1_sub_rows = 2^k1
    cmp  r11, r8
    jb   .Lnttinvcols_norm_l2
    mov  r11, r8
    jmp  .Lnttinvcols_choose_buf
.Lnttinvcols_norm_l2:
    cmp  r11, r10
    cmovb r11, r10
    lzcnt rax, r11
    mov  ecx, 63
    sub  ecx, eax
    mov  eax, 1
    shl  rax, cl
    mov  r11, rax                       // l2_sub_rows = 2^k2 >= l1_sub_rows
.Lnttinvcols_choose_buf:
    mov  rcx, r14                       // restore prime ptr
    test rbx, rbx
    jnz  .Lnttinvcols_save_cfg
    mov  rax, r8
    cmp  r8,  r11
    cmova rax, r10                      // strip_rows = (rows <= l2_sub_rows ? rows : l1_sub_rows)
    shl  rax, 6                         // strip_bytes = strip_rows * 64
.Lnttinvcols_probe:
    cmp  rax, 4096
    jbe  .Lnttinvcols_probe_tail
    sub  rsp, 4096
    mov  qword ptr [rsp], 0
    sub  rax, 4096
    jmp  .Lnttinvcols_probe
.Lnttinvcols_probe_tail:
    sub  rsp, rax
    and  rsp, -64
    mov  qword ptr [rsp], 0
    lea  rbx, [rsp + 320]
.Lnttinvcols_save_cfg:
    mov  [rsp + 256], r10               // l1_sub_rows
    mov  [rsp + 264], r12               // k1
    mov  [rsp + 272], r11               // l2_sub_rows
    mov  [rsp + 280], rbx               // strip_buf_base
.Lnttinvcols_stk_ok:

    vbroadcastsd zmm29, [rcx + 0]       // p
    vbroadcastsd zmm30, [rcx + 8]       // inv_p
    vbroadcastsd zmm28, [rcx + 16]      // scale
    vpxorq       zmm31, zmm31, zmm31    // 0.0
    vmulsd       xmm16, xmm28, xmm30
    vmovsd       [rsp + 288], xmm16     // scale_wp = fl(scale * inv_p)
    mov  [rsp + 56], rcx                // prime ptr

    cmp  r8,  1
    je   .Lnttinvcols_scale

    mov  rax, [rcx + 16]
    mov  rbx, 0x3FF0000000000000        // 1.0
    xor  edx, edx
    cmp  rax, rbx
    setne dl
    mov  [rsp + 96], rdx                // need_scale

    mov  [rsp + 0],  r8                 // rows
    mov  [rsp + 8],  r9                 // cols
    mov  rax, r9
    shl  rax, 3
    mov  [rsp + 16], rax                // row_stride_bytes
    xor  eax, eax
    mov  [rsp + 24], rax                // col_offset = 0

.Lnttinvcols_strip_loop:
    mov  rcx, [rsp + 24]
    mov  r9,  [rsp + 8]
    sub  r9,  rcx
    jz   .Lnttinvcols_done
    lea  r15, [rdi + 8*rcx]
    mov  [rsp + 32], r15
    cmp  r9,  8
    jb   .Lnttinvcols_masked_strip

    // Full 8-column unmasked strip
    mov  r8,  [rsp + 0]                 // rows
    cmp  r8,  [rsp + 256]
    ja   .Lnttinvcols_above_l1
    mov  qword ptr [rsp + 112], 0       // full_buf_mode = 0
    mov  [rsp + 64], r8                 // sub_rows = rows
    mov  qword ptr [rsp + 72], 1        // num_subs = 1
    jmp  .Lnttinvcols_sub_init

.Lnttinvcols_above_l1:
    mov  rcx, [rsp + 256]
    mov  [rsp + 64], rcx                // sub_rows = l1_sub_rows
    mov  rcx, [rsp + 264]               // k1
    mov  rax, r8
    shr  rax, cl
    mov  [rsp + 72], rax                // num_subs = rows / l1_sub_rows
    xor  eax, eax
    cmp  r8,  [rsp + 272]
    setbe al
    mov  [rsp + 112], rax               // full_buf_mode = (rows <= l2_sub_rows ? 1 : 0)

.Lnttinvcols_sub_init:
    xor  eax, eax
    mov  [rsp + 80], rax                // sub_idx = 0

.Lnttinvcols_sub_loop:
    mov  rax, [rsp + 80]                // sub_idx
    mov  rcx, [rsp + 72]                // num_subs
    add  rcx, rax
    mov  [rsp + 88], rcx                // tw_root = num_subs + sub_idx
    mov  r8,  [rsp + 64]                // sub_rows
    mov  rdx, [rsp + 16]                // row_stride_bytes
    mov  rcx, rax
    imul rcx, r8
    imul rcx, rdx
    add  rcx, [rsp + 32]
    mov  [rsp + 104], rcx               // sub_strip_ptr
    mov  r11, rcx
    mov  r9,  [rsp + 280]               // strip_buf_base
    cmp  qword ptr [rsp + 112], 0
    je   .Lnttinvcols_do_gath
    imul rax, r8                        // sub_idx * sub_rows
    shl  rax, 6                         // * 64
    add  r9,  rax
.Lnttinvcols_do_gath:
    mov  [rsp + 120], r9                // sub_stk_base
    cmp  r8,  16
    jae  .Lnttinvcols_gath_done         // sub_rows >= 16 gathers directly in Pass 1 (s_rows == 1)!
    mov  rcx, r8
    cmp  rcx, 4
    jb   .Lnttinvcols_gath2
.p2align 4
.Lnttinvcols_gath4:
    vmovupd zmm0, [r11]
    vmovupd zmm1, [r11 + rdx]
    lea  r11, [r11 + 2*rdx]
    vmovupd zmm2, [r11]
    vmovupd zmm3, [r11 + rdx]
    lea  r11, [r11 + 2*rdx]
    vmovapd [r9 + 0],   zmm0
    vmovapd [r9 + 64],  zmm1
    vmovapd [r9 + 128], zmm2
    vmovapd [r9 + 192], zmm3
    add  r9,  256
    sub  rcx, 4
    jnz  .Lnttinvcols_gath4
    jmp  .Lnttinvcols_gath_done
.Lnttinvcols_gath2:
    vmovupd zmm0, [r11]
    vmovupd zmm1, [r11 + rdx]
    vmovapd [r9 + 0],  zmm0
    vmovapd [r9 + 64], zmm1

.Lnttinvcols_gath_done:
    tzcnt r14, r8                       // rem_stages = log2(sub_rows)
    mov  r13, 1                         // s_rows = 1
    mov  r12, r8
    shr  r12, 1                         // b_local = sub_rows / 2

.Lnttinvcols_l1_r16_chk:
    cmp  r14, 4
    jb   .Lnttinvcols_l1_rem
    mov  rax, r12
    shr  rax, 3                         // b0_local = sub_rows / (16 * s_rows)
    mov  [rsp + 40], rax
    mov  rbx, r13
    shl  rbx, 6                         // sub_stride_bytes = s_rows * 64
    xor  r8d, r8d
.Lnttinvcols_l1_r16_blk:
    mov  [rsp + 48], r8
    mov  rcx, [rsp + 88]
    imul rcx, [rsp + 40]
    add  rcx, r8                        // tw_idx0 = tw_root * b0_local + j_local
    shl  rcx, 3                         // 8 * tw_idx0
    mov  rax, r8
    shl  rax, 4
    imul rax, rbx
    mov  r9,  [rsp + 120]
    add  r9,  rax
    mov  r10, r13
    lea  rax, [rbx + 2*rbx]             // 3 * sub_stride_bytes
    mov  r11, 0x3FF0000000000000
    cmp  qword ptr [rsi + rcx], r11
    jne  .Lnttinvcols_l1_r16_prep_gen
    cmp  qword ptr [rsi + 2*rcx], r11
    jne  .Lnttinvcols_l1_r16_prep_gen
    cmp  qword ptr [rsi + 4*rcx], r11
    jne  .Lnttinvcols_l1_r16_prep_gen
    vmovsd       xmm20, [rsi + 2*rcx + 8]
    vmovupd      ymm21, [rsi + 4*rcx]
    vmovupd      zmm22, [rsi + 8*rcx]
    vmulsd       xmm20, xmm20, xmm30
    vmulpd       ymm21, ymm21, ymm30
    vmulpd       zmm22, zmm22, zmm30
    vmovsd       [rsp + 152], xmm20
    vmovapd      [rsp + 160], ymm21
    vmovapd      [rsp + 192], zmm22
    vbroadcastsd zmm24, [rsi + 4*rcx + 16]
    vbroadcastsd zmm25, [rsi + 4*rcx + 24]
    vmulpd       zmm26, zmm24, zmm30
    vmulpd       zmm27, zmm25, zmm30

.p2align 4
.Lnttinvcols_l1_r16_row_w1:
    cmp  r13, 1
    je   .Lnttinvcols_l1_r16_w1_gld
    vmovapd zmm0,  [r9]
    vmovapd zmm1,  [r9 + rbx]
    vmovapd zmm2,  [r9 + 2*rbx]
    vmovapd zmm3,  [r9 + rax]
    lea  r11, [r9 + 4*rbx]
    lea  r8,  [r9 + 8*rbx]
    vmovapd zmm4,  [r11]
    vmovapd zmm5,  [r11 + rbx]
    vmovapd zmm6,  [r11 + 2*rbx]
    vmovapd zmm7,  [r11 + rax]
    vmovapd zmm8,  [r8]
    vmovapd zmm9,  [r8 + rbx]
    vmovapd zmm10, [r8 + 2*rbx]
    vmovapd zmm11, [r8 + rax]
    lea  r11, [r8 + 4*rbx]
    vmovapd zmm12, [r11]
    vmovapd zmm13, [r11 + rbx]
    vmovapd zmm14, [r11 + 2*rbx]
    vmovapd zmm15, [r11 + rax]
    jmp  .Lnttinvcols_l1_r16_w1_bfy
.Lnttinvcols_l1_r16_w1_gld:
    mov  r8,  [rsp + 48]
    shl  r8,  4
    mov  rdx, [rsp + 16]
    imul r8,  rdx
    add  r8,  [rsp + 104]
    lea  r11, [rdx + 2*rdx]
    vmovupd zmm0,  [r8]
    vmovupd zmm1,  [r8 + rdx]
    vmovupd zmm2,  [r8 + 2*rdx]
    vmovupd zmm3,  [r8 + r11]
    lea  r8,  [r8 + 4*rdx]
    vmovupd zmm4,  [r8]
    vmovupd zmm5,  [r8 + rdx]
    vmovupd zmm6,  [r8 + 2*rdx]
    vmovupd zmm7,  [r8 + r11]
    lea  r8,  [r8 + 4*rdx]
    vmovupd zmm8,  [r8]
    vmovupd zmm9,  [r8 + rdx]
    vmovupd zmm10, [r8 + 2*rdx]
    vmovupd zmm11, [r8 + r11]
    lea  r8,  [r8 + 4*rdx]
    vmovupd zmm12, [r8]
    vmovupd zmm13, [r8 + rdx]
    vmovupd zmm14, [r8 + 2*rdx]
