.Lnttinvcols_r16_w1_noscl:
    ZMM_FIX_NEG4 zmm0,  zmm1,  zmm2,  zmm3
    ZMM_FIX_NEG4 zmm4,  zmm5,  zmm6,  zmm7
    ZMM_FIX_NEG4 zmm8,  zmm9,  zmm10, zmm11
    ZMM_FIX_NEG4 zmm12, zmm13, zmm14, zmm15

.Lnttinvcols_r16_w1_store:
    vmovupd [rdi],         zmm0
    vmovupd [rdi + rdx],   zmm1
    vmovupd [rdi + 2*rdx], zmm2
    vmovupd [rdi + rax],   zmm3
    vmovupd [r10],         zmm4
    vmovupd [r10 + rdx],   zmm5
    vmovupd [r10 + 2*rdx], zmm6
    vmovupd [r10 + rax],   zmm7
    vmovupd [r11],         zmm8
    vmovupd [r11 + rdx],   zmm9
    vmovupd [r11 + 2*rdx], zmm10
    vmovupd [r11 + rax],   zmm11
    vmovupd [r12],         zmm12
    vmovupd [r12 + rdx],   zmm13
    vmovupd [r12 + 2*rdx], zmm14
    vmovupd [r12 + rax],   zmm15

    add  rdi, 64
    sub  r9,  8
    cmp  r9,  8
    jae  .Lnttinvcols_r16_loop_w1
    jmp  .Lnttinvcols_r16_tail

.Lnttinvcols_r16_gen:
    vbroadcastsd zmm24, [rsi + 16]
    vbroadcastsd zmm25, [rsi + 24]
    vbroadcastsd zmm26, [rsp + 16]
    vbroadcastsd zmm27, [rsp + 24]

.p2align 4
.Lnttinvcols_r16_loop:
    vmovupd zmm0,  [rdi]
    vmovupd zmm1,  [rdi + rdx]
    vmovupd zmm2,  [rdi + 2*rdx]
    vmovupd zmm3,  [rdi + rax]
    lea  r10, [rdi + rbx]
    lea  r11, [rdi + 2*rbx]
    vmovupd zmm4,  [r10]
    vmovupd zmm5,  [r10 + rdx]
    vmovupd zmm6,  [r10 + 2*rdx]
    vmovupd zmm7,  [r10 + rax]
    vmovupd zmm8,  [r11]
    vmovupd zmm9,  [r11 + rdx]
    vmovupd zmm10, [r11 + 2*rdx]
    vmovupd zmm11, [r11 + rax]
    lea  r12, [r11 + rbx]
    vmovupd zmm12, [r12]
    vmovupd zmm13, [r12 + rdx]
    vmovupd zmm14, [r12 + 2*rdx]
    vmovupd zmm15, [r12 + rax]

    NTT_DIT4_SHOUP_MEM zmm0, zmm1,  rsi+64, rsp+64, zmm2,  zmm3,  rsi+72,  rsp+72,  zmm4,  zmm5,  rsi+80,  rsp+80,  zmm6,  zmm7,  rsi+88,  rsp+88
    NTT_DIT4_SHOUP_MEM zmm8, zmm9,  rsi+96, rsp+96, zmm10, zmm11, rsi+104, rsp+104, zmm12, zmm13, rsi+112, rsp+112, zmm14, zmm15, rsi+120, rsp+120

    NTT_DIT4_SHOUP_MEM zmm0, zmm2,  rsi+32, rsp+32, zmm1,  zmm3,  rsi+32,  rsp+32,  zmm4,  zmm6,  rsi+40,  rsp+40,  zmm5,  zmm7,  rsi+40,  rsp+40
    NTT_DIT4_SHOUP_MEM zmm8, zmm10, rsi+48, rsp+48, zmm9,  zmm11, rsi+48,  rsp+48,  zmm12, zmm14, rsi+56,  rsp+56,  zmm13, zmm15, rsi+56,  rsp+56
    ZMM_RED4_SIGNED    zmm0, zmm4, zmm8, zmm12

    NTT_DIT4_SHOUP     zmm0, zmm4,  zmm24, zmm26, zmm1, zmm5,  zmm24, zmm26, zmm2, zmm6,  zmm24, zmm26, zmm3, zmm7,  zmm24, zmm26
    NTT_DIT4_SHOUP     zmm8, zmm12, zmm25, zmm27, zmm9, zmm13, zmm25, zmm27, zmm10, zmm14, zmm25, zmm27, zmm11, zmm15, zmm25, zmm27

    NTT_DIT4_SHOUP_MEM zmm0, zmm8,  rsi+8, rsp+8, zmm1, zmm9,  rsi+8, rsp+8, zmm2, zmm10, rsi+8, rsp+8, zmm3, zmm11, rsi+8, rsp+8
    NTT_DIT4_SHOUP_MEM zmm4, zmm12, rsi+8, rsp+8, zmm5, zmm13, rsi+8, rsp+8, zmm6, zmm14, rsi+8, rsp+8, zmm7, zmm15, rsi+8, rsp+8

    ZMM_RED4_SIGNED zmm0,  zmm1,  zmm2,  zmm3
    ZMM_RED4_SIGNED zmm4,  zmm5,  zmm6,  zmm7

    test r14, r14
    jz   .Lnttinvcols_r16_noscl
    ZMM_SCALE4_SHOUP zmm0,  zmm1,  zmm2,  zmm3,  qword ptr [rsp + 288]{1to8}
    ZMM_SCALE4_SHOUP zmm4,  zmm5,  zmm6,  zmm7,  qword ptr [rsp + 288]{1to8}
    ZMM_SCALE4_SHOUP zmm8,  zmm9,  zmm10, zmm11, qword ptr [rsp + 288]{1to8}
    ZMM_SCALE4_SHOUP zmm12, zmm13, zmm14, zmm15, qword ptr [rsp + 288]{1to8}
    jmp  .Lnttinvcols_r16_store

.Lnttinvcols_r16_noscl:
    ZMM_FIX_NEG4 zmm0,  zmm1,  zmm2,  zmm3
    ZMM_FIX_NEG4 zmm4,  zmm5,  zmm6,  zmm7
    ZMM_FIX_NEG4 zmm8,  zmm9,  zmm10, zmm11
    ZMM_FIX_NEG4 zmm12, zmm13, zmm14, zmm15

.Lnttinvcols_r16_store:
    vmovupd [rdi],         zmm0
    vmovupd [rdi + rdx],   zmm1
    vmovupd [rdi + 2*rdx], zmm2
    vmovupd [rdi + rax],   zmm3
    vmovupd [r10],         zmm4
    vmovupd [r10 + rdx],   zmm5
    vmovupd [r10 + 2*rdx], zmm6
    vmovupd [r10 + rax],   zmm7
    vmovupd [r11],         zmm8
    vmovupd [r11 + rdx],   zmm9
    vmovupd [r11 + 2*rdx], zmm10
    vmovupd [r11 + rax],   zmm11
    vmovupd [r12],         zmm12
    vmovupd [r12 + rdx],   zmm13
    vmovupd [r12 + 2*rdx], zmm14
    vmovupd [r12 + rax],   zmm15

    add  rdi, 64
    sub  r9,  8
    cmp  r9,  8
    jae  .Lnttinvcols_r16_loop

.Lnttinvcols_r16_tail:
    test r9,  r9
    jz   .Lnttinvcols_done
    mov  qword ptr [rsp + 0], 16
    mov  [rsp + 8],  r9
    mov  [rsp + 16], rdx
    mov  qword ptr [rsp + 24], 0
    mov  [rsp + 32], rdi
    mov  [rsp + 96], r14
    jmp  .Lnttinvcols_masked_strip

.Lnttinvcols_scale:
    mov  rcx, [rsp + 56]
    mov  rax, [rcx + 16]
    mov  rbx, 0x3FF0000000000000        // 1.0
    cmp  rax, rbx
    je   .Lnttinvcols_done

    mov  rcx, r8
    imul rcx, r9                        // total = rows * cols
    vmulpd zmm15, zmm28, zmm30          // scale_wp
    cmp  rcx, 32
    jb   .Lnttinvcols_scale8_check
.p2align 4
.Lnttinvcols_scale32:
    vmovupd zmm0, [rdi + 0]
    vmovupd zmm1, [rdi + 64]
    vmovupd zmm2, [rdi + 128]
    vmovupd zmm3, [rdi + 192]
    vmulpd       zmm16, zmm0, zmm28
    vmulpd       zmm17, zmm1, zmm28
    vmulpd       zmm18, zmm2, zmm28
    vmulpd       zmm19, zmm3, zmm28
    vmulpd       zmm20, zmm0, zmm15
    vmulpd       zmm21, zmm1, zmm15
    vmulpd       zmm22, zmm2, zmm15
    vmulpd       zmm23, zmm3, zmm15
    vfmsub213pd  zmm0,  zmm28, zmm16
    vfmsub213pd  zmm1,  zmm28, zmm17
    vfmsub213pd  zmm2,  zmm28, zmm18
    vfmsub213pd  zmm3,  zmm28, zmm19
    vrndscalepd  zmm20, zmm20, 8
    vrndscalepd  zmm21, zmm21, 8
    vrndscalepd  zmm22, zmm22, 8
    vrndscalepd  zmm23, zmm23, 8
    vfnmadd231pd zmm16, zmm20, zmm29
    vfnmadd231pd zmm17, zmm21, zmm29
    vfnmadd231pd zmm18, zmm22, zmm29
    vfnmadd231pd zmm19, zmm23, zmm29
    vaddpd       zmm0,  zmm16, zmm0
    vaddpd       zmm1,  zmm17, zmm1
    vaddpd       zmm2,  zmm18, zmm2
    vaddpd       zmm3,  zmm19, zmm3
    vcmppd       k1, zmm0, zmm31, 1
    vcmppd       k2, zmm1, zmm31, 1
    vcmppd       k3, zmm2, zmm31, 1
    vcmppd       k4, zmm3, zmm31, 1
    vaddpd       zmm0 {k1}, zmm0, zmm29
    vaddpd       zmm1 {k2}, zmm1, zmm29
    vaddpd       zmm2 {k3}, zmm2, zmm29
    vaddpd       zmm3 {k4}, zmm3, zmm29
    vmovupd [rdi + 0],   zmm0
    vmovupd [rdi + 64],  zmm1
    vmovupd [rdi + 128], zmm2
    vmovupd [rdi + 192], zmm3
    lea  rdi, [rdi + 256]
    sub  rcx, 32
    cmp  rcx, 32
    jae  .Lnttinvcols_scale32

.Lnttinvcols_scale8_check:
    cmp  rcx, 8
    jb   .Lnttinvcols_scale_tail
.Lnttinvcols_scale8:
    vmovupd zmm0, [rdi]
    ZMM_MUL_MOD zmm0, zmm28, zmm16, zmm20, k1
    vmovupd [rdi], zmm0
    lea  rdi, [rdi + 64]
    sub  rcx, 8
    cmp  rcx, 8
    jae  .Lnttinvcols_scale8

.Lnttinvcols_scale_tail:
    test rcx, rcx
    jz   .Lnttinvcols_done
    mov  eax, 0xFF
    bzhi eax, eax, ecx
    kmovw k5, eax
    vmovupd zmm0 {k5}{z}, [rdi]
    ZMM_MUL_MOD zmm0, zmm28, zmm16, zmm20, k1
    vmovupd [rdi] {k5}, zmm0

.Lnttinvcols_done:
    VEC_LEAVE

// [17] ntt_pmul(dst: rdi, a: rsi, b: rdx, cfg: rcx)
// NttVecCfg: n@0, p@8, inv_p@16, sub_second@24
// When sub_second != 0: cols = sub_second, dst[r*cols+c] = ((dst[r*cols+c] * a[r*cols+c]) mod p * b[r]) mod p
LOCAL_FN supi_k_ntt_pmul
    VEC_ENTER_PMUL
    mov  r8,  [rcx + 0]                 // n
    test r8,  r8
    jz   .Lnttpmul_ret

    vbroadcastsd zmm29, [rcx + 8]       // p
    vbroadcastsd zmm30, [rcx + 16]      // inv_p
    vpxorq       zmm31, zmm31, zmm31    // 0.0

    mov  r9,  [rcx + 24]                // sub_second (cols for row-twist mode)
    test r9,  r9
    jnz  .Lnttpmul_row_twist

    cmp  r8,  64
    jb   .Lnttpmul_check32
.p2align 4
.Lnttpmul_loop64:
    vmovupd zmm0,  [rsi + 0]
    vmovupd zmm1,  [rsi + 64]
    vmovupd zmm2,  [rsi + 128]
    vmovupd zmm3,  [rsi + 192]
    vmovupd zmm4,  [rsi + 256]
    vmovupd zmm5,  [rsi + 320]
    vmovupd zmm24, [rsi + 384]
    vmovupd zmm25, [rsi + 448]

    vmulpd       zmm16, zmm0,  [rdx + 0]
    vmulpd       zmm17, zmm1,  [rdx + 64]
    vmulpd       zmm18, zmm2,  [rdx + 128]
    vmulpd       zmm19, zmm3,  [rdx + 192]
    vmulpd       zmm20, zmm16, zmm30
    vmulpd       zmm21, zmm17, zmm30
    vmulpd       zmm22, zmm18, zmm30
    vmulpd       zmm23, zmm19, zmm30
    vfmsub132pd  zmm0,  zmm16, [rdx + 0]
    vfmsub132pd  zmm1,  zmm17, [rdx + 64]
    vfmsub132pd  zmm2,  zmm18, [rdx + 128]
    vfmsub132pd  zmm3,  zmm19, [rdx + 192]
    vrndscalepd  zmm20, zmm20, 8
    vrndscalepd  zmm21, zmm21, 8
    vrndscalepd  zmm22, zmm22, 8
    vrndscalepd  zmm23, zmm23, 8
    vfnmadd231pd zmm16, zmm20, zmm29
    vfnmadd231pd zmm17, zmm21, zmm29
    vfnmadd231pd zmm18, zmm22, zmm29
    vfnmadd231pd zmm19, zmm23, zmm29

    vmulpd       zmm20, zmm4,  [rdx + 256]
    vmulpd       zmm21, zmm5,  [rdx + 320]
    vmulpd       zmm22, zmm24, [rdx + 384]
    vmulpd       zmm23, zmm25, [rdx + 448]
    vaddpd       zmm0,  zmm16, zmm0
    vaddpd       zmm1,  zmm17, zmm1
    vaddpd       zmm2,  zmm18, zmm2
    vaddpd       zmm3,  zmm19, zmm3
    vmulpd       zmm16, zmm20, zmm30
    vmulpd       zmm17, zmm21, zmm30
    vmulpd       zmm18, zmm22, zmm30
    vmulpd       zmm19, zmm23, zmm30
    vfmsub132pd  zmm4,  zmm20, [rdx + 256]
    vfmsub132pd  zmm5,  zmm21, [rdx + 320]
    vfmsub132pd  zmm24, zmm22, [rdx + 384]
    vfmsub132pd  zmm25, zmm23, [rdx + 448]
    vcmppd       k1, zmm0, zmm31, 1
    vcmppd       k2, zmm1, zmm31, 1
    vcmppd       k3, zmm2, zmm31, 1
    vcmppd       k4, zmm3, zmm31, 1
    vaddpd       zmm0 {k1}, zmm0, zmm29
    vaddpd       zmm1 {k2}, zmm1, zmm29
    vaddpd       zmm2 {k3}, zmm2, zmm29
    vaddpd       zmm3 {k4}, zmm3, zmm29

    vrndscalepd  zmm16, zmm16, 8
    vrndscalepd  zmm17, zmm17, 8
    vrndscalepd  zmm18, zmm18, 8
    vrndscalepd  zmm19, zmm19, 8
    vfnmadd231pd zmm20, zmm16, zmm29
    vfnmadd231pd zmm21, zmm17, zmm29
    vfnmadd231pd zmm22, zmm18, zmm29
    vfnmadd231pd zmm23, zmm19, zmm29
    vaddpd       zmm4,  zmm20, zmm4
    vaddpd       zmm5,  zmm21, zmm5
    vaddpd       zmm24, zmm22, zmm24
    vaddpd       zmm25, zmm23, zmm25
    vcmppd       k1, zmm4,  zmm31, 1
    vcmppd       k2, zmm5,  zmm31, 1
    vcmppd       k3, zmm24, zmm31, 1
    vcmppd       k4, zmm25, zmm31, 1
    vaddpd       zmm4  {k1}, zmm4,  zmm29
    vaddpd       zmm5  {k2}, zmm5,  zmm29
    vaddpd       zmm24 {k3}, zmm24, zmm29
    vaddpd       zmm25 {k4}, zmm25, zmm29

    vmovupd [rdi + 0],   zmm0
    vmovupd [rdi + 64],  zmm1
    vmovupd [rdi + 128], zmm2
    vmovupd [rdi + 192], zmm3
    vmovupd [rdi + 256], zmm4
    vmovupd [rdi + 320], zmm5
    vmovupd [rdi + 384], zmm24
    vmovupd [rdi + 448], zmm25

    lea  rsi, [rsi + 512]
    lea  rdx, [rdx + 512]
    lea  rdi, [rdi + 512]
    sub  r8,  64
    cmp  r8,  64
    jae  .Lnttpmul_loop64

.Lnttpmul_check32:
    cmp  r8,  32
    jb   .Lnttpmul_check8
.p2align 4
.Lnttpmul_loop32:
    vmovupd zmm0,  [rsi + 0]
    vmovupd zmm1,  [rsi + 64]
    vmovupd zmm2,  [rsi + 128]
    vmovupd zmm3,  [rsi + 192]
    vmovupd zmm4,  [rdx + 0]
    vmovupd zmm5,  [rdx + 64]
    vmovupd zmm24, [rdx + 128]
    vmovupd zmm25, [rdx + 192]

    vmulpd       zmm16, zmm0, zmm4
    vmulpd       zmm17, zmm1, zmm5
    vmulpd       zmm18, zmm2, zmm24
    vmulpd       zmm19, zmm3, zmm25
    vmulpd       zmm20, zmm16, zmm30
    vmulpd       zmm21, zmm17, zmm30
    vmulpd       zmm22, zmm18, zmm30
    vmulpd       zmm23, zmm19, zmm30
    vfmsub213pd  zmm0,  zmm4,  zmm16
    vfmsub213pd  zmm1,  zmm5,  zmm17
    vfmsub213pd  zmm2,  zmm24, zmm18
    vfmsub213pd  zmm3,  zmm25, zmm19
    vrndscalepd  zmm20, zmm20, 8
    vrndscalepd  zmm21, zmm21, 8
    vrndscalepd  zmm22, zmm22, 8
    vrndscalepd  zmm23, zmm23, 8
    vfnmadd231pd zmm16, zmm20, zmm29
    vfnmadd231pd zmm17, zmm21, zmm29
    vfnmadd231pd zmm18, zmm22, zmm29
    vfnmadd231pd zmm19, zmm23, zmm29
    vaddpd       zmm0,  zmm16, zmm0
    vaddpd       zmm1,  zmm17, zmm1
    vaddpd       zmm2,  zmm18, zmm2
    vaddpd       zmm3,  zmm19, zmm3
    vcmppd       k1, zmm0, zmm31, 1
    vcmppd       k2, zmm1, zmm31, 1
    vcmppd       k3, zmm2, zmm31, 1
    vcmppd       k4, zmm3, zmm31, 1
    vaddpd       zmm0 {k1}, zmm0, zmm29
    vaddpd       zmm1 {k2}, zmm1, zmm29
    vaddpd       zmm2 {k3}, zmm2, zmm29
    vaddpd       zmm3 {k4}, zmm3, zmm29

    vmovupd [rdi + 0],   zmm0
    vmovupd [rdi + 64],  zmm1
    vmovupd [rdi + 128], zmm2
    vmovupd [rdi + 192], zmm3
    lea  rsi, [rsi + 256]
    lea  rdx, [rdx + 256]
    lea  rdi, [rdi + 256]
    sub  r8,  32
    cmp  r8,  32
    jae  .Lnttpmul_loop32

.Lnttpmul_check8:
    cmp  r8,  8
    jb   .Lnttpmul_tail
.Lnttpmul_loop8:
    vmovupd zmm0, [rsi]
    vmovupd zmm1, [rdx]
    ZMM_MUL_MOD zmm0, zmm1, zmm16, zmm20, k1
    vmovupd [rdi], zmm0
    lea  rsi, [rsi + 64]
    lea  rdx, [rdx + 64]
    lea  rdi, [rdi + 64]
    sub  r8,  8
    cmp  r8,  8
    jae  .Lnttpmul_loop8

.Lnttpmul_tail:
    test r8,  r8
    jz   .Lnttpmul_done
    mov  eax, 0xFF
    bzhi eax, eax, r8d
    kmovw k5, eax
    vmovupd zmm0 {k5}{z}, [rsi]
    vmovupd zmm1 {k5}{z}, [rdx]
    ZMM_MUL_MOD zmm0, zmm1, zmm16, zmm20, k1
    vmovupd [rdi] {k5}, zmm0
    jmp  .Lnttpmul_done

.Lnttpmul_row_twist:
    cmp  r8,  r9
    jb   .Lnttpmul_done
    cmp  r9,  64
    je   .Lnttpmul_tw64_row
    cmp  r9,  32
    jne  .Lnttpmul_tw_row
    cmp  r8,  64
    jb   .Lnttpmul_tw_row
.p2align 4
.Lnttpmul_tw32_pair:
    vbroadcastsd zmm26, [rdx + 0]
    vbroadcastsd zmm27, [rdx + 8]
    vmulpd       zmm28, zmm26, zmm30
    add  rdx, 16
    sub  r8,  64

    vmovupd zmm0,  [rdi + 0]
    vmovupd zmm1,  [rdi + 64]
    vmovupd zmm2,  [rdi + 128]
    vmovupd zmm3,  [rdi + 192]
    vmovupd zmm4,  [rdi + 256]
    vmovupd zmm5,  [rdi + 320]
    vmovupd zmm24, [rdi + 384]
    vmovupd zmm25, [rdi + 448]

    // Multiply 1 (tile * tw_tile0) overlapped across Row 0 (zmm0..3) and Row 1 (zmm4,5,24,25)
    vmulpd       zmm16, zmm0, [rsi + 0]
    vmulpd       zmm17, zmm1, [rsi + 64]
    vmulpd       zmm18, zmm2, [rsi + 128]
    vmulpd       zmm19, zmm3, [rsi + 192]
    vmulpd       zmm20, zmm16, zmm30
    vmulpd       zmm21, zmm17, zmm30
    vmulpd       zmm22, zmm18, zmm30
    vmulpd       zmm23, zmm19, zmm30
    vfmsub132pd  zmm0,  zmm16, [rsi + 0]
    vfmsub132pd  zmm1,  zmm17, [rsi + 64]
    vfmsub132pd  zmm2,  zmm18, [rsi + 128]
    vfmsub132pd  zmm3,  zmm19, [rsi + 192]
    vrndscalepd  zmm20, zmm20, 8
    vrndscalepd  zmm21, zmm21, 8
    vrndscalepd  zmm22, zmm22, 8
    vrndscalepd  zmm23, zmm23, 8
    vfnmadd231pd zmm16, zmm20, zmm29
    vfnmadd231pd zmm17, zmm21, zmm29
    vfnmadd231pd zmm18, zmm22, zmm29
    vfnmadd231pd zmm19, zmm23, zmm29

    vmulpd       zmm20, zmm4,  [rsi + 256]
    vmulpd       zmm21, zmm5,  [rsi + 320]
    vmulpd       zmm22, zmm24, [rsi + 384]
    vmulpd       zmm23, zmm25, [rsi + 448]
    vaddpd       zmm0,  zmm16, zmm0
    vaddpd       zmm1,  zmm17, zmm1
    vaddpd       zmm2,  zmm18, zmm2
    vaddpd       zmm3,  zmm19, zmm3
    vmulpd       zmm16, zmm20, zmm30
    vmulpd       zmm17, zmm21, zmm30
    vmulpd       zmm18, zmm22, zmm30
    vmulpd       zmm19, zmm23, zmm30
