    vmovupd zmm1, [rsi]
    ZMM_MUL_MOD zmm0, zmm1, zmm16, zmm20, k1
    ZMM_MUL_MOD zmm0, zmm28, zmm16, zmm20, k1
    vmovupd [rdi], zmm0
    lea  rsi, [rsi + 64]
    lea  rdi, [rdi + 64]
    sub  r10, 8
    cmp  r10, 8
    jae  .Lnttpmul_tw_loop8

