    jz   .Lnttpmul_tw_next
    mov  eax, 0xFF
    bzhi eax, eax, r10d
    kmovw k5, eax
    vmovupd zmm0 {k5}{z}, [rdi]
    vmovupd zmm1 {k5}{z}, [rsi]
    ZMM_MUL_MOD zmm0, zmm1, zmm16, zmm20, k1
    ZMM_MUL_MOD zmm0, zmm28, zmm16, zmm20, k1
    vmovupd [rdi] {k5}, zmm0
    lea  rsi, [rsi + 8*r10]
    lea  rdi, [rdi + 8*r10]
.Lnttpmul_tw_next:
    cmp  r8,  r9
    jae  .Lnttpmul_tw_row

.Lnttpmul_done:
.Lnttpmul_ret:
