// [18] ntt_pmuladd(dst: rdi, ptrs: rsi /* &[a1,b1,a2,b2] */, cfg: rdx)
// When b1 == null: dst[i] = (a1[i] +/- (a2[i] * b2[i]) mod p) mod p
