.macro ZMM_RED_P4 A0, A1, A2, A3
    vcmppd k1, \A0, zmm29, 13
    vcmppd k2, \A1, zmm29, 13
    vcmppd k3, \A2, zmm29, 13
    vcmppd k4, \A3, zmm29, 13
    vsubpd \A0 {k1}, \A0, zmm29
    vsubpd \A1 {k2}, \A1, zmm29
    vsubpd \A2 {k3}, \A2, zmm29
    vsubpd \A3 {k4}, \A3, zmm29
.endm

.macro ZMM_ADD_MOD4 A0, A1, A2, A3, B0, B1, B2, B3
    vaddpd \A0, \A0, \B0
    vaddpd \A1, \A1, \B1
    vaddpd \A2, \A2, \B2
    vaddpd \A3, \A3, \B3
    ZMM_RED_P4 \A0, \A1, \A2, \A3
.endm

.macro ZMM_SUB_MOD4 D0, D1, D2, D3, R0, R1, R2, R3, A0, A1, A2, A3
    vsubpd \D0, \R0, \A0
    vsubpd \D1, \R1, \A1
    vsubpd \D2, \R2, \A2
    vsubpd \D3, \R3, \A3
    vcmppd k1, \D0, zmm31, 1
    vcmppd k2, \D1, zmm31, 1
    vcmppd k3, \D2, zmm31, 1
    vcmppd k4, \D3, zmm31, 1
    vaddpd \D0 {k1}, \D0, zmm29
    vaddpd \D1 {k2}, \D1, zmm29
    vaddpd \D2 {k3}, \D2, zmm29
    vaddpd \D3 {k4}, \D3, zmm29
.endm

// Lazy 4-ZMM Horner step: A0..3 = (A0..3 * Y (mod p_i)) + [MEM_BASE + MEM_OFF + 0..192].
// Zero mask instructions; uses ONLY zmm16..19 and zmm23..26 (preserving zmm6..15, zmm20..22).
.macro ZMM_HORNER_LAZY4 A0, A1, A2, A3, Y, MEM_BASE, MEM_OFF
    vmulpd       zmm16, \A0, \Y
    vmulpd       zmm17, \A1, \Y
    vmulpd       zmm18, \A2, \Y
    vmulpd       zmm19, \A3, \Y
    vmulpd       zmm23, zmm16, zmm30
    vmulpd       zmm24, zmm17, zmm30
    vmulpd       zmm25, zmm18, zmm30
    vmulpd       zmm26, zmm19, zmm30
    vfmsub213pd  \A0, \Y, zmm16
    vfmsub213pd  \A1, \Y, zmm17
    vfmsub213pd  \A2, \Y, zmm18
    vfmsub213pd  \A3, \Y, zmm19
    vrndscalepd  zmm23, zmm23, 8
    vrndscalepd  zmm24, zmm24, 8
    vrndscalepd  zmm25, zmm25, 8
    vrndscalepd  zmm26, zmm26, 8
    vfnmadd231pd zmm16, zmm23, zmm29
    vfnmadd231pd zmm17, zmm24, zmm29
    vfnmadd231pd zmm18, zmm25, zmm29
    vfnmadd231pd zmm19, zmm26, zmm29
    vaddpd       \A0, zmm16, \A0
    vaddpd       \A1, zmm17, \A1
    vaddpd       \A2, zmm18, \A2
    vaddpd       \A3, zmm19, \A3
    vaddpd       \A0, \A0, [\MEM_BASE + \MEM_OFF + 0]
    vaddpd       \A1, \A1, [\MEM_BASE + \MEM_OFF + 64]
    vaddpd       \A2, \A2, [\MEM_BASE + \MEM_OFF + 128]
    vaddpd       \A3, \A3, [\MEM_BASE + \MEM_OFF + 192]
.endm

// Shoup-FMA 4-ZMM lazy Horner step & canonical modular multiply reading sequential (w, wp) from [r9]:
// Breaks the serial H -> Q_raw dependency chain (-4 cycles latency per step!).
// Scratch: zmm4, zmm5, zmm16..19, zmm23..26 (preserving zmm6..15, zmm20..22, zmm29..31).
.macro ZMM_HORNER_SHOUP4 A0, A1, A2, A3, MEM_BASE, MEM_OFF
    vbroadcastsd zmm4,  [r9 + 0]
    vbroadcastsd zmm5,  [r9 + 8]
    add          r9,    16
    vmulpd       zmm16, \A0, zmm4
    vmulpd       zmm17, \A1, zmm4
    vmulpd       zmm18, \A2, zmm4
    vmulpd       zmm19, \A3, zmm4
    vmulpd       zmm23, \A0, zmm5
    vmulpd       zmm24, \A1, zmm5
    vmulpd       zmm25, \A2, zmm5
    vmulpd       zmm26, \A3, zmm5
    vfmsub213pd  \A0,   zmm4, zmm16
    vfmsub213pd  \A1,   zmm4, zmm17
    vfmsub213pd  \A2,   zmm4, zmm18
    vfmsub213pd  \A3,   zmm4, zmm19
    vrndscalepd  zmm23, zmm23, 8
    vrndscalepd  zmm24, zmm24, 8
    vrndscalepd  zmm25, zmm25, 8
    vrndscalepd  zmm26, zmm26, 8
    vfnmadd231pd zmm16, zmm23, zmm29
    vfnmadd231pd zmm17, zmm24, zmm29
    vfnmadd231pd zmm18, zmm25, zmm29
    vfnmadd231pd zmm19, zmm26, zmm29
    vaddpd       \A0,   zmm16, \A0
    vaddpd       \A1,   zmm17, \A1
    vaddpd       \A2,   zmm18, \A2
    vaddpd       \A3,   zmm19, \A3
    vaddpd       \A0,   \A0, [\MEM_BASE + \MEM_OFF + 0]
    vaddpd       \A1,   \A1, [\MEM_BASE + \MEM_OFF + 64]
    vaddpd       \A2,   \A2, [\MEM_BASE + \MEM_OFF + 128]
    vaddpd       \A3,   \A3, [\MEM_BASE + \MEM_OFF + 192]
.endm

.macro ZMM_MUL_MOD_SHOUP4 A0, A1, A2, A3
    vbroadcastsd zmm4,  [r9 + 0]
    vbroadcastsd zmm5,  [r9 + 8]
    add          r9,    16
    vmulpd       zmm16, \A0, zmm4
    vmulpd       zmm17, \A1, zmm4
    vmulpd       zmm18, \A2, zmm4
    vmulpd       zmm19, \A3, zmm4
    vmulpd       zmm23, \A0, zmm5
    vmulpd       zmm24, \A1, zmm5
    vmulpd       zmm25, \A2, zmm5
    vmulpd       zmm26, \A3, zmm5
    vfmsub213pd  \A0,   zmm4, zmm16
    vfmsub213pd  \A1,   zmm4, zmm17
    vfmsub213pd  \A2,   zmm4, zmm18
    vfmsub213pd  \A3,   zmm4, zmm19
    vrndscalepd  zmm23, zmm23, 8
    vrndscalepd  zmm24, zmm24, 8
    vrndscalepd  zmm25, zmm25, 8
    vrndscalepd  zmm26, zmm26, 8
    vfnmadd231pd zmm16, zmm23, zmm29
    vfnmadd231pd zmm17, zmm24, zmm29
    vfnmadd231pd zmm18, zmm25, zmm29
    vfnmadd231pd zmm19, zmm26, zmm29
    vaddpd       \A0,   zmm16, \A0
    vaddpd       \A1,   zmm17, \A1
    vaddpd       \A2,   zmm18, \A2
    vaddpd       \A3,   zmm19, \A3
    vcmppd       k1,    \A0, zmm31, 1
    vcmppd       k2,    \A1, zmm31, 1
    vcmppd       k3,    \A2, zmm31, 1
    vcmppd       k4,    \A3, zmm31, 1
    vaddpd       \A0 {k1}, \A0, zmm29
    vaddpd       \A1 {k2}, \A1, zmm29
    vaddpd       \A2 {k3}, \A2, zmm29
    vaddpd       \A3 {k4}, \A3, zmm29
.endm


// Lazy 4-ZMM difference & signed FMA reduction: A0..3 = ([R_BASE + 0..192] - A0..3) mod p_i in [-0.501p, 0.501p].
// Uses ONLY zmm4, zmm5, zmm27, zmm28 and zmm23..26 (preserving zmm6..15, zmm20..22).
.macro ZMM_SUB_RED4 A0, A1, A2, A3, R_BASE
    vmovupd      zmm4,  [\R_BASE + 0]
    vmovupd      zmm5,  [\R_BASE + 64]
    vmovupd      zmm27, [\R_BASE + 128]
    vmovupd      zmm28, [\R_BASE + 192]
    vsubpd       \A0, zmm4,  \A0
    vsubpd       \A1, zmm5,  \A1
    vsubpd       \A2, zmm27, \A2
    vsubpd       \A3, zmm28, \A3
    vmulpd       zmm23, \A0, zmm30
    vmulpd       zmm24, \A1, zmm30
    vmulpd       zmm25, \A2, zmm30
    vmulpd       zmm26, \A3, zmm30
    vrndscalepd  zmm23, zmm23, 8
    vrndscalepd  zmm24, zmm24, 8
    vrndscalepd  zmm25, zmm25, 8
    vrndscalepd  zmm26, zmm26, 8
    vfnmadd231pd \A0, zmm23, zmm29
    vfnmadd231pd \A1, zmm24, zmm29
    vfnmadd231pd \A2, zmm25, zmm29
    vfnmadd231pd \A3, zmm26, zmm29
.endm

// [19] ntt_crt(out_limbs: rdi, residues: rsi, cfg: rdx) -> rax (w0)
// NttCrtCfg: k_primes@0, count@8, coeff_bits@16, out_limbs@24, signed@32,
//            wrap_cyclic@40, primes@48, inv_primes@56, garner_inv@64,
//            prefix_prods@72, k_words@80, carry_limbs@88,
//            segments@96, seg_res_stride@104, seg_out_stride@112, seg_carry_stride@120,
//            seg_w0@128, seg_w0_stride@136
// With segments >= 2 the call is `segments` streams of `count` coefficients: stream s reads
// residues[i] + s*seg_res_stride, writes out_limbs limbs at out + s*seg_out_stride, starts with
// a zero carry and leaves its carry at carry_limbs + s*seg_carry_stride and its check word at
// seg_w0[s*seg_w0_stride]; rax is 0.
// Stack layout (2496 bytes, 64-byte aligned):
//   [rsp +    0 .. 1152): v_buf[18][8] (or v_buf32[0..4][32] on 32-lane fast path)
//   [rsp + 1152 .. 1312): carry[20]
//   [rsp + 1312 .. 1472): coeff_val[20] ([rsp + 1344 .. 1600): W0..W3[8] on 32-lane fast path)
//   [rsp + 1472 .. 1632): mag[20]
//   [rsp + 1632 .. 2112): saved scalars, preloaded prefix_prods, radix-2^30 limbs, res_ptrs
//   [rsp + 2112 .. 2368): v4_buf32[32] on 32-lane k=5 fast path
//   [rsp + 2368 .. 2496): P4 radix-2^30 limbs [0..7] and saved p4 Garner scalars
//   [rsp + 1936]: base of the block area; [rsp + 1944]: 0 = the paths below emit coefficient by
//   coefficient, 1 = one stream through the block path, 2 = many segments through it
// Block area, 16576 bytes above whichever frame is in use; offsets from its base:
//   [0 .. 8192): words of up to 8 vectors of 8 coefficients, vector v plane w at v*1024 + w*64
//   [8192 .. 10368): field planes; [10368 .. 10624), [10624 .. 10752), [10752 .. 10816):
//   B (4 planes), C (2 planes) and E of the vector before; [10816 .. 10944): carry out;
//   [10944 .. 11200): carry parts of the segments ending in a block; [11200 .. 15808): mixed-radix
//   digits of 8 vectors per prime; [15808 .. 16296): tables of the block and of one segment;
//   [16296 .. 16576): scalars
LOCAL_FN supi_k_ntt_crt
    VEC_ENTER 19712
    lea  r11, [rsp + 2560]              // the block area lies above the base frame
    cmp  qword ptr [rdx + 0], 5
    jbe  .Lcrt_frame_ready
    sub  rsp, 3456
    mov  qword ptr [rsp], 0
    cmp  qword ptr [rdx + 0], 9
    ja   .Lcrt_alloc_wide
    cmp  qword ptr [rdx + 16], 240
    ja   .Lcrt_alloc_wide
    mov  rax, [rdx + 80]
    inc  rax
    cmp  rax, [rdx + 0]
    je   .Lcrt_frame_ready
.Lcrt_alloc_wide:
    .rept 5
        sub  rsp, 4096
        mov  qword ptr [rsp], 0
    .endr
.Lcrt_frame_ready:
    mov  [rsp + 1936], r11
    mov  [rsp + 1632], rdi              // out_limbs ptr
    mov  [rsp + 1640], rsi              // residues **
    mov  [rsp + 1648], rdx              // cfg *

    mov  rax, [rdx + 0]
    mov  [rsp + 1808], rax              // k_primes
    mov  rax, [rdx + 8]
    mov  [rsp + 1816], rax              // count
    mov  rax, [rdx + 16]
    mov  [rsp + 1824], rax              // b = coeff_bits
    mov  r12, [rdx + 24]
    mov  [rsp + 1832], r12              // out_len
    mov  rax, [rdx + 32]
    mov  [rsp + 1840], rax              // signed
    mov  r13, [rdx + 80]
    mov  [rsp + 1848], r13              // k_words

    // Unsigned single-stream non-wrapping calls with carry_limbs == NULL never depend on
    // coefficients past ceil(out_len * 64 / b): cap count to the 32-lane multiple covering out_len!
    test rax, rax
    jnz  .Lcrt_cap_count_done
    cmp  qword ptr [rdx + 96], 2
    jae  .Lcrt_cap_count_done
    mov  rcx, [rdx + 40]                // wrap_cyclic
    or   rcx, [rdx + 88]                // | carry_limbs
    jnz  .Lcrt_cap_count_done
    mov  rcx, [rsp + 1824]              // b
    test rcx, rcx
    jz   .Lcrt_cap_count_done
    mov  rax, r12
    shr  rax, 57
    jnz  .Lcrt_cap_count_done
    mov  rax, r12
    shl  rax, 6                         // out_len * 64
    lea  rax, [rax + rcx - 1]
    xor  edx, edx
    div  rcx                            // ceil(out_len * 64 / b)
    mov  rdx, [rsp + 1648]              // restore cfg *
    add  rax, 31
    and  rax, -32                       // 32-lane aligned cap
    cmp  rax, [rsp + 1816]
    jae  .Lcrt_cap_count_done
    mov  [rsp + 1816], rax
.Lcrt_cap_count_done:

    // Check register-resident 4-word streaming bit-buffer eligibility:
    //   k_words <= 4 && k_primes <= 5 && k_words >= k_primes - 1 && 1 <= b <= 128
    xor  eax, eax
    cmp  r13, 4
    ja   .Lcrt_set_fast_flag
    mov  rcx, [rsp + 1808]              // k_primes
    cmp  rcx, 5
    ja   .Lcrt_set_fast_flag
    lea  rbx, [rcx - 1]
    cmp  r13, rbx
    jb   .Lcrt_set_fast_flag
    mov  rcx, [rsp + 1824]              // b = coeff_bits
    test rcx, rcx
    jz   .Lcrt_set_fast_flag
    cmp  rcx, 128
    ja   .Lcrt_set_fast_flag
    mov  eax, 1
.Lcrt_set_fast_flag:
    mov  [rsp + 1888], rax              // is_fast4

    // Check 6..9-prime 32-lane vectorized CRT + streaming bit-buffer eligibility:
    //   k_primes in 6..9 && k_words == k_primes - 1 && 1 <= b <= 240
    xor  ebx, ebx
    mov  rcx, [rsp + 1824]              // b = coeff_bits
    sub  rcx, 1
    cmp  rcx, 239
    ja   .Lcrt_set_fast67_flag
    mov  rcx, [rsp + 1808]              // k_primes
    sub  rcx, 6
    cmp  rcx, 3
    ja   .Lcrt_set_fast67_flag
    mov  rcx, [rsp + 1808]
    dec  rcx
    cmp  r13, rcx
    jne  .Lcrt_set_fast67_flag
    mov  ebx, 1
.Lcrt_set_fast67_flag:
    mov  [rsp + 2496], rbx              // is_fast_k69
    or   rax, rbx

    // Check general 6..18-prime 32-lane vectorized CRT + streaming bit-buffer eligibility:
    //   !(is_fast4 || is_fast_k69) && k_primes in 6..18 && k_words in 5..16 && 1 <= b <= 384 && b <= 64*k_words
    xor  edx, edx
    test rax, rax
    jnz  .Lcrt_set_wide_flag
    mov  rcx, [rsp + 1808]              // k_primes
    sub  rcx, 6
    cmp  rcx, 12
    ja   .Lcrt_set_wide_flag
    mov  rcx, r13                       // k_words
    sub  rcx, 5
    cmp  rcx, 11
    ja   .Lcrt_set_wide_flag
    mov  rcx, [rsp + 1824]              // b
    sub  rcx, 1
    cmp  rcx, 383
    ja   .Lcrt_set_wide_flag
    mov  rcx, r13
    shl  rcx, 6
    cmp  [rsp + 1824], rcx
    ja   .Lcrt_set_wide_flag
    mov  edx, 1
.Lcrt_set_wide_flag:
    mov  [rsp + 2536], rdx              // is_fast_k_wide
    or   rax, rdx
    jnz  .Lcrt_init_fast_stream

    // Generic path: pre-zero out_limbs[0 .. out_len]
    vpxorq zmm0, zmm0, zmm0
    mov  rax, rdi
    mov  rcx, r12
    cmp  rcx, 8
    jb   .Lcrt_zero_tail
.Lcrt_zero8:
    vmovdqu64 [rax], zmm0
    lea  rax, [rax + 64]
    sub  rcx, 8
    cmp  rcx, 8
    jae  .Lcrt_zero8
.Lcrt_zero_tail:
    test rcx, rcx
    jz   .Lcrt_zero_done
    xor  ebx, ebx
.Lcrt_zero1:
    mov  [rax], rbx
    lea  rax, [rax + 8]
    dec  rcx
    jnz  .Lcrt_zero1
    jmp  .Lcrt_zero_done

.Lcrt_init_fast_stream:
    mov  [rsp + 1896], rdi              // out_cur = out_limbs
    lea  rax, [rdi + 8*r12]
    mov  [rsp + 1920], rax              // out_end = out_limbs + 8 * out_len
    xor  eax, eax
    mov  [rsp + 1904], rax              // acc_word = 0
    mov  [rsp + 1912], rax              // acc_bits = 0
.Lcrt_zero_done:

    mov  rdx, [rsp + 1648]
    mov  r13, [rsp + 1848]              // k_words
    // Initialize carry[0 .. k_words] from cfg.carry_limbs or zero
    mov  rax, [rdx + 88]                // carry_limbs
    xor  ecx, ecx
    test rax, rax
    jz   .Lcrt_init_carry_zero
.Lcrt_init_carry_copy:
    mov  rbx, [rax + 8*rcx]
    mov  [rsp + 1152 + 8*rcx], rbx
    inc  rcx
    cmp  rcx, r13
    jb   .Lcrt_init_carry_copy
    jmp  .Lcrt_init_carry_done
.Lcrt_init_carry_zero:
    xor  ebx, ebx
.Lcrt_init_carry_zloop:
    mov  [rsp + 1152 + 8*rcx], rbx
    inc  rcx
    cmp  rcx, r13
    jb   .Lcrt_init_carry_zloop
.Lcrt_init_carry_done:

    // Precompute top_p >> 1 and p_tot only when signed != 0
    mov  r14, [rsp + 1808]              // k_primes
    cmp  qword ptr [rsp + 1840], 0
    jne  .Lcrt_init_signed_ptot
    cmp  qword ptr [rsp + 2496], 0
    jne  .Lcrt_do_preload_p14
    jmp  .Lcrt_ptot67_done
.Lcrt_init_signed_ptot:
    mov  rax, [rdx + 48]                // primes *
    vcvttsd2usi rbx, [rax + 8*r14 - 8]
    shr  rbx, 1
    mov  [rsp + 1680], rbx              // top_p >> 1

    // Preload zero-extended p_tot[0..4] into [rsp + 1696 .. 1728) when k_words <= 4
    cmp  r13, 4
    ja   .Lcrt_ptot_done
    mov  rax, r14
    imul rax, r13
    mov  rcx, [rdx + 72]                // prefix_prods *
    lea  rcx, [rcx + 8*rax]             // &prefix_prods[k_primes * k_words]
    xor  eax, eax
    mov  [rsp + 1712], rax
    mov  [rsp + 1720], rax
    mov  rbx, [rcx + 0]
    mov  [rsp + 1696], rbx
    mov  rbx, [rcx + 8]
    mov  [rsp + 1704], rbx
    cmp  r13, 3
    jb   .Lcrt_ptot_done
    mov  rbx, [rcx + 16]
    mov  [rsp + 1712], rbx
    cmp  r13, 4
    jb   .Lcrt_ptot_done
    mov  rbx, [rcx + 24]
    mov  [rsp + 1720], rbx
.Lcrt_ptot_done:
    // Precompute radix-2^30 limbs PT67_0..PT67_10 of p_tot when is_fast_k67 == 1
    cmp  qword ptr [rsp + 2496], 0
    je   .Lcrt_ptot67_done
    mov  rax, r14
    imul rax, r13
    mov  rcx, [rdx + 72]                // prefix_prods *
    lea  rcx, [rcx + 8*rax]             // &prefix_prods[k_primes * k_words]
    mov  r8,  [rcx + 0]
    mov  r9,  [rcx + 8]
    mov  r10, [rcx + 16]
    mov  r11, [rcx + 24]
    mov  rsi, [rcx + 32]
    xor  edi, edi
    cmp  r13, 6
    jb   .Lcrt_ptot67_split
    mov  rdi, [rcx + 40]
.Lcrt_ptot67_split:
    mov  rax, r8
    and  eax, 0x3FFFFFFF
    mov  [rsp + 3456], rax              // PT67_0
    mov  rax, r8
    shr  rax, 30
    and  eax, 0x3FFFFFFF
    mov  [rsp + 3464], rax              // PT67_1
    shr  r8,  60
    mov  rax, r9
    shl  rax, 4
    or   r8,  rax
    and  r8d, 0x3FFFFFFF
    mov  [rsp + 3472], r8               // PT67_2
    mov  rax, r9
    shr  rax, 26
    and  eax, 0x3FFFFFFF
    mov  [rsp + 3480], rax              // PT67_3
    shr  r9,  56
    mov  rax, r10
    shl  rax, 8
    or   r9,  rax
    and  r9d, 0x3FFFFFFF
    mov  [rsp + 3488], r9               // PT67_4
    mov  rax, r10
    shr  rax, 22
    and  eax, 0x3FFFFFFF
    mov  [rsp + 3496], rax              // PT67_5
    shr  r10, 52
    mov  rax, r11
    shl  rax, 12
    or   r10, rax
    and  r10d, 0x3FFFFFFF
    mov  [rsp + 3504], r10              // PT67_6
    mov  rax, r11
    shr  rax, 18
    and  eax, 0x3FFFFFFF
    mov  [rsp + 3512], rax              // PT67_7
    shr  r11, 48
    mov  rax, rsi
    shl  rax, 16
    or   r11, rax
    and  r11d, 0x3FFFFFFF
    mov  [rsp + 3808], r11              // PT67_8
    mov  rax, rsi
    shr  rax, 14
    and  eax, 0x3FFFFFFF
    mov  [rsp + 3816], rax              // PT67_9
    shr  rsi, 44
    mov  rax, rdi
    shl  rax, 20
    or   rsi, rax
    cmp  r14, 8
    jb   .Lcrt_ptot_store10
    and  esi, 0x3FFFFFFF
    mov  [rsp + 3824], rsi              // PT_10 (30 bits)
    mov  r8,  [rcx + 48]                // W6
    xor  r9d, r9d
    cmp  r13, 8
    jb   .Lcrt_ptot89_split
    mov  r9,  [rcx + 56]                // W7
.Lcrt_ptot89_split:
    mov  rax, rdi
    shr  rax, 10
    and  eax, 0x3FFFFFFF
    mov  [rsp + 5824], rax              // PT_11
    shr  rdi, 40
    mov  rax, r8
    shl  rax, 24
    or   rdi, rax
    and  edi, 0x3FFFFFFF
    mov  [rsp + 5832], rdi              // PT_12
    mov  rax, r8
    shr  rax, 6
    and  eax, 0x3FFFFFFF
    mov  [rsp + 5840], rax              // PT_13
    shr  r8,  36
    shl  r9,  28
    or   r8,  r9
    mov  [rsp + 5848], r8               // PT_14 (< 2^30)
    jmp  .Lcrt_do_preload_p14
.Lcrt_ptot_store10:
    mov  [rsp + 3824], rsi              // PT67_10 (< 2^50)
    jmp  .Lcrt_do_preload_p14
.Lcrt_ptot67_done:

    // Preload P1..P4 into [rsp + 1728 .. 1808) when fast 4-word lane path applies
    cmp  r13, 4
    ja   .Lcrt_p14_done
    cmp  r14, 5
    ja   .Lcrt_p14_done
    lea  rcx, [r14 - 1]
    cmp  r13, rcx
    jb   .Lcrt_p14_done
    cmp  r14, 2
    jb   .Lcrt_p14_done
.Lcrt_do_preload_p14:
    mov  rcx, [rdx + 72]                // prefix_prods *
    lea  rsi, [rcx + 8*r13]             // &prefix_prods[1 * k_words]
    mov  rbx, [rsi + 0]
    mov  [rsp + 1728], rbx              // P1[0]
    cmp  r14, 3
    jb   .Lcrt_p14_done
    lea  rsi, [rsi + 8*r13]             // &prefix_prods[2 * k_words]
    mov  rbx, [rsi + 0]
    mov  [rsp + 1736], rbx              // P2[0]
    mov  rbx, [rsi + 8]
    mov  [rsp + 1744], rbx              // P2[1]
    cmp  r14, 4
    jb   .Lcrt_p14_done
    lea  rsi, [rsi + 8*r13]             // &prefix_prods[3 * k_words]
    mov  rbx, [rsi + 0]
    mov  [rsp + 1752], rbx              // P3[0]
    mov  rbx, [rsi + 8]
    mov  [rsp + 1760], rbx              // P3[1]
    mov  rbx, [rsi + 16]
    mov  [rsp + 1768], rbx              // P3[2]
    cmp  r14, 5
    jb   .Lcrt_p14_done
    lea  rsi, [rsi + 8*r13]             // &prefix_prods[4 * k_words]
    mov  rbx, [rsi + 0]
    mov  [rsp + 1776], rbx              // P4[0]
    mov  rbx, [rsi + 8]
    mov  [rsp + 1784], rbx              // P4[1]
    mov  rbx, [rsi + 16]
    mov  [rsp + 1792], rbx              // P4[2]
    mov  rbx, [rsi + 24]
    mov  [rsp + 1800], rbx              // P4[3]

.Lcrt_p14_done:
    // Precompute radix-2^30 limbs of P1..P8 (and PT3/PT4 for signed k=3/4) for AVX512F vpmuludq 8-lane reconstruction
    mov  rax, [rsp + 1888]
    or   rax, [rsp + 2496]
    jz   .Lcrt_r30_done
    cmp  r14, 3
    jb   .Lcrt_r30_done
    cmp  r14, 9
    ja   .Lcrt_r30_done

    // Precompute sequential Shoup (w, wp) pairs for 32/64-lane Garner at [r15 + 16576 .. 17152):
    // Uses only xmm0..xmm2 so preloaded zmm6..zmm15, zmm21..zmm28 remain untouched for 8-lane tails!
    mov  rdx, [rsp + 1648]              // cfg *
    mov  r8,  [rdx + 48]                // primes *
    mov  r9,  [rdx + 56]                // inv_primes *
    mov  r10, [rdx + 64]                // garner_inv *
    mov  rdi, [rsp + 1936]
    add  rdi, 16576
    mov  ecx, 1                         // i = 1
.Lcrt_shoup_i:
    vmovsd xmm0, [r8 + 8*rcx]           // p_i
    vmovsd xmm1, [r9 + 8*rcx]           // inv_p_i
    lea  rbx, [rcx - 2]                 // j = i - 2
    test rbx, rbx
    js   .Lcrt_shoup_ginv
.Lcrt_shoup_j:
    vmovsd xmm2, [r8 + 8*rbx]           // p_j
    vcmpsd k1, xmm2, xmm0, 13
    vsubsd xmm2 {k1}, xmm2, xmm0        // w = p_j mod p_i
    vmovsd [rdi + 0], xmm2
    vmulsd xmm2, xmm2, xmm1             // wp = w * inv_p_i
    vmovsd [rdi + 8], xmm2
    add  rdi, 16
    dec  rbx
    jns  .Lcrt_shoup_j
.Lcrt_shoup_ginv:
    vmovsd xmm2, [r10 + 8*rcx]          // ginv_i
    vmovsd [rdi + 0], xmm2
    vmulsd xmm2, xmm2, xmm1             // ginv_wp_i = ginv_i * inv_p_i
    vmovsd [rdi + 8], xmm2
    add  rdi, 16
    inc  rcx
    cmp  rcx, r14
    jb   .Lcrt_shoup_i

    mov  eax, 0x3FFFFFFF
    mov  [rsp + 2072], rax              // MASK30
    mov  rbx, [rsp + 1728]              // P1[0]
    mov  rcx, rbx
    and  ecx, 0x3FFFFFFF
    mov  [rsp + 1984], rcx              // P1_0
    shr  rbx, 30
    mov  [rsp + 1992], rbx              // P1_1

    mov  rbx, [rsp + 1736]              // P2[0]
    mov  rdx, [rsp + 1744]              // P2[1]
    mov  rcx, rbx
    and  ecx, 0x3FFFFFFF
    mov  [rsp + 2000], rcx              // P2_0
    mov  rcx, rbx
    shr  rcx, 30
    and  ecx, 0x3FFFFFFF
    mov  [rsp + 2008], rcx              // P2_1
    shr  rbx, 60
    mov  rcx, rdx
    shl  rcx, 4
    or   rbx, rcx
    and  ebx, 0x3FFFFFFF
    mov  [rsp + 2016], rbx              // P2_2
    shr  rdx, 26
    mov  [rsp + 2024], rdx              // P2_3

    cmp  r14, 4
    jae  .Lcrt_r30_p3
    cmp  qword ptr [rsp + 1840], 0
    je   .Lcrt_r30_done
