    vmovupd zmm1 {k7}{z}, [r8 + 8*rax]  // ri
    ZMM_SUB_MOD zmm0, zmm1, zmm0, k1    // diff = (ri - acc) mod pi
    vbroadcastsd zmm2, [r11 + 8*rcx]    // garner_inv[i]
    ZMM_MUL_MOD zmm0, zmm2, zmm16, zmm20, k1
    mov  rbx, rcx
    shl  rbx, 6
    vmovapd [rsp + rbx], zmm0           // v[i]

