    vmovapd zmm29, zmm9                 // p2
    vmovapd zmm30, zmm10                // inv_p2
    vcmppd  k1, zmm0, zmm29, 13
    vsubpd  zmm0 {k1}, zmm0, zmm29
    vmovapd zmm3, zmm4
    vcmppd  k2, zmm3, zmm29, 13
    vsubpd  zmm3 {k2}, zmm3, zmm29
    ZMM_MUL_MOD zmm0, zmm12, zmm16, zmm20, k1
    ZMM_ADD_MOD zmm0, zmm0, zmm3, k1
    mov  r8,  [rsp + 1872]              // res_ptrs[2]
    vmovupd zmm1 {k7}{z}, [r8 + 8*rax]
    ZMM_SUB_MOD zmm0, zmm1, zmm0, k1
    ZMM_MUL_MOD zmm0, zmm11, zmm16, zmm20, k1
