    vcmppd  k2, zmm3, zmm29, 13
    vsubpd  zmm3 {k2}, zmm3, zmm29
    ZMM_MUL_MOD zmm0, zmm26, zmm16, zmm20, k1
    ZMM_ADD_MOD zmm0, zmm0, zmm3, k1
