    or   r12, rcx
    shrx r13, r9,  rax
    shlx rcx, r10, rdx
    or   r13, rcx
    sarx r14, r10, rax
    bzhi rcx, r8,  rax
    jmp  .Lcrt_k3_pack
.Lcrt_k3_gt64:
