    shrx rbx, r8,  rdx
    bzhi rcx, r9,  rax
    jmp  .Lcrt_k3_pack
.Lcrt_k3_b64:
    mov  r12, r9
    mov  r13, r10
    mov  r14, r10
    sar  r14, 63
    mov  rcx, r8
.Lcrt_k3_pack:
