    mov  [rdx], rbx
    add  rdx, 8
.Lcrt_k4_skip_st_hi:
    sub  esi, 64
    mov  r11d, 63
    sub  r11d, r10d                     // 63 - old_acc_bits
    shr  rcx, 1
    shrx rbx, rcx, r11
.Lcrt_k4_next_lane:
