    vbroadcastsd zmm30, [rsp + 5544]    // inv_p8
    ZMM_HORNER_SHOUP4 zmm0, zmm1, zmm2, zmm3, rsp, 4416
    ZMM_HORNER_SHOUP4 zmm0, zmm1, zmm2, zmm3, rsp, 4160
    ZMM_HORNER_SHOUP4 zmm0, zmm1, zmm2, zmm3, rsp, 2816
    ZMM_HORNER_SHOUP4 zmm0, zmm1, zmm2, zmm3, rsp, 2560
    ZMM_HORNER_SHOUP4 zmm0, zmm1, zmm2, zmm3, rsp, 512
    ZMM_HORNER_SHOUP4 zmm0, zmm1, zmm2, zmm3, rsp, 256
    ZMM_HORNER_SHOUP4 zmm0, zmm1, zmm2, zmm3, rsp, 0
    mov  r8,  [rsp + 5448]              // res_ptrs[8]
    lea  r8,  [r8 + 8*rax]
    ZMM_SUB_RED4 zmm0, zmm1, zmm2, zmm3, r8
    ZMM_MUL_MOD_SHOUP4 zmm0, zmm1, zmm2, zmm3
    vcvttpd2uqq zmm0, zmm0
    vcvttpd2uqq zmm1, zmm1
    vcvttpd2uqq zmm2, zmm2
    vcvttpd2uqq zmm3, zmm3
    vmovdqa64 [rsp + 5184], zmm0
    vmovdqa64 [rsp + 5248], zmm1
    vmovdqa64 [rsp + 5312], zmm2
    vmovdqa64 [rsp + 5376], zmm3

.Lcrt32_cvt_v6:
    vcvttpd2uqq zmm0, [rsp + 4416]
    vcvttpd2uqq zmm1, [rsp + 4480]
    vcvttpd2uqq zmm2, [rsp + 4544]
    vcvttpd2uqq zmm3, [rsp + 4608]
    vmovdqa64 [rsp + 2560], zmm0
    vmovdqa64 [rsp + 2624], zmm1
    vmovdqa64 [rsp + 2688], zmm2
    vmovdqa64 [rsp + 2752], zmm3

.Lcrt32_cvt_v01:
    vcvttpd2uqq zmm0, [rsp + 0]
    vcvttpd2uqq zmm1, [rsp + 64]
    vcvttpd2uqq zmm2, [rsp + 128]
    vcvttpd2uqq zmm3, [rsp + 192]
    vmovdqa64 [rsp + 0],   zmm0
    vmovdqa64 [rsp + 64],  zmm1
    vmovdqa64 [rsp + 128], zmm2
    vmovdqa64 [rsp + 192], zmm3
    vcvttpd2uqq zmm0, [rsp + 256]
    vcvttpd2uqq zmm1, [rsp + 320]
    vcvttpd2uqq zmm2, [rsp + 384]
    vcvttpd2uqq zmm3, [rsp + 448]
    vmovdqa64 [rsp + 256], zmm0
    vmovdqa64 [rsp + 320], zmm1
    vmovdqa64 [rsp + 384], zmm2
    vmovdqa64 [rsp + 448], zmm3
    vcvttpd2uqq zmm0, [rsp + 512]
    vcvttpd2uqq zmm1, [rsp + 576]
    vcvttpd2uqq zmm2, [rsp + 640]
    vcvttpd2uqq zmm3, [rsp + 704]
    vmovdqa64 [rsp + 512], zmm0
    vmovdqa64 [rsp + 576], zmm1
    vmovdqa64 [rsp + 640], zmm2
    vmovdqa64 [rsp + 704], zmm3

.Lcrt32_after_cvt:
    vpbroadcastq zmm30, [rsp + 2072]    // MASK30 = 0x3FFFFFFF
