    mov  r12, [rsp + 1152 + 0]
    mov  r13, [rsp + 1152 + 8]
    mov  r14, [rsp + 1152 + 16]
    mov  r15, [rsp + 1152 + 24]
    kmovq k3, qword ptr [rsp + 1896]    // out_cur
    kmovq k4, qword ptr [rsp + 1920]    // out_end
    mov  eax, dword ptr [rsp + 1824]
