    vpsrlq zmm17, zmm0, 30              // C1 = v0_1

    vpandq zmm0,  zmm1, zmm30           // v1_0
    vpsrlq zmm1,  zmm1, 30              // v1_1
    vpbroadcastq zmm28, [rsp + 1984]
    vpbroadcastq zmm29, [rsp + 1992]
    vpmuludq zmm4,  zmm0, zmm28
    vpmuludq zmm5,  zmm0, zmm29
    vpaddq   zmm16, zmm16, zmm4
    vpaddq   zmm17, zmm17, zmm5
    vpmuludq zmm4,  zmm1, zmm28
    vpmuludq zmm18, zmm1, zmm29         // C2 = v1_1 * P1_1
    vpaddq   zmm17, zmm17, zmm4

    vpandq zmm0,  zmm2, zmm30           // v2_0
    vpsrlq zmm1,  zmm2, 30              // v2_1
    vpbroadcastq zmm26, [rsp + 2000]
    vpbroadcastq zmm27, [rsp + 2008]
    vpbroadcastq zmm28, [rsp + 2016]
    vpbroadcastq zmm29, [rsp + 2024]
    vpmuludq zmm4,  zmm0, zmm26
    vpmuludq zmm5,  zmm0, zmm27
    vpaddq   zmm16, zmm16, zmm4
    vpaddq   zmm17, zmm17, zmm5
    vpmuludq zmm4,  zmm1, zmm26
    vpmuludq zmm5,  zmm0, zmm28
    vpaddq   zmm17, zmm17, zmm4
    vpaddq   zmm18, zmm18, zmm5
    vpmuludq zmm4,  zmm1, zmm27
    vpmuludq zmm19, zmm0, zmm29         // C3 = v2_0 * P2_3
    vpaddq   zmm18, zmm18, zmm4
    vpmuludq zmm5,  zmm1, zmm28
    vpmuludq zmm20, zmm1, zmm29         // C4 = v2_1 * P2_3
    vpaddq   zmm19, zmm19, zmm5

