    vpsrlq zmm1,  zmm3, 30              // v3_1
    vpbroadcastq zmm25, [rsp + 2032]
    vpbroadcastq zmm26, [rsp + 2040]
    vpbroadcastq zmm27, [rsp + 2048]
    vpbroadcastq zmm28, [rsp + 2056]
    vpbroadcastq zmm29, [rsp + 2064]
    vpmuludq zmm4,  zmm0, zmm25
    vpmuludq zmm5,  zmm0, zmm26
    vpaddq   zmm16, zmm16, zmm4
    vpaddq   zmm17, zmm17, zmm5
    vpmuludq zmm4,  zmm1, zmm25
    vpmuludq zmm5,  zmm0, zmm27
    vpaddq   zmm17, zmm17, zmm4
    vpaddq   zmm18, zmm18, zmm5
    vpmuludq zmm4,  zmm1, zmm26
    vpmuludq zmm5,  zmm0, zmm28
    vpaddq   zmm18, zmm18, zmm4
    vpaddq   zmm19, zmm19, zmm5
    vpmuludq zmm4,  zmm1, zmm27
    vpmuludq zmm5,  zmm0, zmm29
    vpaddq   zmm19, zmm19, zmm4
    vpaddq   zmm20, zmm20, zmm5
