    vpbroadcastq zmm29, [rsp + 2376]
    vpmuludq zmm4,  zmm0, zmm28
    vpmuludq zmm5,  zmm0, zmm29
    vpaddq   zmm16, zmm16, zmm4
    vpaddq   zmm17, zmm17, zmm5
    vpmuludq zmm4,  zmm1, zmm28
    vpbroadcastq zmm28, [rsp + 2384]
    vpmuludq zmm5,  zmm0, zmm28
    vpaddq   zmm17, zmm17, zmm4
    vpaddq   zmm18, zmm18, zmm5
    vpmuludq zmm4,  zmm1, zmm29
    vpbroadcastq zmm29, [rsp + 2392]
    vpmuludq zmm5,  zmm0, zmm29
    vpaddq   zmm18, zmm18, zmm4
    vpaddq   zmm19, zmm19, zmm5
    vpmuludq zmm4,  zmm1, zmm28
    vpbroadcastq zmm28, [rsp + 2400]
    vpmuludq zmm5,  zmm0, zmm28
    vpaddq   zmm19, zmm19, zmm4
    vpaddq   zmm20, zmm20, zmm5
    vpmuludq zmm4,  zmm1, zmm29
    vpmuludq zmm5,  zmm1, zmm28
    vpaddq   zmm20, zmm20, zmm4
    vpaddq   zmm23, zmm23, zmm5
    vpbroadcastq zmm28, [rsp + 2408]
    vpbroadcastq zmm29, [rsp + 2416]
    vpmuludq zmm4,  zmm0, zmm28
    vpmuludq zmm24, zmm0, zmm29         // C6 = v4_0 * P4_6
    vpaddq   zmm23, zmm23, zmm4
    vpmuludq zmm4,  zmm1, zmm28
    vpmuludq zmm2,  zmm1, zmm29         // C7 = v4_1 * P4_6
