    vpsrlq zmm5,  zmm19, 30
    vpandq zmm16, zmm16, zmm30
    vpandq zmm19, zmm19, zmm30
    vpaddq zmm17, zmm17, zmm4
    vpaddq zmm20, zmm20, zmm5
    vpsrlq zmm4,  zmm17, 30
    vpsrlq zmm5,  zmm20, 30
    vpandq zmm17, zmm17, zmm30
    vpandq zmm20, zmm20, zmm30
    vpaddq zmm18, zmm18, zmm4
    vpaddq zmm23, zmm23, zmm5
    vpsrlq zmm4,  zmm18, 30
    vpsrlq zmm5,  zmm23, 30
    vpandq zmm18, zmm18, zmm30
    vpandq zmm23, zmm23, zmm30
    vpaddq zmm19, zmm19, zmm4
    vpaddq zmm24, zmm24, zmm5
    vpsrlq zmm4,  zmm19, 30
    vpsrlq zmm5,  zmm24, 30
    vpandq zmm19, zmm19, zmm30
    vpandq zmm24, zmm24, zmm30
    vpaddq zmm20, zmm20, zmm4
    vpaddq zmm2,  zmm2,  zmm5
