    vporq  zmm0, zmm16, zmm4
    vpsllq zmm5, zmm18, 60
    vporq  zmm0, zmm0,  zmm5            // W0
    vpsrlq zmm1, zmm18, 4
    vpsllq zmm4, zmm19, 26
    vporq  zmm1, zmm1,  zmm4
    vpsllq zmm5, zmm20, 56
    vporq  zmm1, zmm1,  zmm5            // W1
    vpsrlq zmm3, zmm24, 12
    vpsllq zmm4, zmm2,  18
    vporq  zmm3, zmm3,  zmm4            // W3
    vpsrlq zmm2, zmm20, 8
    vpsllq zmm4, zmm23, 22
    vporq  zmm2, zmm2,  zmm4
    vpsllq zmm5, zmm24, 52
    vporq  zmm2, zmm2,  zmm5            // W2
    jmp    .Lcrt32_k4_store_w

.Lcrt32_k4_only_carry:
