    vpsubq       zmm17 {k1}, zmm17, zmm26
    vpsubq       zmm18 {k1}, zmm18, zmm27
    vpsubq       zmm19 {k1}, zmm19, zmm28
    vpsubq       zmm20 {k1}, zmm20, zmm29
    vpbroadcastq zmm28, [rsp + 2408]    // PT4_5
    vpbroadcastq zmm29, [rsp + 2416]    // PT4_6
    vpsubq       zmm23 {k1}, zmm23, zmm28
    vpsubq       zmm24 {k1}, zmm24, zmm29

