    lea  r8,  [rdx + 128]
    cmp  r8,  r11
    ja   .Lcrt32_k4_lane

.p2align 4
.Lcrt32_k4_fast_u:
    mov  r8,  [rsp + 1344 + 8*rdi]
    mov  r9,  [rsp + 1408 + 8*rdi]
    mov  r10, [rsp + 1472 + 8*rdi]
    mov  r11, [rsp + 1536 + 8*rdi]
    add  r8,  r12
    adc  r9,  r13
    adc  r10, r14
    adc  r11, r15

    mov  ecx, 64
    sub  ecx, eax
    shrx r12, r9,  rax
    shlx r13, r10, rcx
    or   r12, r13
    shrx r13, r10, rax
    shlx r14, r11, rcx
    or   r13, r14
    sarx r14, r11, rax
    mov  r15, r11
    sar  r15, 63

    shlx r10, r8, rsi
    or   rbx, r10
    mov  [rdx], rbx
    add  rdx, 8

    mov  ecx, 63
    sub  ecx, esi
    mov  rbx, r8
    shr  rbx, 1
    shrx rbx, rbx, rcx
    bzhi rcx, r9, rax
    shlx r10, rcx, rsi
    or   rbx, r10
    mov  r10d, esi
    add  esi, eax
    cmp  esi, 64
    jb   .Lcrt32_k4_fast_u_next
    mov  [rdx], rbx
    add  rdx, 8
    sub  esi, 64
    mov  r11d, 63
    sub  r11d, r10d
    shr  rcx, 1
    shrx rbx, rcx, r11
.Lcrt32_k4_fast_u_next:
    inc  edi
    cmp  edi, 8
    jb   .Lcrt32_k4_fast_u
    kmovq k3, rdx
    jmp  .Lcrt32_k4_subvec_next

.p2align 4
.Lcrt32_k4_lane:
    mov  r8,  [rsp + 1344 + 8*rdi]
    mov  r9,  [rsp + 1408 + 8*rdi]
    mov  r10, [rsp + 1472 + 8*rdi]
    mov  r11, [rsp + 1536 + 8*rdi]

    cmp  qword ptr [rsp + 1840], 0
