    mov  rcx, [rcx + 8*rdi]             // v_top[lane]
    cmp  rcx, [rsp + 1680]
    jbe  .Lcrt32_k4_add_c
    sub  r8,  [rsp + 1696]
    sbb  r9,  [rsp + 1704]
    sbb  r10, [rsp + 1712]
    sbb  r11, [rsp + 1720]

.Lcrt32_k4_add_c:
    add  r8,  r12
    adc  r9,  r13
    adc  r10, r14
    adc  r11, r15

    mov  ecx, 64
    sub  ecx, eax
    shrx r12, r9,  rax
    shlx r13, r10, rcx
    or   r12, r13
    shrx r13, r10, rax
    shlx r14, r11, rcx
    or   r13, r14
    sarx r14, r11, rax
    mov  r15, r11
    sar  r15, 63

