    mov  [rdx], rbx
    add  rdx, 8
.Lcrt32_k4_skip_lo:
    mov  ecx, 63
    sub  ecx, esi
    mov  rbx, r8
    shr  rbx, 1
    shrx rbx, rbx, rcx
    bzhi rcx, r9, rax
    shlx r10, rcx, rsi
    or   rbx, r10
    mov  r10d, esi
    add  esi, eax
    cmp  esi, 64
    jb   .Lcrt32_k4_next_lane
    cmp  rdx, r11
    jae  .Lcrt32_k4_skip_hi
    mov  [rdx], rbx
    add  rdx, 8
.Lcrt32_k4_skip_hi:
    sub  esi, 64
    mov  r11d, 63
    sub  r11d, r10d
    shr  rcx, 1
    shrx rbx, rcx, r11
.Lcrt32_k4_next_lane:
    inc  edi
    cmp  edi, 8
