.p2align 4
.Lcrt32_k67_fast_gt128:
    mov  r8,  [rsp + 1344 + 8*rdi]
    mov  r9,  [rsp + 1408 + 8*rdi]
    mov  r10, [rsp + 1472 + 8*rdi]
    mov  r11, [rsp + 1536 + 8*rdi]
    mov  rax, [rsp + 3328 + 8*rdi]
    mov  rcx, [rsp + 3392 + 8*rdi]
