.p2align 4
.Lcrt32_k67_lane:
    mov  r8,  [rsp + 1344 + 8*rdi]
    mov  r9,  [rsp + 1408 + 8*rdi]
    mov  r10, [rsp + 1472 + 8*rdi]
    mov  r11, [rsp + 1536 + 8*rdi]
    mov  rax, [rsp + 3328 + 8*rdi]
    mov  rdx, [rsp + 3392 + 8*rdi]

    kmovq rcx, k5
    add  r8,  r12
    adc  r9,  r13
    adc  r10, r14
    adc  r11, r15
    adc  rax, rcx
    kmovq rcx, k6
    adc  rdx, rcx

    mov  ecx, dword ptr [rsp + 1824]    // b in 1..160
    cmp  ecx, 128
    ja   .Lcrt32_k67_gt128
    je   .Lcrt32_k67_eq128
    cmp  ecx, 64
    ja   .Lcrt32_k67_65_127
    je   .Lcrt32_k67_eq64

    // 1 <= b <= 63:
    sarx r12, rdx, rcx                  // new_c5 = S5 >>_arith b
    kmovq k6, r12
    shrx r12, rax, rcx                  // S4 >> b
    neg  ecx
    add  ecx, 64                        // 64 - b
    shlx rdx, rdx, rcx                  // S5 << (64 - b)
    or   r12, rdx                       // new_c4
    kmovq k5, r12
    mov  edx, dword ptr [rsp + 1824]    // b
    shrx r12, r8,  rdx
    shrx r13, r9,  rdx
    shrx r14, r10, rdx
    shrx r15, r11, rdx
    shlx r9,  r9,  rcx
    or   r12, r9
    shlx r10, r10, rcx
    or   r13, r10
    shlx r11, r11, rcx
    or   r14, r11
    shlx rax, rax, rcx
    or   r15, rax
    bzhi rcx, r8,  rdx
    mov  eax, edx
    jmp  .Lcrt32_k67_le64_pack

.Lcrt32_k67_eq64:
    mov  r12, r9
    mov  r13, r10
    mov  r14, r11
    mov  r15, rax
    kmovq k5, rdx
    sar  rdx, 63
    kmovq k6, rdx
    mov  rcx, r8
    mov  eax, 64
.Lcrt32_k67_le64_pack:
    shlx r10, rcx, rsi
    or   rbx, r10
    mov  r10d, esi
    add  esi, eax
    cmp  esi, 64
    jb   .Lcrt32_k67_lane_next
    kmovq rdx, k3
    kmovq r11, k4
    cmp  rdx, r11
    jae  .Lcrt32_k67_le64_sk
    mov  [rdx], rbx
    add  rdx, 8
    kmovq k3, rdx
.Lcrt32_k67_le64_sk:
    sub  esi, 64
    mov  r11d, 63
    sub  r11d, r10d
    shr  rcx, 1
    shrx rbx, rcx, r11
    jmp  .Lcrt32_k67_lane_next

.Lcrt32_k67_eq128:
    mov  r12, r10
    mov  r13, r11
    mov  r14, rax
    mov  r15, rdx
    sar  rdx, 63
    kmovq k5, rdx
    kmovq k6, rdx
    kmovq rdx, k3
    kmovq r11, k4
    test esi, esi
    jnz  .Lcrt32_k67_b_pack_gen
    lea  rax, [rdx + 16]
    cmp  rax, r11
    ja   .Lcrt32_k67_b_pack_gen
    mov  [rdx],     r8
    mov  [rdx + 8], r9
    mov  rdx, rax
    kmovq k3, rdx
    jmp  .Lcrt32_k67_lane_next

.Lcrt32_k67_65_127:
    sub  ecx, 64                        // s = b - 64 in 1..63
    sarx r12, rdx, rcx                  // new_c4 = S5 >>_arith s
    kmovq k5, r12
    shrx r12, r9,  rcx                  // S1 >> s
    shrx r13, r10, rcx                  // S2 >> s
    shrx r14, r11, rcx                  // S3 >> s
    shrx r15, rax, rcx                  // S4 >> s
    neg  ecx
    add  ecx, 64                        // 64 - s in 1..63
    shlx r10, r10, rcx
    or   r12, r10                       // new_c0
    shlx r11, r11, rcx
    or   r13, r11                       // new_c1
    shlx rax, rax, rcx
    or   r14, rax                       // new_c2
    shlx rcx, rdx, rcx
    or   r15, rcx                       // new_c3
    sar  rdx, 63
    kmovq k6, rdx
    kmovq rdx, k3
    kmovq r11, k4

.Lcrt32_k67_b_pack_gen:
    shlx rax, r8, rsi
    or   rbx, rax
    cmp  rdx, r11
    jae  .Lcrt32_k67_b_sk0
    mov  [rdx], rbx
    add  rdx, 8
.Lcrt32_k67_b_sk0:
    mov  ecx, 63
    sub  ecx, esi
    shr  r8,  1
    shrx rbx, r8, rcx
    mov  eax, dword ptr [rsp + 1824]
    sub  eax, 64                        // s = b - 64 in 1..64
    mov  rcx, r9
    cmp  eax, 64
    je   .Lcrt32_k67_b_nobzhi
    bzhi rcx, rcx, rax
.Lcrt32_k67_b_nobzhi:
    shlx r8,  rcx, rsi
    or   rbx, r8
    mov  r8d, esi
    add  esi, eax
    cmp  esi, 64
    jb   .Lcrt32_k67_b_done
    cmp  rdx, r11
    jae  .Lcrt32_k67_b_sk1
    mov  [rdx], rbx
    add  rdx, 8
.Lcrt32_k67_b_sk1:
    sub  esi, 64
    mov  r9d, 63
    sub  r9d, r8d
    shr  rcx, 1
    shrx rbx, rcx, r9
.Lcrt32_k67_b_done:
    kmovq k3, rdx
    jmp  .Lcrt32_k67_lane_next

.Lcrt32_k67_gt128:
    sub  ecx, 128                       // s = b - 128 in 1..32
    shrx r12, r10, rcx
    shrx r13, r11, rcx
    shrx r14, rax, rcx
    sarx r15, rdx, rcx                  // new_c3
    neg  ecx
    add  ecx, 64                        // 64 - s in 32..63
    shlx r11, r11, rcx
    or   r12, r11                       // new_c0
    shlx rax, rax, rcx
    or   r13, rax                       // new_c1
    shlx rcx, rdx, rcx
    or   r14, rcx                       // new_c2
    sar  rdx, 63
    kmovq k5, rdx
    kmovq k6, rdx

    kmovq rdx, k3
    kmovq r11, k4
    shlx rax, r8, rsi
    or   rbx, rax
    cmp  rdx, r11
    jae  .Lcrt32_k67_c_sk0
    mov  [rdx], rbx
    add  rdx, 8
.Lcrt32_k67_c_sk0:
    mov  ecx, 63
    sub  ecx, esi
    shr  r8,  1
    shrx rbx, r8, rcx
    shlx rax, r9, rsi
    or   rbx, rax
    cmp  rdx, r11
    jae  .Lcrt32_k67_c_sk1
    mov  [rdx], rbx
    add  rdx, 8
.Lcrt32_k67_c_sk1:
    shr  r9,  1
    shrx rbx, r9, rcx
    mov  eax, dword ptr [rsp + 1824]
    sub  eax, 128                       // s in 1..32
    bzhi rcx, r10, rax
    shlx r8,  rcx, rsi
    or   rbx, r8
    mov  r8d, esi
    add  esi, eax
    cmp  esi, 64
    jb   .Lcrt32_k67_c_done
    cmp  rdx, r11
    jae  .Lcrt32_k67_c_sk2
    mov  [rdx], rbx
    add  rdx, 8
.Lcrt32_k67_c_sk2:
    sub  esi, 64
    mov  r9d, 63
    sub  r9d, r8d
    shr  rcx, 1
    shrx rbx, rcx, r9
.Lcrt32_k67_c_done:
    kmovq k3, rdx

.Lcrt32_k67_lane_next:
    inc  rdi
    cmp  rdi, [rsp + 2512]
    jb   .Lcrt32_k67_lane

.Lcrt32_k67_subvec_done:
