    kmovq rdx, k3
    mov  [rsp + 1896], rdx
    mov  [rsp + 1904], rbx
    mov  [rsp + 1912], rsi
    mov  [rsp + 1152 + 0],  r12
    mov  [rsp + 1152 + 8],  r13
    mov  [rsp + 1152 + 16], r14
    mov  [rsp + 1152 + 24], r15
    kmovq rax, k5
    mov  [rsp + 1152 + 32], rax
    cmp  qword ptr [rsp + 1848], 6
    jb   .Lcrt_next_batch
    kmovq rax, k6
    mov  [rsp + 1152 + 40], rax
    jmp  .Lcrt_next_batch

    // k_primes == 8 or 9 radix-2^30 accumulation (C0..C14 -> W0..W7) + 8-word bit-packer
