    vpandq zmm24, zmm24, zmm30
    vpandq zmm3,  zmm3,  zmm30
    vpaddq zmm19, zmm19, zmm5
    vpaddq zmm25, zmm25, zmm28
    vpaddq zmm0,  zmm0,  zmm29
