    vporq  zmm16, zmm16, zmm28
    vpsllq zmm29, zmm18, 60
    vporq  zmm16, zmm16, zmm29          // W0

    vpsrlq zmm17, zmm18, 4
    vpsllq zmm28, zmm19, 26
    vporq  zmm17, zmm17, zmm28
    vpsllq zmm29, zmm20, 56
    vporq  zmm17, zmm17, zmm29          // W1

    vpsrlq zmm18, zmm20, 8
    vpsllq zmm28, zmm23, 22
    vporq  zmm18, zmm18, zmm28
    vpsllq zmm29, zmm24, 52
    vporq  zmm18, zmm18, zmm29          // W2

    vpsrlq zmm19, zmm24, 12
    vpsllq zmm28, zmm25, 18
    vporq  zmm19, zmm19, zmm28
    vpsllq zmm29, zmm26, 48
