    vporq  zmm20, zmm20, zmm28
    vpsllq zmm29, zmm2,  44
    vporq  zmm20, zmm20, zmm29          // W4

    vpsrlq zmm23, zmm2,  20
    vpsllq zmm28, zmm3,  10
    vporq  zmm23, zmm23, zmm28
    vpsllq zmm29, zmm0,  40
    vporq  zmm23, zmm23, zmm29          // W5

