    vmovdqa64 [rsp + 1408], zmm17
    vmovdqa64 [rsp + 1472], zmm18
    vmovdqa64 [rsp + 1536], zmm19
    vmovdqa64 [rsp + 3328], zmm20
    vmovdqa64 [rsp + 3392], zmm23
    vmovdqa64 [rsp + 4032], zmm24
    vmovdqa64 [rsp + 4096], zmm25

.Lcrt32_k89_lanes:
