    mov   eax, dword ptr [rsp + 1824]
    sub   eax, 129
    cmp   eax, 63
    jb    .Lcrt32_k89_fast_ws2
    mov   eax, dword ptr [rsp + 1824]
    sub   eax, 193
    cmp   eax, 63
    jae   .Lcrt32_k89_gen_init

