    // ========================================================================
    // Block path. The paths above leave the words of up to 64 coefficients in the block area;
    // their digits are then placed with no carry that runs from one coefficient to the next.
    // A value x splits at b bits into A + B*2^b + C*2^(2b). Output digit m is
    // S = A_m + B_(m-1) + C_(m-2), below 3*2^b, which splits again into D + E*2^b with E <= 2,
    // and D_m + E_(m-1) is the digit unless it reaches 2^b, which a scalar pass resolves (rare).
    // The digits are then transposed, so that a lane holds eight coefficients in a row, merged
    // with shifts that are the same in every lane, and stored as b bytes per lane.
    // The emit uses zmm0-5, zmm16-20, zmm23-30: zmm6-15, zmm21, zmm22, zmm31 hold the constants of
    // the paths' own Garner. The driver (.Lcrtd_enter) replaces that Garner and uses all but zmm31.
    // ========================================================================
.p2align 4
.Lcrtv_take3:
    mov  rax, [rsp + 1936]
    mov  rcx, [rax + 16296]
    lea  rdx, [rcx + 1]
    mov  [rax + 16296], rdx
    shl  rcx, 10
    vmovdqa64 [rax + rcx + 0],   zmm0
    vmovdqa64 [rax + rcx + 64],  zmm1
    vmovdqa64 [rax + rcx + 128], zmm2
    jmp  .Lcrt32_k3_subvec_next

.p2align 4
.Lcrtv_take4:
    mov  rax, [rsp + 1936]
    mov  rcx, [rax + 16296]
    lea  rdx, [rcx + 1]
    mov  [rax + 16296], rdx
    shl  rcx, 10
    vmovdqa64 [rax + rcx + 0],   zmm0
    vmovdqa64 [rax + rcx + 64],  zmm1
    vmovdqa64 [rax + rcx + 128], zmm2
    vmovdqa64 [rax + rcx + 192], zmm3
    jmp  .Lcrt32_k4_subvec_next

.p2align 4
.Lcrtv_take6:
    mov  rax, [rsp + 1936]
    mov  rcx, [rax + 16296]
    lea  rdx, [rcx + 1]
    mov  [rax + 16296], rdx
    shl  rcx, 10
    vmovdqa64 [rax + rcx + 0],   zmm0
    vmovdqa64 [rax + rcx + 64],  zmm1
    vmovdqa64 [rax + rcx + 128], zmm3
    vmovdqa64 [rax + rcx + 192], zmm16
    vmovdqa64 [rax + rcx + 256], zmm17
    vmovdqa64 [rax + rcx + 320], zmm18
    jmp  .Lcrt32_k67_subvec_done

.p2align 4
.Lcrtv_take8:
    mov  rax, [rsp + 1936]
    mov  rcx, [rax + 16296]
    lea  rdx, [rcx + 1]
    mov  [rax + 16296], rdx
    shl  rcx, 10
    vmovdqa64 [rax + rcx + 0],   zmm16
    vmovdqa64 [rax + rcx + 64],  zmm17
    vmovdqa64 [rax + rcx + 128], zmm18
    vmovdqa64 [rax + rcx + 192], zmm19
    vmovdqa64 [rax + rcx + 256], zmm20
    vmovdqa64 [rax + rcx + 320], zmm23
    vmovdqa64 [rax + rcx + 384], zmm24
    vmovdqa64 [rax + rcx + 448], zmm25
