    vpsrlq zmm4,  zmm23, 30
    vpandq zmm23, zmm23, zmm30
    vpaddq zmm24, zmm24, zmm4
    vpsrlq zmm4,  zmm24, 30
    vpandq zmm24, zmm24, zmm30
