    mov  rbx, [rdx + 112]               // seg_out_stride
    imul rbx, r8
.Lcrtd_one_stream:
    add  rax, r9
    shl  rax, 3                         // byte offset of the block in every residue array
    mov  rdi, [r15 + 16504]
    lea  rdi, [rdi + 8*rbx]
    mov  r11, [r15 + 16392]              // bytes of output per lane
    mov  rbx, r9
    imul rbx, r11
    shr  rbx, 3
    add  rdi, rbx                       // first output byte of the block
    xor  ecx, ecx
    mov  qword ptr [r15 + 16528], 0
    cmp  qword ptr [rsp + 1944], 2
    jne  .Lcrtd_tab4
    cmp  qword ptr [rsp + 1816], 64
    ja   .Lcrtd_tab4
    mov  qword ptr [r15 + 16528], 1
    mov  [r15 + 16536], rdi
    mov  [r15 + 16544], rdi
    lea  rdi, [r15 + 11200]
.Lcrtd_tab4:
