    add  rdi, r11
    inc  ecx
    cmp  ecx, 8
    jb   .Lcrtd_tab8
    mov  qword ptr [r15 + 16456], 8
    mov  qword ptr [r15 + 16464], 8
    mov  qword ptr [r15 + 16472], 3
