    mov  rax, [rdx + 104]
    shl  rax, 3
    add  rax, [r15 + 15808]                 // the next segment's residues
    mov  rdi, [rdx + 112]
    shl  rdi, 3
    cmp  qword ptr [r15 + 16528], 0
