    add  rdi, [r15 + 15872]                 // and its output
    jmp  .Lcrtd_tabp
.Lcrtd_pair_l1:
    add  rdi, [r15 + 16536]
    mov  [r15 + 16544], rdi
    lea  rdi, [r15 + 12224]
.Lcrtd_tabp:
    mov  [r15 + 15808 + 8*rcx], rax
    mov  [r15 + 15872 + 8*rcx], rdi
