.Lcrtd_pf_l:
    prefetcht0 [rdi]
    add  rdi, 64
    cmp  rdi, rax
    jb   .Lcrtd_pf_l
    prefetcht0 [rax]
    add  rdx, rcx
    cmp  rdx, [r15 + 16456]
