    // Write out carry[0 .. k_words] to carry_limbs
    xor  ecx, ecx
.Lcrt_out_carry:
    mov  rbx, [rsp + 1152 + 8*rcx]
    mov  [rax + 8*rcx], rbx
    inc  rcx
    cmp  rcx, r13
    jb   .Lcrt_out_carry
    jmp  .Lcrt_compute_w0

.Lcrt_check_wrap:
    mov  rax, [rdx + 40]                // wrap_cyclic
    test rax, rax
    jz   .Lcrt_flush_pos_carry

    // fold_cyclic_carry(out_limbs, out_len, total_bits = bit_pos, carry)
    test r12, r12
    jz   .Lcrt_compute_w0
    mov  r10, [rsp + 1672]              // total_bits = bit_pos
    test r10, r10
    jz   .Lcrt_compute_w0

    mov  rax, [rsp + 1152 + 8*r13 - 8]
    test rax, rax
    sets r15b                           // r15b = 1 if neg else 0
    movzx r15d, r15b

    // Copy carry -> mag (and negate if neg), checking if all zero
    xor  ecx, ecx
    xor  eax, eax                       // borrow = 0
    xor  r8d, r8d                       // nonzero_or = 0
.Lcrt_mag_loop:
    mov  rbx, [rsp + 1152 + 8*rcx]
    test r15d, r15d
    jz   .Lcrt_mag_store
    bt   eax, 0
    mov  r9,  0
    sbb  r9,  rbx
    setc al
    mov  rbx, r9
.Lcrt_mag_store:
    mov  [rsp + 1472 + 8*rcx], rbx
    or   r8,  rbx
    inc  rcx
    cmp  rcx, r13
    jb   .Lcrt_mag_loop

    test r8,  r8
    jz   .Lcrt_compute_w0

    // top_limb = (total_bits - 1) >> 6; top_bits = total_bits - top_limb * 64
    lea  r14, [r10 - 1]
    shr  r14, 6                         // top_limb
    mov  rax, r14
    shl  rax, 6
    mov  r11, r10
    sub  r11, rax                       // top_bits (1..64)
    mov  rbx, -1
    cmp  r11, 64
    je   .Lcrt_got_topmask
    bzhi rbx, rbx, r11
.Lcrt_got_topmask:
    // rbx = top_mask; r9 = limit_limb = min(top_limb, out_len - 1)
    lea  r9,  [r12 - 1]
    cmp  r14, r9
    cmovb r9, r14
    mov  rdi, [rsp + 1632]              // out_limbs

    test r15d, r15d
    jnz  .Lcrt_fold_neg

    // Positive cyclic fold
    xor  eax, eax                       // c = 0
    xor  ecx, ecx                       // i = 0
.Lcrt_fold_pos_loop:
    xor  edx, edx
    cmp  rcx, r13
    jae  .Lcrt_fp_got_add
    mov  rdx, [rsp + 1472 + 8*rcx]
.Lcrt_fp_got_add:
    mov  rsi, [rdi + 8*rcx]
    xor  r8d, r8d
    add  rsi, rdx
    adc  r8,  0
    add  rsi, rax
    adc  r8,  0                         // r8 = c1 + c2
    cmp  rcx, r14                       // i == top_limb ?
    jne  .Lcrt_fp_not_top
    mov  rdx, rsi
    and  rdx, rbx
    mov  [rdi + 8*rcx], rdx
    mov  rax, r8
    cmp  r11, 64
    je   .Lcrt_fp_next
    shrx rsi, rsi, r11
    mov  edx, 64
    sub  edx, r11d
    shlx rax, r8, rdx
    add  rax, rsi
    jmp  .Lcrt_fp_next
.Lcrt_fp_not_top:
    mov  [rdi + 8*rcx], rsi
    mov  rax, r8
.Lcrt_fp_next:
    inc  rcx
    cmp  rcx, r9
    jbe  .Lcrt_fold_pos_loop

.Lcrt_fp_while_c:
    test rax, rax
    jz   .Lcrt_canonicalize
    mov  rdx, rax                       // cc = c
    xor  eax, eax                       // c = 0
    xor  ecx, ecx                       // i = 0
.Lcrt_fp_prop:
    mov  rsi, [rdi + 8*rcx]
    xor  r8d, r8d
    add  rsi, rdx
    adc  r8,  0                         // ov
    cmp  rcx, r14
    jne  .Lcrt_fp_prop_nottop
    mov  rax, r8
    cmp  r11, 64
    je   .Lcrt_fp_prop_mask
    shrx rax, rsi, r11
.Lcrt_fp_prop_mask:
    and  rsi, rbx
    mov  [rdi + 8*rcx], rsi
    jmp  .Lcrt_fp_prop_next
.Lcrt_fp_prop_nottop:
    mov  [rdi + 8*rcx], rsi
    mov  rdx, r8
    test rdx, rdx
    jz   .Lcrt_fp_while_c
.Lcrt_fp_prop_next:
    inc  rcx
    cmp  rcx, r9
    jbe  .Lcrt_fp_prop
    jmp  .Lcrt_fp_while_c

    // Negative cyclic fold
.Lcrt_fold_neg:
    xor  eax, eax                       // b = 0
    xor  ecx, ecx                       // i = 0
.Lcrt_fold_neg_loop:
    xor  edx, edx
    cmp  rcx, r13
    jae  .Lcrt_fn_got_sub
    mov  rdx, [rsp + 1472 + 8*rcx]
.Lcrt_fn_got_sub:
    mov  rsi, [rdi + 8*rcx]
    xor  r8d, r8d
    sub  rsi, rdx
    adc  r8,  0
    sub  rsi, rax
    adc  r8,  0                         // r8 = b1 + b2
    cmp  rcx, r14
    jne  .Lcrt_fn_not_top
    mov  rdx, rsi
    and  rdx, rbx
    mov  [rdi + 8*rcx], rdx
    xor  eax, eax
    test r8,  r8
    jnz  .Lcrt_fn_set_b1
    cmp  r11, 64
    je   .Lcrt_fn_next
    shrx rsi, rsi, r11
    test rsi, rsi
    jz   .Lcrt_fn_next
.Lcrt_fn_set_b1:
    mov  eax, 1
    jmp  .Lcrt_fn_next
.Lcrt_fn_not_top:
    mov  [rdi + 8*rcx], rsi
    mov  rax, r8
.Lcrt_fn_next:
    inc  rcx
    cmp  rcx, r9
    jbe  .Lcrt_fold_neg_loop

    test rax, rax
    jz   .Lcrt_canonicalize
    mov  edx, 1                         // bb = 1
    xor  ecx, ecx
.Lcrt_fn_sub1:
    mov  rsi, [rdi + 8*rcx]
    xor  r8d, r8d
    sub  rsi, rdx
    adc  r8,  0
    cmp  rcx, r14
    jne  .Lcrt_fn_sub1_store
    and  rsi, rbx
.Lcrt_fn_sub1_store:
    mov  [rdi + 8*rcx], rsi
    mov  rdx, r8
    test rdx, rdx
    jz   .Lcrt_canonicalize
    inc  rcx
    cmp  rcx, r9
    jbe  .Lcrt_fn_sub1

.Lcrt_canonicalize:
    cmp  r14, r12
    jae  .Lcrt_compute_w0
    xor  ecx, ecx
.Lcrt_canon_check:
    mov  rax, -1
    cmp  rcx, r14
    cmove rax, rbx                      // top_mask on top_limb else u64::MAX
    cmp  [rdi + 8*rcx], rax
    jne  .Lcrt_compute_w0
    inc  rcx
    cmp  rcx, r14
    jbe  .Lcrt_canon_check
    xor  ecx, ecx
    xor  eax, eax
.Lcrt_canon_zero:
    mov  [rdi + 8*rcx], rax
    inc  rcx
    cmp  rcx, r14
    jbe  .Lcrt_canon_zero
    jmp  .Lcrt_compute_w0

.Lcrt_flush_pos_carry:
    // Flush positive carry into remaining bits of out_limbs above bit_pos
    mov  r10, [rsp + 1672]              // bit_pos
    mov  rax, r12
    shl  rax, 6                         // out_len * 64
    cmp  r10, rax
    jae  .Lcrt_compute_w0
    sub  rax, r10                       // out_len * 64 - bit_pos
    mov  rcx, r13
    shl  rcx, 6                         // k_words * 64
    cmp  rax, rcx
    cmova rax, rcx                      // width = min(out_len*64 - bit_pos, k_words*64)
    mov  r15, rax                       // width
    mov  r9,  [rsp + 1632]              // out_limbs
    xor  edi, edi                       // written = 0
.Lcrt_flush_wb:
    cmp  rdi, r15
    jae  .Lcrt_compute_w0
    lea  rax, [r10 + rdi]
    mov  rbx, rax
    shr  rbx, 6
    cmp  rbx, r12
    jae  .Lcrt_compute_w0
    and  eax, 63
    mov  ecx, 64
    sub  ecx, eax
    mov  r11, r15
    sub  r11, rdi
    cmp  r11, rcx
    cmova r11, rcx

    mov  rcx, rdi
    shr  rcx, 6
    mov  edx, edi
    and  edx, 63
    shrx rsi, [rsp + 1152 + 8*rcx], rdx
    lea  r8,  [rdx + r11]
    cmp  r8,  64
    jbe  .Lcrt_fwb_mask
    lea  r8,  [rcx + 1]
    cmp  r8,  r13
    jae  .Lcrt_fwb_mask
    neg  edx
    add  edx, 64
    shlx r8,  [rsp + 1152 + 8*rcx + 8], rdx
    or   rsi, r8
.Lcrt_fwb_mask:
    cmp  r11, 64
    jae  .Lcrt_fwb_or
    bzhi rsi, rsi, r11
.Lcrt_fwb_or:
    shlx rsi, rsi, rax
    or   [r9 + 8*rbx], rsi
    add  rdi, r11
    jmp  .Lcrt_flush_wb

.Lcrt_compute_w0:
    mov  r12, [rsp + 1632]              // limbs = out_limbs
    mov  r13, [rsp + 1832]              // n = out_len
    mov  r9,  0x1FFFFFFFFFFFFFFF        // MOD_W0 = 2^61 - 1
    mov  r10, 0x03FFFFFFFFFFFFFF        // (1 << 58) - 1
    xor  eax, eax                       // w0 = 0
    test r13, r13
    jz   .Lcrt_w0_done

    mov  rcx, r13
    and  rcx, 7
    mov  rbx, r13
    and  rbx, -8                        // vec_n = n & !7
    jz   .Lcrt_w0_peel_only
    test rcx, rcx
    jz   .Lcrt_w0_vec_init

.Lcrt_w0_peel_only:
    mov  r8,  r13
.Lcrt_w0_peel_loop:
    cmp  r8,  rbx
    jbe  .Lcrt_w0_vec_check
    dec  r8
    mov  rdx, [r12 + 8*r8]
    mov  rsi, rdx
    and  rsi, r9
    shr  rdx, 61
    add  rsi, rdx
    mov  rdx, rsi
    sub  rdx, r9
    cmovae rsi, rdx

    mov  rdx, rax
    and  rdx, r10
    shl  rdx, 3
    shr  rax, 58
    add  rax, rdx
    mov  rdx, rax
    sub  rdx, r9
    cmovae rax, rdx
    add  rax, rsi
    mov  rdx, rax
    sub  rdx, r9
    cmovae rax, rdx
    jmp  .Lcrt_w0_peel_loop

.Lcrt_w0_vec_check:
    test rbx, rbx
    jz   .Lcrt_w0_done

.Lcrt_w0_vec_init:
    vmovq        xmm0, rax
    vpbroadcastq zmm16, r9
    mov  rdx, 0x0000001FFFFFFFFF
    vpbroadcastq zmm17, rdx

    lea  rsi, [r12 + 8*rbx - 64]
    mov  rcx, rbx
    shr  rcx, 3
    test cl,  1
    jz   .Lcrt_w0_vec_pairs
    vmovdqu64 zmm1, [rsi]
    vpandq    zmm2, zmm0, zmm17
    vpsllq    zmm2, zmm2, 24
    vpsrlq    zmm0, zmm0, 37
    vpaddq    zmm0, zmm0, zmm2
    vpandq    zmm3, zmm1, zmm16
    vpsrlq    zmm1, zmm1, 61
    vpaddq    zmm3, zmm3, zmm1
    vpaddq    zmm0, zmm0, zmm3
    sub  rsi, 64
    dec  rcx
    jz   .Lcrt_w0_vec_done
.Lcrt_w0_vec_pairs:
    vpxorq    zmm18, zmm18, zmm18
    mov  edx, 0x1FFF
    vpbroadcastq zmm19, rdx
.p2align 4
.Lcrt_w0_vec_loop:
    vmovdqu64 zmm4, [rsi]
    vmovdqu64 zmm1, [rsi - 64]
    vpandq    zmm2, zmm0,  zmm19
    vpandq    zmm5, zmm18, zmm19
    vpsllq    zmm2, zmm2,  48
    vpsllq    zmm5, zmm5,  48
    vpsrlq    zmm0,  zmm0,  13
    vpsrlq    zmm18, zmm18, 13
    vpaddq    zmm0,  zmm0,  zmm2
    vpaddq    zmm18, zmm18, zmm5

    vpandq    zmm3,  zmm1, zmm16
    vpandq    zmm20, zmm4, zmm16
    vpsrlq    zmm1,  zmm1, 61
    vpsrlq    zmm4,  zmm4, 61
    vpaddq    zmm3,  zmm3,  zmm1
    vpaddq    zmm20, zmm20, zmm4
    vpaddq    zmm0,  zmm0,  zmm3
    vpaddq    zmm18, zmm18, zmm20

    sub  rsi, 128
    sub  rcx, 2
    jnz  .Lcrt_w0_vec_loop

    vpandq    zmm2,  zmm18, zmm17
    vpsllq    zmm2,  zmm2,  24
    vpsrlq    zmm18, zmm18, 37
    vpaddq    zmm18, zmm18, zmm2
    vpaddq    zmm0,  zmm0,  zmm18
.Lcrt_w0_vec_done:

    vmovdqa64 [rsp + 0], zmm0
    xor  eax, eax
    mov  ecx, 7
.Lcrt_w0_hfold:
    mov  rsi, [rsp + 8*rcx]
    mov  rdx, rsi
    and  rsi, r9
    shr  rdx, 61
    add  rsi, rdx
    mov  rdx, rsi
    sub  rdx, r9
    cmovae rsi, rdx

    mov  rdx, rax
    and  rdx, r10
    shl  rdx, 3
    shr  rax, 58
    add  rax, rdx
    mov  rdx, rax
    sub  rdx, r9
    cmovae rax, rdx
    add  rax, rsi
    mov  rdx, rax
    sub  rdx, r9
    cmovae rax, rdx
    sub  ecx, 1
    jnc  .Lcrt_w0_hfold

.Lcrt_w0_done:
    cmp  qword ptr [rsp + 1944], 2
    je   .Lcrtd_after_w0                // the check word of one segment of many
    VEC_LEAVE

// ============================================================================
// 6. Family 4 — Movement Kernels (2): Strided & 50-bit Packed Gather/Scatter
// ============================================================================

// [20] gather(tile_dst: rdi, outer_src: rsi, cfg: rdx)
// MoveCfg: rows@0, cols@8, outer_stride_bytes@16, packed@24, use_nt@32
LOCAL_FN supi_k_gather
    VEC_ENTER_FAST
    mov  r8,  [rdx + 0]                 // rows
    mov  r9,  [rdx + 8]                 // cols
    mov  r10, [rdx + 16]                // stride_bytes
    mov  r11, [rdx + 24]                // packed
    mov  r12, [rdx + 32]                // use_nt

    test r8,  r8
    jz   .Lgather_done
    test r9,  r9
    jz   .Lgather_done

    test r11, r11
    jnz  .Lgather_packed

    // Unpacked strided gather (only zmm0..zmm3)
    xor  r13d, r13d                     // r = 0
.Lgather_unp_row:
    mov  rcx, r9                        // cols_rem = cols
    mov  rax, rsi                       // src_row
    test r12, r12
    jz   .Lgather_unp_no_nt_row
    cmp  r9,  64
    ja   .Lgather_unp_nt4_chk
    lea  r11, [r13 + 8]
    cmp  r11, r8
    jae  .Lgather_unp_nt4_chk
    lea  rbx, [rsi + 8*r10]             // 8 rows ahead for narrow strided DRAM/dTLB hiding
    jmp  .Lgather_unp_nt_go
.Lgather_unp_nt4_chk:
    lea  r11, [r13 + 4]
    cmp  r11, r8
    jae  .Lgather_unp_nt1_chk
    lea  rbx, [rsi + 4*r10]             // 4 rows ahead for DRAM/dTLB latency hiding
    jmp  .Lgather_unp_nt_go
.Lgather_unp_nt1_chk:
    lea  r11, [r13 + 1]
    cmp  r11, r8
    jae  .Lgather_unp_no_nt_row
    lea  rbx, [rsi + r10]               // next_row for prefetchnta
.Lgather_unp_nt_go:
    cmp  rcx, 32
    jb   .Lgather_unp_nt_rem8
.p2align 4
.Lgather_unp_nt_vec32:
    prefetchnta [rbx]
    prefetchnta [rbx + 64]
    prefetchnta [rbx + 128]
    prefetchnta [rbx + 192]
    prefetchnta [rbx + 255]
    lea  rbx, [rbx + 256]
    vmovupd zmm0, [rax]
    vmovupd zmm1, [rax + 64]
    vmovupd zmm2, [rax + 128]
    vmovupd zmm3, [rax + 192]
    vmovupd [rdi],       zmm0
    vmovupd [rdi + 64],  zmm1
    vmovupd [rdi + 128], zmm2
    vmovupd [rdi + 192], zmm3
    add  rax, 256
    add  rdi, 256
    sub  rcx, 32
    cmp  rcx, 32
    jae  .Lgather_unp_nt_vec32

.Lgather_unp_nt_rem8:
    cmp  rcx, 8
    jb   .Lgather_unp_tail
.Lgather_unp_nt_vec8:
    prefetchnta [rbx]
    lea  rbx, [rbx + 64]
    vmovupd zmm0, [rax]
    vmovupd [rdi], zmm0
    lea  rax, [rax + 64]
    lea  rdi, [rdi + 64]
    sub  rcx, 8
    cmp  rcx, 8
    jae  .Lgather_unp_nt_vec8
    jmp  .Lgather_unp_tail

.Lgather_unp_no_nt_row:
    cmp  rcx, 32
    jb   .Lgather_unp_rem8
.p2align 4
.Lgather_unp_vec32:
    vmovupd zmm0, [rax]
    vmovupd zmm1, [rax + 64]
    vmovupd zmm2, [rax + 128]
    vmovupd zmm3, [rax + 192]
    vmovupd [rdi],       zmm0
    vmovupd [rdi + 64],  zmm1
    vmovupd [rdi + 128], zmm2
    vmovupd [rdi + 192], zmm3
    add  rax, 256
    add  rdi, 256
    sub  rcx, 32
    cmp  rcx, 32
    jae  .Lgather_unp_vec32

.Lgather_unp_rem8:
    cmp  rcx, 8
    jb   .Lgather_unp_tail
.Lgather_unp_vec8:
    vmovupd zmm0, [rax]
    vmovupd [rdi], zmm0
    lea  rax, [rax + 64]
    lea  rdi, [rdi + 64]
    sub  rcx, 8
    cmp  rcx, 8
    jae  .Lgather_unp_vec8

.Lgather_unp_tail:
    test rcx, rcx
    jz   .Lgather_unp_next_row
    mov  edx, 0xFF
    bzhi edx, edx, ecx
    kmovw k1, edx
    vmovupd zmm0 {k1}{z}, [rax]
    vmovupd [rdi] {k1}, zmm0
    lea  rdi, [rdi + 8*rcx]

.Lgather_unp_next_row:
    add  rsi, r10
    inc  r13
    cmp  r13, r8
    jb   .Lgather_unp_row
    jmp  .Lgather_done

    // Packed 50-bit gather (50 bytes -> 8 f64s via vpermw + vpsrlvq + vcvtuqq2pd)
.macro UNPACK4_DIRECT_STEP g, nt
.if \g == 0
.if \nt != 0
    prefetchnta [rbx + 0]
    prefetchnta [rbx + 64]
    prefetchnta [rbx + 128]
    prefetchnta [rbx + 192]
.endif
    vmovdqa64  zmm29, [rax + 0]
    vmovdqa64  zmm30, [rax + 64]
    vmovdqa64  zmm31, [rax + 128]
    vmovdqa64  zmm21, [rax + 192]
    vmovdqa64  zmm0,  zmm29
    valignq    zmm1,  zmm30, zmm29, 6
    valignq    zmm2,  zmm31, zmm30, 4
    valignq    zmm3,  zmm21, zmm31, 2
    vmovdqa64  zmm29, zmm21
.elseif \g == 1
.if \nt != 0
    prefetchnta [rbx + 256]
    prefetchnta [rbx + 320]
    prefetchnta [rbx + 384]
.endif
    vmovdqa64  zmm30, [rax + 256]
    vmovdqa64  zmm31, [rax + 320]
    vmovdqa64  zmm21, [rax + 384]
    valignq    zmm0,  zmm30, zmm29, 1
    valignq    zmm1,  zmm30, zmm29, 7
    valignq    zmm2,  zmm31, zmm30, 5
    valignq    zmm3,  zmm21, zmm31, 3
    vmovdqa64  zmm29, zmm21
.elseif \g == 2
.if \nt != 0
    prefetchnta [rbx + 448]
    prefetchnta [rbx + 512]
    prefetchnta [rbx + 576]
.endif
    vmovdqa64  zmm30, [rax + 448]
    vmovdqa64  zmm31, [rax + 512]
    vmovdqa64  zmm21, [rax + 576]
    valignq    zmm0,  zmm30, zmm29, 2
    vmovdqa64  zmm1,  zmm30
    valignq    zmm2,  zmm31, zmm30, 6
    valignq    zmm3,  zmm21, zmm31, 4
    vmovdqa64  zmm29, zmm21
.elseif \g == 3
.if \nt != 0
    prefetchnta [rbx + 640]
    prefetchnta [rbx + 704]
    prefetchnta [rbx + 768]
.endif
    vmovdqa64  zmm30, [rax + 640]
    vmovdqa64  zmm31, [rax + 704]
    vmovdqa64  zmm21, [rax + 768]
    valignq    zmm0,  zmm30, zmm29, 3
    valignq    zmm1,  zmm31, zmm30, 1
    valignq    zmm2,  zmm31, zmm30, 7
    valignq    zmm3,  zmm21, zmm31, 5
    vmovdqa64  zmm29, zmm21
.elseif \g == 4
.if \nt != 0
    prefetchnta [rbx + 832]
    prefetchnta [rbx + 896]
    prefetchnta [rbx + 960]
.endif
    vmovdqa64  zmm30, [rax + 832]
    vmovdqa64  zmm31, [rax + 896]
    vmovdqa64  zmm21, [rax + 960]
    valignq    zmm0,  zmm30, zmm29, 4
    valignq    zmm1,  zmm31, zmm30, 2
    vmovdqa64  zmm2,  zmm31
    valignq    zmm3,  zmm21, zmm31, 6
    vmovdqa64  zmm29, zmm21
.elseif \g == 5
.if \nt != 0
    prefetchnta [rbx + 1024]
    prefetchnta [rbx + 1088]
    prefetchnta [rbx + 1152]
