    vpermw     zmm1, zmm26, zmm1
    vpermw     zmm2, zmm27, zmm2
    vpermw     zmm3, zmm28, zmm3
    vpsrlvq    zmm0, zmm0,  zmm5
    vpsrlvq    zmm1, zmm1,  zmm5
    vpsrlvq    zmm2, zmm2,  zmm5
    vpsrlvq    zmm3, zmm3,  zmm5
