.Lgather_packed:
    vmovdqa64 zmm4, [rip + .Lconst_unpack50_permw]
    vmovdqa64 zmm5, [rip + .Lconst_pack50_shifts]
    mov  rax, 0x0003FFFFFFFFFFFF
    vpbroadcastq zmm16, rax             // 50-bit mask (volatile zmm16)
    mov  eax, 0x01FFFFFF                // 25 16-bit words = 50 bytes
    kmovd k2, eax

    shr  r9,  3                         // blocks = cols / 8
    cmp  r9,  32
    jb   .Lgather_pk_rows_start
    test r9,  31
    jnz  .Lgather_pk_rows_start
    test sil, 63
    jnz  .Lgather_pk_rows_start
    cmp  r8,  1
    je   .Lgather_pk_direct32_entry
    test r10b, 63
    jnz  .Lgather_pk_rows_start

.Lgather_pk_direct32_entry:
    vmovdqa64 zmm26, [rip + .Lconst_unpack50_permw1]
    vmovdqa64 zmm27, [rip + .Lconst_unpack50_permw2]
    vmovdqa64 zmm28, [rip + .Lconst_unpack50_permw3]
    xor  r13d, r13d
    test r12, r12
    jnz  .Lgather_pk_direct32_nt_row
.p2align 4
.Lgather_pk_direct32_row:
    mov  rax, rsi
    mov  rcx, r9
.p2align 4
.Lgather_pk_direct32_blk:
    .irp g, 0, 1, 2, 3, 4, 5, 6, 7
        UNPACK4_DIRECT_STEP \g, 0
    .endr
    add  rax, 1600
    add  rdi, 2048
    sub  rcx, 32
    jnz  .Lgather_pk_direct32_blk
    add  rsi, r10
    inc  r13
    cmp  r13, r8
    jb   .Lgather_pk_direct32_row
    jmp  .Lgather_done

.p2align 4
.Lgather_pk_direct32_nt_row:
    mov  rax, rsi
    mov  rcx, r9
    cmp  r9,  32
    ja   .Lgather_pk_direct32_nt_wide_chk
    lea  r11, [r13 + 4]
    cmp  r11, r8
    jb   .Lgather_pk_direct32_nt_pf4
    lea  r11, [r13 + 1]
    cmp  r11, r8
    jae  .Lgather_pk_direct32_nt_last
    lea  rbx, [rsi + r10]
    jmp  .Lgather_pk_direct32_nt_xrow_blk
.Lgather_pk_direct32_nt_pf4:
    lea  rbx, [rsi + 4*r10]
    jmp  .Lgather_pk_direct32_nt_xrow_blk
.Lgather_pk_direct32_nt_wide_chk:
    lea  r11, [r13 + 1]
    cmp  r11, r8
    jae  .Lgather_pk_direct32_nt_lastrow
    lea  rbx, [rsi + r10]
.p2align 4
.Lgather_pk_direct32_nt_xrow_blk:
    .irp g, 0, 1, 2, 3, 4, 5, 6, 7
        UNPACK4_DIRECT_STEP \g, 1
    .endr
    add  rax, 1600
    add  rbx, 1600
    add  rdi, 2048
    sub  rcx, 32
    jnz  .Lgather_pk_direct32_nt_xrow_blk
    add  rsi, r10
    inc  r13
    jmp  .Lgather_pk_direct32_nt_row

.Lgather_pk_direct32_nt_lastrow:
    cmp  rcx, 64
    jb   .Lgather_pk_direct32_nt_last
    lea  rbx, [rax + 1600]
.p2align 4
.Lgather_pk_direct32_nt_blk:
    .irp g, 0, 1, 2, 3, 4, 5, 6, 7
        UNPACK4_DIRECT_STEP \g, 1
    .endr
    add  rax, 1600
    add  rbx, 1600
    add  rdi, 2048
    sub  rcx, 32
    cmp  rcx, 64
    jae  .Lgather_pk_direct32_nt_blk
.Lgather_pk_direct32_nt_last:
    .irp g, 0, 1, 2, 3, 4, 5, 6, 7
        UNPACK4_DIRECT_STEP \g, 0
    .endr
    add  rdi, 2048
    jmp  .Lgather_done

