    jmp  .Lgather_pk_nt_go
.Lgather_pk_nt4_chk:
    lea  r11, [r13 + 4]
    cmp  r11, r8
    jae  .Lgather_pk_nt1_chk
    lea  rbx, [rsi + 4*r10]             // 4 rows ahead for DRAM/dTLB latency hiding
    jmp  .Lgather_pk_nt_go
.Lgather_pk_nt1_chk:
    lea  r11, [r13 + 1]
    cmp  r11, r8
    jae  .Lgather_pk_nt_inrow_chk
    lea  rbx, [rsi + r10]               // next_row (in bounds: r13 + 1 < r8)
    jmp  .Lgather_pk_nt_go
