// [21] scatter(outer_dst: rdi, tile_src: rsi, cfg: rdx)
LOCAL_FN supi_k_scatter
    VEC_ENTER_FAST
    mov  r8,  [rdx + 0]                 // rows
    mov  r9,  [rdx + 8]                 // cols
    mov  r10, [rdx + 16]                // stride_bytes
    mov  r11, [rdx + 24]                // packed
    mov  r12, [rdx + 32]                // use_nt

    test r8,  r8
    jz   .Lscatter_done
    test r9,  r9
    jz   .Lscatter_done

    test r11b, 1
    jnz  .Lscatter_packed

    // Unpacked strided scatter: if (packed >> 8) != 0, use it as src_stride_bytes; else cols * 8.
    shr  r11, 8
    jnz  1f
    lea  r11, [8*r9]
1:
    xor  r14d, r14d                     // issued_nt = 0
    xor  r13d, r13d                     // r = 0
    mov  r15, rsi                       // src_row_base = tile_src
.Lscatter_unp_row:
    mov  rsi, r15                       // src_row
    mov  rax, rdi                       // dst_row
    mov  rcx, r9                        // cols_rem
    test r12, r12
    jz   .Lscatter_unp_reg_check8

    // Check 8-byte alignment for peeling to 64-byte boundary
    test al, 7
    jnz  .Lscatter_unp_reg_check8
    mov  edx, eax
    and  edx, 63
    jz   .Lscatter_unp_nt_check8
    mov  ebx, 64
    sub  ebx, edx
    shr  ebx, 3                         // peel_elems = (64 - (dst & 63)) / 8
    cmp  rcx, rbx
    jb   .Lscatter_unp_reg_check8
    mov  edx, 0xFF
    bzhi edx, edx, ebx
    kmovw k1, edx
    vmovupd zmm0 {k1}{z}, [rsi]
    vmovupd [rax] {k1}, zmm0
    lea  rsi, [rsi + 8*rbx]
    lea  rax, [rax + 8*rbx]
    sub  rcx, rbx

.Lscatter_unp_nt_check8:
    cmp  rcx, 8
    jb   .Lscatter_unp_tail
    mov  r14d, 1
    cmp  rcx, 32
    jb   .Lscatter_unp_nt8
.p2align 4
.Lscatter_unp_nt32:
    vmovupd  zmm0, [rsi]
    vmovupd  zmm1, [rsi + 64]
    vmovupd  zmm2, [rsi + 128]
    vmovupd  zmm3, [rsi + 192]
    vmovntpd [rax],       zmm0
    vmovntpd [rax + 64],  zmm1
    vmovntpd [rax + 128], zmm2
    vmovntpd [rax + 192], zmm3
    add  rsi, 256
    add  rax, 256
    sub  rcx, 32
    cmp  rcx, 32
    jae  .Lscatter_unp_nt32
    cmp  rcx, 8
    jb   .Lscatter_unp_tail
.Lscatter_unp_nt8:
    vmovupd  zmm0, [rsi]
    vmovntpd [rax], zmm0
    lea  rsi, [rsi + 64]
    lea  rax, [rax + 64]
    sub  rcx, 8
    cmp  rcx, 8
    jae  .Lscatter_unp_nt8
    jmp  .Lscatter_unp_tail

.Lscatter_unp_reg_check8:
    cmp  rcx, 32
    jb   .Lscatter_unp_reg_rem8
.p2align 4
.Lscatter_unp_reg32:
    vmovupd zmm0, [rsi]
    vmovupd zmm1, [rsi + 64]
    vmovupd zmm2, [rsi + 128]
    vmovupd zmm3, [rsi + 192]
    vmovupd [rax],       zmm0
    vmovupd [rax + 64],  zmm1
    vmovupd [rax + 128], zmm2
    vmovupd [rax + 192], zmm3
    add  rsi, 256
    add  rax, 256
    sub  rcx, 32
    cmp  rcx, 32
    jae  .Lscatter_unp_reg32
.Lscatter_unp_reg_rem8:
    cmp  rcx, 8
    jb   .Lscatter_unp_tail
.Lscatter_unp_reg8:
    vmovupd zmm0, [rsi]
    vmovupd [rax], zmm0
    lea  rsi, [rsi + 64]
    lea  rax, [rax + 64]
    sub  rcx, 8
    cmp  rcx, 8
    jae  .Lscatter_unp_reg8

.Lscatter_unp_tail:
    test rcx, rcx
    jz   .Lscatter_unp_next_row
    mov  edx, 0xFF
    bzhi edx, edx, ecx
    kmovw k1, edx
    vmovupd zmm0 {k1}{z}, [rsi]
    vmovupd [rax] {k1}, zmm0
    lea  rsi, [rsi + 8*rcx]

.Lscatter_unp_next_row:
    add  r15, r11
    add  rdi, r10
    inc  r13
    cmp  r13, r8
    jb   .Lscatter_unp_row
    jmp  .Lscatter_done

    // Packed 50-bit scatter: 4-block unmasked helper + 2-slot L1d ping-pong staging for both
    // Sweep-1 tiles (rows >= 2, blocks = 4 or 8) and Sweep-2 wide rows (blocks >= 64), using ONLY
    // volatile zmm0..zmm5 and zmm16..zmm24 (zero vpermt2w shuffles, zero STLF stalls, zero XMM saves!).
.macro PACK4_UNMASKED dst_reg, off0, off1, off2, off3
    vmovupd     zmm0,  [rsi + 0]
    vmovupd     zmm1,  [rsi + 64]
    vmovupd     zmm2,  [rsi + 128]
    vmovupd     zmm3,  [rsi + 192]
    vcvttpd2uqq zmm0,  zmm0
    vcvttpd2uqq zmm1,  zmm1
    vcvttpd2uqq zmm2,  zmm2
    vcvttpd2uqq zmm3,  zmm3
    vpsllvq     zmm0,  zmm0,  zmm4
    vpsllvq     zmm1,  zmm1,  zmm4
    vpsllvq     zmm2,  zmm2,  zmm4
    vpsllvq     zmm3,  zmm3,  zmm4
    vpermw      zmm17, zmm5,  zmm0
    vpermw      zmm18, zmm5,  zmm1
    vpermw      zmm19, zmm5,  zmm2
    vpermw      zmm20, zmm5,  zmm3
    vpermw      zmm21 {k2}{z}, zmm16, zmm0
    vpermw      zmm22 {k2}{z}, zmm16, zmm1
    vpermw      zmm23 {k2}{z}, zmm16, zmm2
    vpermw      zmm24 {k2}{z}, zmm16, zmm3
    vporq       zmm17, zmm17, zmm21
    vporq       zmm18, zmm18, zmm22
    vporq       zmm19, zmm19, zmm23
    vporq       zmm20, zmm20, zmm24
    vmovdqu64   [\dst_reg + \off0], zmm17
    vmovdqu64   [\dst_reg + \off1], zmm18
    vmovdqu64   [\dst_reg + \off2], zmm19
    vmovdqu64   [\dst_reg + \off3], zmm20
    add  rsi, 256
.endm

.macro PACK4_EXACT dst_reg, off0, off1, off2, off3
    vmovupd     zmm0,  [rsi + 0]
    vmovupd     zmm1,  [rsi + 64]
    vmovupd     zmm2,  [rsi + 128]
    vmovupd     zmm3,  [rsi + 192]
    vcvttpd2uqq zmm0,  zmm0
    vcvttpd2uqq zmm1,  zmm1
    vcvttpd2uqq zmm2,  zmm2
    vcvttpd2uqq zmm3,  zmm3
    vpsllvq     zmm0,  zmm0,  zmm4
    vpsllvq     zmm1,  zmm1,  zmm4
    vpsllvq     zmm2,  zmm2,  zmm4
    vpsllvq     zmm3,  zmm3,  zmm4
    vpermw      zmm17, zmm5,  zmm0
    vpermw      zmm18, zmm5,  zmm1
    vpermw      zmm19, zmm5,  zmm2
    vpermw      zmm20, zmm5,  zmm3
    vpermw      zmm21 {k2}{z}, zmm16, zmm0
    vpermw      zmm22 {k2}{z}, zmm16, zmm1
    vpermw      zmm23 {k2}{z}, zmm16, zmm2
    vpermw      zmm24 {k2}{z}, zmm16, zmm3
    vporq       zmm17, zmm17, zmm21
    vporq       zmm18, zmm18, zmm22
    vporq       zmm19, zmm19, zmm23
    vporq       zmm20, zmm20, zmm24
    vmovdqu64   [\dst_reg + \off0], zmm17
    vmovdqu64   [\dst_reg + \off1], zmm18
    vmovdqu64   [\dst_reg + \off2], zmm19
    vmovdqu16   [\dst_reg + \off3] {k3}, zmm20
    add  rsi, 256
.endm

// Zero-stack register-direct 4-block (200B = 25 qwords) emitter step g in 0..7:
// Uses modulo-32 word-rotated perm_a0..3 / perm_b0..3 + 3 x vpblendmw (zero shuffle-port uops
// to stitch 4 x 50B blocks into 200B!) and emits 25 whole-cache-line 64B stores per 32 blocks
// directly from volatile ZMMs with zero L1d stack roundtrips and zero cache-line-splitting stores!
.macro PACK4_DIRECT_STEP g, use_nt
    vmovupd     zmm0,  [rsi + 0]
    vmovupd     zmm1,  [rsi + 64]
    vmovupd     zmm2,  [rsi + 128]
    vmovupd     zmm3,  [rsi + 192]
    add         rsi,   256
    vcvttpd2uqq zmm0,  zmm0
    vcvttpd2uqq zmm1,  zmm1
    vcvttpd2uqq zmm2,  zmm2
    vcvttpd2uqq zmm3,  zmm3
    vpsllvq     zmm0,  zmm0,  zmm4
    vpsllvq     zmm1,  zmm1,  zmm4
    vpsllvq     zmm2,  zmm2,  zmm4
    vpsllvq     zmm3,  zmm3,  zmm4
    vpermw      zmm17, zmm5,  zmm0
    vpermw      zmm18, zmm26, zmm1
    vpermw      zmm19, zmm27, zmm2
    vpermw      zmm20, zmm28, zmm3
    vpermw      zmm21 {k2}{z}, zmm29, zmm0
    vpermw      zmm22 {k6}{z}, zmm30, zmm1
    vpermw      zmm23 {k3}{z}, zmm31, zmm2
    vpermw      zmm0  {k4}{z}, zmm24, zmm3
    vporq       zmm17, zmm17, zmm21
    vporq       zmm18, zmm18, zmm22
    vporq       zmm19, zmm19, zmm23
    vporq       zmm20, zmm20, zmm0

    vpblendmw   zmm0 {k1}, zmm18, zmm17
    vpblendmw   zmm1 {k5}, zmm19, zmm18
    vpblendmw   zmm2 {k7}, zmm20, zmm19
.if \g == 0
    .if \use_nt
        vmovntdq  [rax + 0],   zmm0
        vmovntdq  [rax + 64],  zmm1
        vmovntdq  [rax + 128], zmm2
    .else
        vmovdqu64 [rax + 0],   zmm0
        vmovdqu64 [rax + 64],  zmm1
        vmovdqu64 [rax + 128], zmm2
    .endif
    valignq     zmm25, zmm20, zmm2, 1
.elseif \g < 7
    valignq     zmm21, zmm0, zmm25, (8 - \g)
    valignq     zmm22, zmm1, zmm0,  (8 - \g)
    valignq     zmm23, zmm2, zmm1,  (8 - \g)
    .if \use_nt
        vmovntdq  [rax + 192 * \g + 0],   zmm21
        vmovntdq  [rax + 192 * \g + 64],  zmm22
        vmovntdq  [rax + 192 * \g + 128], zmm23
    .else
        vmovdqu64 [rax + 192 * \g + 0],   zmm21
        vmovdqu64 [rax + 192 * \g + 64],  zmm22
        vmovdqu64 [rax + 192 * \g + 128], zmm23
    .endif
    valignq     zmm25, zmm20, zmm2, 1
.else
    valignq     zmm21, zmm0,  zmm25, 1
    valignq     zmm22, zmm1,  zmm0,  1
    valignq     zmm23, zmm2,  zmm1,  1
    valignq     zmm25, zmm20, zmm2,  1
    .if \use_nt
        vmovntdq  [rax + 1344], zmm21
        vmovntdq  [rax + 1408], zmm22
        vmovntdq  [rax + 1472], zmm23
        vmovntdq  [rax + 1536], zmm25
    .else
        vmovdqu64 [rax + 1344], zmm21
        vmovdqu64 [rax + 1408], zmm22
        vmovdqu64 [rax + 1472], zmm23
        vmovdqu64 [rax + 1536], zmm25
    .endif
.endif
.endm

.Lscatter_packed:
    vmovdqa64 zmm4,  [rip + .Lconst_pack50_shifts]
    vmovdqa64 zmm5,  [rip + .Lconst_pack50_perm_a]
    vmovdqa64 zmm16, [rip + .Lconst_pack50_perm_b]
    mov  eax, 0x00249248                // overlap word mask (words 3,6,9,12,15,18,21)
    kmovd k2, eax
    mov  eax, 0x01FFFFFF                // 25 16-bit words = 50 bytes
    kmovd k3, eax

    shr  r9,  3                         // blocks = cols / 8
    test r12, r12
    jnz  .Lscatter_pk_chk_nt32
    cmp  r9,  32
    jb   .Lscatter_pk_reg_rows
    test r9,  31
    jz   .Lscatter_pk_direct32_entry
    jmp  .Lscatter_pk_reg_rows
.Lscatter_pk_chk_nt32:
    cmp  r9,  32
    jb   .Lscatter_pk_chk_nt4
    test r9,  31
    jnz  .Lscatter_pk_nt_rows
    test dil, 63
    jnz  .Lscatter_pk_nt_rows
    cmp  r8,  1
    je   .Lscatter_pk_direct32_entry
    test r10b, 63
    jz   .Lscatter_pk_direct32_entry
    jmp  .Lscatter_pk_nt_rows
.Lscatter_pk_chk_nt4:
    cmp  r9,  4
    jae  .Lscatter_pk_nt_rows

.Lscatter_pk_reg_rows:
    xor  r13d, r13d                     // r = 0
.Lscatter_pk_row:
    mov  rax, rdi                       // dst_row
    mov  rcx, r9                        // blocks_rem
    cmp  rcx, 9
    jb   .Lscatter_pk_chk8_exact
.p2align 4
.Lscatter_pk_blk8:
    PACK4_UNMASKED rax, 0, 50, 100, 150
    PACK4_UNMASKED rax, 200, 250, 300, 350
    add  rax, 400
    sub  rcx, 8
    cmp  rcx, 9
    jae  .Lscatter_pk_blk8

.Lscatter_pk_chk8_exact:
    cmp  rcx, 8
    jb   .Lscatter_pk_chk4_exact
    PACK4_UNMASKED rax, 0, 50, 100, 150
    PACK4_EXACT    rax, 200, 250, 300, 350
    jmp  .Lscatter_pk_row_next

.Lscatter_pk_chk4_exact:
    cmp  rcx, 4
    jb   .Lscatter_pk_chk1
    PACK4_EXACT rax, 0, 50, 100, 150
    add  rax, 200
    sub  rcx, 4

.Lscatter_pk_chk1:
    test rcx, rcx
    jz   .Lscatter_pk_row_next
.Lscatter_pk_blk:
    vmovupd     zmm0, [rsi]
    vcvttpd2uqq zmm0, zmm0
    vpsllvq     zmm0, zmm0, zmm4
    vpermw      zmm1, zmm5, zmm0
    vpermw      zmm2 {k2}{z}, zmm16, zmm0
    vporq       zmm1, zmm1, zmm2
    vmovdqu16   [rax] {k3}, zmm1
    lea  rsi, [rsi + 64]
    lea  rax, [rax + 50]
    dec  rcx
    jnz  .Lscatter_pk_blk

.Lscatter_pk_row_next:
    add  rdi, r10
    inc  r13
    cmp  r13, r8
    jb   .Lscatter_pk_row
    jmp  .Lscatter_done

    // Zero-stack register-direct 32-block (1600B -> 25 x 64B stores) fast path for
    // Sweep-2 rows (cols = 256..32768) and Sweep-1 tile_cols = 32 tiles!
.p2align 4
.Lscatter_pk_direct32_entry:
    vmovdqa64 zmm29, zmm16
    vmovdqa64 zmm26, [rip + .Lconst_pack50_perm_a1]
    vmovdqa64 zmm27, [rip + .Lconst_pack50_perm_a2]
    vmovdqa64 zmm28, [rip + .Lconst_pack50_perm_a3]
    vmovdqa64 zmm30, [rip + .Lconst_pack50_perm_b1]
    vmovdqa64 zmm31, [rip + .Lconst_pack50_perm_b2]
    vmovdqa64 zmm24, [rip + .Lconst_pack50_perm_b3]
    kmovd     k1, eax                   // 0x01FFFFFF (still in eax!)
    mov       eax, 0x90004924
    kmovd     k6, eax
    mov       eax, 0x49200092
    kmovd     k3, eax
    mov       eax, 0x24924001
    kmovd     k4, eax
    mov       eax, 0x0003FFFF
    kmovd     k5, eax
    mov       eax, 0x000007FF
    kmovd     k7, eax
    xor       r13d, r13d
    test      r12,  r12
    jz        .Lscatter_pk_direct32_reg_row
.p2align 4
.Lscatter_pk_direct32_row:
    mov  rax, rdi
    mov  rcx, r9
.p2align 4
.Lscatter_pk_direct32_blk:
    .irp g, 0, 1, 2, 3, 4, 5, 6, 7
        PACK4_DIRECT_STEP \g, 1
    .endr
    add  rax, 1600
    sub  rcx, 32
    jnz  .Lscatter_pk_direct32_blk
    add  rdi, r10
    inc  r13
    cmp  r13, r8
    jb   .Lscatter_pk_direct32_row
    jmp  .Lscatter_done

.p2align 4
.Lscatter_pk_direct32_reg_row:
    mov  rax, rdi
    mov  rcx, r9
.p2align 4
.Lscatter_pk_direct32_reg_blk:
    .irp g, 0, 1, 2, 3, 4, 5, 6, 7
        PACK4_DIRECT_STEP \g, 0
    .endr
    add  rax, 1600
    sub  rcx, 32
    jnz  .Lscatter_pk_direct32_reg_blk
    add  rdi, r10
    inc  r13
    cmp  r13, r8
    jb   .Lscatter_pk_direct32_reg_row
    jmp  .Lscatter_done

    // Non-temporal packed scatter: 2-slot L1d ping-pong staging (< 4 KiB stack frame).
.Lscatter_pk_nt_rows:
    sub  rsp, 3392
    and  rsp, -64
    mov  qword ptr [rsp], 0
    mov  qword ptr [rsp + 3328], 0

    // Fast Path A: Multi-row Sweep-1 tiles (rows >= 2, blocks == 4, 8, or 32):
    // Row r packs into slot (r & 1) while Row (r - 1) retires and flushes from slot ((r - 1) & 1).
    cmp  r8,  2
    jb   .Lscatter_pk_nt_gen
    cmp  r9,  32
    je   .Lscatter_pk_tile32_chk
    cmp  r9,  4
    je   .Lscatter_pk_tile4
    cmp  r9,  8
    jne  .Lscatter_pk_nt_gen

    mov  r14d, 400
    PACK4_UNMASKED rsp, 0, 50, 100, 150
    PACK4_UNMASKED rsp, 200, 250, 300, 350
    jmp  .Lscatter_pk_tile_init

.Lscatter_pk_tile4:
    mov  r14d, 200
    PACK4_UNMASKED rsp, 0, 50, 100, 150

.Lscatter_pk_tile_init:
    mov  r13d, 1                        // next row to pack
    mov  r15d, 512                      // cur_slot offset (0 or 512)
.p2align 4
.Lscatter_pk_tile_step:
    cmp  r13, r8
    jae  .Lscatter_pk_tile_flush_prev
    lea  rdx, [rsp + r15]
    PACK4_UNMASKED rdx, 0, 50, 100, 150
    cmp  r14d, 400
    jb   .Lscatter_pk_tile_flush_prev
    PACK4_UNMASKED rdx, 200, 250, 300, 350

.Lscatter_pk_tile_flush_prev:
    mov  edx, r15d
    xor  edx, 512
    lea  rdx, [rsp + rdx]               // retired L1d slot of previous row
    mov  rax, rdi                       // dst_prev
    mov  ecx, r14d                      // bytes_rem (200 or 400)
    test al,  63
    jz   .Lscatter_pk_tile_nt
    mov  ebx, eax
    and  ebx, 63
    neg  ebx
    add  ebx, 64                        // peel = 64 - (dst & 63) (1..63)
    mov  r11, -1
    bzhi r11, r11, rbx
    kmovq k1, r11
    vmovdqa64 zmm0, [rdx]
    vmovdqu8  [rax] {k1}, zmm0
    add  rax, rbx
    add  rdx, rbx
    sub  rcx, rbx

.Lscatter_pk_tile_nt:
    cmp  rcx, 128
    jb   .Lscatter_pk_tile_nt64
.Lscatter_pk_tile_nt128:
    vmovdqu8  zmm0, [rdx]
    vmovdqu8  zmm1, [rdx + 64]
    vmovntdq  [rax],      zmm0
    vmovntdq  [rax + 64], zmm1
    add  rdx, 128
    add  rax, 128
    sub  rcx, 128
    cmp  rcx, 128
    jae  .Lscatter_pk_tile_nt128

.Lscatter_pk_tile_nt64:
    cmp  rcx, 64
    jb   .Lscatter_pk_tile_tail
    vmovdqu8  zmm0, [rdx]
    vmovntdq  [rax], zmm0
    add  rdx, 64
    add  rax, 64
    sub  rcx, 64

.Lscatter_pk_tile_tail:
    test rcx, rcx
    jz   .Lscatter_pk_tile_next
    mov  r11, -1
    bzhi r11, r11, rcx
    kmovq k1, r11
    vmovdqu8  zmm0, [rdx]
    vmovdqu8  [rax] {k1}, zmm0

.Lscatter_pk_tile_next:
    cmp  r13, r8
    jae  .Lscatter_pk_nt_sfence
    add  rdi, r10
    xor  r15d, 512
    inc  r13
    jmp  .Lscatter_pk_tile_step

.Lscatter_pk_tile32_chk:
    mov  rax, rdi
    or   rax, r10
    test al,  63
    jnz  .Lscatter_pk_nt_gen
    mov  rdx, rsp
    mov  r11d, 4
.Lscatter_pk_tile32_pro:
    PACK4_UNMASKED rdx, 0, 50, 100, 150
    PACK4_UNMASKED rdx, 200, 250, 300, 350
    add  rdx, 400
    dec  r11d
    jnz  .Lscatter_pk_tile32_pro
    mov  r13d, 1                        // next row to pack
    mov  ebx, 1664                      // cur_slot offset (0 or 1664)
.p2align 4
.Lscatter_pk_tile32_step:
    cmp  r13, r8
    jae  .Lscatter_pk_tile32_flush
    lea  rdx, [rsp + rbx]
    mov  r11d, 4
.Lscatter_pk_tile32_pack:
    PACK4_UNMASKED rdx, 0, 50, 100, 150
    PACK4_UNMASKED rdx, 200, 250, 300, 350
    add  rdx, 400
    dec  r11d
    jnz  .Lscatter_pk_tile32_pack

.Lscatter_pk_tile32_flush:
    mov  edx, ebx
    xor  edx, 1664
    lea  rdx, [rsp + rdx]
    vmovdqa64 zmm0, [rdx + 0]
    vmovdqa64 zmm1, [rdx + 64]
    vmovdqa64 zmm2, [rdx + 128]
    vmovdqa64 zmm3, [rdx + 192]
    vmovntdq  [rdi + 0],   zmm0
    vmovntdq  [rdi + 64],  zmm1
    vmovntdq  [rdi + 128], zmm2
    vmovntdq  [rdi + 192], zmm3
    vmovdqa64 zmm0, [rdx + 256]
    vmovdqa64 zmm1, [rdx + 320]
    vmovdqa64 zmm2, [rdx + 384]
    vmovdqa64 zmm3, [rdx + 448]
    vmovntdq  [rdi + 256], zmm0
    vmovntdq  [rdi + 320], zmm1
    vmovntdq  [rdi + 384], zmm2
    vmovntdq  [rdi + 448], zmm3
    vmovdqa64 zmm0, [rdx + 512]
    vmovdqa64 zmm1, [rdx + 576]
    vmovdqa64 zmm2, [rdx + 640]
    vmovdqa64 zmm3, [rdx + 704]
    vmovntdq  [rdi + 512], zmm0
    vmovntdq  [rdi + 576], zmm1
    vmovntdq  [rdi + 640], zmm2
    vmovntdq  [rdi + 704], zmm3
    vmovdqa64 zmm0, [rdx + 768]
    vmovdqa64 zmm1, [rdx + 832]
    vmovdqa64 zmm2, [rdx + 896]
    vmovdqa64 zmm3, [rdx + 960]
    vmovntdq  [rdi + 768], zmm0
    vmovntdq  [rdi + 832], zmm1
    vmovntdq  [rdi + 896], zmm2
    vmovntdq  [rdi + 960], zmm3
    vmovdqa64 zmm0, [rdx + 1024]
    vmovdqa64 zmm1, [rdx + 1088]
    vmovdqa64 zmm2, [rdx + 1152]
    vmovdqa64 zmm3, [rdx + 1216]
    vmovntdq  [rdi + 1024], zmm0
    vmovntdq  [rdi + 1088], zmm1
    vmovntdq  [rdi + 1152], zmm2
    vmovntdq  [rdi + 1216], zmm3
    vmovdqa64 zmm0, [rdx + 1280]
    vmovdqa64 zmm1, [rdx + 1344]
    vmovdqa64 zmm2, [rdx + 1408]
    vmovdqa64 zmm3, [rdx + 1472]
    vmovdqa64 zmm17, [rdx + 1536]
    vmovntdq  [rdi + 1280], zmm0
    vmovntdq  [rdi + 1344], zmm1
    vmovntdq  [rdi + 1408], zmm2
    vmovntdq  [rdi + 1472], zmm3
    vmovntdq  [rdi + 1536], zmm17
    cmp  r13, r8
    jae  .Lscatter_pk_nt_sfence
    add  rdi, r10
    xor  ebx, 1664
    inc  r13
    jmp  .Lscatter_pk_tile32_step

.Lscatter_pk_nt_gen:
    xor  r13d, r13d                     // r = 0
.Lscatter_pk_nt_row:
    mov  rax, rdi                       // dst_row
    mov  rcx, r9                        // blocks_rem (>= 4)
    xor  r15d, r15d                     // buf_len = 0 bytes pending at [rsp]

    test al,  63
    jnz  .Lscatter_pk_peel

    // Fast Path B: 2-slot 32-block (1600B = 25 * 64B) ping-pong for wide Sweep-2/Sweep-1 rows (rcx >= 32).
    cmp  rcx, 32
    jb   .Lscatter_pk_nt_check8
    mov  rdx, rsp
    mov  r11d, 4
.Lscatter_pk_nt_pp_pro:
    PACK4_UNMASKED rdx, 0, 50, 100, 150
    PACK4_UNMASKED rdx, 200, 250, 300, 350
    add  rdx, 400
    dec  r11d
    jnz  .Lscatter_pk_nt_pp_pro
    sub  rcx, 32
    mov  ebx, 1664                      // cur_slot = 1664

.p2align 4
.Lscatter_pk_nt_pp_step:
    cmp  rcx, 32
    jb   .Lscatter_pk_nt_pp_flush_only
    lea  rdx, [rsp + rbx]
    mov  r11d, 4
.Lscatter_pk_nt_pp_pack:
    PACK4_UNMASKED rdx, 0, 50, 100, 150
    PACK4_UNMASKED rdx, 200, 250, 300, 350
    add  rdx, 400
    dec  r11d
    jnz  .Lscatter_pk_nt_pp_pack
    sub  rcx, 32
    mov  r14d, 1
    jmp  .Lscatter_pk_nt_pp_flush

.Lscatter_pk_nt_pp_flush_only:
    xor  r14d, r14d

.Lscatter_pk_nt_pp_flush:
    mov  edx, ebx
    xor  edx, 1664
    lea  rdx, [rsp + rdx]
    vmovdqa64 zmm0, [rdx + 0]
    vmovdqa64 zmm1, [rdx + 64]
    vmovdqa64 zmm2, [rdx + 128]
    vmovdqa64 zmm3, [rdx + 192]
    vmovntdq  [rax + 0],   zmm0
    vmovntdq  [rax + 64],  zmm1
    vmovntdq  [rax + 128], zmm2
    vmovntdq  [rax + 192], zmm3
    vmovdqa64 zmm0, [rdx + 256]
    vmovdqa64 zmm1, [rdx + 320]
    vmovdqa64 zmm2, [rdx + 384]
    vmovdqa64 zmm3, [rdx + 448]
    vmovntdq  [rax + 256], zmm0
    vmovntdq  [rax + 320], zmm1
    vmovntdq  [rax + 384], zmm2
    vmovntdq  [rax + 448], zmm3
    vmovdqa64 zmm0, [rdx + 512]
    vmovdqa64 zmm1, [rdx + 576]
    vmovdqa64 zmm2, [rdx + 640]
    vmovdqa64 zmm3, [rdx + 704]
    vmovntdq  [rax + 512], zmm0
    vmovntdq  [rax + 576], zmm1
    vmovntdq  [rax + 640], zmm2
    vmovntdq  [rax + 704], zmm3
    vmovdqa64 zmm0, [rdx + 768]
    vmovdqa64 zmm1, [rdx + 832]
    vmovdqa64 zmm2, [rdx + 896]
    vmovdqa64 zmm3, [rdx + 960]
    vmovntdq  [rax + 768], zmm0
    vmovntdq  [rax + 832], zmm1
    vmovntdq  [rax + 896], zmm2
    vmovntdq  [rax + 960], zmm3
    vmovdqa64 zmm0, [rdx + 1024]
    vmovdqa64 zmm1, [rdx + 1088]
    vmovdqa64 zmm2, [rdx + 1152]
    vmovdqa64 zmm3, [rdx + 1216]
    vmovntdq  [rax + 1024], zmm0
    vmovntdq  [rax + 1088], zmm1
    vmovntdq  [rax + 1152], zmm2
    vmovntdq  [rax + 1216], zmm3
    vmovdqa64 zmm0, [rdx + 1280]
    vmovdqa64 zmm1, [rdx + 1344]
    vmovdqa64 zmm2, [rdx + 1408]
    vmovdqa64 zmm3, [rdx + 1472]
    vmovdqa64 zmm17, [rdx + 1536]
    vmovntdq  [rax + 1280], zmm0
    vmovntdq  [rax + 1344], zmm1
    vmovntdq  [rax + 1408], zmm2
    vmovntdq  [rax + 1472], zmm3
    vmovntdq  [rax + 1536], zmm17
    add  rax, 1600
    test r14d, r14d
    jz   .Lscatter_pk_nt_check8
    xor  ebx, 1664
    jmp  .Lscatter_pk_nt_pp_step

.Lscatter_pk_peel:
    // Peel misaligned head using first 4 blocks (200B) staged at [rsp + 0..200]
    mov  rdx, rsp
    mov  r11d, 4
.Lscatter_pk_peel_pack:
    vmovupd     zmm0, [rsi]
    vcvttpd2uqq zmm0, zmm0
    vpsllvq     zmm0, zmm0, zmm4
    vpermw      zmm1, zmm5, zmm0
    vpermw      zmm2 {k2}{z}, zmm16, zmm0
    vporq       zmm1, zmm1, zmm2
    vmovdqu16   [rdx] {k3}, zmm1
    lea  rsi, [rsi + 64]
    lea  rdx, [rdx + 50]
    dec  r11d
    jnz  .Lscatter_pk_peel_pack
    sub  rcx, 4

    mov  edx, eax
    and  edx, 63                        // mis (1..63)
    mov  ebx, 64
    sub  ebx, edx                       // peel = 64 - mis (1..63)
    mov  rdx, -1
    bzhi rdx, rdx, rbx
    kmovq k1, rdx
    vmovdqa64 zmm0, [rsp]
    vmovdqu8  [rax] {k1}, zmm0
    add  rax, rbx                       // rax is now 64-byte aligned!

    mov  r15d, 200
    sub  r15, rbx                       // rem = 200 - peel (137..199)
    lea  rdx, [rsp + rbx]
    vmovdqu8  zmm0, [rdx + 0]
    vmovntdq  [rax + 0], zmm0
    vmovdqu8  zmm1, [rdx + 64]
    vmovntdq  [rax + 64], zmm1
    add  rax, 128
    add  rdx, 128
    sub  r15, 128                       // rem is now 9..71
    cmp  r15, 64
    jb   .Lscatter_pk_peel_save
    vmovdqu8  zmm0, [rdx]
    vmovntdq  [rax], zmm0
    add  rax, 64
    add  rdx, 64
    sub  r15, 64
.Lscatter_pk_peel_save:
    vmovdqu8  zmm0, [rdx]
    vmovdqa64 [rsp], zmm0

.Lscatter_pk_nt_check8:
    cmp  rcx, 8
    jb   .Lscatter_pk_nt_check4

.p2align 4
.Lscatter_pk_nt_loop8:
    lea  rdx, [rsp + r15]
    mov  r11d, 8
.Lscatter_pk_nt_pack1:
    vmovupd     zmm0, [rsi]
    vcvttpd2uqq zmm0, zmm0
    vpsllvq     zmm0, zmm0, zmm4
    vpermw      zmm1, zmm5, zmm0
    vpermw      zmm2 {k2}{z}, zmm16, zmm0
    vporq       zmm1, zmm1, zmm2
    vmovdqu16   [rdx] {k3}, zmm1
    lea  rsi, [rsi + 64]
    lea  rdx, [rdx + 50]
    dec  r11d
    jnz  .Lscatter_pk_nt_pack1

    vmovdqa64 zmm0, [rsp + 0]
    vmovntdq  [rax + 0], zmm0
    vmovdqa64 zmm1, [rsp + 64]
    vmovntdq  [rax + 64], zmm1
    vmovdqa64 zmm0, [rsp + 128]
    vmovntdq  [rax + 128], zmm0
    vmovdqa64 zmm1, [rsp + 192]
    vmovntdq  [rax + 192], zmm1
    vmovdqa64 zmm0, [rsp + 256]
    vmovntdq  [rax + 256], zmm0
    vmovdqa64 zmm1, [rsp + 320]
    vmovntdq  [rax + 320], zmm1
    add  rax, 384
    add  r15, 16                        // new buf_len = r15 + 400 - 384 (16..79)
    cmp  r15, 64
    jb   .Lscatter_pk_nt_no7th
    vmovdqa64 zmm0, [rsp + 384]
    vmovntdq  [rax], zmm0
    add  rax, 64
    sub  r15, 64
    vmovdqa64 zmm0, [rsp + 448]
    vmovdqa64 [rsp], zmm0
    jmp  .Lscatter_pk_nt_next8
.Lscatter_pk_nt_no7th:
    vmovdqa64 zmm0, [rsp + 384]
    vmovdqa64 [rsp], zmm0
.Lscatter_pk_nt_next8:
    sub  rcx, 8
    cmp  rcx, 8
    jae  .Lscatter_pk_nt_loop8

.Lscatter_pk_nt_check4:
    cmp  rcx, 4
    jb   .Lscatter_pk_nt_flush
    lea  rdx, [rsp + r15]
    mov  r11d, 4
.Lscatter_pk_nt_pack4:
    vmovupd     zmm0, [rsi]
    vcvttpd2uqq zmm0, zmm0
    vpsllvq     zmm0, zmm0, zmm4
    vpermw      zmm1, zmm5, zmm0
    vpermw      zmm2 {k2}{z}, zmm16, zmm0
    vporq       zmm1, zmm1, zmm2
    vmovdqu16   [rdx] {k3}, zmm1
    lea  rsi, [rsi + 64]
    lea  rdx, [rdx + 50]
    dec  r11d
    jnz  .Lscatter_pk_nt_pack4

    vmovdqa64 zmm0, [rsp + 0]
    vmovntdq  [rax + 0], zmm0
    vmovdqa64 zmm1, [rsp + 64]
    vmovntdq  [rax + 64], zmm1
    vmovdqa64 zmm0, [rsp + 128]
    vmovntdq  [rax + 128], zmm0
    add  rax, 192
    add  r15, 8                         // new buf_len = r15 + 200 - 192 (8..71)
    cmp  r15, 64
    jb   .Lscatter_pk_nt_no4th_4
    vmovdqa64 zmm0, [rsp + 192]
    vmovntdq  [rax], zmm0
    add  rax, 64
    sub  r15, 64
    vmovdqa64 zmm0, [rsp + 256]
    vmovdqa64 [rsp], zmm0
    jmp  .Lscatter_pk_nt_done4
.Lscatter_pk_nt_no4th_4:
    vmovdqa64 zmm0, [rsp + 192]
    vmovdqa64 [rsp], zmm0
.Lscatter_pk_nt_done4:
    sub  rcx, 4

.Lscatter_pk_nt_flush:
    test r15, r15
    jz   .Lscatter_pk_nt_rem_blks
    mov  rdx, -1
    bzhi rdx, rdx, r15
    kmovq k1, rdx
    vmovdqa64 zmm0, [rsp]
    vmovdqu8  [rax] {k1}, zmm0
    add  rax, r15

.Lscatter_pk_nt_rem_blks:
    test rcx, rcx
    jz   .Lscatter_pk_nt_next_row
.Lscatter_pk_nt_tail_blk:
    vmovupd     zmm0, [rsi]
    vcvttpd2uqq zmm0, zmm0
    vpsllvq     zmm0, zmm0, zmm4
    vpermw      zmm1, zmm5, zmm0
    vpermw      zmm2 {k2}{z}, zmm16, zmm0
    vporq       zmm1, zmm1, zmm2
    vmovdqu16   [rax] {k3}, zmm1
    lea  rsi, [rsi + 64]
    lea  rax, [rax + 50]
    dec  rcx
    jnz  .Lscatter_pk_nt_tail_blk

.Lscatter_pk_nt_next_row:
    add  rdi, r10
    inc  r13
    cmp  r13, r8
    jb   .Lscatter_pk_nt_row
.Lscatter_pk_nt_sfence:

.Lscatter_done:
    VEC_LEAVE_FAST

// ============================================================================
// 7. Family 5 — Digits and Check-Word Kernels (2): to_digits, check_n
// ============================================================================

// [22] to_digits(out_buf: rdi, words_19dig: rsi, n_words: rdx, format_text: rcx) -> rax (w0)
LOCAL_FN supi_k_to_digits
    VEC_ENTER_FAST
    sub  rsp, 128
    and  rsp, -64
    xor  r8d, r8d                       // r8 = w0 = 0
    test rdx, rdx
    jz   .Ltodig_ret

    mov  r9,  0x1FFFFFFFFFFFFFFF        // MOD_W0 = 2^61 - 1
    mov  r10, 0x0AC7230489E80004        // POW10_19_MOD_W0 = 10^19 % (2^61 - 1)
    mov  r11, rdx                       // remaining words

    test rcx, rcx
    jnz  .Ltodig_text

    // Binary packed19 format: copy 8-byte LE words while accumulating w0
.Ltodig_bin_loop:
    mov  rax, [rsi]
    mov  [rdi], rax
    // v_mod = (rax & r9) + (rax >> 61); if >= r9: -= r9
    mov  rcx, rax
    and  rcx, r9
    shr  rax, 61
    add  rcx, rax
    lea  rax, [rcx - 1]                 // dummy
    mov  rax, rcx
    sub  rax, r9
    cmovae rcx, rax

    // w0 = (w0 * POW10_19_MOD_W0 + v_mod) mod (2^61 - 1)
    mov  rdx, r8
    mulx r12, rax, r10                  // r12:rax = w0 * POW10_19_MOD_W0 (< 2^122)
    shld r12, rax, 3                    // hi = prod >> 61 (< 2^61)
    and  rax, r9                        // lo = prod & MOD_W0
    add  rax, r12
    mov  rdx, rax
    sub  rdx, r9
    cmovae rax, rdx
    add  rax, rcx
    mov  rdx, rax
    sub  rdx, r9
    cmovae rax, rdx
    mov  r8,  rax

    lea  rsi, [rsi + 8]
    lea  rdi, [rdi + 8]
    dec  r11
    jnz  .Ltodig_bin_loop
    jmp  .Ltodig_ret

    // ASCII text format: 4 words (76 ASCII bytes) per iteration via ZMM SIMD BCD
.Ltodig_text:
    mov  eax, 109951163
    vpbroadcastq zmm20, rax             // magic 10^4 (ceil(2^40 / 10000))
    mov  eax, 10000
    vpbroadcastq zmm21, rax             // 10000 u64
    mov  ax,  5243
    vpbroadcastw ymm22, eax             // magic 100 (>> 19)
    mov  ax,  100
    vpbroadcastw ymm23, eax             // 100 u16
    mov  ax,  205
    vpbroadcastw zmm24, eax             // magic 10 (>> 11)
    mov  ax,  10
    vpbroadcastw zmm25, eax             // 10 u16
    mov  eax, 0x30303030
    vpbroadcastd zmm26, eax             // '0' bytes

    mov  r13, 0x39A5652FB1137857        // magic 5^16 (s = 35)
    mov  r14, 0xABCC77118461CEFD        // magic 5^8  (s = 18)
    mov  r15, 10000000000000000         // 10^16

    cmp  r11, 4
    jb   .Ltodig_text_tail

.p2align 4
.Ltodig_text_loop4:
    xor  ebx, ebx                       // k = 0..3
.Ltodig_prep4:
    mov  rax, [rsi + 8*rbx]             // val
    // Accumulate w0 = (w0 * POW10_19_MOD_W0 + val_mod) mod MOD_W0
    mov  rcx, rax
    and  rcx, r9
    mov  rdx, rax
    shr  rdx, 61
    add  rcx, rdx
    mov  rdx, rcx
    sub  rdx, r9
    cmovae rcx, rdx

    mov  rdx, r8
    mulx r12, r8, r10
    shld r12, r8, 3
    and  r8,  r9
    add  r8,  r12
    mov  rdx, r8
    sub  rdx, r9
    cmovae r8, rdx
    add  r8,  rcx
    mov  rdx, r8
    sub  rdx, r9
    cmovae r8, rdx

    // Split val into top3 = val / 10^16 and lo16 = val % 10^16
    mov  rdx, rax
    shr  rdx, 16
    mulx r12, rcx, r13
    shr  r12, 35                        // top3 (0..999)
    mov  [rsp + 64 + 8*rbx], r12

    mov  rcx, r12
    imul rcx, r15                       // top3 * 10^16
    sub  rax, rcx                       // lo16 (0 .. 10^16 - 1)

    // Split lo16 into q8 = lo16 / 10^8 and r8_lo = lo16 % 10^8
    mov  rdx, rax
    shr  rdx, 8
    mulx r12, rcx, r14
    shr  r12, 18                        // q8
    imul rcx, r12, 100000000
    sub  rax, rcx                       // r8_lo
    mov  rcx, rbx
    shl  rcx, 4
    mov  [rsp + rcx + 0], r12
    mov  [rsp + rcx + 8], rax

    inc  ebx
    cmp  ebx, 4
    jb   .Ltodig_prep4

    // Convert 8 u64s (< 10^8) in [rsp + 0..64] -> 64 ASCII bytes in ZMM0!
    vmovdqa64 zmm0, [rsp + 0]
    vpmuludq  zmm1, zmm0, zmm20
    vpsrlq    zmm1, zmm1, 40            // a = x / 10000
    vpmullq   zmm2, zmm1, zmm21         // a * 10000 (AVX512DQ)
    vpsubq    zmm0, zmm0, zmm2          // b = x % 10000
    vpsllq    zmm0, zmm0, 16
    vporq     zmm0, zmm1, zmm0          // (b << 16) | a
    vpmovqd   ymm0, zmm0                // 16 u16s < 10000

    vpmulhuw  ymm1, ymm0, ymm22
    vpsrlw    ymm1, ymm1, 3             // hi = w / 100
    vpmullw   ymm2, ymm1, ymm23
    vpsubw    ymm0, ymm0, ymm2          // lo = w % 100
    vpsllw    ymm0, ymm0, 8
    vpor      ymm0, ymm1, ymm0          // 32 u8s < 100

    vpmovzxbw zmm0, ymm0                // 32 u16s < 100
    vpmullw   zmm1, zmm0, zmm24
    vpsrlw    zmm1, zmm1, 11            // d_hi = b / 10
    vpmullw   zmm2, zmm1, zmm25
    vpsubw    zmm0, zmm0, zmm2          // d_lo = b % 10
    vpsllw    zmm0, zmm0, 8
    vporq     zmm0, zmm1, zmm0
    vpaddb    zmm0, zmm0, zmm26         // 64 ASCII bytes across 4 XMM lanes!

    // Write 4 x (3 top ASCII bytes + 16 lower ASCII bytes) = 76 bytes
    vmovdqu   [rdi + 3],  xmm0
    vextracti32x4 [rdi + 22], zmm0, 1
    vextracti32x4 [rdi + 41], zmm0, 2
    vextracti32x4 [rdi + 60], zmm0, 3

    xor  ebx, ebx
    mov  rcx, rdi
.Ltodig_top3_loop:
    mov  eax, dword ptr [rsp + 64 + 8*rbx]
    imul edx, eax, 41
    shr  edx, 12                        // d0 = top3 / 100
    imul r12d, edx, 100
    sub  eax, r12d                      // rem (0..99)
    add  dl,  48
    mov  [rcx + 0], dl
    imul edx, eax, 205
    shr  edx, 11                        // d1 = rem / 10
    imul r12d, edx, 10
    sub  eax, r12d                      // d2 = rem % 10
    add  dl,  48
    add  al,  48
    mov  [rcx + 1], dl
    mov  [rcx + 2], al
    lea  rcx, [rcx + 19]
    inc  ebx
    cmp  ebx, 4
    jb   .Ltodig_top3_loop

    lea  rsi, [rsi + 32]
    lea  rdi, [rdi + 76]
    sub  r11, 4
    cmp  r11, 4
    jae  .Ltodig_text_loop4

.Ltodig_text_tail:
    test r11, r11
    jz   .Ltodig_ret
.Ltodig_text_loop1:
    mov  rax, [rsi]
    // w0 update
    mov  rcx, rax
    and  rcx, r9
    mov  rdx, rax
    shr  rdx, 61
    add  rcx, rdx
    mov  rdx, rcx
    sub  rdx, r9
    cmovae rcx, rdx

    mov  rdx, r8
    mulx r12, r8, r10
    shld r12, r8, 3
    and  r8,  r9
    add  r8,  r12
    mov  rdx, r8
    sub  rdx, r9
    cmovae r8, rdx
    add  r8,  rcx
    mov  rdx, r8
    sub  rdx, r9
    cmovae r8, rdx

    // Render 19 ASCII digits via XMM SIMD + 3 top digits
    mov  rdx, rax
    shr  rdx, 16
    mulx r12, rcx, r13
    shr  r12, 35                        // top3
    mov  rcx, r12
    imul rcx, r15
    sub  rax, rcx                       // lo16

    mov  ecx, r12d
    imul edx, ecx, 41
    shr  edx, 12
    imul r12d, edx, 100
    sub  ecx, r12d
    add  dl,  48
    mov  [rdi + 0], dl
    imul edx, ecx, 205
    shr  edx, 11
    imul r12d, edx, 10
    sub  ecx, r12d
    add  dl,  48
    add  cl,  48
    mov  [rdi + 1], dl
    mov  [rdi + 2], cl

    mov  rdx, rax
    shr  rdx, 8
    mulx r12, rcx, r14
    shr  r12, 18                        // q8
    imul rcx, r12, 100000000
    sub  rax, rcx                       // r8_lo
    mov  [rsp + 0], r12
    mov  [rsp + 8], rax
    vmovdqu   xmm0, [rsp + 0]
    vpmuludq  xmm1, xmm0, xmm20
    vpsrlq    xmm1, xmm1, 40
    vpmullq   xmm2, xmm1, xmm21
    vpsubq    xmm0, xmm0, xmm2
    vpsllq    xmm0, xmm0, 16
    vpor      xmm0, xmm1, xmm0
    vpmovqd   xmm0, xmm0                // 4 u16s in low 64 bits of xmm0
    vpmulhuw  xmm1, xmm0, xmm22
    vpsrlw    xmm1, xmm1, 3
    vpmullw   xmm2, xmm1, xmm23
    vpsubw    xmm0, xmm0, xmm2
    vpsllw    xmm0, xmm0, 8
    vpor      xmm0, xmm1, xmm0          // 8 u8s in low 64 bits
    vpmovzxbw xmm0, xmm0                // 8 u16s in 128 bits
    vpmullw   xmm1, xmm0, xmm24
    vpsrlw    xmm1, xmm1, 11
    vpmullw   xmm2, xmm1, xmm25
    vpsubw    xmm0, xmm0, xmm2
    vpsllw    xmm0, xmm0, 8
    vpor      xmm0, xmm1, xmm0
    vpaddb    xmm0, xmm0, xmm26
    vmovdqu   [rdi + 3], xmm0

    lea  rsi, [rsi + 8]
    lea  rdi, [rdi + 19]
    dec  r11
    jnz  .Ltodig_text_loop1

.Ltodig_ret:
    mov  rax, r8
    VEC_LEAVE_FAST

// [23] check_n(limbs: rdi, n: rsi, out_words: rdx, all_three: rcx) -> rax (w0)
// Computes w0 mod (2^61 - 1) 8 limbs/step in ZMM via shifts & additions
// (2^512 ≡ 2^24 mod 2^61 - 1), and w1, w2 mod PRIME_LOC1, PRIME_LOC2 8 limbs/step
// in ZMM via NTT modular multiply on the two 32-bit halves of each limb.
LOCAL_FN supi_k_check_n
    VEC_ENTER_FAST
    sub  rsp, 128
    and  rsp, -64
    mov  r12, rdi                       // limbs
    mov  r13, rsi                       // n
    mov  r14, rdx                       // out_words
    mov  r15, rcx                       // all_three

    mov  r9,  0x1FFFFFFFFFFFFFFF        // MOD_W0 = 2^61 - 1
    mov  r10, 0x03FFFFFFFFFFFFFF        // (1 << 58) - 1
    xor  eax, eax                       // w0 = 0
    test r13, r13
    jz   .Lcheckn_w0_done

    // Peel top (n & 7) limbs into w0
    mov  rcx, r13
    and  rcx, 7
    mov  rbx, r13
    and  rbx, -8                        // vec_n = n & !7
    jz   .Lcheckn_w0_peel_only
    test rcx, rcx
    jz   .Lcheckn_w0_vec_init

.Lcheckn_w0_peel_only:
    mov  r8,  r13
.Lcheckn_w0_peel_loop:
    cmp  r8,  rbx
    jbe  .Lcheckn_w0_vec_check
    dec  r8
    mov  rdx, [r12 + 8*r8]              // limb
    mov  rsi, rdx
    and  rsi, r9
    shr  rdx, 61
    add  rsi, rdx
    mov  rdx, rsi
    sub  rdx, r9
    cmovae rsi, rdx                     // l_mod

    // shifted = ((w0 & MASK58) << 3) + (w0 >> 58)
    mov  rdx, rax
    and  rdx, r10
    shl  rdx, 3
    shr  rax, 58
    add  rax, rdx
    mov  rdx, rax
    sub  rdx, r9
    cmovae rax, rdx
    add  rax, rsi
    mov  rdx, rax
    sub  rdx, r9
    cmovae rax, rdx
    jmp  .Lcheckn_w0_peel_loop

.Lcheckn_w0_vec_check:
    test rbx, rbx
    jz   .Lcheckn_w0_done

.Lcheckn_w0_vec_init:
    // Lane 0 gets w0_top (zeros lanes 1..7) so w0_top carries weight (2^64)^vec_n!
    vmovq        xmm0, rax
    vpbroadcastq zmm16, r9              // MOD_W0 = (1 << 61) - 1
    mov  rdx, 0x0000001FFFFFFFFF        // MASK37 = (1 << 37) - 1
    vpbroadcastq zmm17, rdx

    lea  rsi, [r12 + 8*rbx - 64]        // &limbs[vec_n - 8]
    mov  rcx, rbx
    shr  rcx, 3                         // blocks = vec_n / 8
    // The sums stay unreduced: for any s below 2^64, s * 2^k mod (2^61 - 1) is
    // (s >> (61 - k)) + ((s & (2^(61-k) - 1)) << k), below 2^61 + 2^(3+k), and a limb is
    // (limb & (2^61 - 1)) + (limb >> 61), below 2^61 + 8: a step leaves a sum below 2^63.
    test cl, 1
    jz   .Lcheckn_w0_pairs
    // an odd block first: sums * 2^512 (2^24 modulo 2^61 - 1), plus the block
    vmovdqu64 zmm1, [rsi]
    vpandq    zmm2, zmm0, zmm17
    vpsllq    zmm2, zmm2, 24
    vpsrlq    zmm0, zmm0, 37
    vpaddq    zmm0, zmm0, zmm2
    vpandq    zmm3, zmm1, zmm16
    vpsrlq    zmm1, zmm1, 61
    vpaddq    zmm3, zmm3, zmm1
    vpaddq    zmm0, zmm0, zmm3
    sub  rsi, 64
    dec  rcx
    jz   .Lcheckn_w0_vec_done
.Lcheckn_w0_pairs:
    // Two sets of sums, sixteen limbs a step: each * 2^1024 (2^48 modulo 2^61 - 1), plus the
    // upper block into zmm18 and the lower into zmm0, which holds what came before (so that it
    // ends as many blocks up as it should).
    vpxorq    zmm18, zmm18, zmm18
    mov  edx, 0x1FFF                    // 2^13 - 1
    vpbroadcastq zmm19, rdx
.p2align 4
.Lcheckn_w0_vec_loop:
    vmovdqu64 zmm4, [rsi]
    vmovdqu64 zmm1, [rsi - 64]
    vpandq    zmm2, zmm0,  zmm19
    vpandq    zmm5, zmm18, zmm19
    vpsllq    zmm2, zmm2,  48
    vpsllq    zmm5, zmm5,  48
    vpsrlq    zmm0,  zmm0,  13
    vpsrlq    zmm18, zmm18, 13
    vpaddq    zmm0,  zmm0,  zmm2
    vpaddq    zmm18, zmm18, zmm5

    vpandq    zmm3,  zmm1, zmm16
    vpandq    zmm20, zmm4, zmm16
    vpsrlq    zmm1,  zmm1, 61
    vpsrlq    zmm4,  zmm4, 61
    vpaddq    zmm3,  zmm3,  zmm1
    vpaddq    zmm20, zmm20, zmm4
    vpaddq    zmm0,  zmm0,  zmm3
    vpaddq    zmm18, zmm18, zmm20

    sub  rsi, 128
    sub  rcx, 2
    jnz  .Lcheckn_w0_vec_loop

    // the upper set lies one block above the lower: * 2^512, joined (below 2^64)
    vpandq    zmm2,  zmm18, zmm17
    vpsllq    zmm2,  zmm2,  24
    vpsrlq    zmm18, zmm18, 37
    vpaddq    zmm18, zmm18, zmm2
    vpaddq    zmm0,  zmm0,  zmm18
.Lcheckn_w0_vec_done:

    // Horizontally fold lanes k = 7 down to 0: acc = (acc * 8 + lane[k]) mod MOD_W0
    vmovdqa64 [rsp + 0], zmm0
    xor  eax, eax                       // acc = 0
    mov  ecx, 7
.Lcheckn_w0_hfold:
    mov  rsi, [rsp + 8*rcx]
    mov  rdx, rsi
    and  rsi, r9
    shr  rdx, 61
    add  rsi, rdx
    mov  rdx, rsi
    sub  rdx, r9
    cmovae rsi, rdx                     // lane_mod

    mov  rdx, rax
    and  rdx, r10
    shl  rdx, 3
    shr  rax, 58
    add  rax, rdx
    mov  rdx, rax
    sub  rdx, r9
    cmovae rax, rdx
    add  rax, rsi
    mov  rdx, rax
    sub  rdx, r9
    cmovae rax, rdx
    sub  ecx, 1
    jnc  .Lcheckn_w0_hfold

.Lcheckn_w0_done:
    mov  r11, rax                       // save w0 in r11 (untouched by loc_words!)

    test r15, r15                       // all_three == 0 ?
    jnz  .Lcheckn_loc_words
    test r14, r14
    jz   .Lcheckn_ret
    mov  [r14 + 0], rax
    jmp  .Lcheckn_ret

    // Compute w1 (mod PRIME_LOC1) and w2 (mod PRIME_LOC2) 8 limbs at a time in ZMM
.Lcheckn_loc_words:
    vxorpd xmm0, xmm0, xmm0             // acc1_top = 0.0
    vxorpd xmm1, xmm1, xmm1             // acc2_top = 0.0
    test r13, r13
    jz   .Lcheckn_loc_store

    vbroadcastsd zmm24, [rip + .Lconst_p1_f64]
    vbroadcastsd zmm25, [rip + .Lconst_inv_p1_f64]
    vbroadcastsd zmm26, [rip + .Lconst_p2_f64]
    vbroadcastsd zmm27, [rip + .Lconst_inv_p2_f64]
    vbroadcastsd zmm28, [rip + .Lconst_two32_f64]
    vpxorq       zmm31, zmm31, zmm31

    mov  rbx, r13
    and  rbx, -8                        // vec_n
    mov  r8,  r13
    cmp  r8,  rbx
    je   .Lcheckn_loc_vec_check

    vmovsd xmm17, [rip + .Lconst_two64_1_f64]
    vmovsd xmm18, [rip + .Lconst_two64_2_f64]
.Lcheckn_loc_peel:
    dec  r8
    mov  rax, [r12 + 8*r8]
    mov  edx, eax                       // lo32
    shr  rax, 32                        // hi32
    vcvtusi2sd xmm2, xmm2, rdx          // lo
    vcvtusi2sd xmm3, xmm3, rax          // hi

    // v1 = (lo + (hi * 2^32 mod p1)) mod p1
    vmulsd xmm4, xmm3, xmm28
    vmulsd xmm5, xmm4, xmm25
    vfmsub213sd xmm3, xmm28, xmm4
    vrndscalesd xmm5, xmm5, xmm5, 8
    vfnmadd231sd xmm4, xmm5, xmm24
    vaddsd xmm4, xmm4, xmm3
    vcmpsd k1, xmm4, xmm31, 1
    vaddsd xmm4 {k1}, xmm4, xmm24
    vaddsd xmm4, xmm4, xmm2
    vcmpsd k1, xmm4, xmm24, 13
    vsubsd xmm4 {k1}, xmm4, xmm24       // v1

    // acc1 = (acc1 * two64_1 + v1) mod p1
    vmulsd xmm19, xmm0, xmm17
    vmulsd xmm21, xmm19, xmm25
    vfmsub213sd xmm0, xmm17, xmm19
    vrndscalesd xmm21, xmm21, xmm21, 8
    vfnmadd231sd xmm19, xmm21, xmm24
    vaddsd xmm0, xmm19, xmm0
    vcmpsd k1, xmm0, xmm31, 1
    vaddsd xmm0 {k1}, xmm0, xmm24
    vaddsd xmm0, xmm0, xmm4
    vcmpsd k1, xmm0, xmm24, 13
    vsubsd xmm0 {k1}, xmm0, xmm24

    // v2 = (lo + (hi * 2^32 mod p2)) mod p2
    vcvtusi2sd xmm3, xmm3, rax          // hi
    vmulsd xmm4, xmm3, xmm28
    vmulsd xmm5, xmm4, xmm27
    vfmsub213sd xmm3, xmm28, xmm4
    vrndscalesd xmm5, xmm5, xmm5, 8
    vfnmadd231sd xmm4, xmm5, xmm26
    vaddsd xmm4, xmm4, xmm3
    vcmpsd k1, xmm4, xmm31, 1
    vaddsd xmm4 {k1}, xmm4, xmm26
    vaddsd xmm4, xmm4, xmm2
    vcmpsd k1, xmm4, xmm26, 13
    vsubsd xmm4 {k1}, xmm4, xmm26       // v2

    // acc2 = (acc2 * two64_2 + v2) mod p2
    vmulsd xmm19, xmm1, xmm18
    vmulsd xmm21, xmm19, xmm27
    vfmsub213sd xmm1, xmm18, xmm19
    vrndscalesd xmm21, xmm21, xmm21, 8
    vfnmadd231sd xmm19, xmm21, xmm26
    vaddsd xmm1, xmm19, xmm1
    vcmpsd k1, xmm1, xmm31, 1
    vaddsd xmm1 {k1}, xmm1, xmm26
    vaddsd xmm1, xmm1, xmm4
    vcmpsd k1, xmm1, xmm26, 13
    vsubsd xmm1 {k1}, xmm1, xmm26

    cmp  r8,  rbx
    ja   .Lcheckn_loc_peel

.Lcheckn_loc_vec_check:
    test rbx, rbx
    jz   .Lcheckn_loc_store

    // xmm0 = acc1_top in lane 0 (lanes 1..7 zeroed by vmovq)
    // xmm1 = acc2_top in lane 0 (lanes 1..7 zeroed by vmovq)
    vmovq xmm0, xmm0
    vmovq xmm1, xmm1

    vbroadcastsd zmm21, [rip + .Lconst_two512_1_f64]
    vbroadcastsd zmm22, [rip + .Lconst_two512_2_f64]
    mov  eax, 0xFFFFFFFF
    vpbroadcastq zmm23, rax             // low 32-bit mask

    lea  rsi, [r12 + 8*rbx - 64]
    mov  rcx, rbx
    shr  rcx, 3
.p2align 4
.Lcheckn_loc_vec_loop:
    vmovdqu64  zmm2, [rsi]
    vpandq     zmm3, zmm2, zmm23
    vpsrlq     zmm2, zmm2, 32
    vcvtuqq2pd zmm3, zmm3               // lo (8 lanes)
    vcvtuqq2pd zmm2, zmm2               // hi (8 lanes)

    // Prime 1 (p1 = zmm24, inv_p1 = zmm25)
    vmovapd zmm29, zmm24
    vmovapd zmm30, zmm25
    vmovapd zmm4,  zmm2
    ZMM_MUL_MOD zmm4, zmm28, zmm16, zmm20, k1
    ZMM_ADD_MOD zmm4, zmm4,  zmm3,  k1  // v1
    ZMM_MUL_MOD zmm0, zmm21, zmm16, zmm20, k1
    ZMM_ADD_MOD zmm0, zmm0,  zmm4,  k1  // acc1

    // Prime 2 (p2 = zmm26, inv_p2 = zmm27)
    vmovapd zmm29, zmm26
    vmovapd zmm30, zmm27
    ZMM_MUL_MOD zmm2, zmm28, zmm16, zmm20, k1
    ZMM_ADD_MOD zmm2, zmm2,  zmm3,  k1  // v2
    ZMM_MUL_MOD zmm1, zmm22, zmm16, zmm20, k1
    ZMM_ADD_MOD zmm1, zmm1,  zmm2,  k1  // acc2

    sub  rsi, 64
    dec  rcx
    jnz  .Lcheckn_loc_vec_loop

    // Horizontally fold lanes k = 7 down to 0 for acc1 and acc2
    vmovapd [rsp + 0],  zmm0
    vmovapd [rsp + 64], zmm1
    vxorpd  xmm0, xmm0, xmm0
    vxorpd  xmm1, xmm1, xmm1
    vmovsd  xmm17, [rip + .Lconst_two64_1_f64]
    vmovsd  xmm18, [rip + .Lconst_two64_2_f64]
    mov     ecx, 7
.Lcheckn_loc_hfold:
    vmovsd xmm4, [rsp + 0 + 8*rcx]
    vmulsd xmm19, xmm0, xmm17
    vmulsd xmm21, xmm19, xmm25
    vfmsub213sd xmm0, xmm17, xmm19
    vrndscalesd xmm21, xmm21, xmm21, 8
    vfnmadd231sd xmm19, xmm21, xmm24
    vaddsd xmm0, xmm19, xmm0
    vcmpsd k1, xmm0, xmm31, 1
    vaddsd xmm0 {k1}, xmm0, xmm24
    vaddsd xmm0, xmm0, xmm4
    vcmpsd k1, xmm0, xmm24, 13
    vsubsd xmm0 {k1}, xmm0, xmm24

    vmovsd xmm5, [rsp + 64 + 8*rcx]
    vmulsd xmm19, xmm1, xmm18
    vmulsd xmm21, xmm19, xmm27
    vfmsub213sd xmm1, xmm18, xmm19
    vrndscalesd xmm21, xmm21, xmm21, 8
    vfnmadd231sd xmm19, xmm21, xmm26
    vaddsd xmm1, xmm19, xmm1
    vcmpsd k1, xmm1, xmm31, 1
    vaddsd xmm1 {k1}, xmm1, xmm26
    vaddsd xmm1, xmm1, xmm5
    vcmpsd k1, xmm1, xmm26, 13
    vsubsd xmm1 {k1}, xmm1, xmm26

    sub  ecx, 1
    jnc  .Lcheckn_loc_hfold

.Lcheckn_loc_store:
    mov  rax, r11                       // restore w0
    test r14, r14
    jz   .Lcheckn_ret
    vcvttsd2usi r8, xmm0
    vcvttsd2usi r9, xmm1
    mov  [r14 + 0],  rax                // w0
    mov  [r14 + 8],  r8                 // w1
    mov  [r14 + 16], r9                 // w2
.Lcheckn_ret:
    VEC_LEAVE_FAST

